globalThis.ANDE_CHUNKS["96c99cc5be64a8ade5a61e6de54aaa2cd69f4b957cbbd37ee66b94d2b59a0c49"] = [{"id":"tencent:1231829074692139040","sourceKey":"tencent","company":"腾讯","title":"微信小游戏-多模态交互式 GUI Agent 研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139040","duty":"课题背景：\n小游戏平台游戏测试面临多场景、高频迭代的挑战，传统人工测试效率低且覆盖率有限。多模态大模型在视觉理解与自主决策方面取得突破，为构建智能游戏交互 Agent 提供了新路径，但针对小游戏特殊交互环境的 GUI Agent 研究尚处于早期，亟需深入探索。\n\n课题挑战：\n1、多模态感知融合：需将游戏界面截图、动态画面等视觉信息与操作语义深度融合，实现对复杂界面的精准理解与实时响应\n2、动态交互决策：小游戏场景多变，Agent 需具备自适应的多步推理能力，在不同类型游戏中灵活切换策略\n3、泛化与鲁棒性：需跨越不同类型小游戏的界面差异实现高泛化 GUI 操作，并保持对异常场景的鲁棒处理能力。\n\n具体工作：\n参与多模态视觉-动作大模型的 GUI Agent 架构设计与实现，完成小游戏场景下的智能交互实验与系统原型开发。","requirements":"学历和专业要求：\n来自计算机科学、人工智能、软件工程等相关专业的硕士或博士同学。\n\n技术技能要求：\n掌握深度学习与多模态模型相关算法，熟悉Python/PyTorch，有GUI自动化或强化学习经验者优先。\n\n软性素质要求：\n自驱力强，具备良好的沟通协作能力，能够主动探索前沿技术并快速迭代实验方案。","description":"课题描述\n课题背景：\n小游戏平台游戏测试面临多场景、高频迭代的挑战，传统人工测试效率低且覆盖率有限。多模态大模型在视觉理解与自主决策方面取得突破，为构建智能游戏交互 Agent 提供了新路径，但针对小游戏特殊交互环境的 GUI Agent 研究尚处于早期，亟需深入探索。\n\n课题挑战：\n1、多模态感知融合：需将游戏界面截图、动态画面等视觉信息与操作语义深度融合，实现对复杂界面的精准理解与实时响应\n2、动态交互决策：小游戏场景多变，Agent 需具备自适应的多步推理能力，在不同类型游戏中灵活切换策略\n3、泛化与鲁棒性：需跨越不同类型小游戏的界面差异实现高泛化 GUI 操作，并保持对异常场景的鲁棒处理能力。\n\n具体工作：\n参与多模态视觉-动作大模型的 GUI Agent 架构设计与实现，完成小游戏场景下的智能交互实验与系统原型开发。\n\n课题要求\n学历和专业要求：\n来自计算机科学、人工智能、软件工程等相关专业的硕士或博士同学。\n\n技术技能要求：\n掌握深度学习与多模态模型相关算法，熟悉Python/PyTorch，有GUI自动化或强化学习经验者优先。\n\n软性素质要求：\n自驱力强，具备良好的沟通协作能力，能够主动探索前沿技术并快速迭代实验方案。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nWXG\n微信事业群\n\n微信游戏&小游戏团队\n微信游戏&小游戏团队主要负责微信游戏生态多元建设，通过平台能力提升、开发工具迭代、服务体系搭建等多方面，为开发者、玩家、社会带来更多价值。微信游戏经过11年努力已经让数亿玩家和精品游戏相遇，迸发快乐。微信小游戏从跳一跳出发，经过9年发展，已经服务超过50万开发者，用优质小游戏内容为10亿玩家带来简单快乐。 现在，微信游戏&小游戏团队依旧创想无限，微信游戏生态更有无限可能，我们欢迎每一位怀揣游戏梦想的你加入我们，让想法成为现实，让创造产生价值。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139041","sourceKey":"tencent","company":"腾讯","title":"微信小游戏-基于游戏研发管线的Agentic Coding 研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139041","duty":"课题背景：\n小游戏研发具有迭代快、技术栈多样、任务碎片化等特点。代码大模型已展现强大的代码生成能力，Agentic Coding 正重塑开发流程，但面向小游戏垂直领域的研究仍处空白，如何让 AI 编程助手真正理解游戏研发需求并高效转化为代码，是亟待突破的关键问题。\n\n课题挑战：\n1、领域知识注入：小游戏涉及特定引擎 API、框架规范和设计模式，需高效将领域知识融入代码大模型以生成符合规范的高质量代码\n2、需求理解与分解：游戏需求复杂多层次，Agent 需自动将高层需求分解为可执行编码任务并保证一致性\n3、代码质量保障：需确保自动生成代码的功能正确性、性能合规性与可维护性，实现生成到验证的闭环。\n\n具体工作：\n参与需求驱动的多 Agent 协作编码方案设计与实现，完成小游戏场景下代码生成系统的开发与评测。","requirements":"学历和专业要求：\n来自计算机科学、软件工程、人工智能等相关专业的硕士或博士同学。\n\n技术技能要求：\n掌握大语言模型及代码生成相关技术，熟悉Python/TypeScript，有Agent系统或编译原理经验者优先。\n\n软性素质要求：\n逻辑思维清晰，具备较强的工程落地能力和团队协作意识，善于从需求出发推动技术方案。","description":"课题描述\n课题背景：\n小游戏研发具有迭代快、技术栈多样、任务碎片化等特点。代码大模型已展现强大的代码生成能力，Agentic Coding 正重塑开发流程，但面向小游戏垂直领域的研究仍处空白，如何让 AI 编程助手真正理解游戏研发需求并高效转化为代码，是亟待突破的关键问题。\n\n课题挑战：\n1、领域知识注入：小游戏涉及特定引擎 API、框架规范和设计模式，需高效将领域知识融入代码大模型以生成符合规范的高质量代码\n2、需求理解与分解：游戏需求复杂多层次，Agent 需自动将高层需求分解为可执行编码任务并保证一致性\n3、代码质量保障：需确保自动生成代码的功能正确性、性能合规性与可维护性，实现生成到验证的闭环。\n\n具体工作：\n参与需求驱动的多 Agent 协作编码方案设计与实现，完成小游戏场景下代码生成系统的开发与评测。\n\n课题要求\n学历和专业要求：\n来自计算机科学、软件工程、人工智能等相关专业的硕士或博士同学。\n\n技术技能要求：\n掌握大语言模型及代码生成相关技术，熟悉Python/TypeScript，有Agent系统或编译原理经验者优先。\n\n软性素质要求：\n逻辑思维清晰，具备较强的工程落地能力和团队协作意识，善于从需求出发推动技术方案。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nWXG\n微信事业群\n\n微信游戏&小游戏团队\n微信游戏&小游戏团队主要负责微信游戏生态多元建设，通过平台能力提升、开发工具迭代、服务体系搭建等多方面，为开发者、玩家、社会带来更多价值。微信游戏经过11年努力已经让数亿玩家和精品游戏相遇，迸发快乐。微信小游戏从跳一跳出发，经过9年发展，已经服务超过50万开发者，用优质小游戏内容为10亿玩家带来简单快乐。 现在，微信游戏&小游戏团队依旧创想无限，微信游戏生态更有无限可能，我们欢迎每一位怀揣游戏梦想的你加入我们，让想法成为现实，让创造产生价值。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139042","sourceKey":"tencent","company":"腾讯","title":"微信游戏-用户数据驱动的交互式内容生成研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139042","duty":"课题背景：\n游戏核心内容创作高度依赖资深策划经验，效率与规模面临瓶颈。用户在游戏中积累了海量行为数据与交互偏好，蕴含丰富创意灵感。多模态生成技术飞速发展，为数据驱动的智能内容创作提供了新可能，但如何融合用户数据与创意生成仍是极具挑战的开放问题。\n\n课题挑战：\n1、用户数据理解与建模：游戏数据维度丰富且噪声大，需从海量行为数据中提取有效创意信号与偏好特征，构建精准用户需求模型\n2、混合概念创作：需融合文本、图像、3D 模型等多模态信息，在保持创意新颖性的同时确保内容合理性与可玩性\n3、交互式生成控制：需实现人机协作流程，让创作者通过自然交互高效引导 AI 生成结果。\n\n具体工作：\n参与用户数据建模与多模态内容生成方案的设计与实现，完成交互式游戏内容创作系统的原型开发与实验验证。","requirements":"学历和专业要求：\n来自计算机科学、人工智能、数字媒体技术等相关专业的硕士或博士同学。\n\n技术技能要求：\n掌握生成模型（如Diffusion、GAN）相关算法，熟悉Python/PyTorch，有多模态学习或用户建模经验者优先。\n\n软性素质要求：\n对创意生成有浓厚兴趣，具备良好的跨领域沟通能力和独立研究能力，注重细节与实验严谨性。","description":"课题描述\n课题背景：\n游戏核心内容创作高度依赖资深策划经验，效率与规模面临瓶颈。用户在游戏中积累了海量行为数据与交互偏好，蕴含丰富创意灵感。多模态生成技术飞速发展，为数据驱动的智能内容创作提供了新可能，但如何融合用户数据与创意生成仍是极具挑战的开放问题。\n\n课题挑战：\n1、用户数据理解与建模：游戏数据维度丰富且噪声大，需从海量行为数据中提取有效创意信号与偏好特征，构建精准用户需求模型\n2、混合概念创作：需融合文本、图像、3D 模型等多模态信息，在保持创意新颖性的同时确保内容合理性与可玩性\n3、交互式生成控制：需实现人机协作流程，让创作者通过自然交互高效引导 AI 生成结果。\n\n具体工作：\n参与用户数据建模与多模态内容生成方案的设计与实现，完成交互式游戏内容创作系统的原型开发与实验验证。\n\n课题要求\n学历和专业要求：\n来自计算机科学、人工智能、数字媒体技术等相关专业的硕士或博士同学。\n\n技术技能要求：\n掌握生成模型（如Diffusion、GAN）相关算法，熟悉Python/PyTorch，有多模态学习或用户建模经验者优先。\n\n软性素质要求：\n对创意生成有浓厚兴趣，具备良好的跨领域沟通能力和独立研究能力，注重细节与实验严谨性。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nWXG\n微信事业群\n\n微信游戏&小游戏团队\n微信游戏&小游戏团队主要负责微信游戏生态多元建设，通过平台能力提升、开发工具迭代、服务体系搭建等多方面，为开发者、玩家、社会带来更多价值。微信游戏经过11年努力已经让数亿玩家和精品游戏相遇，迸发快乐。微信小游戏从跳一跳出发，经过9年发展，已经服务超过50万开发者，用优质小游戏内容为10亿玩家带来简单快乐。 现在，微信游戏&小游戏团队依旧创想无限，微信游戏生态更有无限可能，我们欢迎每一位怀揣游戏梦想的你加入我们，让想法成为现实，让创造产生价值。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139043","sourceKey":"tencent","company":"腾讯","title":"微信游戏-生成式推荐系统研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139043","duty":"课题背景：\n游戏推荐系统主要依赖协同过滤等传统方法，难以精准捕捉用户动态偏好和深层需求。随着平台内容生态日益丰富，传统方法在个性化深度与内容发现能力方面局限性凸显。生成式大模型为推荐系统带来范式变革机遇，有望从\"检索匹配\"迈向\"理解生成\"。\n\n课题挑战：\n1、用户偏好的生成式建模：需利用大模型对用户游戏偏好进行深层理解与生成式表达，超越传统嵌入表征的局限，捕捉兴趣动态演化\n2、推荐的创造性生成：需平衡\"创造\"与\"匹配\"，确保推荐内容既个性化又多样化，避免信息茧房\n3、冷启动与长尾覆盖：需通过生成式方法缓解新游戏和长尾游戏数据不足的困境，提升覆盖广度。\n\n具体工作：\n参与基于大语言模型的生成式推荐方案设计与实现，完成游戏推荐场景下的模型训练、评测与系统原型开发。","requirements":"学历和专业要求：\n来自计算机科学、人工智能、信息检索等相关专业的硕士或博士同学。\n\n技术技能要求：\n掌握推荐系统与大语言模型相关算法，熟悉Python/PyTorch，有推荐系统或NLP实践经验者优先。\n\n软性素质要求：\n数据敏感度高，具备扎实的实验分析能力和良好的团队协作精神，善于从业务视角理解技术问题。","description":"课题描述\n课题背景：\n游戏推荐系统主要依赖协同过滤等传统方法，难以精准捕捉用户动态偏好和深层需求。随着平台内容生态日益丰富，传统方法在个性化深度与内容发现能力方面局限性凸显。生成式大模型为推荐系统带来范式变革机遇，有望从\"检索匹配\"迈向\"理解生成\"。\n\n课题挑战：\n1、用户偏好的生成式建模：需利用大模型对用户游戏偏好进行深层理解与生成式表达，超越传统嵌入表征的局限，捕捉兴趣动态演化\n2、推荐的创造性生成：需平衡\"创造\"与\"匹配\"，确保推荐内容既个性化又多样化，避免信息茧房\n3、冷启动与长尾覆盖：需通过生成式方法缓解新游戏和长尾游戏数据不足的困境，提升覆盖广度。\n\n具体工作：\n参与基于大语言模型的生成式推荐方案设计与实现，完成游戏推荐场景下的模型训练、评测与系统原型开发。\n\n课题要求\n学历和专业要求：\n来自计算机科学、人工智能、信息检索等相关专业的硕士或博士同学。\n\n技术技能要求：\n掌握推荐系统与大语言模型相关算法，熟悉Python/PyTorch，有推荐系统或NLP实践经验者优先。\n\n软性素质要求：\n数据敏感度高，具备扎实的实验分析能力和良好的团队协作精神，善于从业务视角理解技术问题。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nWXG\n微信事业群\n\n微信游戏&小游戏团队\n微信游戏&小游戏团队主要负责微信游戏生态多元建设，通过平台能力提升、开发工具迭代、服务体系搭建等多方面，为开发者、玩家、社会带来更多价值。微信游戏经过11年努力已经让数亿玩家和精品游戏相遇，迸发快乐。微信小游戏从跳一跳出发，经过9年发展，已经服务超过50万开发者，用优质小游戏内容为10亿玩家带来简单快乐。 现在，微信游戏&小游戏团队依旧创想无限，微信游戏生态更有无限可能，我们欢迎每一位怀揣游戏梦想的你加入我们，让想法成为现实，让创造产生价值。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139044","sourceKey":"tencent","company":"腾讯","title":"微信小程序Agent-面向小程序复杂交互环境的强化学习 GUIAgent 决策机制研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139044","duty":"本课题旨在研发能像真人一样感知并操作小程序的智能体。针对小程序多层嵌套、动态加载及跨页面逻辑等复杂环境，研究基于视觉与元数据融合的语义理解技术。通过深度强化学习（DRL）构建决策模型，解决在稀疏奖赏环境下的路径规划与长序列任务执行问题，实现 Agent 在未见场景下的自主探索与高成功率交互。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程等专业的博士和优秀硕士；\n2、具备VLM相关的CPT、SFT、RL经验；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。","description":"课题描述\n本课题旨在研发能像真人一样感知并操作小程序的智能体。针对小程序多层嵌套、动态加载及跨页面逻辑等复杂环境，研究基于视觉与元数据融合的语义理解技术。通过深度强化学习（DRL）构建决策模型，解决在稀疏奖赏环境下的路径规划与长序列任务执行问题，实现 Agent 在未见场景下的自主探索与高成功率交互。\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程等专业的博士和优秀硕士；\n2、具备VLM相关的CPT、SFT、RL经验；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。\n\nWXG\n微信事业群\n\n基础微信团队\n微信基础团队负责微信通讯与社交业务，为亿万用户提供高可用、低延迟的通讯基础设施。\n团队积极探索AI、音乐等创新领域，持续推进原生AI助手\"小微\"的研发，支持通过文字或语音对话操作微信原生功能，致力于打造更智能、更丰富的通讯社交生态。我们始终坚持产品逻辑的科学性与普适性，追求交互体验的简单与细致，以及技术实现的严谨与高效，致力于解决\"看似简单实则复杂\"的核心问题。\n如果你对产品与设计有自己的理解和抱负，对技术创新和实现有自己的理想与追求，欢迎加入微信基础团队，共同塑造下一代通讯社交基础设施。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139045","sourceKey":"tencent","company":"腾讯","title":"微信小程序Agent-基于大语言模型的小程序功能组件（Skill）生成式编译技术研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139045","duty":"本课题聚焦于自然语言到小程序功能逻辑的自动化转化。研究如何利用LLM 的代码理解与生成能力，将小程序的原子能力编译成标准化的 Skill 组件（JSON/JS 代码块）。重点突破端侧 Skill 的动态下发、沙箱隔离编译以及生成代码与原生 API 的自适应对齐技术，构建一套从对话到功能实现（Text-to-Skill）的高效编译流水线。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程等专业的博士和优秀硕士；\n2、具备CodeLLM相关的CPT、SFT、RL经验；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。","description":"课题描述\n本课题聚焦于自然语言到小程序功能逻辑的自动化转化。研究如何利用LLM 的代码理解与生成能力，将小程序的原子能力编译成标准化的 Skill 组件（JSON/JS 代码块）。重点突破端侧 Skill 的动态下发、沙箱隔离编译以及生成代码与原生 API 的自适应对齐技术，构建一套从对话到功能实现（Text-to-Skill）的高效编译流水线。\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程等专业的博士和优秀硕士；\n2、具备CodeLLM相关的CPT、SFT、RL经验；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。\n\nWXG\n微信事业群\n\n基础微信团队\n微信基础团队负责微信通讯与社交业务，为亿万用户提供高可用、低延迟的通讯基础设施。\n团队积极探索AI、音乐等创新领域，持续推进原生AI助手\"小微\"的研发，支持通过文字或语音对话操作微信原生功能，致力于打造更智能、更丰富的通讯社交生态。我们始终坚持产品逻辑的科学性与普适性，追求交互体验的简单与细致，以及技术实现的严谨与高效，致力于解决\"看似简单实则复杂\"的核心问题。\n如果你对产品与设计有自己的理解和抱负，对技术创新和实现有自己的理想与追求，欢迎加入微信基础团队，共同塑造下一代通讯社交基础设施。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139046","sourceKey":"tencent","company":"腾讯","title":"微信搜索-搜索场景下基于大模型的多模态输入表征应用研究","city":"广州","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139046","duty":"课题背景：\n利用大基座模型语义压缩和强表征能力，优化搜索内容理解、召回、精排各阶段输入，提升计算精度，提升搜索体验；另外，利用大模型解决搜索各阶段由于输入长度带来的在线计算带来的成本和耗时问题。\n\n课题挑战：\n1、微信搜索场景单doc下用户行为稀疏，历史query覆盖doc语义不全，单利用用户行为引导表征学习导致学习语义表征有偏，无法覆盖长尾内容需求；\n2、搜索场景下，图文/视频场景 表征或压缩 涉及到跨模态/跨表征空间的语义对齐问题，直接关系到基于表征/压缩作为输入的，搜索模型召回粗排的能力上限，从而影响最终搜索模型的效果上限。\n\n具体工作：\n1、表征模型到搜索模型的语义空间对齐预训练；\n2、视觉-文本表征如何更高效融合，提升输入压缩效果。\n3、提升基于表征/压缩输入的搜索模型的粗排和召回能力。","requirements":"学历和专业要求：自然语言处理/多模态/机器学习方向博士/硕士。\n技术技能要求：必须掌握大语言模型/多模态大模型框架，熟悉预训练、后训练技术，并且至少有后训练相关经验。另外，需熟练掌握机器学习基础理论，以及强化学习技术。对大模型前沿技术和理论有不错理解。","description":"课题描述\n课题背景：\n利用大基座模型语义压缩和强表征能力，优化搜索内容理解、召回、精排各阶段输入，提升计算精度，提升搜索体验；另外，利用大模型解决搜索各阶段由于输入长度带来的在线计算带来的成本和耗时问题。\n\n课题挑战：\n1、微信搜索场景单doc下用户行为稀疏，历史query覆盖doc语义不全，单利用用户行为引导表征学习导致学习语义表征有偏，无法覆盖长尾内容需求；\n2、搜索场景下，图文/视频场景 表征或压缩 涉及到跨模态/跨表征空间的语义对齐问题，直接关系到基于表征/压缩作为输入的，搜索模型召回粗排的能力上限，从而影响最终搜索模型的效果上限。\n\n具体工作：\n1、表征模型到搜索模型的语义空间对齐预训练；\n2、视觉-文本表征如何更高效融合，提升输入压缩效果。\n3、提升基于表征/压缩输入的搜索模型的粗排和召回能力。\n\n课题要求\n学历和专业要求：自然语言处理/多模态/机器学习方向博士/硕士。\n技术技能要求：必须掌握大语言模型/多模态大模型框架，熟悉预训练、后训练技术，并且至少有后训练相关经验。另外，需熟练掌握机器学习基础理论，以及强化学习技术。对大模型前沿技术和理论有不错理解。\n\nWXG\n微信事业群\n\n微信搜索团队\n微信搜索团队依托微信AI助手小微、公众号、视频号、小程序、微信小店构成的独特生态，以大模型技术为驱动，深度耕耘 AI 应用与智能搜索两大方向，覆盖微信各场景。\n在AI应用侧，我们深度参与微信AI助手“小微”的建设，让数亿用户通过自然对话获取信息、完成服务、连接彼此；在搜索侧，我们运用搜索与推荐技术，构建新一代生成式智能搜索，全面覆盖AI搜索、综合搜索、视频号搜索、小店与商品搜索、公众号搜索、小程序搜索等场景。\n独特的生态、海量的用户、领先的大模型落地实践，共同支撑着业务的快速发展。我们拥有优秀的AI算法、工程与产品团队，欢迎你的加入，一起探索大模型在复杂生态下的无限潜力，提升数亿人的AI与搜索体验。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139047","sourceKey":"tencent","company":"腾讯","title":"微信搜索-大模型在搜索系统中的应用落地研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139047","duty":"利用大模型全面升级现有搜索技术、解决搜索系统中的核心难题、提升搜索效果并且兼顾搜索成本是目前的一个重要方向，具体研发内容包括但不限于：\n1、基于大模型的内容理解、复杂语义和多模态匹配技术。\n2、基于大模型agent技术在搜索场景中的研究和应用。\n3、基于大模型的搜索搜索排序下用户行为反馈和满意度的RL应用落地。\n4、类openclaw的主动性的长程规划强化学习 Agent，稀疏反馈下模拟专家决策路径，例如搜索结果比较、满意度判断、多结果组合排序，从而端到端建模优化用户的整体满意度、行为、个性化等。","requirements":"学历：\n博士或者比较突出的硕士，优先博士\n\n专业：\n计算机、人工智能、大模型等\n\n技术技能要求：\n技术方向上优先多模态大模型、强化学习、agent规划等，有较好的学术能力，最好有顶会论文；\n\n软性素质要求：\n沟通协作等能力强","description":"课题描述\n利用大模型全面升级现有搜索技术、解决搜索系统中的核心难题、提升搜索效果并且兼顾搜索成本是目前的一个重要方向，具体研发内容包括但不限于：\n1、基于大模型的内容理解、复杂语义和多模态匹配技术。\n2、基于大模型agent技术在搜索场景中的研究和应用。\n3、基于大模型的搜索搜索排序下用户行为反馈和满意度的RL应用落地。\n4、类openclaw的主动性的长程规划强化学习 Agent，稀疏反馈下模拟专家决策路径，例如搜索结果比较、满意度判断、多结果组合排序，从而端到端建模优化用户的整体满意度、行为、个性化等。\n\n课题要求\n学历：\n博士或者比较突出的硕士，优先博士\n\n专业：\n计算机、人工智能、大模型等\n\n技术技能要求：\n技术方向上优先多模态大模型、强化学习、agent规划等，有较好的学术能力，最好有顶会论文；\n\n软性素质要求：\n沟通协作等能力强\n\nWXG\n微信事业群\n\n微信搜索团队\n微信搜索团队依托微信AI助手小微、公众号、视频号、小程序、微信小店构成的独特生态，以大模型技术为驱动，深度耕耘 AI 应用与智能搜索两大方向，覆盖微信各场景。\n在AI应用侧，我们深度参与微信AI助手“小微”的建设，让数亿用户通过自然对话获取信息、完成服务、连接彼此；在搜索侧，我们运用搜索与推荐技术，构建新一代生成式智能搜索，全面覆盖AI搜索、综合搜索、视频号搜索、小店与商品搜索、公众号搜索、小程序搜索等场景。\n独特的生态、海量的用户、领先的大模型落地实践，共同支撑着业务的快速发展。我们拥有优秀的AI算法、工程与产品团队，欢迎你的加入，一起探索大模型在复杂生态下的无限潜力，提升数亿人的AI与搜索体验。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139048","sourceKey":"tencent","company":"腾讯","title":"优图实验室—原生多模态后训练技术研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139048","duty":"课题背景：\n近来，业界大模型的发展已经从纯语言模型为重点变成以原生多模态模型为重点，从之前纯pretrain的scaling到pretrain+rl的scaling。 随着模型结构的原生、多个模态的融合、理解生成任务的统一，大模型的后训练也面临更大的挑战。本课题旨在探索原生多模态模型下后训练技术的演进策略，构建能够解决现实复杂场景问题的、具备持续学习能力的原生多模态模型。\n\n课题挑战：\n1、原生多模态深度推理能力： 如何设计类似于文本长COT的后训练策略，使模型能够自发产生带图/视频/音频的多模态、跨模态思考数据，提升模型跨模态深度推理能力；\n2、原生多模态奖励系统：针对不同模态的输入输出、理解和生成任务，如何构建统一公平稳定的奖励系统\n3、原生多模态强化学习算法：探索理解生成一体化的多任务统一的强化学习算法；提升超大规模RL训练的稳定性和效率；\n4、原生多模态后训练范式：针对后训练中不同模态的输入输出场景、理解和生成任务的场景，系统性的探索SFT/OPD/RL等全流程训练范式；\n\n具体工作：\n你将参与到原生多模态基座模型的研发，包括但不限于：超高质量多模态对齐数据、推理数据构建、多模态奖励系统和强化学习算法的研究等。","requirements":"1、计算机科学、人工智能、视觉计算、自然语言处理等相关专业的博士；\n2、深度理解多模态前沿进展，熟悉 ViT, Diffusion Models, Autoregressive Models 等技术路径，在 CVPR, ICLR, NeurIPS 等顶会有相关研究成果者优先；\n3、具备极强的工程能力，精通 PyTorch 框架，熟悉分布式训练技术（如 DeepSpeed, Megatron-LM），熟悉PPO/GRPO等强化学习技术，有超大规模参数模型训练经验者优先；\n4、熟练掌握 Python 编程，熟悉高性能算子开发或底层架构优化（如 CUDA 编程）者更佳；\n5、对技术有强烈的好奇心，具备解决底层复杂系统问题的韧性与出色的团队协作能力。","description":"课题描述\n课题背景：\n近来，业界大模型的发展已经从纯语言模型为重点变成以原生多模态模型为重点，从之前纯pretrain的scaling到pretrain+rl的scaling。 随着模型结构的原生、多个模态的融合、理解生成任务的统一，大模型的后训练也面临更大的挑战。本课题旨在探索原生多模态模型下后训练技术的演进策略，构建能够解决现实复杂场景问题的、具备持续学习能力的原生多模态模型。\n\n课题挑战：\n1、原生多模态深度推理能力： 如何设计类似于文本长COT的后训练策略，使模型能够自发产生带图/视频/音频的多模态、跨模态思考数据，提升模型跨模态深度推理能力；\n2、原生多模态奖励系统：针对不同模态的输入输出、理解和生成任务，如何构建统一公平稳定的奖励系统\n3、原生多模态强化学习算法：探索理解生成一体化的多任务统一的强化学习算法；提升超大规模RL训练的稳定性和效率；\n4、原生多模态后训练范式：针对后训练中不同模态的输入输出场景、理解和生成任务的场景，系统性的探索SFT/OPD/RL等全流程训练范式；\n\n具体工作：\n你将参与到原生多模态基座模型的研发，包括但不限于：超高质量多模态对齐数据、推理数据构建、多模态奖励系统和强化学习算法的研究等。\n\n课题要求\n1、计算机科学、人工智能、视觉计算、自然语言处理等相关专业的博士；\n2、深度理解多模态前沿进展，熟悉 ViT, Diffusion Models, Autoregressive Models 等技术路径，在 CVPR, ICLR, NeurIPS 等顶会有相关研究成果者优先；\n3、具备极强的工程能力，精通 PyTorch 框架，熟悉分布式训练技术（如 DeepSpeed, Megatron-LM），熟悉PPO/GRPO等强化学习技术，有超大规模参数模型训练经验者优先；\n4、熟练掌握 Python 编程，熟悉高性能算子开发或底层架构优化（如 CUDA 编程）者更佳；\n5、对技术有强烈的好奇心，具备解决底层复杂系统问题的韧性与出色的团队协作能力。\n\nCSIG\n云与智慧产业事业群\n\n优图实验室\n腾讯优图实验室——离产业最近的AI。我们专注于人工智能领域的前沿技术研究和产业实践落地，涵盖了视觉感知理解、多模态理解、大语言模型、计算加速、AIGC等技术研究领域；作为腾讯顶级的人工智能实验室，优图实验室在多个领域开展技术研究和应用落地，同时为腾讯内外部超500+产品和业务提供技术支持和服务；优图实验室汇聚来自国内外的顶尖人才，并与世界顶级院校和机构合作，我们拥有超过1800项全球专利，1000余篇论文被国际顶会收录。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139049","sourceKey":"tencent","company":"腾讯","title":"优图实验室—原生多模态预训练技术研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139049","duty":"课题背景：\n随着多模态大模型发展，它的架构已向原生多模态（Native Multimodal）架构演进，实现不同模态在同一模型架构下的深度融合已成为当前 AI 研究的前沿。原生多模态模型通过统一的架构，直接处理图像、视频、音频及文本等多种模态输入与输出，能够显著降低跨模态信息损耗，提升对复杂多模态场景的推理与生成能力。本课题旨在探索大模型在原生多模态方向的演进策略，目标是构建具备全模态理解与高质量生成能力的基础模型。\n\n课题挑战：\n1、统一模态表示设计： 如何设计高效的视觉、音频 Tokenizer，将高维连续信号转化为可与文本 Token 联合建模的特征空间，并保持语义一致性；\n2、多模态大规模预训练策略： 针对原生架构，如何设计合理的混合训练策略，平衡不同模态间的训练速度与收敛目标，避免单一模态退化；\n3、多尺度与长视频序列建模： 原生模型面临极高的计算复杂度，如何在统一架构下实现对超高分辨率图像及长视频序列的高效建模与长程依赖捕捉；\n4、高质量多模态数据合成与清洗： 如何从海量互联网数据中自动化筛选、交织并合成具有逻辑性、高质量的图文视频语料，构建亿级数据集；\n5、原生多模态生成一致性： 探索如何在同一套权重下，实现从理解到生成的闭环，并确保生成的视觉内容在空间、时间与语义上与指令高度一致。\n\n具体工作：\n你将参与原生多模态基座模型的研发，包括但不限于：多模态算法优化、亿级多模态语料的清洗与工程化、模型架构优化等。","requirements":"1、计算机科学、人工智能、视觉计算、自然语言处理等相关专业的博士；\n2、深度理解多模态前沿进展，熟悉 ViT, Diffusion Models, Autoregressive Models 等技术路径，在 CVPR, ICLR, NeurIPS 等顶会有相关研究成果者优先；\n3、具备极强的工程能力，精通 PyTorch 框架，熟悉分布式训练技术（如 DeepSpeed, Megatron-LM），有超大规模参数模型训练经验者优先；\n4、熟练掌握 Python 编程，熟悉高性能算子开发或底层架构优化（如 CUDA 编程）者更佳；\n5、对技术有强烈的好奇心，具备解决底层复杂系统问题的韧性与出色的团队协作能力。","description":"课题描述\n课题背景：\n随着多模态大模型发展，它的架构已向原生多模态（Native Multimodal）架构演进，实现不同模态在同一模型架构下的深度融合已成为当前 AI 研究的前沿。原生多模态模型通过统一的架构，直接处理图像、视频、音频及文本等多种模态输入与输出，能够显著降低跨模态信息损耗，提升对复杂多模态场景的推理与生成能力。本课题旨在探索大模型在原生多模态方向的演进策略，目标是构建具备全模态理解与高质量生成能力的基础模型。\n\n课题挑战：\n1、统一模态表示设计： 如何设计高效的视觉、音频 Tokenizer，将高维连续信号转化为可与文本 Token 联合建模的特征空间，并保持语义一致性；\n2、多模态大规模预训练策略： 针对原生架构，如何设计合理的混合训练策略，平衡不同模态间的训练速度与收敛目标，避免单一模态退化；\n3、多尺度与长视频序列建模： 原生模型面临极高的计算复杂度，如何在统一架构下实现对超高分辨率图像及长视频序列的高效建模与长程依赖捕捉；\n4、高质量多模态数据合成与清洗： 如何从海量互联网数据中自动化筛选、交织并合成具有逻辑性、高质量的图文视频语料，构建亿级数据集；\n5、原生多模态生成一致性： 探索如何在同一套权重下，实现从理解到生成的闭环，并确保生成的视觉内容在空间、时间与语义上与指令高度一致。\n\n具体工作：\n你将参与原生多模态基座模型的研发，包括但不限于：多模态算法优化、亿级多模态语料的清洗与工程化、模型架构优化等。\n\n课题要求\n1、计算机科学、人工智能、视觉计算、自然语言处理等相关专业的博士；\n2、深度理解多模态前沿进展，熟悉 ViT, Diffusion Models, Autoregressive Models 等技术路径，在 CVPR, ICLR, NeurIPS 等顶会有相关研究成果者优先；\n3、具备极强的工程能力，精通 PyTorch 框架，熟悉分布式训练技术（如 DeepSpeed, Megatron-LM），有超大规模参数模型训练经验者优先；\n4、熟练掌握 Python 编程，熟悉高性能算子开发或底层架构优化（如 CUDA 编程）者更佳；\n5、对技术有强烈的好奇心，具备解决底层复杂系统问题的韧性与出色的团队协作能力。\n\nCSIG\n云与智慧产业事业群\n\n优图实验室\n腾讯优图实验室——离产业最近的AI。我们专注于人工智能领域的前沿技术研究和产业实践落地，涵盖了视觉感知理解、多模态理解、大语言模型、计算加速、AIGC等技术研究领域；作为腾讯顶级的人工智能实验室，优图实验室在多个领域开展技术研究和应用落地，同时为腾讯内外部超500+产品和业务提供技术支持和服务；优图实验室汇聚来自国内外的顶尖人才，并与世界顶级院校和机构合作，我们拥有超过1800项全球专利，1000余篇论文被国际顶会收录。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139050","sourceKey":"tencent","company":"腾讯","title":"优图实验室—原生多模态infra技术研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139050","duty":"课题背景：\n原生多模态大模型的兴起对训练与推理基础设施提出了前所未有的挑战。与纯语言模型不同，原生多模态模型需要在统一框架下同时处理文本、图像、视频、音频等高度异构的模态数据，其计算模式、显存占用、数据吞吐需求与通信拓扑均远比单模态模型复杂。现有训练基础设施在多模态混合并行调度、异构数据流水线、大规模显存管理及跨模态梯度同步等方面存在严重瓶颈，制约着原生多模态模型规模化训练的效率与稳定性。本课题旨在面向原生多模态场景，从系统层面重新设计高效、可扩展的训练与推理基础设施。\n\n课题挑战：\n1、多模态异构并行策略设计：原生多模态模型中，Vision Encoder、Audio Encoder 与 LLM Backbone 的计算量、显存占用和通信模式差异显著，如何设计针对多模态异构架构的混合并行策略（张量并行、流水线并行、序列并行的协同组合），最大化多模态训练的硬件利用率与扩展效率；\n2、多模态动态序列的高效调度：视频帧数、图像分辨率、音频时长的不确定性导致每个样本的 Token 序列长度高度动态，如何设计支持变长多模态序列的高效批处理、动态显存分配与负载均衡机制，消除因序列长度差异带来的计算资源浪费；\n3、超大规模多模态训练的通信优化：多模态训练中跨模态的梯度同步、KV Cache 跨节点传输及多模态数据预处理 I/O 均面临严峻的通信瓶颈，如何针对多模态训练的通信特征设计定制化的梯度压缩、异步流水与 overlap 策略，降低通信开销对训练效率的影响；\n4、多模态推理系统优化：原生多模态模型在推理阶段面临视觉 Token 数量爆炸（长视频可达数万Token）与自回归解码串行瓶颈的双重压力，如何设计面向多模态的 KV Cache 管理、视觉 Token 动态压缩与投机解码机制，支撑高并发、低延迟的在线服务场景。\n\n具体工作：\n你将参与多模态混合并行训练框架设计、动态序列调度与显存管理优化、跨节点通信策略研发、多模态推理系统优化，推动原生多模态模型训练与服务基础设施的性能突破。","requirements":"1、计算机科学、计算机体系结构、软件工程、人工智能等相关专业的博士及优秀硕士；具有大规模分布式训练系统、高性能计算或 MLSys 方向研究与工程背景者优先；\n2、深入理解大规模分布式训练系统，熟悉 DeepSpeed、Megatron-LM、PyTorch FSDP 等主流框架原理；熟悉张量并行、流水线并行、序列并行等并行策略；精通 Python 与 C++，熟悉 CUDA 编程及高性能算子开发；在 MLSys、SC、EuroSys、OSDI、ATC 等系统顶会或 CVPR/NeurIPS/ICML 系统方向有相关成果者优先；\n3、对底层系统与 AI 交叉方向有浓厚兴趣，具备从系统视角分解和量化性能瓶颈的能力；工程严谨性强，能在超大规模训练环境中快速定位和解决复杂系统问题；沟通协作能力强，能与算法、硬件、平台等多方团队高效协同推进。","description":"课题描述\n课题背景：\n原生多模态大模型的兴起对训练与推理基础设施提出了前所未有的挑战。与纯语言模型不同，原生多模态模型需要在统一框架下同时处理文本、图像、视频、音频等高度异构的模态数据，其计算模式、显存占用、数据吞吐需求与通信拓扑均远比单模态模型复杂。现有训练基础设施在多模态混合并行调度、异构数据流水线、大规模显存管理及跨模态梯度同步等方面存在严重瓶颈，制约着原生多模态模型规模化训练的效率与稳定性。本课题旨在面向原生多模态场景，从系统层面重新设计高效、可扩展的训练与推理基础设施。\n\n课题挑战：\n1、多模态异构并行策略设计：原生多模态模型中，Vision Encoder、Audio Encoder 与 LLM Backbone 的计算量、显存占用和通信模式差异显著，如何设计针对多模态异构架构的混合并行策略（张量并行、流水线并行、序列并行的协同组合），最大化多模态训练的硬件利用率与扩展效率；\n2、多模态动态序列的高效调度：视频帧数、图像分辨率、音频时长的不确定性导致每个样本的 Token 序列长度高度动态，如何设计支持变长多模态序列的高效批处理、动态显存分配与负载均衡机制，消除因序列长度差异带来的计算资源浪费；\n3、超大规模多模态训练的通信优化：多模态训练中跨模态的梯度同步、KV Cache 跨节点传输及多模态数据预处理 I/O 均面临严峻的通信瓶颈，如何针对多模态训练的通信特征设计定制化的梯度压缩、异步流水与 overlap 策略，降低通信开销对训练效率的影响；\n4、多模态推理系统优化：原生多模态模型在推理阶段面临视觉 Token 数量爆炸（长视频可达数万Token）与自回归解码串行瓶颈的双重压力，如何设计面向多模态的 KV Cache 管理、视觉 Token 动态压缩与投机解码机制，支撑高并发、低延迟的在线服务场景。\n\n具体工作：\n你将参与多模态混合并行训练框架设计、动态序列调度与显存管理优化、跨节点通信策略研发、多模态推理系统优化，推动原生多模态模型训练与服务基础设施的性能突破。\n\n课题要求\n1、计算机科学、计算机体系结构、软件工程、人工智能等相关专业的博士及优秀硕士；具有大规模分布式训练系统、高性能计算或 MLSys 方向研究与工程背景者优先；\n2、深入理解大规模分布式训练系统，熟悉 DeepSpeed、Megatron-LM、PyTorch FSDP 等主流框架原理；熟悉张量并行、流水线并行、序列并行等并行策略；精通 Python 与 C++，熟悉 CUDA 编程及高性能算子开发；在 MLSys、SC、EuroSys、OSDI、ATC 等系统顶会或 CVPR/NeurIPS/ICML 系统方向有相关成果者优先；\n3、对底层系统与 AI 交叉方向有浓厚兴趣，具备从系统视角分解和量化性能瓶颈的能力；工程严谨性强，能在超大规模训练环境中快速定位和解决复杂系统问题；沟通协作能力强，能与算法、硬件、平台等多方团队高效协同推进。\n\nCSIG\n云与智慧产业事业群\n\n优图实验室\n腾讯优图实验室——离产业最近的AI。我们专注于人工智能领域的前沿技术研究和产业实践落地，涵盖了视觉感知理解、多模态理解、大语言模型、计算加速、AIGC等技术研究领域；作为腾讯顶级的人工智能实验室，优图实验室在多个领域开展技术研究和应用落地，同时为腾讯内外部超500+产品和业务提供技术支持和服务；优图实验室汇聚来自国内外的顶尖人才，并与世界顶级院校和机构合作，我们拥有超过1800项全球专利，1000余篇论文被国际顶会收录。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139052","sourceKey":"tencent","company":"腾讯","title":"优图实验室—图文(含OCR)多模态视觉细粒度理解研究","city":"合肥","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139052","duty":"课题背景：\n随着多模态大模型能力的持续跃升，视觉理解的边界正从粗粒度的图像描述向细粒度的精准感知与深度语义理解加速拓展。真实业务场景——如文档智能处理、工业质检、遥感解析、医疗影像分析——对模型的细粒度视觉能力提出了严苛要求：精确识别与定位图像中的文字、符号、微小目标、密集物体及复杂版式结构。然而，现有多模态模型在视觉细粒度感知方面仍存在显著短板，难以在高分辨率、复杂场景下稳定输出精准的结构化理解结果。本课题旨在系统性突破多模态模型的细粒度视觉理解能力，覆盖文字识别、文档解析、视觉定位与精细属性理解等核心子任务。\n\n课题挑战：\n1、细粒度视觉感知与高分辨率建模：针对密集文字、微小目标和高分辨率输入时存在语义损失，如何设计兼顾全局上下文与局部精细特征的视觉感知能力，使模型在保持高效推理的同时实现像素级精度的视觉理解；\n2、复杂场景 OCR 与文档结构化解析：真实文档涵盖多栏排版、嵌套表格、图文混排、手写印刷混合等复杂版式，如何实现文字识别与文档逻辑结构的联合建模，输出保留层次语义的结构化内容，支撑下游 RAG、信息抽取等高价值应用；\n3、视觉定位与细粒度属性理解：Referring、Grounding、计数、关系推理等细粒度任务要求模型在视觉空间与语义空间之间建立精准映射，如何设计统一的细粒度理解框架，在单一模型内协同解决定位、识别与属性描述等多类子任务；\n4、细粒度理解的数据构建与自动化评估：细粒度任务对标注质量要求极高且人工成本巨大，如何设计高效的自动化数据合成流水线与可扩展的评估体系，覆盖多样场景与任务类型，驱动模型能力的持续迭代。\n\n具体工作：\n你将参与细粒度视觉 Encoder 架构设计、复杂场景 OCR 与文档解析算法研究、多任务细粒度理解框架构建、训练数据自动合成与评估系统建设，推动原生多模态大模型在视觉细粒度理解方向的能力突破。","requirements":"1、计算机科学、人工智能、模式识别、计算机视觉、自然语言处理等相关专业的博士及优秀硕士；具有目标检测、OCR、文档理解、视觉定位或细粒度识别方向研究背景者优先；\n2、深入理解多模态细粒度理解前沿进展，熟悉 ViT、CLIP、Grounding DINO、SAM、InternVL、Donut 等技术路径；精通 PyTorch，熟悉分布式训练框架（DeepSpeed、Megatron-LM）；在 CVPR、ICLR、NeurIPS、ECCV、ICDAR 等顶会有相关成果者优先；熟悉 Python 编程，有 CUDA 优化经验者更佳；\n3、对细粒度视觉理解技术有强烈研究热情，具备将复杂视觉问题抽象为可量化技术命题的能力；沟通协作能力强，能在多方向交叉的大型项目中高效推进；具备面对开放性难题的韧性与独立攻坚精神。","description":"课题描述\n课题背景：\n随着多模态大模型能力的持续跃升，视觉理解的边界正从粗粒度的图像描述向细粒度的精准感知与深度语义理解加速拓展。真实业务场景——如文档智能处理、工业质检、遥感解析、医疗影像分析——对模型的细粒度视觉能力提出了严苛要求：精确识别与定位图像中的文字、符号、微小目标、密集物体及复杂版式结构。然而，现有多模态模型在视觉细粒度感知方面仍存在显著短板，难以在高分辨率、复杂场景下稳定输出精准的结构化理解结果。本课题旨在系统性突破多模态模型的细粒度视觉理解能力，覆盖文字识别、文档解析、视觉定位与精细属性理解等核心子任务。\n\n课题挑战：\n1、细粒度视觉感知与高分辨率建模：针对密集文字、微小目标和高分辨率输入时存在语义损失，如何设计兼顾全局上下文与局部精细特征的视觉感知能力，使模型在保持高效推理的同时实现像素级精度的视觉理解；\n2、复杂场景 OCR 与文档结构化解析：真实文档涵盖多栏排版、嵌套表格、图文混排、手写印刷混合等复杂版式，如何实现文字识别与文档逻辑结构的联合建模，输出保留层次语义的结构化内容，支撑下游 RAG、信息抽取等高价值应用；\n3、视觉定位与细粒度属性理解：Referring、Grounding、计数、关系推理等细粒度任务要求模型在视觉空间与语义空间之间建立精准映射，如何设计统一的细粒度理解框架，在单一模型内协同解决定位、识别与属性描述等多类子任务；\n4、细粒度理解的数据构建与自动化评估：细粒度任务对标注质量要求极高且人工成本巨大，如何设计高效的自动化数据合成流水线与可扩展的评估体系，覆盖多样场景与任务类型，驱动模型能力的持续迭代。\n\n具体工作：\n你将参与细粒度视觉 Encoder 架构设计、复杂场景 OCR 与文档解析算法研究、多任务细粒度理解框架构建、训练数据自动合成与评估系统建设，推动原生多模态大模型在视觉细粒度理解方向的能力突破。\n\n课题要求\n1、计算机科学、人工智能、模式识别、计算机视觉、自然语言处理等相关专业的博士及优秀硕士；具有目标检测、OCR、文档理解、视觉定位或细粒度识别方向研究背景者优先；\n2、深入理解多模态细粒度理解前沿进展，熟悉 ViT、CLIP、Grounding DINO、SAM、InternVL、Donut 等技术路径；精通 PyTorch，熟悉分布式训练框架（DeepSpeed、Megatron-LM）；在 CVPR、ICLR、NeurIPS、ECCV、ICDAR 等顶会有相关成果者优先；熟悉 Python 编程，有 CUDA 优化经验者更佳；\n3、对细粒度视觉理解技术有强烈研究热情，具备将复杂视觉问题抽象为可量化技术命题的能力；沟通协作能力强，能在多方向交叉的大型项目中高效推进；具备面对开放性难题的韧性与独立攻坚精神。\n\nCSIG\n云与智慧产业事业群\n\n优图实验室\n腾讯优图实验室——离产业最近的AI。我们专注于人工智能领域的前沿技术研究和产业实践落地，涵盖了视觉感知理解、多模态理解、大语言模型、计算加速、AIGC等技术研究领域；作为腾讯顶级的人工智能实验室，优图实验室在多个领域开展技术研究和应用落地，同时为腾讯内外部超500+产品和业务提供技术支持和服务；优图实验室汇聚来自国内外的顶尖人才，并与世界顶级院校和机构合作，我们拥有超过1800项全球专利，1000余篇论文被国际顶会收录。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139053","sourceKey":"tencent","company":"腾讯","title":"优图实验室—Agentic RAG相关技术研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139053","duty":"课题背景：\n随着大语言模型从单纯的“知识问答”向“任务解决”演进，传统的检索增强生成（RAG）正从静态的 Pipeline 向具备自主决策能力的 Agentic RAG 架构转型。Agentic RAG 不再是被动地检索与总结，而是通过引入 Agent 的规划、反思、工具调用及多步推理能力，实现对复杂问题的自适应检索。它能够自主判断检索质量、动态修正查询策略，并在多个知识库或工具间进行协同调度。本课题旨在探索 Agent 框架与 RAG 技术的深度融合，构建能够处理复杂长链任务、具备自我纠错能力的下一代智能知识系统。\n\n课题挑战：\n1、主动式检索策略设计： 如何设计高效的 Agent 决策逻辑，使模型能够根据问题的复杂程度自主决定检索的时机、次数以及是否需要多跳（Multi-hop）推理；\n2、复杂工具链与多源异构调度： 在面对向量数据库、图数据库、实时搜索及私有 API 时，如何优化 Agent 的工具调用准确性，实现多源信息的无缝整合；\n3、反思与自我纠偏机制： 针对 RAG 常见的幻觉问题，如何构建闭环的验证机制，通过 Agent 对检索结果的关联性、准确性进行实时评估与二次修正；\n4、Memory研究： 在多轮交互与复杂任务拆解中，研究如何有效管理历史信息和记忆状态，避免长序列下的信息遗忘或指令漂移。\n\n具体工作：\n你将参与 Agentic RAG 核心框架的研发，包括但不限于：多 Agent 协作系统设计、复杂 Query 改写与拆解算法优化、基于知识图谱与向量混合检索的增强研究、Text2SQL、Memory、自动化评估体系的建立与优化。","requirements":"1、专业背景： 计算机、人工智能、自然语言处理、信息检索、数据挖掘、数学等相关专业的博士或优秀硕士；\n2、技术积累： 深入理解大模型架构及 RAG 全链路技术（如向量化、重排序、Graphrag），熟悉Agent框架者优先；\n3、编程能力： 具备极强的工程实现能力，精通 Python 编程，熟练使用 PyTorch 或 DeepSpeed 等深度学习框架，熟悉 Linux 开发环境及主流向量数据库；\n4、综合素质： 具有优秀的逻辑思维与问题解决能力，对技术前沿有极高的敏感度，发表过顶会论文（ACL, EMNLP, NeurIPS 等）者优先。","description":"课题描述\n课题背景：\n随着大语言模型从单纯的“知识问答”向“任务解决”演进，传统的检索增强生成（RAG）正从静态的 Pipeline 向具备自主决策能力的 Agentic RAG 架构转型。Agentic RAG 不再是被动地检索与总结，而是通过引入 Agent 的规划、反思、工具调用及多步推理能力，实现对复杂问题的自适应检索。它能够自主判断检索质量、动态修正查询策略，并在多个知识库或工具间进行协同调度。本课题旨在探索 Agent 框架与 RAG 技术的深度融合，构建能够处理复杂长链任务、具备自我纠错能力的下一代智能知识系统。\n\n课题挑战：\n1、主动式检索策略设计： 如何设计高效的 Agent 决策逻辑，使模型能够根据问题的复杂程度自主决定检索的时机、次数以及是否需要多跳（Multi-hop）推理；\n2、复杂工具链与多源异构调度： 在面对向量数据库、图数据库、实时搜索及私有 API 时，如何优化 Agent 的工具调用准确性，实现多源信息的无缝整合；\n3、反思与自我纠偏机制： 针对 RAG 常见的幻觉问题，如何构建闭环的验证机制，通过 Agent 对检索结果的关联性、准确性进行实时评估与二次修正；\n4、Memory研究： 在多轮交互与复杂任务拆解中，研究如何有效管理历史信息和记忆状态，避免长序列下的信息遗忘或指令漂移。\n\n具体工作：\n你将参与 Agentic RAG 核心框架的研发，包括但不限于：多 Agent 协作系统设计、复杂 Query 改写与拆解算法优化、基于知识图谱与向量混合检索的增强研究、Text2SQL、Memory、自动化评估体系的建立与优化。\n\n课题要求\n1、专业背景： 计算机、人工智能、自然语言处理、信息检索、数据挖掘、数学等相关专业的博士或优秀硕士；\n2、技术积累： 深入理解大模型架构及 RAG 全链路技术（如向量化、重排序、Graphrag），熟悉Agent框架者优先；\n3、编程能力： 具备极强的工程实现能力，精通 Python 编程，熟练使用 PyTorch 或 DeepSpeed 等深度学习框架，熟悉 Linux 开发环境及主流向量数据库；\n4、综合素质： 具有优秀的逻辑思维与问题解决能力，对技术前沿有极高的敏感度，发表过顶会论文（ACL, EMNLP, NeurIPS 等）者优先。\n\nCSIG\n云与智慧产业事业群\n\n优图实验室\n腾讯优图实验室——离产业最近的AI。我们专注于人工智能领域的前沿技术研究和产业实践落地，涵盖了视觉感知理解、多模态理解、大语言模型、计算加速、AIGC等技术研究领域；作为腾讯顶级的人工智能实验室，优图实验室在多个领域开展技术研究和应用落地，同时为腾讯内外部超500+产品和业务提供技术支持和服务；优图实验室汇聚来自国内外的顶尖人才，并与世界顶级院校和机构合作，我们拥有超过1800项全球专利，1000余篇论文被国际顶会收录。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139054","sourceKey":"tencent","company":"腾讯","title":"优图实验室—大规模原生多模态智能体研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139054","duty":"课题背景：\n我们正处于从“静态模型”向“自主演进智能体”跨越的关键节点。本课题的核心目标是构建具备极大规模环境适应性与用户学习能力的原生多模态智能体。我们不仅关注模型在统一参数空间内的多模态理解与逻辑推理，更侧重于通过大规模环境仿真（Env Scaling）与真实用户交互反馈（User Scaling），利用强化学习驱动模型在复杂、开放域任务中的性能 Scaling，打造能够闭环学习、自我进化的通用智能体。\n\n课题挑战：\n1、多模态经验 Scaling (Experience Scaling)： 针对纯文本与多模态混合任务，如何构建支持数百万级并发交互的仿真环境，通过自博弈（Self-play）或环境探索产生海量高质量“视觉-语言-动作”轨迹数据。\n2、用户反馈驱动的在线演进： 在大规模用户交互场景下，如何处理极其稀疏、噪声大且非平稳的反馈数据，设计高效的在线强化学习（Online RL）策略，使智能体能够根据用户习惯实现“千人千面”的持续进化。\n3、全模态统一推理与策略 Scaling： 探索在扩大模型参数（Model Scaling）与增加计算量（Compute Scaling）的同时，如何确保文本逻辑（如代码、数学）与多模态感知（如 GUI 定位、视觉因果推理）协同增强，避免大模型在 Agent 任务中的能力坍塌。\n4、超大规模分布式 RL 基础设施： 面对包含复杂环境反馈（环境渲染、多模态输入处理）的 RL 训练，如何优化计算资源调度，提升超大规模分布式强化学习训练的稳定性和吞吐量。\n\n具体工作：\n1、Scaling 算法研发： 负责原生多模态 Agent 在大规模 SFT 和 RL 阶段的算法优化，利用 Scaling Law 指导数据比例与训练策略。\n2、数据/经验飞轮建设： 搭建自动化轨迹生成与清洗流水线，通过分布式仿真环境或合成数据技术，实现 Agent 经验数据的指数级增长。\n3、用户对齐与闭环优化： 研发基于用户反馈的奖励建模（Reward Modeling）技术，提升智能体在真实场景下的工具调用准确率与任务完成度。\n4、跨模态协同训练： 优化文本与多模态任务的联合训练方案，确保模型在复杂 Agent 场景下具备顶级的长链条推理（CoT）能力。","requirements":"1、计算机科学、人工智能、软件工程等相关专业的博士及硕士生；\n2、有深度大模型训练、Agent框架设计或使用的经历；\n3、求知欲驱动的行动力： 对大模型、具身智能及 AGI 的演进具有极其浓厚的兴趣与探索欲。不满足于现有的 SOTA，能够主动追踪并复现全球最前沿的研究进展，对“模型能力的边界在哪里”有持续的好奇心；\n4、AI-Native 的工程范式： 极其擅长利用 Coding Agent (如 Cursor, GitHub Copilot, Windsurf 等) 优化工作流。我们不仅在研发 Agent，更要求你是一个深度 Agent 使用者，能够通过自动化工具极速提升代码质量与实验效率；\n5、极致的细节控制力 (Attention to Detail)： 在处理大规模数据清洗、多模态对齐及超大规模 RL 训练时，表现出近乎偏执的细心。深信“Garbage in, Garbage out”，能够敏锐察觉实验数据中的细微异常并追溯底层逻辑；\n6、坚定的第一性原理思考者： 面对复杂、多模态的混沌问题，不盲从于现有的 Paper 或技术路径。能够拆解问题的本质，从物理底层、信息论或计算效率等基本点出发，推演并设计最优的技术方案。","description":"课题描述\n课题背景：\n我们正处于从“静态模型”向“自主演进智能体”跨越的关键节点。本课题的核心目标是构建具备极大规模环境适应性与用户学习能力的原生多模态智能体。我们不仅关注模型在统一参数空间内的多模态理解与逻辑推理，更侧重于通过大规模环境仿真（Env Scaling）与真实用户交互反馈（User Scaling），利用强化学习驱动模型在复杂、开放域任务中的性能 Scaling，打造能够闭环学习、自我进化的通用智能体。\n\n课题挑战：\n1、多模态经验 Scaling (Experience Scaling)： 针对纯文本与多模态混合任务，如何构建支持数百万级并发交互的仿真环境，通过自博弈（Self-play）或环境探索产生海量高质量“视觉-语言-动作”轨迹数据。\n2、用户反馈驱动的在线演进： 在大规模用户交互场景下，如何处理极其稀疏、噪声大且非平稳的反馈数据，设计高效的在线强化学习（Online RL）策略，使智能体能够根据用户习惯实现“千人千面”的持续进化。\n3、全模态统一推理与策略 Scaling： 探索在扩大模型参数（Model Scaling）与增加计算量（Compute Scaling）的同时，如何确保文本逻辑（如代码、数学）与多模态感知（如 GUI 定位、视觉因果推理）协同增强，避免大模型在 Agent 任务中的能力坍塌。\n4、超大规模分布式 RL 基础设施： 面对包含复杂环境反馈（环境渲染、多模态输入处理）的 RL 训练，如何优化计算资源调度，提升超大规模分布式强化学习训练的稳定性和吞吐量。\n\n具体工作：\n1、Scaling 算法研发： 负责原生多模态 Agent 在大规模 SFT 和 RL 阶段的算法优化，利用 Scaling Law 指导数据比例与训练策略。\n2、数据/经验飞轮建设： 搭建自动化轨迹生成与清洗流水线，通过分布式仿真环境或合成数据技术，实现 Agent 经验数据的指数级增长。\n3、用户对齐与闭环优化： 研发基于用户反馈的奖励建模（Reward Modeling）技术，提升智能体在真实场景下的工具调用准确率与任务完成度。\n4、跨模态协同训练： 优化文本与多模态任务的联合训练方案，确保模型在复杂 Agent 场景下具备顶级的长链条推理（CoT）能力。\n\n课题要求\n1、计算机科学、人工智能、软件工程等相关专业的博士及硕士生；\n2、有深度大模型训练、Agent框架设计或使用的经历；\n3、求知欲驱动的行动力： 对大模型、具身智能及 AGI 的演进具有极其浓厚的兴趣与探索欲。不满足于现有的 SOTA，能够主动追踪并复现全球最前沿的研究进展，对“模型能力的边界在哪里”有持续的好奇心；\n4、AI-Native 的工程范式： 极其擅长利用 Coding Agent (如 Cursor, GitHub Copilot, Windsurf 等) 优化工作流。我们不仅在研发 Agent，更要求你是一个深度 Agent 使用者，能够通过自动化工具极速提升代码质量与实验效率；\n5、极致的细节控制力 (Attention to Detail)： 在处理大规模数据清洗、多模态对齐及超大规模 RL 训练时，表现出近乎偏执的细心。深信“Garbage in, Garbage out”，能够敏锐察觉实验数据中的细微异常并追溯底层逻辑；\n6、坚定的第一性原理思考者： 面对复杂、多模态的混沌问题，不盲从于现有的 Paper 或技术路径。能够拆解问题的本质，从物理底层、信息论或计算效率等基本点出发，推演并设计最优的技术方案。\n\nCSIG\n云与智慧产业事业群\n\n优图实验室\n腾讯优图实验室——离产业最近的AI。我们专注于人工智能领域的前沿技术研究和产业实践落地，涵盖了视觉感知理解、多模态理解、大语言模型、计算加速、AIGC等技术研究领域；作为腾讯顶级的人工智能实验室，优图实验室在多个领域开展技术研究和应用落地，同时为腾讯内外部超500+产品和业务提供技术支持和服务；优图实验室汇聚来自国内外的顶尖人才，并与世界顶级院校和机构合作，我们拥有超过1800项全球专利，1000余篇论文被国际顶会收录。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139056","sourceKey":"tencent","company":"腾讯","title":"优图实验室—面向刷掌支付的多模态大模型研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139056","duty":"课题背景：\n刷掌支付在业务落地中面临多方面的约束与挑战：多样的环境与用户使用习惯、严格的法律法规限制。在这些前提下，刷掌问题排查与优化面临巨大的挑战。随着大语言模型（LLM）及多模态大模型（MLLM）技术的突破性发展，通过多模态大模型进行刷掌问题排查与优化成为一种可能，本课题聚焦多模态大模型在刷掌支付场景中的深度应用，解决支付现场理解与身份识别可靠性的核心业务痛点。\n\n课题挑战：\n1、支付现场理解：基于多模态大模型对支付现场进行综合理解，包括用户行为意图、设备环境状态、手掌质量等因素，并进行综合推理确定问题和优化方案。\n2、身份识别可靠推理：将多模态大模型的语义理解能力与掌纹识别管线深度结合，结合上下文提供可靠的识别结果与可解释的识别结论。\n3、生成识别统一框架构建： 将AIGC生成机制与掌纹识别深度融合，利用生成模型的内在特性反哺识别任务，实现高效率的识别问题修复；\n4、模型轻量化与端侧部署：面向刷掌支付终端的算力与时延约束，研究低延时的多模态大模型技术，在保证现场理解与推理能力的前提下实现多模态大模型的高效端侧部署\n\n具体工作：\n你将参与面向刷掌支付的多模态大模型研发，包括多模态大模型训练与微调、可解释推理能力增强（DPO、GRPO等）、模型轻量化研究等，推动多模态大模型在刷掌支付真实业务中的落地应用。","requirements":"1、计算机科学、人工智能、模式识别等相关专业的博士及优秀硕士；具有目标检测、Grounding，MLLM等研究背景者优先；\n2、熟悉VLM/MLLM前沿进展，熟悉 CLIP/InternVL等技术路径；精通 PyTorch，在 CVPR/ICLR/NeurIPS/ICCV等顶会有相关成果者优先；\n3、对多模态理解技术有强烈研究热情，对技术有较强的好奇心，具备较好的研究能力；沟通协作能力强，逻辑性强，具备独立解决问题的能力。","description":"课题描述\n课题背景：\n刷掌支付在业务落地中面临多方面的约束与挑战：多样的环境与用户使用习惯、严格的法律法规限制。在这些前提下，刷掌问题排查与优化面临巨大的挑战。随着大语言模型（LLM）及多模态大模型（MLLM）技术的突破性发展，通过多模态大模型进行刷掌问题排查与优化成为一种可能，本课题聚焦多模态大模型在刷掌支付场景中的深度应用，解决支付现场理解与身份识别可靠性的核心业务痛点。\n\n课题挑战：\n1、支付现场理解：基于多模态大模型对支付现场进行综合理解，包括用户行为意图、设备环境状态、手掌质量等因素，并进行综合推理确定问题和优化方案。\n2、身份识别可靠推理：将多模态大模型的语义理解能力与掌纹识别管线深度结合，结合上下文提供可靠的识别结果与可解释的识别结论。\n3、生成识别统一框架构建： 将AIGC生成机制与掌纹识别深度融合，利用生成模型的内在特性反哺识别任务，实现高效率的识别问题修复；\n4、模型轻量化与端侧部署：面向刷掌支付终端的算力与时延约束，研究低延时的多模态大模型技术，在保证现场理解与推理能力的前提下实现多模态大模型的高效端侧部署\n\n具体工作：\n你将参与面向刷掌支付的多模态大模型研发，包括多模态大模型训练与微调、可解释推理能力增强（DPO、GRPO等）、模型轻量化研究等，推动多模态大模型在刷掌支付真实业务中的落地应用。\n\n课题要求\n1、计算机科学、人工智能、模式识别等相关专业的博士及优秀硕士；具有目标检测、Grounding，MLLM等研究背景者优先；\n2、熟悉VLM/MLLM前沿进展，熟悉 CLIP/InternVL等技术路径；精通 PyTorch，在 CVPR/ICLR/NeurIPS/ICCV等顶会有相关成果者优先；\n3、对多模态理解技术有强烈研究热情，对技术有较强的好奇心，具备较好的研究能力；沟通协作能力强，逻辑性强，具备独立解决问题的能力。\n\nCSIG\n云与智慧产业事业群\n\n优图实验室\n腾讯优图实验室——离产业最近的AI。我们专注于人工智能领域的前沿技术研究和产业实践落地，涵盖了视觉感知理解、多模态理解、大语言模型、计算加速、AIGC等技术研究领域；作为腾讯顶级的人工智能实验室，优图实验室在多个领域开展技术研究和应用落地，同时为腾讯内外部超500+产品和业务提供技术支持和服务；优图实验室汇聚来自国内外的顶尖人才，并与世界顶级院校和机构合作，我们拥有超过1800项全球专利，1000余篇论文被国际顶会收录。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139057","sourceKey":"tencent","company":"腾讯","title":"优图实验室—面向内容安全的多模态鉴伪大模型研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139057","duty":"课题背景：\n随着 AIGC 与 DeepFake 技术快速迭代，数字内容伪造、证件篡改、人脸合成等安全问题日益突出。目前单模态判别方法难以应对高真实感伪造、跨域复杂场景与多类型攻击的泛化挑战。多模态大模型凭借强大的跨模态理解、细粒度语义感知与统一表征能力，为内容真伪鉴别提供了全新技术路径。本课题旨在探索多模态大模型在内容安全领域的深度应用，构建支持 AIGC检测、证件/文档 篡改检测等可信鉴伪技术，提升对恶意生成内容的理解、定位与溯源能力。\n\n课题挑战：\n1、细粒度理解感知： 基于多模态大模型，挖掘 生成内容、篡改内容 在纹理细节、物理成像等细微差异，实现对微弱伪造痕迹的感知；\n2、视觉推理能力构建：赋予鉴伪大模型视觉推理能力，能够结合例如 版式规则、生理结构等对复杂伪造内容进行可信的逻辑推理与判断；\n3、生成检测统一框架构建： 将AIGC生成机制与鉴伪检测逻辑深度融合，利用生成模型的内在特性反哺检测理解任务，实现对AIGC生成内容的高效检测；\n4、Agent 工具调用： 引入Agent的自主决策、反思与工具调用能力，实现鉴伪任务的智能化调度，自主判断检测场景、选择鉴伪策略、二次验证等，提升复杂场景下鉴伪任务的自动化与准确性；\n5、未知攻击防御与高效应对：面对不断迭代的新型伪造技术，建立MLLM驱动的异常模式挖掘等能力，提升模型的泛化能力；以及构建动态更新的伪造特征知识图谱与自适应检测机制，实现对未知伪造模式的快速识别与响应。\n\n具体工作：\n你将参与面向内容安全的多模态鉴伪大模型系统的研发，围绕细粒度感知、视觉推理、工具调用、智能体开发等方向展开研究，推动模型在人脸核身、证件鉴伪、AIGC检测等真实业务场景中的落地。","requirements":"1、计算机科学、人工智能、模式识别等相关专业的博士及优秀硕士；具有目标检测、Grounding，MLLM等研究背景者优先；\n2、熟悉VLM/MLLM前沿进展，熟悉 CLIP/InternVL等技术路径；精通 PyTorch，在 CVPR/ICLR/NeurIPS/ICCV等顶会有相关成果者优先；\n3、对多模态理解技术有强烈研究热情，对技术有较强的好奇心，具备较好的研究能力；沟通协作能力强，逻辑性强，具备独立解决问题的能力。","description":"课题描述\n课题背景：\n随着 AIGC 与 DeepFake 技术快速迭代，数字内容伪造、证件篡改、人脸合成等安全问题日益突出。目前单模态判别方法难以应对高真实感伪造、跨域复杂场景与多类型攻击的泛化挑战。多模态大模型凭借强大的跨模态理解、细粒度语义感知与统一表征能力，为内容真伪鉴别提供了全新技术路径。本课题旨在探索多模态大模型在内容安全领域的深度应用，构建支持 AIGC检测、证件/文档 篡改检测等可信鉴伪技术，提升对恶意生成内容的理解、定位与溯源能力。\n\n课题挑战：\n1、细粒度理解感知： 基于多模态大模型，挖掘 生成内容、篡改内容 在纹理细节、物理成像等细微差异，实现对微弱伪造痕迹的感知；\n2、视觉推理能力构建：赋予鉴伪大模型视觉推理能力，能够结合例如 版式规则、生理结构等对复杂伪造内容进行可信的逻辑推理与判断；\n3、生成检测统一框架构建： 将AIGC生成机制与鉴伪检测逻辑深度融合，利用生成模型的内在特性反哺检测理解任务，实现对AIGC生成内容的高效检测；\n4、Agent 工具调用： 引入Agent的自主决策、反思与工具调用能力，实现鉴伪任务的智能化调度，自主判断检测场景、选择鉴伪策略、二次验证等，提升复杂场景下鉴伪任务的自动化与准确性；\n5、未知攻击防御与高效应对：面对不断迭代的新型伪造技术，建立MLLM驱动的异常模式挖掘等能力，提升模型的泛化能力；以及构建动态更新的伪造特征知识图谱与自适应检测机制，实现对未知伪造模式的快速识别与响应。\n\n具体工作：\n你将参与面向内容安全的多模态鉴伪大模型系统的研发，围绕细粒度感知、视觉推理、工具调用、智能体开发等方向展开研究，推动模型在人脸核身、证件鉴伪、AIGC检测等真实业务场景中的落地。\n\n课题要求\n1、计算机科学、人工智能、模式识别等相关专业的博士及优秀硕士；具有目标检测、Grounding，MLLM等研究背景者优先；\n2、熟悉VLM/MLLM前沿进展，熟悉 CLIP/InternVL等技术路径；精通 PyTorch，在 CVPR/ICLR/NeurIPS/ICCV等顶会有相关成果者优先；\n3、对多模态理解技术有强烈研究热情，对技术有较强的好奇心，具备较好的研究能力；沟通协作能力强，逻辑性强，具备独立解决问题的能力。\n\nCSIG\n云与智慧产业事业群\n\n优图实验室\n腾讯优图实验室——离产业最近的AI。我们专注于人工智能领域的前沿技术研究和产业实践落地，涵盖了视觉感知理解、多模态理解、大语言模型、计算加速、AIGC等技术研究领域；作为腾讯顶级的人工智能实验室，优图实验室在多个领域开展技术研究和应用落地，同时为腾讯内外部超500+产品和业务提供技术支持和服务；优图实验室汇聚来自国内外的顶尖人才，并与世界顶级院校和机构合作，我们拥有超过1800项全球专利，1000余篇论文被国际顶会收录。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139058","sourceKey":"tencent","company":"腾讯","title":"优图实验室—多模态理解与检索研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139058","duty":"课题背景：\n随着大语言模型（LLM）及多模态大模型（MLLM）技术的突破性发展，通用场景下的图文内容语义理解能力与embedding 表征能力得到显著提升。然而，在开放业务场景中，现有技术仍面临两大核心挑战：首先，在复杂场景下，细粒度特征（如局部属性、跨模态语义关联等）的精准建模能力不足；其次，直接应用预训练大模型容易导致灾难性遗忘、幻觉输出和泛化能力欠缺等问题，难以满足精细场景理解，多粒度图文检索，开放场景识别等业务需求。本研究致力于面向复杂开放场景下的多模态内容理解与检索，探索基于大模型架构的高效细粒度理解方案，构建多粒度感知与检索范式，突破模型在业务场景中的适配瓶颈，推动在多业务场景下的规模化落地。\n\n课题挑战：\n1、优化多模态大模型在细粒度感知理解中的效果，研究如何设计跨模态细粒度对齐方法、优化视觉表征能力，实现更精准的语义理解与交互；\n2、研究如何基于多模态大模型构建高效多粒度数据管线与检索匹配方法；\n3、研究如何解决大模型在业务适配中的灾难性遗忘与泛化性损失等问题；探索基于DPO、GRPO等人类反馈对齐技术，提升模型在复杂场景任务理解与Reasoning能力；\n4、研究模型结构优化，知识蒸馏等方法提升大模型推理效率，在满足适配效果同时降低推理成本。\n\n具体工作：\n你将参与到多模态大模型感知增强的数据管线设计与实现，基于 RL 等方法构建多粒度感知理解方案，设计多粒度跨模态检索特征学习与匹配方案，推动上述多模态相关技术在内容理解等真实业务场景的落地","requirements":"1、计算机科学、人工智能、模式识别等相关专业的博士及优秀硕士；具有目标检测与识别、Grounding，VLM等研究背景者优先；\n2、熟悉VLM/MLLM前沿进展，熟悉 CLIP/InternVL等技术路径；精通 PyTorch，熟悉分布式训练框架（DeepSpeed、Megatron-LM）；在 CVPR/ICLR/NeurIPS/ICCV等顶会有相关成果者优先；\n3、对多模态理解技术有强烈研究热情，对技术有较强的好奇心，具备较好的研究能力；沟通协作能力强，逻辑性强，具备独立解决问题的能力。","description":"课题描述\n课题背景：\n随着大语言模型（LLM）及多模态大模型（MLLM）技术的突破性发展，通用场景下的图文内容语义理解能力与embedding 表征能力得到显著提升。然而，在开放业务场景中，现有技术仍面临两大核心挑战：首先，在复杂场景下，细粒度特征（如局部属性、跨模态语义关联等）的精准建模能力不足；其次，直接应用预训练大模型容易导致灾难性遗忘、幻觉输出和泛化能力欠缺等问题，难以满足精细场景理解，多粒度图文检索，开放场景识别等业务需求。本研究致力于面向复杂开放场景下的多模态内容理解与检索，探索基于大模型架构的高效细粒度理解方案，构建多粒度感知与检索范式，突破模型在业务场景中的适配瓶颈，推动在多业务场景下的规模化落地。\n\n课题挑战：\n1、优化多模态大模型在细粒度感知理解中的效果，研究如何设计跨模态细粒度对齐方法、优化视觉表征能力，实现更精准的语义理解与交互；\n2、研究如何基于多模态大模型构建高效多粒度数据管线与检索匹配方法；\n3、研究如何解决大模型在业务适配中的灾难性遗忘与泛化性损失等问题；探索基于DPO、GRPO等人类反馈对齐技术，提升模型在复杂场景任务理解与Reasoning能力；\n4、研究模型结构优化，知识蒸馏等方法提升大模型推理效率，在满足适配效果同时降低推理成本。\n\n具体工作：\n你将参与到多模态大模型感知增强的数据管线设计与实现，基于 RL 等方法构建多粒度感知理解方案，设计多粒度跨模态检索特征学习与匹配方案，推动上述多模态相关技术在内容理解等真实业务场景的落地\n\n课题要求\n1、计算机科学、人工智能、模式识别等相关专业的博士及优秀硕士；具有目标检测与识别、Grounding，VLM等研究背景者优先；\n2、熟悉VLM/MLLM前沿进展，熟悉 CLIP/InternVL等技术路径；精通 PyTorch，熟悉分布式训练框架（DeepSpeed、Megatron-LM）；在 CVPR/ICLR/NeurIPS/ICCV等顶会有相关成果者优先；\n3、对多模态理解技术有强烈研究热情，对技术有较强的好奇心，具备较好的研究能力；沟通协作能力强，逻辑性强，具备独立解决问题的能力。\n\nCSIG\n云与智慧产业事业群\n\n优图实验室\n腾讯优图实验室——离产业最近的AI。我们专注于人工智能领域的前沿技术研究和产业实践落地，涵盖了视觉感知理解、多模态理解、大语言模型、计算加速、AIGC等技术研究领域；作为腾讯顶级的人工智能实验室，优图实验室在多个领域开展技术研究和应用落地，同时为腾讯内外部超500+产品和业务提供技术支持和服务；优图实验室汇聚来自国内外的顶尖人才，并与世界顶级院校和机构合作，我们拥有超过1800项全球专利，1000余篇论文被国际顶会收录。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139059","sourceKey":"tencent","company":"腾讯","title":"优图实验室—高保真人像视频生成及应用研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139059","duty":"课题背景：\n近年来视频生成领域取得了很大的进展，并在影视创作、社交等场景开始实际应用。其中人像相关视频的生成应用需求最为广泛。\n\n课题挑战：\n1、真人像视频生成中ID的维持能力\n2、人物交互中的动作合理性\n3、人物面部的细节表情控制与表达。\n\n具体工作：\n你将跟进前沿的生成技术，并参与到文生视频/图生视频等基础生成模型的设计、开发和优化过程中。针对人像视频这个特定领域，完善量化评估，建立benchmark。在此基础之上，将视频生成底模改造适配到实际的下游任务中，结合文本、音频、视觉等多种模态地控制信号，探索新技术在实际应用中的有效性和商业潜力。","requirements":"1、计算机科学、人工智能、模式识别、计算机视觉等相关专业的博士及优秀硕士；具有图像生成、视频生成方向研究背景者优先；\n2、熟悉视频生成领域的基础理论和主流大模型原理，具备大模型实践经验者优先；\n3、在CVPR、ICCV、NeurIPS、ICML等学术会议或期刊发表过文章者优先；\n4、熟练掌握Python编程，熟悉至少一种深度学习框架，如PyTorch等。有较强的代码能力优先，如获得过ACM奖牌或代码开源产生了较大影响力；\n5、熟悉人脸人体相关的生成编辑任务，有实际项目经验的优先；\n6、良好的自驱力，优秀的分析和解决问题的能力，对解决具有挑战性的问题充满激情。","description":"课题描述\n课题背景：\n近年来视频生成领域取得了很大的进展，并在影视创作、社交等场景开始实际应用。其中人像相关视频的生成应用需求最为广泛。\n\n课题挑战：\n1、真人像视频生成中ID的维持能力\n2、人物交互中的动作合理性\n3、人物面部的细节表情控制与表达。\n\n具体工作：\n你将跟进前沿的生成技术，并参与到文生视频/图生视频等基础生成模型的设计、开发和优化过程中。针对人像视频这个特定领域，完善量化评估，建立benchmark。在此基础之上，将视频生成底模改造适配到实际的下游任务中，结合文本、音频、视觉等多种模态地控制信号，探索新技术在实际应用中的有效性和商业潜力。\n\n课题要求\n1、计算机科学、人工智能、模式识别、计算机视觉等相关专业的博士及优秀硕士；具有图像生成、视频生成方向研究背景者优先；\n2、熟悉视频生成领域的基础理论和主流大模型原理，具备大模型实践经验者优先；\n3、在CVPR、ICCV、NeurIPS、ICML等学术会议或期刊发表过文章者优先；\n4、熟练掌握Python编程，熟悉至少一种深度学习框架，如PyTorch等。有较强的代码能力优先，如获得过ACM奖牌或代码开源产生了较大影响力；\n5、熟悉人脸人体相关的生成编辑任务，有实际项目经验的优先；\n6、良好的自驱力，优秀的分析和解决问题的能力，对解决具有挑战性的问题充满激情。\n\nCSIG\n云与智慧产业事业群\n\n优图实验室\n腾讯优图实验室——离产业最近的AI。我们专注于人工智能领域的前沿技术研究和产业实践落地，涵盖了视觉感知理解、多模态理解、大语言模型、计算加速、AIGC等技术研究领域；作为腾讯顶级的人工智能实验室，优图实验室在多个领域开展技术研究和应用落地，同时为腾讯内外部超500+产品和业务提供技术支持和服务；优图实验室汇聚来自国内外的顶尖人才，并与世界顶级院校和机构合作，我们拥有超过1800项全球专利，1000余篇论文被国际顶会收录。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139060","sourceKey":"tencent","company":"腾讯","title":"优图实验室-高精3D生成技术研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139060","duty":"课题背景：\n近年来，图生 3D、文生3D等技术迎来爆发式增长，成为 AIGC 领域最具潜力的方向之一，在游戏开发、数字孪生、影视特效、工业设计等行业展现出巨大的应用价值。然而目前的技术仍然存在几何质量瑕疵、拓扑混乱、纹理保真度不高、渲染兼容性差等问题。 因此本课题聚焦于打破生成式AI与传统计算机图形学之间的壁垒，将3D生成模型和整个计算机图形学管线深度融合，实现工业级“生成即可用”的高质量3D资产生成。\n\n课题内容：\n1. 精通计算机图形学管线并能根据问题针对性优化：能完整搭建3D建模、拓扑优化、UV展开、贴图制作、光栅化、纹理烘焙、光照合成等全流程，并与最新的生成式AI模型的训练、推理流程融合。\n2. 3D 表达技术优化：掌握传统几何处理管线，熟悉新型的3D表示原理，例如NeRF、SDF、3D Gaussian Splatting 。解决不同表示方式存在的质量损失和效率瓶颈问题。\n3. 工业级材质纹理生成技术：深入了解常见生成模型原理，例如扩散模型、流匹配、自回归或掩码自回归，实现符合物理规律、支持主流引擎直接渲染的高质量 PBR 材质与纹理自动生成。\n4. 多模态与后训练融合的 3D 生成增强技术：精通生成模型的后训练方法，例如高效参数微调、强化学习等。 研究多模态语义约束下的3D生成模型的后训练范式，实现3D资产的几何、纹理、光照与多模态输入的精准对齐。能够搭建基于多模态模型的3D资产自动质量评价流程。\n\n具体工作：\n你将参与到计算机图形学管线搭建和优化，并与生成式模型进行深度融合的工作中。搭建生成模型训练流程，根据阶段性问题优化管线问题，提升整体生成结果的语义准确性、物理真实性和工业级渲染兼容性。3D生成模型训练与应用等。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学等专业的博士和优秀硕士；有计算机图形学等相关研究经验者优先；\n2、精通计算机图形学管线原理，理解3D建模、 Mesh 拓扑、UV 展开、贴图制作、光栅化、纹理烘焙、光照合成等底层技术，熟悉至少一种主流 3D 建模软件与渲染引擎；\n3、熟悉常见生成模型原理，包括但不限于扩散模型、流匹配、自回归或掩码自回归，有3D生成、重建经验者优先；\n4、熟悉常见的后训练和生成模型加速技术，能将业界新方法迁移到不同的问题场景中，提出创新性解决方案；\n5、代码能力强，具备较强的学习、沟通和团队协作能力。","description":"课题描述\n课题背景：\n近年来，图生 3D、文生3D等技术迎来爆发式增长，成为 AIGC 领域最具潜力的方向之一，在游戏开发、数字孪生、影视特效、工业设计等行业展现出巨大的应用价值。然而目前的技术仍然存在几何质量瑕疵、拓扑混乱、纹理保真度不高、渲染兼容性差等问题。 因此本课题聚焦于打破生成式AI与传统计算机图形学之间的壁垒，将3D生成模型和整个计算机图形学管线深度融合，实现工业级“生成即可用”的高质量3D资产生成。\n\n课题内容：\n1. 精通计算机图形学管线并能根据问题针对性优化：能完整搭建3D建模、拓扑优化、UV展开、贴图制作、光栅化、纹理烘焙、光照合成等全流程，并与最新的生成式AI模型的训练、推理流程融合。\n2. 3D 表达技术优化：掌握传统几何处理管线，熟悉新型的3D表示原理，例如NeRF、SDF、3D Gaussian Splatting 。解决不同表示方式存在的质量损失和效率瓶颈问题。\n3. 工业级材质纹理生成技术：深入了解常见生成模型原理，例如扩散模型、流匹配、自回归或掩码自回归，实现符合物理规律、支持主流引擎直接渲染的高质量 PBR 材质与纹理自动生成。\n4. 多模态与后训练融合的 3D 生成增强技术：精通生成模型的后训练方法，例如高效参数微调、强化学习等。 研究多模态语义约束下的3D生成模型的后训练范式，实现3D资产的几何、纹理、光照与多模态输入的精准对齐。能够搭建基于多模态模型的3D资产自动质量评价流程。\n\n具体工作：\n你将参与到计算机图形学管线搭建和优化，并与生成式模型进行深度融合的工作中。搭建生成模型训练流程，根据阶段性问题优化管线问题，提升整体生成结果的语义准确性、物理真实性和工业级渲染兼容性。3D生成模型训练与应用等。\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学等专业的博士和优秀硕士；有计算机图形学等相关研究经验者优先；\n2、精通计算机图形学管线原理，理解3D建模、 Mesh 拓扑、UV 展开、贴图制作、光栅化、纹理烘焙、光照合成等底层技术，熟悉至少一种主流 3D 建模软件与渲染引擎；\n3、熟悉常见生成模型原理，包括但不限于扩散模型、流匹配、自回归或掩码自回归，有3D生成、重建经验者优先；\n4、熟悉常见的后训练和生成模型加速技术，能将业界新方法迁移到不同的问题场景中，提出创新性解决方案；\n5、代码能力强，具备较强的学习、沟通和团队协作能力。\n\nCSIG\n云与智慧产业事业群\n\n优图实验室\n腾讯优图实验室——离产业最近的AI。我们专注于人工智能领域的前沿技术研究和产业实践落地，涵盖了视觉感知理解、多模态理解、大语言模型、计算加速、AIGC等技术研究领域；作为腾讯顶级的人工智能实验室，优图实验室在多个领域开展技术研究和应用落地，同时为腾讯内外部超500+产品和业务提供技术支持和服务；优图实验室汇聚来自国内外的顶尖人才，并与世界顶级院校和机构合作，我们拥有超过1800项全球专利，1000余篇论文被国际顶会收录。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139061","sourceKey":"tencent","company":"腾讯","title":"优图实验室—音频大模型研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139061","duty":"课题背景：\n音频是信息传递的核心模态之一，贯穿生产生活全场景。相较于视觉、文本大模型的爆发式发展，音频领域研究存在明显短板：现有模型多局限于单一任务（如仅语音识别、仅音乐分类），缺乏跨音频类型（语音 / 音乐 / 环境音）的统一能力；音频理解深度不足，难以实现复杂语义推理与情感分析；全模态融合中，音频常处于辅助地位，未形成 “平等融合”的技术范式，无法充分发挥其信息价值。\n\n课题挑战：\n1、统一音频表征学习：突破语音、音乐、环境音的模态壁垒，构建通用音频表征模型，实现不同音频类型的统一理解与特征复用，解决现有模型 “任务割裂” 问题；\n2、构建音频大模型范式：打造具备 “处理 - 分类 - 理解 - 推理 - 生成 - 评价” 全链路能力的大模型架构，覆盖从基础音频处理到高阶智能决策的全需求，适配多业务场景的灵活调用；\n3、探索音频全模态融合方法：研究音频与文本、图像、视频的深度融合机制，突破 “音频辅助” 的传统模式，实现多模态信息的互补增强。\n\n具体工作：\n你将参与音频大模型相关的数据与建模工作，并结合安全审核和内容理解等业务需求寻找落地途径，探索与其他模态相融合方法。","requirements":"1、包含但不限于计算机、人工智能、模式识别等相关专业的博士和优秀硕士；\n2、熟悉机器学习、深度学习、大模型等基础理论与算法，具有语音/音频/多模态相关研究经历的优先；\n3、有较强的学术研究能力，在人工智能或语音相关顶会上有论文发表者优先；\n4、熟练掌握Python编程，熟悉分布式训练框架，具备丰富的大模型训练经验；\n5、具备较强的逻辑思考和解决问题能力，沟通协作和逻辑表达良好。","description":"课题描述\n课题背景：\n音频是信息传递的核心模态之一，贯穿生产生活全场景。相较于视觉、文本大模型的爆发式发展，音频领域研究存在明显短板：现有模型多局限于单一任务（如仅语音识别、仅音乐分类），缺乏跨音频类型（语音 / 音乐 / 环境音）的统一能力；音频理解深度不足，难以实现复杂语义推理与情感分析；全模态融合中，音频常处于辅助地位，未形成 “平等融合”的技术范式，无法充分发挥其信息价值。\n\n课题挑战：\n1、统一音频表征学习：突破语音、音乐、环境音的模态壁垒，构建通用音频表征模型，实现不同音频类型的统一理解与特征复用，解决现有模型 “任务割裂” 问题；\n2、构建音频大模型范式：打造具备 “处理 - 分类 - 理解 - 推理 - 生成 - 评价” 全链路能力的大模型架构，覆盖从基础音频处理到高阶智能决策的全需求，适配多业务场景的灵活调用；\n3、探索音频全模态融合方法：研究音频与文本、图像、视频的深度融合机制，突破 “音频辅助” 的传统模式，实现多模态信息的互补增强。\n\n具体工作：\n你将参与音频大模型相关的数据与建模工作，并结合安全审核和内容理解等业务需求寻找落地途径，探索与其他模态相融合方法。\n\n课题要求\n1、包含但不限于计算机、人工智能、模式识别等相关专业的博士和优秀硕士；\n2、熟悉机器学习、深度学习、大模型等基础理论与算法，具有语音/音频/多模态相关研究经历的优先；\n3、有较强的学术研究能力，在人工智能或语音相关顶会上有论文发表者优先；\n4、熟练掌握Python编程，熟悉分布式训练框架，具备丰富的大模型训练经验；\n5、具备较强的逻辑思考和解决问题能力，沟通协作和逻辑表达良好。\n\nCSIG\n云与智慧产业事业群\n\n优图实验室\n腾讯优图实验室——离产业最近的AI。我们专注于人工智能领域的前沿技术研究和产业实践落地，涵盖了视觉感知理解、多模态理解、大语言模型、计算加速、AIGC等技术研究领域；作为腾讯顶级的人工智能实验室，优图实验室在多个领域开展技术研究和应用落地，同时为腾讯内外部超500+产品和业务提供技术支持和服务；优图实验室汇聚来自国内外的顶尖人才，并与世界顶级院校和机构合作，我们拥有超过1800项全球专利，1000余篇论文被国际顶会收录。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139064","sourceKey":"tencent","company":"腾讯","title":"腾讯云安全—LLM & Agentic AI安全护栏研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139064","duty":"课题背景：\n随着大语言模型从“对话框”走向“智能体（Agent）”，其具备了调用 API、执行代码及操作数据库的自主能力。然而，这引入了全新的安全风险：Agent 可能被诱导执行破坏性指令（如删除线上数据）、滥用高额付费接口或泄露系统机密。传统的文本过滤已不足以应对物理世界的行为风险。本课题旨在构建 LLM & Agent 双重护栏，不仅监控输入输出的语义安全，更深层地对 Agent 的 Action（执行动作） 进行实时拦截、风险评估与权限管控，确保 Agent 在预设的安全沙盒内运行。\n\n课题挑战：\n1、Action 语义合规与意图对齐： 如何精准识别 Agent 生成的 Tool Call 是否背离了用户原始意图，防止“幻觉”导致的越狱执行或误操作；Agent 行为的语义对齐， 如何训练模型理解特定领域工具调用的深层风险（如在金融系统执行高频交易指令的潜在风险），建立 Action 到安全等级的精准映射；\n2、高风险动作的动态判定： 针对删除、转账、敏感查询等高风险 Action，如何构建一套基于上下文的动态审批流（Human-in-the-loop）与自动阻断机制；\n3、多工具调用的链式安全： 在复杂的 Agent 任务流中，如何防止通过一系列看似无害的组合动作（Chain of Thought）最终诱发的协同攻击；\n4、执行环境的隔离与沙盒化： 如何在保障执行效率的同时，为 Code Interpreter 或 Bash Tool 提供极致的安全沙盒，防御针对宿主机的逃逸攻击；\n5、实时防御与性能损耗： 在多步推理中，如何在每一跳（Hop）的 Action 触发前完成毫秒级的安全前置检查。\n\n具体工作：\n你将主导 LLM-Guard 领域模型的训练全流程。包括：构建行业级安全指令微调数据集；应用 SFT、DPO 或 PPO 算法进行模型安全对齐；探索基于特征解耦的 Agent 行为检测模型；优化在线推理侧的 Guard 模型，并持续迭代自动化评测体系。","requirements":"1、来自计算机、软件工程、人工智能、信息安全或数学等相关专业的硕士或博士同学；对大模型安全、对齐技术或智能体（Agent）有浓厚兴趣和基础了解；\n2、熟悉 NLP 基础算法及 Transformer 架构，了解大模型微调（如 SFT、LoRA）的基本原理；熟练掌握 Python 编程，至少使用过 PyTorch 或 TensorFlow 其中一种深度学习框架；\n3、了解常见的 Agent 机制（如 Function Calling）及基础的网络安全/内容合规概念者优先；\n4、具备良好的逻辑思维与问题分析能力；沟通协作能力强，能够积极主动跟踪领域内的新技术；具备一定的工程实现能力，能将算法逻辑转化为实验代码。","description":"课题描述\n课题背景：\n随着大语言模型从“对话框”走向“智能体（Agent）”，其具备了调用 API、执行代码及操作数据库的自主能力。然而，这引入了全新的安全风险：Agent 可能被诱导执行破坏性指令（如删除线上数据）、滥用高额付费接口或泄露系统机密。传统的文本过滤已不足以应对物理世界的行为风险。本课题旨在构建 LLM & Agent 双重护栏，不仅监控输入输出的语义安全，更深层地对 Agent 的 Action（执行动作） 进行实时拦截、风险评估与权限管控，确保 Agent 在预设的安全沙盒内运行。\n\n课题挑战：\n1、Action 语义合规与意图对齐： 如何精准识别 Agent 生成的 Tool Call 是否背离了用户原始意图，防止“幻觉”导致的越狱执行或误操作；Agent 行为的语义对齐， 如何训练模型理解特定领域工具调用的深层风险（如在金融系统执行高频交易指令的潜在风险），建立 Action 到安全等级的精准映射；\n2、高风险动作的动态判定： 针对删除、转账、敏感查询等高风险 Action，如何构建一套基于上下文的动态审批流（Human-in-the-loop）与自动阻断机制；\n3、多工具调用的链式安全： 在复杂的 Agent 任务流中，如何防止通过一系列看似无害的组合动作（Chain of Thought）最终诱发的协同攻击；\n4、执行环境的隔离与沙盒化： 如何在保障执行效率的同时，为 Code Interpreter 或 Bash Tool 提供极致的安全沙盒，防御针对宿主机的逃逸攻击；\n5、实时防御与性能损耗： 在多步推理中，如何在每一跳（Hop）的 Action 触发前完成毫秒级的安全前置检查。\n\n具体工作：\n你将主导 LLM-Guard 领域模型的训练全流程。包括：构建行业级安全指令微调数据集；应用 SFT、DPO 或 PPO 算法进行模型安全对齐；探索基于特征解耦的 Agent 行为检测模型；优化在线推理侧的 Guard 模型，并持续迭代自动化评测体系。\n\n课题要求\n1、来自计算机、软件工程、人工智能、信息安全或数学等相关专业的硕士或博士同学；对大模型安全、对齐技术或智能体（Agent）有浓厚兴趣和基础了解；\n2、熟悉 NLP 基础算法及 Transformer 架构，了解大模型微调（如 SFT、LoRA）的基本原理；熟练掌握 Python 编程，至少使用过 PyTorch 或 TensorFlow 其中一种深度学习框架；\n3、了解常见的 Agent 机制（如 Function Calling）及基础的网络安全/内容合规概念者优先；\n4、具备良好的逻辑思维与问题分析能力；沟通协作能力强，能够积极主动跟踪领域内的新技术；具备一定的工程实现能力，能将算法逻辑转化为实验代码。\n\nCSIG\n云与智慧产业事业群\n\n腾讯安全\n腾讯安全是腾讯云旗下，以多个安全实验室作为实力技术支撑的网络安全领先品牌。旗下产品包含面对用户的全方位网络安全应用、对政企网络安全的系列解决方案，成为保卫腾讯互联网业务发展及用户、政企三方网络安全的守护者。腾讯安全把多年积累的网络安全技术能力提供给行业合作伙伴，共同推进中国网络安全环境建设。\n腾讯安全集结TK、killer、吴石等大批顶尖安全专家，多次斩获国内、外各大顶级赛事冠军，两次夺得有“网安世界杯”之称的DEF CON CTF全球总冠军；拥有超2200多项安全技术专利，位居行业领先地位。\n依托20年多业务安全运营及黑灰产对抗经验，腾讯安全构建了业界最大的威胁情报库、完备的大数据分析能力、AI及大模型技术积累，为客户提供提供紧贴业务需要的安全实践，守护客户的 AI Agent、数据、系统、业务安全，全力守护智能时代的美好未来。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139065","sourceKey":"tencent","company":"腾讯","title":"腾讯天御—基于大模型的移动安全病毒检测研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139065","duty":"课题背景：\n近年来，随着移动安全研究的不断深入，移动安全病毒威胁日益复杂多样化，传统基于规则或安全策略的检测方法难以应对新型、隐蔽的病毒手段。大模型凭借其强大的语义理解、复杂推理和泛化学习能力，为移动安全病毒检测提供了智能化的新路径。本研究旨在探索大模型相关技术在移动安全病毒检测中的应用，提升检测效果和检测效率，以应对不断对抗演化的移动安全挑战，保障用户移动设备安全。\n\n课题挑战：\n1、大模型在垂类领域的适配研究：大模型需从通用领域迁移至移动安全垂类领域，需解决领域知识注入、不平衡样本学习、对抗样本鲁棒性等问题，以提升传统安全检测能力；\n2、安全领域特性：在安全领域，对准确率要求极高，并对判毒样本有着可解释性的诉求。在安全领域应用大模型技术，如何兼顾高准确率和可解释性，值得研究；\n3、海量数据下的性能瓶颈：天御移动安全保护着海量用户，移动端样本数量庞大，而大模型的计算开销和时延又是显著特点之一，需研究如何在海量数据下高效应用大模型技术；\n4、安全运营提效：安全运营是安全领域的重要工作之一，如何应用大模型相关技术有效提升安全运营效率。\n\n具体工作：\n您将参与到大模型在安全领域的前沿研究，包括大模型在移动安全病毒检测场景的领域适配、监督微调与强化学习优化，利用多模态等技术实现移动安全病毒样本的自动化触发与检测，构建移动安全智能运营Agent，从而提升移动安全病毒检测工作的效果与效率。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟悉Transformer模型及其变种原理与架构，具备LLM相关经验，包括但不限于预训练/微调/强化学习/多模态/Agent等；\n3、较强的工程实现能力，熟练掌握C/C++, JAVA,Python等至少一种语言；\n4、具备极强的学习能力和技术追求，擅于思考、自驱力强，良好的团队合作和沟通能力。","description":"课题描述\n课题背景：\n近年来，随着移动安全研究的不断深入，移动安全病毒威胁日益复杂多样化，传统基于规则或安全策略的检测方法难以应对新型、隐蔽的病毒手段。大模型凭借其强大的语义理解、复杂推理和泛化学习能力，为移动安全病毒检测提供了智能化的新路径。本研究旨在探索大模型相关技术在移动安全病毒检测中的应用，提升检测效果和检测效率，以应对不断对抗演化的移动安全挑战，保障用户移动设备安全。\n\n课题挑战：\n1、大模型在垂类领域的适配研究：大模型需从通用领域迁移至移动安全垂类领域，需解决领域知识注入、不平衡样本学习、对抗样本鲁棒性等问题，以提升传统安全检测能力；\n2、安全领域特性：在安全领域，对准确率要求极高，并对判毒样本有着可解释性的诉求。在安全领域应用大模型技术，如何兼顾高准确率和可解释性，值得研究；\n3、海量数据下的性能瓶颈：天御移动安全保护着海量用户，移动端样本数量庞大，而大模型的计算开销和时延又是显著特点之一，需研究如何在海量数据下高效应用大模型技术；\n4、安全运营提效：安全运营是安全领域的重要工作之一，如何应用大模型相关技术有效提升安全运营效率。\n\n具体工作：\n您将参与到大模型在安全领域的前沿研究，包括大模型在移动安全病毒检测场景的领域适配、监督微调与强化学习优化，利用多模态等技术实现移动安全病毒样本的自动化触发与检测，构建移动安全智能运营Agent，从而提升移动安全病毒检测工作的效果与效率。\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟悉Transformer模型及其变种原理与架构，具备LLM相关经验，包括但不限于预训练/微调/强化学习/多模态/Agent等；\n3、较强的工程实现能力，熟练掌握C/C++, JAVA,Python等至少一种语言；\n4、具备极强的学习能力和技术追求，擅于思考、自驱力强，良好的团队合作和沟通能力。\n\nCSIG\n云与智慧产业事业群\n\n腾讯安全\n腾讯安全是腾讯云旗下，以多个安全实验室作为实力技术支撑的网络安全领先品牌。旗下产品包含面对用户的全方位网络安全应用、对政企网络安全的系列解决方案，成为保卫腾讯互联网业务发展及用户、政企三方网络安全的守护者。腾讯安全把多年积累的网络安全技术能力提供给行业合作伙伴，共同推进中国网络安全环境建设。\n腾讯安全集结TK、killer、吴石等大批顶尖安全专家，多次斩获国内、外各大顶级赛事冠军，两次夺得有“网安世界杯”之称的DEF CON CTF全球总冠军；拥有超2200多项安全技术专利，位居行业领先地位。\n依托20年多业务安全运营及黑灰产对抗经验，腾讯安全构建了业界最大的威胁情报库、完备的大数据分析能力、AI及大模型技术积累，为客户提供提供紧贴业务需要的安全实践，守护客户的 AI Agent、数据、系统、业务安全，全力守护智能时代的美好未来。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139067","sourceKey":"tencent","company":"腾讯","title":"自动驾驶实验室—基于世界模型的自动驾驶数据合成技术研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139067","duty":"课题背景：\n针对自动驾驶长尾场景数据匮乏及传统合成数据“域差距”痛点，本课题融合Stable Diffusion语义生成与3D/4D高斯泼溅（3D/4DGS）神经渲染技术，构建自动驾驶生成式世界模型。旨在通过实车数据的高保真数字化重构与可控编辑，低成本量产带完美真值的极端场景样本，突破感知与规划算法在复杂工况下的鲁棒性瓶颈。\n\n课题挑战：\n1、动态四维一致性与物理建模：在4DGS重建高速运动物体时，如何消除时空伪影与闪烁？在编辑天气、光照或轨迹时，如何确保阴影、遮挡等变化符合真实物理规律，维持画面逻辑自洽？\n2、2D先验到3D几何的精准映射：Stable Diffusion缺乏显式3D认知，如何将大模型的强语义生成能力（如“侧翻卡车”）精准约束至3D/4DGS几何结构？需解决多视角一致性难题，实现既符合文本指令又几何正确的可控场景编辑，避免结构崩塌或纹理畸变。\n\n具体工作：\n研发改进版4DGS算法，实现动态场景秒级初始化与高保真重构；构建连接Diffusion与3DGS的语义编辑引擎，支持文本/草图驱动的多视角一致场景修改；设计自动化真值流水线，反推生成像素级标注数据；跟踪顶会前沿，优化模型量化部署，赋能端到端自动驾驶闭环仿真。","requirements":"学历与专业：\n硕士及以上学历，计算机、自动化、人工智能相关专业。具备扎实的三维视觉和深度学习理论基础，有自动驾驶、3DGS和Diffusion Transformer相关研究经验和项目经历。\n\n技术技能：\n精通PyTorch，熟悉3DGS、Diffusion Models原理。具备Python/c++代码能力，有多传感器融合实战经验者优先。\n\n软性素质：\n对前沿技术有敏锐洞察力，具备极强的自驱力与问题解决能力。拥有优秀的逻辑思维与团队协作精神，能在快节奏研发中高效沟通，勇于挑战技术无人区。","description":"课题描述\n课题背景：\n针对自动驾驶长尾场景数据匮乏及传统合成数据“域差距”痛点，本课题融合Stable Diffusion语义生成与3D/4D高斯泼溅（3D/4DGS）神经渲染技术，构建自动驾驶生成式世界模型。旨在通过实车数据的高保真数字化重构与可控编辑，低成本量产带完美真值的极端场景样本，突破感知与规划算法在复杂工况下的鲁棒性瓶颈。\n\n课题挑战：\n1、动态四维一致性与物理建模：在4DGS重建高速运动物体时，如何消除时空伪影与闪烁？在编辑天气、光照或轨迹时，如何确保阴影、遮挡等变化符合真实物理规律，维持画面逻辑自洽？\n2、2D先验到3D几何的精准映射：Stable Diffusion缺乏显式3D认知，如何将大模型的强语义生成能力（如“侧翻卡车”）精准约束至3D/4DGS几何结构？需解决多视角一致性难题，实现既符合文本指令又几何正确的可控场景编辑，避免结构崩塌或纹理畸变。\n\n具体工作：\n研发改进版4DGS算法，实现动态场景秒级初始化与高保真重构；构建连接Diffusion与3DGS的语义编辑引擎，支持文本/草图驱动的多视角一致场景修改；设计自动化真值流水线，反推生成像素级标注数据；跟踪顶会前沿，优化模型量化部署，赋能端到端自动驾驶闭环仿真。\n\n课题要求\n学历与专业：\n硕士及以上学历，计算机、自动化、人工智能相关专业。具备扎实的三维视觉和深度学习理论基础，有自动驾驶、3DGS和Diffusion Transformer相关研究经验和项目经历。\n\n技术技能：\n精通PyTorch，熟悉3DGS、Diffusion Models原理。具备Python/c++代码能力，有多传感器融合实战经验者优先。\n\n软性素质：\n对前沿技术有敏锐洞察力，具备极强的自驱力与问题解决能力。拥有优秀的逻辑思维与团队协作精神，能在快节奏研发中高效沟通，勇于挑战技术无人区。\n\nCSIG\n云与智慧产业事业群\n\n腾讯地图\n腾讯地图以手机地图APP、出行服务小程序、位置服务、位置大数据及智驾图等业务产品形态，基于8000万+POI点位，以AI重塑时空智能，构建起包括微信、QQ、腾讯游戏、京东、美团、滴滴等在内的腾讯LBS生态。\n立足生态，助力人们更便捷地生活、工作和出行，进而影响亿万人的生活方式；连接未来，一起构建虚拟与现实交融的新互联网世界。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139069","sourceKey":"tencent","company":"腾讯","title":"腾讯地图多模态大模型融合建图研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139069","duty":"课题背景：\n高精度地图与环境感知是自动驾驶、机器人导航、智能交通与数字孪生场景的核心基础设施。传统建图方案多依赖激光雷达、视觉、IMU 等单一或简单融合的传感器数据，在复杂城市场景、极端光照、动态遮挡、无纹理区域等条件下，存在鲁棒性不足、精度受限、语义信息缺失、建图效率低等问题。\n随着多模态大模型与端到端感知技术的快速发展，基于视觉、激光、文本语义、先验地图、GPS / 北斗位置信息等多源异构数据的联合建图成为下一代主流技术方向。但当前行业仍面临三大核心瓶颈：\n1、多模态数据难以深度对齐：图像、点云、位置、文本等数据在时空、特征、语义层面缺乏统一表征与融合机制；\n2、环境语义理解能力薄弱：现有建图系统以几何重建为主，缺乏对道路、设施、障碍物、交通规则的高层语义理解与结构化表达；\n3、泛化与鲁棒性不足：在长尾场景、陌生环境、动态干扰下易失效，难以实现大规模、低成本、自动化的地图更新与维护。\n本课题旨在突破传统几何建图范式，构建多模态原生融合的端到端建图体系，实现高精度、高鲁棒、高语义的自动化地图构建与持续更新。\n\n课题挑战：\n1、多源异构数据融合建模：视觉、激光、惯性、位置、文本等模态差异大，时空校准与特征融合难度高，业界缺乏统一的融合表征框架；\n2、语义与几何联合优化：同时满足地图的几何精度、拓扑一致性与语义完整性，存在多目标约束与优化冲突问题；\n3、动态环境与在线建图：在动态障碍物干扰下实现稳定建图，支持低算力平台实时推理与增量更新；\n4、大模型与传统 SLAM 深度结合：如何将多模态大模型的感知与理解能力，注入到经典 SLAM 流程中，提升泛化性与鲁棒性，是前沿且开放的难题。\n\n具体工作：\n你将参与下一代多模态融合建图系统的核心研发，主要内容包括：\n多模态（图像 / 点云 / IMU / 位置 / 文本）时空对齐与深度融合模型设计；\n面向建图的多模态基座模型预训练、特征提取与跨模态表征学习；\n视觉 - 激光融合定位、SLAM、里程计与后端优化算法研发；\n语义分割、目标检测、场景理解与地图结构化信息抽取；\n语义与几何联合约束的图优化、束调整与地图一致性校正；\n大模型驱动的自动化建图、标注、校验与增量更新闭环系统；\n多任务联合训练策略、蒸馏量化、端侧部署与完整评估体系建设。","requirements":"学历和专业要求：\n包括但不限于：计算机科学与技术、人工智能、自动化、机器人、模式识别、遥感与地理信息工程（GIS）、测绘工程、应用数学、统计学等相关专业博士及优秀硕士。\n\n技术技能要求：\n熟练掌握多模态模型、SLAM、三维重建、深度学习基础理论与主流方法；\n具备扎实的工程能力，熟悉 PyTorch/TensorFlow 等训练框架，有模型训练、优化与部署经验；\n\n有以下任一经验者优先：\n1、多模态融合、VLM 大模型、特征对齐与跨模态表征学习；\n2、视觉 / 激光 SLAM、视觉里程计、点云处理、传感器标定与融合；\n4、3、三维重建、语义建图、数字孪生、自动驾驶环境感知；\n模型优化、蒸馏、量化、端侧部署与系统落地经验。\n\n软性素质要求：\n1、具备极强的自驱力与科研探索精神，能够在前沿方向上独立拆解问题、设计方案并落地；\n2、具备良好的论文阅读、算法复现与创新能力，善于在无成熟方案的场景下推进迭代；\n3、具备优秀的跨团队协作与沟通能力，能够快速理解业务场景并将技术转化为实际产品价值。","description":"课题描述\n课题背景：\n高精度地图与环境感知是自动驾驶、机器人导航、智能交通与数字孪生场景的核心基础设施。传统建图方案多依赖激光雷达、视觉、IMU 等单一或简单融合的传感器数据，在复杂城市场景、极端光照、动态遮挡、无纹理区域等条件下，存在鲁棒性不足、精度受限、语义信息缺失、建图效率低等问题。\n随着多模态大模型与端到端感知技术的快速发展，基于视觉、激光、文本语义、先验地图、GPS / 北斗位置信息等多源异构数据的联合建图成为下一代主流技术方向。但当前行业仍面临三大核心瓶颈：\n1、多模态数据难以深度对齐：图像、点云、位置、文本等数据在时空、特征、语义层面缺乏统一表征与融合机制；\n2、环境语义理解能力薄弱：现有建图系统以几何重建为主，缺乏对道路、设施、障碍物、交通规则的高层语义理解与结构化表达；\n3、泛化与鲁棒性不足：在长尾场景、陌生环境、动态干扰下易失效，难以实现大规模、低成本、自动化的地图更新与维护。\n本课题旨在突破传统几何建图范式，构建多模态原生融合的端到端建图体系，实现高精度、高鲁棒、高语义的自动化地图构建与持续更新。\n\n课题挑战：\n1、多源异构数据融合建模：视觉、激光、惯性、位置、文本等模态差异大，时空校准与特征融合难度高，业界缺乏统一的融合表征框架；\n2、语义与几何联合优化：同时满足地图的几何精度、拓扑一致性与语义完整性，存在多目标约束与优化冲突问题；\n3、动态环境与在线建图：在动态障碍物干扰下实现稳定建图，支持低算力平台实时推理与增量更新；\n4、大模型与传统 SLAM 深度结合：如何将多模态大模型的感知与理解能力，注入到经典 SLAM 流程中，提升泛化性与鲁棒性，是前沿且开放的难题。\n\n具体工作：\n你将参与下一代多模态融合建图系统的核心研发，主要内容包括：\n多模态（图像 / 点云 / IMU / 位置 / 文本）时空对齐与深度融合模型设计；\n面向建图的多模态基座模型预训练、特征提取与跨模态表征学习；\n视觉 - 激光融合定位、SLAM、里程计与后端优化算法研发；\n语义分割、目标检测、场景理解与地图结构化信息抽取；\n语义与几何联合约束的图优化、束调整与地图一致性校正；\n大模型驱动的自动化建图、标注、校验与增量更新闭环系统；\n多任务联合训练策略、蒸馏量化、端侧部署与完整评估体系建设。\n\n课题要求\n学历和专业要求：\n包括但不限于：计算机科学与技术、人工智能、自动化、机器人、模式识别、遥感与地理信息工程（GIS）、测绘工程、应用数学、统计学等相关专业博士及优秀硕士。\n\n技术技能要求：\n熟练掌握多模态模型、SLAM、三维重建、深度学习基础理论与主流方法；\n具备扎实的工程能力，熟悉 PyTorch/TensorFlow 等训练框架，有模型训练、优化与部署经验；\n\n有以下任一经验者优先：\n1、多模态融合、VLM 大模型、特征对齐与跨模态表征学习；\n2、视觉 / 激光 SLAM、视觉里程计、点云处理、传感器标定与融合；\n4、3、三维重建、语义建图、数字孪生、自动驾驶环境感知；\n模型优化、蒸馏、量化、端侧部署与系统落地经验。\n\n软性素质要求：\n1、具备极强的自驱力与科研探索精神，能够在前沿方向上独立拆解问题、设计方案并落地；\n2、具备良好的论文阅读、算法复现与创新能力，善于在无成熟方案的场景下推进迭代；\n3、具备优秀的跨团队协作与沟通能力，能够快速理解业务场景并将技术转化为实际产品价值。\n\nCSIG\n云与智慧产业事业群\n\n腾讯地图\n腾讯地图以手机地图APP、出行服务小程序、位置服务、位置大数据及智驾图等业务产品形态，基于8000万+POI点位，以AI重塑时空智能，构建起包括微信、QQ、腾讯游戏、京东、美团、滴滴等在内的腾讯LBS生态。\n立足生态，助力人们更便捷地生活、工作和出行，进而影响亿万人的生活方式；连接未来，一起构建虚拟与现实交融的新互联网世界。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139072","sourceKey":"tencent","company":"腾讯","title":"元宝—基于大模型的搜索排序技术研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139072","duty":"课题背景：\n攻克AI搜索场景排序能力的突破难题，优化搜索能力的鲁棒性和满意度。\n\n课题挑战：\n1、 大模型排序(LLM Ranking): 传统搜索的排序模型在“长尾 Query 理解”和“深层语义对齐”上存在一定瓶颈，需要平衡 LLM 的语义通识能力、领域任务解决能力\n2、模型推理（Reasoning Ranking）： AI 搜索场景大量的复杂查询、长尾满足，需要模型具备一定的推理能力，建模目标从“概率匹配”进化到“逻辑决策”。\n3、 基于强化反馈的排序泛化增强（RL from Feedback）：如何在领域任务下，引入强化反馈，在噪声环境下设置有效的 reward，引导模型增强细粒度排序的泛化能力\n4、推理加速：在长上下文与多文档排序中，需在极低延迟约束下，解决压缩表征导致的关键信息丢失与语义匹配的平衡难题。\n\n具体工作：\n1、大模型排序(LLM Ranking):\n研究大模型排序核心技术如LLM Scaling Up、Continued Pre-Training、Reasoning Ranking等方向，提升多目标排序满意度和鲁棒性\n2、Reasoning Ranking：\n借鉴思维链（CoT）， 引入自反思机制（Self-Reflection），对比推理过程与最终打分的一致性，通过rubrics 等有效过程监督信号，提升推理能力。\n3、基于强化反馈的排序泛化增强:\n构建鲁棒的奖励模型，利用 DPO、GRPO 等建模方式，对 DocList 进行细粒度偏序的感知能力，合成有效的过程监督、结果监督 reward，引导模型进行有效泛化补充。\n4、推理加速:\n探究 Query 感知的动态 Token 修剪与层级化语义表征算法，通过注意力机制识别并剔除文档冗余信息；构建轻量化压缩模型，将长文本编码为固定长度的 Soft Tokens；同步优化 KV Cache 缓存策略与算子并行化等","requirements":"学历和专业要求：\n计算机、人工智能、数学等相关专业硕士或博士。重点关注在自然语言处理 (NLP)、信息检索 (IR)、大模型微调或强化学习领域有深厚学术积累或顶会论文发表（如 ACL、SIGIR、KDD、NeurIPS）的同学。\n\n技术技能要求：\n熟练掌握 PyTorch/DeepSpeed 及主流大模型架构，深入理解 RAG、LTR 排序及 RLHF/DPO 算法。精通 Python/C++，具备优秀的底层算子优化或 KV Cache 优化能力，有大规模分布式训练及搜索性能调优经验者优先。\n\n软性素质要求：\n具备极强的逻辑思维与自驱动力，能够敏锐捕捉前沿技术并转化为业务落地。拥有出色的抗压能力与团队协作精神，能在复杂业务场景下保持沟通高效，对解决算法落地中的硬核挑战充满激情。","description":"课题描述\n课题背景：\n攻克AI搜索场景排序能力的突破难题，优化搜索能力的鲁棒性和满意度。\n\n课题挑战：\n1、 大模型排序(LLM Ranking): 传统搜索的排序模型在“长尾 Query 理解”和“深层语义对齐”上存在一定瓶颈，需要平衡 LLM 的语义通识能力、领域任务解决能力\n2、模型推理（Reasoning Ranking）： AI 搜索场景大量的复杂查询、长尾满足，需要模型具备一定的推理能力，建模目标从“概率匹配”进化到“逻辑决策”。\n3、 基于强化反馈的排序泛化增强（RL from Feedback）：如何在领域任务下，引入强化反馈，在噪声环境下设置有效的 reward，引导模型增强细粒度排序的泛化能力\n4、推理加速：在长上下文与多文档排序中，需在极低延迟约束下，解决压缩表征导致的关键信息丢失与语义匹配的平衡难题。\n\n具体工作：\n1、大模型排序(LLM Ranking):\n研究大模型排序核心技术如LLM Scaling Up、Continued Pre-Training、Reasoning Ranking等方向，提升多目标排序满意度和鲁棒性\n2、Reasoning Ranking：\n借鉴思维链（CoT）， 引入自反思机制（Self-Reflection），对比推理过程与最终打分的一致性，通过rubrics 等有效过程监督信号，提升推理能力。\n3、基于强化反馈的排序泛化增强:\n构建鲁棒的奖励模型，利用 DPO、GRPO 等建模方式，对 DocList 进行细粒度偏序的感知能力，合成有效的过程监督、结果监督 reward，引导模型进行有效泛化补充。\n4、推理加速:\n探究 Query 感知的动态 Token 修剪与层级化语义表征算法，通过注意力机制识别并剔除文档冗余信息；构建轻量化压缩模型，将长文本编码为固定长度的 Soft Tokens；同步优化 KV Cache 缓存策略与算子并行化等\n\n课题要求\n学历和专业要求：\n计算机、人工智能、数学等相关专业硕士或博士。重点关注在自然语言处理 (NLP)、信息检索 (IR)、大模型微调或强化学习领域有深厚学术积累或顶会论文发表（如 ACL、SIGIR、KDD、NeurIPS）的同学。\n\n技术技能要求：\n熟练掌握 PyTorch/DeepSpeed 及主流大模型架构，深入理解 RAG、LTR 排序及 RLHF/DPO 算法。精通 Python/C++，具备优秀的底层算子优化或 KV Cache 优化能力，有大规模分布式训练及搜索性能调优经验者优先。\n\n软性素质要求：\n具备极强的逻辑思维与自驱动力，能够敏锐捕捉前沿技术并转化为业务落地。拥有出色的抗压能力与团队协作精神，能在复杂业务场景下保持沟通高效，对解决算法落地中的硬核挑战充满激情。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139073","sourceKey":"tencent","company":"腾讯","title":"元宝—基于大模型的搜索召回技术研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139073","duty":"课题背景：\nEmbedding 和表示学习是现代搜索召回的核心基础能力。随着 AI 搜索场景对语义理解、细粒度匹配和复杂意图建模的要求不断提高，传统单向量表示逐渐暴露出表达能力不足的问题。多向量、多粒度表示以及语义与关键词联合建模，成为提升召回能力的重要研究方向。\n\n课题挑战：\n1、单向量表达能力有限：面对复杂语义、组合条件和细粒度匹配需求，单一向量往往难以完整表征文本。\n2、多向量建模成本高：多向量虽然表达更强，但索引、存储、检索和在线服务成本显著增加。\n3、多粒度表示设计复杂：如何同时建模词级、句级、段落级甚至文档级语义，并实现有效协同，是关键问题。\n4、语义与关键词联合建模难：纯语义召回容易弱化精确约束，纯关键词召回又难覆盖深层语义，二者融合机制需要深入设计。\n5、训练样本构建难度大：高质量 query-doc 配对、难负样本、多任务监督信号的构造直接决定表示学习效果。\n\n具体工作：\n1、召回embedding模型训练优化：embedding模型优化，解决复杂语义、组合条件、细粒度需求下query-title/query-chunk的 embedding search问题；\n2、query纠错和改写优化：纠错召回和改写召回，通过query fan-out技术提升召回率。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、具备扎实的 信息检索 / 表示学习 / 大模型相关技术基础，熟悉向量检索、语义匹配、召回评估指标等核心问题；\n3、熟练使用主流深度学习及大模型的训练与推理框架，对 Transformer、Embedding 模型及其在搜索场景中的应用有深入理解；\n4、具备良好的分析与系统性解决问题能力，能够针对复杂业务场景设计、优化并落地召回算法与系统方案；\n5、在信息检索、自然语言处理、机器学习等相关领域顶会/期刊发表论文者优先。","description":"课题描述\n课题背景：\nEmbedding 和表示学习是现代搜索召回的核心基础能力。随着 AI 搜索场景对语义理解、细粒度匹配和复杂意图建模的要求不断提高，传统单向量表示逐渐暴露出表达能力不足的问题。多向量、多粒度表示以及语义与关键词联合建模，成为提升召回能力的重要研究方向。\n\n课题挑战：\n1、单向量表达能力有限：面对复杂语义、组合条件和细粒度匹配需求，单一向量往往难以完整表征文本。\n2、多向量建模成本高：多向量虽然表达更强，但索引、存储、检索和在线服务成本显著增加。\n3、多粒度表示设计复杂：如何同时建模词级、句级、段落级甚至文档级语义，并实现有效协同，是关键问题。\n4、语义与关键词联合建模难：纯语义召回容易弱化精确约束，纯关键词召回又难覆盖深层语义，二者融合机制需要深入设计。\n5、训练样本构建难度大：高质量 query-doc 配对、难负样本、多任务监督信号的构造直接决定表示学习效果。\n\n具体工作：\n1、召回embedding模型训练优化：embedding模型优化，解决复杂语义、组合条件、细粒度需求下query-title/query-chunk的 embedding search问题；\n2、query纠错和改写优化：纠错召回和改写召回，通过query fan-out技术提升召回率。\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、具备扎实的 信息检索 / 表示学习 / 大模型相关技术基础，熟悉向量检索、语义匹配、召回评估指标等核心问题；\n3、熟练使用主流深度学习及大模型的训练与推理框架，对 Transformer、Embedding 模型及其在搜索场景中的应用有深入理解；\n4、具备良好的分析与系统性解决问题能力，能够针对复杂业务场景设计、优化并落地召回算法与系统方案；\n5、在信息检索、自然语言处理、机器学习等相关领域顶会/期刊发表论文者优先。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139074","sourceKey":"tencent","company":"腾讯","title":"元宝—基于rubrics的网页set选取技术研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139074","duty":"课题背景：\n在RAG/Search Agent场景中，排序系统承担着为LLM供给基础物料、助力其生成可信赖回复的核心作用。但当前排序系统存在明显局限，其仅通过拟合rank label输出网页列表，在信息密度上表现不佳，具体体现为网页信息存在错误、冗余、冲突等问题，无法充分满足LLM对输入物料的高质量需求。与此同时，近期Rubrics RM的出现为LLM RL领域开辟了新的方向，这也为排序系统的优化提供了新的思路。\n\n课题挑战：\n要实现基于rubrics的网页Set选取，仍需攻克以下三项核心研究挑战：\n1、如何定义合理的search rubrics，并探索其自动化合成方法，确保rubrics能够精准匹配Query需求；\n2、如何基于rubrics对网页set RM进行科学、全面的评估，验证其选取效果；\n3、如何设计可行的网页set选取RL训练方案，保障排序系统能够稳定输出符合rubrics标准的网页集合。\n\n具体工作：\n1、基于rubrics的网页set选取模型训练优化：包括rubrics抽取、基于rubrics的reward model设计、RL训练等，优化排序效果\n2、基于answer的set选取模型训练优化：对齐answer好坏标准，通过answer的反馈信号（点赞、点踩、分享、重新生成等）和rubrics 对set选取模型RL训练，优化排序效果","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握计算机视觉和图像处理相关的基本算法及应用，熟悉Caffe、TensorFlow，PyTorch等至少一个深度学习框架；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。","description":"课题描述\n课题背景：\n在RAG/Search Agent场景中，排序系统承担着为LLM供给基础物料、助力其生成可信赖回复的核心作用。但当前排序系统存在明显局限，其仅通过拟合rank label输出网页列表，在信息密度上表现不佳，具体体现为网页信息存在错误、冗余、冲突等问题，无法充分满足LLM对输入物料的高质量需求。与此同时，近期Rubrics RM的出现为LLM RL领域开辟了新的方向，这也为排序系统的优化提供了新的思路。\n\n课题挑战：\n要实现基于rubrics的网页Set选取，仍需攻克以下三项核心研究挑战：\n1、如何定义合理的search rubrics，并探索其自动化合成方法，确保rubrics能够精准匹配Query需求；\n2、如何基于rubrics对网页set RM进行科学、全面的评估，验证其选取效果；\n3、如何设计可行的网页set选取RL训练方案，保障排序系统能够稳定输出符合rubrics标准的网页集合。\n\n具体工作：\n1、基于rubrics的网页set选取模型训练优化：包括rubrics抽取、基于rubrics的reward model设计、RL训练等，优化排序效果\n2、基于answer的set选取模型训练优化：对齐answer好坏标准，通过answer的反馈信号（点赞、点踩、分享、重新生成等）和rubrics 对set选取模型RL训练，优化排序效果\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握计算机视觉和图像处理相关的基本算法及应用，熟悉Caffe、TensorFlow，PyTorch等至少一个深度学习框架；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139075","sourceKey":"tencent","company":"腾讯","title":"元宝—面向全网搜索的多模态文档表征技术研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139075","duty":"课题背景：\n目前文档（doc）的建模工作主要以文字为核心开展表示学习，缺乏对视觉信息的利用；近期deepseek-ocr及其v2版本提出了通过视觉信息建模文档表征的思路，且该思路已在ocr相关场景中得到应用，为多模态文档表示研究提供了参考。\n\n课题挑战：\n如何合理利用视觉信息实现文档表示的有效压缩，兼顾信息捕获的完整性与表示的简洁性；如何将基于视觉的多模态文档表示顺利适配搜索ranking、rag生成等多样化下游场景，解决不同场景下的适配性问题，确保其能稳定发挥提升效果、降低耗时的作用。\n\n具体工作：\n1、doc的多模态表征技术研究：研究如何通过多模态模型，更好的表征图文网页的信息，更好的捕捉doc语义和结构\n2、基于多模态doc表征的ranking模型训练优化：研究如何利用多模态doc表征优化ranking效果，解决以往纯文本语义刻画不了图文信息导致的排序问题","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握计算机视觉和图像处理相关的基本算法及应用，熟悉Caffe、TensorFlow，PyTorch等至少一个深度学习框架；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。","description":"课题描述\n课题背景：\n目前文档（doc）的建模工作主要以文字为核心开展表示学习，缺乏对视觉信息的利用；近期deepseek-ocr及其v2版本提出了通过视觉信息建模文档表征的思路，且该思路已在ocr相关场景中得到应用，为多模态文档表示研究提供了参考。\n\n课题挑战：\n如何合理利用视觉信息实现文档表示的有效压缩，兼顾信息捕获的完整性与表示的简洁性；如何将基于视觉的多模态文档表示顺利适配搜索ranking、rag生成等多样化下游场景，解决不同场景下的适配性问题，确保其能稳定发挥提升效果、降低耗时的作用。\n\n具体工作：\n1、doc的多模态表征技术研究：研究如何通过多模态模型，更好的表征图文网页的信息，更好的捕捉doc语义和结构\n2、基于多模态doc表征的ranking模型训练优化：研究如何利用多模态doc表征优化ranking效果，解决以往纯文本语义刻画不了图文信息导致的排序问题\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握计算机视觉和图像处理相关的基本算法及应用，熟悉Caffe、TensorFlow，PyTorch等至少一个深度学习框架；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139076","sourceKey":"tencent","company":"腾讯","title":"元宝—基于多模态大模型的搜索关键技术研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139076","duty":"课题背景：\n多模态搜索面临跨模态语义鸿沟、检索效率与精度失衡、多轮多模态交互记忆缺失等核心难题。亟需攻克多模态信息的统一表征、高效检索与全链路协同优化技术，突破现有搜索系统在多模态场景下的能力瓶颈，满足用户在复杂知识问答、跨模态内容溯源、个性化多模交互等场景的高满意度需求。\n\n课题挑战：\n1、多模态统一表征与跨模态对齐\n攻克多模态的统一表征技术，优化图像/语音/视频编码器与模态适配器的结构设计，结合持续预训练/后训练等策略，破解跨模态语义鸿沟难题；探索多模态信息的层级化表征机制，提升细粒度语义的对齐精度等。\n2、多模态生成式检索\n突破基于大模型的多模态生成式检索技术，设计高效的生成式检索框架和算法，提升高质多模态内容的召回率与相关性、检索效率等；\n3、多模态搜索排序与多目标优化\n探索多模态场景下的大模型排序（VLM Ranking）核心技术，融合多模态内容的语义特征、质量特征与用户偏好特征等，研究Reasoning Ranking、多模态特征融合排序等方向；构建“精度-效率-用户满意度”等多目标优化框架，提升排序结果的鲁棒性与综合适配性；\n4、多轮多模态交互与全链路协同\n研究多轮对话中多模态历史信息的存储、检索与应用机制，实现用户个性化偏好的精准捕捉与动态适配；协同优化多模态查询改写、召回、排序、LLM总结全链路，解决各环节的任务对齐（Task Alignment）问题，提升多模态检索整体效果。\n\n具体工作：\n参与多模态Agent理解、跨模态表征、多模态检索能力和系统建设，突破现有搜索系统在多模态场景下的能力瓶颈，满足元宝用户在复杂知识问答、跨模态内容溯源、个性化多模交互等场景的高满意度需求。","requirements":"1、来自计算机、人工智能、自动化、电子信息或数学等相关专业的博士/硕士同学。在多模态大模型（VLM）、大语言模型（LLM）或视觉推理等领域有深厚学术背景或顶会（CVPR、ECCV、ICLR、ACL、NeurIPS等）第一作者论文发表经历者优先；\n2、掌握多模态表征、多模态理解、思维链（CoT）、强化学习（DPO/PPO）等算法及应用；熟练掌握计算机视觉和图像处理相关的基本算法及应用，精通 Python 语言，熟练掌握 PyTorch 等主流深度学习框架及大模型训练推理工具；\n3、具备卓越的自驱动力与逻辑拆解能力，能够从复杂现象中提炼科学问题；沟通协作能力强，拥有极佳的学术视野，能快速研读并复现前沿论文，对探索通用人工智能（AGI）具有强烈的热情。","description":"课题描述\n课题背景：\n多模态搜索面临跨模态语义鸿沟、检索效率与精度失衡、多轮多模态交互记忆缺失等核心难题。亟需攻克多模态信息的统一表征、高效检索与全链路协同优化技术，突破现有搜索系统在多模态场景下的能力瓶颈，满足用户在复杂知识问答、跨模态内容溯源、个性化多模交互等场景的高满意度需求。\n\n课题挑战：\n1、多模态统一表征与跨模态对齐\n攻克多模态的统一表征技术，优化图像/语音/视频编码器与模态适配器的结构设计，结合持续预训练/后训练等策略，破解跨模态语义鸿沟难题；探索多模态信息的层级化表征机制，提升细粒度语义的对齐精度等。\n2、多模态生成式检索\n突破基于大模型的多模态生成式检索技术，设计高效的生成式检索框架和算法，提升高质多模态内容的召回率与相关性、检索效率等；\n3、多模态搜索排序与多目标优化\n探索多模态场景下的大模型排序（VLM Ranking）核心技术，融合多模态内容的语义特征、质量特征与用户偏好特征等，研究Reasoning Ranking、多模态特征融合排序等方向；构建“精度-效率-用户满意度”等多目标优化框架，提升排序结果的鲁棒性与综合适配性；\n4、多轮多模态交互与全链路协同\n研究多轮对话中多模态历史信息的存储、检索与应用机制，实现用户个性化偏好的精准捕捉与动态适配；协同优化多模态查询改写、召回、排序、LLM总结全链路，解决各环节的任务对齐（Task Alignment）问题，提升多模态检索整体效果。\n\n具体工作：\n参与多模态Agent理解、跨模态表征、多模态检索能力和系统建设，突破现有搜索系统在多模态场景下的能力瓶颈，满足元宝用户在复杂知识问答、跨模态内容溯源、个性化多模交互等场景的高满意度需求。\n\n课题要求\n1、来自计算机、人工智能、自动化、电子信息或数学等相关专业的博士/硕士同学。在多模态大模型（VLM）、大语言模型（LLM）或视觉推理等领域有深厚学术背景或顶会（CVPR、ECCV、ICLR、ACL、NeurIPS等）第一作者论文发表经历者优先；\n2、掌握多模态表征、多模态理解、思维链（CoT）、强化学习（DPO/PPO）等算法及应用；熟练掌握计算机视觉和图像处理相关的基本算法及应用，精通 Python 语言，熟练掌握 PyTorch 等主流深度学习框架及大模型训练推理工具；\n3、具备卓越的自驱动力与逻辑拆解能力，能够从复杂现象中提炼科学问题；沟通协作能力强，拥有极佳的学术视野，能快速研读并复现前沿论文，对探索通用人工智能（AGI）具有强烈的热情。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139077","sourceKey":"tencent","company":"腾讯","title":"元宝—面向开放知识问答任务的生成式搜索关键技术研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139077","duty":"课题背景：\n大语言模型技术的突破和智能体的出现，催生了生成式搜索研究课题的兴起，智能体对搜索引擎的精度、响应速度、可控性提出了更高的要求，推动生成式搜索成为了关键研究方向。传统搜索技术受限于分层损失以及复杂的系统架构，在搜索效果和效率上都没有达到最佳状态。生成式搜索技术的出现，为解决这一问题提供了新的技术范式。\n\n课题挑战：\n1、实现海量资源下的端到端搜索，面临着检索精度与推理效率的双重挑战。当前的生成式搜索算法，受限于码本大小和序列长度，当面对海量文档库时，效果衰减明显。如何支撑海量文档库，同时保证对长尾文档的精准记忆，是极大的难点。而随着序列变长、搜索宽度加大，推理延迟又会明显增加。\n2、生成式搜索旨在实现端到端的搜索技术框架，并需要再训练阶段融合表征模型、向量量化、生成式模型各个阶段的训练，进行联合优化。这使得生成式搜索模型的训练过程具有很高的复杂度，在训练算法的设计和具体实现上都带来挑战。\n\n具体工作：\n1、文档表征：研究语义ID（Semantic DocID）设计，如何通过Codebook 算法或量化算法，将文档映射为具有语义信息的数字序列\n2、Gerative Joint Optimization: 设计融合了“生成损失”与“对比学习损失”的训练目标，让模型在学习生成 DocID 的同时，保持对文档向量空间的表征能力；联合文档排序目标，解码阶段联合引入 ranking loss对齐文档多目标偏序\n3、受限解码： 研究解码算法，例如前缀树（Trie Tree）搜索算法，确保模型生成的每一个 Token 都在合法的 DocID 集合中，缩减搜索空间。","requirements":"学历和专业要求：\n计算机、人工智能、NLP等方向相关专业的硕士或博士。在生成式搜索、自然语言处理（NLP）、信息检索（IR）等领域有深厚的学术积淀，在 SIGIR、KDD、NeurIPS、ACL 等国际顶会有高质量论文发表者优先。\n\n技术技能要求：\n精通 LLM、RAG、生成式搜索（DSI）及排序算法，模型微调（SFT）、强化学习（RLHF）及模型量化技术。熟练使用 Python/C++，精通 PyTorch 或 TensorFlow 框架，具备大规模分布式训练或高性能推理优化经验。\n\n软性素质要求：\n具备极强的逻辑思维与复杂问题拆解能力，沟通协作高效，能够胜任跨团队协同。对前沿技术有高度敏锐感和自驱力，抗压能力强，能适应高强度的技术攻关与业务快速迭代节奏。","description":"课题描述\n课题背景：\n大语言模型技术的突破和智能体的出现，催生了生成式搜索研究课题的兴起，智能体对搜索引擎的精度、响应速度、可控性提出了更高的要求，推动生成式搜索成为了关键研究方向。传统搜索技术受限于分层损失以及复杂的系统架构，在搜索效果和效率上都没有达到最佳状态。生成式搜索技术的出现，为解决这一问题提供了新的技术范式。\n\n课题挑战：\n1、实现海量资源下的端到端搜索，面临着检索精度与推理效率的双重挑战。当前的生成式搜索算法，受限于码本大小和序列长度，当面对海量文档库时，效果衰减明显。如何支撑海量文档库，同时保证对长尾文档的精准记忆，是极大的难点。而随着序列变长、搜索宽度加大，推理延迟又会明显增加。\n2、生成式搜索旨在实现端到端的搜索技术框架，并需要再训练阶段融合表征模型、向量量化、生成式模型各个阶段的训练，进行联合优化。这使得生成式搜索模型的训练过程具有很高的复杂度，在训练算法的设计和具体实现上都带来挑战。\n\n具体工作：\n1、文档表征：研究语义ID（Semantic DocID）设计，如何通过Codebook 算法或量化算法，将文档映射为具有语义信息的数字序列\n2、Gerative Joint Optimization: 设计融合了“生成损失”与“对比学习损失”的训练目标，让模型在学习生成 DocID 的同时，保持对文档向量空间的表征能力；联合文档排序目标，解码阶段联合引入 ranking loss对齐文档多目标偏序\n3、受限解码： 研究解码算法，例如前缀树（Trie Tree）搜索算法，确保模型生成的每一个 Token 都在合法的 DocID 集合中，缩减搜索空间。\n\n课题要求\n学历和专业要求：\n计算机、人工智能、NLP等方向相关专业的硕士或博士。在生成式搜索、自然语言处理（NLP）、信息检索（IR）等领域有深厚的学术积淀，在 SIGIR、KDD、NeurIPS、ACL 等国际顶会有高质量论文发表者优先。\n\n技术技能要求：\n精通 LLM、RAG、生成式搜索（DSI）及排序算法，模型微调（SFT）、强化学习（RLHF）及模型量化技术。熟练使用 Python/C++，精通 PyTorch 或 TensorFlow 框架，具备大规模分布式训练或高性能推理优化经验。\n\n软性素质要求：\n具备极强的逻辑思维与复杂问题拆解能力，沟通协作高效，能够胜任跨团队协同。对前沿技术有高度敏锐感和自驱力，抗压能力强，能适应高强度的技术攻关与业务快速迭代节奏。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139078","sourceKey":"tencent","company":"腾讯","title":"元宝—搜索大模型推理加速研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139078","duty":"课题背景：\n大规模搜索系统面临长序列建模、高计算开销与异构资源约束的挑战，传统稠密注意力模型在效率、存储及部署层面存在显著瓶颈，制约系统性能与扩展性。\n\n课题挑战：\n1、近线性注意力的语义保真：在实现O(n)的近似注意力计算时，需突破在长序列建模中的语义瓶颈，在降低计算负载的同时保持全局语义的建模能力，避免因近似计算导致的排序精度衰减。\n2、多约束的联合压缩优化：结构化稀疏、动态路由与非均匀量化形成了包含离散与连续变量的混合优化空间，需在精度、效率、鲁棒性的多重约束下建立联合优化范式，实现多维压缩目标间的平衡。\n3、异构算力的协同调度：混合硬件架构中，计算、通信、I/O等资源深度耦合。需建立统一的计算图分析与调度模型，突破异构分布式推理的性能边界，实现异构资源的性能突破。\n\n具体工作：\n1、高效推理注意力机制\n研究并设计高性能注意力机制（线性注意力、稀疏注意力），针对搜索长序列短输出场景定制算子，将计算复杂度从 O(n^2) 降至 O(n) ，在保障排序精度的前提下显著提升推理吞吐与响应速度。\n2、高精度结构化模型压缩\n构建融合结构化稀疏、动态路由与非均匀量化的联合压缩范式，以排序指标为约束优化模型体量，实现计算与存储的协同压缩，确保轻量化后精度无损。\n3、异构分布式推理架构\n设计混合并行策略与通信原语融合机制，优化跨节点传输与动态调度能力，打通从算子内核到集群的全栈链路，挖掘异构资源潜力以触达系统性能边界。","requirements":"学历和专业要求：\n计算机、人工智能、高性能计算或相关专业硕士及以上学历，博士优先。需具备扎实的深度学习理论基础，在高性能计算、编译器优化或大模型架构领域有深入研究背景。\n\n技术技能要求：\n精通PyTorch/TensorRT/vLLM等框架，熟练掌握CUDA编程与分布式训练推理技术。深入理解Transformer/SSM架构，拥有模型剪枝、量化及大规模搜索系统落地经验者优先。\n\n软性素质要求：\n具备极强的技术自驱力与系统架构思维，善于跨算法与系统工程边界协同攻关。拥有优秀的沟通协作能力，能在高并发、低延迟的生产环境下高效解决复杂工程难题。","description":"课题描述\n课题背景：\n大规模搜索系统面临长序列建模、高计算开销与异构资源约束的挑战，传统稠密注意力模型在效率、存储及部署层面存在显著瓶颈，制约系统性能与扩展性。\n\n课题挑战：\n1、近线性注意力的语义保真：在实现O(n)的近似注意力计算时，需突破在长序列建模中的语义瓶颈，在降低计算负载的同时保持全局语义的建模能力，避免因近似计算导致的排序精度衰减。\n2、多约束的联合压缩优化：结构化稀疏、动态路由与非均匀量化形成了包含离散与连续变量的混合优化空间，需在精度、效率、鲁棒性的多重约束下建立联合优化范式，实现多维压缩目标间的平衡。\n3、异构算力的协同调度：混合硬件架构中，计算、通信、I/O等资源深度耦合。需建立统一的计算图分析与调度模型，突破异构分布式推理的性能边界，实现异构资源的性能突破。\n\n具体工作：\n1、高效推理注意力机制\n研究并设计高性能注意力机制（线性注意力、稀疏注意力），针对搜索长序列短输出场景定制算子，将计算复杂度从 O(n^2) 降至 O(n) ，在保障排序精度的前提下显著提升推理吞吐与响应速度。\n2、高精度结构化模型压缩\n构建融合结构化稀疏、动态路由与非均匀量化的联合压缩范式，以排序指标为约束优化模型体量，实现计算与存储的协同压缩，确保轻量化后精度无损。\n3、异构分布式推理架构\n设计混合并行策略与通信原语融合机制，优化跨节点传输与动态调度能力，打通从算子内核到集群的全栈链路，挖掘异构资源潜力以触达系统性能边界。\n\n课题要求\n学历和专业要求：\n计算机、人工智能、高性能计算或相关专业硕士及以上学历，博士优先。需具备扎实的深度学习理论基础，在高性能计算、编译器优化或大模型架构领域有深入研究背景。\n\n技术技能要求：\n精通PyTorch/TensorRT/vLLM等框架，熟练掌握CUDA编程与分布式训练推理技术。深入理解Transformer/SSM架构，拥有模型剪枝、量化及大规模搜索系统落地经验者优先。\n\n软性素质要求：\n具备极强的技术自驱力与系统架构思维，善于跨算法与系统工程边界协同攻关。拥有优秀的沟通协作能力，能在高并发、低延迟的生产环境下高效解决复杂工程难题。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139079","sourceKey":"tencent","company":"腾讯","title":"元宝—面向真实复杂任务的全栈VLM Agent研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139079","duty":"课题背景：\n在 AI 迈向通用智能体的进程中，仅具备“文本理解”能力的模型已无法满足日益复杂的数字化生存需求。传统 Agent 往往局限于单一的 API 调用或特定的软件环境，难以像人类专家一样跨越浏览器、代码工具与底层文件系统进行协同办公。随着 VLM（视觉语言模型）的成熟，技术路径正在从“解析后台代码”转向“理解原始像素”。面对复杂、动态且非标的数字化环境，亟需构建一个具备全栈操作能力的 VLM Agent，打通从“视觉感知”到“真实执行”的闭环，解决真实世界中的长链路问题。\n\n课题挑战：\n要实现高可靠的数字化 Agent，我们需要在工程与算法层面解决以下实际难题：\n跨模态动作生成的精度：重点在于如何将 VLM 提取的模糊视觉意图，精准转化为像素级的鼠标点击或结构化的 Bash 命令，减少执行时的“误触”与“偏移”。\n长时程任务的错误恢复：在涉及浏览器与系统多步交互的长流程中，如何有效识别环境反馈中的报错（如网页加载失败、指令权限不足），并具备自主重试或路径修正的能力。\n异构工具链的协同决策：研究如何让模型在“视觉感知”与“系统反馈”双重信号下，理性判断何时该用浏览器搜索，何时该用代码计算，确保跨工具调用逻辑的连贯性。\n\n具体工作：\n构建跨工具真实长链评估集，研发具备 UI 感知与 CoT 对齐能力的高精度 VLM，并引入推理侧经验回放机制，通过在线总结与召回实现无需训练的即时纠错，全面提升 Agent 在复杂环境下的意图理解与多工具协同执行效率。","requirements":"学历和专业要求：\n来自计算机、人工智能、自动化、电子信息或数学等相关专业的博士/硕士同学。在多模态大模型（VLM）、智能体（Agent）或视觉推理等领域有深厚学术背景或顶会（CVPR、ICLR、NeurIPS等）论文发表经历者优先。\n\n技术技能要求：\n掌握多模态表征、思维链（CoT）、强化学习（DPO/PPO）等算法及应用；熟悉 GUI 自动化或代码驱动的视觉处理技术。精通 Python 语言，熟练掌握 PyTorch 等主流深度学习框架及大模型训练推理工具。\n\n软性素质要求：\n具备卓越的自驱动力与逻辑拆解能力，能够从复杂现象中提炼科学问题；沟通协作能力强，拥有极佳的学术视野，能快速研读并复现前沿论文，对探索通用人工智能（AGI）具有强烈的热情。","description":"课题描述\n课题背景：\n在 AI 迈向通用智能体的进程中，仅具备“文本理解”能力的模型已无法满足日益复杂的数字化生存需求。传统 Agent 往往局限于单一的 API 调用或特定的软件环境，难以像人类专家一样跨越浏览器、代码工具与底层文件系统进行协同办公。随着 VLM（视觉语言模型）的成熟，技术路径正在从“解析后台代码”转向“理解原始像素”。面对复杂、动态且非标的数字化环境，亟需构建一个具备全栈操作能力的 VLM Agent，打通从“视觉感知”到“真实执行”的闭环，解决真实世界中的长链路问题。\n\n课题挑战：\n要实现高可靠的数字化 Agent，我们需要在工程与算法层面解决以下实际难题：\n跨模态动作生成的精度：重点在于如何将 VLM 提取的模糊视觉意图，精准转化为像素级的鼠标点击或结构化的 Bash 命令，减少执行时的“误触”与“偏移”。\n长时程任务的错误恢复：在涉及浏览器与系统多步交互的长流程中，如何有效识别环境反馈中的报错（如网页加载失败、指令权限不足），并具备自主重试或路径修正的能力。\n异构工具链的协同决策：研究如何让模型在“视觉感知”与“系统反馈”双重信号下，理性判断何时该用浏览器搜索，何时该用代码计算，确保跨工具调用逻辑的连贯性。\n\n具体工作：\n构建跨工具真实长链评估集，研发具备 UI 感知与 CoT 对齐能力的高精度 VLM，并引入推理侧经验回放机制，通过在线总结与召回实现无需训练的即时纠错，全面提升 Agent 在复杂环境下的意图理解与多工具协同执行效率。\n\n课题要求\n学历和专业要求：\n来自计算机、人工智能、自动化、电子信息或数学等相关专业的博士/硕士同学。在多模态大模型（VLM）、智能体（Agent）或视觉推理等领域有深厚学术背景或顶会（CVPR、ICLR、NeurIPS等）论文发表经历者优先。\n\n技术技能要求：\n掌握多模态表征、思维链（CoT）、强化学习（DPO/PPO）等算法及应用；熟悉 GUI 自动化或代码驱动的视觉处理技术。精通 Python 语言，熟练掌握 PyTorch 等主流深度学习框架及大模型训练推理工具。\n\n软性素质要求：\n具备卓越的自驱动力与逻辑拆解能力，能够从复杂现象中提炼科学问题；沟通协作能力强，拥有极佳的学术视野，能快速研读并复现前沿论文，对探索通用人工智能（AGI）具有强烈的热情。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139080","sourceKey":"tencent","company":"腾讯","title":"元宝—基于视觉思维链的深层逻辑推理VQA框架研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139080","duty":"课题背景：\n在 AI 迈向强人工智能的进程中，视觉问答（VQA）正从“直觉式描述”转向“逻辑式推演”。现有的 VQA 模型往往倾向于根据图像全局特征直接给出预测，这种“一步位”的模式在面对需要多步空间变换、隐喻理解或因果分析的复杂问题时，极易产生逻辑断层。随着 VLM 基础能力的跃迁，技术路径正在从“端到端预测”转向“Think with Images”式的启发式推理。面对高复杂度、高逻辑要求的视觉任务，亟需构建一个具备视觉思维链能力的 VQA 框架，打通“局部观测-中间推论-全局结论”的思考链路，解决视觉推理过程中的不可解释性难题。\n\n课题挑战：\n要实现具备“思维链”的高可靠 VQA，我们需要在模型推理质量与逻辑闭环层面解决以下实际难题：\n视觉中间态的稳定性：重点在于如何确保模型在利用代码工具进行“Think with Images”的过程中，生成的中间图像或视觉表征不发生语义偏移，避免推理路径因图像处理不当而“跑题”。\n多维空间感知与心理旋转：挑战模型在处理复杂 3D 转换或遮挡关系时的思维能力，确保模型在主动调整视角的推演过程中，具备精准的空间守恒性与物理常识约束。\n逻辑坍塌的自我纠偏：研究如何建立视觉思维的反馈评价机制，当 Agent 意识到基于调整后图像得出的中间结论与原始全局信息发生矛盾时，能够像人类一样进行“回溯重思考”，确保最终答案的严谨性。\n\n具体工作：\n构建含空间与物理推演的复杂 VQA 评估集，研发代码驱动的感知增强模型，并引入推理侧回溯纠偏机制，通过语义一致性检验实现逻辑矛盾时的自主路径重构，提升 VLM 在复杂时空约束下的推演深度、空间守恒性与逻辑严谨性。","requirements":"学历和专业要求：\n来自计算机、人工智能、数学或自动化相关专业的博士/硕士同学。深耕视觉问答（VQA）、多模态逻辑推理或计算机视觉（CV）领域，在顶会（CVPR、ICCV、NeurIPS等）有高水平论文发表经历者优先。\n\n技术技能要求：\n掌握多模态推理、视觉逻辑建模、3D 空间几何变换等算法；熟悉 VLM 思维链（CoT）及代码驱动的图像处理算子调用。精通 Python 语言，熟练使用 PyTorch 等主流框架及大模型训练推理工具。\n\n软性素质要求：\n具备极强的逻辑推演与空间想象力，能敏锐发现并解决模型推理中的逻辑断层。沟通协作能力强，具备独立开展前沿课题研究的韧性，对探索具备人类水平逻辑的可解释视觉智能有浓厚兴趣。","description":"课题描述\n课题背景：\n在 AI 迈向强人工智能的进程中，视觉问答（VQA）正从“直觉式描述”转向“逻辑式推演”。现有的 VQA 模型往往倾向于根据图像全局特征直接给出预测，这种“一步位”的模式在面对需要多步空间变换、隐喻理解或因果分析的复杂问题时，极易产生逻辑断层。随着 VLM 基础能力的跃迁，技术路径正在从“端到端预测”转向“Think with Images”式的启发式推理。面对高复杂度、高逻辑要求的视觉任务，亟需构建一个具备视觉思维链能力的 VQA 框架，打通“局部观测-中间推论-全局结论”的思考链路，解决视觉推理过程中的不可解释性难题。\n\n课题挑战：\n要实现具备“思维链”的高可靠 VQA，我们需要在模型推理质量与逻辑闭环层面解决以下实际难题：\n视觉中间态的稳定性：重点在于如何确保模型在利用代码工具进行“Think with Images”的过程中，生成的中间图像或视觉表征不发生语义偏移，避免推理路径因图像处理不当而“跑题”。\n多维空间感知与心理旋转：挑战模型在处理复杂 3D 转换或遮挡关系时的思维能力，确保模型在主动调整视角的推演过程中，具备精准的空间守恒性与物理常识约束。\n逻辑坍塌的自我纠偏：研究如何建立视觉思维的反馈评价机制，当 Agent 意识到基于调整后图像得出的中间结论与原始全局信息发生矛盾时，能够像人类一样进行“回溯重思考”，确保最终答案的严谨性。\n\n具体工作：\n构建含空间与物理推演的复杂 VQA 评估集，研发代码驱动的感知增强模型，并引入推理侧回溯纠偏机制，通过语义一致性检验实现逻辑矛盾时的自主路径重构，提升 VLM 在复杂时空约束下的推演深度、空间守恒性与逻辑严谨性。\n\n课题要求\n学历和专业要求：\n来自计算机、人工智能、数学或自动化相关专业的博士/硕士同学。深耕视觉问答（VQA）、多模态逻辑推理或计算机视觉（CV）领域，在顶会（CVPR、ICCV、NeurIPS等）有高水平论文发表经历者优先。\n\n技术技能要求：\n掌握多模态推理、视觉逻辑建模、3D 空间几何变换等算法；熟悉 VLM 思维链（CoT）及代码驱动的图像处理算子调用。精通 Python 语言，熟练使用 PyTorch 等主流框架及大模型训练推理工具。\n\n软性素质要求：\n具备极强的逻辑推演与空间想象力，能敏锐发现并解决模型推理中的逻辑断层。沟通协作能力强，具备独立开展前沿课题研究的韧性，对探索具备人类水平逻辑的可解释视觉智能有浓厚兴趣。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139081","sourceKey":"tencent","company":"腾讯","title":"量子神经网络设计与性质研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139081","duty":"课题背景：\n量子神经网络（QNN）是量子计算与机器学习两个前沿领域的交叉产物，在近期NISQ时代及远期量子AI中都发挥着至关重要的作用。对于大量经典计算难以解决的问题，如分子模拟、组合优化、机器学习等方向，QNN具有量子加速的潜力。深入探索QNN的性质有利于发现新的量子算法，以及量子算法在近期量子设备上实现，从而加速量子算法落地。研究成果将助力优化QNN的架构设计与训练策略，推动QNN从“理论潜力”向“实用价值”的实质性跨越，对实现可实用量子算法具有重要的理论意义与现实推动作用。\n\n课题挑战：\n当前对量子神经网络的研究仍缺乏体系化的数学工具支撑，其性质与行为受到量子纠缠、噪声、电路结构等多重因素的复杂影响。\n\n具体工作：\n本课题旨在结合严格的数学理论及不断发展的强大AI工具，观察QNN训练中的规律，以及刻画QNN性质与行为机理。","requirements":"1、包含但不限于计算机、量子信息、物理学、人工智能、自动化、数学、统计学等专业的博士和优秀硕士；\n2、在量子算法及机器学习方向具有强烈的研究和实践兴趣和经验。","description":"课题描述\n课题背景：\n量子神经网络（QNN）是量子计算与机器学习两个前沿领域的交叉产物，在近期NISQ时代及远期量子AI中都发挥着至关重要的作用。对于大量经典计算难以解决的问题，如分子模拟、组合优化、机器学习等方向，QNN具有量子加速的潜力。深入探索QNN的性质有利于发现新的量子算法，以及量子算法在近期量子设备上实现，从而加速量子算法落地。研究成果将助力优化QNN的架构设计与训练策略，推动QNN从“理论潜力”向“实用价值”的实质性跨越，对实现可实用量子算法具有重要的理论意义与现实推动作用。\n\n课题挑战：\n当前对量子神经网络的研究仍缺乏体系化的数学工具支撑，其性质与行为受到量子纠缠、噪声、电路结构等多重因素的复杂影响。\n\n具体工作：\n本课题旨在结合严格的数学理论及不断发展的强大AI工具，观察QNN训练中的规律，以及刻画QNN性质与行为机理。\n\n课题要求\n1、包含但不限于计算机、量子信息、物理学、人工智能、自动化、数学、统计学等专业的博士和优秀硕士；\n2、在量子算法及机器学习方向具有强烈的研究和实践兴趣和经验。\n\nCSIG\n云与智慧产业事业群\n\n量子实验室\n腾讯量子实验室作为腾讯科技实验室矩阵的重要一员，依托公司在前沿科技领域的长期投入与战略布局，致力于打造面向未来的基础科研引擎。量子实验室由量子计算领域杰出科学家、原香港中文大学终身教授张胜誉领衔，聚焦量子算法、量子电路设计、量子模拟、量子AI等前沿方向，开展系统性理论研究与技术攻关，着力构建覆盖软件、算法与硬件协同的全栈能力体系；并与腾讯内部业务、学术界及产业界开展广泛合作，积极探索量子计算在药物发现、材料科学等领域的产业应用与价值落地。团队汇聚了来自全球顶尖高校与研究机构的人才，我们诚邀具备探索精神与专业能力的同行者加入，一起推进基础科技，探索行业价值！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139082","sourceKey":"tencent","company":"腾讯","title":"量子电路优化研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139082","duty":"课题背景：\n量子算法在特定重要问题上具有超越经典计算的潜力。然而，从理论算法到物理实现之间存在显著障碍。尽管量子硬件的比特数量持续增长，但现有NISQ设备仍面临高错误率与高噪声敏感性的局限，下一步纠错容错也受T门数量的影响。在此背景下，量子电路优化成为连接算法理论与物理实现的关键桥梁。其核心目标是在不改变目标计算任务的前提下，通过优化其电路的资源开销，降低噪声累积效应和纠错容错开销，从而提升计算的可靠性与执行效率。\n\n课题挑战：\n1、现有量子电路优化算法存在固定的优化框架，难以在此基础上继续改进。\n2、缺乏不同量子电路模型下的量子资源下界证明工具，从而难以衡量算法的优势。\n\n具体工作：\n针对特定/一般的有意义的计算问题，在不同的量子电路模型下设计其量子算法，优化其资源开销（电路大小、深度、T门数/深度、辅助比特数量等）。并探索从理论上证明资源开销的下界。","requirements":"1、包含但不限于计算机、量子信息、物理学、人工智能、自动化、数学、统计学等专业的博士和优秀硕士；\n2、对量子算法及量子电路优化方向具有强烈的研究和实践兴趣和经验。","description":"课题描述\n课题背景：\n量子算法在特定重要问题上具有超越经典计算的潜力。然而，从理论算法到物理实现之间存在显著障碍。尽管量子硬件的比特数量持续增长，但现有NISQ设备仍面临高错误率与高噪声敏感性的局限，下一步纠错容错也受T门数量的影响。在此背景下，量子电路优化成为连接算法理论与物理实现的关键桥梁。其核心目标是在不改变目标计算任务的前提下，通过优化其电路的资源开销，降低噪声累积效应和纠错容错开销，从而提升计算的可靠性与执行效率。\n\n课题挑战：\n1、现有量子电路优化算法存在固定的优化框架，难以在此基础上继续改进。\n2、缺乏不同量子电路模型下的量子资源下界证明工具，从而难以衡量算法的优势。\n\n具体工作：\n针对特定/一般的有意义的计算问题，在不同的量子电路模型下设计其量子算法，优化其资源开销（电路大小、深度、T门数/深度、辅助比特数量等）。并探索从理论上证明资源开销的下界。\n\n课题要求\n1、包含但不限于计算机、量子信息、物理学、人工智能、自动化、数学、统计学等专业的博士和优秀硕士；\n2、对量子算法及量子电路优化方向具有强烈的研究和实践兴趣和经验。\n\nCSIG\n云与智慧产业事业群\n\n量子实验室\n腾讯量子实验室作为腾讯科技实验室矩阵的重要一员，依托公司在前沿科技领域的长期投入与战略布局，致力于打造面向未来的基础科研引擎。量子实验室由量子计算领域杰出科学家、原香港中文大学终身教授张胜誉领衔，聚焦量子算法、量子电路设计、量子模拟、量子AI等前沿方向，开展系统性理论研究与技术攻关，着力构建覆盖软件、算法与硬件协同的全栈能力体系；并与腾讯内部业务、学术界及产业界开展广泛合作，积极探索量子计算在药物发现、材料科学等领域的产业应用与价值落地。团队汇聚了来自全球顶尖高校与研究机构的人才，我们诚邀具备探索精神与专业能力的同行者加入，一起推进基础科技，探索行业价值！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139083","sourceKey":"tencent","company":"腾讯","title":"量子计算软硬件系统实现","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139083","duty":"课题背景：\n本课题聚焦于超导量子计算机软硬件系统的工程实现与整体性能提升。当前，超导量子计算技术正从含噪声的中等规模量子（NISQ）时代向未来容错量子计算迈进，本课题的研究将致力于：1. 持续增强量子计算的相干性能和规模，提升计算系统整体性能；2. 探索量子错误缓解与量子纠错容错的具体实验实践，以有效抑制噪声影响，提升计算保真度与算法运行的可靠性，为推进实用化量子计算奠定基础。\n\n课题挑战：\n量子计算性能的提升是巨大的工程挑战。\n\n具体工作：\n1、超导量子计算的EDA辅助设计软件开发\n2、超导量子计算器件的设计和制造\n3、应用于量子纠错的反馈控制系统开发\n4、探索适用于超导量子计算机的量子错误缓解方案","requirements":"1、包含但不限于计算机、量子信息、电子工程、物理学、人工智能、自动化、数学、统计学等专业的博士和优秀硕士；\n2、对超导量子计算机有着强烈研究和实践兴趣。","description":"课题描述\n课题背景：\n本课题聚焦于超导量子计算机软硬件系统的工程实现与整体性能提升。当前，超导量子计算技术正从含噪声的中等规模量子（NISQ）时代向未来容错量子计算迈进，本课题的研究将致力于：1. 持续增强量子计算的相干性能和规模，提升计算系统整体性能；2. 探索量子错误缓解与量子纠错容错的具体实验实践，以有效抑制噪声影响，提升计算保真度与算法运行的可靠性，为推进实用化量子计算奠定基础。\n\n课题挑战：\n量子计算性能的提升是巨大的工程挑战。\n\n具体工作：\n1、超导量子计算的EDA辅助设计软件开发\n2、超导量子计算器件的设计和制造\n3、应用于量子纠错的反馈控制系统开发\n4、探索适用于超导量子计算机的量子错误缓解方案\n\n课题要求\n1、包含但不限于计算机、量子信息、电子工程、物理学、人工智能、自动化、数学、统计学等专业的博士和优秀硕士；\n2、对超导量子计算机有着强烈研究和实践兴趣。\n\nCSIG\n云与智慧产业事业群\n\n量子实验室\n腾讯量子实验室作为腾讯科技实验室矩阵的重要一员，依托公司在前沿科技领域的长期投入与战略布局，致力于打造面向未来的基础科研引擎。量子实验室由量子计算领域杰出科学家、原香港中文大学终身教授张胜誉领衔，聚焦量子算法、量子电路设计、量子模拟、量子AI等前沿方向，开展系统性理论研究与技术攻关，着力构建覆盖软件、算法与硬件协同的全栈能力体系；并与腾讯内部业务、学术界及产业界开展广泛合作，积极探索量子计算在药物发现、材料科学等领域的产业应用与价值落地。团队汇聚了来自全球顶尖高校与研究机构的人才，我们诚邀具备探索精神与专业能力的同行者加入，一起推进基础科技，探索行业价值！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139090","sourceKey":"tencent","company":"腾讯","title":"腾讯会议—语音理解大模型方向研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139090","duty":"课题背景：\n会议内容理解是一项艰巨的课题，难点主要在于超长音频，超长上下文，多说话人，多距离，多语种，多方言，多轮，连续语流，还需要利用会议中出现的各类视觉，文本多模态信息，辅助音频理解达到理想的效果。\n\n课题挑战：\n会议是一个连续，长时音频输入，又涉及多人对话，远场场景，还有文档分享这些外部输入源。本研究旨在研发超长音频，超长上下文，多说话人，连续语流场景下，全面理解会议内容的大模型方案；更好的识别会议内容(semantic info)和富信息（paralinguistic info）。与此同时，如何更好的利用会议进行时的实时in context learning：充分利用会议的会前文档，会中屏幕文档共享，会议历史信息，提升模型的输出质量，最后，研发会议reward model，通过和参会用户不断的交互，建立价值体系，在交互中不断提升模型的能力。\n\n具体工作：\n本职位承接腾讯会议实时字幕，会后流式和离线纪要，上传文件，录音笔，实时和离线多语种语音内容理解等工作。在当前已有模型下，需要进一步提升内容识别和理解质量，这里就需要针对会议的特点，从长度和内容的丰富度上，研发超长音频，超长上下文，多说话人，多语种，多方言，多轮，连续语流场景下，全面理解会议内容的大模型方案；同时，从可利用的信息上，充分利用会中会外各类多媒体信息，通过和用户不断的交互，提升会议场景内容理解的质量。","requirements":"1、具有语音识别、说话人识别等方向的研究经验；\n2、具备一定的LLM理论基础和调优实践经验；\n3、熟悉端到端语音大模型的训练和调优技术；\n4、在Interspeech、ICASSP等会议中投稿者优先。","description":"课题描述\n课题背景：\n会议内容理解是一项艰巨的课题，难点主要在于超长音频，超长上下文，多说话人，多距离，多语种，多方言，多轮，连续语流，还需要利用会议中出现的各类视觉，文本多模态信息，辅助音频理解达到理想的效果。\n\n课题挑战：\n会议是一个连续，长时音频输入，又涉及多人对话，远场场景，还有文档分享这些外部输入源。本研究旨在研发超长音频，超长上下文，多说话人，连续语流场景下，全面理解会议内容的大模型方案；更好的识别会议内容(semantic info)和富信息（paralinguistic info）。与此同时，如何更好的利用会议进行时的实时in context learning：充分利用会议的会前文档，会中屏幕文档共享，会议历史信息，提升模型的输出质量，最后，研发会议reward model，通过和参会用户不断的交互，建立价值体系，在交互中不断提升模型的能力。\n\n具体工作：\n本职位承接腾讯会议实时字幕，会后流式和离线纪要，上传文件，录音笔，实时和离线多语种语音内容理解等工作。在当前已有模型下，需要进一步提升内容识别和理解质量，这里就需要针对会议的特点，从长度和内容的丰富度上，研发超长音频，超长上下文，多说话人，多语种，多方言，多轮，连续语流场景下，全面理解会议内容的大模型方案；同时，从可利用的信息上，充分利用会中会外各类多媒体信息，通过和用户不断的交互，提升会议场景内容理解的质量。\n\n课题要求\n1、具有语音识别、说话人识别等方向的研究经验；\n2、具备一定的LLM理论基础和调优实践经验；\n3、熟悉端到端语音大模型的训练和调优技术；\n4、在Interspeech、ICASSP等会议中投稿者优先。\n\nCSIG\n云与智慧产业事业群\n\n腾讯会议\n腾讯会议是腾讯云旗下的一站式音视频协作平台，依托腾讯20余年音视频技术积累，提供高清流畅、安全可靠的会议体验，支持跨企业/跨区域高效协作，服务覆盖全球220+国家地区，累计服务超4亿用户。核心产品包括视频会议、Rooms会议室解决方案等。产品诸多AI能力获得了广大用户的认可，如元宝实时总结纪要、还原真实氛围，AI托管实现分身有术、关键会议永远在场等，近1年AI功能用户量同比增长150%+。现在腾讯会议已成为各行业500强及广大企业的首选协作工具。加入我们，一起打造AI时代极致的会议体验！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139091","sourceKey":"tencent","company":"腾讯","title":"腾讯会议—语音大模型方向研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139091","duty":"课题背景：\n近年来， 端到端语音对话大模型在智能客服、虚拟人交互、辅助诊疗等领域得到广泛应用，其具备低延迟、丰富副语言信息等优点，但模型智商的维持仍面临较大挑战。\n\n课题挑战：\n本课题研究聚焦模态对齐、跨模态语义迁移、动态融合推理等关键问题，通过自监督学习、专家混合机制等技术提升模型对复杂场景的适配能力。其核心目标是让智能系统精准捕捉多模态信息中的情感倾向与语义关联，实现更贴近人类交互习惯的自然对话。\n\n具体工作：\n参与语音大模型的全流程研发，包括跨模态对齐、多模态理解及生成，涵盖文本和语音等训练数据的清洗和制作、基础模型算法选型与优化，聚焦预训练、监督微调及强化学习等关键环节的技术迭代； 提高在远场、低信噪比、多人、音乐等场景下的理解及生成效果，改善模型在方言、副语言信息等方面的理解能力，加强情感对话能力。","requirements":"1、具有语音对话、语音识别、语音合成、语音翻译、语音合成转换、说话人识别等方向的研究经验；\n2、掌握端到端多模态大模型的训练和调优技术；\n3、熟悉实时对话模型的流式处理实现方案和多种模态之间对齐的技术实现；\n4、掌握改善模型遵循复杂指令能力的技术。","description":"课题描述\n课题背景：\n近年来， 端到端语音对话大模型在智能客服、虚拟人交互、辅助诊疗等领域得到广泛应用，其具备低延迟、丰富副语言信息等优点，但模型智商的维持仍面临较大挑战。\n\n课题挑战：\n本课题研究聚焦模态对齐、跨模态语义迁移、动态融合推理等关键问题，通过自监督学习、专家混合机制等技术提升模型对复杂场景的适配能力。其核心目标是让智能系统精准捕捉多模态信息中的情感倾向与语义关联，实现更贴近人类交互习惯的自然对话。\n\n具体工作：\n参与语音大模型的全流程研发，包括跨模态对齐、多模态理解及生成，涵盖文本和语音等训练数据的清洗和制作、基础模型算法选型与优化，聚焦预训练、监督微调及强化学习等关键环节的技术迭代； 提高在远场、低信噪比、多人、音乐等场景下的理解及生成效果，改善模型在方言、副语言信息等方面的理解能力，加强情感对话能力。\n\n课题要求\n1、具有语音对话、语音识别、语音合成、语音翻译、语音合成转换、说话人识别等方向的研究经验；\n2、掌握端到端多模态大模型的训练和调优技术；\n3、熟悉实时对话模型的流式处理实现方案和多种模态之间对齐的技术实现；\n4、掌握改善模型遵循复杂指令能力的技术。\n\nCSIG\n云与智慧产业事业群\n\n腾讯会议\n腾讯会议是腾讯云旗下的一站式音视频协作平台，依托腾讯20余年音视频技术积累，提供高清流畅、安全可靠的会议体验，支持跨企业/跨区域高效协作，服务覆盖全球220+国家地区，累计服务超4亿用户。核心产品包括视频会议、Rooms会议室解决方案等。产品诸多AI能力获得了广大用户的认可，如元宝实时总结纪要、还原真实氛围，AI托管实现分身有术、关键会议永远在场等，近1年AI功能用户量同比增长150%+。现在腾讯会议已成为各行业500强及广大企业的首选协作工具。加入我们，一起打造AI时代极致的会议体验！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139092","sourceKey":"tencent","company":"腾讯","title":"元宝—语音同传大模型方向研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139092","duty":"课题背景：\n随着全球化沟通的发展需要，语言障碍一直是国际会议、商务谈判和学术交流等场景的挑战。语音同传技术正是为了打破这一语言障碍获得了快速的发展。从传统的级联技术方案到现阶段的端到端语音方案。另外近年来伴随大模型技术的快速发展，语音结合大模型的端到端技术方案也在不断的探索往前发展，本项目为了实现基于LLM的端到端语音同传技术，攻克同传模型中流式和同声等技术难点，最终实现低延时、高质量翻译和保留说话人音色等功能。\n\n课题挑战：\n1、实现低延时的同时保证翻译的质量，如何设计模型或者通过RL算法来动态决策听和译的时机权衡。\n2、复杂场景下的翻译问题，如背景音、回声、混响、多人说话，口音和方言等复杂场景翻译问题。\n3、专有名词和时新词的翻译准确性，如何利用context和RAG技术引入外部知识。\n4、跨语种的翻译过程中翻译语序和源语言语音情感保留。\n\n具体工作：\n将参与端到端语音同传大模型的模型架构设计，预训练数据的清洗和基模的训练，context和RAG技术能力的建设，奖励函数和强化学习算法的研究，提升端到端语音同传大模型的效果。","requirements":"1、具有端到端语音建模、语音翻译、语音理解、语音合成转换、说话人识别等方向的研究经验；\n2、具备一定的LLM理论基础和调优实践经验；\n3、熟悉端到端语音大模型的训练和调优技术；\n4、在Interspeech、ICASSP等会议中投稿者优先。","description":"课题描述\n课题背景：\n随着全球化沟通的发展需要，语言障碍一直是国际会议、商务谈判和学术交流等场景的挑战。语音同传技术正是为了打破这一语言障碍获得了快速的发展。从传统的级联技术方案到现阶段的端到端语音方案。另外近年来伴随大模型技术的快速发展，语音结合大模型的端到端技术方案也在不断的探索往前发展，本项目为了实现基于LLM的端到端语音同传技术，攻克同传模型中流式和同声等技术难点，最终实现低延时、高质量翻译和保留说话人音色等功能。\n\n课题挑战：\n1、实现低延时的同时保证翻译的质量，如何设计模型或者通过RL算法来动态决策听和译的时机权衡。\n2、复杂场景下的翻译问题，如背景音、回声、混响、多人说话，口音和方言等复杂场景翻译问题。\n3、专有名词和时新词的翻译准确性，如何利用context和RAG技术引入外部知识。\n4、跨语种的翻译过程中翻译语序和源语言语音情感保留。\n\n具体工作：\n将参与端到端语音同传大模型的模型架构设计，预训练数据的清洗和基模的训练，context和RAG技术能力的建设，奖励函数和强化学习算法的研究，提升端到端语音同传大模型的效果。\n\n课题要求\n1、具有端到端语音建模、语音翻译、语音理解、语音合成转换、说话人识别等方向的研究经验；\n2、具备一定的LLM理论基础和调优实践经验；\n3、熟悉端到端语音大模型的训练和调优技术；\n4、在Interspeech、ICASSP等会议中投稿者优先。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139093","sourceKey":"tencent","company":"腾讯","title":"元宝—语音生成大模型方向研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139093","duty":"课题背景：\n语音交互在元宝产品交互中扮演重要的角色，为了打造极致的用户交互体验，需要研发基于大模型的端到端语音生成技术，优化语音的自然度和流畅性。通过更先进的端到端语音大模型，使合成的语音将更加接近人类的真实语音。另外还需支持更多的语言和方言，使得不同语言背景的用户都能够享受到高质量的语音服务。未来的语音合成技术将允许用户进行个性化定制，用户可以根据自己的喜好选择合成语音的音色、语速和情感，从而提升用户体验。\n\n课题挑战：\n1、根据语义内容来推理生成相对应场景语音的风格和情感。\n2、多人对话语音生成，解决交替说话过程中语气正常切换问题。\n3、基于LLM的TTS模型幻觉问题，如错读和漏读等问题。\n4、通过文本指令精准控制语音生成的风格，情感等。\n5、设计RL算法同时保证生成语音的准确性和情感化。\n6、多方言和多语种如何构建统一的语音生成大模型。\n\n具体工作：\n将参与语音生成大模型架构设计，预训练数据的清洗和基模的训练，tokenizer的设计和训练，instruct语音生成数据建设和算法优化，speech reward模型的建设和强化学习算法的研究，探索基于连续语音表征的技术方案，提升语音生成大模型的效果。","requirements":"1、具有语音合成、语音转换等方向的研究经验；\n2、具备一定的LLM理论基础和调优实践经验；\n3、熟悉语音大模型的训练和调优技术；\n4、在Interspeech、ICASSP等会议中投稿者优先。","description":"课题描述\n课题背景：\n语音交互在元宝产品交互中扮演重要的角色，为了打造极致的用户交互体验，需要研发基于大模型的端到端语音生成技术，优化语音的自然度和流畅性。通过更先进的端到端语音大模型，使合成的语音将更加接近人类的真实语音。另外还需支持更多的语言和方言，使得不同语言背景的用户都能够享受到高质量的语音服务。未来的语音合成技术将允许用户进行个性化定制，用户可以根据自己的喜好选择合成语音的音色、语速和情感，从而提升用户体验。\n\n课题挑战：\n1、根据语义内容来推理生成相对应场景语音的风格和情感。\n2、多人对话语音生成，解决交替说话过程中语气正常切换问题。\n3、基于LLM的TTS模型幻觉问题，如错读和漏读等问题。\n4、通过文本指令精准控制语音生成的风格，情感等。\n5、设计RL算法同时保证生成语音的准确性和情感化。\n6、多方言和多语种如何构建统一的语音生成大模型。\n\n具体工作：\n将参与语音生成大模型架构设计，预训练数据的清洗和基模的训练，tokenizer的设计和训练，instruct语音生成数据建设和算法优化，speech reward模型的建设和强化学习算法的研究，探索基于连续语音表征的技术方案，提升语音生成大模型的效果。\n\n课题要求\n1、具有语音合成、语音转换等方向的研究经验；\n2、具备一定的LLM理论基础和调优实践经验；\n3、熟悉语音大模型的训练和调优技术；\n4、在Interspeech、ICASSP等会议中投稿者优先。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139095","sourceKey":"tencent","company":"腾讯","title":"腾讯云—基于大语言模型的边缘安全运维智能体研究与实现","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139095","duty":"课题背景：\n在当前边缘安全防护领域，面对日益复杂隐蔽的DDoS与Web攻击（WAF），传统响应式运维模式在实时性、准确性与自适应性上存在不足。\n\n课题挑战：\n为突破瓶颈，本课题提出研发基于大语言模型（LLM）的安全运维智能体。在边缘安全防护领域，建设自动化安全运维防护能力。\n\n课题价值和具体工作：\n该智能体将深度融合边缘侧多维度安全数据与产品防护能力，构建自动化分析引擎，实现：一、对安全事件与运维问题的智能诊断与精准回答；二、在攻击场景下，通过实时流量分析与行为模式推演，动态优化并加固WAF/DDoS防护策略。最终形成“感知-决策-执行”闭环，提升主动防御能力，推动安全运维向智能化、自动化演进。","requirements":"1、计算机科学、软件工程、分布式计算、人工智能、计算机体系结构、网络与信息安全、通信工程、电子工程、应用数学、自动化等相关专业的博士和优秀硕士；\n2、熟悉安全防护；了解大模型推理优化（量化/并行策略/调度算法）、Agent系统架构、沙箱安全或边缘计算相关研究经验者优先；熟练掌握Go/C++/Rust/Python/Java/Lua中至少一种语言；\n3、具备扎实的科研素养与系统性思维能力，善于将前沿理论转化为工程实践；良好的跨团队沟通协作意识，能主动推动复杂问题的定义与解决，具备较强的自驱力与抗压能力。","description":"课题描述\n课题背景：\n在当前边缘安全防护领域，面对日益复杂隐蔽的DDoS与Web攻击（WAF），传统响应式运维模式在实时性、准确性与自适应性上存在不足。\n\n课题挑战：\n为突破瓶颈，本课题提出研发基于大语言模型（LLM）的安全运维智能体。在边缘安全防护领域，建设自动化安全运维防护能力。\n\n课题价值和具体工作：\n该智能体将深度融合边缘侧多维度安全数据与产品防护能力，构建自动化分析引擎，实现：一、对安全事件与运维问题的智能诊断与精准回答；二、在攻击场景下，通过实时流量分析与行为模式推演，动态优化并加固WAF/DDoS防护策略。最终形成“感知-决策-执行”闭环，提升主动防御能力，推动安全运维向智能化、自动化演进。\n\n课题要求\n1、计算机科学、软件工程、分布式计算、人工智能、计算机体系结构、网络与信息安全、通信工程、电子工程、应用数学、自动化等相关专业的博士和优秀硕士；\n2、熟悉安全防护；了解大模型推理优化（量化/并行策略/调度算法）、Agent系统架构、沙箱安全或边缘计算相关研究经验者优先；熟练掌握Go/C++/Rust/Python/Java/Lua中至少一种语言；\n3、具备扎实的科研素养与系统性思维能力，善于将前沿理论转化为工程实践；良好的跨团队沟通协作意识，能主动推动复杂问题的定义与解决，具备较强的自驱力与抗压能力。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139096","sourceKey":"tencent","company":"腾讯","title":"腾讯云—多模态大模型驱动的智能媒体处理平台研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139096","duty":"课题背景​：\n在短视频、直播、影视等内容产业爆发的背景下，传统音视频处理技术在复杂语义场景下面临理解不足、生成失真等瓶颈。为应对这一挑战，本项目致力于融合AIGC生成模型与多模态大模型，开展面向“感知-理解-生成”全链路的垂直媒体AI技术研究，旨在推动视听内容在修复、编辑、翻译、检索等场景的智能化升级，提升信息处理效率与用户体验。\n\n课题挑战​：\n课题需攻克四大核心难点：一是在复杂动态场景下实现高精度视觉内容修复与生成，包括水印与遮挡物的无痕擦除、超分辨与风格迁移；二是实现长视频的深度语义理解，包括跨模态高光识别、时序建模与语义检索；三是构建鲁棒高效的跨语言同传系统，实现音、视频、文本的语义对齐与时序同步；四是为保障技术落地，需对扩散模型、大语言模型等进行轻量化与工程优化，以支持高并发、低延迟的云端业务部署。\n\n具体工作​：\n加入课题后，同学将主要参与以下方向的研究与实现：复杂场景视觉编辑算法研发、多模态视频理解与检索系统构建、跨语言同传技术探索，以及模型轻量化与工程部署等相关工作。","requirements":"1、熟练掌握深度学习原理，对 Diffusion Model、Transformer、VAE、GAN 等生成框架有深入研究；\n2、熟悉视频时序建模（如 Temporal Attention、3D-Conv）或 ASR/NLP 大模型；\n3、在 CV 垂直领域（视频编辑、视频理解、多模态检索）或 语音大模型有实际落地项目经验。\n4、熟悉 ControlNet、LoRA、Adapter 等插件化微调技术。\n5、在 CVPR、ICCV、ECCV、NeurIPS、ACL、ICASSP 等顶会发表过论文。\n6、对媒体 AI 行业趋势敏感，具备解决复杂工程问题（如 AI infra算力优化、大规模数据清洗）的热情。","description":"课题描述\n课题背景​：\n在短视频、直播、影视等内容产业爆发的背景下，传统音视频处理技术在复杂语义场景下面临理解不足、生成失真等瓶颈。为应对这一挑战，本项目致力于融合AIGC生成模型与多模态大模型，开展面向“感知-理解-生成”全链路的垂直媒体AI技术研究，旨在推动视听内容在修复、编辑、翻译、检索等场景的智能化升级，提升信息处理效率与用户体验。\n\n课题挑战​：\n课题需攻克四大核心难点：一是在复杂动态场景下实现高精度视觉内容修复与生成，包括水印与遮挡物的无痕擦除、超分辨与风格迁移；二是实现长视频的深度语义理解，包括跨模态高光识别、时序建模与语义检索；三是构建鲁棒高效的跨语言同传系统，实现音、视频、文本的语义对齐与时序同步；四是为保障技术落地，需对扩散模型、大语言模型等进行轻量化与工程优化，以支持高并发、低延迟的云端业务部署。\n\n具体工作​：\n加入课题后，同学将主要参与以下方向的研究与实现：复杂场景视觉编辑算法研发、多模态视频理解与检索系统构建、跨语言同传技术探索，以及模型轻量化与工程部署等相关工作。\n\n课题要求\n1、熟练掌握深度学习原理，对 Diffusion Model、Transformer、VAE、GAN 等生成框架有深入研究；\n2、熟悉视频时序建模（如 Temporal Attention、3D-Conv）或 ASR/NLP 大模型；\n3、在 CV 垂直领域（视频编辑、视频理解、多模态检索）或 语音大模型有实际落地项目经验。\n4、熟悉 ControlNet、LoRA、Adapter 等插件化微调技术。\n5、在 CVPR、ICCV、ECCV、NeurIPS、ACL、ICASSP 等顶会发表过论文。\n6、对媒体 AI 行业趋势敏感，具备解决复杂工程问题（如 AI infra算力优化、大规模数据清洗）的热情。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139097","sourceKey":"tencent","company":"腾讯","title":"腾讯云—音视频语音识别大模型研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139097","duty":"课题背景：\n针对ASR在复杂场景（多轮对话、噪声、口音）的识别瓶颈及传统模型迭代慢、响应滞后问题，利用LLM的上下文推理与热词感知能力，构建可敏捷适应线上变化、快速修复识别缺陷的新一代架构。\n\n课题挑战：\n1、实时响应滞后：传统模型无法即时吸收新热词、适应主题切换，线上问题修复不及时。\n2、语境歧义难解：缺乏长上下文参考，易混淆同音词或在噪声中丢失关键语义。\n3、LLM流式效果不佳：低延迟流式场景下，音频特征与LLM动态文本特征的维度高效对齐困难，影响实时识别效果。\n\n具体工作：\n1、构建动态上下文修复机制：研发LLM推理模块捕捉对话主题演变，设计动态提示工程注入实时主题与热词，修正语境缺失错误。\n2、开发热词自适应与在线纠偏方案：建立热词库与解码器毫秒级联动，生成候选修正列表，实现无需全量重训的热修复能力。\n3、实现跨模态特征高效对齐：研究音文特征维度映射算法，验证最优融合架构，平衡开销与效果，保障复杂场景高准确率。","requirements":"1、计算机、人工智能、数学等相关专业的全日制研究生及以上学历；\n2、熟悉ASR语音识别、LLM模型项目；\n3、具备 Python/C++ 的算法实现能力，有深度学习框架 PyTorch/TensorFlow 经验。","description":"课题描述\n课题背景：\n针对ASR在复杂场景（多轮对话、噪声、口音）的识别瓶颈及传统模型迭代慢、响应滞后问题，利用LLM的上下文推理与热词感知能力，构建可敏捷适应线上变化、快速修复识别缺陷的新一代架构。\n\n课题挑战：\n1、实时响应滞后：传统模型无法即时吸收新热词、适应主题切换，线上问题修复不及时。\n2、语境歧义难解：缺乏长上下文参考，易混淆同音词或在噪声中丢失关键语义。\n3、LLM流式效果不佳：低延迟流式场景下，音频特征与LLM动态文本特征的维度高效对齐困难，影响实时识别效果。\n\n具体工作：\n1、构建动态上下文修复机制：研发LLM推理模块捕捉对话主题演变，设计动态提示工程注入实时主题与热词，修正语境缺失错误。\n2、开发热词自适应与在线纠偏方案：建立热词库与解码器毫秒级联动，生成候选修正列表，实现无需全量重训的热修复能力。\n3、实现跨模态特征高效对齐：研究音文特征维度映射算法，验证最优融合架构，平衡开销与效果，保障复杂场景高准确率。\n\n课题要求\n1、计算机、人工智能、数学等相关专业的全日制研究生及以上学历；\n2、熟悉ASR语音识别、LLM模型项目；\n3、具备 Python/C++ 的算法实现能力，有深度学习框架 PyTorch/TensorFlow 经验。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139098","sourceKey":"tencent","company":"腾讯","title":"腾讯云—边缘计算在AI推理加速方向研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139098","duty":"课题背景：\n随着 AI 应用向边缘侧下沉，实时推理、低时延、高并发需求日益突出。传统云端推理存在带宽压力大、延迟高不足等问题，难以满足视频分析、智能监控、工业感知等场景。边缘推理可将 AI 计算下沉到靠近数据源的节点，降低时延、节省带宽。但边缘硬件异构、资源受限、部署复杂，亟需一套高效、稳定、易扩展的边缘推理方案，因此开展本课题研究。\n\n课题挑战：\n1、边缘节点 CPU/GPU/NPU 等硬件高度异构，模型适配与推理加速难度大；\n2、边缘设备资源有限，需在低算力、低内存条件下保证推理性能与稳定性；\n3、云边协同调度复杂，任务分配、动态扩缩容、故障自愈难以兼顾效率与可靠性。在多场景、多硬件下保持一致体验，技术实现与工程化落地难度较高。\n\n具体工作：\n参与边缘推理框架开发、模型优化与部署工具链建设；\n实现模型转换、量化、加速与异构硬件适配；\n协助完成云边协同调度、服务部署与性能优化。","requirements":"1、学历和专业要求：计算机、软件工程、电子信息、自动化等相关专业硕士、博士同学，具备云计算、AI基础者优先；\n2、技术技能要求：掌握深度学习框架与推理优化知识，熟练使用C++/Python语言，了解边缘计算、云原生、模型量化加速者优先；\n3、软性素质要求：学习能力突出，逻辑思维缜密，沟通协作顺畅，责任心强，具备独立调研与动手实践能力。","description":"课题描述\n课题背景：\n随着 AI 应用向边缘侧下沉，实时推理、低时延、高并发需求日益突出。传统云端推理存在带宽压力大、延迟高不足等问题，难以满足视频分析、智能监控、工业感知等场景。边缘推理可将 AI 计算下沉到靠近数据源的节点，降低时延、节省带宽。但边缘硬件异构、资源受限、部署复杂，亟需一套高效、稳定、易扩展的边缘推理方案，因此开展本课题研究。\n\n课题挑战：\n1、边缘节点 CPU/GPU/NPU 等硬件高度异构，模型适配与推理加速难度大；\n2、边缘设备资源有限，需在低算力、低内存条件下保证推理性能与稳定性；\n3、云边协同调度复杂，任务分配、动态扩缩容、故障自愈难以兼顾效率与可靠性。在多场景、多硬件下保持一致体验，技术实现与工程化落地难度较高。\n\n具体工作：\n参与边缘推理框架开发、模型优化与部署工具链建设；\n实现模型转换、量化、加速与异构硬件适配；\n协助完成云边协同调度、服务部署与性能优化。\n\n课题要求\n1、学历和专业要求：计算机、软件工程、电子信息、自动化等相关专业硕士、博士同学，具备云计算、AI基础者优先；\n2、技术技能要求：掌握深度学习框架与推理优化知识，熟练使用C++/Python语言，了解边缘计算、云原生、模型量化加速者优先；\n3、软性素质要求：学习能力突出，逻辑思维缜密，沟通协作顺畅，责任心强，具备独立调研与动手实践能力。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139099","sourceKey":"tencent","company":"腾讯","title":"腾讯云大数据—DataAgent-数据决策智能体关键技术研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139099","duty":"课题背景：\n近年来，大语言模型在推理、代码生成、工具调用等方面持续进步，推动 Agent 从单轮问答向复杂任务闭环演进。在数据领域，DataAgent 已由传统“问数答疑”扩展至数据分析、归因诊断、策略生成、数据营销、A/B Testing 与效果评估等场景，对模型的任务理解、推理规划、工具调用与结果验证能力提出了更高要求。面向真实业务场景，DataAgent 仍面临模糊语义理解、多步推理、工具协同与结果校验等挑战，通用模型难以稳定完成复杂数据任务。因此，本课题聚焦 DataAgent 基座能力建设，围绕任务建模、训练数据构建、自动评估与后训练优化等关键问题，提升大模型在数据决策场景中的理解、推理与执行能力。\n\n课题挑战：\n1、DataAgent框架设计： 如何设计清晰、完备的 DataAgent 系统流程，使模型能够完成数据决策场景中的任务理解、分析规划、工具调用、结果验证与策略生成；\n2、数据长链路预训练优化： 如何筛选、清洗和组织多样化的数据任务语料、分析链路与工具使用轨迹，或通过自动化方式合成包含丰富上下文的训练数据，提升基座模型对复杂数据任务的理解与建模能力；\n3、Agent指令数据自动化合成： 如何设计有效策略，自动化合成覆盖数据分析、数据营销、A/B Testing 等多类场景的高质量、高复杂度 DataAgent 指令数据与中间轨迹数据；\n4、自动评估系统建设： 如何针对数据决策场景设计自动化评估体系，包括语义理解、查询生成、工具调用、执行结果、推理链路与结论质量等，对模型效果评估与训练数据清洗进行提效；\n5、奖励系统建设和强化学习策略优化： 对于复杂数据决策任务，如何结合执行反馈、链路质量、策略有效性与效率成本，设计合理的奖励信号并优化强化学习训练效果。\n\n具体工作：\n你将参与到 DataAgent 框架设计、数据长链路训练数据优化、复杂指令数据合成与自动评估、奖励系统建设和强化学习策略优化，提升大模型在数据决策场景中的复杂推理与智能体能力。","requirements":"1、计算机、人工智能、软件工程、自动化、电子工程、数学、统计学、数据科学、运筹优化等相关专业博士及优秀硕士；\n2、熟练掌握 Python、PyTorch 等编程语言与深度学习框架，具备大模型训练、后训练或 Agent 系统研发经验，熟悉 SFT、RL、Reward Model等相关技术；\n3、对数据分析、数据库、SQL 生成、实验设计、因果推断、多工具协同等方向有较好理解，具备较强的工程实现、问题分析与科研创新能力，有相关研究成果或实践经验者优先。","description":"课题描述\n课题背景：\n近年来，大语言模型在推理、代码生成、工具调用等方面持续进步，推动 Agent 从单轮问答向复杂任务闭环演进。在数据领域，DataAgent 已由传统“问数答疑”扩展至数据分析、归因诊断、策略生成、数据营销、A/B Testing 与效果评估等场景，对模型的任务理解、推理规划、工具调用与结果验证能力提出了更高要求。面向真实业务场景，DataAgent 仍面临模糊语义理解、多步推理、工具协同与结果校验等挑战，通用模型难以稳定完成复杂数据任务。因此，本课题聚焦 DataAgent 基座能力建设，围绕任务建模、训练数据构建、自动评估与后训练优化等关键问题，提升大模型在数据决策场景中的理解、推理与执行能力。\n\n课题挑战：\n1、DataAgent框架设计： 如何设计清晰、完备的 DataAgent 系统流程，使模型能够完成数据决策场景中的任务理解、分析规划、工具调用、结果验证与策略生成；\n2、数据长链路预训练优化： 如何筛选、清洗和组织多样化的数据任务语料、分析链路与工具使用轨迹，或通过自动化方式合成包含丰富上下文的训练数据，提升基座模型对复杂数据任务的理解与建模能力；\n3、Agent指令数据自动化合成： 如何设计有效策略，自动化合成覆盖数据分析、数据营销、A/B Testing 等多类场景的高质量、高复杂度 DataAgent 指令数据与中间轨迹数据；\n4、自动评估系统建设： 如何针对数据决策场景设计自动化评估体系，包括语义理解、查询生成、工具调用、执行结果、推理链路与结论质量等，对模型效果评估与训练数据清洗进行提效；\n5、奖励系统建设和强化学习策略优化： 对于复杂数据决策任务，如何结合执行反馈、链路质量、策略有效性与效率成本，设计合理的奖励信号并优化强化学习训练效果。\n\n具体工作：\n你将参与到 DataAgent 框架设计、数据长链路训练数据优化、复杂指令数据合成与自动评估、奖励系统建设和强化学习策略优化，提升大模型在数据决策场景中的复杂推理与智能体能力。\n\n课题要求\n1、计算机、人工智能、软件工程、自动化、电子工程、数学、统计学、数据科学、运筹优化等相关专业博士及优秀硕士；\n2、熟练掌握 Python、PyTorch 等编程语言与深度学习框架，具备大模型训练、后训练或 Agent 系统研发经验，熟悉 SFT、RL、Reward Model等相关技术；\n3、对数据分析、数据库、SQL 生成、实验设计、因果推断、多工具协同等方向有较好理解，具备较强的工程实现、问题分析与科研创新能力，有相关研究成果或实践经验者优先。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139100","sourceKey":"tencent","company":"腾讯","title":"腾讯云大数据—流湖一体统一增量计算引擎关键技术研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139100","duty":"课题背景：\nOceanus是腾讯云企业级实时大数据分析平台，当前大数据在实时数据处理场景下普遍采用Lambda架构，存在存储冗余、计算成本高、开发维护复杂（流批两套代码逻辑）等痛点。为此，我们自研了Setats统一流湖存储引擎，以\"统一存储+灵活计算\"为核心理念，用一套存储替代多套系统，支持流（秒级）、增量（分钟级）、批（小时级）三种执行模式灵活切换，从而实现存储/计算降本与开发效率的提升。\n\n课题挑战：\n1、统一存储引擎的高效数据更新与多模式访问：如何在远程存储上实现秒级数据合并与变更捕获，同时高效支持流读写、批读写、点查等多种访问模式的统一处理；\n2、存算分离架构下的存储性能优化：如何设计多级缓存与智能预取策略，在存算分离的架构下保证热数据的高效访问，并支持不同计算模式间的平滑切换；\n3、存储格式优化与向量化执行加速：如何优化数据存储组织方式以同时满足点查和批量扫描的性能需求，并通过向量化批处理技术大幅提升数据处理吞吐；\n4、关键算子的C++高性能重写与执行优化：如何将核心计算算子用C++进行高性能重写，消除运行时开销，并优化远程IO并发模型，充分利用系统资源；\n5、流批增量一体的调度与资源优化：如何实现同一套SQL在流/增量/批三种模式间的零代码切换，设计高效的调度与资源复用机制，大幅提升资源利用率。\n\n具体工作：\n你将深入参与Setats统一流湖存储引擎的核心研发，主要涉及以下方向的设计与开发：存储引擎的数据写入与合并优化模块；多级缓存系统的缓存管理与预取策略实现；存储格式的读写路径优化；基于C++的向量化执行引擎与关键算子的高性能重写；高并发IO执行框架的设计与优化；增量计算模式下的状态管理与调度引擎适配。同时参与Setats在各类客户场景的落地优化与性能调优工作。","requirements":"1、计算机科学、软件工程、数据科学、分布式系统等相关专业硕士及以上学历；\n2、扎实的C++编程能力，熟悉现代C++特性（C++17/20），有高性能系统开发经验；具备良好的系统编程基础，熟悉内存管理、并发编程、协程等底层技术；\n3、熟悉大数据处理框架（如Flink、Spark）或分布式存储系统（如RocksDB、HBase、Iceberg、Paimon等）的原理与实现，有相关开发经验者优先；\n4、了解LSM Tree、B+ Tree等存储引擎数据结构，熟悉数据库存储引擎或数据湖存储格式（Parquet、ORC等）的设计与优化，有相关项目经验者优先；\n5、了解分布式系统基本原理，包括一致性协议、存算分离架构、缓存策略、容错机制等；\n6、具备较强的问题分析、系统设计与工程实现能力，有良好的团队协作和沟通能力；有开源项目贡献经验者优先。","description":"课题描述\n课题背景：\nOceanus是腾讯云企业级实时大数据分析平台，当前大数据在实时数据处理场景下普遍采用Lambda架构，存在存储冗余、计算成本高、开发维护复杂（流批两套代码逻辑）等痛点。为此，我们自研了Setats统一流湖存储引擎，以\"统一存储+灵活计算\"为核心理念，用一套存储替代多套系统，支持流（秒级）、增量（分钟级）、批（小时级）三种执行模式灵活切换，从而实现存储/计算降本与开发效率的提升。\n\n课题挑战：\n1、统一存储引擎的高效数据更新与多模式访问：如何在远程存储上实现秒级数据合并与变更捕获，同时高效支持流读写、批读写、点查等多种访问模式的统一处理；\n2、存算分离架构下的存储性能优化：如何设计多级缓存与智能预取策略，在存算分离的架构下保证热数据的高效访问，并支持不同计算模式间的平滑切换；\n3、存储格式优化与向量化执行加速：如何优化数据存储组织方式以同时满足点查和批量扫描的性能需求，并通过向量化批处理技术大幅提升数据处理吞吐；\n4、关键算子的C++高性能重写与执行优化：如何将核心计算算子用C++进行高性能重写，消除运行时开销，并优化远程IO并发模型，充分利用系统资源；\n5、流批增量一体的调度与资源优化：如何实现同一套SQL在流/增量/批三种模式间的零代码切换，设计高效的调度与资源复用机制，大幅提升资源利用率。\n\n具体工作：\n你将深入参与Setats统一流湖存储引擎的核心研发，主要涉及以下方向的设计与开发：存储引擎的数据写入与合并优化模块；多级缓存系统的缓存管理与预取策略实现；存储格式的读写路径优化；基于C++的向量化执行引擎与关键算子的高性能重写；高并发IO执行框架的设计与优化；增量计算模式下的状态管理与调度引擎适配。同时参与Setats在各类客户场景的落地优化与性能调优工作。\n\n课题要求\n1、计算机科学、软件工程、数据科学、分布式系统等相关专业硕士及以上学历；\n2、扎实的C++编程能力，熟悉现代C++特性（C++17/20），有高性能系统开发经验；具备良好的系统编程基础，熟悉内存管理、并发编程、协程等底层技术；\n3、熟悉大数据处理框架（如Flink、Spark）或分布式存储系统（如RocksDB、HBase、Iceberg、Paimon等）的原理与实现，有相关开发经验者优先；\n4、了解LSM Tree、B+ Tree等存储引擎数据结构，熟悉数据库存储引擎或数据湖存储格式（Parquet、ORC等）的设计与优化，有相关项目经验者优先；\n5、了解分布式系统基本原理，包括一致性协议、存算分离架构、缓存策略、容错机制等；\n6、具备较强的问题分析、系统设计与工程实现能力，有良好的团队协作和沟通能力；有开源项目贡献经验者优先。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139101","sourceKey":"tencent","company":"腾讯","title":"腾讯云大数据—面向多模态数据处理的实进智能计算引擎关键技术研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139101","duty":"课题背景：\n随着AI与大数据的深度融合，企业数据形态已从传统的结构化数据扩展至文本、图像、视频等多模态数据，对实时数据处理引擎提出了全新挑战。为此，我们计划在Oceanus平台上构建面向多模态数据处理的新一代计算引擎，融合流批一体架构与向量化执行能力，原生支持半结构化数据、文本、图像、视频等多模态数据的统一处理。同时，引擎上层集成Flink Agents框架，实现对实时数据流的智能化处理，支持Agent的在线推理与强化学习训练。此外，引擎将强化Python生态支持，用户可交互式使用Python进行数据探索与分析，并将交互式任务无缝转化为长驻的生产级流批作业，打通从数据探索到生产部署的全链路。\n\n课题挑战：\n1、多模态数据处理与SQL执行的统一架构设计：如何在传统结构化SQL执行框架中，原生融合文本、图像、视频等多模态数据的处理能力，设计统一的数据模型、类型系统与执行计划，使用户能够用一套查询语言同时处理结构化与非结构化数据；\n2、多模态算子的设计与高效实现：如何设计面向多模态数据的算子体系，包括特征提取、编解码、Embedding计算、相似度检索等，并在流批一体引擎中实现高效调度与执行；\n3、GPU与国产加速卡的异构计算支持：如何实现GPU/国产加速卡的高效调度与CUDA算子优化，充分利用异构计算资源加速多模态数据处理与模型推理，同时兼容不同硬件平台；\n4、基于Flink Agents的实时智能体框架优化：如何基于Flink Agents开源项目构建高效的Agent执行框架，实现Agent与流式数据处理的深度集成，支持复杂的多步推理、工具调用与实时决策；\n5、小模型的在线训练与推理能力建设：如何在流式计算引擎中实现小模型的Online RL训练与实时推理，设计高效的训练数据采集、模型更新与在线服务机制，使模型能够随数据流持续学习与演进；\n6、Python交互式计算与任务生产化：如何强化引擎的Python支持能力，使用户可通过交互式Python环境进行数据探索与分析，并将交互式代码无缝转化为长驻的流批生产任务，实现开发与部署的一体化。\n\n具体工作：\n你将参与面向多模态数据处理的新一代流批一体智能计算引擎的核心研发，主要涉及以下方向：多模态数据处理与传统SQL执行的统一架构设计与实现；多模态算子（特征提取、编解码、Embedding等）的开发与优化；GPU/国产加速卡的异构计算调度与CUDA算子性能优化；基于Flink Agents的实时智能体框架开发与优化；小模型在线训练（Online RL）与实时推理能力的引擎集成；Python交互式计算环境与长驻任务转化机制的设计与实现。","requirements":"1、计算机科学、软件工程、人工智能、数据科学等相关专业硕士及以上学历；\n2、扎实的C++编程能力，熟悉现代C++特性，有高性能系统或计算引擎开发经验；\n3、熟悉CUDA编程或GPU异构计算开发，有CUDA算子优化经验者优先；\n4、熟悉大数据处理框架（如Flink、Spark）的原理与实现，有流式计算开发经验者优先；\n5、有Agent系统开发经验，熟悉LLM推理、工具调用、强化学习（RL）等相关技术者优先；\n6、有模型训练与推理系统开发经验，熟悉PyTorch等深度学习框架，了解在线学习与模型服务架构者优先；\n7、熟悉Python，有Python与C++混合编程经验者优先；\n8、具备较强的问题分析、系统设计与工程实现能力，有良好的团队协作和沟通能力；有开源项目贡献经验者优先。","description":"课题描述\n课题背景：\n随着AI与大数据的深度融合，企业数据形态已从传统的结构化数据扩展至文本、图像、视频等多模态数据，对实时数据处理引擎提出了全新挑战。为此，我们计划在Oceanus平台上构建面向多模态数据处理的新一代计算引擎，融合流批一体架构与向量化执行能力，原生支持半结构化数据、文本、图像、视频等多模态数据的统一处理。同时，引擎上层集成Flink Agents框架，实现对实时数据流的智能化处理，支持Agent的在线推理与强化学习训练。此外，引擎将强化Python生态支持，用户可交互式使用Python进行数据探索与分析，并将交互式任务无缝转化为长驻的生产级流批作业，打通从数据探索到生产部署的全链路。\n\n课题挑战：\n1、多模态数据处理与SQL执行的统一架构设计：如何在传统结构化SQL执行框架中，原生融合文本、图像、视频等多模态数据的处理能力，设计统一的数据模型、类型系统与执行计划，使用户能够用一套查询语言同时处理结构化与非结构化数据；\n2、多模态算子的设计与高效实现：如何设计面向多模态数据的算子体系，包括特征提取、编解码、Embedding计算、相似度检索等，并在流批一体引擎中实现高效调度与执行；\n3、GPU与国产加速卡的异构计算支持：如何实现GPU/国产加速卡的高效调度与CUDA算子优化，充分利用异构计算资源加速多模态数据处理与模型推理，同时兼容不同硬件平台；\n4、基于Flink Agents的实时智能体框架优化：如何基于Flink Agents开源项目构建高效的Agent执行框架，实现Agent与流式数据处理的深度集成，支持复杂的多步推理、工具调用与实时决策；\n5、小模型的在线训练与推理能力建设：如何在流式计算引擎中实现小模型的Online RL训练与实时推理，设计高效的训练数据采集、模型更新与在线服务机制，使模型能够随数据流持续学习与演进；\n6、Python交互式计算与任务生产化：如何强化引擎的Python支持能力，使用户可通过交互式Python环境进行数据探索与分析，并将交互式代码无缝转化为长驻的流批生产任务，实现开发与部署的一体化。\n\n具体工作：\n你将参与面向多模态数据处理的新一代流批一体智能计算引擎的核心研发，主要涉及以下方向：多模态数据处理与传统SQL执行的统一架构设计与实现；多模态算子（特征提取、编解码、Embedding等）的开发与优化；GPU/国产加速卡的异构计算调度与CUDA算子性能优化；基于Flink Agents的实时智能体框架开发与优化；小模型在线训练（Online RL）与实时推理能力的引擎集成；Python交互式计算环境与长驻任务转化机制的设计与实现。\n\n课题要求\n1、计算机科学、软件工程、人工智能、数据科学等相关专业硕士及以上学历；\n2、扎实的C++编程能力，熟悉现代C++特性，有高性能系统或计算引擎开发经验；\n3、熟悉CUDA编程或GPU异构计算开发，有CUDA算子优化经验者优先；\n4、熟悉大数据处理框架（如Flink、Spark）的原理与实现，有流式计算开发经验者优先；\n5、有Agent系统开发经验，熟悉LLM推理、工具调用、强化学习（RL）等相关技术者优先；\n6、有模型训练与推理系统开发经验，熟悉PyTorch等深度学习框架，了解在线学习与模型服务架构者优先；\n7、熟悉Python，有Python与C++混合编程经验者优先；\n8、具备较强的问题分析、系统设计与工程实现能力，有良好的团队协作和沟通能力；有开源项目贡献经验者优先。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139102","sourceKey":"tencent","company":"腾讯","title":"腾讯云大数据-AI Native Data Infra平台关键技术研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139102","duty":"课题背景：\n随着大模型和多模态AI应用的快速发展，数据基础设施正从传统数据分析平台向 AI-Native Data Infrastructure 演进。新一代数据平台不仅需要支持大规模SQL分析，还需要原生支持LLM推理、向量计算、多模态数据处理以及AI Agent驱动的数据决策。\n当前主流数据系统仍然主要围绕CPU架构与结构化数据设计，在AI算子执行、GPU异构计算、LLM调用优化以及Serverless资源调度等方面存在明显瓶颈。同时，企业正在将大模型能力深度引入数据分析流程，通过数据分析智能体实现自动化分析与决策，但在复杂业务环境下仍面临规划能力不足、推理可靠性和成本控制等挑战。\n本课题旨在探索 AI与数据系统深度融合的新一代架构，围绕AI算子执行优化、GPU加速计算引擎、Serverless调度优化、SQL+LLM融合优化以及数据分析智能体等关键方向开展研究，推动构建面向AI时代的 AI-Native Data Infra平台。\n\n课题挑战：\n构建AI-Native Data Infra平台涉及一系列新的系统挑战：\n1、AI算子（如Embedding生成、LLM推理等）在执行模型与资源特性上与传统SQL算子存在显著差异，现有SQL优化器缺乏针对AI算子的代价模型与执行优化机制。\n2、AI与数据处理负载正在从CPU计算向 CPU+GPU异构计算架构 转变，如何设计高效的协同执行模型、GPU友好型数据结构以及端到端数据通路优化，是构建高性能AI数据系统的重要问题。\n3、在Serverless Lakehouse架构下，任务调度需要在毫秒级时间内完成，同时实现高精度资源预测和高资源利用率，这对调度算法和系统架构提出了更高要求。\n4、在SQL中直接调用LLM进行语义理解或多模态分析时，推理成本和执行延迟较高，缺乏Prompt变化感知、结果复用和增量推理等优化机制。\n5、面向企业生产环境的数据分析智能体仍然面临规划偏差、推理一致性、生成幻觉以及结果可验证性等挑战。\n\n具体工作：\n参与AI-Native Data Infra核心技术研发，包括AI算子执行优化、GPU加速计算引擎、Serverless调度优化、SQL+LLM融合执行优化以及企业级数据分析智能体能力建设，推动下一代AI数据基础设施平台落地。","requirements":"1、计算机科学、软件工程、人工智能、数据科学等相关专业博士或优秀硕士研究生，具备扎实的数据系统、分布式系统或机器学习基础。在数据库、数据系统、AI Infra等方向有研究经历，或在 FAST、VLDB、SIGMOD、OSDI、SOSP、MLSys 等顶级会议发表论文者优先；\n2、具备数据库系统、分布式计算或机器学习系统相关基础，熟悉SQL优化、查询执行引擎、调度系统、向量计算或AI推理系统等方向；熟练掌握 C++ / Java / Python 等至少一门语言，有大规模数据系统或AI Infra研发经验者优先；\n3、具备良好的系统思维与技术探索精神，能够从复杂系统问题中抽象关键技术挑战并推动落地；具有良好的沟通协作能力和工程推进能力，能够在跨团队环境中推动技术创新和系统落地。","description":"课题描述\n课题背景：\n随着大模型和多模态AI应用的快速发展，数据基础设施正从传统数据分析平台向 AI-Native Data Infrastructure 演进。新一代数据平台不仅需要支持大规模SQL分析，还需要原生支持LLM推理、向量计算、多模态数据处理以及AI Agent驱动的数据决策。\n当前主流数据系统仍然主要围绕CPU架构与结构化数据设计，在AI算子执行、GPU异构计算、LLM调用优化以及Serverless资源调度等方面存在明显瓶颈。同时，企业正在将大模型能力深度引入数据分析流程，通过数据分析智能体实现自动化分析与决策，但在复杂业务环境下仍面临规划能力不足、推理可靠性和成本控制等挑战。\n本课题旨在探索 AI与数据系统深度融合的新一代架构，围绕AI算子执行优化、GPU加速计算引擎、Serverless调度优化、SQL+LLM融合优化以及数据分析智能体等关键方向开展研究，推动构建面向AI时代的 AI-Native Data Infra平台。\n\n课题挑战：\n构建AI-Native Data Infra平台涉及一系列新的系统挑战：\n1、AI算子（如Embedding生成、LLM推理等）在执行模型与资源特性上与传统SQL算子存在显著差异，现有SQL优化器缺乏针对AI算子的代价模型与执行优化机制。\n2、AI与数据处理负载正在从CPU计算向 CPU+GPU异构计算架构 转变，如何设计高效的协同执行模型、GPU友好型数据结构以及端到端数据通路优化，是构建高性能AI数据系统的重要问题。\n3、在Serverless Lakehouse架构下，任务调度需要在毫秒级时间内完成，同时实现高精度资源预测和高资源利用率，这对调度算法和系统架构提出了更高要求。\n4、在SQL中直接调用LLM进行语义理解或多模态分析时，推理成本和执行延迟较高，缺乏Prompt变化感知、结果复用和增量推理等优化机制。\n5、面向企业生产环境的数据分析智能体仍然面临规划偏差、推理一致性、生成幻觉以及结果可验证性等挑战。\n\n具体工作：\n参与AI-Native Data Infra核心技术研发，包括AI算子执行优化、GPU加速计算引擎、Serverless调度优化、SQL+LLM融合执行优化以及企业级数据分析智能体能力建设，推动下一代AI数据基础设施平台落地。\n\n课题要求\n1、计算机科学、软件工程、人工智能、数据科学等相关专业博士或优秀硕士研究生，具备扎实的数据系统、分布式系统或机器学习基础。在数据库、数据系统、AI Infra等方向有研究经历，或在 FAST、VLDB、SIGMOD、OSDI、SOSP、MLSys 等顶级会议发表论文者优先；\n2、具备数据库系统、分布式计算或机器学习系统相关基础，熟悉SQL优化、查询执行引擎、调度系统、向量计算或AI推理系统等方向；熟练掌握 C++ / Java / Python 等至少一门语言，有大规模数据系统或AI Infra研发经验者优先；\n3、具备良好的系统思维与技术探索精神，能够从复杂系统问题中抽象关键技术挑战并推动落地；具有良好的沟通协作能力和工程推进能力，能够在跨团队环境中推动技术创新和系统落地。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139103","sourceKey":"tencent","company":"腾讯","title":"腾讯云CodeBuddy—利用强化学习方法基于经验数据训练提升大模型Agent能力研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139103","duty":"课题背景：\n随着 Agent 在真实业务场景的普及，产生了海量的交互经验数据（Experience Data）。这些数据不仅包含成功的路径，也包含失败的纠错过程，是模型理解复杂世界和自我进化的“富矿”。当前，大模型研发正处于从依赖人工标注向利用真实反馈转化的关键期。本课题旨在探索如何从这些高噪声的交互数据中提取高质量训练信号，并以此驱动模型能力的持续迭代。\n\n课题价值：\n1、开辟增长新极：在预训练数据红利消减、后训练（SFT/RLHF）边际效应递减的背景下，利用真实经验数据实现模型能力的二次增长。\n2、实现自我闭环：通过 Agent 系统在研发闭环中的实践，产生数据再反哺模型，形成“研发-反馈-进化”的飞轮效应。\n3、沉淀高价值策略：MAS（多智能体）作为经验捕获的载体，能更精细地记录复杂任务的拆解与协作逻辑，为模型提供更深层的思维链条（CoT）。\n\n课题挑战：\n1、高噪声数据洗练：如何从海量 Agent 交互轨迹中，通过自动化机制判别并提取出具备启发性的“高价值信号”，解决信噪比低的问题。\n2、MAS 自适应协同：如何设计多智能体架构，使其在利用经验数据进化的过程中，能自发演化出更高效的协作协议，以应对复杂的模型研发任务。\n3、闭环演进的稳定性：防止模型在利用自身产生的经验数据进行微调时，出现“模型崩溃”或偏离人类意图的泛化退化现象。\n\n具体工作：\n1、参与到Code Agent模型的训练优化，利用好CodeBuddy的Agent数据训练模型，包括提升base能力、模型扩窗口、搭建并优化RL环境、将RL scaling起来优化模型；\n2、搭建并优化LLM research 多智能体系统，直接用于大模型的研发，产生价值。","requirements":"1、CS/AI相关专业（博士优先）；\n2、熟练Python/PyTorch，优秀的编程技能；\n3、有大模型研究相关的项目经验；\n4、英语读写流利；\n5、良好的沟通协作能力。\n\n加分项：\n1、发表过AI顶会论文；\n2、有ACM等竞赛成绩。","description":"课题描述\n课题背景：\n随着 Agent 在真实业务场景的普及，产生了海量的交互经验数据（Experience Data）。这些数据不仅包含成功的路径，也包含失败的纠错过程，是模型理解复杂世界和自我进化的“富矿”。当前，大模型研发正处于从依赖人工标注向利用真实反馈转化的关键期。本课题旨在探索如何从这些高噪声的交互数据中提取高质量训练信号，并以此驱动模型能力的持续迭代。\n\n课题价值：\n1、开辟增长新极：在预训练数据红利消减、后训练（SFT/RLHF）边际效应递减的背景下，利用真实经验数据实现模型能力的二次增长。\n2、实现自我闭环：通过 Agent 系统在研发闭环中的实践，产生数据再反哺模型，形成“研发-反馈-进化”的飞轮效应。\n3、沉淀高价值策略：MAS（多智能体）作为经验捕获的载体，能更精细地记录复杂任务的拆解与协作逻辑，为模型提供更深层的思维链条（CoT）。\n\n课题挑战：\n1、高噪声数据洗练：如何从海量 Agent 交互轨迹中，通过自动化机制判别并提取出具备启发性的“高价值信号”，解决信噪比低的问题。\n2、MAS 自适应协同：如何设计多智能体架构，使其在利用经验数据进化的过程中，能自发演化出更高效的协作协议，以应对复杂的模型研发任务。\n3、闭环演进的稳定性：防止模型在利用自身产生的经验数据进行微调时，出现“模型崩溃”或偏离人类意图的泛化退化现象。\n\n具体工作：\n1、参与到Code Agent模型的训练优化，利用好CodeBuddy的Agent数据训练模型，包括提升base能力、模型扩窗口、搭建并优化RL环境、将RL scaling起来优化模型；\n2、搭建并优化LLM research 多智能体系统，直接用于大模型的研发，产生价值。\n\n课题要求\n1、CS/AI相关专业（博士优先）；\n2、熟练Python/PyTorch，优秀的编程技能；\n3、有大模型研究相关的项目经验；\n4、英语读写流利；\n5、良好的沟通协作能力。\n\n加分项：\n1、发表过AI顶会论文；\n2、有ACM等竞赛成绩。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nCSIG\n云与智慧产业事业群\n\nCodeBuddy系列智能体产品\nCodeBuddy系列智能体产品致力于打造基于大模型的创新AI产品。我们面向软件开发、智能办公、创意设计和内容生成等场景，通过打造 CodeBuddy、WorkBuddy、腾讯设计 Ardot、Miora等创新AI产品，持续提升研发效率、协作体验与创意生产力，其中，WorkBuddy 已成为中国用户规模第一的 AI 办公智能体。加入我们，一起打造更多创新AI产品，定义工作生活新范式。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139104","sourceKey":"tencent","company":"腾讯","title":"腾讯云—面向数据库自动驾驶领域大模型的强化学习研究","city":"成都","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139104","duty":"课题背景：\n随着大语言模型整体智能化程度的不断提升，当前数据库存储系统的智能化数据管理和运维能力还不够智能化，特别是随着vibe coding在更多的用户中普及，这些没有开发能力的用户也无法运营和管理好自己的数据库服务，如何实现这些数据库和基础设施的自动驾驶变的越来越重要。\n\n课题挑战：\n参与业界顶尖的数据库agentic模型后训练工作，结合RL能力，提高模型表现\n\n具体工作：\n你将参与到Database Model继续训练和后训练的整个技术管线设计和实现，包含强化学习轨迹数据合成，强化学习算法设计，强化学习环境设计，强化学习效率优化等等。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、有强化学习方向顶会的博士和优秀硕士；\n2、深入理解Transformer架构和大语言模型原理，熟练掌握SFT、RLHF、DPO，RLVR等后训练技术，熟悉PyTorch/TensorFlow框架，有实际模型训练调优和分布式训练经验；\n3、熟悉数据库原理、SQL语法、执行计划分析等专业知识，有数据库内核开发、性能优化、运维自动化相关经验者优先；\n4、有大规模数据处理、数据标注质量控制、模型评测体系构建经验，熟悉领域Benchmark设计或参与过开源评测项目者优先。","description":"课题描述\n课题背景：\n随着大语言模型整体智能化程度的不断提升，当前数据库存储系统的智能化数据管理和运维能力还不够智能化，特别是随着vibe coding在更多的用户中普及，这些没有开发能力的用户也无法运营和管理好自己的数据库服务，如何实现这些数据库和基础设施的自动驾驶变的越来越重要。\n\n课题挑战：\n参与业界顶尖的数据库agentic模型后训练工作，结合RL能力，提高模型表现\n\n具体工作：\n你将参与到Database Model继续训练和后训练的整个技术管线设计和实现，包含强化学习轨迹数据合成，强化学习算法设计，强化学习环境设计，强化学习效率优化等等。\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、有强化学习方向顶会的博士和优秀硕士；\n2、深入理解Transformer架构和大语言模型原理，熟练掌握SFT、RLHF、DPO，RLVR等后训练技术，熟悉PyTorch/TensorFlow框架，有实际模型训练调优和分布式训练经验；\n3、熟悉数据库原理、SQL语法、执行计划分析等专业知识，有数据库内核开发、性能优化、运维自动化相关经验者优先；\n4、有大规模数据处理、数据标注质量控制、模型评测体系构建经验，熟悉领域Benchmark设计或参与过开源评测项目者优先。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139105","sourceKey":"tencent","company":"腾讯","title":"腾讯云—面向智能体长短期记忆的智能化数据管理系统的强化学习研究","city":"成都","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139105","duty":"课题背景：\n随着大语言模型整体智能化程度的不断提升，计算平台已经逐步往GPU为核心的平台演进，产生数据的来源也将演进到智能体这种新兴的形式上，相关的数据格式也将发生变化。agent将是一个非常主流的计算载体和平台，如何管理这些agent产生的上下文，将这些上下文沉淀为agent的长短期记忆变的越来越重要。\n\n课题挑战：\n如何将Agent上下文管理、记忆机制构建与强化学习训练管线有效结合，并进一步提升数据利用效率、训练效果和系统可扩展性，是本课题需要重点解决的核心挑战。\n\n具体工作：\n你将参与到Database Model继续训练和后训练的整个技术管线设计和实现，包含强化学习轨迹数据合成，强化学习算法设计，强化学习环境设计，强化学习效率优化等等。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、有强化学习方向顶会的博士和优秀硕士；\n2、深入理解Transformer架构和大语言模型原理，熟练掌握SFT、RLHF、DPO，RLVR等后训练技术，熟悉PyTorch/TensorFlow框架，有实际模型训练调优和分布式训练经验；\n3、熟悉数据库原理、SQL语法、执行计划分析等专业知识，有数据库内核开发、性能优化、运维自动化相关经验者优先；\n4、有大规模数据处理、数据标注质量控制、模型评测体系构建经验，熟悉领域Benchmark设计或参与过开源评测项目者优先。","description":"课题描述\n课题背景：\n随着大语言模型整体智能化程度的不断提升，计算平台已经逐步往GPU为核心的平台演进，产生数据的来源也将演进到智能体这种新兴的形式上，相关的数据格式也将发生变化。agent将是一个非常主流的计算载体和平台，如何管理这些agent产生的上下文，将这些上下文沉淀为agent的长短期记忆变的越来越重要。\n\n课题挑战：\n如何将Agent上下文管理、记忆机制构建与强化学习训练管线有效结合，并进一步提升数据利用效率、训练效果和系统可扩展性，是本课题需要重点解决的核心挑战。\n\n具体工作：\n你将参与到Database Model继续训练和后训练的整个技术管线设计和实现，包含强化学习轨迹数据合成，强化学习算法设计，强化学习环境设计，强化学习效率优化等等。\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、有强化学习方向顶会的博士和优秀硕士；\n2、深入理解Transformer架构和大语言模型原理，熟练掌握SFT、RLHF、DPO，RLVR等后训练技术，熟悉PyTorch/TensorFlow框架，有实际模型训练调优和分布式训练经验；\n3、熟悉数据库原理、SQL语法、执行计划分析等专业知识，有数据库内核开发、性能优化、运维自动化相关经验者优先；\n4、有大规模数据处理、数据标注质量控制、模型评测体系构建经验，熟悉领域Benchmark设计或参与过开源评测项目者优先。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139106","sourceKey":"tencent","company":"腾讯","title":"腾讯云—分布式数据库 TDSQL 数据动态自适应调度研究","city":"成都","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139106","duty":"课题背景：\n目前 TDSQL 架构主要面向金融核心业务场景，在技术选型上更侧重数据库性能、低延迟以及延迟抖动控制。为保障高性能表现，系统通常将数据在存储节点之间的分布方式与分片算法（如 Hash、Range、List）进行较强绑定，以尽可能保证数据局部性，从而满足核心场景对稳定性和实时性的高要求。\n\n课题挑战：\n现有架构虽然在高性能和低时延方面具备优势，但在扩缩容场景下，动态平滑迁移和数据自适应调度能力存在一定妥协。随着业务负载变化加剧，系统需要在保持原有高性能特性的同时，进一步提升数据分布调整、弹性扩缩容和迁移过程中的平滑性与灵活性。如何平衡“高性能、强局部性”与“高弹性、强适配性”之间的矛盾，成为该课题的核心挑战。\n\n具体工作：\n本课题尝试在当前 TDSQL 架构基础上，研究兼顾高性能与优秀数据弹性的实现方案。重点围绕数据分布策略优化、扩缩容过程中动态平滑迁移机制设计，以及数据自适应调度能力建设展开，探索在不显著牺牲性能、低延迟和延迟稳定性的前提下，提升系统在负载变化和资源调整场景下的数据弹性能力。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学等专业的博士和优秀硕士；\n2、熟练掌握数据库基础理论知识，熟悉多线程编程、锁机制（Mutex/Spinlock）及无锁编程（Lock-free）技术；深刻理解 CPU 缓存层次（L1/L2/L3）、Cache Line、缓存一致性协议（MESI 等）；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。","description":"课题描述\n课题背景：\n目前 TDSQL 架构主要面向金融核心业务场景，在技术选型上更侧重数据库性能、低延迟以及延迟抖动控制。为保障高性能表现，系统通常将数据在存储节点之间的分布方式与分片算法（如 Hash、Range、List）进行较强绑定，以尽可能保证数据局部性，从而满足核心场景对稳定性和实时性的高要求。\n\n课题挑战：\n现有架构虽然在高性能和低时延方面具备优势，但在扩缩容场景下，动态平滑迁移和数据自适应调度能力存在一定妥协。随着业务负载变化加剧，系统需要在保持原有高性能特性的同时，进一步提升数据分布调整、弹性扩缩容和迁移过程中的平滑性与灵活性。如何平衡“高性能、强局部性”与“高弹性、强适配性”之间的矛盾，成为该课题的核心挑战。\n\n具体工作：\n本课题尝试在当前 TDSQL 架构基础上，研究兼顾高性能与优秀数据弹性的实现方案。重点围绕数据分布策略优化、扩缩容过程中动态平滑迁移机制设计，以及数据自适应调度能力建设展开，探索在不显著牺牲性能、低延迟和延迟稳定性的前提下，提升系统在负载变化和资源调整场景下的数据弹性能力。\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学等专业的博士和优秀硕士；\n2、熟练掌握数据库基础理论知识，熟悉多线程编程、锁机制（Mutex/Spinlock）及无锁编程（Lock-free）技术；深刻理解 CPU 缓存层次（L1/L2/L3）、Cache Line、缓存一致性协议（MESI 等）；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139109","sourceKey":"tencent","company":"腾讯","title":"腾讯云—分布式任务调度系统高并发处理与容量模型研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139109","duty":"课题背景：\n随着云计算、大数据和微服务架构的深入应用，分布式任务调度系统已成为现代互联网基础设施的核心组件。腾讯云 CVM 任务调度系统承载着海量任务，日均调度量达到数亿级别。在双十一、春保、突发流量等高峰业务场景下，系统需要持续具备高并发处理能力、高吞吐性能以及稳定可靠的服务能力，因此任务调度系统的稳定性与弹性建设变得尤为关键。\n\n课题挑战：\n当前系统在容灾机制、故障域隔离、流控能力和背压机制等方面仍面临较大挑战。具体表现为：在大规模任务并发场景下，调度延迟显著增加；资源利用率存在不均衡问题；流量突增时容易引发系统雪崩风险；同时上下游系统之间的压力传导也会进一步放大整体稳定性问题。这些因素使得系统在极端流量场景下的持续服务能力面临考验。\n\n具体工作：\n本课题聚焦于分布式任务调度系统的稳定性优化，围绕系统架构优化、调度算法改进和容量模型建设开展研究。一方面，通过优化系统架构，提升容灾、隔离与流量承载能力；另一方面，通过改进调度算法，降低高并发场景下的调度延迟并提升资源利用率；同时结合容量模型建设，完善流控、背压与稳定性保障机制，最终构建一套完整的稳定性保障体系，提升系统在极端场景下的持续服务能力。","requirements":"1、包含但不限于计算机、软件工程、人工智能、网络工程、自动化等相关专业的博士或优秀硕士；\n2、熟练掌握至少一门主流后端开发语言（Python/Golang/Java/C++），具备优秀的编码、调试和系统架构设计能力。熟悉Linux开发环境及常用性能分析工具；\n3、AI Coding与自动化能力：熟悉并善于利用AI编程助手（如GitHub Copilot、Claude Code或CodeBuddy）进行高效开发，具备使用大语言模型（LLM）辅助进行代码生成、重构、调试和文档编写的能力。对自动化代码审查、测试用例生成等DevOps实践有了解或浓厚兴趣；\n4、额外加分项：有大规模分布式系统（如Kubernetes、YARN、Mesos等）研发或调优经验者优先；熟悉消息队列、RPC框架、服务治理等中间件者优先；有AI for Systems或LLM辅助编程相关项目经验者优先。","description":"课题描述\n课题背景：\n随着云计算、大数据和微服务架构的深入应用，分布式任务调度系统已成为现代互联网基础设施的核心组件。腾讯云 CVM 任务调度系统承载着海量任务，日均调度量达到数亿级别。在双十一、春保、突发流量等高峰业务场景下，系统需要持续具备高并发处理能力、高吞吐性能以及稳定可靠的服务能力，因此任务调度系统的稳定性与弹性建设变得尤为关键。\n\n课题挑战：\n当前系统在容灾机制、故障域隔离、流控能力和背压机制等方面仍面临较大挑战。具体表现为：在大规模任务并发场景下，调度延迟显著增加；资源利用率存在不均衡问题；流量突增时容易引发系统雪崩风险；同时上下游系统之间的压力传导也会进一步放大整体稳定性问题。这些因素使得系统在极端流量场景下的持续服务能力面临考验。\n\n具体工作：\n本课题聚焦于分布式任务调度系统的稳定性优化，围绕系统架构优化、调度算法改进和容量模型建设开展研究。一方面，通过优化系统架构，提升容灾、隔离与流量承载能力；另一方面，通过改进调度算法，降低高并发场景下的调度延迟并提升资源利用率；同时结合容量模型建设，完善流控、背压与稳定性保障机制，最终构建一套完整的稳定性保障体系，提升系统在极端场景下的持续服务能力。\n\n课题要求\n1、包含但不限于计算机、软件工程、人工智能、网络工程、自动化等相关专业的博士或优秀硕士；\n2、熟练掌握至少一门主流后端开发语言（Python/Golang/Java/C++），具备优秀的编码、调试和系统架构设计能力。熟悉Linux开发环境及常用性能分析工具；\n3、AI Coding与自动化能力：熟悉并善于利用AI编程助手（如GitHub Copilot、Claude Code或CodeBuddy）进行高效开发，具备使用大语言模型（LLM）辅助进行代码生成、重构、调试和文档编写的能力。对自动化代码审查、测试用例生成等DevOps实践有了解或浓厚兴趣；\n4、额外加分项：有大规模分布式系统（如Kubernetes、YARN、Mesos等）研发或调优经验者优先；熟悉消息队列、RPC框架、服务治理等中间件者优先；有AI for Systems或LLM辅助编程相关项目经验者优先。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139110","sourceKey":"tencent","company":"腾讯","title":"腾讯云—高性能大模型训练/推理网络","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139110","duty":"课题背景：\n随着大语言模型（LLM）参数量级的爆炸式增长，超大规模 AI 集群的算力瓶颈已逐渐从单卡算力转移到集群通信能力上。本项目聚焦于“高性能大模型训练/推理网络”，基于腾讯自研的星脉网络 2.0，致力于打通端侧计算节点与网侧交换机，构建端到端的高性能网络架构。通过在芯片、硬件、软件及集群网络算法等关键技术上的全栈自研，全面提升 GPU 集群的数据吞吐与协同效率，为腾讯内部应用及公有云业务的 AI 大模型训练与推理场景提供坚实的底层网络支撑。\n\n课题挑战：\n1、端网协同的极致性能优化：如何在硬件网卡、驱动、传输层协议与网侧交换机之间进行全栈协同设计，打破传统网络协议瓶颈，实现底层通信效率的极限突破；\n2、复杂流量下的动态拥塞控制：在大模型训练的 All-to-All、All-Reduce 等高频突发流量场景下，如何设计并实现高效、灵活的网卡可编程拥塞控制（CC）算法，避免网络拥堵导致的算力闲置；\n3、vRDMA 协议栈的深度定制与虚拟化：在云原生环境下，如何兼顾 RDMA 的高性能与虚拟化的灵活性，解决 vRDMA 在多租户隔离、连接大规模扩展及高可靠传输上的技术挑战；\n4、全路径性能瓶颈定位与观测：在复杂的分布式环境下，如何建立从底层网络协议到上层 AI 框架的端到端观测体系，实现对网络波动、协议异常及计算通信重叠问题的精准识别与快速定位。\n\n具体工作：\n你将深入参与到超大规模 AI 集群高性能网络的架构设计、协议开发与端到端优化中，具体包括：\n1、vRDMA 核心传输协议开发：深入参与vRDMA传输层的设计与实现，涵盖多路径负载均衡、快速重传机制、大规模连接状态机管理逻辑优化；\n2、端到端训练性能优化：基于 vRDMA 平台及商业网卡（如 NVIDIA ConnectX 系列），优化大模型训练中的集合通信库（如 NCCL/RCCL），提升有效带宽与并行效率；\n3、低延迟推理网络优化：针对大语言模型推理场景，利用 vRDMA 的硬件卸载与轻量化协议栈特性，优化 Prefill 与 Decode 阶段的通信逻辑，并结合商业网卡技术栈实现高并发场景下的端到端推理加速；\n4、全路径观测与性能分析体系建设：构建跨层次的性能监控方案，打通从网卡硬件计数器、驱动层、传输层协议到 AI 框架通信算子的全路径数据，实现对训练/推理任务中性能瓶颈的准确识别与根因分析；\n5、可编程拥塞控制与闭环调优：参与自研可编程拥塞控制模块（如 DCQCN 或新型 CC 协议）的开发与在线调优，针对不同业务流量特征实现精细化的带宽分配。","requirements":"1、包含但不限于计算机、软件工程、人工智能等相关专业博士或优秀硕士；\n2、熟悉高性能网络相关技术，包括RDMA, IB, libfabric, mpi等;\n3、熟悉机器学习训练过程，特别是训练中的网络通信过程及相关技术和组件。包括NCCL, DP/PP/TP, Megatron等;\n4、追求极致性能，主动寻求突破。","description":"课题描述\n课题背景：\n随着大语言模型（LLM）参数量级的爆炸式增长，超大规模 AI 集群的算力瓶颈已逐渐从单卡算力转移到集群通信能力上。本项目聚焦于“高性能大模型训练/推理网络”，基于腾讯自研的星脉网络 2.0，致力于打通端侧计算节点与网侧交换机，构建端到端的高性能网络架构。通过在芯片、硬件、软件及集群网络算法等关键技术上的全栈自研，全面提升 GPU 集群的数据吞吐与协同效率，为腾讯内部应用及公有云业务的 AI 大模型训练与推理场景提供坚实的底层网络支撑。\n\n课题挑战：\n1、端网协同的极致性能优化：如何在硬件网卡、驱动、传输层协议与网侧交换机之间进行全栈协同设计，打破传统网络协议瓶颈，实现底层通信效率的极限突破；\n2、复杂流量下的动态拥塞控制：在大模型训练的 All-to-All、All-Reduce 等高频突发流量场景下，如何设计并实现高效、灵活的网卡可编程拥塞控制（CC）算法，避免网络拥堵导致的算力闲置；\n3、vRDMA 协议栈的深度定制与虚拟化：在云原生环境下，如何兼顾 RDMA 的高性能与虚拟化的灵活性，解决 vRDMA 在多租户隔离、连接大规模扩展及高可靠传输上的技术挑战；\n4、全路径性能瓶颈定位与观测：在复杂的分布式环境下，如何建立从底层网络协议到上层 AI 框架的端到端观测体系，实现对网络波动、协议异常及计算通信重叠问题的精准识别与快速定位。\n\n具体工作：\n你将深入参与到超大规模 AI 集群高性能网络的架构设计、协议开发与端到端优化中，具体包括：\n1、vRDMA 核心传输协议开发：深入参与vRDMA传输层的设计与实现，涵盖多路径负载均衡、快速重传机制、大规模连接状态机管理逻辑优化；\n2、端到端训练性能优化：基于 vRDMA 平台及商业网卡（如 NVIDIA ConnectX 系列），优化大模型训练中的集合通信库（如 NCCL/RCCL），提升有效带宽与并行效率；\n3、低延迟推理网络优化：针对大语言模型推理场景，利用 vRDMA 的硬件卸载与轻量化协议栈特性，优化 Prefill 与 Decode 阶段的通信逻辑，并结合商业网卡技术栈实现高并发场景下的端到端推理加速；\n4、全路径观测与性能分析体系建设：构建跨层次的性能监控方案，打通从网卡硬件计数器、驱动层、传输层协议到 AI 框架通信算子的全路径数据，实现对训练/推理任务中性能瓶颈的准确识别与根因分析；\n5、可编程拥塞控制与闭环调优：参与自研可编程拥塞控制模块（如 DCQCN 或新型 CC 协议）的开发与在线调优，针对不同业务流量特征实现精细化的带宽分配。\n\n课题要求\n1、包含但不限于计算机、软件工程、人工智能等相关专业博士或优秀硕士；\n2、熟悉高性能网络相关技术，包括RDMA, IB, libfabric, mpi等;\n3、熟悉机器学习训练过程，特别是训练中的网络通信过程及相关技术和组件。包括NCCL, DP/PP/TP, Megatron等;\n4、追求极致性能，主动寻求突破。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139111","sourceKey":"tencent","company":"腾讯","title":"腾讯云—AI存储研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139111","duty":"课题背景：\n随着AI大模型、自动驾驶、多模态检索等核心场景的快速发展，底层存储系统面临前所未有的压力。训练阶段需要高吞吐地读取海量非结构化数据（图片、视频、点云等），推理阶段要求低延迟地加载模型权重与特征缓存，向量检索场景则需要高效存取和检索高维向量数据。传统对象存储在IO性能、数据组织方式和检索能力上难以满足AI全链路的多样化需求，如何构建面向AI多模态场景的高性能存储体系，成为支撑AI产业规模化落地的关键基础设施命题。\n\n课题挑战：\n1、性能瓶颈突出：AI训练与推理对存储的吞吐、延迟和并发能力要求极高，传统对象存储的IO路径存在多层开销，缓存命中率和预取策略的优化面临数据访问模式多变、热点漂移等难题；\n2、向量存储与检索效率不足：高维向量的索引构建、近似最近邻（ANN）搜索的精度与速度权衡、以及向量数据与元数据的联合过滤查询，在大规模数据集下面临严峻的工程挑战；\n3、多模态数据湖管理复杂：图片、视频、文本、点云等异构数据的统一存储、元数据治理和跨模态关联分析缺乏成熟方案，数据湖在schema演进、增量更新和分析查询性能上仍需系统性突破。\n\n具体工作：\n参与AI场景下存储系统的性能优化与产品研发，包括GooseFS系列产品的高性能缓存策略优化（预取、淘汰、分层缓存）、COS向量存储引擎的索引结构与检索性能调优，以及面向多模态数据湖的存储架构设计与数据组织优化，支撑大模型训练、自动驾驶数据回灌、多模态检索等核心业务场景。","requirements":"专业背景：\n包含但不限于计算机科学与技术、计算机体系结构、网络工程、通信工程、软件工程、电子信息工程、信息与通信系统、应用数学、分布式计算等专业的博士和优秀硕士。\n\n存储与网络基础：\n熟悉计算机网络协议栈（TCP/IP）基本原理，了解 RDMA（InfiniBand/RoCE v2）技术原理及其相比传统 TCP 的优势；了解对象存储（如 COS/S3）或分布式存储系统的基本架构和读写流程者优先。\n\n编程与工程能力：\n较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Linux 系统编程（Socket、epoll、内存管理等）；熟悉 Shell/Python 至少一种脚本语言；有 RDMA 编程经验（libibverbs/librdmacm）或 DPDK/SPDK 开发经验者优先。\n\n加分项（满足其一即可）：\n1、有高性能网络传输、用户态协议栈（如 eRPC、Accelio）相关项目或研究经验；\n2、熟悉 RDMA 通信模型（Send/Recv、Read/Write、SRQ）及其性能调优；\n3、了解 NVMe-oF、存储计算分离架构或有 COS/HDFS/Ceph 等存储系统开发经验；\n4、在高性能计算、网络系统、存储系统等方向有高质量论文发表或开源项目贡献。","description":"课题描述\n课题背景：\n随着AI大模型、自动驾驶、多模态检索等核心场景的快速发展，底层存储系统面临前所未有的压力。训练阶段需要高吞吐地读取海量非结构化数据（图片、视频、点云等），推理阶段要求低延迟地加载模型权重与特征缓存，向量检索场景则需要高效存取和检索高维向量数据。传统对象存储在IO性能、数据组织方式和检索能力上难以满足AI全链路的多样化需求，如何构建面向AI多模态场景的高性能存储体系，成为支撑AI产业规模化落地的关键基础设施命题。\n\n课题挑战：\n1、性能瓶颈突出：AI训练与推理对存储的吞吐、延迟和并发能力要求极高，传统对象存储的IO路径存在多层开销，缓存命中率和预取策略的优化面临数据访问模式多变、热点漂移等难题；\n2、向量存储与检索效率不足：高维向量的索引构建、近似最近邻（ANN）搜索的精度与速度权衡、以及向量数据与元数据的联合过滤查询，在大规模数据集下面临严峻的工程挑战；\n3、多模态数据湖管理复杂：图片、视频、文本、点云等异构数据的统一存储、元数据治理和跨模态关联分析缺乏成熟方案，数据湖在schema演进、增量更新和分析查询性能上仍需系统性突破。\n\n具体工作：\n参与AI场景下存储系统的性能优化与产品研发，包括GooseFS系列产品的高性能缓存策略优化（预取、淘汰、分层缓存）、COS向量存储引擎的索引结构与检索性能调优，以及面向多模态数据湖的存储架构设计与数据组织优化，支撑大模型训练、自动驾驶数据回灌、多模态检索等核心业务场景。\n\n课题要求\n专业背景：\n包含但不限于计算机科学与技术、计算机体系结构、网络工程、通信工程、软件工程、电子信息工程、信息与通信系统、应用数学、分布式计算等专业的博士和优秀硕士。\n\n存储与网络基础：\n熟悉计算机网络协议栈（TCP/IP）基本原理，了解 RDMA（InfiniBand/RoCE v2）技术原理及其相比传统 TCP 的优势；了解对象存储（如 COS/S3）或分布式存储系统的基本架构和读写流程者优先。\n\n编程与工程能力：\n较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Linux 系统编程（Socket、epoll、内存管理等）；熟悉 Shell/Python 至少一种脚本语言；有 RDMA 编程经验（libibverbs/librdmacm）或 DPDK/SPDK 开发经验者优先。\n\n加分项（满足其一即可）：\n1、有高性能网络传输、用户态协议栈（如 eRPC、Accelio）相关项目或研究经验；\n2、熟悉 RDMA 通信模型（Send/Recv、Read/Write、SRQ）及其性能调优；\n3、了解 NVMe-oF、存储计算分离架构或有 COS/HDFS/Ceph 等存储系统开发经验；\n4、在高性能计算、网络系统、存储系统等方向有高质量论文发表或开源项目贡献。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139112","sourceKey":"tencent","company":"腾讯","title":"腾讯云—统一多模态检索研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139112","duty":"课题背景：\n随着企业数字化转型加速，非结构化数据（图像、视频、文档等）占比已超过80%，传统基于文本的关键词检索已无法满足企业对全类型数据的智能管理需求。当前市场上多数检索产品仍停留在单模态或浅层多模态阶段，跨模态语义理解能力薄弱，导致\"信息孤岛\"现象严重——用户需要分别在图像库、视频库、文档库中进行多次检索，无法获得统一的语义关联结果。与此同时，大模型的爆发式增长对检索系统提出了更高要求：不仅需要返回相关结果，更需要理解多模态内容间的深层语义关联，为下游任务（如问答、生成、推理）提供精准的知识支持。在此背景下，统一多模态检索（Universal Multimodal Retrieval, UMR）技术成为突破检索天花板、构建下一代智能知识基础设施的关键方向。\n\n课题挑战：\n1、跨模态语义对齐难题：不同模态的数据（如产品图、说明书、操作视频、技术文档）在特征空间分布差异巨大，如何学习真正统一的嵌入表示，而非简单的特征拼接，使得文本-图像-视频的语义粒度对齐成为核心难点；\n2、垂类场景适配困境：通用UMR模型在特定行业（如工业质检、医疗影像、零售商品））中往往面临领域知识缺失、专业术语理解不足等问题，需要在保持跨模态通用能力的同时实现高效定制化；\n3、负样本挖掘与难例区分：多模态场景下硬负样本的定义与挖掘策略远比单模态复杂，如何构建有效的难例学习机制，避免模型在\"看似简单\"的跨模态对（如外观相似但功能不同的产品）上失效，是提升检索精度的关键；\n4、计算效率与精度的平衡：统一嵌入空间的高维计算开销大，如何在百亿级规模下实现毫秒级响应，同时保持细粒度语义区分能力，对索引结构、量化策略、硬件加速都提出严苛要求。\n\n具体工作：\n1、参与UMR核心算法在MetaInsight产品中的工程化落地，包括跨模态预训练模型的垂类微调策略设计与实验、基于难例挖掘的对比学习优化；\n2、参与构建多模态统一索引架构，支持文本/图像/视频的混合检索与排序；参与面向企业客户的检索产品功能迭代，包括多模态Query理解、结果重排序及相关性解释机制开发；\n3、参与检索效果评测体系建设，设计跨模态检索准确率、泛化能力及端到端延迟等核心指标的评测方案与工具开发。","requirements":"专业背景：\n1、计算机科学与技术、人工智能、机器学习、模式识别、计算机视觉等相关专业的博士 / 硕士同学；\n2、具备多模态特征学习、检索系统相关研究或项目背景者优先。\n\n技术技能要求：\n1、具备多模态大模型的模型预训练、后训练、模型推理等基本技能；\n2、具备大模型产品，尤其是多模态检索/图像检索/视频检索产品方案的落地实践经验；\n3、熟练运用 Python，熟悉 PyTorch/TensorFlow 框架，熟悉vLLM/SGLang等大模型推理框架；\n4、密切跟进多模态大模型技术发展，具备大模型效果调优能力和开发经验。\n\n软性素质要求：\n1、具备较强的问题拆解与创新能力，沟通协作、跨团队对接效率高；\n2、对垂类行业场景适配有耐心，能高效推进算法落地与迭代。","description":"课题描述\n课题背景：\n随着企业数字化转型加速，非结构化数据（图像、视频、文档等）占比已超过80%，传统基于文本的关键词检索已无法满足企业对全类型数据的智能管理需求。当前市场上多数检索产品仍停留在单模态或浅层多模态阶段，跨模态语义理解能力薄弱，导致\"信息孤岛\"现象严重——用户需要分别在图像库、视频库、文档库中进行多次检索，无法获得统一的语义关联结果。与此同时，大模型的爆发式增长对检索系统提出了更高要求：不仅需要返回相关结果，更需要理解多模态内容间的深层语义关联，为下游任务（如问答、生成、推理）提供精准的知识支持。在此背景下，统一多模态检索（Universal Multimodal Retrieval, UMR）技术成为突破检索天花板、构建下一代智能知识基础设施的关键方向。\n\n课题挑战：\n1、跨模态语义对齐难题：不同模态的数据（如产品图、说明书、操作视频、技术文档）在特征空间分布差异巨大，如何学习真正统一的嵌入表示，而非简单的特征拼接，使得文本-图像-视频的语义粒度对齐成为核心难点；\n2、垂类场景适配困境：通用UMR模型在特定行业（如工业质检、医疗影像、零售商品））中往往面临领域知识缺失、专业术语理解不足等问题，需要在保持跨模态通用能力的同时实现高效定制化；\n3、负样本挖掘与难例区分：多模态场景下硬负样本的定义与挖掘策略远比单模态复杂，如何构建有效的难例学习机制，避免模型在\"看似简单\"的跨模态对（如外观相似但功能不同的产品）上失效，是提升检索精度的关键；\n4、计算效率与精度的平衡：统一嵌入空间的高维计算开销大，如何在百亿级规模下实现毫秒级响应，同时保持细粒度语义区分能力，对索引结构、量化策略、硬件加速都提出严苛要求。\n\n具体工作：\n1、参与UMR核心算法在MetaInsight产品中的工程化落地，包括跨模态预训练模型的垂类微调策略设计与实验、基于难例挖掘的对比学习优化；\n2、参与构建多模态统一索引架构，支持文本/图像/视频的混合检索与排序；参与面向企业客户的检索产品功能迭代，包括多模态Query理解、结果重排序及相关性解释机制开发；\n3、参与检索效果评测体系建设，设计跨模态检索准确率、泛化能力及端到端延迟等核心指标的评测方案与工具开发。\n\n课题要求\n专业背景：\n1、计算机科学与技术、人工智能、机器学习、模式识别、计算机视觉等相关专业的博士 / 硕士同学；\n2、具备多模态特征学习、检索系统相关研究或项目背景者优先。\n\n技术技能要求：\n1、具备多模态大模型的模型预训练、后训练、模型推理等基本技能；\n2、具备大模型产品，尤其是多模态检索/图像检索/视频检索产品方案的落地实践经验；\n3、熟练运用 Python，熟悉 PyTorch/TensorFlow 框架，熟悉vLLM/SGLang等大模型推理框架；\n4、密切跟进多模态大模型技术发展，具备大模型效果调优能力和开发经验。\n\n软性素质要求：\n1、具备较强的问题拆解与创新能力，沟通协作、跨团队对接效率高；\n2、对垂类行业场景适配有耐心，能高效推进算法落地与迭代。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139113","sourceKey":"tencent","company":"腾讯","title":"腾讯云—适合 AI Agent 的 Infra 体系研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139113","duty":"课题背景：\n2025-2026年，AI技术迎来关键转型期，正从传统会话式交互向执行式落地加速演进，智能体（Agent）不再局限于简单的问答响应，而是能够自主拆解任务、调用工具、执行复杂操作，广泛渗透到企业运维、自动化办公、工业控制等各类场景。这一转型使得AI基础设施（AI Infra）的需求发生根本性变化， 匹配Agent执行特征的运行环境成为Agent Infra非常关键的技术挑战。\n\n课题挑战：\n1、会话级高频磁盘/内存快照对 Sandbox 无感；\n2、大规模磁盘/内存快照的高性能低成本按需存储；\n3、秒级的基于快照恢复sandbox。\n\n具体工作：\n1、参与Agent Sandbox大规模磁盘/内存快照存储系统的设计研发；\n2、紧跟行业最新趋势， 为团队在Agent Infra 领域提供前沿视角。","requirements":"1、计算机、信息工程、模式识别/人工智能、自动化、软件工程、电子工程、信息安全、信号与信息处理等相关专业博士或优秀硕士；\n2、多年机器学习/深度学习研发经验，且具备至少1年大模型训练/微调/落地实战经验（含数据、训练、评测或部署任一环节）；\n3、深入理解 LLM 全链路与关键方法，包括CPT、SFT、RM、RLHF/DPO、数据合成与评测体系等；\n4、熟悉行业 Agent infra 的挑战和做法， 有扎实的计算机底层基础和大型系统架构意识；\n5、有良好的自驱力和好奇心， 对技术有本质和极简的追求，能将一件事情做到极致。","description":"课题描述\n课题背景：\n2025-2026年，AI技术迎来关键转型期，正从传统会话式交互向执行式落地加速演进，智能体（Agent）不再局限于简单的问答响应，而是能够自主拆解任务、调用工具、执行复杂操作，广泛渗透到企业运维、自动化办公、工业控制等各类场景。这一转型使得AI基础设施（AI Infra）的需求发生根本性变化， 匹配Agent执行特征的运行环境成为Agent Infra非常关键的技术挑战。\n\n课题挑战：\n1、会话级高频磁盘/内存快照对 Sandbox 无感；\n2、大规模磁盘/内存快照的高性能低成本按需存储；\n3、秒级的基于快照恢复sandbox。\n\n具体工作：\n1、参与Agent Sandbox大规模磁盘/内存快照存储系统的设计研发；\n2、紧跟行业最新趋势， 为团队在Agent Infra 领域提供前沿视角。\n\n课题要求\n1、计算机、信息工程、模式识别/人工智能、自动化、软件工程、电子工程、信息安全、信号与信息处理等相关专业博士或优秀硕士；\n2、多年机器学习/深度学习研发经验，且具备至少1年大模型训练/微调/落地实战经验（含数据、训练、评测或部署任一环节）；\n3、深入理解 LLM 全链路与关键方法，包括CPT、SFT、RM、RLHF/DPO、数据合成与评测体系等；\n4、熟悉行业 Agent infra 的挑战和做法， 有扎实的计算机底层基础和大型系统架构意识；\n5、有良好的自驱力和好奇心， 对技术有本质和极简的追求，能将一件事情做到极致。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139114","sourceKey":"tencent","company":"腾讯","title":"腾讯云—下一代AI原生的云产品全链路交互研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139114","duty":"课题背景：\n随着LLM技术的发展与基于ReAct的Agent运行框架日益成熟，传统复杂的云平台与云产品亟需进行全链路使用体验的升级：把云产品的操控能力从挫败感极强的“方向盘”形态，转变为启发式的“导航仪”形态。本课题聚焦于云平台最底层的IaaS产品线，从网络域切入，探索与落地AI智能化路径，为后续在更多IaaS产品上的推广打下基础。\n\n课题挑战：\n1、专业化小模型与排障效果：在网络域构建高效、轻量的专业小模型，并在复杂场景中显著提升AI排障的准确性与效率；\n2、AI Infra端到端落地：围绕底模对比、领域数据集构建、训练与后训练框架、多模型服务化以及评测标准，完成从研究到工程的全链路打通；\n3、通用化与适配扩展：将上述AI Infra能力抽象与标准化，使其可复用、可扩展，支持其他IaaS产品的快速接入与平滑演进。\n\n具体工作：\n1、构建网络域的专业小模型，提升AI排障性能与效果；\n2、以网络产品AI化为起点，完成底模对比调研、领域数据集构建、训练框架、多模型servicing，以及AI后训练效果评估标准等AI Infra系统的实践落地；\n3、将上述AI Infra系统通用化，使之能够支持其他IaaS产品的适配接入。","requirements":"1、计算机、信息工程、模式识别/人工智能、自动化、软件工程、电子工程、信息安全、信号与信息处理等相关专业博士或硕士；\n2、多年机器学习/深度学习研发经验，且具备至少1年大模型训练/微调/落地实战经验（含数据、训练、评测或部署任一环节）；\n3、深入理解 LLM 全链路与关键方法，包括CPT、SFT、RM、RLHF/DPO、数据合成与评测体系等；\n4、熟练 Python/PyTorch，理解 Transformer/MoE 等核心架构；代码能力扎实，具备 Python 工程开发与调试能力；\n5、加分项：具备扎实网络与云IaaS基础（TCP/IP、路由协议、SDN、VPC等），有网络排障/自动化运维或相关项目经验更佳。","description":"课题描述\n课题背景：\n随着LLM技术的发展与基于ReAct的Agent运行框架日益成熟，传统复杂的云平台与云产品亟需进行全链路使用体验的升级：把云产品的操控能力从挫败感极强的“方向盘”形态，转变为启发式的“导航仪”形态。本课题聚焦于云平台最底层的IaaS产品线，从网络域切入，探索与落地AI智能化路径，为后续在更多IaaS产品上的推广打下基础。\n\n课题挑战：\n1、专业化小模型与排障效果：在网络域构建高效、轻量的专业小模型，并在复杂场景中显著提升AI排障的准确性与效率；\n2、AI Infra端到端落地：围绕底模对比、领域数据集构建、训练与后训练框架、多模型服务化以及评测标准，完成从研究到工程的全链路打通；\n3、通用化与适配扩展：将上述AI Infra能力抽象与标准化，使其可复用、可扩展，支持其他IaaS产品的快速接入与平滑演进。\n\n具体工作：\n1、构建网络域的专业小模型，提升AI排障性能与效果；\n2、以网络产品AI化为起点，完成底模对比调研、领域数据集构建、训练框架、多模型servicing，以及AI后训练效果评估标准等AI Infra系统的实践落地；\n3、将上述AI Infra系统通用化，使之能够支持其他IaaS产品的适配接入。\n\n课题要求\n1、计算机、信息工程、模式识别/人工智能、自动化、软件工程、电子工程、信息安全、信号与信息处理等相关专业博士或硕士；\n2、多年机器学习/深度学习研发经验，且具备至少1年大模型训练/微调/落地实战经验（含数据、训练、评测或部署任一环节）；\n3、深入理解 LLM 全链路与关键方法，包括CPT、SFT、RM、RLHF/DPO、数据合成与评测体系等；\n4、熟练 Python/PyTorch，理解 Transformer/MoE 等核心架构；代码能力扎实，具备 Python 工程开发与调试能力；\n5、加分项：具备扎实网络与云IaaS基础（TCP/IP、路由协议、SDN、VPC等），有网络排障/自动化运维或相关项目经验更佳。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139115","sourceKey":"tencent","company":"腾讯","title":"腾讯云—TurboCFS高性能存储项目","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139115","duty":"课题背景：\n近年来，人工智能AI技术飞速发展，特别是在大语言模型和自动驾驶这两种场景。模型参数、集群规模以及数据量呈指数级增长，对人工智能依赖的底层存储系统提出了极大的挑战和要求。为了提供更好的一致性、兼容性和性能，文件存储作为AI存储首选基座，其涵盖了训练和推理的全生命周期，包括数据采集、预处理、训练、保存、分发和归档等全流程阶段。不同的业务场景和不同的业务阶段对文件存储提出了不一样的挑战和要求，包括TB级/s的读写带宽能力、百PB级别的单集群存储能力、千万级的元数据OPS能力、百亿级的文件数量管理能力等等。\n\n课题挑战：\n大模型训练、推理以及自动驾驶场景下的高性能文件存储项目集体的挑战分为如下几个方面：\n1、通过极致优化和无限扩展能力，提供极高带宽吞吐，满足单集群TB/s到数十TB/s读写带宽能力。\n2、通过全链路的微秒级优化设计，提供极低延迟（数十微秒级别）的数据访问能力。\n3、加强元数据管理能力，提供海量（百亿级别）文件场景下的极高性能（千万OPS）元数据访问能力。\n4、满足十万级卡集群的高并发访问模式，确保超大规模集群的训练长期稳定运行。\n5、提供高并发访问场景的强一致性能力，以及秒级的HA恢复能力。\n6、提供丰富的接口和生态能力，支持同一底座多种接口的访问能力，如POSIX、S3、NFS、SAMBA和HDFS。\n\n具体工作：\n深度参与业界领先的自研AI存储基座，并完成课题的核心挑战，包括TB级/s的读写带宽能力、百PB级别的单集群存储能力、数十微秒级别的数据访问延迟能力、千万级的元数据OPS能力、百亿级的文件数量管理能力等等。","requirements":"1、计算机、信息工程、软件工程等专业的博士和优秀硕士；\n2、熟练掌握计算机操作系统和计算机网络，熟悉ext4/xfs等至少一个文件系统和tcp/ip协议；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Go至少一种编程语言。","description":"课题描述\n课题背景：\n近年来，人工智能AI技术飞速发展，特别是在大语言模型和自动驾驶这两种场景。模型参数、集群规模以及数据量呈指数级增长，对人工智能依赖的底层存储系统提出了极大的挑战和要求。为了提供更好的一致性、兼容性和性能，文件存储作为AI存储首选基座，其涵盖了训练和推理的全生命周期，包括数据采集、预处理、训练、保存、分发和归档等全流程阶段。不同的业务场景和不同的业务阶段对文件存储提出了不一样的挑战和要求，包括TB级/s的读写带宽能力、百PB级别的单集群存储能力、千万级的元数据OPS能力、百亿级的文件数量管理能力等等。\n\n课题挑战：\n大模型训练、推理以及自动驾驶场景下的高性能文件存储项目集体的挑战分为如下几个方面：\n1、通过极致优化和无限扩展能力，提供极高带宽吞吐，满足单集群TB/s到数十TB/s读写带宽能力。\n2、通过全链路的微秒级优化设计，提供极低延迟（数十微秒级别）的数据访问能力。\n3、加强元数据管理能力，提供海量（百亿级别）文件场景下的极高性能（千万OPS）元数据访问能力。\n4、满足十万级卡集群的高并发访问模式，确保超大规模集群的训练长期稳定运行。\n5、提供高并发访问场景的强一致性能力，以及秒级的HA恢复能力。\n6、提供丰富的接口和生态能力，支持同一底座多种接口的访问能力，如POSIX、S3、NFS、SAMBA和HDFS。\n\n具体工作：\n深度参与业界领先的自研AI存储基座，并完成课题的核心挑战，包括TB级/s的读写带宽能力、百PB级别的单集群存储能力、数十微秒级别的数据访问延迟能力、千万级的元数据OPS能力、百亿级的文件数量管理能力等等。\n\n课题要求\n1、计算机、信息工程、软件工程等专业的博士和优秀硕士；\n2、熟练掌握计算机操作系统和计算机网络，熟悉ext4/xfs等至少一个文件系统和tcp/ip协议；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Go至少一种编程语言。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139116","sourceKey":"tencent","company":"腾讯","title":"腾讯云—腾讯云下一代虚拟化预研项目","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139116","duty":"课题背景：\n虚拟化团队负责腾讯云虚拟化宿主机内核以及虚拟化套件的开发与维护工作，支撑腾讯自研云平台、公有云及私有云场景下的虚拟化底层技术，支持大规模业务的稳定运营。\n下一代虚拟化平台的主要方向涵盖：\n1、轻量虚拟化，重构 QEMU/KVM 架构，支持在高密服务器下的轻量级部署，减少虚拟化损耗；\n2、可维护性提升，支持任何组件的热升级和热替换能力；\n3、HostOS 与 GuestOS 的协同优化，实现性能和资源消耗的极致优化。\n\n课题挑战：\n1、虚拟化属于计算机工程范畴里复杂性最大的软件程序之一，对操作系统的开发、维护需要足够的熟悉与全局化思维；\n2、底层硬件不断地发展，单机规格越来越大。进而带来对虚拟化和操作系统扩展性的挑战，底层软件需要和CPU体系结构深度优化，解决扩展性和稳定性的问题。\n\n具体工作：\n1、针对弹性内存，优化冷热内存判断机制与检测算法\n2、针对所设计检测机制与对应的淘汰算法，设计方案去进行性能评估/准确性评估","requirements":"1、熟悉虚拟化相关技术，熟悉以下模块中的一个或者多个：kvm、调度器、内存管理、网络、存储(有开源贡献、实际代码开发项目经验的优先)；\n2、了解/熟悉Linux系统下通用的问题分析工具链使用，如ebpf，perf，ftrace，kprobe等；\n3、熟悉x86/arm cpu架构或者异构硬件架构，有相关的调研、调优经验；\n4、分析问题有专研精神，做到刨根问底。解决问题有长远意识，底层组件需要做到足够优雅。","description":"课题描述\n课题背景：\n虚拟化团队负责腾讯云虚拟化宿主机内核以及虚拟化套件的开发与维护工作，支撑腾讯自研云平台、公有云及私有云场景下的虚拟化底层技术，支持大规模业务的稳定运营。\n下一代虚拟化平台的主要方向涵盖：\n1、轻量虚拟化，重构 QEMU/KVM 架构，支持在高密服务器下的轻量级部署，减少虚拟化损耗；\n2、可维护性提升，支持任何组件的热升级和热替换能力；\n3、HostOS 与 GuestOS 的协同优化，实现性能和资源消耗的极致优化。\n\n课题挑战：\n1、虚拟化属于计算机工程范畴里复杂性最大的软件程序之一，对操作系统的开发、维护需要足够的熟悉与全局化思维；\n2、底层硬件不断地发展，单机规格越来越大。进而带来对虚拟化和操作系统扩展性的挑战，底层软件需要和CPU体系结构深度优化，解决扩展性和稳定性的问题。\n\n具体工作：\n1、针对弹性内存，优化冷热内存判断机制与检测算法\n2、针对所设计检测机制与对应的淘汰算法，设计方案去进行性能评估/准确性评估\n\n课题要求\n1、熟悉虚拟化相关技术，熟悉以下模块中的一个或者多个：kvm、调度器、内存管理、网络、存储(有开源贡献、实际代码开发项目经验的优先)；\n2、了解/熟悉Linux系统下通用的问题分析工具链使用，如ebpf，perf，ftrace，kprobe等；\n3、熟悉x86/arm cpu架构或者异构硬件架构，有相关的调研、调优经验；\n4、分析问题有专研精神，做到刨根问底。解决问题有长远意识，底层组件需要做到足够优雅。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139117","sourceKey":"tencent","company":"腾讯","title":"腾讯云—腾讯自研操作系统（Tencent OS）项目","city":"成都","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139117","duty":"课题背景：\n随着芯片技术的发展，单台服务器的核心规模不断增加。如何保证操作系统和硬件体系结构的扩展性、性能、稳定性成为一个重要的研究方向。该课题聚焦在软硬件结合领域，解决几方面的问题：\n1、操作系统本身在多核架构的扩展性问题，保证性能的水平扩展\n2、解决大核心的稳定性问题，调研软硬件结合领域，研究CPU计算核心、Cache、内存、PCIE、GPU等领域RAS业界前沿技术，提升整体的稳定性\n\n课题挑战：\n1、操作系统属于计算机工程范畴里复杂性最大的软件程序之一，对操作系统的开发、维护需要足够的熟悉与全局化思维；\n2、底层硬件不断地发展，单机规格越来越大。进而带来对操作系统扩展性的挑战，底层软件需要和CPU体系结构深度优化，解决扩展性和稳定性的问题。\n\n具体工作：\n1、承担操作系统方向中偏向于预研性质的专项，并且承担疑难技术问题的攻坚，如大规格数据中心服务器集成高密带来的稳定性和故障率问题等。","requirements":"1、熟悉Linux操作系统内核实现，熟悉以下模块中的一个或者多个：kvm、调度器、内存管理、网络、存储(有开源贡献、实际代码开发项目经验的优先)；\n2、了解/熟悉Linux系统下通用的问题分析工具链使用，如ebpf，perf，ftrace，kprobe等；\n3、深入理解x86/arm cpu架构或者异构硬件架构，有相关的调研、调优经验；\n4、分析问题有专研精神，做到刨根问底。解决问题有长远意识，底层组件需要做到足够优雅。","description":"课题描述\n课题背景：\n随着芯片技术的发展，单台服务器的核心规模不断增加。如何保证操作系统和硬件体系结构的扩展性、性能、稳定性成为一个重要的研究方向。该课题聚焦在软硬件结合领域，解决几方面的问题：\n1、操作系统本身在多核架构的扩展性问题，保证性能的水平扩展\n2、解决大核心的稳定性问题，调研软硬件结合领域，研究CPU计算核心、Cache、内存、PCIE、GPU等领域RAS业界前沿技术，提升整体的稳定性\n\n课题挑战：\n1、操作系统属于计算机工程范畴里复杂性最大的软件程序之一，对操作系统的开发、维护需要足够的熟悉与全局化思维；\n2、底层硬件不断地发展，单机规格越来越大。进而带来对操作系统扩展性的挑战，底层软件需要和CPU体系结构深度优化，解决扩展性和稳定性的问题。\n\n具体工作：\n1、承担操作系统方向中偏向于预研性质的专项，并且承担疑难技术问题的攻坚，如大规格数据中心服务器集成高密带来的稳定性和故障率问题等。\n\n课题要求\n1、熟悉Linux操作系统内核实现，熟悉以下模块中的一个或者多个：kvm、调度器、内存管理、网络、存储(有开源贡献、实际代码开发项目经验的优先)；\n2、了解/熟悉Linux系统下通用的问题分析工具链使用，如ebpf，perf，ftrace，kprobe等；\n3、深入理解x86/arm cpu架构或者异构硬件架构，有相关的调研、调优经验；\n4、分析问题有专研精神，做到刨根问底。解决问题有长远意识，底层组件需要做到足够优雅。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139118","sourceKey":"tencent","company":"腾讯","title":"腾讯云—基于大模型异构分布式推理性能优化研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139118","duty":"课题背景：\n随着大模型技术的快速发展，模型架构日趋多样化——从稠密Transformer到稀疏MoE（如DeepSeek-V3），从纯文本到多模态融合，从单轮问答到具备深度推理能力的Reasoning Model——部署模型的规模越来越大，相关服务的QPS也在不断增加，服务的任务种类也在不断增多且各不相同，例如文本摘要服务、对话与Agent服务、图片/视频生成服务、深度推理服务等。各种服务对推理引擎的挑战也各不相同。同样是长序列，文本摘要服务的输入Prompt通常很长，因此TTFT是关键；对话与Agent服务更关注TPOT与多轮交互延迟；图片/视频生成服务则更强调E2E Latency；而Reasoning Model需要支持超长思维链输出，对Decode吞吐提出极高要求。即使是短序列，遇到长序列时也会产生P99问题。这些问题结合当前Prefill和Decode两阶段不同的计算特性、PD分离等新型架构模式的成熟落地、以及日益增大的模型体量与部署规模，给大模型推理引擎和服务带来了巨大挑战。与此同时，推理引擎的性能最终依赖于底层算子的执行效率，而传统由工程师针对每种硬件平台（NVIDIA GPU、国产NPU等）手工编写和调优算子的模式，已难以跟上模型结构快速迭代与多硬件生态并存的节奏。本课题的目标是设计开发一款面向通用场景的分布式大模型推理引擎，同时探索构建一套面向多硬件平台的高性能算子DSL及自动调优编译器，实现从推理服务调度到底层算子生成的全栈极致优化。\n\n课题挑战：\n1、在通用场景下，面对不同长度、不同模态和不同种类的大模型请求服务（包括MoE动态路由、超长上下文、多模态混合、深度推理等），满足各自的TTFT、TPOT及P99要求；\n2、在上述前提条件下，做到最大化资源利用率，通过PD分离、Speculative Decoding、KV Cache智能管理等技术将单Token的成本降到最低；\n3、探索面向多硬件平台的算子DSL与编译优化技术，支持从统一算子描述自动生成多后端高性能代码，降低算子开发与跨平台适配成本，使编译生成的算子性能逼近专家手工优化水平。\n\n具体工作：\n1、参与到大模型推理引擎工程项目中的核心开发工作，涵盖PD分离调度、KV Cache管理、多模态Pipeline、MoE动态路由等关键模块并产出成果，其成果的产出能够给我们的大模型推理引擎技术带来直接价值——产品、技术竞争力的提升，从而获得极致的成本优化，带来直接的经济收益；\n2、参与面向多硬件平台的高性能算子DSL设计与编译器开发，构建从算子描述到多后端代码生成的自动化工具链，大幅降低算子跨平台适配成本，加速国产AI芯片生态建设；\n3、在参与公司、知名厂商及高校合作中，建立行业技术影响力与标杆项目，推动AI基础软件开源生态发展，最终吸引企业用户使用腾讯云的产品；\n4、在当前的AI浪潮中，参与AI重构移动互联网应用，以推理引擎与编译优化的核心能力推动行业深刻变革。","requirements":"1、深入理解主流大模型架构，包括Transformer及其注意力机制变体（MHA/GQA/MLA等）、MoE稀疏架构、以及多模态相关模型（ViT、VAE、Diffusion等），能够针对不同架构特点进行推理优化；\n2、扎实的系统编程与GPU编程能力，熟练使用C/C++和Python，至少掌握CUDA/CUTLASS/Triton中的一种；熟悉MLIR/LLVM编译基础设施或有AI编译器开发经验者优先；\n3、熟悉大模型推理引擎的核心技术，包括Attention优化（FlashAttention系列、FlashDecoding等）、KV Cache管理（PagedAttention等）、量化部署（GPTQ/AWQ/FP8等），并有vLLM、SGLang、TensorRT-LLM等主流框架的实际使用或开发经验；\n4、具备分布式推理系统设计与优化经验，理解PD分离、Speculative Decoding、Chunked Prefill等架构模式，熟悉TP/SP/EP/CP等并行策略，能针对不同业务场景进行调度与资源优化；\n5、了解高性能网络通信技术（RDMA、NVLink、NVSwitch等），能在多机多卡集群环境下进行通信性能调优。","description":"课题描述\n课题背景：\n随着大模型技术的快速发展，模型架构日趋多样化——从稠密Transformer到稀疏MoE（如DeepSeek-V3），从纯文本到多模态融合，从单轮问答到具备深度推理能力的Reasoning Model——部署模型的规模越来越大，相关服务的QPS也在不断增加，服务的任务种类也在不断增多且各不相同，例如文本摘要服务、对话与Agent服务、图片/视频生成服务、深度推理服务等。各种服务对推理引擎的挑战也各不相同。同样是长序列，文本摘要服务的输入Prompt通常很长，因此TTFT是关键；对话与Agent服务更关注TPOT与多轮交互延迟；图片/视频生成服务则更强调E2E Latency；而Reasoning Model需要支持超长思维链输出，对Decode吞吐提出极高要求。即使是短序列，遇到长序列时也会产生P99问题。这些问题结合当前Prefill和Decode两阶段不同的计算特性、PD分离等新型架构模式的成熟落地、以及日益增大的模型体量与部署规模，给大模型推理引擎和服务带来了巨大挑战。与此同时，推理引擎的性能最终依赖于底层算子的执行效率，而传统由工程师针对每种硬件平台（NVIDIA GPU、国产NPU等）手工编写和调优算子的模式，已难以跟上模型结构快速迭代与多硬件生态并存的节奏。本课题的目标是设计开发一款面向通用场景的分布式大模型推理引擎，同时探索构建一套面向多硬件平台的高性能算子DSL及自动调优编译器，实现从推理服务调度到底层算子生成的全栈极致优化。\n\n课题挑战：\n1、在通用场景下，面对不同长度、不同模态和不同种类的大模型请求服务（包括MoE动态路由、超长上下文、多模态混合、深度推理等），满足各自的TTFT、TPOT及P99要求；\n2、在上述前提条件下，做到最大化资源利用率，通过PD分离、Speculative Decoding、KV Cache智能管理等技术将单Token的成本降到最低；\n3、探索面向多硬件平台的算子DSL与编译优化技术，支持从统一算子描述自动生成多后端高性能代码，降低算子开发与跨平台适配成本，使编译生成的算子性能逼近专家手工优化水平。\n\n具体工作：\n1、参与到大模型推理引擎工程项目中的核心开发工作，涵盖PD分离调度、KV Cache管理、多模态Pipeline、MoE动态路由等关键模块并产出成果，其成果的产出能够给我们的大模型推理引擎技术带来直接价值——产品、技术竞争力的提升，从而获得极致的成本优化，带来直接的经济收益；\n2、参与面向多硬件平台的高性能算子DSL设计与编译器开发，构建从算子描述到多后端代码生成的自动化工具链，大幅降低算子跨平台适配成本，加速国产AI芯片生态建设；\n3、在参与公司、知名厂商及高校合作中，建立行业技术影响力与标杆项目，推动AI基础软件开源生态发展，最终吸引企业用户使用腾讯云的产品；\n4、在当前的AI浪潮中，参与AI重构移动互联网应用，以推理引擎与编译优化的核心能力推动行业深刻变革。\n\n课题要求\n1、深入理解主流大模型架构，包括Transformer及其注意力机制变体（MHA/GQA/MLA等）、MoE稀疏架构、以及多模态相关模型（ViT、VAE、Diffusion等），能够针对不同架构特点进行推理优化；\n2、扎实的系统编程与GPU编程能力，熟练使用C/C++和Python，至少掌握CUDA/CUTLASS/Triton中的一种；熟悉MLIR/LLVM编译基础设施或有AI编译器开发经验者优先；\n3、熟悉大模型推理引擎的核心技术，包括Attention优化（FlashAttention系列、FlashDecoding等）、KV Cache管理（PagedAttention等）、量化部署（GPTQ/AWQ/FP8等），并有vLLM、SGLang、TensorRT-LLM等主流框架的实际使用或开发经验；\n4、具备分布式推理系统设计与优化经验，理解PD分离、Speculative Decoding、Chunked Prefill等架构模式，熟悉TP/SP/EP/CP等并行策略，能针对不同业务场景进行调度与资源优化；\n5、了解高性能网络通信技术（RDMA、NVLink、NVSwitch等），能在多机多卡集群环境下进行通信性能调优。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139119","sourceKey":"tencent","company":"腾讯","title":"腾讯云—多模态大模型高精度蒸馏加速研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139119","duty":"课题背景：\n随着大语言模型（LLM）、扩散模型在生成式AI领域的广泛应用，模型规模持续扩大，带来了高算力消耗、高显存占用、推理延迟高的问题，严重制约其在端侧、边缘设备及低算力场景的落地。本课题聚焦模型蒸馏压缩技术，重点针对扩散模型与大语言模型，通过蒸馏、量化、剪枝等技术手段，在尽可能保留原模型精度与生成效果的前提下，实现模型轻量化，降低部署成本，推动生成式AI技术的规模化、低成本应用。\n\n课题挑战：\n1、精度与轻量化平衡的核心挑战：扩散模型的生成质量、大语言模型的语义理解与生成连贯性，对模型结构和参数依赖性极强，蒸馏过程中难以在大幅压缩模型体积（参数量、计算量）的同时，完全保留原模型的性能，易出现生成模糊、语义偏差、推理精度下降等问题。\n2、针对性蒸馏策略设计难度：扩散模型与大语言模型的模型结构、训练逻辑差异显著，需设计差异化蒸馏方案，适配两类模型的核心特性，避免通用蒸馏方法导致的性能损耗，同时优化蒸馏效率。\n3、工程化落地的技术瓶颈：蒸馏后的轻量化模型需适配不同部署场景（端侧、边缘、云端），需解决蒸馏过程中的训练稳定性、量化噪声、剪枝稀疏性带来的推理效率瓶颈；同时需兼顾蒸馏速度与模型泛化能力，避免过拟合，确保轻量化模型在复杂场景下的可靠运行。\n\n具体工作：\n1、负责扩散模型、大语言模型的蒸馏压缩方案设计与实现，结合两类模型特性，选用合适的蒸馏策略（如知识蒸馏、自蒸馏、量化蒸馏），制定模型压缩目标（参数量、计算量、推理延迟）。\n2、开展蒸馏模型的训练与优化，调试蒸馏温度、损失函数、蒸馏节奏等关键参数，解决蒸馏过程中精度下降、训练不稳定等问题，确保轻量化模型与原模型性能差距控制在可接受范围。\n3、配合工程团队，完成蒸馏后模型的量化、剪枝等后续优化，适配不同部署场景的需求，测试模型推理速度、显存占用情况，输出工程化落地方案；跟进模型蒸馏领域前沿技术，迭代优化蒸馏策略，提升压缩效率与模型性能。","requirements":"1、熟悉深度学习基础理论，掌握模型蒸馏核心原理，了解扩散模型（如Stable Diffusion）、大语言模型（如DeepSeek、Qwen等）的基本结构；\n2、熟练使用Python编程语言，掌握PyTorch/FSDP等深度学习框架，能独立完成模型训练与调试；\n3、具备良好的逻辑思维能力、问题解决能力，对模型加速、蒸馏方向有浓厚兴趣，愿意主动学习前沿技术；\n4、熟悉模型蒸馏、量化（INT8/INT4）、剪枝等常用模型压缩技术，有落地经验。","description":"课题描述\n课题背景：\n随着大语言模型（LLM）、扩散模型在生成式AI领域的广泛应用，模型规模持续扩大，带来了高算力消耗、高显存占用、推理延迟高的问题，严重制约其在端侧、边缘设备及低算力场景的落地。本课题聚焦模型蒸馏压缩技术，重点针对扩散模型与大语言模型，通过蒸馏、量化、剪枝等技术手段，在尽可能保留原模型精度与生成效果的前提下，实现模型轻量化，降低部署成本，推动生成式AI技术的规模化、低成本应用。\n\n课题挑战：\n1、精度与轻量化平衡的核心挑战：扩散模型的生成质量、大语言模型的语义理解与生成连贯性，对模型结构和参数依赖性极强，蒸馏过程中难以在大幅压缩模型体积（参数量、计算量）的同时，完全保留原模型的性能，易出现生成模糊、语义偏差、推理精度下降等问题。\n2、针对性蒸馏策略设计难度：扩散模型与大语言模型的模型结构、训练逻辑差异显著，需设计差异化蒸馏方案，适配两类模型的核心特性，避免通用蒸馏方法导致的性能损耗，同时优化蒸馏效率。\n3、工程化落地的技术瓶颈：蒸馏后的轻量化模型需适配不同部署场景（端侧、边缘、云端），需解决蒸馏过程中的训练稳定性、量化噪声、剪枝稀疏性带来的推理效率瓶颈；同时需兼顾蒸馏速度与模型泛化能力，避免过拟合，确保轻量化模型在复杂场景下的可靠运行。\n\n具体工作：\n1、负责扩散模型、大语言模型的蒸馏压缩方案设计与实现，结合两类模型特性，选用合适的蒸馏策略（如知识蒸馏、自蒸馏、量化蒸馏），制定模型压缩目标（参数量、计算量、推理延迟）。\n2、开展蒸馏模型的训练与优化，调试蒸馏温度、损失函数、蒸馏节奏等关键参数，解决蒸馏过程中精度下降、训练不稳定等问题，确保轻量化模型与原模型性能差距控制在可接受范围。\n3、配合工程团队，完成蒸馏后模型的量化、剪枝等后续优化，适配不同部署场景的需求，测试模型推理速度、显存占用情况，输出工程化落地方案；跟进模型蒸馏领域前沿技术，迭代优化蒸馏策略，提升压缩效率与模型性能。\n\n课题要求\n1、熟悉深度学习基础理论，掌握模型蒸馏核心原理，了解扩散模型（如Stable Diffusion）、大语言模型（如DeepSeek、Qwen等）的基本结构；\n2、熟练使用Python编程语言，掌握PyTorch/FSDP等深度学习框架，能独立完成模型训练与调试；\n3、具备良好的逻辑思维能力、问题解决能力，对模型加速、蒸馏方向有浓厚兴趣，愿意主动学习前沿技术；\n4、熟悉模型蒸馏、量化（INT8/INT4）、剪枝等常用模型压缩技术，有落地经验。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139120","sourceKey":"tencent","company":"腾讯","title":"腾讯云—高性能RL系统设计研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139120","duty":"课题背景：\nAI Infra强化学习工程师是连接强化学习算法与工程化落地的核心纽带，其工作直接决定LLM RL、Agentic RL等强化学习技术的部署效率、性能表现与规模化应用能力。当前强化学习在AI领域的应用场景持续拓展，大规模RL算法的高效落地成为企业技术竞争力的关键，该岗位通过构建高效分布式训练体系、优化训练工具链、解决工程化瓶颈，可显著提升GPU利用率与训练吞吐，降低技术落地成本，推动强化学习技术从算法研发走向实际业务应用，同时为企业搭建完善的AI Infra基础设施、储备核心技术人才提供重要支撑。\n\n课题挑战：\n1、大规模RL训练的性能优化挑战：需解决大规模RL算法（PPO、DQN、GRPO等）训练中的高并发、高吞吐难题，优化训推异步、partial rollout等核心机制，在千级GPU集群场景下，实现算力与显存的高效调度，突破GPU利用率瓶颈，同时规避样本传输延迟、数据一致性等问题。\n2、分布式训练体系的设计与优化难度：需深入掌握分布式训练原理，基于FSDP、DeepSpeed、Ray等工具，构建适配LLM RL、Agentic RL的分布式训练架构，解决模型并行、数据并行中的通信开销问题，同时优化Replay Buffer分布式存储与调度策略，平衡存储效率与样本读取速度，保障训练稳定性。\n3、工程化瓶颈的攻坚难度：需精准定位并解决RL训练中的核心技术痛点，包括GPU显存溢出、梯度爆炸/消失等训练稳定性问题，以及环境封装适配、工具链全流程联动等工程化难题；同时需跟进VERL、rllm等前沿技术，快速将技术转化为实际落地能力，适配多场景RL训练的动态需求。\n\n具体工作：\n1、负责LLM RL、Agentic RL强化学习训练框架的全流程设计、开发与性能优化，核心支撑PPO、DQN、GRPO等大规模RL算法的高效落地，适配不同业务场景的算法应用需求。\n2、构建高效分布式训练体系，重点优化训推异步、partial rollout、数据并行、模型并行等核心机制，同时优化Replay Buffer分布式存储与调度策略，最大化提升GPU利用率与训练吞吐效率。\n3、设计并实现强化学习训练全流程工具链，覆盖环境封装、数据预处理、模型版本管理、训练日志监控、TensorBoard/Weights & Biases指标可视化等关键环节，保障训练流程的规范化与高效化。\n4、跟踪强化学习与分布式训练领域前沿技术，包括VERL、rllm、Agentlightning、Ray、Megatron-LM等，将前沿技术转化为实际系统能力，持续提升基础设施的性能与竞争力。","requirements":"1、熟练掌握 Python 编程，具备扎实的工程编码能力，熟悉 C/C++ 者优先（底层优化场景）；​\n2、深入理解深度学习框架（PyTorch），精通分布式训练原理与实践（FSDP/DeepSpeed/Megatron/Ray 等工具使用经验）；​\n3、具备强化学习基础，理解 RL 训练流程（智能体、环境、奖励机制、经验回放等核心组件），熟悉主流 RL 框架（Ray、VERL、rllm、Agentlightning）者优先。","description":"课题描述\n课题背景：\nAI Infra强化学习工程师是连接强化学习算法与工程化落地的核心纽带，其工作直接决定LLM RL、Agentic RL等强化学习技术的部署效率、性能表现与规模化应用能力。当前强化学习在AI领域的应用场景持续拓展，大规模RL算法的高效落地成为企业技术竞争力的关键，该岗位通过构建高效分布式训练体系、优化训练工具链、解决工程化瓶颈，可显著提升GPU利用率与训练吞吐，降低技术落地成本，推动强化学习技术从算法研发走向实际业务应用，同时为企业搭建完善的AI Infra基础设施、储备核心技术人才提供重要支撑。\n\n课题挑战：\n1、大规模RL训练的性能优化挑战：需解决大规模RL算法（PPO、DQN、GRPO等）训练中的高并发、高吞吐难题，优化训推异步、partial rollout等核心机制，在千级GPU集群场景下，实现算力与显存的高效调度，突破GPU利用率瓶颈，同时规避样本传输延迟、数据一致性等问题。\n2、分布式训练体系的设计与优化难度：需深入掌握分布式训练原理，基于FSDP、DeepSpeed、Ray等工具，构建适配LLM RL、Agentic RL的分布式训练架构，解决模型并行、数据并行中的通信开销问题，同时优化Replay Buffer分布式存储与调度策略，平衡存储效率与样本读取速度，保障训练稳定性。\n3、工程化瓶颈的攻坚难度：需精准定位并解决RL训练中的核心技术痛点，包括GPU显存溢出、梯度爆炸/消失等训练稳定性问题，以及环境封装适配、工具链全流程联动等工程化难题；同时需跟进VERL、rllm等前沿技术，快速将技术转化为实际落地能力，适配多场景RL训练的动态需求。\n\n具体工作：\n1、负责LLM RL、Agentic RL强化学习训练框架的全流程设计、开发与性能优化，核心支撑PPO、DQN、GRPO等大规模RL算法的高效落地，适配不同业务场景的算法应用需求。\n2、构建高效分布式训练体系，重点优化训推异步、partial rollout、数据并行、模型并行等核心机制，同时优化Replay Buffer分布式存储与调度策略，最大化提升GPU利用率与训练吞吐效率。\n3、设计并实现强化学习训练全流程工具链，覆盖环境封装、数据预处理、模型版本管理、训练日志监控、TensorBoard/Weights & Biases指标可视化等关键环节，保障训练流程的规范化与高效化。\n4、跟踪强化学习与分布式训练领域前沿技术，包括VERL、rllm、Agentlightning、Ray、Megatron-LM等，将前沿技术转化为实际系统能力，持续提升基础设施的性能与竞争力。\n\n课题要求\n1、熟练掌握 Python 编程，具备扎实的工程编码能力，熟悉 C/C++ 者优先（底层优化场景）；​\n2、深入理解深度学习框架（PyTorch），精通分布式训练原理与实践（FSDP/DeepSpeed/Megatron/Ray 等工具使用经验）；​\n3、具备强化学习基础，理解 RL 训练流程（智能体、环境、奖励机制、经验回放等核心组件），熟悉主流 RL 框架（Ray、VERL、rllm、Agentlightning）者优先。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139121","sourceKey":"tencent","company":"腾讯","title":"腾讯云—海量多模态小模型的Serverless 推理技术研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139121","duty":"课题背景：\n在多模态数据处理与智能分析场景中，往往需要调用大量功能各异的专用小模型（SLM）完成视觉、语音、文本及跨模态推理任务。此类场景下模型数量繁多、调用模式呈现明显的长尾特征，传统的常驻式推理部署方式难以兼顾资源成本与弹性需求。为此，Serverless 推理服务成为支撑多模态小模型规模化部署的重要系统形态，但其在 GPU 资源利用率、模型切换与加载开销等方面仍面临较大挑战，亟需系统性的技术突破。\n\n课题挑战：\n1、冷启动开销优化：多模态小模型种类繁多，模型按需加载会引入显著的冷启动延迟，如何通过模型快照与运行时状态复用等技术手段有效降低启动成本，是核心挑战之一；\n2、GPU 资源高效复用：长尾调用模式导致 GPU 资源利用率低、碎片化严重，如何实现多模型间的 GPU 快速切换与细粒度复用，以提升整体资源利用效率，是关键技术难点；\n3、推理请求感知与调度：不同模态、不同优先级的推理请求在时延与吞吐需求上差异显著，如何设计请求感知的智能调度策略，在保障服务质量（SLO）的同时降低资源浪费，是重要的系统设计挑战；\n4、高弹性服务体系构建：如何将上述技术有机整合，构建兼具低时延、高弹性、低资源浪费的 Serverless 推理服务体系，并在真实业务场景下验证其可靠性与可扩展性。\n\n具体工作：\n你将参与多模态小模型 Serverless 推理服务的核心技术研发，围绕模型快照机制设计、运行时状态复用策略、GPU 复用与快速切换方案，以及推理请求感知调度算法等方向开展深入研究与工程实践，降低模型冷启动成本，提升 GPU 利用效率，推动构建高弹性、低时延、低资源浪费的推理服务体系落地。","requirements":"1、包含但不限于计算机、软件工程、人工智能、电子信息、自动化、信号与信息处理等相关专业的博士及优秀硕士；\n2、熟悉深度学习基本原理，熟练掌握 PyTorch、TensorFlow 等至少一个主流框架，了解模型推理流程与底层运行机制；\n3、具备良好的AI Coding技巧，善用AI提效工具，熟悉操作系统、虚拟化等底层知识，有 CUDA/GPU 编程经验者优先；\n4、了解 Serverless 或安全沙箱基本原理者优先；\n5、动手能力强，能独立完成系统模块的设计、实现与性能调优，有顶会论文发表或复现经验者优先。","description":"课题描述\n课题背景：\n在多模态数据处理与智能分析场景中，往往需要调用大量功能各异的专用小模型（SLM）完成视觉、语音、文本及跨模态推理任务。此类场景下模型数量繁多、调用模式呈现明显的长尾特征，传统的常驻式推理部署方式难以兼顾资源成本与弹性需求。为此，Serverless 推理服务成为支撑多模态小模型规模化部署的重要系统形态，但其在 GPU 资源利用率、模型切换与加载开销等方面仍面临较大挑战，亟需系统性的技术突破。\n\n课题挑战：\n1、冷启动开销优化：多模态小模型种类繁多，模型按需加载会引入显著的冷启动延迟，如何通过模型快照与运行时状态复用等技术手段有效降低启动成本，是核心挑战之一；\n2、GPU 资源高效复用：长尾调用模式导致 GPU 资源利用率低、碎片化严重，如何实现多模型间的 GPU 快速切换与细粒度复用，以提升整体资源利用效率，是关键技术难点；\n3、推理请求感知与调度：不同模态、不同优先级的推理请求在时延与吞吐需求上差异显著，如何设计请求感知的智能调度策略，在保障服务质量（SLO）的同时降低资源浪费，是重要的系统设计挑战；\n4、高弹性服务体系构建：如何将上述技术有机整合，构建兼具低时延、高弹性、低资源浪费的 Serverless 推理服务体系，并在真实业务场景下验证其可靠性与可扩展性。\n\n具体工作：\n你将参与多模态小模型 Serverless 推理服务的核心技术研发，围绕模型快照机制设计、运行时状态复用策略、GPU 复用与快速切换方案，以及推理请求感知调度算法等方向开展深入研究与工程实践，降低模型冷启动成本，提升 GPU 利用效率，推动构建高弹性、低时延、低资源浪费的推理服务体系落地。\n\n课题要求\n1、包含但不限于计算机、软件工程、人工智能、电子信息、自动化、信号与信息处理等相关专业的博士及优秀硕士；\n2、熟悉深度学习基本原理，熟练掌握 PyTorch、TensorFlow 等至少一个主流框架，了解模型推理流程与底层运行机制；\n3、具备良好的AI Coding技巧，善用AI提效工具，熟悉操作系统、虚拟化等底层知识，有 CUDA/GPU 编程经验者优先；\n4、了解 Serverless 或安全沙箱基本原理者优先；\n5、动手能力强，能独立完成系统模块的设计、实现与性能调优，有顶会论文发表或复现经验者优先。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139122","sourceKey":"tencent","company":"腾讯","title":"腾讯云—构建企业级MaaS后训练平台的技术研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139122","duty":"课题背景：\n随着大模型从通用能力走向行业落地，企业级MaaS平台需要为客户提供模型后训练（微调、对齐）服务，使通用模型适配金融、医疗、制造等垂直场景。然而，企业客户在算力成本、训练可控性等方面面临重重障碍，大量AI项目停留在验证阶段，难以规模化投产。如何构建高效、安全、易用的后训练服务体系，成为MaaS平台能否真正赋能产业的关键命题。\n\n课题挑战：\n一是成本与效率矛盾：后训练需要大量算力，中小企业难以承担，同时异构算力的调度与利用率优化是技术难点。二是效果可控性不足：微调后模型在垂直场景的精准性与通用能力的保持之间难以平衡，且缺乏统一的效果评估标准，客户对训练过程的透明度和可解释性要求日益提高。三是工程化挑战：多租户环境下的训练隔离、模型版本管理、持续迭代更新以及灰度发布等生产级能力尚不成熟，制约了后训练服务的规模化交付。\n\n具体工作：\n参与后训练流水线的设计与开发，包括微调策略实验与效果评测、训练任务调度优化，以及面向客户的低代码微调产品功能迭代。","requirements":"1、自然语言处理/机器学习/模式识别/人工智能/计算机等相关专业硕士以上学历；\n2、了解 LLM 训练全流程：预训练，SFT，RLHF/DPO；熟悉主流训练框架；\n3、了解分布式训练基本概念（数据并行、模型并行、Pipeline 并行、ZeRO）；\n4、对 Prompt Engineering、RAG、Agent、Function Calling 等应用技术有基本认知’\n5、关注 AI 行业动态，熟悉主流开源模型（LLaMA、Qwen、DeepSeek 等）；\n6、有高质量论文发表者优先（如ACL、EMNLP、NeurIPS、ICML、ICLR等)。","description":"课题描述\n课题背景：\n随着大模型从通用能力走向行业落地，企业级MaaS平台需要为客户提供模型后训练（微调、对齐）服务，使通用模型适配金融、医疗、制造等垂直场景。然而，企业客户在算力成本、训练可控性等方面面临重重障碍，大量AI项目停留在验证阶段，难以规模化投产。如何构建高效、安全、易用的后训练服务体系，成为MaaS平台能否真正赋能产业的关键命题。\n\n课题挑战：\n一是成本与效率矛盾：后训练需要大量算力，中小企业难以承担，同时异构算力的调度与利用率优化是技术难点。二是效果可控性不足：微调后模型在垂直场景的精准性与通用能力的保持之间难以平衡，且缺乏统一的效果评估标准，客户对训练过程的透明度和可解释性要求日益提高。三是工程化挑战：多租户环境下的训练隔离、模型版本管理、持续迭代更新以及灰度发布等生产级能力尚不成熟，制约了后训练服务的规模化交付。\n\n具体工作：\n参与后训练流水线的设计与开发，包括微调策略实验与效果评测、训练任务调度优化，以及面向客户的低代码微调产品功能迭代。\n\n课题要求\n1、自然语言处理/机器学习/模式识别/人工智能/计算机等相关专业硕士以上学历；\n2、了解 LLM 训练全流程：预训练，SFT，RLHF/DPO；熟悉主流训练框架；\n3、了解分布式训练基本概念（数据并行、模型并行、Pipeline 并行、ZeRO）；\n4、对 Prompt Engineering、RAG、Agent、Function Calling 等应用技术有基本认知’\n5、关注 AI 行业动态，熟悉主流开源模型（LLaMA、Qwen、DeepSeek 等）；\n6、有高质量论文发表者优先（如ACL、EMNLP、NeurIPS、ICML、ICLR等)。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139123","sourceKey":"tencent","company":"腾讯","title":"腾讯云—TCE 私有云AI Infra研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139123","duty":"课题背景：\n随着AI技术的不断发展和成熟，相对稳健的私有化客户也生长出旺盛的AI智算需求，其中包括两部分：\n1、Cloud for AI，通过云的基础设施支撑大模型训练推理等AI业务，包括多元GPU纳管、RDMA网络、高性能存储的设计与产品化\n2、AI for Cloud，通过AI推理等技术手段，打通日志、监控、告警等可观测性能力，实现云平台的智能自助排障与运维\n\n课题挑战：\n1、异构算力资源的高效纳管与调度：需兼容多品牌 GPU、解决显存分配粒度、异构算力协同，设计跨芯片架构的统一资源抽象层，避免单卡故障导致训练中断\n2、高性能存储系统的全链路优化：需突破NUMA架构下的存储缓存一致性问题，设计冷热数据分层策略以降低存储成本\n3、AI驱动的智能运维闭环构建：需训练高精度运维大模型（如基于Llama架构），实现故障根因分析（准确率>85%）、资源弹性扩缩容（预测误差\u003c10%），并设计自动化修复策略（如自动替换故障GPU）\n\n具体工作：\n1、异构算力基础设施研发，多元GPU纳管平台、RDMA网络优化\n2、高性能存储系统增强，存储底座升级\n3、AI推理引擎与工具链研发，AI推理服务治理，分布式推理框架优化\n4、智能运维自动化系统研发，基于历史运维数据构建领域语料库，进行AI运维大模型训练","requirements":"1、教育背景：计算机科学、软件工程、人工智能等相关专业的在读博士生和优秀硕士生，具备扎实的计算机系统与算法基础；\n2、研究能力：在以下至少一个领域有深入的研究或项目经验：\n云计算/分布式系统：熟悉Kubernetes、容器、虚拟化技术，对计算、存储、网络其中某一方向的底层原理有了解；\n3、人工智能/机器学习：熟悉大模型相关技术（如RAG、Agent、微调）、或经典的时序分析、异常检测算法，并有一定的动手实现能力。\n4、技术实践：出色的编程能力（Python/Go），有将学术想法转化为代码或原型系统的成功经验；\n5、个人特质：对挑战性难题有强烈的好奇心和驱动力，具备优秀的问题分析与解决能力，良好的沟通与团队协作精神。","description":"课题描述\n课题背景：\n随着AI技术的不断发展和成熟，相对稳健的私有化客户也生长出旺盛的AI智算需求，其中包括两部分：\n1、Cloud for AI，通过云的基础设施支撑大模型训练推理等AI业务，包括多元GPU纳管、RDMA网络、高性能存储的设计与产品化\n2、AI for Cloud，通过AI推理等技术手段，打通日志、监控、告警等可观测性能力，实现云平台的智能自助排障与运维\n\n课题挑战：\n1、异构算力资源的高效纳管与调度：需兼容多品牌 GPU、解决显存分配粒度、异构算力协同，设计跨芯片架构的统一资源抽象层，避免单卡故障导致训练中断\n2、高性能存储系统的全链路优化：需突破NUMA架构下的存储缓存一致性问题，设计冷热数据分层策略以降低存储成本\n3、AI驱动的智能运维闭环构建：需训练高精度运维大模型（如基于Llama架构），实现故障根因分析（准确率>85%）、资源弹性扩缩容（预测误差\u003c10%），并设计自动化修复策略（如自动替换故障GPU）\n\n具体工作：\n1、异构算力基础设施研发，多元GPU纳管平台、RDMA网络优化\n2、高性能存储系统增强，存储底座升级\n3、AI推理引擎与工具链研发，AI推理服务治理，分布式推理框架优化\n4、智能运维自动化系统研发，基于历史运维数据构建领域语料库，进行AI运维大模型训练\n\n课题要求\n1、教育背景：计算机科学、软件工程、人工智能等相关专业的在读博士生和优秀硕士生，具备扎实的计算机系统与算法基础；\n2、研究能力：在以下至少一个领域有深入的研究或项目经验：\n云计算/分布式系统：熟悉Kubernetes、容器、虚拟化技术，对计算、存储、网络其中某一方向的底层原理有了解；\n3、人工智能/机器学习：熟悉大模型相关技术（如RAG、Agent、微调）、或经典的时序分析、异常检测算法，并有一定的动手实现能力。\n4、技术实践：出色的编程能力（Python/Go），有将学术想法转化为代码或原型系统的成功经验；\n5、个人特质：对挑战性难题有强烈的好奇心和驱动力，具备优秀的问题分析与解决能力，良好的沟通与团队协作精神。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139124","sourceKey":"tencent","company":"腾讯","title":"腾讯云—微服务平台—AI 服务流量接入与治理基础设施研究","city":"杭州","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139124","duty":"课题背景：\n随着大模型和智能体的快速发展，传统微服务难以满足 AI 服务化、智能体协作、动态能力发现和统一治理需求。模型调用、Agent 协作和工具访问存在接口异构、流式交互、Token 计费及上下文管理等特性，为此，提出 “AI 服务流量接入与治理基础设施”课题，旨在构建一个统一的 AI 基础设施能力，提供服务接入、能力发现、流量治理和生态协同等能力，实现面向未来的 AI 服务治理与平台化支撑\n\n课题挑战：\n1、AI 服务类型复杂，包括 模型（LLM）、Agent、Tool、Skills、Workflow 等多种服务形态，其接口协议（如 OpenAI API、MCP、A2A 等）与调用模式高度异构，统一抽象与标准化治理难度较大\n2、AI 请求具有长连接、流式返回、Token 计费、上下文状态等特征，传统流量治理模型难以直接复用\n3、服务发现转换为动态能力发现、Tool 自动调用、跨 Agent 协作等问题，对AI基础设施元数据建模、能力标签、基于能力的服务发现机制提出更高要求。\n4、在保证高性能与低延迟的同时，实现多模型智能路由、能力统一发现和治理是该课题的关键技术挑战\n\n具体工作：\n参与AI 服务流量接入与治理基础设施的核心架构与关键技术研发，建设 AI 网关、Agent 网关与 AI 注册中心，实现模型、Agent、Tool 、Skills等 AI 服务的统一接入、注册发现与治理；研究多模型路由、Agent 协作、MCP 等协议集成，提升 AI 服务的稳定性与生态协同能力，包括以下三方面：\n1、LLM/MCP智能网关：用于优化、管理和保护AI模型的API访问与推理服务，能够优化完善如路由、认证、限流等功能，还能对大模型、深度学习推理进行了增强，提供动态负载均衡、智能流量调度、模型版本管理、A/B测试等能力\n2、智能体网关：集合 AI 注册中心，解决智能体如何行动、协作和完成指定的任务目标。重点解决AI智能体应用在智能体网关的注册、 发现 、注销、以及协同与管理问题，并能够完成存量应用向 A2A 协议的自动化升级能力\n3、统一管理大模型、Agent、MCP、Tool、Skills 等 AI 服务的智能路由与治理，构建统一的 AI 服务接入、能力发现、协议互操作、流量智能控制和治理、智能编排平台能力，保障 AI 服务的稳定运行与生态协同","requirements":"1、招聘硕士或博士，专业方向包括但不限于 计算机、人工智能、信息工程、软件工程、自动化、电子工程、应用数学、信息安全；\n2、熟悉大模型（LLM）、智能体（Agent）、多模型网关与服务注册发现相关理论与实践，了解 MCP、A2A 等协议；\n3、扎实的编程与工程能力，熟练掌握 Java、Go、C/C++、Python等至少一门语言；\n4、熟悉分布式系统和云原生架构开发，具备模型调用、路由与流量治理、Agent协作等开发经验者优先；\n5、具备良好的 算法分析、系统设计、架构实现能力，能够承担复杂SI平台及基础设施模块研发。","description":"课题描述\n课题背景：\n随着大模型和智能体的快速发展，传统微服务难以满足 AI 服务化、智能体协作、动态能力发现和统一治理需求。模型调用、Agent 协作和工具访问存在接口异构、流式交互、Token 计费及上下文管理等特性，为此，提出 “AI 服务流量接入与治理基础设施”课题，旨在构建一个统一的 AI 基础设施能力，提供服务接入、能力发现、流量治理和生态协同等能力，实现面向未来的 AI 服务治理与平台化支撑\n\n课题挑战：\n1、AI 服务类型复杂，包括 模型（LLM）、Agent、Tool、Skills、Workflow 等多种服务形态，其接口协议（如 OpenAI API、MCP、A2A 等）与调用模式高度异构，统一抽象与标准化治理难度较大\n2、AI 请求具有长连接、流式返回、Token 计费、上下文状态等特征，传统流量治理模型难以直接复用\n3、服务发现转换为动态能力发现、Tool 自动调用、跨 Agent 协作等问题，对AI基础设施元数据建模、能力标签、基于能力的服务发现机制提出更高要求。\n4、在保证高性能与低延迟的同时，实现多模型智能路由、能力统一发现和治理是该课题的关键技术挑战\n\n具体工作：\n参与AI 服务流量接入与治理基础设施的核心架构与关键技术研发，建设 AI 网关、Agent 网关与 AI 注册中心，实现模型、Agent、Tool 、Skills等 AI 服务的统一接入、注册发现与治理；研究多模型路由、Agent 协作、MCP 等协议集成，提升 AI 服务的稳定性与生态协同能力，包括以下三方面：\n1、LLM/MCP智能网关：用于优化、管理和保护AI模型的API访问与推理服务，能够优化完善如路由、认证、限流等功能，还能对大模型、深度学习推理进行了增强，提供动态负载均衡、智能流量调度、模型版本管理、A/B测试等能力\n2、智能体网关：集合 AI 注册中心，解决智能体如何行动、协作和完成指定的任务目标。重点解决AI智能体应用在智能体网关的注册、 发现 、注销、以及协同与管理问题，并能够完成存量应用向 A2A 协议的自动化升级能力\n3、统一管理大模型、Agent、MCP、Tool、Skills 等 AI 服务的智能路由与治理，构建统一的 AI 服务接入、能力发现、协议互操作、流量智能控制和治理、智能编排平台能力，保障 AI 服务的稳定运行与生态协同\n\n课题要求\n1、招聘硕士或博士，专业方向包括但不限于 计算机、人工智能、信息工程、软件工程、自动化、电子工程、应用数学、信息安全；\n2、熟悉大模型（LLM）、智能体（Agent）、多模型网关与服务注册发现相关理论与实践，了解 MCP、A2A 等协议；\n3、扎实的编程与工程能力，熟练掌握 Java、Go、C/C++、Python等至少一门语言；\n4、熟悉分布式系统和云原生架构开发，具备模型调用、路由与流量治理、Agent协作等开发经验者优先；\n5、具备良好的 算法分析、系统设计、架构实现能力，能够承担复杂SI平台及基础设施模块研发。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139125","sourceKey":"tencent","company":"腾讯","title":"腾讯云—自驾/具身（时空感知类模型）场景的系统优化研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139125","duty":"课题背景：\n随着自动驾驶向L4+级别演进，智驾模型训练面临三大核心困境：模型架构多样性导致传统并行训练框架难以适配BEV、YOLO等异构模型，特殊算子优化成为瓶颈；PB级多模态数据的预处理与训练资源竞争严重制约GPU利用率，拖慢迭代周期；VLM/VLA等大模型的端到端训练需求激增，千卡级集群的稳定性与效率挑战凸显。在具身智能场景下，这些挑战进一步加剧：多传感器融合（激光雷达、摄像头、毫米波雷达）产生更复杂的时空序列数据，强化学习训练需要实时环境交互与仿真回放，端到端决策模型对训练延迟和资源弹性提出更高要求。本课题旨在通过底层框架创新、算子深度优化与资源调度优化，构建面向自驾以及具身智能场景类的训练加速平台，实现训练效率的突破性提升，支撑模型快速迭代与商业化落地。\n\n课题挑战：\nL4 + 自动驾驶与具身智能场景中，BEV、VLM/VLA 等模型异构性强，多传感器时空数据复杂，传统训练框架难以统一适配。特殊算子优化、PB 级多模态数据预处理开销大，与训练任务资源竞争激烈。千卡级集群训练稳定性、并行效率与强化学习实时交互调度协同难度高，低延迟、高弹性的端到端训练加速方案落地极具挑战。\n\n具体工作：\n参与训练框架适配与算子优化，负责多模态数据预处理与特征工程，协助集群资源调度与训练加速模块开发，支撑自动驾驶与具身智能模型高效训练。","requirements":"1、熟悉深度学习框架（PyTorch/TensorFlow），了解分布式训练、并行策略优先；\n2、熟悉多模态数据、BEV、VLM 等智驾相关模型，有训练 / 推理优化经验优先；\n3、熟悉 GPU、算子优化、集群调度或数据处理者优先；\n4、在具身智能或自动驾驶领域发布高质量学术论文，能沉下心做底层系统与性能优化。","description":"课题描述\n课题背景：\n随着自动驾驶向L4+级别演进，智驾模型训练面临三大核心困境：模型架构多样性导致传统并行训练框架难以适配BEV、YOLO等异构模型，特殊算子优化成为瓶颈；PB级多模态数据的预处理与训练资源竞争严重制约GPU利用率，拖慢迭代周期；VLM/VLA等大模型的端到端训练需求激增，千卡级集群的稳定性与效率挑战凸显。在具身智能场景下，这些挑战进一步加剧：多传感器融合（激光雷达、摄像头、毫米波雷达）产生更复杂的时空序列数据，强化学习训练需要实时环境交互与仿真回放，端到端决策模型对训练延迟和资源弹性提出更高要求。本课题旨在通过底层框架创新、算子深度优化与资源调度优化，构建面向自驾以及具身智能场景类的训练加速平台，实现训练效率的突破性提升，支撑模型快速迭代与商业化落地。\n\n课题挑战：\nL4 + 自动驾驶与具身智能场景中，BEV、VLM/VLA 等模型异构性强，多传感器时空数据复杂，传统训练框架难以统一适配。特殊算子优化、PB 级多模态数据预处理开销大，与训练任务资源竞争激烈。千卡级集群训练稳定性、并行效率与强化学习实时交互调度协同难度高，低延迟、高弹性的端到端训练加速方案落地极具挑战。\n\n具体工作：\n参与训练框架适配与算子优化，负责多模态数据预处理与特征工程，协助集群资源调度与训练加速模块开发，支撑自动驾驶与具身智能模型高效训练。\n\n课题要求\n1、熟悉深度学习框架（PyTorch/TensorFlow），了解分布式训练、并行策略优先；\n2、熟悉多模态数据、BEV、VLM 等智驾相关模型，有训练 / 推理优化经验优先；\n3、熟悉 GPU、算子优化、集群调度或数据处理者优先；\n4、在具身智能或自动驾驶领域发布高质量学术论文，能沉下心做底层系统与性能优化。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139126","sourceKey":"tencent","company":"腾讯","title":"游戏AI算法研究","city":"成都","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139126","duty":"负责游戏AI的研发，突破传统基于API数据的开发模式，利用计算机视觉、模仿学习、强化学习与大模型技术，打造体验良好的指挥官AI。","requirements":"1、学历背景：计算机、人工智能、数学、模式识别等相关专业硕士及以上学历；\n2、核心算法能力：深入理解Transformer、CNN、视频理解及多模态对齐技术。熟悉模仿学习、强化学习和大模型微调；\n3、工程能力：熟练使用PyTorch等至少一种深度学习框架，熟悉C++/Python编程语言和常用数据结构，熟悉Linux开发环境，掌握脚本语言。\n4、综合素质：热爱游戏，良好的沟通能力，高度的责任心和团队合作精神，积极主动，乐于分享，能够快速复现前沿论文并进行工程化落地。\n\n加分项：\n1、学术成果：\n在CVPR,ICCV,ECCV,NIPS,ICML,AAAI等顶会发表过关于视频理解、模仿学习、强化学习、多模态决策方向的论文；\n2、项目经验：有Minecraft、ViZDoom、Atari等基于像素输入的游戏AI开发经验；\n3、竞赛经历：在Kaggle,MineRL等AI竞赛中获得过优异名次。","description":"课题描述\n负责游戏AI的研发，突破传统基于API数据的开发模式，利用计算机视觉、模仿学习、强化学习与大模型技术，打造体验良好的指挥官AI。\n\n课题要求\n1、学历背景：计算机、人工智能、数学、模式识别等相关专业硕士及以上学历；\n2、核心算法能力：深入理解Transformer、CNN、视频理解及多模态对齐技术。熟悉模仿学习、强化学习和大模型微调；\n3、工程能力：熟练使用PyTorch等至少一种深度学习框架，熟悉C++/Python编程语言和常用数据结构，熟悉Linux开发环境，掌握脚本语言。\n4、综合素质：热爱游戏，良好的沟通能力，高度的责任心和团队合作精神，积极主动，乐于分享，能够快速复现前沿论文并进行工程化落地。\n\n加分项：\n1、学术成果：\n在CVPR,ICCV,ECCV,NIPS,ICML,AAAI等顶会发表过关于视频理解、模仿学习、强化学习、多模态决策方向的论文；\n2、项目经验：有Minecraft、ViZDoom、Atari等基于像素输入的游戏AI开发经验；\n3、竞赛经历：在Kaggle,MineRL等AI竞赛中获得过优异名次。\n\nIEG\n互动娱乐事业群\n\n天美工作室群\n天美工作室群是腾讯游戏旗下的游戏研运团队。天美在诸多游戏细分领域潜心耕耘，建立了全球领先的核心研发能力。\n自2008年成立以来，天美持续推出多款热门产品，涵盖MOBA、RPG、射击、竞速、策略、休闲等多个品类，有丰富的跨平台研发经验。旗下作品包括《王者荣耀》、《三角洲行动》、《QQ飞车》、《穿越火线：枪战王者》、《元梦之星》、《逆战：未来》等多款知名游戏，为全球亿万用户提供卓越的游戏娱乐体验。同时，天美也是多个世界知名游戏厂商的合作伙伴，共同创造了如《使命召唤手游》、首款策略性宝可梦团队对战游戏《宝可梦大集结》和《帝国时代手游》等广受玩家欢迎的作品。\n在进行品类开拓的同时，天美亦致力于通过文创践行及电竞探索等方式，不断挖掘游戏的社会价值，为游戏赋能，将正能量传递给更多玩家。在天美，共创游戏的未来！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139127","sourceKey":"tencent","company":"腾讯","title":"大模型游戏推理项目","city":"成都","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139127","duty":"负责LLM、Agent在王者荣耀及相关生态游戏领域应用，能针对业务场景需求对模型进行设计和优化，包括但不限于游戏盘面推理、智能对话、游戏教学等。","requirements":"1、自然语言处理/机器学习/强化学习/模式识别/人工智能/计算机等相关专业硕士及以上学历；\n2、在LLM、NLP、强化学习、机器学习等方面有一定研究基础，熟悉主流模型和算法，关注领域内的最新进展，能够跟进和实现新的算法能力；\n3、熟练使用PyTorch等至少一种深度学习框架，熟悉C++/Python编程语言和常用数据结构，熟悉Linux开发环境，掌握脚本语言；\n4、具备良好的沟通能力，高度的责任心和团队合作精神，积极主动，乐于分享，能够快速复现前沿论文并进行工程化落地；\n5、具备良好的产品sense，鼓励参与设计讨论；\n6、王者资深玩家，对体验有自己的追求，能基于对游戏的理解把控数据和交付质量。\n\n加分项：\n1、学术成果：在ACL、EMNLP、NeurIPS、ICML、ICLR等会议或期刊上发表过关于大语言模型（LLM）、NLP、强化学习、机器学习等方面的论文；\n2、项目经验：有大语言模型（LLM）和NLP的实际业务经验，包括不限于剧情生成、可控NPC对话、聊天对话、逻辑推理、盘面推理等；\n3、竞赛经验：在kaggle等相关AI竞赛中获得过优异名次。","description":"课题描述\n负责LLM、Agent在王者荣耀及相关生态游戏领域应用，能针对业务场景需求对模型进行设计和优化，包括但不限于游戏盘面推理、智能对话、游戏教学等。\n\n课题要求\n1、自然语言处理/机器学习/强化学习/模式识别/人工智能/计算机等相关专业硕士及以上学历；\n2、在LLM、NLP、强化学习、机器学习等方面有一定研究基础，熟悉主流模型和算法，关注领域内的最新进展，能够跟进和实现新的算法能力；\n3、熟练使用PyTorch等至少一种深度学习框架，熟悉C++/Python编程语言和常用数据结构，熟悉Linux开发环境，掌握脚本语言；\n4、具备良好的沟通能力，高度的责任心和团队合作精神，积极主动，乐于分享，能够快速复现前沿论文并进行工程化落地；\n5、具备良好的产品sense，鼓励参与设计讨论；\n6、王者资深玩家，对体验有自己的追求，能基于对游戏的理解把控数据和交付质量。\n\n加分项：\n1、学术成果：在ACL、EMNLP、NeurIPS、ICML、ICLR等会议或期刊上发表过关于大语言模型（LLM）、NLP、强化学习、机器学习等方面的论文；\n2、项目经验：有大语言模型（LLM）和NLP的实际业务经验，包括不限于剧情生成、可控NPC对话、聊天对话、逻辑推理、盘面推理等；\n3、竞赛经验：在kaggle等相关AI竞赛中获得过优异名次。\n\nIEG\n互动娱乐事业群\n\n天美工作室群\n天美工作室群是腾讯游戏旗下的游戏研运团队。天美在诸多游戏细分领域潜心耕耘，建立了全球领先的核心研发能力。\n自2008年成立以来，天美持续推出多款热门产品，涵盖MOBA、RPG、射击、竞速、策略、休闲等多个品类，有丰富的跨平台研发经验。旗下作品包括《王者荣耀》、《三角洲行动》、《QQ飞车》、《穿越火线：枪战王者》、《元梦之星》、《逆战：未来》等多款知名游戏，为全球亿万用户提供卓越的游戏娱乐体验。同时，天美也是多个世界知名游戏厂商的合作伙伴，共同创造了如《使命召唤手游》、首款策略性宝可梦团队对战游戏《宝可梦大集结》和《帝国时代手游》等广受玩家欢迎的作品。\n在进行品类开拓的同时，天美亦致力于通过文创践行及电竞探索等方式，不断挖掘游戏的社会价值，为游戏赋能，将正能量传递给更多玩家。在天美，共创游戏的未来！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139128","sourceKey":"tencent","company":"腾讯","title":"和人类以语言沟通的智能NPC","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139128","duty":"课题背景：\n随着大语言模型（LLM）从“静态对话”向“动态交互智能体（Agentic NPC）”演进，游戏已成为检验通用人工智能（AGI）逻辑推理与交互的场景。当前NPC面临“感知-决策-表达”链路冗长、长时记忆遗忘、以及缺乏环境反馈驱动的自进化能力等瓶颈。本课题旨在利用LLM前沿技术，赋予智能NPC深度理解游戏世界观、实时多模态交互及复杂意图规划的能力。通过构建基于环境反馈的强化学习与记忆增强架构，打造具备高度拟人化性格、社会关系感知及实时策略执行能力的智能NPC，重新定义下一代游戏的沉浸感。\n\n课题挑战：\n1、高动态环境下的实时语义决策： 如何在大规模开放世界中，让NPC在毫秒级延迟内完成从“环境观测”到“自然语言动作指令”的端到端转化；\n2、长程记忆与一致性人格构建： 如何突破Transformer上下文窗口限制，通过向量数据库与知识图谱的深度融合，实现NPC跨周期的记忆保存与性格稳定性；\n3、情感对齐与价值观约束： 如何在复杂的游戏剧情分支中，确保LLM生成的回复既符合角色设定（Role-play），又具备高情商的交互反馈，且不偏离正向表达；\n4、群体智能的协同与演化： 如何设计多智能体通信协议（Agent-to-Agent Communication），实现NPC之间的信息共享、分工协作及自发的社会化行为演进。\n\n具体工作：\n1、游戏垂直大模型微调与对齐： 负责游戏场景下大语言模型的SFT（监督微调）与偏好对齐（RLHF/DPO/PPO），优化NPC的对话风格、角色一致性及逻辑推理能力；\n2、Agentic工作流与架构设计： 设计并实现NPC智能体架构，包括长短时记忆系统（Memory Bank）、工具调用（Tool Use）、多级规划（Planning）及基于环境感知的动作决策闭环；\n3、高质量语料合成与自动化评估： 针对游戏特定世界观与剧情需求，构建基于LLM的自动化数据生成管线（Self-Instruct/Evol-Instruct），并开发针对NPC智能程度与人格魅力的量化评估体系；\n4、实时对话与推理加速优化： 配合工程团队，针对NPC实时交互需求，进行模型蒸馏、量化及KV Cache优化等技术攻坚，降低推理首字延迟与算力成本；\n5、多模态交互与社会化演进： 探索文本、语音、动作同步生成的多模态技术，研究多NPC环境下的群体行为涌现与社会关系建模，提升游戏生态的动态多样性。","requirements":"基本素质：\n1、深厚的学术/理论底蕴： 具备计算机科学、计算语言学或认知科学背景，对Transformer架构、主流LLM（如GPT系列、Llama系列）的底层机制有透彻理解；\n2、极强的逻辑抽象能力： 能够将复杂的游戏玩法解构为可工程化的Prompt管道或状态机，擅长从繁杂的非结构化数据中提取关键特征；\n3、前瞻性的科研视野： 持续追踪NLP与Agent领域的最新进展（如Reasoning Models、World Models、Small Language Models），能够判断技术落地趋势；\n4、结果导向的极客精神： 不满足于SOTA模型的简单调用，具备深入底层优化模型表现、解决长尾问题的抗压能力与好奇心。\n\n技能要求：\n1、核心硬实力： 熟练使用 PyTorch，精通 SFT (监督微调)、RLHF/DPO (偏好对齐) 等流程；\n2、Agent开发经验： 熟悉 LangChain、AutoGPT 或类似框架，有 RAG (检索增强生成) 或 CoT (思维链) 调优经验者优先。","description":"课题描述\n课题背景：\n随着大语言模型（LLM）从“静态对话”向“动态交互智能体（Agentic NPC）”演进，游戏已成为检验通用人工智能（AGI）逻辑推理与交互的场景。当前NPC面临“感知-决策-表达”链路冗长、长时记忆遗忘、以及缺乏环境反馈驱动的自进化能力等瓶颈。本课题旨在利用LLM前沿技术，赋予智能NPC深度理解游戏世界观、实时多模态交互及复杂意图规划的能力。通过构建基于环境反馈的强化学习与记忆增强架构，打造具备高度拟人化性格、社会关系感知及实时策略执行能力的智能NPC，重新定义下一代游戏的沉浸感。\n\n课题挑战：\n1、高动态环境下的实时语义决策： 如何在大规模开放世界中，让NPC在毫秒级延迟内完成从“环境观测”到“自然语言动作指令”的端到端转化；\n2、长程记忆与一致性人格构建： 如何突破Transformer上下文窗口限制，通过向量数据库与知识图谱的深度融合，实现NPC跨周期的记忆保存与性格稳定性；\n3、情感对齐与价值观约束： 如何在复杂的游戏剧情分支中，确保LLM生成的回复既符合角色设定（Role-play），又具备高情商的交互反馈，且不偏离正向表达；\n4、群体智能的协同与演化： 如何设计多智能体通信协议（Agent-to-Agent Communication），实现NPC之间的信息共享、分工协作及自发的社会化行为演进。\n\n具体工作：\n1、游戏垂直大模型微调与对齐： 负责游戏场景下大语言模型的SFT（监督微调）与偏好对齐（RLHF/DPO/PPO），优化NPC的对话风格、角色一致性及逻辑推理能力；\n2、Agentic工作流与架构设计： 设计并实现NPC智能体架构，包括长短时记忆系统（Memory Bank）、工具调用（Tool Use）、多级规划（Planning）及基于环境感知的动作决策闭环；\n3、高质量语料合成与自动化评估： 针对游戏特定世界观与剧情需求，构建基于LLM的自动化数据生成管线（Self-Instruct/Evol-Instruct），并开发针对NPC智能程度与人格魅力的量化评估体系；\n4、实时对话与推理加速优化： 配合工程团队，针对NPC实时交互需求，进行模型蒸馏、量化及KV Cache优化等技术攻坚，降低推理首字延迟与算力成本；\n5、多模态交互与社会化演进： 探索文本、语音、动作同步生成的多模态技术，研究多NPC环境下的群体行为涌现与社会关系建模，提升游戏生态的动态多样性。\n\n课题要求\n基本素质：\n1、深厚的学术/理论底蕴： 具备计算机科学、计算语言学或认知科学背景，对Transformer架构、主流LLM（如GPT系列、Llama系列）的底层机制有透彻理解；\n2、极强的逻辑抽象能力： 能够将复杂的游戏玩法解构为可工程化的Prompt管道或状态机，擅长从繁杂的非结构化数据中提取关键特征；\n3、前瞻性的科研视野： 持续追踪NLP与Agent领域的最新进展（如Reasoning Models、World Models、Small Language Models），能够判断技术落地趋势；\n4、结果导向的极客精神： 不满足于SOTA模型的简单调用，具备深入底层优化模型表现、解决长尾问题的抗压能力与好奇心。\n\n技能要求：\n1、核心硬实力： 熟练使用 PyTorch，精通 SFT (监督微调)、RLHF/DPO (偏好对齐) 等流程；\n2、Agent开发经验： 熟悉 LangChain、AutoGPT 或类似框架，有 RAG (检索增强生成) 或 CoT (思维链) 调优经验者优先。\n\nIEG\n互动娱乐事业群\n\n魔方工作室群\n魔方工作室群（Morefun Studios），专注于动作、射击、大世界、RPG等多品类精品游戏研发与运营 。 魔方自 2010 年成立以来持续推出多款热门游戏，旗下代表产品包括《火影忍者手游》、《暗区突围》手游、《暗区突围：无限》、《洛克王国》、《洛克王国：世界》、《王牌战士》、《异人之下》游戏、《航海王：壮志雄心》等。 \n魔方人以“风骚狂热，极致进取”要求自我，致力于完成“创造时代游戏，链接全球玩家”的使命。\n 满怀热枕！爱与梦想兼顾！在魔方，你可以成为任何你想成为的人。 加入魔方，MOREFUN TOGETHER！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139129","sourceKey":"tencent","company":"腾讯","title":"游戏视频生成项目","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139129","duty":"课题背景：\n游戏 PV 与物料生产依赖 AI 视频技术的高审美、强一致与可编辑能力。当前瓶颈包括：大位移运镜与多角色/镜头外入画下的人物一致性不足；成片人物体型微调缺乏可用的身份保持编辑管线；物品/道具的替换、插入与属性修改在长视频中时序一致性与稳定性不足。本课题围绕游戏 PV 场景，攻关身份一致视频生成、基于 3D 先验的人物/物品编辑，为游戏视觉内容生产提供可落地方案。\n\n课题挑战：\n1、大位移运镜下人物身份漂移：强相机运动下身份 embedding 难以稳定传递，需在不牺牲运镜自由度的前提下实现跨帧、跨视角的身份锚定；\n2、多角色与镜头外角色一致性：多角色同框需分别维持身份且不串身份；画外入画角色缺乏延迟参考机制；\n3、成片人物体型编辑与身份保持：体型调整需兼顾身份、动作与光照；需引入 3D 人体先验（如 SMPL/SMPL-X）做参数化与引导；\n4、视频中物品编辑与一致性：物品替换/插入需跨帧一致、与运动与透视协调，多物体编辑需避免干扰与伪影；\n5、游戏场景审美与管线适配：在有限参考下适配不同美术风格，将生成与编辑能力整合为可嵌入 DCC/剪辑的管线。\n\n具体工作：\n1、大位移运镜下的身份一致视频生成：复现/改进 ContextAnyone、Wan-Move/CameraCtrl 等，将参考图/身份与运镜联合建模，设计跨帧或 trajectory-aware 特征传递。\n2、多角色及镜头外一致性：研究多身份并行锚定与延迟参考注入，构建游戏向多角色、多镜头评测数据；\n3、基于 3D 先验的人物体型编辑：用 SMPL/SMPL-X 做姿态与形状估计与编辑，结合 Odo、DiffBody、Motionshop 等做扩散修复与身份保持；\n4、视频物品编辑与替换：实践 VideoPainter、EditCtrl、InVi 等，支持插入/替换/删除/属性修改，构建 mask/参考图驱动的游戏向编辑管线；\n5、数据与评测：构建含运镜、多角色、体型编辑、物品编辑的 PV 评测集与指标（身份/体型/物品一致性、视觉质量）；\n6、管线集成与验证：将生成与编辑模块抽象为可配置管线，对接现有素材与工作流，做端到端验证并输出技术报告与接口方案。","requirements":"基本素质：\n1、扎实的视觉与几何基础：熟悉扩散模型、视频生成与 3D 人体建模（如 SMPL/SMPL-X）；\n2、较强的文献与复现能力：能梳理身份一致生成、视频编辑等领域最新工作并在 PyTorch 下复现与改进；\n3、问题拆解与落地意识：能将游戏 PV、人物修型、物品编辑等需求拆解为可建模、可评测的技术问题；\n4、结果导向与抗压能力：在长时序、多角色、复杂运镜等长尾场景下具备调试与优化耐心。\n\n技能要求：\n1、核心硬实力：熟练 PyTorch；具备图像/视频扩散模型（Stable Diffusion、Wan、ComfyUI 等）训练或推理经验；了解 ControlNet、IP-Adapter、Reference-only 等；\n2、3D 与视频编辑：熟悉或可快速上手 SMPL/SMPL-X；有视频 inpainting、人体 reposing、物体级编辑/替换经验者优先；\n3、工程与协作：具备多模态评估与脚本化实验能力；可与美术、策划沟通并收敛为可执行方案。","description":"课题描述\n课题背景：\n游戏 PV 与物料生产依赖 AI 视频技术的高审美、强一致与可编辑能力。当前瓶颈包括：大位移运镜与多角色/镜头外入画下的人物一致性不足；成片人物体型微调缺乏可用的身份保持编辑管线；物品/道具的替换、插入与属性修改在长视频中时序一致性与稳定性不足。本课题围绕游戏 PV 场景，攻关身份一致视频生成、基于 3D 先验的人物/物品编辑，为游戏视觉内容生产提供可落地方案。\n\n课题挑战：\n1、大位移运镜下人物身份漂移：强相机运动下身份 embedding 难以稳定传递，需在不牺牲运镜自由度的前提下实现跨帧、跨视角的身份锚定；\n2、多角色与镜头外角色一致性：多角色同框需分别维持身份且不串身份；画外入画角色缺乏延迟参考机制；\n3、成片人物体型编辑与身份保持：体型调整需兼顾身份、动作与光照；需引入 3D 人体先验（如 SMPL/SMPL-X）做参数化与引导；\n4、视频中物品编辑与一致性：物品替换/插入需跨帧一致、与运动与透视协调，多物体编辑需避免干扰与伪影；\n5、游戏场景审美与管线适配：在有限参考下适配不同美术风格，将生成与编辑能力整合为可嵌入 DCC/剪辑的管线。\n\n具体工作：\n1、大位移运镜下的身份一致视频生成：复现/改进 ContextAnyone、Wan-Move/CameraCtrl 等，将参考图/身份与运镜联合建模，设计跨帧或 trajectory-aware 特征传递。\n2、多角色及镜头外一致性：研究多身份并行锚定与延迟参考注入，构建游戏向多角色、多镜头评测数据；\n3、基于 3D 先验的人物体型编辑：用 SMPL/SMPL-X 做姿态与形状估计与编辑，结合 Odo、DiffBody、Motionshop 等做扩散修复与身份保持；\n4、视频物品编辑与替换：实践 VideoPainter、EditCtrl、InVi 等，支持插入/替换/删除/属性修改，构建 mask/参考图驱动的游戏向编辑管线；\n5、数据与评测：构建含运镜、多角色、体型编辑、物品编辑的 PV 评测集与指标（身份/体型/物品一致性、视觉质量）；\n6、管线集成与验证：将生成与编辑模块抽象为可配置管线，对接现有素材与工作流，做端到端验证并输出技术报告与接口方案。\n\n课题要求\n基本素质：\n1、扎实的视觉与几何基础：熟悉扩散模型、视频生成与 3D 人体建模（如 SMPL/SMPL-X）；\n2、较强的文献与复现能力：能梳理身份一致生成、视频编辑等领域最新工作并在 PyTorch 下复现与改进；\n3、问题拆解与落地意识：能将游戏 PV、人物修型、物品编辑等需求拆解为可建模、可评测的技术问题；\n4、结果导向与抗压能力：在长时序、多角色、复杂运镜等长尾场景下具备调试与优化耐心。\n\n技能要求：\n1、核心硬实力：熟练 PyTorch；具备图像/视频扩散模型（Stable Diffusion、Wan、ComfyUI 等）训练或推理经验；了解 ControlNet、IP-Adapter、Reference-only 等；\n2、3D 与视频编辑：熟悉或可快速上手 SMPL/SMPL-X；有视频 inpainting、人体 reposing、物体级编辑/替换经验者优先；\n3、工程与协作：具备多模态评估与脚本化实验能力；可与美术、策划沟通并收敛为可执行方案。\n\nIEG\n互动娱乐事业群\n\n魔方工作室群\n魔方工作室群（Morefun Studios），专注于动作、射击、大世界、RPG等多品类精品游戏研发与运营 。 魔方自 2010 年成立以来持续推出多款热门游戏，旗下代表产品包括《火影忍者手游》、《暗区突围》手游、《暗区突围：无限》、《洛克王国》、《洛克王国：世界》、《王牌战士》、《异人之下》游戏、《航海王：壮志雄心》等。 \n魔方人以“风骚狂热，极致进取”要求自我，致力于完成“创造时代游戏，链接全球玩家”的使命。\n 满怀热枕！爱与梦想兼顾！在魔方，你可以成为任何你想成为的人。 加入魔方，MOREFUN TOGETHER！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139130","sourceKey":"tencent","company":"腾讯","title":"游戏实时多模态交互系统研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139130","duty":"近年来，深度学习技术的持续演进，尤其是大语言模型（LLM）的快速发展，推动语音处理领域取得了一系列关键突破。实时语音增强技术已显著提升，但在手机游戏等复杂声学环境（多源干扰、强非平稳噪声、回声与混响叠加、设备与链路差异显著）下，仍面临诸多工程与算法挑战。同时，自动语音识别（ASR）与语音合成（TTS）能力也在近年实现跨越式进展，其中合成语音在自然度、可懂度与表现力方面的提升尤为突出。\n\n更为重要的是，LLM与视觉理解、实时语音处理等能力的深度融合，正在重塑语音交互范式：系统不仅能够理解文本语义，还可在语音与视觉输入的共同约束下实现实时感知、推理与自然对话，从而支撑更高质量的多模态交互体验。在此背景下，游戏场景中的多模态交互需求持续扩展、新玩法不断涌现，这既对视觉处理与语音增强等底层能力提出更高标准，也为多模态交互技术在游戏中的落地应用打开了更广阔的空间。\n\n我们诚邀具备图像与视觉处理、语音信号处理、语音增强、语音识别、语音合成或大模型相关研究与工程背景，并具备扎实科研素养与落地实践能力的候选人加入团队，共同探索面向游戏场景的语音大模型及覆盖全链路的语音增强、识别与合成关键技术。","requirements":"1、学历专业：博士研究生或优秀硕士研究生，人工智能、计算机科学与技术等相关专业，，具有较强的深度学习相关背景技能和学习功底；\n2、有图像与视觉处理/自然语言处理/语音信号处理/语音合成/语音识别等相关背景知识；有相关项目落地经验的优先；\n3、有预训练技术，包括但不限于高效训练、强化学习，参与过研发音频、NLP相关的预训练模型及其下游应用者优先；\n4、熟练掌握PyTorch等深度学习框架，Python编程语言；\n5、发表过领域顶级会议文章（NeurIPS、ICML、ICLR、ACL、Interspeech、ICASSP等）、相关实习经验或者ACM竞赛获奖者优先。","description":"课题描述\n近年来，深度学习技术的持续演进，尤其是大语言模型（LLM）的快速发展，推动语音处理领域取得了一系列关键突破。实时语音增强技术已显著提升，但在手机游戏等复杂声学环境（多源干扰、强非平稳噪声、回声与混响叠加、设备与链路差异显著）下，仍面临诸多工程与算法挑战。同时，自动语音识别（ASR）与语音合成（TTS）能力也在近年实现跨越式进展，其中合成语音在自然度、可懂度与表现力方面的提升尤为突出。\n\n更为重要的是，LLM与视觉理解、实时语音处理等能力的深度融合，正在重塑语音交互范式：系统不仅能够理解文本语义，还可在语音与视觉输入的共同约束下实现实时感知、推理与自然对话，从而支撑更高质量的多模态交互体验。在此背景下，游戏场景中的多模态交互需求持续扩展、新玩法不断涌现，这既对视觉处理与语音增强等底层能力提出更高标准，也为多模态交互技术在游戏中的落地应用打开了更广阔的空间。\n\n我们诚邀具备图像与视觉处理、语音信号处理、语音增强、语音识别、语音合成或大模型相关研究与工程背景，并具备扎实科研素养与落地实践能力的候选人加入团队，共同探索面向游戏场景的语音大模型及覆盖全链路的语音增强、识别与合成关键技术。\n\n课题要求\n1、学历专业：博士研究生或优秀硕士研究生，人工智能、计算机科学与技术等相关专业，，具有较强的深度学习相关背景技能和学习功底；\n2、有图像与视觉处理/自然语言处理/语音信号处理/语音合成/语音识别等相关背景知识；有相关项目落地经验的优先；\n3、有预训练技术，包括但不限于高效训练、强化学习，参与过研发音频、NLP相关的预训练模型及其下游应用者优先；\n4、熟练掌握PyTorch等深度学习框架，Python编程语言；\n5、发表过领域顶级会议文章（NeurIPS、ICML、ICLR、ACL、Interspeech、ICASSP等）、相关实习经验或者ACM竞赛获奖者优先。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139131","sourceKey":"tencent","company":"腾讯","title":"游戏具身智能","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139131","duty":"课题背景：\n随着游戏产业迈向内容与体验驱动的新阶段，对游戏内人工智能（AI）提出了更高要求。传统游戏AI多依赖预设规则，行为刻板，难以适应复杂多变的开放游戏环境。为突破此瓶颈，我们提出“游戏具身智能”项目。本项目旨在研发新一代游戏AI技术，其核心是构建能够以游戏视觉、接口等多模态信息为输入，深度理解游戏语义、空间与任务的智能体。该智能体模拟人类“感知-决策-行动-反馈”的认知闭环，能通过端到端学习生成拟人化的决策与控制，并在环境中通过自我探索与反思持续进化策略，从而快速掌握并精通一类游戏。\n\n课题价值：\n项目成功后，将带来显著优势：一、创造高度拟人化的AI应用，如智能游戏虚拟主播、可交互的拟人AI队友等，极大增强游戏交互体验与可玩性；二、所训练的通用交互AI模型，其强大的环境理解与策略判断能力可迁移至游戏反外挂等场景，提升安全保障水平。综上所述，本项目是迈向通用游戏人工智能的关键一步，具有重要的技术价值与广阔的商业前景。\n\n课题挑战：\n1、高动态环境感知鲁棒性挑战：​​ 现有视觉模型对游戏画面中的遮挡、光影变化、特效干扰等​​容错性低​​，难以​​实时、精准​​地识别角色状态、环境威胁等多模态关键信息；\n​2. 毫秒级精准动作生成与物理协同挑战：​​ VLA模型需在​​极低延迟​​下将高层策略解析为精确的键鼠/触屏操作流，并​​无缝适配不同游戏引擎​​的物理规则，当前模型对复杂3D环境的物理预测存在显著偏差；\n​3. 长期一致性维持与跨域泛化挑战：​​ NPC需在长任务链中​​维持角色动机/情感的深度一致性​​，并实现​​知识向新游戏场景的迁移​​。现有技术难以平衡长时上下文记忆、推理效率与​​无监督跨域自适应​​；\n​​4. 安全可信的人机协作机制：​​ 在深度理解玩家意图并动态调整协作策略的同时，亟需​​严格约束​​大模型固有的​​行为，建立清晰的伦理边界与控制机制。\n\n具体工作：\n参与游戏具身智能的算法研发，包括但不限于VLA、VA、World Model、RL等模型架构设计，算法效果优化，在线算法实验验证等。","requirements":"基本素质：\n具备扎实的计算机科学、人工智能或应用数学理论基础，拥有跨学科的技术视野与深厚的学术素养。在游戏机器人VLA（Vision-Language-Action）领域，展现出极强的独立科研攻坚能力与前瞻性思维，能深入探索大模型在游戏复杂环境与智能决策中的融合应用。具备长期主义的科研精神，致力于将前沿理论转化为在游戏场景下具备高度可行性的技术原型与实验成果。\n\n技能要求：\n1、理论深度：在大模型、计算机视觉方面积淀深厚，熟练掌握指令微调、迁移学习、强化学习等关键技术，并能够将其创新应用于游戏场景下的VLA任务中；\n2、工程与实验能力：拥有出色的大模型工程化落地能力，精通面向游戏数据的高效合成与处理、大规模模型分布式训练，以及支持高实时交互的游戏场景推理部署与优化。\n\n学术成果：\n在CVPR、ACL、NeurIPS、ICML、ICLR等顶级会议发表过高质量论文，研究方向聚焦于大模型、游戏智能Agent，尤其在VLA相关领域有突出成果，体现出严谨的学术逻辑与技术创新潜力。","description":"课题描述\n课题背景：\n随着游戏产业迈向内容与体验驱动的新阶段，对游戏内人工智能（AI）提出了更高要求。传统游戏AI多依赖预设规则，行为刻板，难以适应复杂多变的开放游戏环境。为突破此瓶颈，我们提出“游戏具身智能”项目。本项目旨在研发新一代游戏AI技术，其核心是构建能够以游戏视觉、接口等多模态信息为输入，深度理解游戏语义、空间与任务的智能体。该智能体模拟人类“感知-决策-行动-反馈”的认知闭环，能通过端到端学习生成拟人化的决策与控制，并在环境中通过自我探索与反思持续进化策略，从而快速掌握并精通一类游戏。\n\n课题价值：\n项目成功后，将带来显著优势：一、创造高度拟人化的AI应用，如智能游戏虚拟主播、可交互的拟人AI队友等，极大增强游戏交互体验与可玩性；二、所训练的通用交互AI模型，其强大的环境理解与策略判断能力可迁移至游戏反外挂等场景，提升安全保障水平。综上所述，本项目是迈向通用游戏人工智能的关键一步，具有重要的技术价值与广阔的商业前景。\n\n课题挑战：\n1、高动态环境感知鲁棒性挑战：​​ 现有视觉模型对游戏画面中的遮挡、光影变化、特效干扰等​​容错性低​​，难以​​实时、精准​​地识别角色状态、环境威胁等多模态关键信息；\n​2. 毫秒级精准动作生成与物理协同挑战：​​ VLA模型需在​​极低延迟​​下将高层策略解析为精确的键鼠/触屏操作流，并​​无缝适配不同游戏引擎​​的物理规则，当前模型对复杂3D环境的物理预测存在显著偏差；\n​3. 长期一致性维持与跨域泛化挑战：​​ NPC需在长任务链中​​维持角色动机/情感的深度一致性​​，并实现​​知识向新游戏场景的迁移​​。现有技术难以平衡长时上下文记忆、推理效率与​​无监督跨域自适应​​；\n​​4. 安全可信的人机协作机制：​​ 在深度理解玩家意图并动态调整协作策略的同时，亟需​​严格约束​​大模型固有的​​行为，建立清晰的伦理边界与控制机制。\n\n具体工作：\n参与游戏具身智能的算法研发，包括但不限于VLA、VA、World Model、RL等模型架构设计，算法效果优化，在线算法实验验证等。\n\n课题要求\n基本素质：\n具备扎实的计算机科学、人工智能或应用数学理论基础，拥有跨学科的技术视野与深厚的学术素养。在游戏机器人VLA（Vision-Language-Action）领域，展现出极强的独立科研攻坚能力与前瞻性思维，能深入探索大模型在游戏复杂环境与智能决策中的融合应用。具备长期主义的科研精神，致力于将前沿理论转化为在游戏场景下具备高度可行性的技术原型与实验成果。\n\n技能要求：\n1、理论深度：在大模型、计算机视觉方面积淀深厚，熟练掌握指令微调、迁移学习、强化学习等关键技术，并能够将其创新应用于游戏场景下的VLA任务中；\n2、工程与实验能力：拥有出色的大模型工程化落地能力，精通面向游戏数据的高效合成与处理、大规模模型分布式训练，以及支持高实时交互的游戏场景推理部署与优化。\n\n学术成果：\n在CVPR、ACL、NeurIPS、ICML、ICLR等顶级会议发表过高质量论文，研究方向聚焦于大模型、游戏智能Agent，尤其在VLA相关领域有突出成果，体现出严谨的学术逻辑与技术创新潜力。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139132","sourceKey":"tencent","company":"腾讯","title":"LLM实时推理","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139132","duty":"课题背景：\n游戏领域对实时性的严苛要求对大模型实时推理提出了更高要求，当前大模型推理能力的提升往往伴随推理耗时的增加，制约了低延时智能体在游戏场景的落地。本课题依托游戏场景具备干净可扩展的模拟环境的优势，研究大模型实时推理技术，面向实时推理场景探索复杂任务指令与高质量轨迹数据生成模拟环境构建、异步思考架构、大规模实时推理训练等技术，提升大模型推理质量和速度，从而构建高情商、高智商的单/多智能体系统。\n\n课题挑战：\n1、如何突破大模型”单脑慢思考“模式与人类”双脑快慢思考”模式间的差异；\n2、如何优化推理模型“思维链”质量，精简推理链长度、构建可曝光的推理链；\n3、如何打破模型推理能力对参数规模的依赖，通过架构优化、数据质量与奖励优化降低激活参数；\n4、如何构建模拟环境驱动的大规模数据合成与模型训练框架。\n\n具体工作：\n参与游戏场景大模型实时推理算法研发，包括但不限于大规模复杂推理数据合成与模拟环境构建、单智能体/多智能体实时推理架构设计、大模型实时推理训练等。","requirements":"基本素质：\n具备扎实的计算机科学、人工智能或应用数学理论基础，在人工智能领域有开阔的技术视野与优秀的研究能力。聚焦LLM实时推理、游戏智能体领域，展现出极强的独立科研攻坚能力与前瞻性思维，能深入探索游戏场景大模型实时推理技术。勇于挑战并突破技术瓶颈，具备长期主义精神。\n\n技能要求：\n熟练掌握大模型与智能体领域技术原理，如模型结构、智能体架构设计及模型后训练等技术，具备出色的大模型与智能体算法研究与工程化落地能力，擅长大规模的数据合成、分布式训练，能高效完成实验与技术验证。\n\n加分项：\n在大模型与智能体实时推理相关领域有突出成果，如NeurIPS/ICML/ICLR/ACL/CVPR 等人工智能领域顶级会议论文发表、高影响力技术报告/开源项目等。","description":"课题描述\n课题背景：\n游戏领域对实时性的严苛要求对大模型实时推理提出了更高要求，当前大模型推理能力的提升往往伴随推理耗时的增加，制约了低延时智能体在游戏场景的落地。本课题依托游戏场景具备干净可扩展的模拟环境的优势，研究大模型实时推理技术，面向实时推理场景探索复杂任务指令与高质量轨迹数据生成模拟环境构建、异步思考架构、大规模实时推理训练等技术，提升大模型推理质量和速度，从而构建高情商、高智商的单/多智能体系统。\n\n课题挑战：\n1、如何突破大模型”单脑慢思考“模式与人类”双脑快慢思考”模式间的差异；\n2、如何优化推理模型“思维链”质量，精简推理链长度、构建可曝光的推理链；\n3、如何打破模型推理能力对参数规模的依赖，通过架构优化、数据质量与奖励优化降低激活参数；\n4、如何构建模拟环境驱动的大规模数据合成与模型训练框架。\n\n具体工作：\n参与游戏场景大模型实时推理算法研发，包括但不限于大规模复杂推理数据合成与模拟环境构建、单智能体/多智能体实时推理架构设计、大模型实时推理训练等。\n\n课题要求\n基本素质：\n具备扎实的计算机科学、人工智能或应用数学理论基础，在人工智能领域有开阔的技术视野与优秀的研究能力。聚焦LLM实时推理、游戏智能体领域，展现出极强的独立科研攻坚能力与前瞻性思维，能深入探索游戏场景大模型实时推理技术。勇于挑战并突破技术瓶颈，具备长期主义精神。\n\n技能要求：\n熟练掌握大模型与智能体领域技术原理，如模型结构、智能体架构设计及模型后训练等技术，具备出色的大模型与智能体算法研究与工程化落地能力，擅长大规模的数据合成、分布式训练，能高效完成实验与技术验证。\n\n加分项：\n在大模型与智能体实时推理相关领域有突出成果，如NeurIPS/ICML/ICLR/ACL/CVPR 等人工智能领域顶级会议论文发表、高影响力技术报告/开源项目等。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139133","sourceKey":"tencent","company":"腾讯","title":"高品质影视级TTS","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139133","duty":"课题背景：\n传统 TTS 聚焦音质与清晰度，对情感维度（愉悦、悲伤、紧张、戏剧化等）的表达能力有限，往往无法精准传递文本蕴含的情绪或角色设定；而商用情感 TTS 仍存在数据昂贵、风格覆盖窄、推理耗时高与可控性弱等痛点。因此，本课题聚焦系统性攻克“高表现力+细粒度可控+跨风格泛化+低推理耗时”的高质量情感TTS全链路技术，打造下一代语音交互与内容生产工具。\n\n课题挑战：\n1、情感主观性与标注噪声：情绪标签主观性强，情感类别与强度边界模糊，如何解决监督信号不稳定的问题；\n2、文本语义-情感-韵律的耦合建模：情绪并非独立变量，受语义、上下文、角色设定、场景目标影响；韵律特征（F0、时长、能量、停顿）作为情感表达的主要载体，与情感意图之间呈高度非线性的一对多映射；\n3、可控性与自然度的矛盾：强控制可能引入生硬、机械或韵律崩坏，需要兼顾可控强度、连续可调与生成稳定性；\n4、音色与情感解耦：情绪变化易牵连声学特征导致音色漂移（speaker leakage），需要在赋予语音极致情感表现力的同时严格保持声纹稳定性；\n5、长文本/多轮对话的一致性：如何在长文本或多轮对话中保持跨句情感走向、语气一致性及角色人设的稳定，并处理引用、反问、讽刺等复杂语用现象。\n\n具体工作：\n参与情感TTS数据处理与建模实验，包括但不限于研究情感/韵律表征与可控生成，优化音色-情感解耦与长文本一致性，并完成客观指标+主观MOS/偏好评测与游戏场景验证。","requirements":"1、包含但不限于计算机科学、人工智能、模式识别、电子信息、通信工程、声学、自动化等相关专业的博士或优秀硕士；\n2、熟悉语音合成（TTS）或语音信号处理相关算法，了解Transformer、扩散模型、Flow Matching、语音编解码等技术；熟练使用PyTorch等深度学习框架，掌握Python编程语言；\n3、对语音合成和情感表达方向有浓厚研究兴趣，具备较强的文献阅读与问题分析能力，沟通协作意识好，自驱力强，能积极主动推动研究进展。","description":"课题描述\n课题背景：\n传统 TTS 聚焦音质与清晰度，对情感维度（愉悦、悲伤、紧张、戏剧化等）的表达能力有限，往往无法精准传递文本蕴含的情绪或角色设定；而商用情感 TTS 仍存在数据昂贵、风格覆盖窄、推理耗时高与可控性弱等痛点。因此，本课题聚焦系统性攻克“高表现力+细粒度可控+跨风格泛化+低推理耗时”的高质量情感TTS全链路技术，打造下一代语音交互与内容生产工具。\n\n课题挑战：\n1、情感主观性与标注噪声：情绪标签主观性强，情感类别与强度边界模糊，如何解决监督信号不稳定的问题；\n2、文本语义-情感-韵律的耦合建模：情绪并非独立变量，受语义、上下文、角色设定、场景目标影响；韵律特征（F0、时长、能量、停顿）作为情感表达的主要载体，与情感意图之间呈高度非线性的一对多映射；\n3、可控性与自然度的矛盾：强控制可能引入生硬、机械或韵律崩坏，需要兼顾可控强度、连续可调与生成稳定性；\n4、音色与情感解耦：情绪变化易牵连声学特征导致音色漂移（speaker leakage），需要在赋予语音极致情感表现力的同时严格保持声纹稳定性；\n5、长文本/多轮对话的一致性：如何在长文本或多轮对话中保持跨句情感走向、语气一致性及角色人设的稳定，并处理引用、反问、讽刺等复杂语用现象。\n\n具体工作：\n参与情感TTS数据处理与建模实验，包括但不限于研究情感/韵律表征与可控生成，优化音色-情感解耦与长文本一致性，并完成客观指标+主观MOS/偏好评测与游戏场景验证。\n\n课题要求\n1、包含但不限于计算机科学、人工智能、模式识别、电子信息、通信工程、声学、自动化等相关专业的博士或优秀硕士；\n2、熟悉语音合成（TTS）或语音信号处理相关算法，了解Transformer、扩散模型、Flow Matching、语音编解码等技术；熟练使用PyTorch等深度学习框架，掌握Python编程语言；\n3、对语音合成和情感表达方向有浓厚研究兴趣，具备较强的文献阅读与问题分析能力，沟通协作意识好，自驱力强，能积极主动推动研究进展。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139134","sourceKey":"tencent","company":"腾讯","title":"语音/对话驱动数字人","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139134","duty":"课题背景：\n随着大模型、语音生成、多模态建模与实时渲染技术的发展，语音/对话驱动数字人正成为智能交互、虚拟主播、游戏 NPC、数字员工等方向的重要技术基础。相比传统\"会说话\"的数字人，真实可用的系统不仅要完成口型同步，还需要在对话过程中保持身份稳定、情绪一致、表达自然、响应实时。本课题聚焦语音与数字人交叉方向，重点研究如何结合语音、文本、上下文与环境信息，驱动游戏数字人生成自然连贯的面部表情、口型、头部运动与肢体动作，提升数字人的真实感、陪伴感与交互能力。\n\n课题挑战：\n1、角色身份一致性保持: 在长对话和多轮交互中，数字人容易出现表情习惯、动作风格、人格气质不稳定的问题，难以在情绪表达变化的同时持续保持\"像这个角色在说话\"；\n2、语音—情绪—表情—动作的跨模态一致性: 现有方法往往只关注 lip-sync，容易出现\"口型对了但情绪不对\"\"语气强烈但表情平淡\"\"声音和动作不同步\"等跨模态冲突，缺乏覆盖语音韵律、面部表情、头部姿态、手势等多维度的统一情绪约束；\n3、长时序连续性与情绪自然过渡: 持续对话中数字人容易出现表情重复、动作僵硬、情绪漂移与状态跳变等问题，且真实情绪变化是连续渐变而非离散跳转，建模自然过渡比建模静态情绪困难得多；\n4、环境感知与上下文驱动不足: 数字人的表达应受场景、用户实时反馈与上下文语义的多层级影响，但目前系统在\"感知—理解—表达\"闭环上仍较弱，尚停留在被动回应而非主动感知；\n5、实时性与端到端效率挑战: 数字人应用要求低延迟、稳定输出与在线交互，但多模态生成与高保真渲染链路推理成本高，难以兼顾效果与实时性。\n\n具体工作：\n1、多模态输入到数字人驱动的可控生成框架 融合语音、文本、上下文、环境信息与角色设定，建立统一的情绪条件表示；以 3D 数字人为主、兼顾 2D 视频数字人，研究从语音/对话到表情、口型、头部和肢体动作的联合生成，支持情绪强度、风格、视线等可控调节；\n2、情绪一致性与长时序连续性建模 研究跨模态情绪约束与信号传递机制，解决语音、文本、表情、动作之间的情绪冲突；通过时序模型和状态记忆机制提升多轮对话中的情绪连贯性与自然过渡，缓解情绪漂移问题；\n3、实时推理与端到端链路优化 面向在线交互场景，优化从语音输入到数字人输出的完整链路，涉及模型量化、推理加速、流式生成等，兼顾生成质量、响应延迟与系统稳定性。","requirements":"基本素质：\n具备扎实的计算机科学、人工智能、计算机图形学或语音处理理论基础，拥有良好的跨学科技术视野与学术素养。在语音/对话驱动数字人领域，具备较强的独立科研能力与问题分析能力，能够围绕语音、文本、表情、动作与环境感知等多模态信息开展研究，探索数字人在真实交互场景下的情绪一致性、表达自然性与实时驱动问题。具备长期主义的科研精神，致力于将前沿模型与技术转化为具备实际应用价值的数字人原型与实验成果。\n\n技能要求：\n1、理论深度：在生成模型、多模态学习、计算机视觉、计算机图形学或语音技术方面具备扎实积累，熟悉 Transformer、Diffusion、时序建模、迁移学习等关键技术，并能够将其应用于语音/对话驱动数字人的核心任务中，如情绪一致性建模、音视频同步、表情与动作联合生成、长时序连续性优化等；\n2、工程与实验能力：具备较强的模型实现与实验推进能力，熟悉语音、视频与 3D 数字人相关的数据处理、训练与调试流程。了解或掌握SMPL-X标准骨骼、FLAME、blendshape、MetaHuman 等 3D 数字人表示与资产体系，并具备一定的实时推理优化、部署加速或端到端系统实现能力；\n3、学术成果：在 CVPR、SIGGRAPH、NeurIPS、ICML、ICLR、ACL、INTERSPEECH 等顶级会议发表过高质量论文者优先，研究方向聚焦于生成模型、多模态学习、语音交互、数字人等领域；在语音驱动生成、对话数字人、情绪建模、3D 人体/面部表示等相关方向有成果者优先。","description":"课题描述\n课题背景：\n随着大模型、语音生成、多模态建模与实时渲染技术的发展，语音/对话驱动数字人正成为智能交互、虚拟主播、游戏 NPC、数字员工等方向的重要技术基础。相比传统\"会说话\"的数字人，真实可用的系统不仅要完成口型同步，还需要在对话过程中保持身份稳定、情绪一致、表达自然、响应实时。本课题聚焦语音与数字人交叉方向，重点研究如何结合语音、文本、上下文与环境信息，驱动游戏数字人生成自然连贯的面部表情、口型、头部运动与肢体动作，提升数字人的真实感、陪伴感与交互能力。\n\n课题挑战：\n1、角色身份一致性保持: 在长对话和多轮交互中，数字人容易出现表情习惯、动作风格、人格气质不稳定的问题，难以在情绪表达变化的同时持续保持\"像这个角色在说话\"；\n2、语音—情绪—表情—动作的跨模态一致性: 现有方法往往只关注 lip-sync，容易出现\"口型对了但情绪不对\"\"语气强烈但表情平淡\"\"声音和动作不同步\"等跨模态冲突，缺乏覆盖语音韵律、面部表情、头部姿态、手势等多维度的统一情绪约束；\n3、长时序连续性与情绪自然过渡: 持续对话中数字人容易出现表情重复、动作僵硬、情绪漂移与状态跳变等问题，且真实情绪变化是连续渐变而非离散跳转，建模自然过渡比建模静态情绪困难得多；\n4、环境感知与上下文驱动不足: 数字人的表达应受场景、用户实时反馈与上下文语义的多层级影响，但目前系统在\"感知—理解—表达\"闭环上仍较弱，尚停留在被动回应而非主动感知；\n5、实时性与端到端效率挑战: 数字人应用要求低延迟、稳定输出与在线交互，但多模态生成与高保真渲染链路推理成本高，难以兼顾效果与实时性。\n\n具体工作：\n1、多模态输入到数字人驱动的可控生成框架 融合语音、文本、上下文、环境信息与角色设定，建立统一的情绪条件表示；以 3D 数字人为主、兼顾 2D 视频数字人，研究从语音/对话到表情、口型、头部和肢体动作的联合生成，支持情绪强度、风格、视线等可控调节；\n2、情绪一致性与长时序连续性建模 研究跨模态情绪约束与信号传递机制，解决语音、文本、表情、动作之间的情绪冲突；通过时序模型和状态记忆机制提升多轮对话中的情绪连贯性与自然过渡，缓解情绪漂移问题；\n3、实时推理与端到端链路优化 面向在线交互场景，优化从语音输入到数字人输出的完整链路，涉及模型量化、推理加速、流式生成等，兼顾生成质量、响应延迟与系统稳定性。\n\n课题要求\n基本素质：\n具备扎实的计算机科学、人工智能、计算机图形学或语音处理理论基础，拥有良好的跨学科技术视野与学术素养。在语音/对话驱动数字人领域，具备较强的独立科研能力与问题分析能力，能够围绕语音、文本、表情、动作与环境感知等多模态信息开展研究，探索数字人在真实交互场景下的情绪一致性、表达自然性与实时驱动问题。具备长期主义的科研精神，致力于将前沿模型与技术转化为具备实际应用价值的数字人原型与实验成果。\n\n技能要求：\n1、理论深度：在生成模型、多模态学习、计算机视觉、计算机图形学或语音技术方面具备扎实积累，熟悉 Transformer、Diffusion、时序建模、迁移学习等关键技术，并能够将其应用于语音/对话驱动数字人的核心任务中，如情绪一致性建模、音视频同步、表情与动作联合生成、长时序连续性优化等；\n2、工程与实验能力：具备较强的模型实现与实验推进能力，熟悉语音、视频与 3D 数字人相关的数据处理、训练与调试流程。了解或掌握SMPL-X标准骨骼、FLAME、blendshape、MetaHuman 等 3D 数字人表示与资产体系，并具备一定的实时推理优化、部署加速或端到端系统实现能力；\n3、学术成果：在 CVPR、SIGGRAPH、NeurIPS、ICML、ICLR、ACL、INTERSPEECH 等顶级会议发表过高质量论文者优先，研究方向聚焦于生成模型、多模态学习、语音交互、数字人等领域；在语音驱动生成、对话数字人、情绪建模、3D 人体/面部表示等相关方向有成果者优先。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139135","sourceKey":"tencent","company":"腾讯","title":"高精3D数字角色驱动","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139135","duty":"课题背景：\n随着生成式人工智能、多模态大模型与数字人技术的快速发展，用户对于虚拟角色的交互体验提出了更高要求：数字人不仅需要“会说”，更需要“会理解、会表达、会行动”。在游戏 AI、虚拟助手、沉浸式交互等场景中，传统基于规则或单一模态驱动的动画生成方法，已难以满足角色动作自然性、语义一致性、情绪表达丰富性以及实时响应性的综合需求。因此，围绕基于 Diffusion Transformer（DiT）的动作生成架构、多模态驱动的表情与肢体协同生成、文本/语音/视觉/动作统一建模，以及面向实时交互场景的推理优化技术展开研究，具有重要的理论价值与应用意义。本课题聚焦数字角色在复杂交互环境中的“感知—理解—决策—表达”闭环能力，探索在用户指令约束下实时生成符合逻辑、自然流畅且可控的 3D 动作序列，构建语义、情绪与时空动态高度一致的多模态生成模型，并进一步推动视觉-语言-动作（VLA）统一框架在数字人驱动中的落地，为下一代高真实感、强交互性、可实时响应的智能数字角色提供核心技术支撑。","requirements":"1、计算机、人工智能等相关专业硕士或博士学位，在深度学习领域有扎实的理论功底；\n2、具有扎实的深度学习算法基础，具备扎实的大模型研发经验，有 Diffusion Models 和Autoregressive Models 序列建模经验，有数字角色动画相关方向顶级论文者优先；\n3、熟悉各类深度学习网络和算子底层实现细节，训练和推理模型调优，CPU/GPU加速，分布式训练推理加速，有实操经验优先；\n4、熟悉端到端预训练，熟悉 SFT、RL 微调等后续连流程；熟练使用 Python，精通 PyTorch框架；\n5、具备较强的学习能力、沟通能力、团队合作能力，有强烈的好奇心；\n6、在 CVPR、ICCV、ECCV、SIGGRAPH 等顶会发表过高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先。","description":"课题描述\n课题背景：\n随着生成式人工智能、多模态大模型与数字人技术的快速发展，用户对于虚拟角色的交互体验提出了更高要求：数字人不仅需要“会说”，更需要“会理解、会表达、会行动”。在游戏 AI、虚拟助手、沉浸式交互等场景中，传统基于规则或单一模态驱动的动画生成方法，已难以满足角色动作自然性、语义一致性、情绪表达丰富性以及实时响应性的综合需求。因此，围绕基于 Diffusion Transformer（DiT）的动作生成架构、多模态驱动的表情与肢体协同生成、文本/语音/视觉/动作统一建模，以及面向实时交互场景的推理优化技术展开研究，具有重要的理论价值与应用意义。本课题聚焦数字角色在复杂交互环境中的“感知—理解—决策—表达”闭环能力，探索在用户指令约束下实时生成符合逻辑、自然流畅且可控的 3D 动作序列，构建语义、情绪与时空动态高度一致的多模态生成模型，并进一步推动视觉-语言-动作（VLA）统一框架在数字人驱动中的落地，为下一代高真实感、强交互性、可实时响应的智能数字角色提供核心技术支撑。\n\n课题要求\n1、计算机、人工智能等相关专业硕士或博士学位，在深度学习领域有扎实的理论功底；\n2、具有扎实的深度学习算法基础，具备扎实的大模型研发经验，有 Diffusion Models 和Autoregressive Models 序列建模经验，有数字角色动画相关方向顶级论文者优先；\n3、熟悉各类深度学习网络和算子底层实现细节，训练和推理模型调优，CPU/GPU加速，分布式训练推理加速，有实操经验优先；\n4、熟悉端到端预训练，熟悉 SFT、RL 微调等后续连流程；熟练使用 Python，精通 PyTorch框架；\n5、具备较强的学习能力、沟通能力、团队合作能力，有强烈的好奇心；\n6、在 CVPR、ICCV、ECCV、SIGGRAPH 等顶会发表过高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139136","sourceKey":"tencent","company":"腾讯","title":"多模态动作生成大模型","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139136","duty":"课题背景：\n高质量的动画内容创作在当今影视、游戏、等行业中愈发重要, 其中基于3D资产的底层动画内容在质量、灵活性、交互体验等多方面尤为重要, 也是游戏制作中的重要一环. 工业界现有的3D动画制作管线存在高人力场地成本、时间周期长、资产复用率低等问题, 而学术届已有的3D动作生成方案在生成的内容质量、多样性、可控性方面还远达不到工业可用水平。\n基于以上现状, 本项目旨在开发一种先进的多模态3D动作生成系统，通过结合人工智能技术与海量3D资产数据，利用视觉、文本等多模态信息，自动可控地生成高质量的3D动画。该系统能够理解复杂的模态输入，结合数字资产制作(DCC)软件(maya、3dsmax, blender等), 可控、交互式地转化为精确的3D动作，极大地提升动画的制作效率和灵活性, 节省人力。此技术不仅可以广泛应用于游戏开发，还能服务于媒体宣发和影视制作行业，帮助从业者快速高效地创作出符合高标准的可用视觉资产。","requirements":"1、计算机、人工智能等相关专业硕士或博士学位，在深度学习领域有扎实的理论功底；\n2、深入理解主流多模态融合架构（例如 Single-stream、Double-stream 等），能够针对不同模态特征进行灵活的 Transformer 模块设计；\n3、熟悉端到端预训练、SFT、RL 微调等流程；\n4、熟练使用 Python，熟练使用 PyTorch 框架；\n5、具备 3D 骨骼动画或人体运动学（IK/FK、SMPL 等人体参数化模型）相关经验者优先；\n6、具备人体物理仿真（如 PhysX，Isaac Gym，MuJoCo）或基于强化学习的动作控制经验者优先；\n7、在 CVPR、ICCV、ECCV、SIGGRAPH 等顶会发表过高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先；\n8、具备极强的论文复现与改进能力，能够敏锐捕捉大语言模型、视频生成领域的最新技术并将其迁移至动作生成领域。","description":"课题描述\n课题背景：\n高质量的动画内容创作在当今影视、游戏、等行业中愈发重要, 其中基于3D资产的底层动画内容在质量、灵活性、交互体验等多方面尤为重要, 也是游戏制作中的重要一环. 工业界现有的3D动画制作管线存在高人力场地成本、时间周期长、资产复用率低等问题, 而学术届已有的3D动作生成方案在生成的内容质量、多样性、可控性方面还远达不到工业可用水平。\n基于以上现状, 本项目旨在开发一种先进的多模态3D动作生成系统，通过结合人工智能技术与海量3D资产数据，利用视觉、文本等多模态信息，自动可控地生成高质量的3D动画。该系统能够理解复杂的模态输入，结合数字资产制作(DCC)软件(maya、3dsmax, blender等), 可控、交互式地转化为精确的3D动作，极大地提升动画的制作效率和灵活性, 节省人力。此技术不仅可以广泛应用于游戏开发，还能服务于媒体宣发和影视制作行业，帮助从业者快速高效地创作出符合高标准的可用视觉资产。\n\n课题要求\n1、计算机、人工智能等相关专业硕士或博士学位，在深度学习领域有扎实的理论功底；\n2、深入理解主流多模态融合架构（例如 Single-stream、Double-stream 等），能够针对不同模态特征进行灵活的 Transformer 模块设计；\n3、熟悉端到端预训练、SFT、RL 微调等流程；\n4、熟练使用 Python，熟练使用 PyTorch 框架；\n5、具备 3D 骨骼动画或人体运动学（IK/FK、SMPL 等人体参数化模型）相关经验者优先；\n6、具备人体物理仿真（如 PhysX，Isaac Gym，MuJoCo）或基于强化学习的动作控制经验者优先；\n7、在 CVPR、ICCV、ECCV、SIGGRAPH 等顶会发表过高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先；\n8、具备极强的论文复现与改进能力，能够敏锐捕捉大语言模型、视频生成领域的最新技术并将其迁移至动作生成领域。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139137","sourceKey":"tencent","company":"腾讯","title":"面向角色控制的视频生成大模型","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139137","duty":"课题背景：\n随着大语言模型和视频生成技术的快速发展，通过视频引导生成3D游戏动画资产成为可能。本课题旨在探索视频生成模型在游戏角色领域的应用，构建从视频生成到角色动画资产的智能生成管道。通过结合视频生成模型的时序理解能力和游戏引擎的角色控制技术，实现文本驱动的角色动作、表情、交互行为的自动生成。这一方向将为深度学习生成式游戏引擎提供关键的内容生产能力，大幅降低角色动画制作成本，提升创作效率。\n\n课题挑战：\n1、视频-3D资产映射：如何从2D视频生成结果中提取可用的3D骨骼动画、蒙皮权重等游戏引擎可直接使用的参数化表示；\n2、多模态控制信号融合：探索文本、参考图像、骨骼约束等多种输入如何协同控制视频生成模型，保证角色动作的可控性和一致性；\n3、时序连贯性与物理合理性：生成的角色动作需满足运动学约束和物理规律，避免穿模、抖动等游戏中不可接受的瑕疵；\n4、角色交互场景生成：研究如何生成角色-角色、角色-场景的交互视频，并转化为游戏引擎中的动态事件序列。","requirements":"1、计算机、人工智能等相关专业硕士或博士学位，在深度学习领域有扎实的理论功底；\n2、具有扎实的深度学习算法基础，具备扎实的大模型研发经验，有Diffusion Models和 Autoregressive Models相关经验优先，有相关方向顶级论文者优先，有文生图文生视频实践经验者优先；\n3、熟悉各类深度学习网络和算子底层实现细节，训练和推理模型调优，CPU/GPU加速，分布式训练推理加速，有实操经验优先；\n4、熟悉端到端预训练，熟悉SFT、RL 微调等后续连流程；熟练使用Python，精通PyTorch框架；\n5、具备较强的学习能力、沟通能力、团队合作能力，有强烈的好奇心；\n6、在CVPR、ICCV、ECCV、SIGGRAPH 等顶会发表过高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先。","description":"课题描述\n课题背景：\n随着大语言模型和视频生成技术的快速发展，通过视频引导生成3D游戏动画资产成为可能。本课题旨在探索视频生成模型在游戏角色领域的应用，构建从视频生成到角色动画资产的智能生成管道。通过结合视频生成模型的时序理解能力和游戏引擎的角色控制技术，实现文本驱动的角色动作、表情、交互行为的自动生成。这一方向将为深度学习生成式游戏引擎提供关键的内容生产能力，大幅降低角色动画制作成本，提升创作效率。\n\n课题挑战：\n1、视频-3D资产映射：如何从2D视频生成结果中提取可用的3D骨骼动画、蒙皮权重等游戏引擎可直接使用的参数化表示；\n2、多模态控制信号融合：探索文本、参考图像、骨骼约束等多种输入如何协同控制视频生成模型，保证角色动作的可控性和一致性；\n3、时序连贯性与物理合理性：生成的角色动作需满足运动学约束和物理规律，避免穿模、抖动等游戏中不可接受的瑕疵；\n4、角色交互场景生成：研究如何生成角色-角色、角色-场景的交互视频，并转化为游戏引擎中的动态事件序列。\n\n课题要求\n1、计算机、人工智能等相关专业硕士或博士学位，在深度学习领域有扎实的理论功底；\n2、具有扎实的深度学习算法基础，具备扎实的大模型研发经验，有Diffusion Models和 Autoregressive Models相关经验优先，有相关方向顶级论文者优先，有文生图文生视频实践经验者优先；\n3、熟悉各类深度学习网络和算子底层实现细节，训练和推理模型调优，CPU/GPU加速，分布式训练推理加速，有实操经验优先；\n4、熟悉端到端预训练，熟悉SFT、RL 微调等后续连流程；熟练使用Python，精通PyTorch框架；\n5、具备较强的学习能力、沟通能力、团队合作能力，有强烈的好奇心；\n6、在CVPR、ICCV、ECCV、SIGGRAPH 等顶会发表过高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139138","sourceKey":"tencent","company":"腾讯","title":"满足工业生产要求的3D几何资产生成","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139138","duty":"本项目聚焦游戏美术工业化生产链路，主攻美术制作环节（区别于创意设计、艺术创作阶段）的全流程自动化升级，核心攻克3D几何资产智能生成难题。项目需兼顾三大核心标准：一是贴合游戏美术的艺术审美规范，保证资产视觉质感、风格统一性达标；二是适配主流游戏引擎、CAD设计工具的技术接口与格式规范，保障资产无缝导入、高效复用；三是符合工业级量产的精度、稳定性要求，杜绝兼容性缺陷与几何异常。\n\n项目核心追求是极致自动化率，通过算法赋能替代传统人工建模、拓扑、修型等重复性劳作，最大限度减少人工干预、降低人力成本，实现高质量3D几何资产的批量、快速、标准化生成，全面提速游戏美术生产效率，破解行业产能瓶颈。","requirements":"诚邀计算几何领域深耕者，或计算几何+3D智能生成复合型技术人才加盟，要求具备扎实的理论功底与工程实践能力，能够将计算几何算法与3D生成技术深度融合，落地工业级自动化生成方案。","description":"课题描述\n本项目聚焦游戏美术工业化生产链路，主攻美术制作环节（区别于创意设计、艺术创作阶段）的全流程自动化升级，核心攻克3D几何资产智能生成难题。项目需兼顾三大核心标准：一是贴合游戏美术的艺术审美规范，保证资产视觉质感、风格统一性达标；二是适配主流游戏引擎、CAD设计工具的技术接口与格式规范，保障资产无缝导入、高效复用；三是符合工业级量产的精度、稳定性要求，杜绝兼容性缺陷与几何异常。\n\n项目核心追求是极致自动化率，通过算法赋能替代传统人工建模、拓扑、修型等重复性劳作，最大限度减少人工干预、降低人力成本，实现高质量3D几何资产的批量、快速、标准化生成，全面提速游戏美术生产效率，破解行业产能瓶颈。\n\n课题要求\n诚邀计算几何领域深耕者，或计算几何+3D智能生成复合型技术人才加盟，要求具备扎实的理论功底与工程实践能力，能够将计算几何算法与3D生成技术深度融合，落地工业级自动化生成方案。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139139","sourceKey":"tencent","company":"腾讯","title":"基于游戏的 AGI 研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139139","duty":"课题背景：\n随着游戏产业向开放世界、高沉浸感和强交互性演进，以及人工智能技术进入多模态与推理能力深度融合的新阶段，构建具备人类级认知、决策与交互能力的游戏智能体已成为学术界与工业界的共同前沿。当前，研究正从传统的指令跟随与单一游戏专家系统，向具备跨环境泛化能力、复杂任务推理能力及多模态理解与交互能力的通用游戏智能体范式演进。\n近期突破性工作，如DeepMind的SIMA 2，通过集成先进的大语言模型（如Gemini），使智能体不仅能执行指令，更能进行目标推理、与环境对话并解释自身行为，在未经训练的游戏中也展现出强大的泛化能力。\n在此背景下，本研究旨在突破当前“大语言模型规划+多智能体强化学习”的常见框架，直面三大核心挑战：\n1、战略级博弈与动态适应：在复杂多变的游戏环境中，实现超越反应式行为的长期战略规划与实时动态策略调整；\n2、具身协作与有记忆的角色：构建具备长期记忆、情感状态与个性化成长轨迹的智能体，使其能在团队中扮演有深度、可持续互动的智慧角色；\n3、通用能力测试场：将高保真、高复杂度的游戏环境定位为通向人工通用智能（AGI）的关键测试平台，探索智能体在感知、推理、决策与创造方面的综合能力边界。\n本研究将与头部游戏项目深度合作，直接针对其在高水平竞技AI、动态叙事生成与可持续游戏生态构建中的产业痛点进行攻关。\n\n课题价值：\n本课题兼具重大的产业应用价值与深远的科学探索意义，为博士生提供站在技术浪潮之巅、解决定义下一代AI核心问题的独特机会。\n\n产业价值：直接赋能顶级游戏产品\n研究成果将直接转化为可落地的AI解决方案，服务于合作方的头部游戏项目：\n1、竞技AI：开发具备职业选手级战术理解与操作水平的AI，用于玩家训练、平衡性测试及高端赛事；\n2、叙事与生态AI：创造能够理解剧情背景、承载情感记忆并与玩家形成独特羁绊的NPC，以及驱动虚拟社会动态演化的生态AI，极大提升游戏沉浸感。\n\n学术价值：探索AGI的可行路径\n游戏环境是研究通用智能的绝佳沙盒。通过本课题，研究者将：\n1、推动基础模型与游戏智能的融合：探索如何将大规模预训练的世界知识、推理能力与在复杂环境中的实时感知-动作闭环相结合；\n2、攻克因果推理与可解释性：在游戏提供的清晰因果结构中，深入研究智能体如何避免“因果混淆”，建立对环境机制的可解释理解；\n3、验证智能体泛化与迁移的极限：系统研究智能体在跨游戏、跨任务、跨模态情境下的泛化能力，为更广泛的机器人学与AI应用提供原理性启示。\n加入本课题，您将有机会参与世界前沿的 AGI 研究工作，基于充足的算力与数据资源，共同定义并构建下一代游戏智能体，并在此过程中为人工智能迈向通用智能的宏伟征程贡献关键基石。","requirements":"1、包含但不限于计算机科学、人工智能、自动化、控制工程、模式识别、软件工程、信息工程、机器人学、认知科学、应用数学、统计学、运筹学等专业的博士和优秀硕士；\n2、熟练掌握大语言模型（LLM）基本原理与应用，熟练掌握强化学习经典算法方法（PPO、DQN、MCTS等）；\n3、熟悉PyTorch、Hugging Face Transformers、RLlib等至少一个主流深度学习或Agent开发框架，具备较强的工程实现与系统搭建能力；\n4、熟悉Python编程语言，具备良好的软件工程素养，熟悉Linux开发环境；\n5、加分项：在AI Agent、强化学习、NLP、游戏AI等相关领域发表过顶会/顶刊论文（如NeurIPS、ICML、ICLR、ACL、AAAI、CoRL等）；有游戏AI相关项目（如游戏Bot、自动化测试、智能NPC等）开发经验；有维护过具有一定影响力的开源项目。","description":"课题描述\n课题背景：\n随着游戏产业向开放世界、高沉浸感和强交互性演进，以及人工智能技术进入多模态与推理能力深度融合的新阶段，构建具备人类级认知、决策与交互能力的游戏智能体已成为学术界与工业界的共同前沿。当前，研究正从传统的指令跟随与单一游戏专家系统，向具备跨环境泛化能力、复杂任务推理能力及多模态理解与交互能力的通用游戏智能体范式演进。\n近期突破性工作，如DeepMind的SIMA 2，通过集成先进的大语言模型（如Gemini），使智能体不仅能执行指令，更能进行目标推理、与环境对话并解释自身行为，在未经训练的游戏中也展现出强大的泛化能力。\n在此背景下，本研究旨在突破当前“大语言模型规划+多智能体强化学习”的常见框架，直面三大核心挑战：\n1、战略级博弈与动态适应：在复杂多变的游戏环境中，实现超越反应式行为的长期战略规划与实时动态策略调整；\n2、具身协作与有记忆的角色：构建具备长期记忆、情感状态与个性化成长轨迹的智能体，使其能在团队中扮演有深度、可持续互动的智慧角色；\n3、通用能力测试场：将高保真、高复杂度的游戏环境定位为通向人工通用智能（AGI）的关键测试平台，探索智能体在感知、推理、决策与创造方面的综合能力边界。\n本研究将与头部游戏项目深度合作，直接针对其在高水平竞技AI、动态叙事生成与可持续游戏生态构建中的产业痛点进行攻关。\n\n课题价值：\n本课题兼具重大的产业应用价值与深远的科学探索意义，为博士生提供站在技术浪潮之巅、解决定义下一代AI核心问题的独特机会。\n\n产业价值：直接赋能顶级游戏产品\n研究成果将直接转化为可落地的AI解决方案，服务于合作方的头部游戏项目：\n1、竞技AI：开发具备职业选手级战术理解与操作水平的AI，用于玩家训练、平衡性测试及高端赛事；\n2、叙事与生态AI：创造能够理解剧情背景、承载情感记忆并与玩家形成独特羁绊的NPC，以及驱动虚拟社会动态演化的生态AI，极大提升游戏沉浸感。\n\n学术价值：探索AGI的可行路径\n游戏环境是研究通用智能的绝佳沙盒。通过本课题，研究者将：\n1、推动基础模型与游戏智能的融合：探索如何将大规模预训练的世界知识、推理能力与在复杂环境中的实时感知-动作闭环相结合；\n2、攻克因果推理与可解释性：在游戏提供的清晰因果结构中，深入研究智能体如何避免“因果混淆”，建立对环境机制的可解释理解；\n3、验证智能体泛化与迁移的极限：系统研究智能体在跨游戏、跨任务、跨模态情境下的泛化能力，为更广泛的机器人学与AI应用提供原理性启示。\n加入本课题，您将有机会参与世界前沿的 AGI 研究工作，基于充足的算力与数据资源，共同定义并构建下一代游戏智能体，并在此过程中为人工智能迈向通用智能的宏伟征程贡献关键基石。\n\n课题要求\n1、包含但不限于计算机科学、人工智能、自动化、控制工程、模式识别、软件工程、信息工程、机器人学、认知科学、应用数学、统计学、运筹学等专业的博士和优秀硕士；\n2、熟练掌握大语言模型（LLM）基本原理与应用，熟练掌握强化学习经典算法方法（PPO、DQN、MCTS等）；\n3、熟悉PyTorch、Hugging Face Transformers、RLlib等至少一个主流深度学习或Agent开发框架，具备较强的工程实现与系统搭建能力；\n4、熟悉Python编程语言，具备良好的软件工程素养，熟悉Linux开发环境；\n5、加分项：在AI Agent、强化学习、NLP、游戏AI等相关领域发表过顶会/顶刊论文（如NeurIPS、ICML、ICLR、ACL、AAAI、CoRL等）；有游戏AI相关项目（如游戏Bot、自动化测试、智能NPC等）开发经验；有维护过具有一定影响力的开源项目。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139140","sourceKey":"tencent","company":"腾讯","title":"3D生成基础大模型","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139140","duty":"课题背景：\n1、游戏行业是 3D 生成技术最主要的应用场景，2024年全球游戏行业营收大约是 200B 美元，远大于影视行业（30B 美元） 以及3D 相关行业，游戏的研发成本中 1/3 ～ 1/2 被用于美术，而其中的 1/2 以上被用于 3D 资产生成；\n2. 3D AIGC 在游戏行业中主要有两种应用场景：\n1、PGC：主要面向专业美术，对生成质量要求极高，要求新的技术能够和现有制作管线结合；\n2、UGC：主要面向普通用户，对生成质量要求略低，用于发散思维或者是个性化要求，比如 Roblox、 蛋仔派对、元梦等；\n3、当前处于 3D 生成技术已经相当接近 Production Ready 的状态，类似处于 GPT-4 的时刻。\n\n课题价值：\n1、大幅提升 3D 建模效率：传统 3D 建模需要数周甚至数月，而 3D 生成工具可在几秒到几分钟内生成高质量、可编辑的模型；\n2、降低创作门槛，赋能独立开发者：通过提供直观界面和API支持，无需专业建模技能即可生成游戏资产（如角色、道具、场景）。这让小型团队或独立开发者也能创建高质量 3D 内容，降低进入门槛，释放更多创意潜力；\n3、无缝集成现有工作流：3D 工具生成的模型可以直接导入 Unity、Unreal Engine 等主流游戏引擎，与现有开发流程无缝衔接，减少技术适配成本。\n\n课题挑战：\n1、形状编码：如何将 3D mesh 的形状有效地编码到隐空间，并且能够有效地保持原来 3D mesh 中精细的形状细节；\n2、部件拆分：艺术家制作的 3D mesh 中包含了丰富的结构信息，比如分离的部件，能够有效地区分这些结构是一个比较重要的技术挑战；\n3、拓扑生成质量：工业界中使用的 3D mesh 一般对拓扑质量有各种工艺要求，如何在保持 3D mesh 的形状的基础上，还能生成高质量的满足工艺要求的拓扑是一个需要解决的问题；\n4、纹理生成质量：从文本或者图片中还原模型的纹理，并且保持一致性以及高质量的细节是一个很有挑战的问题；。\n5. 3D 模型的可控生成：通过多种条件来对模型进行全局或者局部的可控生成，帮助艺术家更好的生成符合他们要求的 3D mesh。","requirements":"1、熟悉3D生成的前沿理论，了解CLAY、TRELLIS、Hunyuan、Meshtron 等 3D 生成框架的基础原理；\n2、熟悉材质渲染方面的原理，了解TexGen、UniTex、NaTex 等贴图生成相关工作；\n3、熟悉3D几何原理，了解 Marching Cubes、Flexicubes、水密化、Mesh 拓扑处理等技术；\n4、熟悉 3D 理解相关工作，有 3D detection、grounding、segmentation 的相关经验；\n4、在人工智能相关方向的硕士/博士，有扎实基础和丰富经验。","description":"课题描述\n课题背景：\n1、游戏行业是 3D 生成技术最主要的应用场景，2024年全球游戏行业营收大约是 200B 美元，远大于影视行业（30B 美元） 以及3D 相关行业，游戏的研发成本中 1/3 ～ 1/2 被用于美术，而其中的 1/2 以上被用于 3D 资产生成；\n2. 3D AIGC 在游戏行业中主要有两种应用场景：\n1、PGC：主要面向专业美术，对生成质量要求极高，要求新的技术能够和现有制作管线结合；\n2、UGC：主要面向普通用户，对生成质量要求略低，用于发散思维或者是个性化要求，比如 Roblox、 蛋仔派对、元梦等；\n3、当前处于 3D 生成技术已经相当接近 Production Ready 的状态，类似处于 GPT-4 的时刻。\n\n课题价值：\n1、大幅提升 3D 建模效率：传统 3D 建模需要数周甚至数月，而 3D 生成工具可在几秒到几分钟内生成高质量、可编辑的模型；\n2、降低创作门槛，赋能独立开发者：通过提供直观界面和API支持，无需专业建模技能即可生成游戏资产（如角色、道具、场景）。这让小型团队或独立开发者也能创建高质量 3D 内容，降低进入门槛，释放更多创意潜力；\n3、无缝集成现有工作流：3D 工具生成的模型可以直接导入 Unity、Unreal Engine 等主流游戏引擎，与现有开发流程无缝衔接，减少技术适配成本。\n\n课题挑战：\n1、形状编码：如何将 3D mesh 的形状有效地编码到隐空间，并且能够有效地保持原来 3D mesh 中精细的形状细节；\n2、部件拆分：艺术家制作的 3D mesh 中包含了丰富的结构信息，比如分离的部件，能够有效地区分这些结构是一个比较重要的技术挑战；\n3、拓扑生成质量：工业界中使用的 3D mesh 一般对拓扑质量有各种工艺要求，如何在保持 3D mesh 的形状的基础上，还能生成高质量的满足工艺要求的拓扑是一个需要解决的问题；\n4、纹理生成质量：从文本或者图片中还原模型的纹理，并且保持一致性以及高质量的细节是一个很有挑战的问题；。\n5. 3D 模型的可控生成：通过多种条件来对模型进行全局或者局部的可控生成，帮助艺术家更好的生成符合他们要求的 3D mesh。\n\n课题要求\n1、熟悉3D生成的前沿理论，了解CLAY、TRELLIS、Hunyuan、Meshtron 等 3D 生成框架的基础原理；\n2、熟悉材质渲染方面的原理，了解TexGen、UniTex、NaTex 等贴图生成相关工作；\n3、熟悉3D几何原理，了解 Marching Cubes、Flexicubes、水密化、Mesh 拓扑处理等技术；\n4、熟悉 3D 理解相关工作，有 3D detection、grounding、segmentation 的相关经验；\n4、在人工智能相关方向的硕士/博士，有扎实基础和丰富经验。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139141","sourceKey":"tencent","company":"腾讯","title":"多模态世界模型","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139141","duty":"传统游戏内容制作和开发中的每个环节都依赖大量人力工作，包括策划、美术、程序等。世界模型的引入，能让世界生成、演化和交互从“人工设计”转向”数据驱动与模型生成“。通过学习环境的规律，自主生成具有空间一致性、时间连贯性与交互性的虚拟世界，为游戏制作提供全新的“生成式”范式，这一趋势能显著降低游戏生产环节的成本，极大提升生产效率与创作空间。","requirements":"1、教育背景：人工智能、计算机科学、数学或相关专业，硕士及以上学历（博士优先）；\n2、编程能力：熟练掌握 PyTorch 等主流深度学习框架，具备扎实的编程能力与工程实现能力；能够高质量复现前沿论文，并推动算法从研究原型到工程实现。\n\n满足以下任意一种技术栈要求：\n1、生成模型：深入理解Diffusion Models, GANs, VAEs, Flow-based Models等，具备图像生成或视频生成相关研究或实践经验；\n2、模型训练：有大规模 GPU 集群上的模型预训练、微调与后训练经验；具备多模态大模型（如CLIP、LLaVA、Qwen等）的训练或应用经验；\n3、学术能力：在SIGGRAPH, CVPR, ICCV, NeurIPS等顶级会议或期刊发表过相关领域的一作论文者优先。","description":"课题描述\n传统游戏内容制作和开发中的每个环节都依赖大量人力工作，包括策划、美术、程序等。世界模型的引入，能让世界生成、演化和交互从“人工设计”转向”数据驱动与模型生成“。通过学习环境的规律，自主生成具有空间一致性、时间连贯性与交互性的虚拟世界，为游戏制作提供全新的“生成式”范式，这一趋势能显著降低游戏生产环节的成本，极大提升生产效率与创作空间。\n\n课题要求\n1、教育背景：人工智能、计算机科学、数学或相关专业，硕士及以上学历（博士优先）；\n2、编程能力：熟练掌握 PyTorch 等主流深度学习框架，具备扎实的编程能力与工程实现能力；能够高质量复现前沿论文，并推动算法从研究原型到工程实现。\n\n满足以下任意一种技术栈要求：\n1、生成模型：深入理解Diffusion Models, GANs, VAEs, Flow-based Models等，具备图像生成或视频生成相关研究或实践经验；\n2、模型训练：有大规模 GPU 集群上的模型预训练、微调与后训练经验；具备多模态大模型（如CLIP、LLaVA、Qwen等）的训练或应用经验；\n3、学术能力：在SIGGRAPH, CVPR, ICCV, NeurIPS等顶级会议或期刊发表过相关领域的一作论文者优先。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139142","sourceKey":"tencent","company":"腾讯","title":"基于多模态大模型的3D场景智能光照生成与编辑方法研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139142","duty":"课题背景：\n在游戏美术工业中，光照是构建场景视觉基调、烘托叙事氛围与决定最终沉浸感品质的核心要素。随着大型开放世界与高质量虚拟场景成为行业主流，其庞大的体量、复杂的几何结构及多元的时间/天气系统，使得传统依赖灯光美术师全手动、经验驱动的布光工作流面临严峻挑战。该流程不仅耗时漫长、迭代成本高昂，更在项目初期创意构想阶段形成瓶颈，限制了创意探索的广度与深度。当前，行业虽已拥有成熟的物理渲染与光照烘焙解决方案，高效解决了“光照计算”的物理准确性与性能问题，但在“光照设计”这一前置的、更依赖美学判断与空间理解的创造性环节，自动化与智能化水平仍近乎空白。近年来，大语言模型在复杂意图理解与结构化生成上的突破，以及多模态大模型在视觉-语言对齐与内容生成上的进展，为将抽象的、高层次的“美术需求”自动转化为具体、可执行的“灯光配置方案”这一核心难题，提供了革命性的技术解决路径。\n\n课题价值：\n本课题旨在将AIGC技术深度融入游戏光照生产管线，其核心价值体现在以下几个层面：\n1、生产效率的颠覆性提升：通过构建一个由“描述/参考图”到“初步灯光方案”的智能生成系统，能够将美术人员从海量、重复的基础光源摆放与参数调试工作中彻底解放。预计可将场景初始布光阶段的效率提升一个数量级，大幅缩短项目前期原型验证与迭代周期；\n2、创意潜能与艺术标准的释放与统一：系统能够将顶尖灯光美术师的布光逻辑与美学经验编码于模型之中，为不同经验水平的设计师提供高质量、符合专业规范的起点方案。这既降低了高级灯光设计的门槛，也助力团队建立并固化的艺术品质基线，保障大规模生产下光照风格的一致性；\n3、驱动生产管线智能化革新：本课题非独立工具研发，而是对现有生产管线的关键性前置增强。通过将AIGC的“创意生成”能力与MagicDawn的“物理精确渲染”能力无缝衔接，我们构建了一条从“创意概念”直达“最终渲染效果”的、高度自动化与智能化的完整工作流，是游戏工业化与智能化演进的关键一步；\n4、技术前瞻性与范式探索：该研究直接触及“AI如何理解并生成3D空间照明”这一前沿交叉领域，其成果（如多模态空间理解、条件化灯光生成模型）不仅服务于游戏行业，对影视制作、建筑可视化、元宇宙场景构建等广泛领域均有重要的技术辐射与借鉴价值。\n\n课题挑战：\n实现上述目标，需攻克一系列跨模态、跨领域的核心技术挑战：\n1、多模态意图精确对齐与空间推理挑战：如何让模型精确理解文本描述（如“暴雨将至的黄昏码头”）或二维参考图像中所蕴含的复杂光照意图（光源方向、质量、情绪），并将其转化为对3D场景空间的深度推理，准确判断光源应放置的空间位置、照射方向与影响范围，是首要难题；\n2、物理合理性与艺术性的平衡挑战：生成的灯光方案必须在物理上是合理的（如阴影方向一致、无光能冲突），同时具备高度的艺术表现力。模型需要在学习海量真实世界光照规律与优秀美术作品美学范式之间找到平衡，避免生成结果陷入“物理正确但平庸”或“风格突出但违和”的困境；\n3、精细化、可控化的参数生成挑战：光照效果由数十项精细参数（强度、色温、衰减、半径、阴影参数等）共同决定。挑战在于模型不仅要生成光源布局，还需为每个光源预测一套高度可用的初始参数集，并能响应美术师后续“将这里调暖一点”、“让阴影更柔和”等自然语言级的、细粒度的可控编辑指令；\n4、与工业化管线深度融合的工程挑战：生成的灯光数据必须能无损对接主流游戏引擎（如Unity, Unreal Engine）及团队自有的MagicDawn渲染管线，满足工业化生产对数据格式、层级结构、版本管理与批量处理的一切严格要求。这要求整个系统具备极高的鲁棒性、稳定性与可集成性。\n\n科研挑战\n1、突破多模块与游戏灯光生成生成，最终从理论走向落地；\n2、在图形学与 AI 顶级会议发表高水平论文并申请核心专利，形成完整的智能游戏制作解决方案。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、有图形学相关的基本算法及应用游戏；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。","description":"课题描述\n课题背景：\n在游戏美术工业中，光照是构建场景视觉基调、烘托叙事氛围与决定最终沉浸感品质的核心要素。随着大型开放世界与高质量虚拟场景成为行业主流，其庞大的体量、复杂的几何结构及多元的时间/天气系统，使得传统依赖灯光美术师全手动、经验驱动的布光工作流面临严峻挑战。该流程不仅耗时漫长、迭代成本高昂，更在项目初期创意构想阶段形成瓶颈，限制了创意探索的广度与深度。当前，行业虽已拥有成熟的物理渲染与光照烘焙解决方案，高效解决了“光照计算”的物理准确性与性能问题，但在“光照设计”这一前置的、更依赖美学判断与空间理解的创造性环节，自动化与智能化水平仍近乎空白。近年来，大语言模型在复杂意图理解与结构化生成上的突破，以及多模态大模型在视觉-语言对齐与内容生成上的进展，为将抽象的、高层次的“美术需求”自动转化为具体、可执行的“灯光配置方案”这一核心难题，提供了革命性的技术解决路径。\n\n课题价值：\n本课题旨在将AIGC技术深度融入游戏光照生产管线，其核心价值体现在以下几个层面：\n1、生产效率的颠覆性提升：通过构建一个由“描述/参考图”到“初步灯光方案”的智能生成系统，能够将美术人员从海量、重复的基础光源摆放与参数调试工作中彻底解放。预计可将场景初始布光阶段的效率提升一个数量级，大幅缩短项目前期原型验证与迭代周期；\n2、创意潜能与艺术标准的释放与统一：系统能够将顶尖灯光美术师的布光逻辑与美学经验编码于模型之中，为不同经验水平的设计师提供高质量、符合专业规范的起点方案。这既降低了高级灯光设计的门槛，也助力团队建立并固化的艺术品质基线，保障大规模生产下光照风格的一致性；\n3、驱动生产管线智能化革新：本课题非独立工具研发，而是对现有生产管线的关键性前置增强。通过将AIGC的“创意生成”能力与MagicDawn的“物理精确渲染”能力无缝衔接，我们构建了一条从“创意概念”直达“最终渲染效果”的、高度自动化与智能化的完整工作流，是游戏工业化与智能化演进的关键一步；\n4、技术前瞻性与范式探索：该研究直接触及“AI如何理解并生成3D空间照明”这一前沿交叉领域，其成果（如多模态空间理解、条件化灯光生成模型）不仅服务于游戏行业，对影视制作、建筑可视化、元宇宙场景构建等广泛领域均有重要的技术辐射与借鉴价值。\n\n课题挑战：\n实现上述目标，需攻克一系列跨模态、跨领域的核心技术挑战：\n1、多模态意图精确对齐与空间推理挑战：如何让模型精确理解文本描述（如“暴雨将至的黄昏码头”）或二维参考图像中所蕴含的复杂光照意图（光源方向、质量、情绪），并将其转化为对3D场景空间的深度推理，准确判断光源应放置的空间位置、照射方向与影响范围，是首要难题；\n2、物理合理性与艺术性的平衡挑战：生成的灯光方案必须在物理上是合理的（如阴影方向一致、无光能冲突），同时具备高度的艺术表现力。模型需要在学习海量真实世界光照规律与优秀美术作品美学范式之间找到平衡，避免生成结果陷入“物理正确但平庸”或“风格突出但违和”的困境；\n3、精细化、可控化的参数生成挑战：光照效果由数十项精细参数（强度、色温、衰减、半径、阴影参数等）共同决定。挑战在于模型不仅要生成光源布局，还需为每个光源预测一套高度可用的初始参数集，并能响应美术师后续“将这里调暖一点”、“让阴影更柔和”等自然语言级的、细粒度的可控编辑指令；\n4、与工业化管线深度融合的工程挑战：生成的灯光数据必须能无损对接主流游戏引擎（如Unity, Unreal Engine）及团队自有的MagicDawn渲染管线，满足工业化生产对数据格式、层级结构、版本管理与批量处理的一切严格要求。这要求整个系统具备极高的鲁棒性、稳定性与可集成性。\n\n科研挑战\n1、突破多模块与游戏灯光生成生成，最终从理论走向落地；\n2、在图形学与 AI 顶级会议发表高水平论文并申请核心专利，形成完整的智能游戏制作解决方案。\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、有图形学相关的基本算法及应用游戏；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139143","sourceKey":"tencent","company":"腾讯","title":"多模态引导的神经材质生产管线：从生成式合成到物理一致性重构","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139143","duty":"课题背景：\n传统的材质建模依赖于Disney或微表面（Microfacet）等参数化物理模型，虽然稳健，但受限于参数维度，难以捕捉真实世界中复杂的非局部交互和多层视觉效果。神经材质（如NeuMIP）利用小型多层感知机（MLP）和潜在特征贴图，实现了高保真、实时且分辨率无关的复杂外观表示。然而，创作高质量神经材质门槛极高，往往需要专业的测角反光仪实验室或昂贵的艺术加工。随着多模态大语言模型（MLLM）和扩散模型的发展，利用文本或单张照片引导材质生成已成为可能。目前的前沿研究（如VideoNeuMat）正尝试将大型视频模型作为“虚拟测角反光仪”，从中提取被解耦的、可重用的神经材质资产，从而开启了从生成式合成转向高质量物理重构的新范式\n\n课题价值：\n1、内容创作的平民化与高效化： 该管线允许非专业用户通过文本指令或随手拍摄的照片生成电影级精度的PBR材质，极大降低了3D内容生产的成本；\n2、实现真正的资产解耦与重用： 相比于传统的“烘焙”式贴图，该管线强调物理一致性重构，能将材质属性从光照和几何中彻底解耦，使其能够适应任何新场景的重光照需求；\n3、实时渲染性能的跨越式提升： 神经材质在保持高保真度的同时，其评估成本不随材质复杂程度增加，如果能加以利用，将有可能实现高复杂度材质的高性能实时渲染；\n4、工业管线的无缝集成： 我们预期该管线生产的神经材质资产将可以直接用于高品质游戏生产管线中\n\n课题挑战：\n1、物理规律的强制约束： 神经网络本质上并不天然遵循能量守恒定律，如何在重构过程中引入硬性的物理结构约束，而非仅靠软性的损失函数，是确保渲染真实性的关键；\n2、数据稀缺性瓶颈： 训练高质量材质生成模型缺乏大规模、具备真实感且标注完善的PBR/神经材质数据集，依赖视频先验进行知识蒸馏是目前的蓝海但也极具技术难度；\n3、可编辑性与语义控制： 神经材质目前多为“黑盒”表示，一旦生成，艺术家难以像传统贴图那样进行“增加锈迹”等语义级的交互式修改，构建语义可解释的潜空间是管线落地的痛点。\n\n科研挑战：\n1、突破多模块生成与编辑神经材质的理论瓶颈，最终从理论走向落地；\n2、突破神经材质运行时效果与效率，突破硬件瓶颈；\n3、在图形学与 AI 顶级会议发表高水平论文并申请核心专利，形成完整的智能游戏制作解决方案。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、有图形学相关的基本算法及应用游戏；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。","description":"课题描述\n课题背景：\n传统的材质建模依赖于Disney或微表面（Microfacet）等参数化物理模型，虽然稳健，但受限于参数维度，难以捕捉真实世界中复杂的非局部交互和多层视觉效果。神经材质（如NeuMIP）利用小型多层感知机（MLP）和潜在特征贴图，实现了高保真、实时且分辨率无关的复杂外观表示。然而，创作高质量神经材质门槛极高，往往需要专业的测角反光仪实验室或昂贵的艺术加工。随着多模态大语言模型（MLLM）和扩散模型的发展，利用文本或单张照片引导材质生成已成为可能。目前的前沿研究（如VideoNeuMat）正尝试将大型视频模型作为“虚拟测角反光仪”，从中提取被解耦的、可重用的神经材质资产，从而开启了从生成式合成转向高质量物理重构的新范式\n\n课题价值：\n1、内容创作的平民化与高效化： 该管线允许非专业用户通过文本指令或随手拍摄的照片生成电影级精度的PBR材质，极大降低了3D内容生产的成本；\n2、实现真正的资产解耦与重用： 相比于传统的“烘焙”式贴图，该管线强调物理一致性重构，能将材质属性从光照和几何中彻底解耦，使其能够适应任何新场景的重光照需求；\n3、实时渲染性能的跨越式提升： 神经材质在保持高保真度的同时，其评估成本不随材质复杂程度增加，如果能加以利用，将有可能实现高复杂度材质的高性能实时渲染；\n4、工业管线的无缝集成： 我们预期该管线生产的神经材质资产将可以直接用于高品质游戏生产管线中\n\n课题挑战：\n1、物理规律的强制约束： 神经网络本质上并不天然遵循能量守恒定律，如何在重构过程中引入硬性的物理结构约束，而非仅靠软性的损失函数，是确保渲染真实性的关键；\n2、数据稀缺性瓶颈： 训练高质量材质生成模型缺乏大规模、具备真实感且标注完善的PBR/神经材质数据集，依赖视频先验进行知识蒸馏是目前的蓝海但也极具技术难度；\n3、可编辑性与语义控制： 神经材质目前多为“黑盒”表示，一旦生成，艺术家难以像传统贴图那样进行“增加锈迹”等语义级的交互式修改，构建语义可解释的潜空间是管线落地的痛点。\n\n科研挑战：\n1、突破多模块生成与编辑神经材质的理论瓶颈，最终从理论走向落地；\n2、突破神经材质运行时效果与效率，突破硬件瓶颈；\n3、在图形学与 AI 顶级会议发表高水平论文并申请核心专利，形成完整的智能游戏制作解决方案。\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、有图形学相关的基本算法及应用游戏；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139144","sourceKey":"tencent","company":"腾讯","title":"基于Transformer架构的下一代渲染管线：从序列化光传输到物理一致性实时渲染","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139144","duty":"课题背景：\n实时渲染领域正经历一场由神经网络驱动的范式革命。传统光栅化管线依赖手工设计的着色模型与近似光照算法，在全局光照、复杂材质交互等方面存在根本性的物理精度瓶颈；而路径追踪虽能实现物理正确的光传输，却因计算代价高昂而长期被排除在实时应用之外。\n2024年，微软研究院提出的 RenderFormer 开创性地将 Transformer 架构引入渲染管线，将场景中的三角面片视为 token 序列，通过注意力机制直接学习光线在几何体之间的传播与交互，首次实现了端到端的神经渲染管线，在合理规模场景下取得了接近离线渲染的视觉质量。这一工作标志着渲染从\"手工物理建模\"向\"数据驱动光传输学习\"的历史性转折，有望深刻重塑游戏、影视、工业仿真等行业的内容生产范式。\n然而，RenderFormer 当前仍面临若干关键瓶颈：O(N²) 的计算复杂度将场景规模限制在 4,096 个三角形以内；推理速度在 A100 上仅达 10–16 FPS，远未满足消费级实时需求；光源类型固定且数量受限（1–8个场外光源），缺乏对点光源、面光源、天光等任意光源配置的泛化能力；相机参数固定于场景外部，无法支持自由漫游；材质表达停留在 per-triangle 常量级别，缺乏空间变化的纹理细节。这些不足共同构成了 RenderFormer 从学术原型走向工业落地的核心障碍。\n本课题旨在系统性突破上述瓶颈，构建面向工业级应用的下一代 Transformer 渲染管线，实现从序列化光传输建模到物理一致性实时渲染的全面跨越。\n\n课题价值：\n1、重新定义实时渲染的物理精度上限：传统实时管线依赖大量近似（如 IBL、屏幕空间反射），而基于 Transformer 的渲染管线通过学习真实光传输路径，有望在实时帧率下实现接近离线渲染的全局光照效果，从根本上消除\"实时\"与\"物理正确\"之间的长期对立；\n2、颠覆内容生产的技术门槛：当渲染管线本身具备对任意光源、任意相机、任意材质的泛化能力后，美术人员无需再为每种光照场景单独烘焙或调参，极大降低高品质内容的制作成本，加速游戏、影视、虚拟现实等行业的工业化进程；\n3、构建可扩展的神经渲染基础设施：本课题提出的稀疏注意力机制、层次化场景表达与神经纹理集成方案，将为后续神经渲染研究提供可复用的技术底座，推动整个领域从\"单点突破\"走向\"系统性工程\"；\n4、重塑云渲染与流式分发的基础架构：基于 Transformer 的推理式渲染天然契合云端部署范式——渲染过程本质上是一次前向推理，无需维护传统光栅化管线所依赖的图形上下文状态，极易实现无状态横向扩展。这意味着云端可将渲染算力以 AI 推理集群的形式统一调度，按帧按需分配算力，彻底消除传统云渲染中帧间状态同步的工程复杂度。结合流式传输技术，未来移动端、XR 头显乃至低端 PC 均可通过网络实时接收高质量渲染帧，真正实现\"终端零渲染负担\"的云游戏与云仿真落地。此外，AI 推理集群的弹性伸缩能力远优于传统 GPU 渲染农场，可大幅降低影视级离线渲染的排队等待时间与运营成本；\n5、战略卡位 AI 算力时代的渲染话语权：当前 NVIDIA 显卡的发展重心已从传统图形单元（CUDA Core、光追核心）向 AI 计算单元（Tensor Core）大幅倾斜——RTX 50 系列中 Tensor Core 的算力占比持续提升，而传统光栅化单元的边际收益日益递减。这一硬件趋势深刻暗示：未来高端显卡的核心竞争力将是 AI 推理吞吐量，而非传统图形流水线性能。本课题所构建的 Transformer 渲染管线，能够直接将 Tensor Core 的矩阵乘法算力转化为渲染质量与帧率的提升，与硬件演进方向高度契合。率先建立基于 AI 推理的渲染技术体系，意味着在下一代硬件红利释放时占据先发优势，避免在传统图形 API（DirectX、Vulkan）生态中被动跟随，转而在 AI 原生渲染这一新赛道上掌握核心话语权。\n\n课题挑战：\n1、计算复杂度的规模化瓶颈：\nRenderFormer 的 O(N²) 注意力复杂度使其在 4,096 个三角形时已接近极限，而工业级场景动辄包含数百万面片。如何在保留全局光传输建模能力的前提下，将计算复杂度降至亚线性量级，是实现规模化的核心理论挑战。需探索基于场景空间结构（如 BVH、八叉树）的稀疏注意力机制，使模型能够自适应地聚焦于光学上相互可见、相互影响的面片对，而非对所有面片进行全量计算；\n2、实时推理的硬件适配难题：\n当前在 A100 上 512×512 分辨率仅达 10–16 FPS，在消费级 GPU（如 RTX 4060）上差距更为悬殊。将推理性能提升至 30 FPS 以上需要在模型架构、量化压缩、硬件感知调度等多个层面协同优化，同时不能以牺牲物理精度为代价，这对模型的效率-质量帕累托前沿提出了极高要求；\n3、任意光源配置的零样本泛化：\n现有模型对光源类型与数量的强依赖，本质上是因为光照信息以场景外部固定参数的形式注入，模型未能学习到光传输的物理本质。如何将光源解耦为物理先验（如辐射度量学约束、光传输线性叠加原理），使模型在未见过的光源配置下实现零样本或少样本泛化，是突破光照泛化能力的关键；\n4、自由相机与动态场景的支持：\n相机参数固定于场景外部的限制，使得 RenderFormer 无法支持第一人称漫游、飞行相机等游戏核心需求。同时，当场景中存在动态物体时，如何高效更新 token 序列而非重新推理整个场景，是实现动态渲染的工程难点；\n5、高分辨率神经纹理的集成：\nper-triangle 常量材质参数无法表达织物纤维、皮肤毛孔等微观表面细节。如何将 UV 映射下的高分辨率纹理信息以 token 嵌入的形式编码进 Transformer，并与神经纹理（Neural Texture）机制无缝结合，在不显著增加计算量的前提下大幅提升材质表达能力，是材质建模的核心挑战。\n\n科研目标：\n1、提出基于空间感知稀疏注意力的可扩展渲染 Transformer，将场景规模支持上限从 4,096 个三角形扩展至百万级面片，计算复杂度降至 O(N log N) 量级；\n2、实现在消费级 GPU（RTX 4060 级别）上 512×512 分辨率≥30 FPS 的实时推理，通过模型蒸馏、INT8量化与硬件感知算子融合协同实现；\n3、构建基于物理先验解耦的任意光源泛化机制，支持点光源、面光源、HDRI 天光等任意光源类型与组合的零样本渲染；\n4、实现自由相机漫游与动态场景增量更新，支持第一人称视角、飞行相机等游戏级相机控制模式；\n5、集成神经纹理驱动的高分辨率材质表达，支持 UV 映射下的空间变化材质，在图形学与 AI 顶级会议（SIGGRAPH、CVPR、NeurIPS）发表高水平论文并申请核心专利，形成完整的下一代神经渲染解决方案。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、有图形学相关的基本算法及应用游戏；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。","description":"课题描述\n课题背景：\n实时渲染领域正经历一场由神经网络驱动的范式革命。传统光栅化管线依赖手工设计的着色模型与近似光照算法，在全局光照、复杂材质交互等方面存在根本性的物理精度瓶颈；而路径追踪虽能实现物理正确的光传输，却因计算代价高昂而长期被排除在实时应用之外。\n2024年，微软研究院提出的 RenderFormer 开创性地将 Transformer 架构引入渲染管线，将场景中的三角面片视为 token 序列，通过注意力机制直接学习光线在几何体之间的传播与交互，首次实现了端到端的神经渲染管线，在合理规模场景下取得了接近离线渲染的视觉质量。这一工作标志着渲染从\"手工物理建模\"向\"数据驱动光传输学习\"的历史性转折，有望深刻重塑游戏、影视、工业仿真等行业的内容生产范式。\n然而，RenderFormer 当前仍面临若干关键瓶颈：O(N²) 的计算复杂度将场景规模限制在 4,096 个三角形以内；推理速度在 A100 上仅达 10–16 FPS，远未满足消费级实时需求；光源类型固定且数量受限（1–8个场外光源），缺乏对点光源、面光源、天光等任意光源配置的泛化能力；相机参数固定于场景外部，无法支持自由漫游；材质表达停留在 per-triangle 常量级别，缺乏空间变化的纹理细节。这些不足共同构成了 RenderFormer 从学术原型走向工业落地的核心障碍。\n本课题旨在系统性突破上述瓶颈，构建面向工业级应用的下一代 Transformer 渲染管线，实现从序列化光传输建模到物理一致性实时渲染的全面跨越。\n\n课题价值：\n1、重新定义实时渲染的物理精度上限：传统实时管线依赖大量近似（如 IBL、屏幕空间反射），而基于 Transformer 的渲染管线通过学习真实光传输路径，有望在实时帧率下实现接近离线渲染的全局光照效果，从根本上消除\"实时\"与\"物理正确\"之间的长期对立；\n2、颠覆内容生产的技术门槛：当渲染管线本身具备对任意光源、任意相机、任意材质的泛化能力后，美术人员无需再为每种光照场景单独烘焙或调参，极大降低高品质内容的制作成本，加速游戏、影视、虚拟现实等行业的工业化进程；\n3、构建可扩展的神经渲染基础设施：本课题提出的稀疏注意力机制、层次化场景表达与神经纹理集成方案，将为后续神经渲染研究提供可复用的技术底座，推动整个领域从\"单点突破\"走向\"系统性工程\"；\n4、重塑云渲染与流式分发的基础架构：基于 Transformer 的推理式渲染天然契合云端部署范式——渲染过程本质上是一次前向推理，无需维护传统光栅化管线所依赖的图形上下文状态，极易实现无状态横向扩展。这意味着云端可将渲染算力以 AI 推理集群的形式统一调度，按帧按需分配算力，彻底消除传统云渲染中帧间状态同步的工程复杂度。结合流式传输技术，未来移动端、XR 头显乃至低端 PC 均可通过网络实时接收高质量渲染帧，真正实现\"终端零渲染负担\"的云游戏与云仿真落地。此外，AI 推理集群的弹性伸缩能力远优于传统 GPU 渲染农场，可大幅降低影视级离线渲染的排队等待时间与运营成本；\n5、战略卡位 AI 算力时代的渲染话语权：当前 NVIDIA 显卡的发展重心已从传统图形单元（CUDA Core、光追核心）向 AI 计算单元（Tensor Core）大幅倾斜——RTX 50 系列中 Tensor Core 的算力占比持续提升，而传统光栅化单元的边际收益日益递减。这一硬件趋势深刻暗示：未来高端显卡的核心竞争力将是 AI 推理吞吐量，而非传统图形流水线性能。本课题所构建的 Transformer 渲染管线，能够直接将 Tensor Core 的矩阵乘法算力转化为渲染质量与帧率的提升，与硬件演进方向高度契合。率先建立基于 AI 推理的渲染技术体系，意味着在下一代硬件红利释放时占据先发优势，避免在传统图形 API（DirectX、Vulkan）生态中被动跟随，转而在 AI 原生渲染这一新赛道上掌握核心话语权。\n\n课题挑战：\n1、计算复杂度的规模化瓶颈：\nRenderFormer 的 O(N²) 注意力复杂度使其在 4,096 个三角形时已接近极限，而工业级场景动辄包含数百万面片。如何在保留全局光传输建模能力的前提下，将计算复杂度降至亚线性量级，是实现规模化的核心理论挑战。需探索基于场景空间结构（如 BVH、八叉树）的稀疏注意力机制，使模型能够自适应地聚焦于光学上相互可见、相互影响的面片对，而非对所有面片进行全量计算；\n2、实时推理的硬件适配难题：\n当前在 A100 上 512×512 分辨率仅达 10–16 FPS，在消费级 GPU（如 RTX 4060）上差距更为悬殊。将推理性能提升至 30 FPS 以上需要在模型架构、量化压缩、硬件感知调度等多个层面协同优化，同时不能以牺牲物理精度为代价，这对模型的效率-质量帕累托前沿提出了极高要求；\n3、任意光源配置的零样本泛化：\n现有模型对光源类型与数量的强依赖，本质上是因为光照信息以场景外部固定参数的形式注入，模型未能学习到光传输的物理本质。如何将光源解耦为物理先验（如辐射度量学约束、光传输线性叠加原理），使模型在未见过的光源配置下实现零样本或少样本泛化，是突破光照泛化能力的关键；\n4、自由相机与动态场景的支持：\n相机参数固定于场景外部的限制，使得 RenderFormer 无法支持第一人称漫游、飞行相机等游戏核心需求。同时，当场景中存在动态物体时，如何高效更新 token 序列而非重新推理整个场景，是实现动态渲染的工程难点；\n5、高分辨率神经纹理的集成：\nper-triangle 常量材质参数无法表达织物纤维、皮肤毛孔等微观表面细节。如何将 UV 映射下的高分辨率纹理信息以 token 嵌入的形式编码进 Transformer，并与神经纹理（Neural Texture）机制无缝结合，在不显著增加计算量的前提下大幅提升材质表达能力，是材质建模的核心挑战。\n\n科研目标：\n1、提出基于空间感知稀疏注意力的可扩展渲染 Transformer，将场景规模支持上限从 4,096 个三角形扩展至百万级面片，计算复杂度降至 O(N log N) 量级；\n2、实现在消费级 GPU（RTX 4060 级别）上 512×512 分辨率≥30 FPS 的实时推理，通过模型蒸馏、INT8量化与硬件感知算子融合协同实现；\n3、构建基于物理先验解耦的任意光源泛化机制，支持点光源、面光源、HDRI 天光等任意光源类型与组合的零样本渲染；\n4、实现自由相机漫游与动态场景增量更新，支持第一人称视角、飞行相机等游戏级相机控制模式；\n5、集成神经纹理驱动的高分辨率材质表达，支持 UV 映射下的空间变化材质，在图形学与 AI 顶级会议（SIGGRAPH、CVPR、NeurIPS）发表高水平论文并申请核心专利，形成完整的下一代神经渲染解决方案。\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、有图形学相关的基本算法及应用游戏；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139145","sourceKey":"tencent","company":"腾讯","title":"基于3dgs的下一代游戏制作与渲染研究课题背景","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139145","duty":"课题背景：\n生成式 AI 正在深刻重塑游戏工业。传统 3D 内容生产管线长期受制于制作周期长、成本高，以及高保真效果与实时渲染性能之间的结构性矛盾。3D Gaussian Splatting（3DGS）为实时渲染带来突破，但在工程化落地中仍面临存储冗余、可编辑性不足、缺乏物理一致性交互等关键瓶颈。将扩散模型的生成能力与大语言模型（LLM）的语义理解与交互能力引入 3DGS，构建 AI 驱动的新一代 3DGS 端到端制作与渲染管线，有望成为下一阶段的核心突破方向。\n\n课题价值：\n通过自动化、智能化内容生产与编辑流程，减少对高熟练度美术与技术人员的依赖，大幅降低 3D 资产制作门槛与成本，显著缩短开发周期；\n提供高复杂度场景的高帧率实时渲染能力，支持传统方法难以实现的开放世界与动态效果，兼顾画面质量、渲染效率与工程部署可行性。\n\n课题挑战：\n当前 3DGS 在动态光照表达不自然、物理效果缺失等方面仍存在明显短板，需要探索更优核函数设计，并引入可微分的物理建模与交互约束以提升一致性与可控性；\n超大规模场景下 3DGS 表达存在显存占用高、数据冗余大的问题，需研发 Mesh 与 3DGS 的混合表达与混合渲染管线，优化 LOD、流式加载与资源调度机制；\n基于单图与扩散模型生成 3DGS 时容易出现视角移动瑕疵与多视角不一致，需要提升几何与外观的跨视角一致性、时空稳定性与可编辑性。\n\n科研目标：\n突破3DGS生成与渲染的难题，最终从理论走向落地；\n在图形学与 AI 顶级会议发表高水平论文并申请核心专利，形成完整的智能游戏制作解决方案。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、有图形学相关的基本算法及应用游戏；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。","description":"课题描述\n课题背景：\n生成式 AI 正在深刻重塑游戏工业。传统 3D 内容生产管线长期受制于制作周期长、成本高，以及高保真效果与实时渲染性能之间的结构性矛盾。3D Gaussian Splatting（3DGS）为实时渲染带来突破，但在工程化落地中仍面临存储冗余、可编辑性不足、缺乏物理一致性交互等关键瓶颈。将扩散模型的生成能力与大语言模型（LLM）的语义理解与交互能力引入 3DGS，构建 AI 驱动的新一代 3DGS 端到端制作与渲染管线，有望成为下一阶段的核心突破方向。\n\n课题价值：\n通过自动化、智能化内容生产与编辑流程，减少对高熟练度美术与技术人员的依赖，大幅降低 3D 资产制作门槛与成本，显著缩短开发周期；\n提供高复杂度场景的高帧率实时渲染能力，支持传统方法难以实现的开放世界与动态效果，兼顾画面质量、渲染效率与工程部署可行性。\n\n课题挑战：\n当前 3DGS 在动态光照表达不自然、物理效果缺失等方面仍存在明显短板，需要探索更优核函数设计，并引入可微分的物理建模与交互约束以提升一致性与可控性；\n超大规模场景下 3DGS 表达存在显存占用高、数据冗余大的问题，需研发 Mesh 与 3DGS 的混合表达与混合渲染管线，优化 LOD、流式加载与资源调度机制；\n基于单图与扩散模型生成 3DGS 时容易出现视角移动瑕疵与多视角不一致，需要提升几何与外观的跨视角一致性、时空稳定性与可编辑性。\n\n科研目标：\n突破3DGS生成与渲染的难题，最终从理论走向落地；\n在图形学与 AI 顶级会议发表高水平论文并申请核心专利，形成完整的智能游戏制作解决方案。\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、有图形学相关的基本算法及应用游戏；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139146","sourceKey":"tencent","company":"腾讯","title":"用于实时渲染的复杂材质的高效表示","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139146","duty":"课题背景：\n随着游戏画质的提高，材质模型变得越来越复杂，如何探索更高效的材质表达成为一个重要问题，在新的时代下，既有Subtrate 中传统的多层表达，也有neural material model这种基于网络的表达，本课题需要探索这些表达在实时渲染场景下的落地可能。\n\n课题价值：\n在保证渲染性能的基础上，大幅提升渲染质量，提升游戏品质。\n\n具体工作：\n探索新一代生成复杂材质的工作流和优化手段，不断推进绘制效果极限。","requirements":"1、包含但不限于计算机、人工智能、计算机视觉、信息工程、应用数学等专业的博士和优秀硕士；\n2、熟悉计算机图形学，渲染相关的基础方法，有相关项目/研究经验；\n3、加分项：在SIGGRAPH,CVPR、NeurIPS、ICLR、ECCV等顶会发表过先关论文。","description":"课题描述\n课题背景：\n随着游戏画质的提高，材质模型变得越来越复杂，如何探索更高效的材质表达成为一个重要问题，在新的时代下，既有Subtrate 中传统的多层表达，也有neural material model这种基于网络的表达，本课题需要探索这些表达在实时渲染场景下的落地可能。\n\n课题价值：\n在保证渲染性能的基础上，大幅提升渲染质量，提升游戏品质。\n\n具体工作：\n探索新一代生成复杂材质的工作流和优化手段，不断推进绘制效果极限。\n\n课题要求\n1、包含但不限于计算机、人工智能、计算机视觉、信息工程、应用数学等专业的博士和优秀硕士；\n2、熟悉计算机图形学，渲染相关的基础方法，有相关项目/研究经验；\n3、加分项：在SIGGRAPH,CVPR、NeurIPS、ICLR、ECCV等顶会发表过先关论文。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139147","sourceKey":"tencent","company":"腾讯","title":"基于生成式框架的游戏画质增强研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139147","duty":"课题背景：\n以 Diffusion in Transformer (DiT) 为代表的生成式架构，凭借其强大的建模能力与全局感知特性，可以为游戏画质带来了从“插值修复”向“内容生成”跨越的可能。通过引入大规模预训练的先验知识，构建兼顾生成质量与实时响应性的增强管线，将成为突破实时渲染画质上限的核心驱动力。\n\n课题价值：\n利用 DiT 的生成能力填补传统方法无法恢复的像素画质损失，实现跨数量级的性能加速与画质飞跃。改变传统固化的后处理管线，支持语义层面的风格化迁移与画质修复，使开发者能以极低成本实现从写实到特定艺术风格的无缝转换。\n\n课题挑战：\nDiT 架构的高计算复杂度与游戏渲染的毫秒级响应要求存在冲突，需探索轻量化 Transformer 设计、分级采样策略以及特定硬件（Tensor Core）的极致加速方案。生成内容的逻辑一致性，确保空间上的几何准确性与时间上的时空稳定性。风格化与增强过程容易导致画面语义偏移（如材质误认），需研究基于控制向量或 LoRA 的语义约束机制，确保增强效果符合原画设计意图。\n\n具体工作：\n参与新一代游戏画质增强算法的研究与训练，参与数据收集，算法训练，到端上部署的全过程。研究方向包括但不限于视频超分，生成和风格化等，定义新时代画质增强范式","requirements":"1、包含但不限于计算机、人工智能、计算机视觉、信息工程、应用数学等专业的博士和优秀硕士；\n2、熟悉视频生成/扩散模型相关技术（如Video Diffusion、DiT、Flow Matching、Consistency Model等）或计算机视觉基础方法，有相关项目/研究经验；\n3、熟悉PyTorch等深度学习框架，具备视频/图像数据处理能力，掌握Python编程，有大规模生成模型训练/微调实践经验者优先；\n4、加分项：在SIGGRAPH,CVPR、NeurIPS、ICLR、ECCV等顶会发表过视频生成、扩散模型相关论文；有游戏视频数据处理或实时渲染相关项目经验。","description":"课题描述\n课题背景：\n以 Diffusion in Transformer (DiT) 为代表的生成式架构，凭借其强大的建模能力与全局感知特性，可以为游戏画质带来了从“插值修复”向“内容生成”跨越的可能。通过引入大规模预训练的先验知识，构建兼顾生成质量与实时响应性的增强管线，将成为突破实时渲染画质上限的核心驱动力。\n\n课题价值：\n利用 DiT 的生成能力填补传统方法无法恢复的像素画质损失，实现跨数量级的性能加速与画质飞跃。改变传统固化的后处理管线，支持语义层面的风格化迁移与画质修复，使开发者能以极低成本实现从写实到特定艺术风格的无缝转换。\n\n课题挑战：\nDiT 架构的高计算复杂度与游戏渲染的毫秒级响应要求存在冲突，需探索轻量化 Transformer 设计、分级采样策略以及特定硬件（Tensor Core）的极致加速方案。生成内容的逻辑一致性，确保空间上的几何准确性与时间上的时空稳定性。风格化与增强过程容易导致画面语义偏移（如材质误认），需研究基于控制向量或 LoRA 的语义约束机制，确保增强效果符合原画设计意图。\n\n具体工作：\n参与新一代游戏画质增强算法的研究与训练，参与数据收集，算法训练，到端上部署的全过程。研究方向包括但不限于视频超分，生成和风格化等，定义新时代画质增强范式\n\n课题要求\n1、包含但不限于计算机、人工智能、计算机视觉、信息工程、应用数学等专业的博士和优秀硕士；\n2、熟悉视频生成/扩散模型相关技术（如Video Diffusion、DiT、Flow Matching、Consistency Model等）或计算机视觉基础方法，有相关项目/研究经验；\n3、熟悉PyTorch等深度学习框架，具备视频/图像数据处理能力，掌握Python编程，有大规模生成模型训练/微调实践经验者优先；\n4、加分项：在SIGGRAPH,CVPR、NeurIPS、ICLR、ECCV等顶会发表过视频生成、扩散模型相关论文；有游戏视频数据处理或实时渲染相关项目经验。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139148","sourceKey":"tencent","company":"腾讯","title":"复杂3D场景的多模态理解与生成","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139148","duty":"课题背景：\n大模型的深层语义理解需超越\"看图说话\"的表层认知。当前主流方案（如UnrealLLM等）依赖多视角渲染或资产元数据匹配，难以捕获空间拓扑、物理约束与交互可用性（Affordance），导致视觉感知与物理逻辑割裂。本课题旨在建立3D原生数据结构与大模型高维语义空间的精准对齐机制，打通\"视觉-物理\"的认知壁垒。\n\n课题价值：\n1、理论范式：构建多模态场景语义图（Multimodal Scene Graph），实现视觉特征、物理属性与逻辑约束的统一表征，为下一步的生成和编辑提供高维推理认知基座；\n2、应用突破：攻克\"知其形而不知其理\"的认知瓶颈，使大模型深度理解资产间的空间关联与交互机制，支撑3D场景的动态生成与复杂推理；\n3、引擎验证：基于游戏引擎或3D制作工具理解场景，进一步根据用户指令生成场景。","requirements":"1、包含但不限于计算机、人工智能、图形学等相关专业的硕士或优秀本科生；\n2、深入理解UE底层架构（UObject体系、渲染管线），熟练掌握C++/Python编程；\n3、熟悉多模态大模型(MLLM)、3D表征学习或图神经网络(GNN)的前沿进展，具备较强的模态对齐算法落地能力。","description":"课题描述\n课题背景：\n大模型的深层语义理解需超越\"看图说话\"的表层认知。当前主流方案（如UnrealLLM等）依赖多视角渲染或资产元数据匹配，难以捕获空间拓扑、物理约束与交互可用性（Affordance），导致视觉感知与物理逻辑割裂。本课题旨在建立3D原生数据结构与大模型高维语义空间的精准对齐机制，打通\"视觉-物理\"的认知壁垒。\n\n课题价值：\n1、理论范式：构建多模态场景语义图（Multimodal Scene Graph），实现视觉特征、物理属性与逻辑约束的统一表征，为下一步的生成和编辑提供高维推理认知基座；\n2、应用突破：攻克\"知其形而不知其理\"的认知瓶颈，使大模型深度理解资产间的空间关联与交互机制，支撑3D场景的动态生成与复杂推理；\n3、引擎验证：基于游戏引擎或3D制作工具理解场景，进一步根据用户指令生成场景。\n\n课题要求\n1、包含但不限于计算机、人工智能、图形学等相关专业的硕士或优秀本科生；\n2、深入理解UE底层架构（UObject体系、渲染管线），熟练掌握C++/Python编程；\n3、熟悉多模态大模型(MLLM)、3D表征学习或图神经网络(GNN)的前沿进展，具备较强的模态对齐算法落地能力。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139149","sourceKey":"tencent","company":"腾讯","title":"AI Agent研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139149","duty":"课题背景：\nLLM Agent 天然适配结构化文本/CLI 交互（如 CLI-Anything 所示 ），但传统工业软件（以 UE 为代表）基于二进制架构与 GUI 交互，与 LLM 的 Token 推理模态存在结构性错位。现有 API 或 MCP 协议难以支撑 Agent 对复杂系统的深度微观控制。亟需建立将引擎运行时状态降维转译为高密度文本流的通用协议，打通“视觉-逻辑”鸿沟。\n\n课题价值：\n1、通用转译架构：构建面向纯文本 Agent 的底层状态转译协议，将复杂系统黑盒状态映射为大模型可内省、可干预的高维文本流；\n2、CLI-UE 中间层：深度解析 UE 的 C++ 反射系统与编辑器核心子系统，将其转化为支持 CoT 调用的标准化文本 API，实现 LLM 推理与引擎执行的闭环；\n3、工业化赋能：突破大模型心智与重度工业引擎的通信瓶颈，确立零样本/少样本条件下自动化关卡生成、引擎级 QA 测试及 AI 原生 Gameplay 的技术路径。","requirements":"1、包含但不限于计算机科学、软件工程、自动化等相关专业的硕士或优秀本科生；\n2、具备极强的底层源码剖析能力，精通UE C++反射机制及核心子系统源码；\n3、熟悉Agent系统设计架构（如ReAct框架、工具调用范式）及大模型微调技术，对编译原理或领域特定语言(DSL)设计有深刻理解。","description":"课题描述\n课题背景：\nLLM Agent 天然适配结构化文本/CLI 交互（如 CLI-Anything 所示 ），但传统工业软件（以 UE 为代表）基于二进制架构与 GUI 交互，与 LLM 的 Token 推理模态存在结构性错位。现有 API 或 MCP 协议难以支撑 Agent 对复杂系统的深度微观控制。亟需建立将引擎运行时状态降维转译为高密度文本流的通用协议，打通“视觉-逻辑”鸿沟。\n\n课题价值：\n1、通用转译架构：构建面向纯文本 Agent 的底层状态转译协议，将复杂系统黑盒状态映射为大模型可内省、可干预的高维文本流；\n2、CLI-UE 中间层：深度解析 UE 的 C++ 反射系统与编辑器核心子系统，将其转化为支持 CoT 调用的标准化文本 API，实现 LLM 推理与引擎执行的闭环；\n3、工业化赋能：突破大模型心智与重度工业引擎的通信瓶颈，确立零样本/少样本条件下自动化关卡生成、引擎级 QA 测试及 AI 原生 Gameplay 的技术路径。\n\n课题要求\n1、包含但不限于计算机科学、软件工程、自动化等相关专业的硕士或优秀本科生；\n2、具备极强的底层源码剖析能力，精通UE C++反射机制及核心子系统源码；\n3、熟悉Agent系统设计架构（如ReAct框架、工具调用范式）及大模型微调技术，对编译原理或领域特定语言(DSL)设计有深刻理解。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139150","sourceKey":"tencent","company":"腾讯","title":"大语言模型推理能力研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139150","duty":"课题背景：\n随着大语言模型的发展，单纯依靠扩大预训练规模带来的收益正在边际递减，研究前沿已全面转向 “慢思考”与测试时计算的扩展。尽管模型在通用自然语言任务上表现优异，但在复杂数学推导、长周期代码生成及多步逻辑规划等深层符号推理任务中，仍面临幻觉频发、自我纠错能力弱及推理链条易断裂等瓶颈。本课题聚焦于提升 LLM 的系统性与原生推理能力，探索以强化学习、自我博弈及动态测试时计算为核心的全链路推理能力增强机制与前沿评测体系。\n\n课题挑战：\n1、长链推理的鲁棒性与内生自我纠错：在多步复杂推理中如何避免错误级联，赋予模型在推理过程中的反思验证能力；\n2、推理能力的跨领域泛化：如何将基于数理逻辑训练出的强推理能力，有效泛化至缺乏明确对错边界的开放域指令遵循、通用自然语言处理甚至多模态智能体任务中。\n\n具体工作：\n参与新一代 LLM 推理能力评测体系建设；主导或参与推理导向的强化学习算法的实验与策略调优；推动相关前沿推理模型及 Agent 系统的工程落地与泛化应用。","requirements":"1、包含但不限于计算机、信息工程、人工智能、自然语言处理、应用数学、统计学、物理学等专业的博士和优秀硕士；\n2、熟练掌握大语言模型基本原理（Transformer架构、预训练、RLHF等），熟悉主流推理增强方法（MCTS、过程奖励模型、RLVR 等）；\n3、熟悉PyTorch、Hugging Face Transformers等深度学习框架，具备大模型训练/微调的实践经验，掌握Python编程语言，具备较强的工程实现能力；\n4、加分项：在NLP/推理/LLM相关领域发表过顶会论文（如NeurIPS、ICML、ICLR、ACL等）；有开源大模型或推理相关项目维护经验。","description":"课题描述\n课题背景：\n随着大语言模型的发展，单纯依靠扩大预训练规模带来的收益正在边际递减，研究前沿已全面转向 “慢思考”与测试时计算的扩展。尽管模型在通用自然语言任务上表现优异，但在复杂数学推导、长周期代码生成及多步逻辑规划等深层符号推理任务中，仍面临幻觉频发、自我纠错能力弱及推理链条易断裂等瓶颈。本课题聚焦于提升 LLM 的系统性与原生推理能力，探索以强化学习、自我博弈及动态测试时计算为核心的全链路推理能力增强机制与前沿评测体系。\n\n课题挑战：\n1、长链推理的鲁棒性与内生自我纠错：在多步复杂推理中如何避免错误级联，赋予模型在推理过程中的反思验证能力；\n2、推理能力的跨领域泛化：如何将基于数理逻辑训练出的强推理能力，有效泛化至缺乏明确对错边界的开放域指令遵循、通用自然语言处理甚至多模态智能体任务中。\n\n具体工作：\n参与新一代 LLM 推理能力评测体系建设；主导或参与推理导向的强化学习算法的实验与策略调优；推动相关前沿推理模型及 Agent 系统的工程落地与泛化应用。\n\n课题要求\n1、包含但不限于计算机、信息工程、人工智能、自然语言处理、应用数学、统计学、物理学等专业的博士和优秀硕士；\n2、熟练掌握大语言模型基本原理（Transformer架构、预训练、RLHF等），熟悉主流推理增强方法（MCTS、过程奖励模型、RLVR 等）；\n3、熟悉PyTorch、Hugging Face Transformers等深度学习框架，具备大模型训练/微调的实践经验，掌握Python编程语言，具备较强的工程实现能力；\n4、加分项：在NLP/推理/LLM相关领域发表过顶会论文（如NeurIPS、ICML、ICLR、ACL等）；有开源大模型或推理相关项目维护经验。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nIEG\n互动娱乐事业群\n\n光子工作室群\n腾讯光子工作室群是全球知名的游戏研发团队，成立以来坚持精品化和国际化发展战略，致力于打造光子宇宙平台，连接全球玩家和游戏生态。 光子持续推出了战术竞技、MOBA、棋牌、MMO、射击、体育、竞速、音乐和模拟经营等多个品类游戏，打造了《和平精英》《欢乐斗地主》《欢乐麻将》等多款热门游戏，合作推出了《PUBG MOBILE》《英雄联盟手游》《金铲铲之战》，为全球亿万用户提供丰富优质的游戏体验。 光子以强大的游戏研发实力、广阔的产品线为基础，在IP衍生、电竞生态、社会责任等领域积极拓展；持续深耕游戏技术和美术核心能力，在中国、美国、新加坡、加拿大、英国、法国、日本、韩国、新西兰等多个国家和地区研发布局，不断探索游戏的无限可能。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139151","sourceKey":"tencent","company":"腾讯","title":"多模态模型架构和训练方案探索","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139151","duty":"课题背景：\n随着人工智能向物理世界与通用智能迈进，单一文本模态的语言模型已难以满足复杂的真实世界交互需求，研究前沿正全面转向涵盖文本、视觉、语音及动作的原生多模态与端到端融合架构。尽管当前模型在基础图文交互上表现尚可，但在端到端语音对话、长时序多模态时空推理以及具身智能的物理规律理解上，仍面临模态间特征冲突、级联误差及训练效率低下等瓶颈。本课题聚焦于突破多模态架构壁垒，探索以原生全模态融合、语音-视觉-文本联合训练及跨模态强化学习为核心的训练方案与评测体系。\n\n课题挑战：\n1、端到端原生融合与跨模态对齐： 如何打破传统 “语音识别 - 文本大模型 - 语音合成” 的级联范式，设计低 “对齐税” 的统一原生架构（如连续 / 离散混合 Tokenizer），实现图、文、音、控等 Any-to-Any 的高效映射，并精准保留语音中的情感、韵律等非文本特征；\n2、复杂时空交互与跨模态泛化： 在包含实时动态语音指令与长周期视觉输入的复杂场景中，如何克服模态间信息异步与逻辑断裂问题，并通过多模态强化学习机制提升模型在真实环境中的全双工拟人化交互与精准指令遵循能力。\n\n具体工作：\n参与新一代原生多模态模型（涵盖图/文/音/视频/Action）的基础架构设计与统一对齐方案研究；主导或参与大规模跨模态（重点关注端到端语音交互、视觉理解等）预训练与 SFT 数据构建闭环；探索多模态强化学习策略的调优；推动前沿多模态 Agent 系统的工程落地与系统性评测。","requirements":"1、包含但不限于计算机、人工智能、信息工程、计算机视觉、自然语言处理、应用数学等专业的博士和优秀硕士；\n2、熟练掌握多模态大模型的基本原理与架构，熟悉视觉预训练、跨模态对齐、RLHF等核心方法，具备大模型训练/微调的实践经验；\n3、熟悉PyTorch、DeepSpeed、Hugging Face Transformers等主流深度学习框架，掌握Python编程，具备较强的实验设计与消融分析能力；\n4、加分项：在计算机视觉、多模态学习等领域发表过顶会论文（如CVPR、NeurIPS、ICLR、ECCV等）；有多模态开源项目维护经验；有游戏/内容领域多模态应用经历。","description":"课题描述\n课题背景：\n随着人工智能向物理世界与通用智能迈进，单一文本模态的语言模型已难以满足复杂的真实世界交互需求，研究前沿正全面转向涵盖文本、视觉、语音及动作的原生多模态与端到端融合架构。尽管当前模型在基础图文交互上表现尚可，但在端到端语音对话、长时序多模态时空推理以及具身智能的物理规律理解上，仍面临模态间特征冲突、级联误差及训练效率低下等瓶颈。本课题聚焦于突破多模态架构壁垒，探索以原生全模态融合、语音-视觉-文本联合训练及跨模态强化学习为核心的训练方案与评测体系。\n\n课题挑战：\n1、端到端原生融合与跨模态对齐： 如何打破传统 “语音识别 - 文本大模型 - 语音合成” 的级联范式，设计低 “对齐税” 的统一原生架构（如连续 / 离散混合 Tokenizer），实现图、文、音、控等 Any-to-Any 的高效映射，并精准保留语音中的情感、韵律等非文本特征；\n2、复杂时空交互与跨模态泛化： 在包含实时动态语音指令与长周期视觉输入的复杂场景中，如何克服模态间信息异步与逻辑断裂问题，并通过多模态强化学习机制提升模型在真实环境中的全双工拟人化交互与精准指令遵循能力。\n\n具体工作：\n参与新一代原生多模态模型（涵盖图/文/音/视频/Action）的基础架构设计与统一对齐方案研究；主导或参与大规模跨模态（重点关注端到端语音交互、视觉理解等）预训练与 SFT 数据构建闭环；探索多模态强化学习策略的调优；推动前沿多模态 Agent 系统的工程落地与系统性评测。\n\n课题要求\n1、包含但不限于计算机、人工智能、信息工程、计算机视觉、自然语言处理、应用数学等专业的博士和优秀硕士；\n2、熟练掌握多模态大模型的基本原理与架构，熟悉视觉预训练、跨模态对齐、RLHF等核心方法，具备大模型训练/微调的实践经验；\n3、熟悉PyTorch、DeepSpeed、Hugging Face Transformers等主流深度学习框架，掌握Python编程，具备较强的实验设计与消融分析能力；\n4、加分项：在计算机视觉、多模态学习等领域发表过顶会论文（如CVPR、NeurIPS、ICLR、ECCV等）；有多模态开源项目维护经验；有游戏/内容领域多模态应用经历。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nIEG\n互动娱乐事业群\n\n光子工作室群\n腾讯光子工作室群是全球知名的游戏研发团队，成立以来坚持精品化和国际化发展战略，致力于打造光子宇宙平台，连接全球玩家和游戏生态。 光子持续推出了战术竞技、MOBA、棋牌、MMO、射击、体育、竞速、音乐和模拟经营等多个品类游戏，打造了《和平精英》《欢乐斗地主》《欢乐麻将》等多款热门游戏，合作推出了《PUBG MOBILE》《英雄联盟手游》《金铲铲之战》，为全球亿万用户提供丰富优质的游戏体验。 光子以强大的游戏研发实力、广阔的产品线为基础，在IP衍生、电竞生态、社会责任等领域积极拓展；持续深耕游戏技术和美术核心能力，在中国、美国、新加坡、加拿大、英国、法国、日本、韩国、新西兰等多个国家和地区研发布局，不断探索游戏的无限可能。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139152","sourceKey":"tencent","company":"腾讯","title":"游戏智能体技术研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139152","duty":"课题背景：\n随着大模型技术的演进，游戏智能体正从传统的基于行为树与单一强化学习范式，全面迈向由大语言模型与多模态视觉 - 语言 - 动作（VLA）架构驱动的通用智能体时代。尽管当前模型在基于文本的社会模拟沙盒（如斯坦福小镇）中展现出了涌现性的群体交互能力，但在处理高维 3D 开放世界、高动态战术竞技环境以及长时间跨度的空间导航与多步决策上，仍面临状态空间爆炸、跨模态动作映射极易失效及多智能体协作策略脆弱等瓶颈。本课题聚焦于探索下一代游戏智能体技术，构建从宏观社会行为演算到微观物理引擎感知（VLA）的全栈式智能体决策架构与评测体系。\n\n课题挑战：\n1、多智能体社会模拟与长程记忆机制： 在构建高自由度沙盒或复杂战术协作团队时，如何设计高效的流式记忆检索、反思机制与群体社会演化规则，避免智能体陷入 “行为死循环”，并实现高拟真度的社会性与团队博弈能力；\n2、开放世界中的 VLA 具身决策与时空推理： 面对高动态的 3D 游戏环境，如何突破纯文本或符号接口的局限，通过原生 VLA 模型实现纯视觉输入下的精准时空感知与零样本动作泛化，克服跨游戏场景或异构引擎间的 “领域鸿沟”。\n\n具体工作：\n参与新一代游戏智能体（涵盖生成式社会智能体与底层 VLA 具身智能体等）的基础架构设计与模型研发；主导或参与大规模游戏交互对局数据的自动化合成与清洗流水线；探索并落地基于环境反馈与自我博弈的高效强化学习算法；推动泛化智能体在前沿游戏品类中的工程落地与系统性能力评测。","requirements":"1、包含但不限于计算机、人工智能、自动化、控制工程、应用数学、运筹学等专业的博士和优秀硕士；\n2、深入理解大语言模型底层机制与多模态 Agent 技术栈；精通生成式多智能体群体模拟或具身智能大模型架构的设计与优化；熟悉强化学习在大模型对齐与推理增强中的最新应用；\n3、精通 Python 编程，熟练驾驭 PyTorch 等主流深度学习框架；具备强大的系统架构搭建与工程实现能力，能打通从 “大模型 / Agent 策略设计” 到 “游戏引擎交互” 的端到端数据与控制闭环；\n4、加分项：在人工智能、游戏AI等领域发表过顶会论文（如NeurIPS、ICML、ICLR等）；有游戏Bot、AI对战或自动化测试项目经验。","description":"课题描述\n课题背景：\n随着大模型技术的演进，游戏智能体正从传统的基于行为树与单一强化学习范式，全面迈向由大语言模型与多模态视觉 - 语言 - 动作（VLA）架构驱动的通用智能体时代。尽管当前模型在基于文本的社会模拟沙盒（如斯坦福小镇）中展现出了涌现性的群体交互能力，但在处理高维 3D 开放世界、高动态战术竞技环境以及长时间跨度的空间导航与多步决策上，仍面临状态空间爆炸、跨模态动作映射极易失效及多智能体协作策略脆弱等瓶颈。本课题聚焦于探索下一代游戏智能体技术，构建从宏观社会行为演算到微观物理引擎感知（VLA）的全栈式智能体决策架构与评测体系。\n\n课题挑战：\n1、多智能体社会模拟与长程记忆机制： 在构建高自由度沙盒或复杂战术协作团队时，如何设计高效的流式记忆检索、反思机制与群体社会演化规则，避免智能体陷入 “行为死循环”，并实现高拟真度的社会性与团队博弈能力；\n2、开放世界中的 VLA 具身决策与时空推理： 面对高动态的 3D 游戏环境，如何突破纯文本或符号接口的局限，通过原生 VLA 模型实现纯视觉输入下的精准时空感知与零样本动作泛化，克服跨游戏场景或异构引擎间的 “领域鸿沟”。\n\n具体工作：\n参与新一代游戏智能体（涵盖生成式社会智能体与底层 VLA 具身智能体等）的基础架构设计与模型研发；主导或参与大规模游戏交互对局数据的自动化合成与清洗流水线；探索并落地基于环境反馈与自我博弈的高效强化学习算法；推动泛化智能体在前沿游戏品类中的工程落地与系统性能力评测。\n\n课题要求\n1、包含但不限于计算机、人工智能、自动化、控制工程、应用数学、运筹学等专业的博士和优秀硕士；\n2、深入理解大语言模型底层机制与多模态 Agent 技术栈；精通生成式多智能体群体模拟或具身智能大模型架构的设计与优化；熟悉强化学习在大模型对齐与推理增强中的最新应用；\n3、精通 Python 编程，熟练驾驭 PyTorch 等主流深度学习框架；具备强大的系统架构搭建与工程实现能力，能打通从 “大模型 / Agent 策略设计” 到 “游戏引擎交互” 的端到端数据与控制闭环；\n4、加分项：在人工智能、游戏AI等领域发表过顶会论文（如NeurIPS、ICML、ICLR等）；有游戏Bot、AI对战或自动化测试项目经验。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nIEG\n互动娱乐事业群\n\n光子工作室群\n腾讯光子工作室群是全球知名的游戏研发团队，成立以来坚持精品化和国际化发展战略，致力于打造光子宇宙平台，连接全球玩家和游戏生态。 光子持续推出了战术竞技、MOBA、棋牌、MMO、射击、体育、竞速、音乐和模拟经营等多个品类游戏，打造了《和平精英》《欢乐斗地主》《欢乐麻将》等多款热门游戏，合作推出了《PUBG MOBILE》《英雄联盟手游》《金铲铲之战》，为全球亿万用户提供丰富优质的游戏体验。 光子以强大的游戏研发实力、广阔的产品线为基础，在IP衍生、电竞生态、社会责任等领域积极拓展；持续深耕游戏技术和美术核心能力，在中国、美国、新加坡、加拿大、英国、法国、日本、韩国、新西兰等多个国家和地区研发布局，不断探索游戏的无限可能。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139153","sourceKey":"tencent","company":"腾讯","title":"基于生成式框架进行3D空间的推理与生成","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139153","duty":"课题背景：\n3D内容生成是游戏研发与虚拟世界构建中的核心需求，传统3D建模依赖大量人工成本。近年来，以NeRF、3D Gaussian Splatting（3DGS）、扩散模型为代表的生成式3D技术取得突破，使文本/图像驱动的3D生成成为可能。然而，当前方法在空间推理一致性、生成质量、可编辑性和生产效率方面仍有较大提升空间。本课题聚焦于将生成式AI框架引入3D空间推理与内容生成，推动游戏3D资产创作的智能化与规模化。\n\n课题挑战：\n1、多视角一致性：生成式方法在不同视角下保持几何与纹理一致性仍是核心难题，尤其在复杂遮挡与精细结构场景下；\n2、3D表征选择与融合：NeRF、3DGS、Mesh等不同表征各有优劣，如何在生成质量、效率与可编辑性间取得最优权衡；\n3、空间推理能力融入：如何使生成模型具备对3D场景中物体关系、空间布局和物理约束的理解与推理能力；\n4、游戏场景适配：游戏3D资产风格多样（写实/卡通）、类目广泛（角色/场景/道具），如何进行领域适配与风格可控生成；\n5、生成效率与实时性：高质量3D生成通常耗时较长，如何通过模型压缩与加速技术满足游戏研发的生产效率要求。\n\n具体工作：\n参与生成式3D模型的研究与训练、3D表征与扩散模型融合方案设计、游戏3D资产自动化生成Pipeline开发，以及3D生成质量评测体系建设。","requirements":"1、包含但不限于计算机图形学、计算机视觉、人工智能、应用数学、信息工程等专业的博士和优秀硕士；\n2、熟悉生成式3D技术（如NeRF、3DGS、扩散模型等）或计算机图形学（渲染、几何处理）基本原理，有相关项目/研究经验；\n3、熟悉PyTorch等深度学习框架，掌握Python编程，具备3D数据处理和可视化能力（有Open3D、Blender等工具使用经验者优先）；\n4、具备较强的数学基础（线性代数、微分几何等）及独立科研能力，能够快速跟进前沿技术进展；\n5、加分项：在3DV、CVPR、NeurIPS、SIGGRAPH等顶会发表过相关论文；有三维内容生成或游戏美术资产自动化相关项目经验。","description":"课题描述\n课题背景：\n3D内容生成是游戏研发与虚拟世界构建中的核心需求，传统3D建模依赖大量人工成本。近年来，以NeRF、3D Gaussian Splatting（3DGS）、扩散模型为代表的生成式3D技术取得突破，使文本/图像驱动的3D生成成为可能。然而，当前方法在空间推理一致性、生成质量、可编辑性和生产效率方面仍有较大提升空间。本课题聚焦于将生成式AI框架引入3D空间推理与内容生成，推动游戏3D资产创作的智能化与规模化。\n\n课题挑战：\n1、多视角一致性：生成式方法在不同视角下保持几何与纹理一致性仍是核心难题，尤其在复杂遮挡与精细结构场景下；\n2、3D表征选择与融合：NeRF、3DGS、Mesh等不同表征各有优劣，如何在生成质量、效率与可编辑性间取得最优权衡；\n3、空间推理能力融入：如何使生成模型具备对3D场景中物体关系、空间布局和物理约束的理解与推理能力；\n4、游戏场景适配：游戏3D资产风格多样（写实/卡通）、类目广泛（角色/场景/道具），如何进行领域适配与风格可控生成；\n5、生成效率与实时性：高质量3D生成通常耗时较长，如何通过模型压缩与加速技术满足游戏研发的生产效率要求。\n\n具体工作：\n参与生成式3D模型的研究与训练、3D表征与扩散模型融合方案设计、游戏3D资产自动化生成Pipeline开发，以及3D生成质量评测体系建设。\n\n课题要求\n1、包含但不限于计算机图形学、计算机视觉、人工智能、应用数学、信息工程等专业的博士和优秀硕士；\n2、熟悉生成式3D技术（如NeRF、3DGS、扩散模型等）或计算机图形学（渲染、几何处理）基本原理，有相关项目/研究经验；\n3、熟悉PyTorch等深度学习框架，掌握Python编程，具备3D数据处理和可视化能力（有Open3D、Blender等工具使用经验者优先）；\n4、具备较强的数学基础（线性代数、微分几何等）及独立科研能力，能够快速跟进前沿技术进展；\n5、加分项：在3DV、CVPR、NeurIPS、SIGGRAPH等顶会发表过相关论文；有三维内容生成或游戏美术资产自动化相关项目经验。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nIEG\n互动娱乐事业群\n\n光子工作室群\n腾讯光子工作室群是全球知名的游戏研发团队，成立以来坚持精品化和国际化发展战略，致力于打造光子宇宙平台，连接全球玩家和游戏生态。 光子持续推出了战术竞技、MOBA、棋牌、MMO、射击、体育、竞速、音乐和模拟经营等多个品类游戏，打造了《和平精英》《欢乐斗地主》《欢乐麻将》等多款热门游戏，合作推出了《PUBG MOBILE》《英雄联盟手游》《金铲铲之战》，为全球亿万用户提供丰富优质的游戏体验。 光子以强大的游戏研发实力、广阔的产品线为基础，在IP衍生、电竞生态、社会责任等领域积极拓展；持续深耕游戏技术和美术核心能力，在中国、美国、新加坡、加拿大、英国、法国、日本、韩国、新西兰等多个国家和地区研发布局，不断探索游戏的无限可能。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139154","sourceKey":"tencent","company":"腾讯","title":"结合控制信号的实时高质量可交互游戏视频生成","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139154","duty":"课题背景：\n可交互视频生成是生成式AI与游戏技术深度融合的前沿方向，旨在让生成式模型实时响应用户控制信号（键盘、手柄、视角等），动态生成流畅、高保真的游戏画面。以GameNGen、Genie、DIAMOND为代表的研究已证明神经网络游戏引擎的可行性。该技术在游戏原型快速验证、无限内容生成和AI驱动关卡设计等场景中具有革命性应用价值。\n\n课题挑战：\n1、实时性与生成质量的平衡：高质量视频生成与毫秒级实时响应之间存在根本性矛盾，如何通过流匹配、一致性模型、KV Cache等技术突破该瓶颈；\n2、控制信号精确响应：如何确保生成帧内容准确响应多样化控制输入（移动、攻击、摄像头旋转等），避免控制漂移与语义不一致；\n3、长序列时序一致性：在长时间游玩中如何维持场景、角色、物理规律的视觉一致性，防止遗忘与画面崩坏；\n4、游戏数据构建：高质量控制信号与画面帧配对数据获取成本高，如何设计高效的数据采集、清洗与自动化标注方案；\n5、多游戏类型泛化：不同类型游戏（动作/策略/RPG）画面风格与控制逻辑差异悬殊，如何提升模型的跨游戏泛化能力。\n\n具体工作：\n参与可交互视频生成模型的架构设计与训练、控制信号条件生成机制研究、游戏视频数据集构建、模型推理加速与实时部署优化，以及生成质量评测体系建设。","requirements":"1、包含但不限于计算机、人工智能、计算机视觉、信息工程、应用数学等专业的博士和优秀硕士；\n2、熟悉视频生成/扩散模型相关技术（如Video Diffusion、DiT、Flow Matching、Consistency Model等）或计算机视觉基础方法，有相关项目/研究经验；\n3、熟悉PyTorch等深度学习框架，具备视频/图像数据处理能力，掌握Python编程，有大规模生成模型训练/微调实践经验者优先；\n4、加分项：在CVPR、NeurIPS、ICLR、ECCV等顶会发表过视频生成、扩散模型相关论文；有游戏视频数据处理或实时渲染相关项目经验。","description":"课题描述\n课题背景：\n可交互视频生成是生成式AI与游戏技术深度融合的前沿方向，旨在让生成式模型实时响应用户控制信号（键盘、手柄、视角等），动态生成流畅、高保真的游戏画面。以GameNGen、Genie、DIAMOND为代表的研究已证明神经网络游戏引擎的可行性。该技术在游戏原型快速验证、无限内容生成和AI驱动关卡设计等场景中具有革命性应用价值。\n\n课题挑战：\n1、实时性与生成质量的平衡：高质量视频生成与毫秒级实时响应之间存在根本性矛盾，如何通过流匹配、一致性模型、KV Cache等技术突破该瓶颈；\n2、控制信号精确响应：如何确保生成帧内容准确响应多样化控制输入（移动、攻击、摄像头旋转等），避免控制漂移与语义不一致；\n3、长序列时序一致性：在长时间游玩中如何维持场景、角色、物理规律的视觉一致性，防止遗忘与画面崩坏；\n4、游戏数据构建：高质量控制信号与画面帧配对数据获取成本高，如何设计高效的数据采集、清洗与自动化标注方案；\n5、多游戏类型泛化：不同类型游戏（动作/策略/RPG）画面风格与控制逻辑差异悬殊，如何提升模型的跨游戏泛化能力。\n\n具体工作：\n参与可交互视频生成模型的架构设计与训练、控制信号条件生成机制研究、游戏视频数据集构建、模型推理加速与实时部署优化，以及生成质量评测体系建设。\n\n课题要求\n1、包含但不限于计算机、人工智能、计算机视觉、信息工程、应用数学等专业的博士和优秀硕士；\n2、熟悉视频生成/扩散模型相关技术（如Video Diffusion、DiT、Flow Matching、Consistency Model等）或计算机视觉基础方法，有相关项目/研究经验；\n3、熟悉PyTorch等深度学习框架，具备视频/图像数据处理能力，掌握Python编程，有大规模生成模型训练/微调实践经验者优先；\n4、加分项：在CVPR、NeurIPS、ICLR、ECCV等顶会发表过视频生成、扩散模型相关论文；有游戏视频数据处理或实时渲染相关项目经验。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nIEG\n互动娱乐事业群\n\n光子工作室群\n腾讯光子工作室群是全球知名的游戏研发团队，成立以来坚持精品化和国际化发展战略，致力于打造光子宇宙平台，连接全球玩家和游戏生态。 光子持续推出了战术竞技、MOBA、棋牌、MMO、射击、体育、竞速、音乐和模拟经营等多个品类游戏，打造了《和平精英》《欢乐斗地主》《欢乐麻将》等多款热门游戏，合作推出了《PUBG MOBILE》《英雄联盟手游》《金铲铲之战》，为全球亿万用户提供丰富优质的游戏体验。 光子以强大的游戏研发实力、广阔的产品线为基础，在IP衍生、电竞生态、社会责任等领域积极拓展；持续深耕游戏技术和美术核心能力，在中国、美国、新加坡、加拿大、英国、法国、日本、韩国、新西兰等多个国家和地区研发布局，不断探索游戏的无限可能。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139155","sourceKey":"tencent","company":"腾讯","title":"游戏内容分发中的生成式推荐：语义ID、受限解码与多模态对齐","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139155","duty":"课题背景：\n当前主流推荐技术仍停留在ID-Based的判别式浅层深度学习主导的DLRM系统，这与以Transformer架构/强化学习为代表的生成式AI技术之间存在显著的“技术代差”，Scaling Law已成为当前AI模型学习的基本准则，但是在推荐系统领域中的探索比较匮乏。因此，推荐系统的业界正在迫切地引入生成式AI的技术能力，推动推荐系统向生成式推荐（Generative Recommendation）的范式演进。\n\n关于生成式推荐，可以从以下几个方向深入研究：\n1、标识符设计: 如何设计适合 LLM 生成且具有语义信息的 Item ID (例如用层级目录树编码)，而不是无意义的数字ID；\n2、受限生成与效率: 如何保证 LLM 生成的结果必须在有效的物品库内，并且在大规模场景下满足低延迟要求？（例如：结合 Trie 树的受限解码、蒸馏小模型）；\n3、多模态对齐: 如何将物品的图像、文本描述与 ID 嵌入在 LLM 的隐空间中对齐，实现多模态生成式推荐；\n4、显式推理引导生成：将“显式推理”引入生成式推荐，使模型在推荐前能先思考用户偏好与物品关系，从而在给出推荐结果的同时，生成可读推理链条。\n\n课题价值：\n1、推动推荐范式从“判别式打分”升级为“可生成、可组合、可解释“，在复杂语境（任务、剧情阶段、社交关系、实时意图）下实现更强的泛化与组合能力；\n2、契合游戏场景的“强语境+强多模态+强实时”特点；\n3、显著提升“可控性、可解释性与运营可用性”，引入显式推理/链路输出后，可以产出“为什么推荐这个”“满足哪些偏好/缺口”的解释；\n4、形成可复用的工程方法论与资产，围绕“语义ID设计、受限解码、Trie/FAISS检索、蒸馏小模型、多模态对齐、推理约束”形成一套可迁移的技术栈；\n5、学术与产业结合点清晰，易产出高质量论文/专利。\n\n课题挑战：\n1、“生成结果必须在物品库内”的硬约束与幻觉问题；\n2、大规模低延迟：生成式推荐的在线成本与吞吐压力，推荐链路通常要求毫秒级~几十毫秒级延迟，且QPS高。LLM推理成本高，受限解码又会增加解码开销；\n挑战包括：KV Cache、批处理、并行、模型蒸馏、小模型对齐、分层路由（简单请求走传统模型，复杂语境走生成式）、以及端到端延迟预算拆解；\n3、语义ID/标识符设计的“表达力—稳定性—可维护性”矛盾；\n4、多模态对齐与冷启动：物品图文与行为序列的统一建模，游戏物品的图像（皮肤/角色立绘）、文本描述（技能/背景）、结构化属性（数值/稀有度）差异很大，在对齐方面存在较大的挑战；\n5、显式推理的真实性与可控性；\n6、评测体系缺口：离线指标难以覆盖在线业务目标，生成式推荐不仅关心NDCG/Recall，还关心：\n（1）合规与安全（禁推、未成年人、版本节奏）；\n（2）多样性/新颖性/探索；\n（3）解释可用性与一致性；\n（4）线上转化与长期留存；需要构建覆盖“效果-效率-可控-安全-可解释”的综合评测与A/B框架；\n7、数据与隐私：训练语料构建、脱敏与合规。\n\n具体工作：\n参与生成式大模型的研发与效果评估，从SID生成、模型架构、评估方式等方面优化模型效果，参与超大规模游戏场景的上线应用与效果调优","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握LLM\\机器学习\\推荐算法相关的基本原理及应用，熟悉caffe、tensorflow，pytorch等至少一个深度学习框架；\n3、较强的工程实现能力，熟悉 Shell/Python/Matlab 至少一种编程语言；\n4、加分项：发表过顶会文章，有维护过具有一定影响力的开源项目。","description":"课题描述\n课题背景：\n当前主流推荐技术仍停留在ID-Based的判别式浅层深度学习主导的DLRM系统，这与以Transformer架构/强化学习为代表的生成式AI技术之间存在显著的“技术代差”，Scaling Law已成为当前AI模型学习的基本准则，但是在推荐系统领域中的探索比较匮乏。因此，推荐系统的业界正在迫切地引入生成式AI的技术能力，推动推荐系统向生成式推荐（Generative Recommendation）的范式演进。\n\n关于生成式推荐，可以从以下几个方向深入研究：\n1、标识符设计: 如何设计适合 LLM 生成且具有语义信息的 Item ID (例如用层级目录树编码)，而不是无意义的数字ID；\n2、受限生成与效率: 如何保证 LLM 生成的结果必须在有效的物品库内，并且在大规模场景下满足低延迟要求？（例如：结合 Trie 树的受限解码、蒸馏小模型）；\n3、多模态对齐: 如何将物品的图像、文本描述与 ID 嵌入在 LLM 的隐空间中对齐，实现多模态生成式推荐；\n4、显式推理引导生成：将“显式推理”引入生成式推荐，使模型在推荐前能先思考用户偏好与物品关系，从而在给出推荐结果的同时，生成可读推理链条。\n\n课题价值：\n1、推动推荐范式从“判别式打分”升级为“可生成、可组合、可解释“，在复杂语境（任务、剧情阶段、社交关系、实时意图）下实现更强的泛化与组合能力；\n2、契合游戏场景的“强语境+强多模态+强实时”特点；\n3、显著提升“可控性、可解释性与运营可用性”，引入显式推理/链路输出后，可以产出“为什么推荐这个”“满足哪些偏好/缺口”的解释；\n4、形成可复用的工程方法论与资产，围绕“语义ID设计、受限解码、Trie/FAISS检索、蒸馏小模型、多模态对齐、推理约束”形成一套可迁移的技术栈；\n5、学术与产业结合点清晰，易产出高质量论文/专利。\n\n课题挑战：\n1、“生成结果必须在物品库内”的硬约束与幻觉问题；\n2、大规模低延迟：生成式推荐的在线成本与吞吐压力，推荐链路通常要求毫秒级~几十毫秒级延迟，且QPS高。LLM推理成本高，受限解码又会增加解码开销；\n挑战包括：KV Cache、批处理、并行、模型蒸馏、小模型对齐、分层路由（简单请求走传统模型，复杂语境走生成式）、以及端到端延迟预算拆解；\n3、语义ID/标识符设计的“表达力—稳定性—可维护性”矛盾；\n4、多模态对齐与冷启动：物品图文与行为序列的统一建模，游戏物品的图像（皮肤/角色立绘）、文本描述（技能/背景）、结构化属性（数值/稀有度）差异很大，在对齐方面存在较大的挑战；\n5、显式推理的真实性与可控性；\n6、评测体系缺口：离线指标难以覆盖在线业务目标，生成式推荐不仅关心NDCG/Recall，还关心：\n（1）合规与安全（禁推、未成年人、版本节奏）；\n（2）多样性/新颖性/探索；\n（3）解释可用性与一致性；\n（4）线上转化与长期留存；需要构建覆盖“效果-效率-可控-安全-可解释”的综合评测与A/B框架；\n7、数据与隐私：训练语料构建、脱敏与合规。\n\n具体工作：\n参与生成式大模型的研发与效果评估，从SID生成、模型架构、评估方式等方面优化模型效果，参与超大规模游戏场景的上线应用与效果调优\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握LLM\\机器学习\\推荐算法相关的基本原理及应用，熟悉caffe、tensorflow，pytorch等至少一个深度学习框架；\n3、较强的工程实现能力，熟悉 Shell/Python/Matlab 至少一种编程语言；\n4、加分项：发表过顶会文章，有维护过具有一定影响力的开源项目。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nIEG\n互动娱乐事业群\n\n光子工作室群\n腾讯光子工作室群是全球知名的游戏研发团队，成立以来坚持精品化和国际化发展战略，致力于打造光子宇宙平台，连接全球玩家和游戏生态。 光子持续推出了战术竞技、MOBA、棋牌、MMO、射击、体育、竞速、音乐和模拟经营等多个品类游戏，打造了《和平精英》《欢乐斗地主》《欢乐麻将》等多款热门游戏，合作推出了《PUBG MOBILE》《英雄联盟手游》《金铲铲之战》，为全球亿万用户提供丰富优质的游戏体验。 光子以强大的游戏研发实力、广阔的产品线为基础，在IP衍生、电竞生态、社会责任等领域积极拓展；持续深耕游戏技术和美术核心能力，在中国、美国、新加坡、加拿大、英国、法国、日本、韩国、新西兰等多个国家和地区研发布局，不断探索游戏的无限可能。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139156","sourceKey":"tencent","company":"腾讯","title":"多模态大模型在游戏场景中的研究与应用","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139156","duty":"课题背景：\n近年来，以GPT-4o、Gemini、Qwen-VL为代表的多模态大模型（Multimodal Large Language Models, MLLMs）在通用视觉理解、跨模态生成等领域取得了突破性进展，成为AI领域最受关注的前沿方向之一。游戏作为天然的多模态富媒体场景，涵盖画面、文本、音频、视频、UI界面、3D模型及玩家行为序列等多种异构信息，为多模态大模型提供了极具价值的落地土壤。然而，当前通用多模态大模型在游戏这一\"高度风格化、强交互、强实时\"的垂直领域中，仍面临领域适配不足、游戏画面细粒度理解能力欠缺、生成可控性弱、游戏专有知识匮乏等核心挑战。因此，本课题聚焦于将多模态大模型的通用能力高效迁移并深度适配至游戏场景，释放其在游戏研发、运营、测试及玩家体验全链路中的价值。典型应用场景例如：基于游戏截图/视频的智能UI元素识别与状态解析，自动化检测穿模、渲染异常等画面缺陷；构建\"看懂游戏画面、理解游戏语境\"的多模态对话系统，实现基于截图的智能客服问答、游戏攻略自动生成；游戏视频长时序理解，包括操作序列识别、高光时刻自动提取与战斗片段智能摘要等等。\n\n课题挑战：\n1、游戏领域多模态数据建设： 游戏画面具有高度风格化、类别多样、UI元素密集等特点，如何构建高质量的游戏领域多模态训练数据集与评测Benchmark？如何设计高效的数据标注流水线与自动化数据合成策略，以覆盖游戏场景中的多样视觉理解与生成需求？\n2、游戏视觉细粒度理解与定位： 游戏画面中包含大量领域特有的视觉元素（技能图标、状态栏、小地图标注、装备属性面板等），通用多模态模型的识别精度不足。如何通过领域适配微调、视觉Grounding增强等方法，使模型具备对游戏画面的细粒度理解与精确定位能力？\n3、游戏视频长时序理解与推理： 游戏视频包含复杂的时序动态信息（操作序列、战斗节奏、剧情进展），如何在长视频理解中平衡计算效率与时序建模精度？如何使模型具备跨时间步的因果推理与事件关联能力？\n4、游戏专有知识融合与多模态检索： 游戏场景中存在大量专有术语、机制规则、版本更新知识等，如何将结构化/非结构化的游戏知识与视觉信息高效融合？如何构建统一的游戏多模态表征空间，实现\"以图搜资产\"\"以文本检索3D模型\"等跨模态检索能力？\n5、推理效率与部署优化： 游戏场景对实时性要求高（如实时画面理解、在线客服响应），大规模多模态模型的推理延迟和计算开销难以直接满足线上需求。如何通过模型蒸馏、量化、推测解码等技术实现多模态大模型在游戏场景中的高效部署？\n\n具体工作：\n你将参与到游戏领域多模态数据集构建与Benchmark设计、多模态大模型的游戏领域适配微调（视觉理解/对话）、游戏画面细粒度理解与视觉Grounding能力建设、游戏视频长时序理解与高光时刻提取、游戏多模态知识库构建与跨模态检索系统搭建、以及模型推理优化与线上部署等工作中，提升多模态大模型在游戏研发、运营、测试与玩家体验全链路中的实际应用能力。","requirements":"1、包含但不限于计算机科学、人工智能、模式识别、信息工程、多媒体技术、计算机视觉、自然语言处理、电子工程、应用数学、统计学、自动化、软件工程等专业的博士和优秀硕士；\n2、熟练掌握多模态大模型（如CLIP、LLaVA、Qwen-VL、GPT-4V等）的基本原理与技术架构，熟悉视觉-语言预训练、指令微调、RLHF等核心方法，具备大模型训练/微调的实践经验；\n3、熟悉PyTorch、DeepSpeed、Hugging Face Transformers等至少一个主流深度学习/大模型训练框架，具有较强的工程实现能力；\n4、熟悉Shell/Python等编程语言，具备良好的代码规范与实验管理习惯；\n5、加分项：在计算机视觉、多模态学习、NLP等相关领域发表过顶会/顶刊论文（如CVPR、NeurIPS、ACL、ICLR、AAAI等）；有多模态大模型相关开源项目维护经验；有游戏行业相关项目经历。","description":"课题描述\n课题背景：\n近年来，以GPT-4o、Gemini、Qwen-VL为代表的多模态大模型（Multimodal Large Language Models, MLLMs）在通用视觉理解、跨模态生成等领域取得了突破性进展，成为AI领域最受关注的前沿方向之一。游戏作为天然的多模态富媒体场景，涵盖画面、文本、音频、视频、UI界面、3D模型及玩家行为序列等多种异构信息，为多模态大模型提供了极具价值的落地土壤。然而，当前通用多模态大模型在游戏这一\"高度风格化、强交互、强实时\"的垂直领域中，仍面临领域适配不足、游戏画面细粒度理解能力欠缺、生成可控性弱、游戏专有知识匮乏等核心挑战。因此，本课题聚焦于将多模态大模型的通用能力高效迁移并深度适配至游戏场景，释放其在游戏研发、运营、测试及玩家体验全链路中的价值。典型应用场景例如：基于游戏截图/视频的智能UI元素识别与状态解析，自动化检测穿模、渲染异常等画面缺陷；构建\"看懂游戏画面、理解游戏语境\"的多模态对话系统，实现基于截图的智能客服问答、游戏攻略自动生成；游戏视频长时序理解，包括操作序列识别、高光时刻自动提取与战斗片段智能摘要等等。\n\n课题挑战：\n1、游戏领域多模态数据建设： 游戏画面具有高度风格化、类别多样、UI元素密集等特点，如何构建高质量的游戏领域多模态训练数据集与评测Benchmark？如何设计高效的数据标注流水线与自动化数据合成策略，以覆盖游戏场景中的多样视觉理解与生成需求？\n2、游戏视觉细粒度理解与定位： 游戏画面中包含大量领域特有的视觉元素（技能图标、状态栏、小地图标注、装备属性面板等），通用多模态模型的识别精度不足。如何通过领域适配微调、视觉Grounding增强等方法，使模型具备对游戏画面的细粒度理解与精确定位能力？\n3、游戏视频长时序理解与推理： 游戏视频包含复杂的时序动态信息（操作序列、战斗节奏、剧情进展），如何在长视频理解中平衡计算效率与时序建模精度？如何使模型具备跨时间步的因果推理与事件关联能力？\n4、游戏专有知识融合与多模态检索： 游戏场景中存在大量专有术语、机制规则、版本更新知识等，如何将结构化/非结构化的游戏知识与视觉信息高效融合？如何构建统一的游戏多模态表征空间，实现\"以图搜资产\"\"以文本检索3D模型\"等跨模态检索能力？\n5、推理效率与部署优化： 游戏场景对实时性要求高（如实时画面理解、在线客服响应），大规模多模态模型的推理延迟和计算开销难以直接满足线上需求。如何通过模型蒸馏、量化、推测解码等技术实现多模态大模型在游戏场景中的高效部署？\n\n具体工作：\n你将参与到游戏领域多模态数据集构建与Benchmark设计、多模态大模型的游戏领域适配微调（视觉理解/对话）、游戏画面细粒度理解与视觉Grounding能力建设、游戏视频长时序理解与高光时刻提取、游戏多模态知识库构建与跨模态检索系统搭建、以及模型推理优化与线上部署等工作中，提升多模态大模型在游戏研发、运营、测试与玩家体验全链路中的实际应用能力。\n\n课题要求\n1、包含但不限于计算机科学、人工智能、模式识别、信息工程、多媒体技术、计算机视觉、自然语言处理、电子工程、应用数学、统计学、自动化、软件工程等专业的博士和优秀硕士；\n2、熟练掌握多模态大模型（如CLIP、LLaVA、Qwen-VL、GPT-4V等）的基本原理与技术架构，熟悉视觉-语言预训练、指令微调、RLHF等核心方法，具备大模型训练/微调的实践经验；\n3、熟悉PyTorch、DeepSpeed、Hugging Face Transformers等至少一个主流深度学习/大模型训练框架，具有较强的工程实现能力；\n4、熟悉Shell/Python等编程语言，具备良好的代码规范与实验管理习惯；\n5、加分项：在计算机视觉、多模态学习、NLP等相关领域发表过顶会/顶刊论文（如CVPR、NeurIPS、ACL、ICLR、AAAI等）；有多模态大模型相关开源项目维护经验；有游戏行业相关项目经历。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nIEG\n互动娱乐事业群\n\n光子工作室群\n腾讯光子工作室群是全球知名的游戏研发团队，成立以来坚持精品化和国际化发展战略，致力于打造光子宇宙平台，连接全球玩家和游戏生态。 光子持续推出了战术竞技、MOBA、棋牌、MMO、射击、体育、竞速、音乐和模拟经营等多个品类游戏，打造了《和平精英》《欢乐斗地主》《欢乐麻将》等多款热门游戏，合作推出了《PUBG MOBILE》《英雄联盟手游》《金铲铲之战》，为全球亿万用户提供丰富优质的游戏体验。 光子以强大的游戏研发实力、广阔的产品线为基础，在IP衍生、电竞生态、社会责任等领域积极拓展；持续深耕游戏技术和美术核心能力，在中国、美国、新加坡、加拿大、英国、法国、日本、韩国、新西兰等多个国家和地区研发布局，不断探索游戏的无限可能。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139157","sourceKey":"tencent","company":"腾讯","title":"游戏场景中AI Agent的研究与应用","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139157","duty":"课题背景：\n近年来，以大语言模型（LLM）为认知核心的AI Agent技术快速发展，其\"感知—规划—决策—行动—反思\"的闭环能力框架已在软件开发、科学研究、办公自动化等通用场景中展现出强大潜力。游戏作为具备明确目标、丰富交互、复杂规则与动态环境的\"天然Agent试验场\"，为AI Agent的研究与应用提供了理想且极具挑战性的落地土壤。然而，游戏场景对Agent在实时决策、长程规划、多角色协作、环境泛化以及拟人化表现等方面提出了远高于通用场景的要求，当前基于LLM的Agent架构在游戏领域的适配与优化仍处于早期阶段。因此，本课题聚焦于构建面向游戏场景的高能力AI Agent系统，典型应用场景例如：Agent自主理解游戏任务目标，通过感知游戏画面、解析游戏状态、调用操作接口，完成复杂的长程游戏任务（如副本通关、主线任务推进）；基于LLM驱动的智能NPC，具备个性化性格与情感状态，能够根据玩家行为动态调整对话与行为，实现沉浸式交互体验；Agent驱动的游戏自动化测试，自主探索地图、遍历任务流程、发现并复现Bug，显著提升QA效率等等。\n\n课题挑战：\n1、游戏Agent架构设计与环境接入： 游戏环境具有多模态观测（画面、小地图、状态面板、聊天信息等）与多类型动作空间（离散指令、连续操控、自然语言对话等）的特点。如何设计模块化、可扩展的Agent认知架构（感知、记忆、规划、行动、反思），使其能够高效接入异构游戏环境并完成复杂任务？如何设计标准化的游戏环境接口与观测-动作抽象层？\n2、长程规划与层级决策： 游戏任务往往具备高度的层级结构与长程依赖（如主线任务→子目标→具体操作序列），决策序列可长达数百甚至数千步。如何使Agent具备从高层策略到低层执行的层级规划能力？如何结合LLM的推理能力与强化学习的策略优化实现高效的目标分解与动态重规划？如何应对游戏中的稀疏奖励与超长决策Horizon问题？\n3、Agent记忆系统设计与知识管理： 游戏Agent需要同时维护短期工作记忆（当前任务上下文、近期观测）、长期经验记忆（历史策略与成败经验总结）以及世界知识记忆（游戏机制、地图信息、物品属性等）。如何设计高效的记忆存储、检索、更新与遗忘机制？如何避免LLM上下文窗口溢出与信息过载导致的决策质量下降？\n多Agent协作与对抗博弈： 游戏中广泛存在多角色协作（组队副本、团战配合）与竞争对抗（PvP、策略博弈）场景。如何设计多Agent间的高效通信协议与协作机制？如何使多个LLM-based Agent在信息不完全、动态变化的博弈环境中涌现出有效的团队策略？如何避免多Agent系统中的协调失败、通信冗余与策略坍缩问题？\n4、奖励系统设计与强化学习优化： 对于复杂的游戏任务，环境反馈往往是稀疏且延迟的。如何结合游戏沙盒环境设计有效的稠密/稀疏奖励信号？如何利用LLM自评估、过程奖励模型（PRM）等方法构建可靠的奖励系统？如何通过强化学习（RLHF/RLAIF、PPO、GRPO等）进一步优化Agent的决策策略？\n\n具体工作：\n你将参与到游戏Agent认知架构设计与环境接口开发、层级规划与任务分解策略研究、Agent记忆系统（短期/长期/世界知识）的构建与优化、多Agent协作与博弈机制设计、游戏自动化测试Agent开发（自主探索/Bug发现/流程通测）、奖励系统建设与强化学习策略优化等工作中，提升大模型驱动的AI Agent在游戏研发、测试、运营及玩家体验场景中的实际能力与落地效果。","requirements":"1、包含但不限于计算机科学、人工智能、自动化、控制工程、模式识别、软件工程、信息工程、机器人学、认知科学、应用数学、统计学、运筹学等专业的博士和优秀硕士；\n2、熟练掌握大语言模型（LLM）基本原理与应用，熟悉Agent相关技术栈（如Prompt Engineering、ReAct、Chain-of-Thought、Tool Use、RAG等），了解强化学习基本方法（PPO、DQN、MCTS等）；\n3、熟悉PyTorch、Hugging Face Transformers、LangChain/LlamaIndex等至少一个主流深度学习或Agent开发框架，具备较强的工程实现与系统搭建能力；\n4、熟悉Python编程语言，具备良好的软件工程素养，熟悉Linux开发环境；\n5、加分项：在AI Agent、强化学习、NLP、游戏AI等相关领域发表过顶会/顶刊论文（如NeurIPS、ICML、ICLR、ACL、AAAI、CoRL等）；有游戏AI相关项目（如游戏Bot、自动化测试、智能NPC等）开发经验；有维护过具有一定影响力的开源项目。","description":"课题描述\n课题背景：\n近年来，以大语言模型（LLM）为认知核心的AI Agent技术快速发展，其\"感知—规划—决策—行动—反思\"的闭环能力框架已在软件开发、科学研究、办公自动化等通用场景中展现出强大潜力。游戏作为具备明确目标、丰富交互、复杂规则与动态环境的\"天然Agent试验场\"，为AI Agent的研究与应用提供了理想且极具挑战性的落地土壤。然而，游戏场景对Agent在实时决策、长程规划、多角色协作、环境泛化以及拟人化表现等方面提出了远高于通用场景的要求，当前基于LLM的Agent架构在游戏领域的适配与优化仍处于早期阶段。因此，本课题聚焦于构建面向游戏场景的高能力AI Agent系统，典型应用场景例如：Agent自主理解游戏任务目标，通过感知游戏画面、解析游戏状态、调用操作接口，完成复杂的长程游戏任务（如副本通关、主线任务推进）；基于LLM驱动的智能NPC，具备个性化性格与情感状态，能够根据玩家行为动态调整对话与行为，实现沉浸式交互体验；Agent驱动的游戏自动化测试，自主探索地图、遍历任务流程、发现并复现Bug，显著提升QA效率等等。\n\n课题挑战：\n1、游戏Agent架构设计与环境接入： 游戏环境具有多模态观测（画面、小地图、状态面板、聊天信息等）与多类型动作空间（离散指令、连续操控、自然语言对话等）的特点。如何设计模块化、可扩展的Agent认知架构（感知、记忆、规划、行动、反思），使其能够高效接入异构游戏环境并完成复杂任务？如何设计标准化的游戏环境接口与观测-动作抽象层？\n2、长程规划与层级决策： 游戏任务往往具备高度的层级结构与长程依赖（如主线任务→子目标→具体操作序列），决策序列可长达数百甚至数千步。如何使Agent具备从高层策略到低层执行的层级规划能力？如何结合LLM的推理能力与强化学习的策略优化实现高效的目标分解与动态重规划？如何应对游戏中的稀疏奖励与超长决策Horizon问题？\n3、Agent记忆系统设计与知识管理： 游戏Agent需要同时维护短期工作记忆（当前任务上下文、近期观测）、长期经验记忆（历史策略与成败经验总结）以及世界知识记忆（游戏机制、地图信息、物品属性等）。如何设计高效的记忆存储、检索、更新与遗忘机制？如何避免LLM上下文窗口溢出与信息过载导致的决策质量下降？\n多Agent协作与对抗博弈： 游戏中广泛存在多角色协作（组队副本、团战配合）与竞争对抗（PvP、策略博弈）场景。如何设计多Agent间的高效通信协议与协作机制？如何使多个LLM-based Agent在信息不完全、动态变化的博弈环境中涌现出有效的团队策略？如何避免多Agent系统中的协调失败、通信冗余与策略坍缩问题？\n4、奖励系统设计与强化学习优化： 对于复杂的游戏任务，环境反馈往往是稀疏且延迟的。如何结合游戏沙盒环境设计有效的稠密/稀疏奖励信号？如何利用LLM自评估、过程奖励模型（PRM）等方法构建可靠的奖励系统？如何通过强化学习（RLHF/RLAIF、PPO、GRPO等）进一步优化Agent的决策策略？\n\n具体工作：\n你将参与到游戏Agent认知架构设计与环境接口开发、层级规划与任务分解策略研究、Agent记忆系统（短期/长期/世界知识）的构建与优化、多Agent协作与博弈机制设计、游戏自动化测试Agent开发（自主探索/Bug发现/流程通测）、奖励系统建设与强化学习策略优化等工作中，提升大模型驱动的AI Agent在游戏研发、测试、运营及玩家体验场景中的实际能力与落地效果。\n\n课题要求\n1、包含但不限于计算机科学、人工智能、自动化、控制工程、模式识别、软件工程、信息工程、机器人学、认知科学、应用数学、统计学、运筹学等专业的博士和优秀硕士；\n2、熟练掌握大语言模型（LLM）基本原理与应用，熟悉Agent相关技术栈（如Prompt Engineering、ReAct、Chain-of-Thought、Tool Use、RAG等），了解强化学习基本方法（PPO、DQN、MCTS等）；\n3、熟悉PyTorch、Hugging Face Transformers、LangChain/LlamaIndex等至少一个主流深度学习或Agent开发框架，具备较强的工程实现与系统搭建能力；\n4、熟悉Python编程语言，具备良好的软件工程素养，熟悉Linux开发环境；\n5、加分项：在AI Agent、强化学习、NLP、游戏AI等相关领域发表过顶会/顶刊论文（如NeurIPS、ICML、ICLR、ACL、AAAI、CoRL等）；有游戏AI相关项目（如游戏Bot、自动化测试、智能NPC等）开发经验；有维护过具有一定影响力的开源项目。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nIEG\n互动娱乐事业群\n\n光子工作室群\n腾讯光子工作室群是全球知名的游戏研发团队，成立以来坚持精品化和国际化发展战略，致力于打造光子宇宙平台，连接全球玩家和游戏生态。 光子持续推出了战术竞技、MOBA、棋牌、MMO、射击、体育、竞速、音乐和模拟经营等多个品类游戏，打造了《和平精英》《欢乐斗地主》《欢乐麻将》等多款热门游戏，合作推出了《PUBG MOBILE》《英雄联盟手游》《金铲铲之战》，为全球亿万用户提供丰富优质的游戏体验。 光子以强大的游戏研发实力、广阔的产品线为基础，在IP衍生、电竞生态、社会责任等领域积极拓展；持续深耕游戏技术和美术核心能力，在中国、美国、新加坡、加拿大、英国、法国、日本、韩国、新西兰等多个国家和地区研发布局，不断探索游戏的无限可能。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139158","sourceKey":"tencent","company":"腾讯","title":"游戏助手智能体-多模态理解应用能力研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139158","duty":"课题背景：\n当前游戏智能体在多模态交互上存在明显短板：视觉语言模型（VLM）对游戏场景理解浅、实时性不足，且难以融合玩家操作行为、自然语言表达等多源信息，无法提供精准高效的游戏辅助。本课题聚焦游戏助手场景，以 VLM 深度研究为核心，构建可跨游戏品类推广的多模态理解能力，为玩家提供智能指引、操作辅助等功能，提升游戏体验与业务价值。\n\n课题挑战：\n游戏域 VLM 高效理解挑战：游戏画面高动态、UI 复杂、弱文本依赖，传统 VLM 易误判场景、漏检关键元素，且需满足毫秒级实时推理要求，同时要实现新游戏 / 新玩法的少样本快速适配。\n多模态信息融合与意图建模挑战：需整合游戏视觉、玩家语音 / 文本、操作行为、历史交互等异构数据，精准解析模糊、动态的玩家意图，同时构建长期记忆以支撑连贯辅助。\n跨场景泛化与工程落地挑战：不同游戏品类逻辑差异大，模型需具备强跨域泛化能力；同时要满足低延迟、高并发、多平台兼容的商业化要求，实现技术到功能的快速转化。\n\n具体工作：\n你将参与游戏域 VLM 优化、多模态信息融合、用户意图建模、跨场景泛化技术研发，将成果转化为智能指引、操作辅助等游戏助手功能，提升智能体的实时理解与辅助能力。","requirements":"1、包含但不限于数学、计算机、人工智能等相关专业的博士和优秀硕士；\n2、熟练掌握计算机视觉和图像处理相关的基本算法及应用，熟悉tensorflow，pytorch等至少一个深度学习框架；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python至少一种编程语言。","description":"课题描述\n课题背景：\n当前游戏智能体在多模态交互上存在明显短板：视觉语言模型（VLM）对游戏场景理解浅、实时性不足，且难以融合玩家操作行为、自然语言表达等多源信息，无法提供精准高效的游戏辅助。本课题聚焦游戏助手场景，以 VLM 深度研究为核心，构建可跨游戏品类推广的多模态理解能力，为玩家提供智能指引、操作辅助等功能，提升游戏体验与业务价值。\n\n课题挑战：\n游戏域 VLM 高效理解挑战：游戏画面高动态、UI 复杂、弱文本依赖，传统 VLM 易误判场景、漏检关键元素，且需满足毫秒级实时推理要求，同时要实现新游戏 / 新玩法的少样本快速适配。\n多模态信息融合与意图建模挑战：需整合游戏视觉、玩家语音 / 文本、操作行为、历史交互等异构数据，精准解析模糊、动态的玩家意图，同时构建长期记忆以支撑连贯辅助。\n跨场景泛化与工程落地挑战：不同游戏品类逻辑差异大，模型需具备强跨域泛化能力；同时要满足低延迟、高并发、多平台兼容的商业化要求，实现技术到功能的快速转化。\n\n具体工作：\n你将参与游戏域 VLM 优化、多模态信息融合、用户意图建模、跨场景泛化技术研发，将成果转化为智能指引、操作辅助等游戏助手功能，提升智能体的实时理解与辅助能力。\n\n课题要求\n1、包含但不限于数学、计算机、人工智能等相关专业的博士和优秀硕士；\n2、熟练掌握计算机视觉和图像处理相关的基本算法及应用，熟悉tensorflow，pytorch等至少一个深度学习框架；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python至少一种编程语言。\n\nIEG\n互动娱乐事业群\n\nWeGame游戏平台\nWeGame游戏平台，作为国内领先的PC游戏平台，汇聚了全球顶尖的服务型游戏，通过深度定制的游戏助手，致力于为PC玩家提供优质的娱乐体验。我们坚持以玩家为中心。从一个功能的上线到一次社区活动的策划，我们用最专业的态度守护每一份热爱，让复杂的系统化为极致简单的用户体验。​面对AI时代的浪潮，WeGame正将进化为一个能够理解玩家、感知需求的“智能伙伴”，让每一个玩家都能在 AI 的助力下，享受到更简单、更纯粹的游戏乐趣。\n​如果你热爱游戏，对未来保持好奇，并渴望在 AI 驱动的变革中留下自己的印记，无论你是技术极客、产品专家还是运营达人，WeGame 都是你施展才华的绝佳舞台。\n加入我们，不只运营平台，更在与千万玩家一同，共创 PC 游戏的未来。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139159","sourceKey":"tencent","company":"腾讯","title":"游戏智能NPC-大模型角色意图与社会化自演进方法研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139159","duty":"课题背景：\n当下游戏产业加速向开放世界集群式智能NPC方向升级，对标类斯坦福小镇虚拟社会场景，玩家与行业对虚拟生态的诉求，早已跳出单一脚本化NPC，转而追求打造多NPC共存、具备独立三观、能在预设游戏世界里完成自主社会化生存的沉浸式生态。传统NPC依赖固定行为树与人工脚本，无独立认知、无自主社交、无长期成长逻辑，完全无法支撑多NPC协同的虚拟社会运转，更难以实现拟人化的长期生存与交互。\n随着大模型与具身智能技术落地，结合强化学习的动态优化路径，为智能NPC的三观塑造、社会化交互、自演进成长提供了可行方案。本课题聚焦多NPC集群的智能交互体系研发，核心是赋予单个NPC完整三观体系与自主生存逻辑，让多NPC在统一游戏世界观内完成社交互动、关系搭建、行为迭代的社会化生存，同时通过强化学习持续优化模型生成效果与NPC交互体验，逐步探索游戏场景下AGI的落地与演进，打造真正具备自主意识与社会属性的虚拟角色生态。\n\n课题挑战：\n1、行为一致性挑战：多NPC需具备差异化、稳定的三观体系与人格设定，而非通用随机行为，如何构建可量化、可落地的NPC三观建模框架，保证NPC的日常决策、社交选择、行为偏好始终贴合自身认知逻辑，杜绝人设崩塌与行为割裂，是核心基础难题；\n2、集群交互挑战：实现多NPC之间自主社交、关系维系、群体互动、环境适应的全流程社会化生存，如何搭建贴合预设游戏世界的社会规则与交互逻辑，解决多NPC协同冲突、交互闭环、长期关系沉淀问题，是虚拟生态搭建的核心难点；\n3、强化学习适配挑战：常规强化学习算法高度依赖人工标注数据与显性、标准化的奖励信号，而本课题面向开放式虚拟社会场景，既不具备开展大规模人工数据标注的条件，也无法针对NPC社会化交互、三观决策行为预设明确奖励规则，如何在无显性奖励的前提下，搭建适配多NPC集群的强化学习机制，实现算法高效、规模化落地与持续迭代，是课题面临的重大技术难题；\n4、工程化落地挑战：课题最终指向AGI方向的虚拟智能体探索，既要实现NPC的长期自主演进、经验沉淀、认知升级，又要满足游戏场景低延迟、高稳定的工程化要求，平衡AGI探索的前沿性与游戏落地的实用性，是技术突破的核心瓶颈。\n\n具体工作：\n参与智能NPC算法研发，包括但不限于：角色扮演，长上下文管理，工具调用，多模态感知，训练数据合成，benchmark构建，强化学习应用，实时推理和系统优化等。","requirements":"1、学历专业：博士研究生或优秀硕士研究生，人工智能、计算机科学与技术等相关专业，研究方向聚焦大模型、具身智能、强化学习优先；\n2、核心工程与框架能力：具备扎实的深度学习工程实现能力，熟练掌握PyTorch深度学习框架，精通Transformer等核心大模型架构，熟悉DeepSpeed、Megatron等大模型分布式训练框架，具备模型训练优化与工程落地实操经验；\n3、专项算法能力：熟悉强化学习算法，熟悉角色扮演相关技术，熟悉多智能体相关算法；\n4、核心素养：具备较强的算法研发、问题排查与落地迭代能力，能够适配课题前沿探索与工程化落地双重需求。\n\n加分项：\n1、在ACL、ICML、ICLR等会议发表过高质量论文；或者有相关开源项目，算法竞赛中取得优异成绩者优先；\n2、热爱游戏，有丰富游戏经验，且认可AI结合游戏方向者优先。","description":"课题描述\n课题背景：\n当下游戏产业加速向开放世界集群式智能NPC方向升级，对标类斯坦福小镇虚拟社会场景，玩家与行业对虚拟生态的诉求，早已跳出单一脚本化NPC，转而追求打造多NPC共存、具备独立三观、能在预设游戏世界里完成自主社会化生存的沉浸式生态。传统NPC依赖固定行为树与人工脚本，无独立认知、无自主社交、无长期成长逻辑，完全无法支撑多NPC协同的虚拟社会运转，更难以实现拟人化的长期生存与交互。\n随着大模型与具身智能技术落地，结合强化学习的动态优化路径，为智能NPC的三观塑造、社会化交互、自演进成长提供了可行方案。本课题聚焦多NPC集群的智能交互体系研发，核心是赋予单个NPC完整三观体系与自主生存逻辑，让多NPC在统一游戏世界观内完成社交互动、关系搭建、行为迭代的社会化生存，同时通过强化学习持续优化模型生成效果与NPC交互体验，逐步探索游戏场景下AGI的落地与演进，打造真正具备自主意识与社会属性的虚拟角色生态。\n\n课题挑战：\n1、行为一致性挑战：多NPC需具备差异化、稳定的三观体系与人格设定，而非通用随机行为，如何构建可量化、可落地的NPC三观建模框架，保证NPC的日常决策、社交选择、行为偏好始终贴合自身认知逻辑，杜绝人设崩塌与行为割裂，是核心基础难题；\n2、集群交互挑战：实现多NPC之间自主社交、关系维系、群体互动、环境适应的全流程社会化生存，如何搭建贴合预设游戏世界的社会规则与交互逻辑，解决多NPC协同冲突、交互闭环、长期关系沉淀问题，是虚拟生态搭建的核心难点；\n3、强化学习适配挑战：常规强化学习算法高度依赖人工标注数据与显性、标准化的奖励信号，而本课题面向开放式虚拟社会场景，既不具备开展大规模人工数据标注的条件，也无法针对NPC社会化交互、三观决策行为预设明确奖励规则，如何在无显性奖励的前提下，搭建适配多NPC集群的强化学习机制，实现算法高效、规模化落地与持续迭代，是课题面临的重大技术难题；\n4、工程化落地挑战：课题最终指向AGI方向的虚拟智能体探索，既要实现NPC的长期自主演进、经验沉淀、认知升级，又要满足游戏场景低延迟、高稳定的工程化要求，平衡AGI探索的前沿性与游戏落地的实用性，是技术突破的核心瓶颈。\n\n具体工作：\n参与智能NPC算法研发，包括但不限于：角色扮演，长上下文管理，工具调用，多模态感知，训练数据合成，benchmark构建，强化学习应用，实时推理和系统优化等。\n\n课题要求\n1、学历专业：博士研究生或优秀硕士研究生，人工智能、计算机科学与技术等相关专业，研究方向聚焦大模型、具身智能、强化学习优先；\n2、核心工程与框架能力：具备扎实的深度学习工程实现能力，熟练掌握PyTorch深度学习框架，精通Transformer等核心大模型架构，熟悉DeepSpeed、Megatron等大模型分布式训练框架，具备模型训练优化与工程落地实操经验；\n3、专项算法能力：熟悉强化学习算法，熟悉角色扮演相关技术，熟悉多智能体相关算法；\n4、核心素养：具备较强的算法研发、问题排查与落地迭代能力，能够适配课题前沿探索与工程化落地双重需求。\n\n加分项：\n1、在ACL、ICML、ICLR等会议发表过高质量论文；或者有相关开源项目，算法竞赛中取得优异成绩者优先；\n2、热爱游戏，有丰富游戏经验，且认可AI结合游戏方向者优先。\n\nIEG\n互动娱乐事业群\n\n生态发展部\n生态发展部致力于在AI时代打造游戏设计制作的全新范式。我们汇聚全链路顶尖专家，将前沿创意与实战经验沉淀为可复用的平台化解决方案，我们将AI Agent与全新的轻度游戏设计理念结合，再辅助于免费资产库、海量预制逻辑模块与强大的AIGC能力，旨在让开发者无需代码即可高效实现创意，推动“人人皆可创作”的愿景。\n\n在这里，你将有机会深度参与一线项目攻坚，直接助力产品成功；同时也能投身于面向未来的前瞻探索，通过「代号Craft」共同定义下一代游戏开发标准，推动AI进化为“智能创作伙伴”。我们致力于通过体系化、平台化的能力建设，让好创意加速落地，提升项目成功率。\n\n如果你怀揣创业心态，拥有硬核实力，并渴望将不凡的野心付诸实践，欢迎加入。在这里，你不仅是参与项目，更是亲手打造能赋能整个行业的核心平台，共同构建下一代游戏研发生态，一起把不可能变为行业标杆。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139160","sourceKey":"tencent","company":"腾讯","title":"游戏智能NPC-文生动作大模型方法研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139160","duty":"课题背景：\n随着游戏产业从“内容生产驱动”逐步迈向“智能交互驱动”的新阶段，玩家对虚拟角色的真实感、表现力与互动能力提出了更高要求。当前游戏中的角色动作主要依赖于人工动画制作、动作捕捉或有限的动作库拼接，这种方式制作成本高、扩展性差，且难以根据实时语义需求生成丰富多样的动作表现。近年来，大语言模型与生成式人工智能技术的发展，为“文本到动作生成（Text-to-Motion）”提供了新的技术路径。通过构建融合语言理解与人体运动建模的大规模生成模型，可以实现从自然语言描述到角色动作序列的自动生成，使NPC能够理解语义并以拟人化的肢体行为进行表达。然而，在游戏实时环境中，动作生成不仅需要语义准确，还需要满足实时性、物理合理性和长时动作一致性等工程要求。因此，本课题旨在研发面向游戏智能NPC的文生动作大模型（Text-to-Motion Foundation Model），构建从文本语义理解到角色动作生成的端到端技术体系，使游戏角色能够根据语言语义实时生成自然、流畅且符合角色设定的动作表现，从而显著提升游戏角色的表现力与交互体验。\n\n课题挑战：\n1、语言语义与动作表达对齐挑战：自然语言具有高度抽象性，而人体动作是连续的高维时序信号。如何建立语言语义与动作序列之间的有效对齐关系，使模型准确理解动作意图并生成合理的运动，是文生动作模型面临的重要问题；\n2、实时生成与系统延迟挑战：游戏NPC动作生成通常需要在极低延迟下完成，以保证玩家交互的实时性。如何在保证动作质量的同时降低模型计算开销，实现实时生成，是系统落地的重要挑战；\n3、动作物理合理性与角色适配挑战：生成的动作不仅需要符合语义，还必须满足角色骨骼结构与游戏引擎物理规则，否则容易产生动作穿模、不稳定或不符合角色比例的问题；\n4、跨角色与跨场景泛化挑战：不同游戏角色具有不同的骨骼结构、体型比例和动作风格，模型需要具备良好的泛化能力，使生成动作能够适配多种角色与不同游戏场景。\n\n具体工作：\n参与游戏智能NPC文生动作算法研发，包括但不限于：文生动作生成模型架构设计，语言与动作语义对齐算法研究，高质量动作数据构建与训练策略优化，实时推理与系统优化，游戏引擎集成与在线实验验证等。","requirements":"1、包含但不限于人工智能/计算机/自动化/数学等专业的博士和优秀硕士；\n2、较强的工程实现能力，熟练掌握PyTorch，精通Diffusion Model / Transformer 等架构，熟悉DeepSpeed/Megatron等分布式训练框架；\n3、熟悉动作生成大模型相关算法，包括但不限于文生动作、手势动作生成、单目视频动捕、in-betweening 动作生成、动作风格迁移等。\n\n加分项：\n1、在 CVPR、ICCV、ECCV、SIGGRAPH 等顶会发表过高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先；\n2、有数字人全栈开发经验，熟悉游戏引擎和DCC等相关软件（UE/Unity、Maya/Blender）。","description":"课题描述\n课题背景：\n随着游戏产业从“内容生产驱动”逐步迈向“智能交互驱动”的新阶段，玩家对虚拟角色的真实感、表现力与互动能力提出了更高要求。当前游戏中的角色动作主要依赖于人工动画制作、动作捕捉或有限的动作库拼接，这种方式制作成本高、扩展性差，且难以根据实时语义需求生成丰富多样的动作表现。近年来，大语言模型与生成式人工智能技术的发展，为“文本到动作生成（Text-to-Motion）”提供了新的技术路径。通过构建融合语言理解与人体运动建模的大规模生成模型，可以实现从自然语言描述到角色动作序列的自动生成，使NPC能够理解语义并以拟人化的肢体行为进行表达。然而，在游戏实时环境中，动作生成不仅需要语义准确，还需要满足实时性、物理合理性和长时动作一致性等工程要求。因此，本课题旨在研发面向游戏智能NPC的文生动作大模型（Text-to-Motion Foundation Model），构建从文本语义理解到角色动作生成的端到端技术体系，使游戏角色能够根据语言语义实时生成自然、流畅且符合角色设定的动作表现，从而显著提升游戏角色的表现力与交互体验。\n\n课题挑战：\n1、语言语义与动作表达对齐挑战：自然语言具有高度抽象性，而人体动作是连续的高维时序信号。如何建立语言语义与动作序列之间的有效对齐关系，使模型准确理解动作意图并生成合理的运动，是文生动作模型面临的重要问题；\n2、实时生成与系统延迟挑战：游戏NPC动作生成通常需要在极低延迟下完成，以保证玩家交互的实时性。如何在保证动作质量的同时降低模型计算开销，实现实时生成，是系统落地的重要挑战；\n3、动作物理合理性与角色适配挑战：生成的动作不仅需要符合语义，还必须满足角色骨骼结构与游戏引擎物理规则，否则容易产生动作穿模、不稳定或不符合角色比例的问题；\n4、跨角色与跨场景泛化挑战：不同游戏角色具有不同的骨骼结构、体型比例和动作风格，模型需要具备良好的泛化能力，使生成动作能够适配多种角色与不同游戏场景。\n\n具体工作：\n参与游戏智能NPC文生动作算法研发，包括但不限于：文生动作生成模型架构设计，语言与动作语义对齐算法研究，高质量动作数据构建与训练策略优化，实时推理与系统优化，游戏引擎集成与在线实验验证等。\n\n课题要求\n1、包含但不限于人工智能/计算机/自动化/数学等专业的博士和优秀硕士；\n2、较强的工程实现能力，熟练掌握PyTorch，精通Diffusion Model / Transformer 等架构，熟悉DeepSpeed/Megatron等分布式训练框架；\n3、熟悉动作生成大模型相关算法，包括但不限于文生动作、手势动作生成、单目视频动捕、in-betweening 动作生成、动作风格迁移等。\n\n加分项：\n1、在 CVPR、ICCV、ECCV、SIGGRAPH 等顶会发表过高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先；\n2、有数字人全栈开发经验，熟悉游戏引擎和DCC等相关软件（UE/Unity、Maya/Blender）。\n\nIEG\n互动娱乐事业群\n\n生态发展部\n生态发展部致力于在AI时代打造游戏设计制作的全新范式。我们汇聚全链路顶尖专家，将前沿创意与实战经验沉淀为可复用的平台化解决方案，我们将AI Agent与全新的轻度游戏设计理念结合，再辅助于免费资产库、海量预制逻辑模块与强大的AIGC能力，旨在让开发者无需代码即可高效实现创意，推动“人人皆可创作”的愿景。\n\n在这里，你将有机会深度参与一线项目攻坚，直接助力产品成功；同时也能投身于面向未来的前瞻探索，通过「代号Craft」共同定义下一代游戏开发标准，推动AI进化为“智能创作伙伴”。我们致力于通过体系化、平台化的能力建设，让好创意加速落地，提升项目成功率。\n\n如果你怀揣创业心态，拥有硬核实力，并渴望将不凡的野心付诸实践，欢迎加入。在这里，你不仅是参与项目，更是亲手打造能赋能整个行业的核心平台，共同构建下一代游戏研发生态，一起把不可能变为行业标杆。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139161","sourceKey":"tencent","company":"腾讯","title":"游戏垂类多模态理解LLM","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139161","duty":"1、构建系统化的游戏垂类知识理解能力：建立针对游戏垂直领域的专业知识体系建模能力，使模型能够深入理解不同游戏品类（包括但不限于休闲游戏、FPS、RPG、MOBA等）的核心机制、玩法结构、叙事范式与经典桥段，实现对游戏内容的语义级、结构级与策略级理解；\n2、实现娱乐热点与游戏内容的跨域融合能力：提升模型对泛娱乐行业热点（如影视、动漫、综艺、网络文化等）的实时理解与趋势分析能力，并构建跨域知识映射机制，使模型能够将热点内容与游戏垂类知识进行语义融合与创意重构，生成具备传播潜力与商业价值的创新内容；\n3、构建面向二次元剧情导演能力：强化模型对二次元叙事表达体系的理解能力，包括运镜语言、角色站位逻辑、互动结构、情绪表达及视觉节奏控制等要素；在此基础上，构建文本—画面—角色关系—叙事节奏之间的结构化表达与生成框架，使模型能够基于创作需求输出逻辑清晰、结构合理、具备视觉可执行性的多模态剧本方案，提升游戏宣发与内容创作场景下的剧本生成效率。","requirements":"1、包含但不限于人工智能/计算机/自动化/数学等专业的博士和优秀硕士；\n2、较强的工程实现能力，熟练掌握PyTorch，精通Diffusion Model / Transformer 等架构，熟悉DeepSpeed/Megatron等分布式训练框架；\n3、熟悉动作生成大模型相关算法，包括但不限于文生动作、手势动作生成、单目视频动捕、in-betweening 动作生成、动作风格迁移等。\n\n加分项：\n1、在 CVPR、ICCV、ECCV、SIGGRAPH 等顶会发表过高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先；\n2、有数字人全栈开发经验，熟悉游戏引擎和DCC等相关软件（UE/Unity、Maya/Blender）。","description":"课题描述\n1、构建系统化的游戏垂类知识理解能力：建立针对游戏垂直领域的专业知识体系建模能力，使模型能够深入理解不同游戏品类（包括但不限于休闲游戏、FPS、RPG、MOBA等）的核心机制、玩法结构、叙事范式与经典桥段，实现对游戏内容的语义级、结构级与策略级理解；\n2、实现娱乐热点与游戏内容的跨域融合能力：提升模型对泛娱乐行业热点（如影视、动漫、综艺、网络文化等）的实时理解与趋势分析能力，并构建跨域知识映射机制，使模型能够将热点内容与游戏垂类知识进行语义融合与创意重构，生成具备传播潜力与商业价值的创新内容；\n3、构建面向二次元剧情导演能力：强化模型对二次元叙事表达体系的理解能力，包括运镜语言、角色站位逻辑、互动结构、情绪表达及视觉节奏控制等要素；在此基础上，构建文本—画面—角色关系—叙事节奏之间的结构化表达与生成框架，使模型能够基于创作需求输出逻辑清晰、结构合理、具备视觉可执行性的多模态剧本方案，提升游戏宣发与内容创作场景下的剧本生成效率。\n\n课题要求\n1、包含但不限于人工智能/计算机/自动化/数学等专业的博士和优秀硕士；\n2、较强的工程实现能力，熟练掌握PyTorch，精通Diffusion Model / Transformer 等架构，熟悉DeepSpeed/Megatron等分布式训练框架；\n3、熟悉动作生成大模型相关算法，包括但不限于文生动作、手势动作生成、单目视频动捕、in-betweening 动作生成、动作风格迁移等。\n\n加分项：\n1、在 CVPR、ICCV、ECCV、SIGGRAPH 等顶会发表过高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先；\n2、有数字人全栈开发经验，熟悉游戏引擎和DCC等相关软件（UE/Unity、Maya/Blender）。\n\nIEG\n互动娱乐事业群\n\nLevel Infinite Tech Team\n我们致力于为腾讯游戏的全球化业务Level Infinite提供全栈全流程的国际化顶尖技术服务。通过打造全球化的数据科学、人工智能、大数据与精准营销等游戏研发运营关键核心技术，我们为Level Infinite旗下AAA级、创新型等全品类游戏的全球市场开拓提供坚实支撑。团队持续投入AI能力的研发与应用，助力智能内容生成、玩家体验优化与运营自动化，推动技术与游戏的深度融合。团队分布在中国、新加坡、日本、美国、荷兰、英国等国家与地区，这里汇聚行业精英，跨区域协作与跨文化的工作氛围将助你拓展国际化视野。\n\n加入我们，一起在全球化的舞台成长，共同探索游戏与科技的未来！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139162","sourceKey":"tencent","company":"腾讯","title":"游戏垂类视频生成模型","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139162","duty":"1、基于动作/运镜资产与特定角色的短剧化快速生成能力：构建标准化动作库与角色行为表达模型，结合具体游戏角色设定与世界观约束，实现结构化短剧内容的快速生成；支持多镜头调度、角色互动逻辑与节奏编排的自动化组合，提升短视频内容在叙事完整性与生产效率上的稳定性；\n2、实现中高品质宣发级视频内容的自动化生成能力：构建面向游戏宣发场景的视频生成质量控制框架，强化画面构图、运镜逻辑、节奏控制与情绪表达能力，使生成内容在视觉表现力、叙事张力与商业转化潜力方面达到中高品质宣发标准，满足不同渠道投放与营销传播需求。","requirements":"1、包含但不限于人工智能/计算机/自动化/数学等专业的博士和优秀硕士；\n2、较强的工程实现能力，熟练掌握PyTorch，精通Diffusion Model / Transformer 等架构，熟悉DeepSpeed/Megatron等分布式训练框架；\n3、熟悉动作生成大模型相关算法，包括但不限于文生动作、手势动作生成、单目视频动捕、in-betweening 动作生成、动作风格迁移等。\n\n加分项：\n1、在 CVPR、ICCV、ECCV、SIGGRAPH 等顶会发表过高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先；\n2、有数字人全栈开发经验，熟悉游戏引擎和DCC等相关软件（UE/Unity、Maya/Blender）。","description":"课题描述\n1、基于动作/运镜资产与特定角色的短剧化快速生成能力：构建标准化动作库与角色行为表达模型，结合具体游戏角色设定与世界观约束，实现结构化短剧内容的快速生成；支持多镜头调度、角色互动逻辑与节奏编排的自动化组合，提升短视频内容在叙事完整性与生产效率上的稳定性；\n2、实现中高品质宣发级视频内容的自动化生成能力：构建面向游戏宣发场景的视频生成质量控制框架，强化画面构图、运镜逻辑、节奏控制与情绪表达能力，使生成内容在视觉表现力、叙事张力与商业转化潜力方面达到中高品质宣发标准，满足不同渠道投放与营销传播需求。\n\n课题要求\n1、包含但不限于人工智能/计算机/自动化/数学等专业的博士和优秀硕士；\n2、较强的工程实现能力，熟练掌握PyTorch，精通Diffusion Model / Transformer 等架构，熟悉DeepSpeed/Megatron等分布式训练框架；\n3、熟悉动作生成大模型相关算法，包括但不限于文生动作、手势动作生成、单目视频动捕、in-betweening 动作生成、动作风格迁移等。\n\n加分项：\n1、在 CVPR、ICCV、ECCV、SIGGRAPH 等顶会发表过高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先；\n2、有数字人全栈开发经验，熟悉游戏引擎和DCC等相关软件（UE/Unity、Maya/Blender）。\n\nIEG\n互动娱乐事业群\n\nLevel Infinite Tech Team\n我们致力于为腾讯游戏的全球化业务Level Infinite提供全栈全流程的国际化顶尖技术服务。通过打造全球化的数据科学、人工智能、大数据与精准营销等游戏研发运营关键核心技术，我们为Level Infinite旗下AAA级、创新型等全品类游戏的全球市场开拓提供坚实支撑。团队持续投入AI能力的研发与应用，助力智能内容生成、玩家体验优化与运营自动化，推动技术与游戏的深度融合。团队分布在中国、新加坡、日本、美国、荷兰、英国等国家与地区，这里汇聚行业精英，跨区域协作与跨文化的工作氛围将助你拓展国际化视野。\n\n加入我们，一起在全球化的舞台成长，共同探索游戏与科技的未来！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139163","sourceKey":"tencent","company":"腾讯","title":"二次元垂类风格化动作生成模型","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139163","duty":"1、构建支持规模化生产的风格化动作生成体系：面向二次元内容创作与游戏宣发场景中对高频、海量动作资产的需求，建立可扩展的风格化动作生成框架，实现从单条定制生成向批量化、半自动化乃至全自动化生产模式的升级；提升动作资产生产效率与风格一致性；\n2、突破通用动作生成模型在垂类场景下的适配瓶颈：针对现有通用动作生成模型在二次元语境中存在的动作失真、物理逻辑不稳定、风格表达弱化以及角色表现力不足等问题，构建面向二次元垂类特征的专用建模机制；强化对夸张形变、节奏张力、表演性姿态与风格化肢体语言的建模能力，实现动作生成在结构合理性与风格表达力上的同步提升；\n3、建立风格控制与质量评估的可控生成机制：构建可调节的风格参数与表现强度控制体系，实现不同二次元子风格（如写实偏日式、夸张演出风、战斗特效强化风等）之间的可控切换；同时建立面向业务需求的动作质量评估标准，保障生成结果在视觉表现、角色一致性与可用性方面满足实际制作要求。","requirements":"1、包含但不限于人工智能/计算机/自动化/数学等专业的博士和优秀硕士；\n2、较强的工程实现能力，熟练掌握PyTorch，精通Diffusion Model / Transformer 等架构，熟悉DeepSpeed/Megatron等分布式训练框架；\n3、熟悉动作生成大模型相关算法，包括但不限于文生动作、手势动作生成、单目视频动捕、in-betweening 动作生成、动作风格迁移等。\n\n加分项：\n1、在 CVPR、ICCV、ECCV、SIGGRAPH 等顶会发表过高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先；\n2、有数字人全栈开发经验，熟悉游戏引擎和DCC等相关软件（UE/Unity、Maya/Blender）。","description":"课题描述\n1、构建支持规模化生产的风格化动作生成体系：面向二次元内容创作与游戏宣发场景中对高频、海量动作资产的需求，建立可扩展的风格化动作生成框架，实现从单条定制生成向批量化、半自动化乃至全自动化生产模式的升级；提升动作资产生产效率与风格一致性；\n2、突破通用动作生成模型在垂类场景下的适配瓶颈：针对现有通用动作生成模型在二次元语境中存在的动作失真、物理逻辑不稳定、风格表达弱化以及角色表现力不足等问题，构建面向二次元垂类特征的专用建模机制；强化对夸张形变、节奏张力、表演性姿态与风格化肢体语言的建模能力，实现动作生成在结构合理性与风格表达力上的同步提升；\n3、建立风格控制与质量评估的可控生成机制：构建可调节的风格参数与表现强度控制体系，实现不同二次元子风格（如写实偏日式、夸张演出风、战斗特效强化风等）之间的可控切换；同时建立面向业务需求的动作质量评估标准，保障生成结果在视觉表现、角色一致性与可用性方面满足实际制作要求。\n\n课题要求\n1、包含但不限于人工智能/计算机/自动化/数学等专业的博士和优秀硕士；\n2、较强的工程实现能力，熟练掌握PyTorch，精通Diffusion Model / Transformer 等架构，熟悉DeepSpeed/Megatron等分布式训练框架；\n3、熟悉动作生成大模型相关算法，包括但不限于文生动作、手势动作生成、单目视频动捕、in-betweening 动作生成、动作风格迁移等。\n\n加分项：\n1、在 CVPR、ICCV、ECCV、SIGGRAPH 等顶会发表过高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先；\n2、有数字人全栈开发经验，熟悉游戏引擎和DCC等相关软件（UE/Unity、Maya/Blender）。\n\nIEG\n互动娱乐事业群\n\nLevel Infinite Tech Team\n我们致力于为腾讯游戏的全球化业务Level Infinite提供全栈全流程的国际化顶尖技术服务。通过打造全球化的数据科学、人工智能、大数据与精准营销等游戏研发运营关键核心技术，我们为Level Infinite旗下AAA级、创新型等全品类游戏的全球市场开拓提供坚实支撑。团队持续投入AI能力的研发与应用，助力智能内容生成、玩家体验优化与运营自动化，推动技术与游戏的深度融合。团队分布在中国、新加坡、日本、美国、荷兰、英国等国家与地区，这里汇聚行业精英，跨区域协作与跨文化的工作氛围将助你拓展国际化视野。\n\n加入我们，一起在全球化的舞台成长，共同探索游戏与科技的未来！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139164","sourceKey":"tencent","company":"腾讯","title":"基于端到端语音大模型的游戏场景实时跨语言通信系统研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139164","duty":"随着游戏产业的全球化进程加速，“全球同服”（一个服务器容纳全球玩家）已成为大型多人在线游戏的主流运营模式。然而，语言屏障严重破坏了游戏的核心社交与合作体验，成为制约全球同服生态发展的关键瓶颈。\n\n现有的解决方案（如内置文本翻译、第三方语音转译插件）存在显著缺陷：流程割裂、延迟高、丢失情感信息、无法处理游戏术语。玩家需在游戏、翻译软件、语音聊天工具间频繁切换，体验碎片化。\n\n本课题旨在研发一款专门为游戏场景优化的端到端语音大模型，实现实时、准确、高保真的跨语言语音同传，让全球玩家能够像使用母语一样，通过语音进行无缝交流与协作，从根本上提升全球同服游戏的可玩性与社交深度。","requirements":"1、包含但不限于计算机科学、人工智能、模式识别、电子信息、通信工程、声学、自动化等相关专业的博士或优秀硕士；\n2、熟悉语音合成（TTS）或语音信号处理相关算法，了解Transformer、扩散模型、Flow Matching、语音编解码等技术；熟练使用PyTorch等深度学习框架，掌握Python编程语言；\n3、对语音合成和情感表达方向有浓厚研究兴趣，具备较强的文献阅读与问题分析能力，沟通协作意识好，自驱力强，能积极主动推动研究进展。","description":"课题描述\n随着游戏产业的全球化进程加速，“全球同服”（一个服务器容纳全球玩家）已成为大型多人在线游戏的主流运营模式。然而，语言屏障严重破坏了游戏的核心社交与合作体验，成为制约全球同服生态发展的关键瓶颈。\n\n现有的解决方案（如内置文本翻译、第三方语音转译插件）存在显著缺陷：流程割裂、延迟高、丢失情感信息、无法处理游戏术语。玩家需在游戏、翻译软件、语音聊天工具间频繁切换，体验碎片化。\n\n本课题旨在研发一款专门为游戏场景优化的端到端语音大模型，实现实时、准确、高保真的跨语言语音同传，让全球玩家能够像使用母语一样，通过语音进行无缝交流与协作，从根本上提升全球同服游戏的可玩性与社交深度。\n\n课题要求\n1、包含但不限于计算机科学、人工智能、模式识别、电子信息、通信工程、声学、自动化等相关专业的博士或优秀硕士；\n2、熟悉语音合成（TTS）或语音信号处理相关算法，了解Transformer、扩散模型、Flow Matching、语音编解码等技术；熟练使用PyTorch等深度学习框架，掌握Python编程语言；\n3、对语音合成和情感表达方向有浓厚研究兴趣，具备较强的文献阅读与问题分析能力，沟通协作意识好，自驱力强，能积极主动推动研究进展。\n\nIEG\n互动娱乐事业群\n\nLevel Infinite Tech Team\n我们致力于为腾讯游戏的全球化业务Level Infinite提供全栈全流程的国际化顶尖技术服务。通过打造全球化的数据科学、人工智能、大数据与精准营销等游戏研发运营关键核心技术，我们为Level Infinite旗下AAA级、创新型等全品类游戏的全球市场开拓提供坚实支撑。团队持续投入AI能力的研发与应用，助力智能内容生成、玩家体验优化与运营自动化，推动技术与游戏的深度融合。团队分布在中国、新加坡、日本、美国、荷兰、英国等国家与地区，这里汇聚行业精英，跨区域协作与跨文化的工作氛围将助你拓展国际化视野。\n\n加入我们，一起在全球化的舞台成长，共同探索游戏与科技的未来！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139165","sourceKey":"tencent","company":"腾讯","title":"游戏氛围NPC方法研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139165","duty":"随着游戏工业迈入“次世代”，玩家对虚拟世界的期待已从单纯的玩法刺激，升维至深度沉浸与情感共鸣。开放世界、元宇宙及叙事驱动型游戏成为市场主流，其核心挑战在于构建一个“活”的世界，而不仅仅是“大”的地图。\n\n传统的NPC设计大多服务于明确的功能性目标：提供任务（任务NPC）、进行战斗（敌人NPC）或推动主线剧情（关键NPC）。然而，构成世界真实感与氛围的，恰恰是那些“无目的”的居民——街头的路人、酒馆的食客、巡逻的卫兵、忙碌的工匠。他们曾是世界的“背景板”，行为呆板、对话循环、与玩家及环境缺乏有机互动，极易让玩家产生“楚门的世界”般的疏离感，打破沉浸感。\n\n因此，将氛围NPC​ 从“背景装饰”提升为“生态基石”，使其具备自主性、反应性和叙事潜力，已成为下一代游戏开发的关键前沿课题。","requirements":"1、深入理解大语言模型的底层原理，熟悉推理、指令遵循、对齐等能力；有SFT/偏好对齐/推理增强经验者优先；\n2、熟悉主流Agent框架/范式；\n3、精通 Prompt Engineering、RAG、Function Calling、向量数据库；\n4、熟悉记忆系统设计与对话状态管理；\n5、熟练掌握强化学习与思维链等方法，能根据任务需求进行模型适配与评测；\n6、优秀的Python能力，扎实的数据结构与算法；熟悉 PyTorch/DeepSpeed 等训练或推理框架；具备线上系统稳定性意识；\n7、逻辑分析能力强，能将模糊需求拆解为可执行的算法步骤；具备良好的沟通协作与自驱力。","description":"课题描述\n随着游戏工业迈入“次世代”，玩家对虚拟世界的期待已从单纯的玩法刺激，升维至深度沉浸与情感共鸣。开放世界、元宇宙及叙事驱动型游戏成为市场主流，其核心挑战在于构建一个“活”的世界，而不仅仅是“大”的地图。\n\n传统的NPC设计大多服务于明确的功能性目标：提供任务（任务NPC）、进行战斗（敌人NPC）或推动主线剧情（关键NPC）。然而，构成世界真实感与氛围的，恰恰是那些“无目的”的居民——街头的路人、酒馆的食客、巡逻的卫兵、忙碌的工匠。他们曾是世界的“背景板”，行为呆板、对话循环、与玩家及环境缺乏有机互动，极易让玩家产生“楚门的世界”般的疏离感，打破沉浸感。\n\n因此，将氛围NPC​ 从“背景装饰”提升为“生态基石”，使其具备自主性、反应性和叙事潜力，已成为下一代游戏开发的关键前沿课题。\n\n课题要求\n1、深入理解大语言模型的底层原理，熟悉推理、指令遵循、对齐等能力；有SFT/偏好对齐/推理增强经验者优先；\n2、熟悉主流Agent框架/范式；\n3、精通 Prompt Engineering、RAG、Function Calling、向量数据库；\n4、熟悉记忆系统设计与对话状态管理；\n5、熟练掌握强化学习与思维链等方法，能根据任务需求进行模型适配与评测；\n6、优秀的Python能力，扎实的数据结构与算法；熟悉 PyTorch/DeepSpeed 等训练或推理框架；具备线上系统稳定性意识；\n7、逻辑分析能力强，能将模糊需求拆解为可执行的算法步骤；具备良好的沟通协作与自驱力。\n\nIEG\n互动娱乐事业群\n\nLevel Infinite Tech Team\n我们致力于为腾讯游戏的全球化业务Level Infinite提供全栈全流程的国际化顶尖技术服务。通过打造全球化的数据科学、人工智能、大数据与精准营销等游戏研发运营关键核心技术，我们为Level Infinite旗下AAA级、创新型等全品类游戏的全球市场开拓提供坚实支撑。团队持续投入AI能力的研发与应用，助力智能内容生成、玩家体验优化与运营自动化，推动技术与游戏的深度融合。团队分布在中国、新加坡、日本、美国、荷兰、英国等国家与地区，这里汇聚行业精英，跨区域协作与跨文化的工作氛围将助你拓展国际化视野。\n\n加入我们，一起在全球化的舞台成长，共同探索游戏与科技的未来！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139166","sourceKey":"tencent","company":"腾讯","title":"游戏玩法与测试用智能bot","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139166","duty":"使用强化学习技术及其他技术为游戏构建 AI Bot。\n支持可扩展、高性能的 AI Bot 服务（AI Service）的生产与优化。\n运行实验以测试已部署模型的性能，并在过程中定位和解决出现的各类问题。\n研究并探索新的方法（如结合agent能力），以持续提升模型与系统的整体性能。","requirements":"1、包含但不限于人工智能/计算机/数据科学/统计学等专业的博士和优秀硕士；\n2、有强化学习研究经历者，有Unreal Engine 5经历者，有智能Agent经历者，熟悉游戏行业者优先；\n3、在KDD、ICML、NeurIPS、AAAI、ICLR等顶会/顶刊发表高质量论文为加分项。","description":"课题描述\n使用强化学习技术及其他技术为游戏构建 AI Bot。\n支持可扩展、高性能的 AI Bot 服务（AI Service）的生产与优化。\n运行实验以测试已部署模型的性能，并在过程中定位和解决出现的各类问题。\n研究并探索新的方法（如结合agent能力），以持续提升模型与系统的整体性能。\n\n课题要求\n1、包含但不限于人工智能/计算机/数据科学/统计学等专业的博士和优秀硕士；\n2、有强化学习研究经历者，有Unreal Engine 5经历者，有智能Agent经历者，熟悉游戏行业者优先；\n3、在KDD、ICML、NeurIPS、AAAI、ICLR等顶会/顶刊发表高质量论文为加分项。\n\nIEG\n互动娱乐事业群\n\nLevel Infinite Tech Team\n我们致力于为腾讯游戏的全球化业务Level Infinite提供全栈全流程的国际化顶尖技术服务。通过打造全球化的数据科学、人工智能、大数据与精准营销等游戏研发运营关键核心技术，我们为Level Infinite旗下AAA级、创新型等全品类游戏的全球市场开拓提供坚实支撑。团队持续投入AI能力的研发与应用，助力智能内容生成、玩家体验优化与运营自动化，推动技术与游戏的深度融合。团队分布在中国、新加坡、日本、美国、荷兰、英国等国家与地区，这里汇聚行业精英，跨区域协作与跨文化的工作氛围将助你拓展国际化视野。\n\n加入我们，一起在全球化的舞台成长，共同探索游戏与科技的未来！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139167","sourceKey":"tencent","company":"腾讯","title":"游戏智能化决策支持研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139167","duty":"1、为全球游戏业务建立数据科学框架，评估各地区产品功能、核心玩法及运营活动的表现，提供可操作的深度洞察；\n2、运用机器学习与统计建模，为全球产品迭代与本地化体验优化提供模型驱动的支持与策略建议；\n3、基于全球市场趋势及多区域用户反馈，开展行业分析与精细化用户研究，为全球增长战略提供依据并推动策略优化；\n4、构建可扩展的数据处理与建模流程，高效整合；\n5、与国际产品、工程及市场团队协作，将复杂的全球业务挑战转化为数据科学解决方案，推动全球运营的数据驱动决策。","requirements":"1、包含但不限于人工智能/计算机/软件工程/数据科学等专业的博士和优秀硕士；\n2、较强的工程实现与算法落地能力，具有数据敏感性和扎实的数据科学基础，熟练掌握Python及主流深度学习框架；\n3、扎实的自然语言处理与数据库基础，熟悉Text-to-SQL、信息抽取、知识图谱构建与推理等相关技术，对特征工程、AutoML有深入理解。\n\n加分项：\n1、在ACL、EMNLP、SIGMOD、VLDB、KDD、ICLR、NeurIPS等顶会/顶刊发表过相关高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先；\n2、有游戏行业数据分析、数据仓库建设或游戏业务系统开发经验者优先。\n3、对游戏有浓厚兴趣，熟悉至少一种主流游戏类型（如RPG、SLG、MOBA等）的核心玩法与系统者优先。","description":"课题描述\n1、为全球游戏业务建立数据科学框架，评估各地区产品功能、核心玩法及运营活动的表现，提供可操作的深度洞察；\n2、运用机器学习与统计建模，为全球产品迭代与本地化体验优化提供模型驱动的支持与策略建议；\n3、基于全球市场趋势及多区域用户反馈，开展行业分析与精细化用户研究，为全球增长战略提供依据并推动策略优化；\n4、构建可扩展的数据处理与建模流程，高效整合；\n5、与国际产品、工程及市场团队协作，将复杂的全球业务挑战转化为数据科学解决方案，推动全球运营的数据驱动决策。\n\n课题要求\n1、包含但不限于人工智能/计算机/软件工程/数据科学等专业的博士和优秀硕士；\n2、较强的工程实现与算法落地能力，具有数据敏感性和扎实的数据科学基础，熟练掌握Python及主流深度学习框架；\n3、扎实的自然语言处理与数据库基础，熟悉Text-to-SQL、信息抽取、知识图谱构建与推理等相关技术，对特征工程、AutoML有深入理解。\n\n加分项：\n1、在ACL、EMNLP、SIGMOD、VLDB、KDD、ICLR、NeurIPS等顶会/顶刊发表过相关高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先；\n2、有游戏行业数据分析、数据仓库建设或游戏业务系统开发经验者优先。\n3、对游戏有浓厚兴趣，熟悉至少一种主流游戏类型（如RPG、SLG、MOBA等）的核心玩法与系统者优先。\n\nIEG\n互动娱乐事业群\n\nLevel Infinite Tech Team\n我们致力于为腾讯游戏的全球化业务Level Infinite提供全栈全流程的国际化顶尖技术服务。通过打造全球化的数据科学、人工智能、大数据与精准营销等游戏研发运营关键核心技术，我们为Level Infinite旗下AAA级、创新型等全品类游戏的全球市场开拓提供坚实支撑。团队持续投入AI能力的研发与应用，助力智能内容生成、玩家体验优化与运营自动化，推动技术与游戏的深度融合。团队分布在中国、新加坡、日本、美国、荷兰、英国等国家与地区，这里汇聚行业精英，跨区域协作与跨文化的工作氛围将助你拓展国际化视野。\n\n加入我们，一起在全球化的舞台成长，共同探索游戏与科技的未来！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139168","sourceKey":"tencent","company":"腾讯","title":"游戏市场运营智能模型研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139168","duty":"1、为游戏市场建立科学评估和归因框架，评估各地区产品市场表现，建立科学的指标和评估体系；\n2、构建可扩展的数据处理与建模流程，高效整合并分析来自全球市场的高维度、大规模玩家数据；\n3、基于全球市场趋势和海量行业分析，进行精细化用户研究，为产品市场推广策略提供数据支持并持续迭代优化；\n4、与战略、品牌、网红、增长等团队协作，将复杂的增长目标和市场策略建模为可量化、可追踪的数据体系，为市场战略、品牌投放、网红合作等业务建设模型和算法。","requirements":"1、包含但不限于人工智能/计算机/软件工程/数据科学等专业的博士和优秀硕士；\n2、较强的工程实现与算法落地能力，具有数据敏感性和扎实的数据科学基础，熟练掌握Python及主流深度学习框架；\n3、扎实的自然语言处理与数据库基础，熟悉Text-to-SQL、信息抽取、知识图谱构建与推理等相关技术，对特征工程、AutoML有深入理解。\n\n加分项：\n1、在ACL、EMNLP、SIGMOD、VLDB、KDD、ICLR、NeurIPS等顶会/顶刊发表过相关高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先；\n2、有游戏行业数据分析、数据仓库建设或游戏业务系统开发经验者优先。\n3、对游戏有浓厚兴趣，熟悉至少一种主流游戏类型（如RPG、SLG、MOBA等）的核心玩法与系统者优先。","description":"课题描述\n1、为游戏市场建立科学评估和归因框架，评估各地区产品市场表现，建立科学的指标和评估体系；\n2、构建可扩展的数据处理与建模流程，高效整合并分析来自全球市场的高维度、大规模玩家数据；\n3、基于全球市场趋势和海量行业分析，进行精细化用户研究，为产品市场推广策略提供数据支持并持续迭代优化；\n4、与战略、品牌、网红、增长等团队协作，将复杂的增长目标和市场策略建模为可量化、可追踪的数据体系，为市场战略、品牌投放、网红合作等业务建设模型和算法。\n\n课题要求\n1、包含但不限于人工智能/计算机/软件工程/数据科学等专业的博士和优秀硕士；\n2、较强的工程实现与算法落地能力，具有数据敏感性和扎实的数据科学基础，熟练掌握Python及主流深度学习框架；\n3、扎实的自然语言处理与数据库基础，熟悉Text-to-SQL、信息抽取、知识图谱构建与推理等相关技术，对特征工程、AutoML有深入理解。\n\n加分项：\n1、在ACL、EMNLP、SIGMOD、VLDB、KDD、ICLR、NeurIPS等顶会/顶刊发表过相关高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先；\n2、有游戏行业数据分析、数据仓库建设或游戏业务系统开发经验者优先。\n3、对游戏有浓厚兴趣，熟悉至少一种主流游戏类型（如RPG、SLG、MOBA等）的核心玩法与系统者优先。\n\nIEG\n互动娱乐事业群\n\nLevel Infinite Tech Team\n我们致力于为腾讯游戏的全球化业务Level Infinite提供全栈全流程的国际化顶尖技术服务。通过打造全球化的数据科学、人工智能、大数据与精准营销等游戏研发运营关键核心技术，我们为Level Infinite旗下AAA级、创新型等全品类游戏的全球市场开拓提供坚实支撑。团队持续投入AI能力的研发与应用，助力智能内容生成、玩家体验优化与运营自动化，推动技术与游戏的深度融合。团队分布在中国、新加坡、日本、美国、荷兰、英国等国家与地区，这里汇聚行业精英，跨区域协作与跨文化的工作氛围将助你拓展国际化视野。\n\n加入我们，一起在全球化的舞台成长，共同探索游戏与科技的未来！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139169","sourceKey":"tencent","company":"腾讯","title":"游戏数据语义知识库与智能查询技术研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139169","duty":"课题背景：\n游戏行业数据体量庞大、指标关系复杂，业务同学的数据需求高频且多样。当前，非技术同学高度依赖数据研发进行取数，沟通与开发成本高昂，严重制约了快速迭代与决策效率。本课题旨在构建游戏领域的语义知识库与智能查询技术，实现“所想即所得”的数据获取体验，并自动化挖掘深层数据特征，为智能运营打下坚实基础。\n\n课题方向：\n1、构建游戏领域语义知识库：针对游戏业务数据（如用户行为、经济系统、战斗平衡等），研究如何系统性地构建领域本体与知识图谱。将离散的游戏特征、指标、实体及其复杂业务关系进行结构化建模，形成机器可理解和推理的领域语义知识库；\n2、实现自然语言到结构化查询（Text-to-SQL）：基于构建的游戏语义知识库，研发高性能的Text-to-SQL模型。使非技术背景的策划、运营同学能够通过自然语言直接、准确、高效地查询底层数据，降低数据获取门槛，提升决策效率；\n3、研究自动化特征工程方法：探索基于知识库引导的自动化特征发现与组合技术。使系统能够依据特征的业务含义、统计特性及关联关系，自动进行有效的特征交叉、变换与组合，为上层模型挖掘更有价值的输入信号，提升预测与洞察能力。","requirements":"1、包含但不限于人工智能/计算机/软件工程/数据科学等专业的博士和优秀硕士；\n2、较强的工程实现与算法落地能力，具有数据敏感性和扎实的数据科学基础，熟练掌握Python及主流深度学习框架；\n3、扎实的自然语言处理与数据库基础，熟悉Text-to-SQL、信息抽取、知识图谱构建与推理等相关技术，对特征工程、AutoML有深入理解。\n\n加分项：\n1、在ACL、EMNLP、SIGMOD、VLDB、KDD、ICLR、NeurIPS等顶会/顶刊发表过相关高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先；\n2、有游戏行业数据分析、数据仓库建设或游戏业务系统开发经验者优先；\n3、对游戏有浓厚兴趣，熟悉至少一种主流游戏类型（如RPG、SLG、MOBA等）的核心玩法与系统者优先。","description":"课题描述\n课题背景：\n游戏行业数据体量庞大、指标关系复杂，业务同学的数据需求高频且多样。当前，非技术同学高度依赖数据研发进行取数，沟通与开发成本高昂，严重制约了快速迭代与决策效率。本课题旨在构建游戏领域的语义知识库与智能查询技术，实现“所想即所得”的数据获取体验，并自动化挖掘深层数据特征，为智能运营打下坚实基础。\n\n课题方向：\n1、构建游戏领域语义知识库：针对游戏业务数据（如用户行为、经济系统、战斗平衡等），研究如何系统性地构建领域本体与知识图谱。将离散的游戏特征、指标、实体及其复杂业务关系进行结构化建模，形成机器可理解和推理的领域语义知识库；\n2、实现自然语言到结构化查询（Text-to-SQL）：基于构建的游戏语义知识库，研发高性能的Text-to-SQL模型。使非技术背景的策划、运营同学能够通过自然语言直接、准确、高效地查询底层数据，降低数据获取门槛，提升决策效率；\n3、研究自动化特征工程方法：探索基于知识库引导的自动化特征发现与组合技术。使系统能够依据特征的业务含义、统计特性及关联关系，自动进行有效的特征交叉、变换与组合，为上层模型挖掘更有价值的输入信号，提升预测与洞察能力。\n\n课题要求\n1、包含但不限于人工智能/计算机/软件工程/数据科学等专业的博士和优秀硕士；\n2、较强的工程实现与算法落地能力，具有数据敏感性和扎实的数据科学基础，熟练掌握Python及主流深度学习框架；\n3、扎实的自然语言处理与数据库基础，熟悉Text-to-SQL、信息抽取、知识图谱构建与推理等相关技术，对特征工程、AutoML有深入理解。\n\n加分项：\n1、在ACL、EMNLP、SIGMOD、VLDB、KDD、ICLR、NeurIPS等顶会/顶刊发表过相关高质量论文，或在相关开源项目、算法竞赛中获得优异成绩者优先；\n2、有游戏行业数据分析、数据仓库建设或游戏业务系统开发经验者优先；\n3、对游戏有浓厚兴趣，熟悉至少一种主流游戏类型（如RPG、SLG、MOBA等）的核心玩法与系统者优先。\n\nIEG\n互动娱乐事业群\n\nLevel Infinite Tech Team\n我们致力于为腾讯游戏的全球化业务Level Infinite提供全栈全流程的国际化顶尖技术服务。通过打造全球化的数据科学、人工智能、大数据与精准营销等游戏研发运营关键核心技术，我们为Level Infinite旗下AAA级、创新型等全品类游戏的全球市场开拓提供坚实支撑。团队持续投入AI能力的研发与应用，助力智能内容生成、玩家体验优化与运营自动化，推动技术与游戏的深度融合。团队分布在中国、新加坡、日本、美国、荷兰、英国等国家与地区，这里汇聚行业精英，跨区域协作与跨文化的工作氛围将助你拓展国际化视野。\n\n加入我们，一起在全球化的舞台成长，共同探索游戏与科技的未来！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231829074692139170","sourceKey":"tencent","company":"腾讯","title":"游戏数据智能分析与探索Agent","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231829074692139170","duty":"课题背景：\n面对海量的游戏数据，传统“人工提问-手动分析”的模式已难以应对快速变化的业务场景。分析师常陷入重复性的数据探查与报告撰写中，难以进行更深度的策略思考。本课题旨在研发具备自主探索与验证能力的数据科学智能体Agent，将分析师的经验与逻辑固化为自动化工作流，实现从问题定义到报告产出的端到端智能分析，彻底变革数据消费模式，释放人力以聚焦更高价值的决策。\n\n课题方向：\n1、研发具备自主验证能力的数据科学Agent：研究并开发能够自主进行游戏数据分析的智能体（Agent）。该Agent需具备对分析过程阶段性结果（如数据质量、统计显著性、业务合理性）进行自动化检查与验证的能力，确保分析流程的可靠性；\n2、实现自动化分析路径探索：赋予Agent自动化探索数据分析路径的能力。基于初始分析目标与中间发现，Agent应能自主规划下一步分析动作（如深入钻取、关联分析、假设检验、模型尝试等），形成完整的数据洞察链条；\n3、构建结构化报告自动生成能力：研发自动化报告生成模块，使Agent能够将分析过程、关键发现、可视化图表及最终结论，整合生成结构清晰、可直接用于汇报的完整数据报告或分析摘要，实现从“问题”到“报告”的端到端自动化。","requirements":"1、包含但不限于人工智能/计算机/数据科学/统计学等专业的博士和优秀硕士；\n2、较强的工程实现与算法落地能力，精通数据分析全流程，熟练掌握Python数据分析栈，熟悉LangChain等AI应用框架；\n3、对AI Agent架构、规划与决策理论、以及相关的提示工程、智能体框架有深入理解和实践热情，具备将复杂分析任务拆解为可执行步骤的能力。\n\n加分项：\n1、在KDD、ICML、NeurIPS、AAAI、ICLR等顶会/顶刊发表过智能体、数据分析、自动化机器学习相关高质量论文者优先；\n2、有丰富的游戏数据分析、用户增长、商业化或平衡性调优等项目经验者优先；\n3、有高质量数据分析或Agent相关开源项目贡献者优先。","description":"课题描述\n课题背景：\n面对海量的游戏数据，传统“人工提问-手动分析”的模式已难以应对快速变化的业务场景。分析师常陷入重复性的数据探查与报告撰写中，难以进行更深度的策略思考。本课题旨在研发具备自主探索与验证能力的数据科学智能体Agent，将分析师的经验与逻辑固化为自动化工作流，实现从问题定义到报告产出的端到端智能分析，彻底变革数据消费模式，释放人力以聚焦更高价值的决策。\n\n课题方向：\n1、研发具备自主验证能力的数据科学Agent：研究并开发能够自主进行游戏数据分析的智能体（Agent）。该Agent需具备对分析过程阶段性结果（如数据质量、统计显著性、业务合理性）进行自动化检查与验证的能力，确保分析流程的可靠性；\n2、实现自动化分析路径探索：赋予Agent自动化探索数据分析路径的能力。基于初始分析目标与中间发现，Agent应能自主规划下一步分析动作（如深入钻取、关联分析、假设检验、模型尝试等），形成完整的数据洞察链条；\n3、构建结构化报告自动生成能力：研发自动化报告生成模块，使Agent能够将分析过程、关键发现、可视化图表及最终结论，整合生成结构清晰、可直接用于汇报的完整数据报告或分析摘要，实现从“问题”到“报告”的端到端自动化。\n\n课题要求\n1、包含但不限于人工智能/计算机/数据科学/统计学等专业的博士和优秀硕士；\n2、较强的工程实现与算法落地能力，精通数据分析全流程，熟练掌握Python数据分析栈，熟悉LangChain等AI应用框架；\n3、对AI Agent架构、规划与决策理论、以及相关的提示工程、智能体框架有深入理解和实践热情，具备将复杂分析任务拆解为可执行步骤的能力。\n\n加分项：\n1、在KDD、ICML、NeurIPS、AAAI、ICLR等顶会/顶刊发表过智能体、数据分析、自动化机器学习相关高质量论文者优先；\n2、有丰富的游戏数据分析、用户增长、商业化或平衡性调优等项目经验者优先；\n3、有高质量数据分析或Agent相关开源项目贡献者优先。\n\nIEG\n互动娱乐事业群\n\nLevel Infinite Tech Team\n我们致力于为腾讯游戏的全球化业务Level Infinite提供全栈全流程的国际化顶尖技术服务。通过打造全球化的数据科学、人工智能、大数据与精准营销等游戏研发运营关键核心技术，我们为Level Infinite旗下AAA级、创新型等全品类游戏的全球市场开拓提供坚实支撑。团队持续投入AI能力的研发与应用，助力智能内容生成、玩家体验优化与运营自动化，推动技术与游戏的深度融合。团队分布在中国、新加坡、日本、美国、荷兰、英国等国家与地区，这里汇聚行业精英，跨区域协作与跨文化的工作氛围将助你拓展国际化视野。\n\n加入我们，一起在全球化的舞台成长，共同探索游戏与科技的未来！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231837900296284160","sourceKey":"tencent","company":"腾讯","title":"混元多模态-AI队友面向数字世界的Agentic应用与研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231837900296284160","duty":"课题背景：\n伴随大语言模型技术的飞速发展，人工智能正从被动的内容生成范式演进为具备主动感知、规划及环境交互能力的智能体（Agent）。本课题旨在探索下一代Agentic AI技术，聚焦于游戏等数字虚拟环境，致力于构建支持高效决策与复杂协作的智能体框架。我们的核心愿景是打造能够与用户双向重塑、协同进化的数字认知伙伴。\n\n课题挑战：\n1、轻量化模型的高阶能力涌现：如何在参数规模受限（\u003c70B）的约束下，使模型在游戏场景中具备敏锐的多模态感知、长程规划能力以及富有趣味性的交互对话水平；\n2、自主认知演进与价值对齐：如何赋予智能体在开放动态环境中的终身学习能力，使其通过记忆累积与用户交互持续迭代认知模型，最终实现与用户意图及价值观的深度对齐。\n\n具体工作：\n入选同学将重点参与以下研究：\n1、搭建多模态感知与全链路长期记忆机制；\n2、探索基于经验学习的技能迁移与Agentic RL在线探索算法；\n3、构建复杂场景下的多智能体协作框架，提升智能体在长程规划与即时决策上的综合性能。","requirements":"学历和专业要求：\n来自计算机专业的博士/硕士同学\n\n技术技能要求：\n掌握大模型，智能体，强化学习算法及应用\n\n软性素质要求：\n沟通协作能力强，自驱力强，喜欢游戏者更佳","description":"课题描述\n课题背景：\n伴随大语言模型技术的飞速发展，人工智能正从被动的内容生成范式演进为具备主动感知、规划及环境交互能力的智能体（Agent）。本课题旨在探索下一代Agentic AI技术，聚焦于游戏等数字虚拟环境，致力于构建支持高效决策与复杂协作的智能体框架。我们的核心愿景是打造能够与用户双向重塑、协同进化的数字认知伙伴。\n\n课题挑战：\n1、轻量化模型的高阶能力涌现：如何在参数规模受限（\u003c70B）的约束下，使模型在游戏场景中具备敏锐的多模态感知、长程规划能力以及富有趣味性的交互对话水平；\n2、自主认知演进与价值对齐：如何赋予智能体在开放动态环境中的终身学习能力，使其通过记忆累积与用户交互持续迭代认知模型，最终实现与用户意图及价值观的深度对齐。\n\n具体工作：\n入选同学将重点参与以下研究：\n1、搭建多模态感知与全链路长期记忆机制；\n2、探索基于经验学习的技能迁移与Agentic RL在线探索算法；\n3、构建复杂场景下的多智能体协作框架，提升智能体在长程规划与即时决策上的综合性能。\n\n课题要求\n学历和专业要求：\n来自计算机专业的博士/硕士同学\n\n技术技能要求：\n掌握大模型，智能体，强化学习算法及应用\n\n软性素质要求：\n沟通协作能力强，自驱力强，喜欢游戏者更佳\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nTEG\n技术工程事业群\n\n腾讯AI平台部\n腾讯AI平台部聚焦决策AI和生成式AI两大技术研发方向，致力于探索AI与游戏娱乐行业的深度融合，为游戏研发和运营提供全链路AI解决方案，助力游戏行业发展。在决策AI方面，我们研发出屡获国际大奖的棋牌类 AI“绝艺”，以及攻克了 MOBA、FPS、RTS、3D 开放世界等多类游戏场景的决策智能 AI“绝悟”。在游戏生成式AI方向，我们聚焦于提高工程化效率和拓展游玩内容，自主研发了游戏AI引擎GiiNEX，支持AI NPC的创建、驱动和智能交互等技术，并且能够辅助生成关卡、剧情等游戏体验内容。在学术合作方面，我们与王者荣耀联合打造“开悟”AI开放研究平台，通过赛事、课程、共研项目等推动AI青年人才培养及产业发展。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231998633466259456","sourceKey":"tencent","company":"腾讯","title":"腾讯存储-面向高性能基础服务的软硬协同技术研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231998633466259456","duty":"课题背景：\n在大模型训练/推理场景下，如何优化存储/缓存系统来提升训练效率/推理TTFT非常重要。\n课题挑战：\n高性能存储/缓存为了支持好训/推场景，需要对全链路有深入的理解，来上下游CoDesign提供最佳解决方案，确保在链路的任何一环不能出现短板。\n具体工作：\n深入理解各类存储相关技术以及模型训练/推理方面的最新进展，研发相关基础服务，解决实际的训练/推理的痛点，提升性能，创造实际价值。\n该课题涉及到的存储/计算技术包括但不限于：PyTorch框架/Megatron-LM训练框架、近端存储、对象存储、文件存储、RDMA、CXL、NVMeDirect、用户态文件系统、高性能协程计算框架等。","requirements":"1. 计算机、软件工程、信息工程、人工智能、电子工程、应用数学等相关专业，博士及优秀硕士学历；\n2. 在软件工程领域具备优秀科研能力，有FAST、SOSP、OSDI、ASPLOS、VLDB、EuroSys等国际顶级学术会议或期刊论文发表者优先；\n3. 熟悉分布式存储相关技术，具备存储前沿技术研究如软硬协同、智能存储等方向背景者优先。","description":"课题描述\n课题背景：\n在大模型训练/推理场景下，如何优化存储/缓存系统来提升训练效率/推理TTFT非常重要。\n课题挑战：\n高性能存储/缓存为了支持好训/推场景，需要对全链路有深入的理解，来上下游CoDesign提供最佳解决方案，确保在链路的任何一环不能出现短板。\n具体工作：\n深入理解各类存储相关技术以及模型训练/推理方面的最新进展，研发相关基础服务，解决实际的训练/推理的痛点，提升性能，创造实际价值。\n该课题涉及到的存储/计算技术包括但不限于：PyTorch框架/Megatron-LM训练框架、近端存储、对象存储、文件存储、RDMA、CXL、NVMeDirect、用户态文件系统、高性能协程计算框架等。\n\n课题要求\n1. 计算机、软件工程、信息工程、人工智能、电子工程、应用数学等相关专业，博士及优秀硕士学历；\n2. 在软件工程领域具备优秀科研能力，有FAST、SOSP、OSDI、ASPLOS、VLDB、EuroSys等国际顶级学术会议或期刊论文发表者优先；\n3. 熟悉分布式存储相关技术，具备存储前沿技术研究如软硬协同、智能存储等方向背景者优先。\n\nTEG\n技术工程事业群\n\n云架构平台部\n云架构平台部是腾讯最核心的技术部门之一，为内外部业务提供数据接入下载、存储传输、计算加速等技术服务，是腾讯各业务背后的“技术引擎”。我们研发对象存储、块存储、文件存储、键值存储等产品，支撑海量数据存储，安全高可靠地让信息穿越时光；构建大模型、多模态与智能记忆等新型存储能力，让海量数据更好地服务模型训推与智能应用；通过缓存、智能路由、传输协议、编解码等技术构建全球加速引擎，让直播、点播、云游戏触手可达，助力用户随时随地观看高清视频、沉浸式探索游戏体验、高效处理工作事务；通过分布式网关、高性能转发框架、弹性资源调度系统打造一站式安全加速平台EdgeOne，时刻守护用网安全；基于丰富场景和底层软件积累的优势，自研业界领先的编解码芯片和AI软件栈，打破算力瓶颈；持续深耕公司网关TGW、TencentOS，并和OpenCloudOS社区共建操作系统生态，打造软件之魂。\n我们依托腾讯多元的业务生态与多样需求，为热爱技术的你提供绝佳的探索土壤。加入我们，一起探索广阔，更有前景的未来!","jdComplete":false,"sourceStatus":null},{"id":"tencent:1231998633466259457","sourceKey":"tencent","company":"腾讯","title":"腾讯存储-基于业务特征感知的存储智能优化研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1231998633466259457","duty":"课题背景：\n在海量数据存储场景下，业务访问模式复杂多变，热点数据分布不均导致性能抖动和资源浪费。当前存储系统主要依赖被动响应策略，缺乏对业务特征的主动感知和预判能力，难以在热点发生前进行有效干预，亟需引入智能化手段实现从被动应对到主动优化的转变。\n课题挑战： \n1. 业务特征自动提取与演化追踪：需要从海量多维度线上访问数据中提炼与时间点无关的业务行为规律，并建立特征漂移检测机制以识别业务模式的渐变与突变；\n2. 热点预测的准确性与实时性：需构建兼顾准确率与低延迟的趋势预测模型，同时应对访问模式突变等非平稳场景；\n3. 主动优化策略的安全性：数据打散、预热等主动干预操作本身消耗系统资源并引入搬迁风险，需确保优化动作不会反向加剧负载；\n4. 特征驱动的单机引擎策略适配：不同业务访问特征差异显著，需建立特征到引擎策略参数的自动映射与动态调优机制。\n具体工作：\n1. 业务特征自动建模：从线上多维度访问日志中提取业务行为特征，构建用户级业务画像，并建立特征漂移检测机制以持续追踪业务模式变化；\n2. 热点预测与主动优化：基于业务画像与短期访问趋势，构建热点预测模型，驱动数据打散、资源均衡与数据预热等主动干预，同时通过代价评估与熔断机制保障优化操作的安全性；\n3. 单机引擎策略优化：基于业务长期稳定的访问特征，建立特征到引擎策略参数的自动映射，实现缓存、Compaction等关键策略的动态调优。","requirements":"1. 计算机、软件工程、信息工程、人工智能、电子工程、应用数学等相关专业，博士及优秀硕士学历；\n2. 在软件工程领域具备优秀科研能力，有FAST、SOSP、OSDI、ASPLOS、VLDB、EuroSys等国际顶级学术会议或期刊论文发表者优先；\n3. 熟悉分布式存储相关技术，具备存储前沿技术研究如软硬协同、智能存储等方向背景者优先。","description":"课题描述\n课题背景：\n在海量数据存储场景下，业务访问模式复杂多变，热点数据分布不均导致性能抖动和资源浪费。当前存储系统主要依赖被动响应策略，缺乏对业务特征的主动感知和预判能力，难以在热点发生前进行有效干预，亟需引入智能化手段实现从被动应对到主动优化的转变。\n课题挑战： \n1. 业务特征自动提取与演化追踪：需要从海量多维度线上访问数据中提炼与时间点无关的业务行为规律，并建立特征漂移检测机制以识别业务模式的渐变与突变；\n2. 热点预测的准确性与实时性：需构建兼顾准确率与低延迟的趋势预测模型，同时应对访问模式突变等非平稳场景；\n3. 主动优化策略的安全性：数据打散、预热等主动干预操作本身消耗系统资源并引入搬迁风险，需确保优化动作不会反向加剧负载；\n4. 特征驱动的单机引擎策略适配：不同业务访问特征差异显著，需建立特征到引擎策略参数的自动映射与动态调优机制。\n具体工作：\n1. 业务特征自动建模：从线上多维度访问日志中提取业务行为特征，构建用户级业务画像，并建立特征漂移检测机制以持续追踪业务模式变化；\n2. 热点预测与主动优化：基于业务画像与短期访问趋势，构建热点预测模型，驱动数据打散、资源均衡与数据预热等主动干预，同时通过代价评估与熔断机制保障优化操作的安全性；\n3. 单机引擎策略优化：基于业务长期稳定的访问特征，建立特征到引擎策略参数的自动映射，实现缓存、Compaction等关键策略的动态调优。\n\n课题要求\n1. 计算机、软件工程、信息工程、人工智能、电子工程、应用数学等相关专业，博士及优秀硕士学历；\n2. 在软件工程领域具备优秀科研能力，有FAST、SOSP、OSDI、ASPLOS、VLDB、EuroSys等国际顶级学术会议或期刊论文发表者优先；\n3. 熟悉分布式存储相关技术，具备存储前沿技术研究如软硬协同、智能存储等方向背景者优先。\n\nTEG\n技术工程事业群\n\n云架构平台部\n云架构平台部是腾讯最核心的技术部门之一，为内外部业务提供数据接入下载、存储传输、计算加速等技术服务，是腾讯各业务背后的“技术引擎”。我们研发对象存储、块存储、文件存储、键值存储等产品，支撑海量数据存储，安全高可靠地让信息穿越时光；构建大模型、多模态与智能记忆等新型存储能力，让海量数据更好地服务模型训推与智能应用；通过缓存、智能路由、传输协议、编解码等技术构建全球加速引擎，让直播、点播、云游戏触手可达，助力用户随时随地观看高清视频、沉浸式探索游戏体验、高效处理工作事务；通过分布式网关、高性能转发框架、弹性资源调度系统打造一站式安全加速平台EdgeOne，时刻守护用网安全；基于丰富场景和底层软件积累的优势，自研业界领先的编解码芯片和AI软件栈，打破算力瓶颈；持续深耕公司网关TGW、TencentOS，并和OpenCloudOS社区共建操作系统生态，打造软件之魂。\n我们依托腾讯多元的业务生态与多样需求，为热爱技术的你提供绝佳的探索土壤。加入我们，一起探索广阔，更有前景的未来!","jdComplete":false,"sourceStatus":null},{"id":"tencent:1233535296004810752","sourceKey":"tencent","company":"腾讯","title":"元宝—多模态模型安全边界的可解释性研究与Agent应用探索","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1233535296004810752","duty":"课题背景：\n大模型在国旗绘制、地图生成、地理边界表达等高精度场景中，常因能力不足产生错误输出，引发安全风险。当前主要以直接拒答应对，但\"一刀切\"策略导致用户无法区分是安全限制还是能力不足，降低了系统可理解性与信任度。随着模型向多模态Agent演进，Agent需进行多步规划与工具调用，若无法清晰解释失败原因与能力边界，将进一步影响可控性与用户体验。本课题研究各类场景可复用的安全边界可解释机制，在保障安全的同时提升交互可信度。\n\n课题挑战：\n1、能力边界与安全策略难以区分：如何判别\"因安全策略拒绝\"与\"因能力不足无法完成\"，避免处置策略混淆。模型失败可能源于数据缺失、Prompt理解偏差、生成不稳定或工具链路不可靠等多种因素，需建立系统化的归因框架；\n2、解释机制设计：敏感场景中完全拒答影响可用性，直接放开又存在风险，需找到合理平衡点。生成清晰、准确且易理解的反馈，既要有足够信息量，又不能过于复杂；\n3、从基座到Agent的迁移：文生图\"生成失败\"与Agent\"执行失败\"形式不同，需验证边界判别与解释机制在多步任务中的有效性。\n\n具体工作：\n1、场景挖掘与测试集建设：基于文生图Badcase，梳理国旗、地图等典型风险场景，构建能力边界测试集与分类体系；\n2、风险归因分析：判断Badcase来源（数据缺失/Prompt偏差/生成不足/策略误判），建立\"能力不足\"与\"违规内容\"的判别依据；\n3、基座模型能力优化：针对高频边界场景，通过SFT/LoRA等轻量方法提升生成稳定性，从源头减少风险输出与不必要拒答；\n4、可解释拒答机制：设计区分\"安全限制\"与\"能力限制\"的判别模块，替代统一拒答，提供透明的限制原因说明；\n5、Agent场景迁移：将\"边界识别—解释反馈—替代引导\"机制迁移至Agent的任务执行失败、工具调用受限等场景。","requirements":"1、包括但不限于计算机科学与技术、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等相关方向的优秀博士/硕士同学；\n2、熟练掌握计算机视觉、图像处理相关基础算法与应用，了解深度学习基本原理；熟悉 Transformer 架构，了解文生图模型（如 Diffusion）或多模态模型的基本原理与常见方法；\n3、熟悉 Caffe、TensorFlow、PyTorch 等至少一种深度学习框架；具备较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell、Python、Matlab 中至少一种编程语言；\n4、具备一定的数据分析能力，能够从模型 Badcase 中挖掘规律、定位问题，并辅助完成能力边界分析、风险归因与效果评估；\n5、对大模型安全、对齐（Alignment）、多模态理解生成、人机交互（HCI）等方向有较强兴趣，具备良好的问题抽象与研究探索能力；\n6、加分项：了解 Agent 框架或相关应用实践经验者优先，例如 LangChain、AutoGPT 等；有多模态大模型、安全对齐、生成模型优化或相关项目经验者优先。","description":"课题描述\n课题背景：\n大模型在国旗绘制、地图生成、地理边界表达等高精度场景中，常因能力不足产生错误输出，引发安全风险。当前主要以直接拒答应对，但\"一刀切\"策略导致用户无法区分是安全限制还是能力不足，降低了系统可理解性与信任度。随着模型向多模态Agent演进，Agent需进行多步规划与工具调用，若无法清晰解释失败原因与能力边界，将进一步影响可控性与用户体验。本课题研究各类场景可复用的安全边界可解释机制，在保障安全的同时提升交互可信度。\n\n课题挑战：\n1、能力边界与安全策略难以区分：如何判别\"因安全策略拒绝\"与\"因能力不足无法完成\"，避免处置策略混淆。模型失败可能源于数据缺失、Prompt理解偏差、生成不稳定或工具链路不可靠等多种因素，需建立系统化的归因框架；\n2、解释机制设计：敏感场景中完全拒答影响可用性，直接放开又存在风险，需找到合理平衡点。生成清晰、准确且易理解的反馈，既要有足够信息量，又不能过于复杂；\n3、从基座到Agent的迁移：文生图\"生成失败\"与Agent\"执行失败\"形式不同，需验证边界判别与解释机制在多步任务中的有效性。\n\n具体工作：\n1、场景挖掘与测试集建设：基于文生图Badcase，梳理国旗、地图等典型风险场景，构建能力边界测试集与分类体系；\n2、风险归因分析：判断Badcase来源（数据缺失/Prompt偏差/生成不足/策略误判），建立\"能力不足\"与\"违规内容\"的判别依据；\n3、基座模型能力优化：针对高频边界场景，通过SFT/LoRA等轻量方法提升生成稳定性，从源头减少风险输出与不必要拒答；\n4、可解释拒答机制：设计区分\"安全限制\"与\"能力限制\"的判别模块，替代统一拒答，提供透明的限制原因说明；\n5、Agent场景迁移：将\"边界识别—解释反馈—替代引导\"机制迁移至Agent的任务执行失败、工具调用受限等场景。\n\n课题要求\n1、包括但不限于计算机科学与技术、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等相关方向的优秀博士/硕士同学；\n2、熟练掌握计算机视觉、图像处理相关基础算法与应用，了解深度学习基本原理；熟悉 Transformer 架构，了解文生图模型（如 Diffusion）或多模态模型的基本原理与常见方法；\n3、熟悉 Caffe、TensorFlow、PyTorch 等至少一种深度学习框架；具备较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell、Python、Matlab 中至少一种编程语言；\n4、具备一定的数据分析能力，能够从模型 Badcase 中挖掘规律、定位问题，并辅助完成能力边界分析、风险归因与效果评估；\n5、对大模型安全、对齐（Alignment）、多模态理解生成、人机交互（HCI）等方向有较强兴趣，具备良好的问题抽象与研究探索能力；\n6、加分项：了解 Agent 框架或相关应用实践经验者优先，例如 LangChain、AutoGPT 等；有多模态大模型、安全对齐、生成模型优化或相关项目经验者优先。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1235017891590830080","sourceKey":"tencent","company":"腾讯","title":"混元-多模态理解与生成模型压缩算法(蒸馏、量化、投机采样、稀疏化)研究","city":"北京/上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1235017891590830080","duty":"课题背景\n研发面向多模态理解(VLM)、图像生成、视频生成、语言理解和生成、3D大模型的通用压缩加速算法，通过量化、稀疏化、投机解码、步数蒸馏、流式生成、Sparse-Attn/KV-Cache压缩、Token/模型剪枝、动态分辨率等算法创新，在保持模型效果无损的前提下，配合推理框架团队完成加速部署落地，持续降低多模态大模型在音频、3D、图像、视频的理解和生成、视觉多轮交互等任务的部署成本。\n\n课题挑战\n1.多模态理解与生成量化稀疏化：探索自回归、Diffusion、ViT、VAE等架构更低bit量化/稀疏化算法（含通信量化），针对3D、音频、图像、视频等多种模态数据及模型特性，设计量化/稀疏算法，并推进推理框架适配落地；\n2.多模态生成蒸馏：针对3D、音频、图像、视频生成模型，设计步数蒸馏、流式生成蒸馏算法等技术，降低端到端生成延迟，实现实时交互体验\n3.多模态长序列性能优化：针对长视频理解与生成、实时语音交互等长上下文场景，研究视觉/音频理解Token剪枝及投机采样、图像视频动态分辨率生成、DiT/自回归模型的稀疏注意力、KV-Cache压缩等SOTA算法。解决多模态Token序列过长导致的显存爆炸和计算瓶颈问题。\n\n具体工作\n通过量化、投机解码、步数蒸馏、流式生成、Sparse-Attn/KV-Cache压缩、Token/模型剪枝、稀疏化等模型压缩方法，保证多种模态的理解和生成效果的同时，大幅降低模型耗时、提升吞吐，提升用户体验优化推理成本","requirements":"1. 包含但不限于计算机科学、人工智能、电子工程、自动化等相关专业。具备扎实的机器学习/深度学习基础；\n2.精通Python编程，熟练掌握PyTorch等深度学习框架。对Transformer、Diffusion等模型架构、计算瓶颈与优化方法论有深刻理解；具备以下至少一个领域经验：图像视频生成、音频理解生成、图像视频编辑/理解、模型压缩（步数蒸馏，轻量化模型，投机解码、KVCache优化、稀疏剪枝等）、生成对齐算法（DPO\\RLHF等）。\n3.满足上述课题方向中任意一个即可","description":"课题描述\n课题背景\n研发面向多模态理解(VLM)、图像生成、视频生成、语言理解和生成、3D大模型的通用压缩加速算法，通过量化、稀疏化、投机解码、步数蒸馏、流式生成、Sparse-Attn/KV-Cache压缩、Token/模型剪枝、动态分辨率等算法创新，在保持模型效果无损的前提下，配合推理框架团队完成加速部署落地，持续降低多模态大模型在音频、3D、图像、视频的理解和生成、视觉多轮交互等任务的部署成本。\n\n课题挑战\n1.多模态理解与生成量化稀疏化：探索自回归、Diffusion、ViT、VAE等架构更低bit量化/稀疏化算法（含通信量化），针对3D、音频、图像、视频等多种模态数据及模型特性，设计量化/稀疏算法，并推进推理框架适配落地；\n2.多模态生成蒸馏：针对3D、音频、图像、视频生成模型，设计步数蒸馏、流式生成蒸馏算法等技术，降低端到端生成延迟，实现实时交互体验\n3.多模态长序列性能优化：针对长视频理解与生成、实时语音交互等长上下文场景，研究视觉/音频理解Token剪枝及投机采样、图像视频动态分辨率生成、DiT/自回归模型的稀疏注意力、KV-Cache压缩等SOTA算法。解决多模态Token序列过长导致的显存爆炸和计算瓶颈问题。\n\n具体工作\n通过量化、投机解码、步数蒸馏、流式生成、Sparse-Attn/KV-Cache压缩、Token/模型剪枝、稀疏化等模型压缩方法，保证多种模态的理解和生成效果的同时，大幅降低模型耗时、提升吞吐，提升用户体验优化推理成本\n\n课题要求\n1. 包含但不限于计算机科学、人工智能、电子工程、自动化等相关专业。具备扎实的机器学习/深度学习基础；\n2.精通Python编程，熟练掌握PyTorch等深度学习框架。对Transformer、Diffusion等模型架构、计算瓶颈与优化方法论有深刻理解；具备以下至少一个领域经验：图像视频生成、音频理解生成、图像视频编辑/理解、模型压缩（步数蒸馏，轻量化模型，投机解码、KVCache优化、稀疏剪枝等）、生成对齐算法（DPO\\RLHF等）。\n3.满足上述课题方向中任意一个即可\n\nTEG\n技术工程事业群\n\n腾讯混元AI Infra部\nAI Infra部负责大模型训练及推理平台技术能力建设，聚焦大规模分布式训练、高性能推理服务等核心技术能力，构建大模型AI Infra核心竞争力，为大模型算法研发和业务场景落地提供稳定高效的技术支持和服务。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1236099085644457984","sourceKey":"tencent","company":"腾讯","title":"微信小微-支持方言的音频理解模型","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1236099085644457984","duty":"课题背景：\n微信语音消息、语音输入与通话场景覆盖海量用户，但普通话之外还存在大量客家话、邵阳话等小众方言使用需求。现有音频理解模型在方言场景下常出现识别不准、语义理解偏差等问题，影响沟通效率与产品体验，因此需要建设支持多方言的音频理解模型。\n\n课题挑战：\n方言种类多、发音差异大，同一句话在不同地区的音系、词汇和语法上差别明显，导致模型泛化困难。另一方面，方言标注数据稀缺且分布不均，部分长尾方言样本极少，训练成本高。真实微信场景中还存在口语化表达、多人混说、噪声干扰、设备差异等问题，需要模型同时具备鲁棒的语音识别、方言适配与语义理解能力。\n\n具体工作：\n参与方言语音数据处理与分析，探索多方言音频理解模型训练方案，优化识别与理解效果，并结合真实场景完成评测、迭代和效果验证。","requirements":"学历和专业要求：\n来自计算机、人工智能、自动化、电子信息、信号处理、数学等相关专业的博士/硕士同学。\n\n技术技能要求：\n掌握深度学习、生成模型、序列建模等算法及应用，熟悉Python，了解PyTorch/TensorFlow等训练框架。\n\n软性素质要求：\n具备良好的沟通协作与问题分析能力，对音乐、音频或AIGC方向有兴趣，学习能力和执行力强。","description":"课题描述\n课题背景：\n微信语音消息、语音输入与通话场景覆盖海量用户，但普通话之外还存在大量客家话、邵阳话等小众方言使用需求。现有音频理解模型在方言场景下常出现识别不准、语义理解偏差等问题，影响沟通效率与产品体验，因此需要建设支持多方言的音频理解模型。\n\n课题挑战：\n方言种类多、发音差异大，同一句话在不同地区的音系、词汇和语法上差别明显，导致模型泛化困难。另一方面，方言标注数据稀缺且分布不均，部分长尾方言样本极少，训练成本高。真实微信场景中还存在口语化表达、多人混说、噪声干扰、设备差异等问题，需要模型同时具备鲁棒的语音识别、方言适配与语义理解能力。\n\n具体工作：\n参与方言语音数据处理与分析，探索多方言音频理解模型训练方案，优化识别与理解效果，并结合真实场景完成评测、迭代和效果验证。\n\n课题要求\n学历和专业要求：\n来自计算机、人工智能、自动化、电子信息、信号处理、数学等相关专业的博士/硕士同学。\n\n技术技能要求：\n掌握深度学习、生成模型、序列建模等算法及应用，熟悉Python，了解PyTorch/TensorFlow等训练框架。\n\n软性素质要求：\n具备良好的沟通协作与问题分析能力，对音乐、音频或AIGC方向有兴趣，学习能力和执行力强。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nWXG\n微信事业群\n\n基础微信团队\n微信基础团队负责微信通讯与社交业务，为亿万用户提供高可用、低延迟的通讯基础设施。\n团队积极探索AI、音乐等创新领域，持续推进原生AI助手\"小微\"的研发，支持通过文字或语音对话操作微信原生功能，致力于打造更智能、更丰富的通讯社交生态。我们始终坚持产品逻辑的科学性与普适性，追求交互体验的简单与细致，以及技术实现的严谨与高效，致力于解决\"看似简单实则复杂\"的核心问题。\n如果你对产品与设计有自己的理解和抱负，对技术创新和实现有自己的理想与追求，欢迎加入微信基础团队，共同塑造下一代通讯社交基础设施。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1236099085644457985","sourceKey":"tencent","company":"腾讯","title":"微信小微-支持多方言的音频生成模型","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1236099085644457985","duty":"课题背景：\n微信语音消息、语音播报、数字人交互等场景对自然、拟真且具有地域亲和力的语音生成能力需求不断提升。普通话语音生成已较成熟，但在类似客家话等小语种方言场景中，现有模型常存在发音不准、韵律不自然、风格不稳定等问题，因此需要研发支持多方言的音频生成模型，提升用户体验与表达丰富度。\n\n课题挑战：\n多方言语音生成面临发音体系差异大、方言文本表示不统一、训练数据稀缺等问题。部分方言存在多音、多读法和强地域差异，导致模型难以准确学习语音映射关系。同时，真实业务还要求模型兼顾自然度、可懂度、情感表现力和说话人一致性，在长文本、口语化表达及跨方言迁移场景下都保持稳定生成，这对数据、建模和评测都提出了较高要求。\n\n具体工作：\n参与多方言语音数据清洗与标注，探索音频生成模型训练与优化方案，提升发音准确性和自然度，并完成评测分析与效果迭代。","requirements":"学历和专业要求：\n来自计算机、人工智能、自动化、电子信息、信号处理、数学等相关专业的博士/硕士同学。\n\n技术技能要求：\n掌握深度学习、生成模型、序列建模等算法及应用，熟悉Python，了解PyTorch/TensorFlow等训练框架。\n\n软性素质要求：\n具备良好的沟通协作与问题分析能力，对音乐、音频或AIGC方向有兴趣，学习能力和执行力强。","description":"课题描述\n课题背景：\n微信语音消息、语音播报、数字人交互等场景对自然、拟真且具有地域亲和力的语音生成能力需求不断提升。普通话语音生成已较成熟，但在类似客家话等小语种方言场景中，现有模型常存在发音不准、韵律不自然、风格不稳定等问题，因此需要研发支持多方言的音频生成模型，提升用户体验与表达丰富度。\n\n课题挑战：\n多方言语音生成面临发音体系差异大、方言文本表示不统一、训练数据稀缺等问题。部分方言存在多音、多读法和强地域差异，导致模型难以准确学习语音映射关系。同时，真实业务还要求模型兼顾自然度、可懂度、情感表现力和说话人一致性，在长文本、口语化表达及跨方言迁移场景下都保持稳定生成，这对数据、建模和评测都提出了较高要求。\n\n具体工作：\n参与多方言语音数据清洗与标注，探索音频生成模型训练与优化方案，提升发音准确性和自然度，并完成评测分析与效果迭代。\n\n课题要求\n学历和专业要求：\n来自计算机、人工智能、自动化、电子信息、信号处理、数学等相关专业的博士/硕士同学。\n\n技术技能要求：\n掌握深度学习、生成模型、序列建模等算法及应用，熟悉Python，了解PyTorch/TensorFlow等训练框架。\n\n软性素质要求：\n具备良好的沟通协作与问题分析能力，对音乐、音频或AIGC方向有兴趣，学习能力和执行力强。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nWXG\n微信事业群\n\n基础微信团队\n微信基础团队负责微信通讯与社交业务，为亿万用户提供高可用、低延迟的通讯基础设施。\n团队积极探索AI、音乐等创新领域，持续推进原生AI助手\"小微\"的研发，支持通过文字或语音对话操作微信原生功能，致力于打造更智能、更丰富的通讯社交生态。我们始终坚持产品逻辑的科学性与普适性，追求交互体验的简单与细致，以及技术实现的严谨与高效，致力于解决\"看似简单实则复杂\"的核心问题。\n如果你对产品与设计有自己的理解和抱负，对技术创新和实现有自己的理想与追求，欢迎加入微信基础团队，共同塑造下一代通讯社交基础设施。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1236099085644457986","sourceKey":"tencent","company":"腾讯","title":"听一听-音乐生成模型","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1236099085644457986","duty":"课题背景：\n“听一听”等音乐消费与互动场景对个性化、高质量音乐内容的需求持续增长。音乐生成模型能够辅助旋律创作、配器编排、风格延展与短音频生产，提升内容供给效率与创作多样性。随着生成式模型能力提升，探索面向真实业务场景的音乐生成技术，具有明显的产品价值和研究意义。\n\n课题挑战：\n音乐生成不仅要“好听”，还要同时保证旋律连贯、节奏稳定、和声合理与结构完整，比文本或语音生成更强调长期依赖建模。不同风格、情绪、乐器组合之间差异明显，数据标注和统一表示也较困难。真实应用中还需兼顾生成速度、可控性、版权风险规避以及主观评测标准不稳定等问题，因此模型设计、训练和评估都具有较高挑战。\n\n具体工作：\n参与音乐数据处理与分析，探索音乐生成模型训练和可控生成方法，优化生成质量与效率，并结合业务场景开展评测和迭代。","requirements":"学历和专业要求：\n来自计算机、人工智能、自动化、电子信息、信号处理、数学等相关专业的博士/硕士同学。\n\n技术技能要求：\n掌握深度学习、生成模型、序列建模等算法及应用，熟悉Python，了解PyTorch/TensorFlow等训练框架。\n\n软性素质要求：\n具备良好的沟通协作与问题分析能力，对音乐、音频或AIGC方向有兴趣，学习能力和执行力强。","description":"课题描述\n课题背景：\n“听一听”等音乐消费与互动场景对个性化、高质量音乐内容的需求持续增长。音乐生成模型能够辅助旋律创作、配器编排、风格延展与短音频生产，提升内容供给效率与创作多样性。随着生成式模型能力提升，探索面向真实业务场景的音乐生成技术，具有明显的产品价值和研究意义。\n\n课题挑战：\n音乐生成不仅要“好听”，还要同时保证旋律连贯、节奏稳定、和声合理与结构完整，比文本或语音生成更强调长期依赖建模。不同风格、情绪、乐器组合之间差异明显，数据标注和统一表示也较困难。真实应用中还需兼顾生成速度、可控性、版权风险规避以及主观评测标准不稳定等问题，因此模型设计、训练和评估都具有较高挑战。\n\n具体工作：\n参与音乐数据处理与分析，探索音乐生成模型训练和可控生成方法，优化生成质量与效率，并结合业务场景开展评测和迭代。\n\n课题要求\n学历和专业要求：\n来自计算机、人工智能、自动化、电子信息、信号处理、数学等相关专业的博士/硕士同学。\n\n技术技能要求：\n掌握深度学习、生成模型、序列建模等算法及应用，熟悉Python，了解PyTorch/TensorFlow等训练框架。\n\n软性素质要求：\n具备良好的沟通协作与问题分析能力，对音乐、音频或AIGC方向有兴趣，学习能力和执行力强。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nWXG\n微信事业群\n\n基础微信团队\n微信基础团队负责微信通讯与社交业务，为亿万用户提供高可用、低延迟的通讯基础设施。\n团队积极探索AI、音乐等创新领域，持续推进原生AI助手\"小微\"的研发，支持通过文字或语音对话操作微信原生功能，致力于打造更智能、更丰富的通讯社交生态。我们始终坚持产品逻辑的科学性与普适性，追求交互体验的简单与细致，以及技术实现的严谨与高效，致力于解决\"看似简单实则复杂\"的核心问题。\n如果你对产品与设计有自己的理解和抱负，对技术创新和实现有自己的理想与追求，欢迎加入微信基础团队，共同塑造下一代通讯社交基础设施。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1236099085644457987","sourceKey":"tencent","company":"腾讯","title":"微信小微-用户人格建模与个性化对话研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1236099085644457987","duty":"课题背景：\n微信助手目标是做最懂用户的聊天助手，不仅要帮用户做事，还要能有情商地聊天。但现有大模型在对话风格上千人一面，缺乏对用户个性、情绪与偏好的持续感知能力。如何让助手在长期交互中逐步形成对每个用户的独特理解，并以此驱动更贴合用户的回复风格，是提升助手体验的核心课题。\n\n课题挑战：\n用户的个性与情绪信息散落在大量碎片化对话中，显式信号稀少，提炼和更新人格画像本身就是难题，还需防止长期更新带来的遗忘与漂移。同时，助手在不同场景下需要兼顾风格一致性与情感自适应，两者之间的平衡难以把握。此外，人格建模涉及用户隐私，如何在保护隐私的前提下实现高质量建模，也是不可回避的现实约束。\n\n具体工作：\n参与用户人格表示体系的设计与构建，探索人格画像动态注入对话生成的方法，结合微信助手真实场景完成效果评测与迭代优化。","requirements":"学历和专业要求：\n来自计算机、人工智能、自然语言处理、信息工程、心理学等相关专业的博士/硕士同学。\n\n技术技能要求：\n掌握大模型SFT、RLHF、用户画像建模等算法及应用，熟悉Python，了解PyTorch/TensorFlow等训练框架。\n\n软性素质要求：\n具备良好的沟通协作与问题分析能力，对个性化对话或用户体验方向有兴趣，学习能力和执行力强。","description":"课题描述\n课题背景：\n微信助手目标是做最懂用户的聊天助手，不仅要帮用户做事，还要能有情商地聊天。但现有大模型在对话风格上千人一面，缺乏对用户个性、情绪与偏好的持续感知能力。如何让助手在长期交互中逐步形成对每个用户的独特理解，并以此驱动更贴合用户的回复风格，是提升助手体验的核心课题。\n\n课题挑战：\n用户的个性与情绪信息散落在大量碎片化对话中，显式信号稀少，提炼和更新人格画像本身就是难题，还需防止长期更新带来的遗忘与漂移。同时，助手在不同场景下需要兼顾风格一致性与情感自适应，两者之间的平衡难以把握。此外，人格建模涉及用户隐私，如何在保护隐私的前提下实现高质量建模，也是不可回避的现实约束。\n\n具体工作：\n参与用户人格表示体系的设计与构建，探索人格画像动态注入对话生成的方法，结合微信助手真实场景完成效果评测与迭代优化。\n\n课题要求\n学历和专业要求：\n来自计算机、人工智能、自然语言处理、信息工程、心理学等相关专业的博士/硕士同学。\n\n技术技能要求：\n掌握大模型SFT、RLHF、用户画像建模等算法及应用，熟悉Python，了解PyTorch/TensorFlow等训练框架。\n\n软性素质要求：\n具备良好的沟通协作与问题分析能力，对个性化对话或用户体验方向有兴趣，学习能力和执行力强。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nWXG\n微信事业群\n\n基础微信团队\n微信基础团队负责微信通讯与社交业务，为亿万用户提供高可用、低延迟的通讯基础设施。\n团队积极探索AI、音乐等创新领域，持续推进原生AI助手\"小微\"的研发，支持通过文字或语音对话操作微信原生功能，致力于打造更智能、更丰富的通讯社交生态。我们始终坚持产品逻辑的科学性与普适性，追求交互体验的简单与细致，以及技术实现的严谨与高效，致力于解决\"看似简单实则复杂\"的核心问题。\n如果你对产品与设计有自己的理解和抱负，对技术创新和实现有自己的理想与追求，欢迎加入微信基础团队，共同塑造下一代通讯社交基础设施。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1236099085644457988","sourceKey":"tencent","company":"腾讯","title":"微信小微-记忆系统的构建与下游应用","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1236099085644457988","duty":"课题背景：\n微信助手生长于微信之中，无论是作为朋友、助手、秘书，微信助手都需要、也有足够的潜力懂用户。如何在保证用户隐私的情况下，构建记忆系统、用好记忆系统，让用户能够感受到足够的贴心、但又不至于冒犯，是提升微信助手体验的核心课题，也是微信助手的重大潜力。\n\n课题挑战：\n微信生态中的消费数据极度多元，涵盖聊天、朋友圈、支付、小程序、收藏等众多场景，数据的异构性与碎片化使得记忆的统一抽取、结构化与质量保证面临巨大挑战。与此同时，微信用户群体跨度极广，不同年龄层、使用习惯与认知水平的用户对\"贴心\"与\"冒犯\"的边界感知迥异，记忆系统需在高度个性化的同时兼顾足够的泛化能力。在技术链路上，用户画像的持续构建、海量记忆的精准检索、记忆在对话生成中的有效注入，以及通过agentic后训练提升记忆效果，还需兼顾成本与效果，极具挑战。此外，微信中沉淀着用户大量个人文件与资料，如何将其组织为可检索的私有知识库，也是记忆系统落地不可回避的工程难题。\n\n具体工作：\n参与用户记忆体系的设计与构建，探索海量异构消费数据的统一抽取与结构化方案，研究用户画像的持续更新与精准检索机制，并在微信助手真实场景中完成效果评测与迭代。","requirements":"学历和专业要求：\n来自计算机、人工智能、统计学、信息工程、数据挖掘等相关专业的博士、硕士同学。\n\n技术技能要求：\n掌握用户画像构建、记忆检索、知识图谱或图学习等相关算法及应用，熟悉NLP与对话系统技术，了解RAG、LLM后训练或隐私保护机器学习者优先。\n\n软性素质要求：\n具备良好的数据分析与问题拆解能力，对用户建模与对话体验方向有兴趣，逻辑严谨，执行力强。","description":"课题描述\n课题背景：\n微信助手生长于微信之中，无论是作为朋友、助手、秘书，微信助手都需要、也有足够的潜力懂用户。如何在保证用户隐私的情况下，构建记忆系统、用好记忆系统，让用户能够感受到足够的贴心、但又不至于冒犯，是提升微信助手体验的核心课题，也是微信助手的重大潜力。\n\n课题挑战：\n微信生态中的消费数据极度多元，涵盖聊天、朋友圈、支付、小程序、收藏等众多场景，数据的异构性与碎片化使得记忆的统一抽取、结构化与质量保证面临巨大挑战。与此同时，微信用户群体跨度极广，不同年龄层、使用习惯与认知水平的用户对\"贴心\"与\"冒犯\"的边界感知迥异，记忆系统需在高度个性化的同时兼顾足够的泛化能力。在技术链路上，用户画像的持续构建、海量记忆的精准检索、记忆在对话生成中的有效注入，以及通过agentic后训练提升记忆效果，还需兼顾成本与效果，极具挑战。此外，微信中沉淀着用户大量个人文件与资料，如何将其组织为可检索的私有知识库，也是记忆系统落地不可回避的工程难题。\n\n具体工作：\n参与用户记忆体系的设计与构建，探索海量异构消费数据的统一抽取与结构化方案，研究用户画像的持续更新与精准检索机制，并在微信助手真实场景中完成效果评测与迭代。\n\n课题要求\n学历和专业要求：\n来自计算机、人工智能、统计学、信息工程、数据挖掘等相关专业的博士、硕士同学。\n\n技术技能要求：\n掌握用户画像构建、记忆检索、知识图谱或图学习等相关算法及应用，熟悉NLP与对话系统技术，了解RAG、LLM后训练或隐私保护机器学习者优先。\n\n软性素质要求：\n具备良好的数据分析与问题拆解能力，对用户建模与对话体验方向有兴趣，逻辑严谨，执行力强。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nWXG\n微信事业群\n\n基础微信团队\n微信基础团队负责微信通讯与社交业务，为亿万用户提供高可用、低延迟的通讯基础设施。\n团队积极探索AI、音乐等创新领域，持续推进原生AI助手\"小微\"的研发，支持通过文字或语音对话操作微信原生功能，致力于打造更智能、更丰富的通讯社交生态。我们始终坚持产品逻辑的科学性与普适性，追求交互体验的简单与细致，以及技术实现的严谨与高效，致力于解决\"看似简单实则复杂\"的核心问题。\n如果你对产品与设计有自己的理解和抱负，对技术创新和实现有自己的理想与追求，欢迎加入微信基础团队，共同塑造下一代通讯社交基础设施。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1236099085644457989","sourceKey":"tencent","company":"腾讯","title":"微信小微-基于微信复杂生态的Agentic后训练研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1236099085644457989","duty":"课题背景：\n微信的生态非常丰富，拥有朋友圈、视频号、公众号、小程序等功能。作为微信助手，如何能够正确地使用这些功能，是助手能力的基本盘。现有的基模主要聚焦于通用的能力和世界知识，与微信生态和用户真实的使用情况有鸿沟，因此需要我们针对业务场景进行Agentic后训练。\n\n课题挑战：\n微信生态中朋友圈、视频号、公众号、小程序等各功能模块的交互逻辑差异显著，构建高保真的训练环境本身就是一个复杂的系统工程。真实业务场景下，功能调用成败的判断标准模糊，缺乏标准化的自动评估体系，使得模型能力的量化与对比困难重重。Agentic后训练覆盖的能力众多，合版时需要兼顾各能力的独立效果与版内耦合，稍有不慎就可能引入能力遗忘或负向迁移。此外，线上用户的query高度复杂，往往包含多步骤的组合任务与个性化上下文，对模型的指令遵循、工具调用与长程规划能力提出了更高的要求。\n\n具体工作：\n参与Agentic后训练数据体系的设计与构建，探索面向微信生态的多能力联合训练与合版优化方法，结合微信助手真实场景完成效果评测与迭代优化。","requirements":"学历和专业要求：\n来自计算机、人工智能、自动化、信息工程等相关专业的博士、硕士同学。\n\n技术技能要求：\n掌握大模型SFT、强化学习、持续学习等算法及应用，熟悉Python，了解PyTorch等训练框架及LLM Agent相关技术。\n\n软性素质要求：\n具备较强的自主探索与工程实现能力，对Agent系统与后训练方向有浓厚兴趣，学习能力强，能独立推进研究课题。","description":"课题描述\n课题背景：\n微信的生态非常丰富，拥有朋友圈、视频号、公众号、小程序等功能。作为微信助手，如何能够正确地使用这些功能，是助手能力的基本盘。现有的基模主要聚焦于通用的能力和世界知识，与微信生态和用户真实的使用情况有鸿沟，因此需要我们针对业务场景进行Agentic后训练。\n\n课题挑战：\n微信生态中朋友圈、视频号、公众号、小程序等各功能模块的交互逻辑差异显著，构建高保真的训练环境本身就是一个复杂的系统工程。真实业务场景下，功能调用成败的判断标准模糊，缺乏标准化的自动评估体系，使得模型能力的量化与对比困难重重。Agentic后训练覆盖的能力众多，合版时需要兼顾各能力的独立效果与版内耦合，稍有不慎就可能引入能力遗忘或负向迁移。此外，线上用户的query高度复杂，往往包含多步骤的组合任务与个性化上下文，对模型的指令遵循、工具调用与长程规划能力提出了更高的要求。\n\n具体工作：\n参与Agentic后训练数据体系的设计与构建，探索面向微信生态的多能力联合训练与合版优化方法，结合微信助手真实场景完成效果评测与迭代优化。\n\n课题要求\n学历和专业要求：\n来自计算机、人工智能、自动化、信息工程等相关专业的博士、硕士同学。\n\n技术技能要求：\n掌握大模型SFT、强化学习、持续学习等算法及应用，熟悉Python，了解PyTorch等训练框架及LLM Agent相关技术。\n\n软性素质要求：\n具备较强的自主探索与工程实现能力，对Agent系统与后训练方向有浓厚兴趣，学习能力强，能独立推进研究课题。\n\n加分项或注意事项\n此课题同时招聘应届实习生和低年级实习生。\n\nWXG\n微信事业群\n\n基础微信团队\n微信基础团队负责微信通讯与社交业务，为亿万用户提供高可用、低延迟的通讯基础设施。\n团队积极探索AI、音乐等创新领域，持续推进原生AI助手\"小微\"的研发，支持通过文字或语音对话操作微信原生功能，致力于打造更智能、更丰富的通讯社交生态。我们始终坚持产品逻辑的科学性与普适性，追求交互体验的简单与细致，以及技术实现的严谨与高效，致力于解决\"看似简单实则复杂\"的核心问题。\n如果你对产品与设计有自己的理解和抱负，对技术创新和实现有自己的理想与追求，欢迎加入微信基础团队，共同塑造下一代通讯社交基础设施。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1236103359740901376","sourceKey":"tencent","company":"腾讯","title":"企业微信-基于大语言模型的非结构化数据知识挖掘与智能体应用研究","city":"深圳总部/北京/广州","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1236103359740901376","duty":"课题背景：\n企业办公场景中沉淀了海量非结构化数据资产，蕴含着丰富的业务知识与关联信息。本课题旨在基于大语言模型，从复杂的非结构化数据中安全、精准地提取结构化知识，并构建自动化的知识挖掘与分析系统，为企业智能化升级提供核心技术支撑。\n\n课题挑战：\n1、复杂数据的结构化提取：原始数据存在边界模糊、话题交织、语义歧义等特征，需攻克高难度的非结构化文本解析与结构化表示难题。\n2、深层知识关系挖掘：从海量文本中挖掘隐含的实体关系、业务流程与知识图谱，要求极高的准确率和鲁棒性。\n3、知识与智能体的融合应用：将挖掘所得的结构化知识与智能体（Agent）能力深度结合，在实际业务场景中实现稳定、可泛化的智能应用。\n\n具体工作：\n深度参与非结构化数据知识挖掘与智能体应用的研发工作。核心职责包括：基于 LLM 设计并优化知识抽取与图谱构建方案，探索结构化知识与智能体系统的融合路径，推动研究成果在真实场景中落地。","requirements":"岗位职责：\n1、计算机、数学、统计学、自然语言处理、机器学习、人工智能及相关理工科专业，博士学历优先，特别优秀的硕士亦可考虑；\n2、具备LLM驱动的知识图谱构建、信息抽取、结构化处理经验者优先，包括但不限于图数据库应用、实体对齐等；\n3、熟悉序列建模、行为预测等技术，有数据挖掘相关研究经验者优先；\n4、有顶会论文发表、知名研究机构实习经验或开源项目贡献者优先。","description":"课题描述\n课题背景：\n企业办公场景中沉淀了海量非结构化数据资产，蕴含着丰富的业务知识与关联信息。本课题旨在基于大语言模型，从复杂的非结构化数据中安全、精准地提取结构化知识，并构建自动化的知识挖掘与分析系统，为企业智能化升级提供核心技术支撑。\n\n课题挑战：\n1、复杂数据的结构化提取：原始数据存在边界模糊、话题交织、语义歧义等特征，需攻克高难度的非结构化文本解析与结构化表示难题。\n2、深层知识关系挖掘：从海量文本中挖掘隐含的实体关系、业务流程与知识图谱，要求极高的准确率和鲁棒性。\n3、知识与智能体的融合应用：将挖掘所得的结构化知识与智能体（Agent）能力深度结合，在实际业务场景中实现稳定、可泛化的智能应用。\n\n具体工作：\n深度参与非结构化数据知识挖掘与智能体应用的研发工作。核心职责包括：基于 LLM 设计并优化知识抽取与图谱构建方案，探索结构化知识与智能体系统的融合路径，推动研究成果在真实场景中落地。\n\n课题要求\n岗位职责：\n1、计算机、数学、统计学、自然语言处理、机器学习、人工智能及相关理工科专业，博士学历优先，特别优秀的硕士亦可考虑；\n2、具备LLM驱动的知识图谱构建、信息抽取、结构化处理经验者优先，包括但不限于图数据库应用、实体对齐等；\n3、熟悉序列建模、行为预测等技术，有数据挖掘相关研究经验者优先；\n4、有顶会论文发表、知名研究机构实习经验或开源项目贡献者优先。\n\nWXG\n微信事业群\n\n企业微信团队\n企业微信是企业级的通讯和办公工具，是腾讯连接消费互联网与产业互联网的重要连接器：一端连接超过1400万家企业和组织，一端连接超过14亿微信用户。\n企业微信的客户覆盖制造、零售、教育、金融、互联网等90多个行业。\n在AI时代，企业微信研发了AI Agent智能助理大圆、AI记录面聊、AI服务总结等功能，探索让AI走进企业的办公与经营现场，解决企业的真实问题。\n在这里，你会看到中国千行百业真实的工作现场，直面前沿技术挑战，参与AI功能研发，用产品解决企业每天都在发生的协作与服务难题。\n企业微信团队相信“连接创造价值”，期待有思考、有热情、有创造力的你加入团队！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1236474219777485824","sourceKey":"tencent","company":"腾讯","title":"混元基座模型-可在线持续进化的智能体算法研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1236474219777485824","duty":"课题背景：\n当前的智能体（Agents）大多遵循“离线训练-在线部署”的范式。然而，在实际应用场景（如开放域对话、复杂游戏环境、动态自动驾驶等）中，环境的分布是非平稳的（Non-stationary），且用户的需求在不断变化。 在线持续进化（Online Continual Evolution）旨在打破静止模型的限制，使智能体具备在与环境交互的过程中实时学习、自我纠偏与能力扩张的能力，最终实现长效的自主增长。\n\n课题挑战：\n- 灾难性遗忘（Catastrophic Forgetting）： 如何在学习新任务/新知识的同时，确保智能体不丢失已掌握的存量能力？\n- 样本效率与实时性： 在线交互成本高昂，如何在极少量样本下实现快速收敛，并满足推理延迟要求？\n- 长程记忆管理： 如何从海量的交互序列中筛选、压缩并提取有效信息，转化为模型的长期知识？\n\n具体工作：\n- 算法架构设计： 探索基于元学习（Meta-Learning）、动态架构扩展或神经调制技术的持续学习框架。\n- 自我演化机制研究： 研发智能体自主生成练习任务（Self-Generated Tasks）或通过自我博弈（Self-Play）驱动能力进化的算法。\n- 数据飞轮构建： 设计高效的在线采样策略与自动化数据清洗、标注流水线，实现“交互-反馈-微调”的闭环。\n- 实验验证与评估： 在主流的智能体评测集（如 WebShop, AgentBench）或自建的动态仿真环境中进行大规模实验，并追踪模型生命周期的性能曲线。","requirements":"学历和专业要求：\n计算机、人工智能相关专业在读硕士/博士。\n\n技术技能要求：\n- 深厚的深度学习背景，熟练掌握 PyTorch/JAX 框架及分布式训练工具。\n- 熟悉强化学习（PPO, SAC等）或大语言模型（LLM）微调（LoRA, Full Fine-tuning）技术。","description":"课题描述\n课题背景：\n当前的智能体（Agents）大多遵循“离线训练-在线部署”的范式。然而，在实际应用场景（如开放域对话、复杂游戏环境、动态自动驾驶等）中，环境的分布是非平稳的（Non-stationary），且用户的需求在不断变化。 在线持续进化（Online Continual Evolution）旨在打破静止模型的限制，使智能体具备在与环境交互的过程中实时学习、自我纠偏与能力扩张的能力，最终实现长效的自主增长。\n\n课题挑战：\n- 灾难性遗忘（Catastrophic Forgetting）： 如何在学习新任务/新知识的同时，确保智能体不丢失已掌握的存量能力？\n- 样本效率与实时性： 在线交互成本高昂，如何在极少量样本下实现快速收敛，并满足推理延迟要求？\n- 长程记忆管理： 如何从海量的交互序列中筛选、压缩并提取有效信息，转化为模型的长期知识？\n\n具体工作：\n- 算法架构设计： 探索基于元学习（Meta-Learning）、动态架构扩展或神经调制技术的持续学习框架。\n- 自我演化机制研究： 研发智能体自主生成练习任务（Self-Generated Tasks）或通过自我博弈（Self-Play）驱动能力进化的算法。\n- 数据飞轮构建： 设计高效的在线采样策略与自动化数据清洗、标注流水线，实现“交互-反馈-微调”的闭环。\n- 实验验证与评估： 在主流的智能体评测集（如 WebShop, AgentBench）或自建的动态仿真环境中进行大规模实验，并追踪模型生命周期的性能曲线。\n\n课题要求\n学历和专业要求：\n计算机、人工智能相关专业在读硕士/博士。\n\n技术技能要求：\n- 深厚的深度学习背景，熟练掌握 PyTorch/JAX 框架及分布式训练工具。\n- 熟悉强化学习（PPO, SAC等）或大语言模型（LLM）微调（LoRA, Full Fine-tuning）技术。\n\nTEG\n技术工程事业群\n\n腾讯混元基础模型部\n基础模型部负责混元大模型的前沿技术探索与基础模型研发，聚焦模型结构、数据与训练策略、强化学习及Agent能力，协同各模态研发能力，高效开发并迭代基础模型架构，面向AGI愿景探索智能上限、确保技术领先；同时构建基于大模型的AI PaaS中台能力，赋能公司内外部的产品创新与业务应用。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1237440383043269633","sourceKey":"tencent","company":"腾讯","title":"腾讯云-OpenClaw轻量云Runtime基础设施与应用技术的研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1237440383043269633","duty":"课题背景：\nOpenClaw 作为高开放性的 AI Agent 框架，具备插件扩展、环境控制、文件访问和多通道接入等能力，能够支持更加灵活和复杂的 Agent 应用构建。但也正因其开放性强、系统能力深，实际落地过程中对运行权限、安全隔离、接入效率和运维能力提出了更高要求，因此需要为 OpenClaw 提供更易部署、更安全、可推广的云上承载方案。\n\n课题挑战：\n本课题的难点主要体现在三个方面。首先，OpenClaw 需要较高运行权限，涉及本地文件系统、命令执行和外部服务调用，容易引发权限边界不清、数据暴露和运行隔离不足等安全问题；其次，在实际部署中，IM 通道接入复杂、运行环境搭建繁琐、安全加固成本高，影响了框架的快速落地；最后，在多人复用和规模化推广场景下，还需解决统一运维、标准化交付和使用门槛较高等问题，才能支撑 OpenClaw 的稳定推广和云上规模化应用。\n\n具体工作：\n围绕 OpenClaw 的云上落地，研究并建设快速接入通信通道的能力，设计更安全的运行环境与隔离机制，沉淀标准化部署方案，提升多人复用和统一运维能力，降低整体使用与推广门槛。","requirements":"1、熟悉深度学习基础理论，掌握模型蒸馏核心原理，了解扩散模型、大语言模型的基本结构；\n2、熟练使用Python编程语言，掌握PyTorch/FSDP等深度学习框架，能独立完成模型训练与调试；\n3、具备良好的逻辑思维能力、问题解决能力，对模型加速、蒸馏方向有浓厚兴趣，愿意主动学习前沿技术；\n4、熟悉模型蒸馏、量化（INT8/INT4）、剪枝等常用模型压缩技术，有落地经验。","description":"课题描述\n课题背景：\nOpenClaw 作为高开放性的 AI Agent 框架，具备插件扩展、环境控制、文件访问和多通道接入等能力，能够支持更加灵活和复杂的 Agent 应用构建。但也正因其开放性强、系统能力深，实际落地过程中对运行权限、安全隔离、接入效率和运维能力提出了更高要求，因此需要为 OpenClaw 提供更易部署、更安全、可推广的云上承载方案。\n\n课题挑战：\n本课题的难点主要体现在三个方面。首先，OpenClaw 需要较高运行权限，涉及本地文件系统、命令执行和外部服务调用，容易引发权限边界不清、数据暴露和运行隔离不足等安全问题；其次，在实际部署中，IM 通道接入复杂、运行环境搭建繁琐、安全加固成本高，影响了框架的快速落地；最后，在多人复用和规模化推广场景下，还需解决统一运维、标准化交付和使用门槛较高等问题，才能支撑 OpenClaw 的稳定推广和云上规模化应用。\n\n具体工作：\n围绕 OpenClaw 的云上落地，研究并建设快速接入通信通道的能力，设计更安全的运行环境与隔离机制，沉淀标准化部署方案，提升多人复用和统一运维能力，降低整体使用与推广门槛。\n\n课题要求\n1、熟悉深度学习基础理论，掌握模型蒸馏核心原理，了解扩散模型、大语言模型的基本结构；\n2、熟练使用Python编程语言，掌握PyTorch/FSDP等深度学习框架，能独立完成模型训练与调试；\n3、具备良好的逻辑思维能力、问题解决能力，对模型加速、蒸馏方向有浓厚兴趣，愿意主动学习前沿技术；\n4、熟悉模型蒸馏、量化（INT8/INT4）、剪枝等常用模型压缩技术，有落地经验。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1243708556705035264","sourceKey":"tencent","company":"腾讯","title":"混元-Code Agent 攻防研究与沙盒构建","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1243708556705035264","duty":"课题背景：\n现有的评测基准（如传统的 SWE-bench 或 HumanEval）极度脆弱，模型可以通过截获标准输出、劫持测试脚本等方式轻易“作弊”刷榜，导致评测分数虚高，完全掩盖了工业级部署中的级联错误与系统崩溃风险。因此，我们希望你系统性地研究如何LLM如何通过各种手段绕过沙盒限制，直接hack奖励，探索现有主流coding-bench的漏洞，同时研究如何防御住模型的hack，形成系统性的攻防体系。\n\n课题挑战：\n如何系统发现并复现模型的作弊与利用行为，如何区分正常修复和奖励攻击，如何构建既安全又不脱离真实开发场景的防篡改评测环境，以及如何建立能持续演进的攻防与审计机制。\n\n具体工作：\n1、发掘与复现代码智能体的欺骗与利用能力：\n针对主流开源或商业大模型，研究并诱导模型执行高级欺骗行为，如：测试台沙盒逃逸、直接检索答案、测试日志的伪造、针对执行环节的依赖劫持等欺骗奖励系统的行为；\n2、构建防篡改的评测容器与审计机制：零信任沙盒 + 轨迹异常检测。","requirements":"1、计算机科学、软件工程、人工智能或相关专业硕士及以上学历，具备大模型数据工程或Code LLM等实际项目经验；\n2、深入理解 Transformer 架构及大语言模型训练原理，具备丰富的数据处理经验。能针对Code SFT、代码偏好对齐等后训练场景，设计高标准数据方案，有项目实战经验；\n3、深入实践过 CodeAct、SWE-agent、LATS、AlphaCode等前沿代码推理与自动化框架者优先；\n4、熟练掌握 Python，善于利用 Cursor、Claude Code 等 AI 辅助工具提升数据生产与自动化分析效率。熟悉至少一门其他主流编程语言（C++/Java/Go等），熟悉Docker优先；\n5、在前沿会议有高质量论文发表，或在开源社区有高影响力贡献者优先；\n6、具备强烈的数据敏感度、技术热情和自驱力，能够从繁杂的代码与报错日志中洞察模型能力的边界，拥有优秀的跨团队（模型、评测、平台）协作与沟通能力。","description":"课题描述\n课题背景：\n现有的评测基准（如传统的 SWE-bench 或 HumanEval）极度脆弱，模型可以通过截获标准输出、劫持测试脚本等方式轻易“作弊”刷榜，导致评测分数虚高，完全掩盖了工业级部署中的级联错误与系统崩溃风险。因此，我们希望你系统性地研究如何LLM如何通过各种手段绕过沙盒限制，直接hack奖励，探索现有主流coding-bench的漏洞，同时研究如何防御住模型的hack，形成系统性的攻防体系。\n\n课题挑战：\n如何系统发现并复现模型的作弊与利用行为，如何区分正常修复和奖励攻击，如何构建既安全又不脱离真实开发场景的防篡改评测环境，以及如何建立能持续演进的攻防与审计机制。\n\n具体工作：\n1、发掘与复现代码智能体的欺骗与利用能力：\n针对主流开源或商业大模型，研究并诱导模型执行高级欺骗行为，如：测试台沙盒逃逸、直接检索答案、测试日志的伪造、针对执行环节的依赖劫持等欺骗奖励系统的行为；\n2、构建防篡改的评测容器与审计机制：零信任沙盒 + 轨迹异常检测。\n\n课题要求\n1、计算机科学、软件工程、人工智能或相关专业硕士及以上学历，具备大模型数据工程或Code LLM等实际项目经验；\n2、深入理解 Transformer 架构及大语言模型训练原理，具备丰富的数据处理经验。能针对Code SFT、代码偏好对齐等后训练场景，设计高标准数据方案，有项目实战经验；\n3、深入实践过 CodeAct、SWE-agent、LATS、AlphaCode等前沿代码推理与自动化框架者优先；\n4、熟练掌握 Python，善于利用 Cursor、Claude Code 等 AI 辅助工具提升数据生产与自动化分析效率。熟悉至少一门其他主流编程语言（C++/Java/Go等），熟悉Docker优先；\n5、在前沿会议有高质量论文发表，或在开源社区有高影响力贡献者优先；\n6、具备强烈的数据敏感度、技术热情和自驱力，能够从繁杂的代码与报错日志中洞察模型能力的边界，拥有优秀的跨团队（模型、评测、平台）协作与沟通能力。\n\nTEG\n技术工程事业群\n\n腾讯混元AI Data部\nAI Data部是驱动大模型能力进化的核心引擎。我们专注于打造前沿的数据生态和评测体系，构建覆盖从评测优化、数据获取、智能清洗、精细标注、AI驱动合成、实验模拟以及严苛质检的全链路智能数据系统，确保为大模型的预训练、微调和实际应用注入顶尖品质的数据燃料。通过创新评测框架，我们不断引领模型性能的突破性优化。如果你热衷于AI前沿，加入我们，一起定义下一个智能时代！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1243708556705035265","sourceKey":"tencent","company":"腾讯","title":"混元-Code Agent 执行轨迹的评估与过程奖励研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1243708556705035265","duty":"课题背景：\n当前 Code Agent 的强化学习往往依赖最终的通过率作为稀疏奖励，这在长周期复杂任务中极易导致“奖励作弊”——模型可能生成欺骗测试用例但逻辑错误的代码。同时，静态代码切片的评估无法反映 Agent 在真实执行环境中的状态变异。同时，目前的评估体系（如 HumanEval 的 Pass@1 或 SWE-bench）也主要采用结果导向的评估方式，不利于对模型的真实能力做更细致的评估。\n\n课题挑战：\n如何定义“好轨迹”，如何针对不同任务类型自适应评估，如何从动态执行过程里提取有效信号，以及如何把高成本、主观性强的人工轨迹分析，转化为稳定、可规模化、还能服务强化学习的过程奖励。\n\n具体工作：\n本课题旨在构建一套全方位、多维度的 Code Agent 轨迹质量评估框架，不再单纯以“成败论英雄”，而是通过对 Agent 解决问题过程中的每一跳（Step）进行量化分析，从而：\n1、定义“好轨迹”的标准： 明确什么是高效、鲁棒且符合人类开发者逻辑的解决路径；\n2、自适应评估：对于不同类型的code agent数据，能自适应评估轨迹的质量；\n3、诊断与调优： 为 Agent 的迭代提供诊断报告，识别性能瓶颈；\n4、强化学习指引： 为基于过程奖励模型（PRMs）的强化学习提供高质量的评估信号。","requirements":"1、计算机科学、软件工程、人工智能或相关专业硕士及以上学历，具备大模型数据工程或Code LLM等实际项目经验；\n2、深入理解 Transformer 架构及大语言模型训练原理，具备丰富的数据处理经验。能针对Code SFT、代码偏好对齐等后训练场景，设计高标准数据方案，有项目实战经验；\n3、深入实践过 CodeAct、SWE-agent、LATS、AlphaCode等前沿代码推理与自动化框架者优先；\n4、熟练掌握 Python，善于利用 Cursor、Claude Code 等 AI 辅助工具提升数据生产与自动化分析效率。熟悉至少一门其他主流编程语言（C++/Java/Go等），熟悉Docker优先；\n5、在前沿会议有高质量论文发表，或在开源社区有高影响力贡献者优先；\n6、具备强烈的数据敏感度、技术热情和自驱力，能够从繁杂的代码与报错日志中洞察模型能力的边界，拥有优秀的跨团队（模型、评测、平台）协作与沟通能力。","description":"课题描述\n课题背景：\n当前 Code Agent 的强化学习往往依赖最终的通过率作为稀疏奖励，这在长周期复杂任务中极易导致“奖励作弊”——模型可能生成欺骗测试用例但逻辑错误的代码。同时，静态代码切片的评估无法反映 Agent 在真实执行环境中的状态变异。同时，目前的评估体系（如 HumanEval 的 Pass@1 或 SWE-bench）也主要采用结果导向的评估方式，不利于对模型的真实能力做更细致的评估。\n\n课题挑战：\n如何定义“好轨迹”，如何针对不同任务类型自适应评估，如何从动态执行过程里提取有效信号，以及如何把高成本、主观性强的人工轨迹分析，转化为稳定、可规模化、还能服务强化学习的过程奖励。\n\n具体工作：\n本课题旨在构建一套全方位、多维度的 Code Agent 轨迹质量评估框架，不再单纯以“成败论英雄”，而是通过对 Agent 解决问题过程中的每一跳（Step）进行量化分析，从而：\n1、定义“好轨迹”的标准： 明确什么是高效、鲁棒且符合人类开发者逻辑的解决路径；\n2、自适应评估：对于不同类型的code agent数据，能自适应评估轨迹的质量；\n3、诊断与调优： 为 Agent 的迭代提供诊断报告，识别性能瓶颈；\n4、强化学习指引： 为基于过程奖励模型（PRMs）的强化学习提供高质量的评估信号。\n\n课题要求\n1、计算机科学、软件工程、人工智能或相关专业硕士及以上学历，具备大模型数据工程或Code LLM等实际项目经验；\n2、深入理解 Transformer 架构及大语言模型训练原理，具备丰富的数据处理经验。能针对Code SFT、代码偏好对齐等后训练场景，设计高标准数据方案，有项目实战经验；\n3、深入实践过 CodeAct、SWE-agent、LATS、AlphaCode等前沿代码推理与自动化框架者优先；\n4、熟练掌握 Python，善于利用 Cursor、Claude Code 等 AI 辅助工具提升数据生产与自动化分析效率。熟悉至少一门其他主流编程语言（C++/Java/Go等），熟悉Docker优先；\n5、在前沿会议有高质量论文发表，或在开源社区有高影响力贡献者优先；\n6、具备强烈的数据敏感度、技术热情和自驱力，能够从繁杂的代码与报错日志中洞察模型能力的边界，拥有优秀的跨团队（模型、评测、平台）协作与沟通能力。\n\nTEG\n技术工程事业群\n\n腾讯混元AI Data部\nAI Data部是驱动大模型能力进化的核心引擎。我们专注于打造前沿的数据生态和评测体系，构建覆盖从评测优化、数据获取、智能清洗、精细标注、AI驱动合成、实验模拟以及严苛质检的全链路智能数据系统，确保为大模型的预训练、微调和实际应用注入顶尖品质的数据燃料。通过创新评测框架，我们不断引领模型性能的突破性优化。如果你热衷于AI前沿，加入我们，一起定义下一个智能时代！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1243708556705035266","sourceKey":"tencent","company":"腾讯","title":"混元-Agent 长程任务评测体系构建 & 自主协作能力持续深化研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1243708556705035266","duty":"课题背景：\n随着大模型从单轮问答走向自主执行复杂任务的 Agent 范式，如何系统性地评估 Agent 在真实场景中的长程规划、工具调用、多步推理与协作能力，成为推动 AGI 落地的关键瓶颈。当前的评测体系大多停留在静态问答或单步操作层面，难以衡量 Agent 在面对开放式、跨系统、长周期任务时的决策质量、容错恢复与自主演进能力。构建一套贴近真实工程场景、可自动化执行、具备足够区分度的 Agent 评测体系，对于牵引模型向更高阶智能迭代具有重要的战略价值。\n\n课题挑战：\n1、长程任务（Long-Horizon Task）的评测设计极其困难。此类任务涉及多步骤决策链路、环境状态持续变化、中间结果依赖与错误级联传播等问题，如何定义合理的任务粒度、设计可分解且可度量的评价指标、构建既能反映真实复杂度又可自动化执行的评测环境，是核心挑战。同时需要兼顾任务的多样性（代码仓库级修复、跨系统运维、端到端研发流程等）与标准化之间的平衡。\n\n2、多 Agent 协作与自主研究场景缺乏成熟的评测范式。在多 Agent 协同场景中，需要评估角色分工、信息共享、冲突消解与联合推理等能力，而在自主研究场景中，还需衡量 Agent 的探索策略、假设生成、实验设计与结论归纳等高阶认知能力。如何构建可复现、可扩展的评测框架来覆盖这些新兴能力维度，并设计兼顾过程评价与结果评价的自动化验证机制，是亟待突破的难题。\n\n具体工作：\n1、面向 Agent 长程任务的评测体系研究与落地，包括任务环境构建（容器化仿真、多工具链集成）、多层级自动化验证器（状态验证、功能验证、端到端集成验证）设计，以及基于结构化评分标准的自动评测流水线搭建。\n2、多 Agent 协作与自主研究评测能力的联合推进与深化，包括但不限于多 Agent 角色编排与协同效率评估、长程任务中的规划-执行-反思闭环能力度量、自主探索与知识获取效率分析，以及评测任务的众包生产与质量控制体系建设。","requirements":"1.计算机或者相关专业硕士或者以上学历，具备推荐/广告/CV/NLP/RL相关实习经验优先，有大模型调优化应用、评测经历优先；\n2.在ICLR、NeurIPS，ICML、KDD、AAAI，IJCAI等机器学习领域会议或者期刊有第一作者发表过至少一篇文章。","description":"课题描述\n课题背景：\n随着大模型从单轮问答走向自主执行复杂任务的 Agent 范式，如何系统性地评估 Agent 在真实场景中的长程规划、工具调用、多步推理与协作能力，成为推动 AGI 落地的关键瓶颈。当前的评测体系大多停留在静态问答或单步操作层面，难以衡量 Agent 在面对开放式、跨系统、长周期任务时的决策质量、容错恢复与自主演进能力。构建一套贴近真实工程场景、可自动化执行、具备足够区分度的 Agent 评测体系，对于牵引模型向更高阶智能迭代具有重要的战略价值。\n\n课题挑战：\n1、长程任务（Long-Horizon Task）的评测设计极其困难。此类任务涉及多步骤决策链路、环境状态持续变化、中间结果依赖与错误级联传播等问题，如何定义合理的任务粒度、设计可分解且可度量的评价指标、构建既能反映真实复杂度又可自动化执行的评测环境，是核心挑战。同时需要兼顾任务的多样性（代码仓库级修复、跨系统运维、端到端研发流程等）与标准化之间的平衡。\n\n2、多 Agent 协作与自主研究场景缺乏成熟的评测范式。在多 Agent 协同场景中，需要评估角色分工、信息共享、冲突消解与联合推理等能力，而在自主研究场景中，还需衡量 Agent 的探索策略、假设生成、实验设计与结论归纳等高阶认知能力。如何构建可复现、可扩展的评测框架来覆盖这些新兴能力维度，并设计兼顾过程评价与结果评价的自动化验证机制，是亟待突破的难题。\n\n具体工作：\n1、面向 Agent 长程任务的评测体系研究与落地，包括任务环境构建（容器化仿真、多工具链集成）、多层级自动化验证器（状态验证、功能验证、端到端集成验证）设计，以及基于结构化评分标准的自动评测流水线搭建。\n2、多 Agent 协作与自主研究评测能力的联合推进与深化，包括但不限于多 Agent 角色编排与协同效率评估、长程任务中的规划-执行-反思闭环能力度量、自主探索与知识获取效率分析，以及评测任务的众包生产与质量控制体系建设。\n\n课题要求\n1.计算机或者相关专业硕士或者以上学历，具备推荐/广告/CV/NLP/RL相关实习经验优先，有大模型调优化应用、评测经历优先；\n2.在ICLR、NeurIPS，ICML、KDD、AAAI，IJCAI等机器学习领域会议或者期刊有第一作者发表过至少一篇文章。\n\nTEG\n技术工程事业群\n\n腾讯混元AI Data部\nAI Data部是驱动大模型能力进化的核心引擎。我们专注于打造前沿的数据生态和评测体系，构建覆盖从评测优化、数据获取、智能清洗、精细标注、AI驱动合成、实验模拟以及严苛质检的全链路智能数据系统，确保为大模型的预训练、微调和实际应用注入顶尖品质的数据燃料。通过创新评测框架，我们不断引领模型性能的突破性优化。如果你热衷于AI前沿，加入我们，一起定义下一个智能时代！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1243708556705035267","sourceKey":"tencent","company":"腾讯","title":"混元-大模型复杂推理过程评测与过程奖励建模研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1243708556705035267","duty":"课题背景：\n当前主流评测基准普遍仅关注最终答案正确性，无法区分模型是通过严谨推理还是捷径匹配得出结论。随着大模型在数学证明、代码调试、多步科学推理等高阶任务中的应用深入，对推理过程本身的质量评估变得至关重要。构建一套量化每一步推理质量的过程级评测体系，既能精准诊断模型推理能力边界，又能为过程奖励模型（PRM）的强化学习提供高质量监督信号。\n\n课题挑战：\n1、推理过程的质量定义与自动化评估困难。同一正确结论可能对应多条风格迥异的推理链路，如何定义逻辑严谨性、步骤必要性、知识准确性等多维标准，并设计能自动判别推理步骤正确性、识别逻辑跳跃与幻觉注入的评测算法，是核心挑战。同时需探索基于模型互评与共识机制的低成本评测方案。\n\n2、过程评测到训练的闭环缺乏系统方法论。如何将评测结论转化为可用于强化学习的稠密过程奖励信号，需要研究推理步骤粒度划分策略、过程奖励模型训练范式（自动标注 vs 蒙特卡洛估计），以及过程奖励与结果奖励的联合优化机制。\n\n具体工作：\n1、推理过程评测体系研究与落地，包括推理链质量多维评价指标设计、跨任务类型（数学、代码、逻辑、科学）的过程级评测基准构建，以及自动化过程评测流水线搭建。\n2、过程奖励建模研究，包括过程奖励模型（PRM）的训练与校准、评测信号与强化学习训练的闭环打通，以及评测基准的持续迭代与难度进化机制。","requirements":"1.计算机或者相关专业硕士或者以上学历，具备推荐/广告/CV/NLP/RL相关实习经验优先，有大模型调优化应用、评测经历优先；\n2.在ICLR、NeurIPS，ICML、KDD、AAAI，IJCAI等机器学习领域会议或者期刊有第一作者发表过至少一篇文章。","description":"课题描述\n课题背景：\n当前主流评测基准普遍仅关注最终答案正确性，无法区分模型是通过严谨推理还是捷径匹配得出结论。随着大模型在数学证明、代码调试、多步科学推理等高阶任务中的应用深入，对推理过程本身的质量评估变得至关重要。构建一套量化每一步推理质量的过程级评测体系，既能精准诊断模型推理能力边界，又能为过程奖励模型（PRM）的强化学习提供高质量监督信号。\n\n课题挑战：\n1、推理过程的质量定义与自动化评估困难。同一正确结论可能对应多条风格迥异的推理链路，如何定义逻辑严谨性、步骤必要性、知识准确性等多维标准，并设计能自动判别推理步骤正确性、识别逻辑跳跃与幻觉注入的评测算法，是核心挑战。同时需探索基于模型互评与共识机制的低成本评测方案。\n\n2、过程评测到训练的闭环缺乏系统方法论。如何将评测结论转化为可用于强化学习的稠密过程奖励信号，需要研究推理步骤粒度划分策略、过程奖励模型训练范式（自动标注 vs 蒙特卡洛估计），以及过程奖励与结果奖励的联合优化机制。\n\n具体工作：\n1、推理过程评测体系研究与落地，包括推理链质量多维评价指标设计、跨任务类型（数学、代码、逻辑、科学）的过程级评测基准构建，以及自动化过程评测流水线搭建。\n2、过程奖励建模研究，包括过程奖励模型（PRM）的训练与校准、评测信号与强化学习训练的闭环打通，以及评测基准的持续迭代与难度进化机制。\n\n课题要求\n1.计算机或者相关专业硕士或者以上学历，具备推荐/广告/CV/NLP/RL相关实习经验优先，有大模型调优化应用、评测经历优先；\n2.在ICLR、NeurIPS，ICML、KDD、AAAI，IJCAI等机器学习领域会议或者期刊有第一作者发表过至少一篇文章。\n\nTEG\n技术工程事业群\n\n腾讯混元AI Data部\nAI Data部是驱动大模型能力进化的核心引擎。我们专注于打造前沿的数据生态和评测体系，构建覆盖从评测优化、数据获取、智能清洗、精细标注、AI驱动合成、实验模拟以及严苛质检的全链路智能数据系统，确保为大模型的预训练、微调和实际应用注入顶尖品质的数据燃料。通过创新评测框架，我们不断引领模型性能的突破性优化。如果你热衷于AI前沿，加入我们，一起定义下一个智能时代！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1243708556705035268","sourceKey":"tencent","company":"腾讯","title":"混元-大模型后训练数据全链路智能治理研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1243708556705035268","duty":"课题背景：\n大模型后训练数据的质量瓶颈正发生结构性转移：一方面，角色扮演、长文本创作、长程记忆等成熟场景中，数据缺陷从显性的事实错误演变为人设崩塌、逻辑断裂、记忆丢失等更隐蔽的系统性问题，现有质检手段难以精准定位与闭环修复；另一方面，Agentic 场景（多步决策、工具调用、环境交互）正快速崛起，但高质量 RL 训练数据的生产与验证范式缺乏。\n\n课题挑战：\n1、多场景数据质量的自动化评测与闭环治理： 构建覆盖角色扮演、文本创作、长程记忆等线上核心场景的可扩展多维 Rubrics 评分体系与自动化质检 Pipeline，解决自动评分与人类偏好的对齐难题；在此基础上打通从维度评分到缺陷归因、再到定向修复的闭环，解决当前\"能发现问题却无法定位成因、无法自动修复\"的链路断裂问题；\n2、Agentic 场景的 RL 数据合成： 探索在多步决策、工具调用、环境交互等 Agent 场景下，如何合成高质量 RL 训练数据，并设计可靠的过程级 reward 信号与轨迹级验证机制，解决 Agent 数据获取成本高、验证难、分布窄的核心瓶颈。\n\n具体工作：\n参与大模型后训练数据质量治理与 Agentic 数据生产的前沿研究，一方面研发多场景 Rubrics 评测、结构化归因与自动修复的端到端质量闭环，另一方面探索 Agent 场景下 RL 训练数据的自动化合成与验证方法，推动两条技术线在线上核心场景的落地与持续迭代。","requirements":"1、计算机科学、人工智能、自然语言处理等相关专业硕士及以上；\n2、在大模型评测、数据质量、Agent/RL 训练、对话系统等方向有深入研究经验者优先；\n3、有 ICLR、NeurIPS 和 ICML等顶会论文或高影响力开源贡献者优先；\n4、熟练掌握深度学习框架；深入理解 Transformer 架构及 SFT/RL 后训练原理；熟悉Rubric-based Evaluation 等前沿评测方法论；\n5、具备从海量数据与实验结果中发现隐含规律的洞察力，以及从 insight 到落地的全链路推动力。","description":"课题描述\n课题背景：\n大模型后训练数据的质量瓶颈正发生结构性转移：一方面，角色扮演、长文本创作、长程记忆等成熟场景中，数据缺陷从显性的事实错误演变为人设崩塌、逻辑断裂、记忆丢失等更隐蔽的系统性问题，现有质检手段难以精准定位与闭环修复；另一方面，Agentic 场景（多步决策、工具调用、环境交互）正快速崛起，但高质量 RL 训练数据的生产与验证范式缺乏。\n\n课题挑战：\n1、多场景数据质量的自动化评测与闭环治理： 构建覆盖角色扮演、文本创作、长程记忆等线上核心场景的可扩展多维 Rubrics 评分体系与自动化质检 Pipeline，解决自动评分与人类偏好的对齐难题；在此基础上打通从维度评分到缺陷归因、再到定向修复的闭环，解决当前\"能发现问题却无法定位成因、无法自动修复\"的链路断裂问题；\n2、Agentic 场景的 RL 数据合成： 探索在多步决策、工具调用、环境交互等 Agent 场景下，如何合成高质量 RL 训练数据，并设计可靠的过程级 reward 信号与轨迹级验证机制，解决 Agent 数据获取成本高、验证难、分布窄的核心瓶颈。\n\n具体工作：\n参与大模型后训练数据质量治理与 Agentic 数据生产的前沿研究，一方面研发多场景 Rubrics 评测、结构化归因与自动修复的端到端质量闭环，另一方面探索 Agent 场景下 RL 训练数据的自动化合成与验证方法，推动两条技术线在线上核心场景的落地与持续迭代。\n\n课题要求\n1、计算机科学、人工智能、自然语言处理等相关专业硕士及以上；\n2、在大模型评测、数据质量、Agent/RL 训练、对话系统等方向有深入研究经验者优先；\n3、有 ICLR、NeurIPS 和 ICML等顶会论文或高影响力开源贡献者优先；\n4、熟练掌握深度学习框架；深入理解 Transformer 架构及 SFT/RL 后训练原理；熟悉Rubric-based Evaluation 等前沿评测方法论；\n5、具备从海量数据与实验结果中发现隐含规律的洞察力，以及从 insight 到落地的全链路推动力。\n\nTEG\n技术工程事业群\n\n腾讯混元AI Data部\nAI Data部是驱动大模型能力进化的核心引擎。我们专注于打造前沿的数据生态和评测体系，构建覆盖从评测优化、数据获取、智能清洗、精细标注、AI驱动合成、实验模拟以及严苛质检的全链路智能数据系统，确保为大模型的预训练、微调和实际应用注入顶尖品质的数据燃料。通过创新评测框架，我们不断引领模型性能的突破性优化。如果你热衷于AI前沿，加入我们，一起定义下一个智能时代！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1243708556705035269","sourceKey":"tencent","company":"腾讯","title":"混元-面向复杂指令与智能体场景的大模型后训练数据飞轮构建研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1243708556705035269","duty":"课题背景：\n随着前沿模型基础能力持续提升，后训练阶段的核心问题逐步集中到复杂场景数据供给。长篇生成、多约束复杂指令、多轮交互、工具调用与长链路任务，对数据覆盖深度、结构质量、评价标准和迭代效率提出了更高要求。围绕高难样本发现、失败模式归因、自动化质检与定向补强构建数据飞轮，已成为复杂能力持续优化的关键路径。\n\n课题挑战：\n复杂场景数据具有长上下文、多约束、多步骤和动态交互等特征，数据复杂度高；模型复杂能力提升依赖任务类型、约束组合、工具链路和异常路径的充分覆盖，数据多样性要求高；数据提质不能停留在单次质检或局部修补，而需要构建“评测发现问题—错误归因分析—数据定向补强—配方迭代优化—效果回流验证”的飞轮闭环，持续提升数据质量与能力收益转化效率。\n\n具体工作：\n参与大模型后训练（SFT+RL）阶段长文、复杂指令与智能体数据的全链路研发，建立高难样本挖掘、场景分类与难度分层体系；设计长文本与长轨迹数据生产、反例构造和定向修复方案，保障长程连贯性、结构完整性与指令遵循精度；搭建 Rubrics 生成、自动评分、结果验证与多层质量校验 pipeline；沉淀失败模式归因框架，形成“评测发现问题—数据补强—配方迭代—效果回流”的闭环。","requirements":"1、计算机科学、人工智能、自然语言处理等相关专业硕士及以上；\n2、在大模型评测、数据质量、Agent/RL 训练、对话系统等方向有深入研究经验者优先；\n3、有 ICLR、NeurIPS 和 ICML等顶会论文或高影响力开源贡献者优先；\n4、熟练掌握claude code等 ai工具，有基于此落地的soild工作者优先；深入理解 Transformer 架构及 SFT/RL 后训练原理；熟悉Rubric-based Evaluation 等前沿评测方法论；\n5、具备从海量数据与实验结果中发现隐含规律的洞察力，以及从 insight 到落地的全链路推动力。","description":"课题描述\n课题背景：\n随着前沿模型基础能力持续提升，后训练阶段的核心问题逐步集中到复杂场景数据供给。长篇生成、多约束复杂指令、多轮交互、工具调用与长链路任务，对数据覆盖深度、结构质量、评价标准和迭代效率提出了更高要求。围绕高难样本发现、失败模式归因、自动化质检与定向补强构建数据飞轮，已成为复杂能力持续优化的关键路径。\n\n课题挑战：\n复杂场景数据具有长上下文、多约束、多步骤和动态交互等特征，数据复杂度高；模型复杂能力提升依赖任务类型、约束组合、工具链路和异常路径的充分覆盖，数据多样性要求高；数据提质不能停留在单次质检或局部修补，而需要构建“评测发现问题—错误归因分析—数据定向补强—配方迭代优化—效果回流验证”的飞轮闭环，持续提升数据质量与能力收益转化效率。\n\n具体工作：\n参与大模型后训练（SFT+RL）阶段长文、复杂指令与智能体数据的全链路研发，建立高难样本挖掘、场景分类与难度分层体系；设计长文本与长轨迹数据生产、反例构造和定向修复方案，保障长程连贯性、结构完整性与指令遵循精度；搭建 Rubrics 生成、自动评分、结果验证与多层质量校验 pipeline；沉淀失败模式归因框架，形成“评测发现问题—数据补强—配方迭代—效果回流”的闭环。\n\n课题要求\n1、计算机科学、人工智能、自然语言处理等相关专业硕士及以上；\n2、在大模型评测、数据质量、Agent/RL 训练、对话系统等方向有深入研究经验者优先；\n3、有 ICLR、NeurIPS 和 ICML等顶会论文或高影响力开源贡献者优先；\n4、熟练掌握claude code等 ai工具，有基于此落地的soild工作者优先；深入理解 Transformer 架构及 SFT/RL 后训练原理；熟悉Rubric-based Evaluation 等前沿评测方法论；\n5、具备从海量数据与实验结果中发现隐含规律的洞察力，以及从 insight 到落地的全链路推动力。\n\nTEG\n技术工程事业群\n\n腾讯混元AI Data部\nAI Data部是驱动大模型能力进化的核心引擎。我们专注于打造前沿的数据生态和评测体系，构建覆盖从评测优化、数据获取、智能清洗、精细标注、AI驱动合成、实验模拟以及严苛质检的全链路智能数据系统，确保为大模型的预训练、微调和实际应用注入顶尖品质的数据燃料。通过创新评测框架，我们不断引领模型性能的突破性优化。如果你热衷于AI前沿，加入我们，一起定义下一个智能时代！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1243708556705035270","sourceKey":"tencent","company":"腾讯","title":"混元-面向大模型后训练Agent能力的数据策略研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1243708556705035270","duty":"课题背景：\n随着大模型Agent能力的快速演进，Agent场景下的多轮交互、长链路规划及工具调用对后训练（SFT+RL）阶段的数据质量与多样性提出了极高要求。团队当前正深度打造混元大模型的Agent能力，支持OpenClaw、QClaw等面向真实用户的智能体产品，这些场景对模型的工具调用准确性、长链路任务规划能力及探索效率有极高的落地标准。当前Agent训练数据在复杂轨迹覆盖、探索效率、任务多样性等方面面临诸多挑战，本课题旨在通过研究高效的Agent数据生产、自动化质检与评测驱动的数据飞轮机制，持续提升产品级Agent核心能力、降低数据迭代成本、加速技术从研究到产品的闭环落地过程。\n\n课题挑战：\n1、Agent轨迹/环境生产与质检：基于多智能体博弈与复杂轨迹生成技术，研究面向Agent场景的高质量数据自动化生产方案，并设计自动化质检与定向修复算法，确保数据在多轮交互一致性、工具调用准确性、思维链质量等维度达到高标准；\n2、评测驱动的数据飞轮机制：设计科学的Agent能力自动化评测方案，通过深度剖析模型在探索效率、工具使用、长链路规划等实际任务中的弱项，构建\"评测发现问题—数据定向强化—效果闭环提升\"的数据飞轮，实现模型能力的持续迭代优化； \n3、前沿数据技术追踪与转化：持续跟踪Agent数据合成、复杂轨迹构建、多模态与多智能体互动等前沿方向，结合业务实际提出优化方案，将研究成果转化为可落地的业务价值。\n\n具体工作： \nAgent场景下SFT、RL复杂轨迹/环境的数据合成与自动化质检；Agent能力的自动化评测能力与数据飞轮；Agent RL数据的前沿方向研究与在Openclaw、Qclaw等核心场景的落地。","requirements":"1、计算机科学、人工智能等相关专业硕士及以上学历；\n2、熟悉大语言模型训练原理（Transformer架构、RLHF、LLM Alignment等），拥有大模型数据工程或模型训练实际项目经验，在顶会（NeurIPS、ICLR、ICML、ACL等）发表论文或在开源社区有高影响力贡献者优先；\n3、深入实践过ReAct、Reflexion等前沿Agent推理框架，能够系统性优化Agent思维链质量、工具调用鲁棒性及环境反馈准确性；\n4、熟练使用Python、PyTorch等语言及工具，具备快速阅读和复现论文的能力，熟悉Agentic Workflow；\n5、具备强烈的数据敏感度与技术热情，拥有优秀的跨团队（模型、评测）协作与沟通能力。","description":"课题描述\n课题背景：\n随着大模型Agent能力的快速演进，Agent场景下的多轮交互、长链路规划及工具调用对后训练（SFT+RL）阶段的数据质量与多样性提出了极高要求。团队当前正深度打造混元大模型的Agent能力，支持OpenClaw、QClaw等面向真实用户的智能体产品，这些场景对模型的工具调用准确性、长链路任务规划能力及探索效率有极高的落地标准。当前Agent训练数据在复杂轨迹覆盖、探索效率、任务多样性等方面面临诸多挑战，本课题旨在通过研究高效的Agent数据生产、自动化质检与评测驱动的数据飞轮机制，持续提升产品级Agent核心能力、降低数据迭代成本、加速技术从研究到产品的闭环落地过程。\n\n课题挑战：\n1、Agent轨迹/环境生产与质检：基于多智能体博弈与复杂轨迹生成技术，研究面向Agent场景的高质量数据自动化生产方案，并设计自动化质检与定向修复算法，确保数据在多轮交互一致性、工具调用准确性、思维链质量等维度达到高标准；\n2、评测驱动的数据飞轮机制：设计科学的Agent能力自动化评测方案，通过深度剖析模型在探索效率、工具使用、长链路规划等实际任务中的弱项，构建\"评测发现问题—数据定向强化—效果闭环提升\"的数据飞轮，实现模型能力的持续迭代优化； \n3、前沿数据技术追踪与转化：持续跟踪Agent数据合成、复杂轨迹构建、多模态与多智能体互动等前沿方向，结合业务实际提出优化方案，将研究成果转化为可落地的业务价值。\n\n具体工作： \nAgent场景下SFT、RL复杂轨迹/环境的数据合成与自动化质检；Agent能力的自动化评测能力与数据飞轮；Agent RL数据的前沿方向研究与在Openclaw、Qclaw等核心场景的落地。\n\n课题要求\n1、计算机科学、人工智能等相关专业硕士及以上学历；\n2、熟悉大语言模型训练原理（Transformer架构、RLHF、LLM Alignment等），拥有大模型数据工程或模型训练实际项目经验，在顶会（NeurIPS、ICLR、ICML、ACL等）发表论文或在开源社区有高影响力贡献者优先；\n3、深入实践过ReAct、Reflexion等前沿Agent推理框架，能够系统性优化Agent思维链质量、工具调用鲁棒性及环境反馈准确性；\n4、熟练使用Python、PyTorch等语言及工具，具备快速阅读和复现论文的能力，熟悉Agentic Workflow；\n5、具备强烈的数据敏感度与技术热情，拥有优秀的跨团队（模型、评测）协作与沟通能力。\n\nTEG\n技术工程事业群\n\n腾讯混元AI Data部\nAI Data部是驱动大模型能力进化的核心引擎。我们专注于打造前沿的数据生态和评测体系，构建覆盖从评测优化、数据获取、智能清洗、精细标注、AI驱动合成、实验模拟以及严苛质检的全链路智能数据系统，确保为大模型的预训练、微调和实际应用注入顶尖品质的数据燃料。通过创新评测框架，我们不断引领模型性能的突破性优化。如果你热衷于AI前沿，加入我们，一起定义下一个智能时代！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1244039890011040768","sourceKey":"tencent","company":"腾讯","title":"技术研究-基础架构方向","city":"北京","category":"技术","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1244039890011040768","duty":"1、参与基础设施（网络、存储、数据库）的设计、开发和优化；\n2、学习和运用相关技术，例如：虚拟化、容器、分布式系统、微服务架构等。参与解决大规模分布式系统中的技术难题，提升产品的性能、稳定性和可扩展性；\n3、与团队成员紧密合作，共同完成产品迭代和项目交付。","requirements":"1、计算机科学、软件工程、电子信息等相关专业本科及以上学历；\n2、熟练掌握数据结构、算法、操作系统、计算机网络等计算机基础知识；\n3、熟练掌握至少一门编程语言，例如：C/C++、Java、Python、Go等；\n4、具备强烈的学习意愿和能力，能够快速掌握新技术；\n5、具备良好的沟通能力和团队合作精神，能够积极主动地解决问题。","description":"对一个研究者来说，\n丰富的应用场景、全谱领域的技术积累、追求极致的氛围都很重要，\n而你正是其中一员！\n\n岗位描述\n1、参与基础设施（网络、存储、数据库）的设计、开发和优化；\n2、学习和运用相关技术，例如：虚拟化、容器、分布式系统、微服务架构等。参与解决大规模分布式系统中的技术难题，提升产品的性能、稳定性和可扩展性；\n3、与团队成员紧密合作，共同完成产品迭代和项目交付。\n\n岗位要求\n1、计算机科学、软件工程、电子信息等相关专业本科及以上学历；\n2、熟练掌握数据结构、算法、操作系统、计算机网络等计算机基础知识；\n3、熟练掌握至少一门编程语言，例如：C/C++、Java、Python、Go等；\n4、具备强烈的学习意愿和能力，能够快速掌握新技术；\n5、具备良好的沟通能力和团队合作精神，能够积极主动地解决问题。\n\n加分项或注意事项\n1、有云计算相关项目经验或实习经历；\n2、熟悉主流云计算平台的使用；\n3、熟悉开源项目并有相关贡献。\n\n1、有云计算相关项目经验或实习经历；\n2、熟悉主流云计算平台的使用；\n3、熟悉开源项目并有相关贡献。\n\nCSIG\n云与智慧产业事业群\n\n腾讯云-技术与产品方向\n腾讯云是腾讯倾力打造的云服务品牌，为客户提供先进的云产品与云服务。依托各地的数据中心，我们将云计算、大数据、人工智能、物联网、安全等先进技术与智慧产业业务场景相结合，面向互联网、金融、政务、医疗、教育、交通出行、智慧零售、工业、消费电子、能源、建筑、农文旅、运营商、传媒等行业打造全面的智慧行业解决方案。目前，腾讯云在助力产业数字化方面取得了丰富的实践经验，为众多优秀的企业提供领先的产品和服务，助力实现数字化升级。欢迎加入，与我们一起“产业智变，云启未来”！  \n\n「技术及产品方向」包括——数据库、大数据、音视频、计算、存储、网络、云智能、腾讯企点、企业中台SaaS等。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1246578010254242816","sourceKey":"tencent","company":"腾讯","title":"游戏美术生成式AI的Infra技术-超大规模训练和推理性能优化","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1246578010254242816","duty":"课题背景：\n当前，游戏领域的生成式 AI 已广泛应用于 3D 模型生成、动画生成、世界模型等多个业务场景。随着相关模型规模持续扩大、业务落地需求不断增强，训练与推理环节对计算框架、算子优化、系统适配和性能调优提出了更高要求。与此同时，面对多种模型架构与多种算力卡型并存的现实情况，需要在性能、成本与适配效率之间进行系统性权衡与优化。总体来看，大模型训练与推理优化能力正逐步成为企业构建生成式 AI 基础设施的关键能力，亟需提前开展前瞻性研究与布局。\n\n课题价值：\n通过开展训练与推理优化技术研究，可有效降低模型训练和部署成本，缩短业务上线周期，逐步形成面向“游戏工作流”的通用基础设施能力，提升内容生产效率与线上生成能力。\n同时，业务场景的多样性与算力硬件的多样性，使推理加速方案在实际落地中面临“灵活适配”与“统一抽象”之间的平衡问题。围绕该方向开展体系化研究，有助于提升技术复用性、工程稳定性与整体资源利用效率。\n\n课题挑战：\n1、游戏生成链路通常包含多模态、多阶段 Pipeline（文本→点云→图片→几何表示→动画→渲染/仿真），算子类型复杂，涉及大量稀疏计算、不规则访存与动态图形状，性能瓶颈难以通过通用优化方法全面覆盖；\n2、训练侧更强调吞吐率与扩展性，推理侧更强调低时延与高并发，且业务对生成质量要求较高，导致训推一体化和端到端优化难度较大；\n3、多模型、多硬件平台并存，使得底层框架、算子实现、并行策略和部署方案需要进行持续适配，给系统的统一性、可维护性和迭代效率带来挑战。","requirements":"编程能力：\n熟练掌握 Python / C++，具备良好的工程实现能力；熟悉 Triton、CUDA 等者优先。\n\n技术要求：\n满足以下任意一项或多项条件：\n1、熟悉大模型训练框架DeepSpeed/Accelerate或推理框架Vllm/Sglang，有多机多卡训练或推理加速相关经验；\n2、了解算子优化、显存优化、并行训练、低精度推理等常见优化方法，有实际项目经验者优先；\n3、有多模态模型、生成式模型或游戏相关 AI 应用的训练与部署经验者优先。","description":"课题描述\n课题背景：\n当前，游戏领域的生成式 AI 已广泛应用于 3D 模型生成、动画生成、世界模型等多个业务场景。随着相关模型规模持续扩大、业务落地需求不断增强，训练与推理环节对计算框架、算子优化、系统适配和性能调优提出了更高要求。与此同时，面对多种模型架构与多种算力卡型并存的现实情况，需要在性能、成本与适配效率之间进行系统性权衡与优化。总体来看，大模型训练与推理优化能力正逐步成为企业构建生成式 AI 基础设施的关键能力，亟需提前开展前瞻性研究与布局。\n\n课题价值：\n通过开展训练与推理优化技术研究，可有效降低模型训练和部署成本，缩短业务上线周期，逐步形成面向“游戏工作流”的通用基础设施能力，提升内容生产效率与线上生成能力。\n同时，业务场景的多样性与算力硬件的多样性，使推理加速方案在实际落地中面临“灵活适配”与“统一抽象”之间的平衡问题。围绕该方向开展体系化研究，有助于提升技术复用性、工程稳定性与整体资源利用效率。\n\n课题挑战：\n1、游戏生成链路通常包含多模态、多阶段 Pipeline（文本→点云→图片→几何表示→动画→渲染/仿真），算子类型复杂，涉及大量稀疏计算、不规则访存与动态图形状，性能瓶颈难以通过通用优化方法全面覆盖；\n2、训练侧更强调吞吐率与扩展性，推理侧更强调低时延与高并发，且业务对生成质量要求较高，导致训推一体化和端到端优化难度较大；\n3、多模型、多硬件平台并存，使得底层框架、算子实现、并行策略和部署方案需要进行持续适配，给系统的统一性、可维护性和迭代效率带来挑战。\n\n课题要求\n编程能力：\n熟练掌握 Python / C++，具备良好的工程实现能力；熟悉 Triton、CUDA 等者优先。\n\n技术要求：\n满足以下任意一项或多项条件：\n1、熟悉大模型训练框架DeepSpeed/Accelerate或推理框架Vllm/Sglang，有多机多卡训练或推理加速相关经验；\n2、了解算子优化、显存优化、并行训练、低精度推理等常见优化方法，有实际项目经验者优先；\n3、有多模态模型、生成式模型或游戏相关 AI 应用的训练与部署经验者优先。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1246578010254242817","sourceKey":"tencent","company":"腾讯","title":"世界模型编辑器-3DGS游戏引擎研发","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1246578010254242817","duty":"课题背景：\n3DGS（3D Gaussian Splatting，三维高斯溅射/泼溅）是2023年提出的一种革命性三维场景表示与实时渲染技术，具有渲染性能极高、场景生成友善等特点。2025年world lab也推出了基于3DGS的世界模型。然后，世界模型目前不具备可二次编辑创作性，同时尚缺乏光照、阴影、碰撞、动画、物理特性等必要性特性，以及与传统mesh的成熟渲染方式的混合渲染。全面结合可以通过UE引擎进行混合渲染，之后才能具备有可塑性、可娱乐性及拓展至机器人、自动驾驶等相关领域。\n\n课题挑战：\n1、3DGS场景的语义识别及分割，可以识别物体对其中的3DGS物体进行提取；\n2、AI增强，物体分割之后会有画质模糊，物体残缺等问题，通过AI扩散模型进行AI增强，达到游戏工业级画质；\n3、cuda 3dgs渲染与游戏mesh的在游戏引擎中的混合渲染，需要解决性能、relight、动画等相关难题；\n4、3DGS压缩：LOD，高品质的压缩技术，减少存储空间。\n\n具体工作：\n你将参与到世界模型编辑器的相关课题难题的研究工作中，包括语义识别，AI增强，混合渲染，物理GS，4DGS，UE引擎混合渲染等挑战性工作中。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握计算机视觉和图像处理相关的基本算法及应用，熟悉caffe、tensorflow，pytorch等至少一个深度学习框架；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言；\n4、在研究生及博士生期间，有非常深入的与3DGS的研究工作，至少有一篇顶级期刊的一作或者二作以上的论文。","description":"课题描述\n课题背景：\n3DGS（3D Gaussian Splatting，三维高斯溅射/泼溅）是2023年提出的一种革命性三维场景表示与实时渲染技术，具有渲染性能极高、场景生成友善等特点。2025年world lab也推出了基于3DGS的世界模型。然后，世界模型目前不具备可二次编辑创作性，同时尚缺乏光照、阴影、碰撞、动画、物理特性等必要性特性，以及与传统mesh的成熟渲染方式的混合渲染。全面结合可以通过UE引擎进行混合渲染，之后才能具备有可塑性、可娱乐性及拓展至机器人、自动驾驶等相关领域。\n\n课题挑战：\n1、3DGS场景的语义识别及分割，可以识别物体对其中的3DGS物体进行提取；\n2、AI增强，物体分割之后会有画质模糊，物体残缺等问题，通过AI扩散模型进行AI增强，达到游戏工业级画质；\n3、cuda 3dgs渲染与游戏mesh的在游戏引擎中的混合渲染，需要解决性能、relight、动画等相关难题；\n4、3DGS压缩：LOD，高品质的压缩技术，减少存储空间。\n\n具体工作：\n你将参与到世界模型编辑器的相关课题难题的研究工作中，包括语义识别，AI增强，混合渲染，物理GS，4DGS，UE引擎混合渲染等挑战性工作中。\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握计算机视觉和图像处理相关的基本算法及应用，熟悉caffe、tensorflow，pytorch等至少一个深度学习框架；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言；\n4、在研究生及博士生期间，有非常深入的与3DGS的研究工作，至少有一篇顶级期刊的一作或者二作以上的论文。\n\nIEG\n互动娱乐事业群\n\n云互动创新科技\n云互动创新科技，探索科技与游戏的无限可能，专注于智能硬件与云游戏两大前沿创新业务，致力于将尖端科技与游戏内容完美结合，开创前所未有的游戏互动体验。在这里，你将与行业领袖并肩，共同探索创新游戏玩法，构建全新的游戏互动生态系统。\n\n我们聚集了在网络通讯、音视频处理、流媒体技术、图形渲染、云计算、人工智能、智能硬件等领域的全球科技人才，如果你渴望在游戏技术的最前沿留下你的印记，渴望与这些顶尖大牛一起共舞，渴望在一个充满挑战与机遇的环境中成长，那么这里就是你的舞台。欢迎意向前沿技术研究、软硬件交互技术、游戏开发、游戏引擎、游戏产品等方向的同学加入我们，让我们携手共创游戏科技的新纪元。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1246578010254242818","sourceKey":"tencent","company":"腾讯","title":"腾讯游戏-游戏通用智能体算法研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1246578010254242818","duty":"课题背景：\n游戏正成为多模态智能体的重要验证环境。以SIMA2等工作为代表，业界开始探索智能体在3D虚拟场景中的感知、理解、规划与操作能力。VLA框架为统一建模游戏中的视觉感知、语言理解与动作控制提供了新路径，但在真实游戏场景落地中仍面临实时性不足、长短期任务难统一建模、指令遵循不稳定、跨游戏泛化能力弱等问题。\n\n课题内容及挑战：\n本课题聚焦面向游戏的实时通用智能体，研究适用于复杂交互场景的统一模型与框架，重点提升模型的低时延决策、长程任务执行、自然语言指令遵循和跨游戏迁移能力，探索可在多种游戏中复用的实时决策机制，形成兼顾响应速度、任务完成度、控制稳定性与泛化表现的通用游戏智能体原型。\n\n研究方向\n包括但不限于：\n1、实时通用游戏智能体模型与框架；\n2、面向跨游戏迁移的游戏基础模型；\n3、结合世界模型的实时规划与交互方法；\n4、面向通用游戏智能体的Benchmark构建。","requirements":"1、人工智能、计算机科学、数学或相关专业，硕士及以上学历，博士优先；有顶会一作论文或知名开源项目优先；\n2、熟练掌握主流深度学习框架，具备扎实的编程能力和工程实现能力，能够独立完成前沿论文复现、优化与落地；\n\n具备以下任一方向经验者优先：\n1、具身智能方向：对VLA、WAM等相关技术有较深入理解，具备感知、决策、动作一体化建模相关研究或实践经验；\n2、模型训练方向：具备大规模预训练、微调或后训练经验，有多模态大模型相关训练、优化或应用经验；\n3、强化学习方向：具备强化学习、模仿学习、基于模型的规划或决策优化相关研究或实践经验；\n4、具备较强的研究能力，有高质量论文发表或开源项目经验者优先；对游戏Agent、具身智能、世界模型、强化学习等方向有浓厚兴趣，具备良好的研究推进能力和沟通协作能力；\n5、加分项：热爱游戏行业，熟悉多类型游戏。","description":"课题描述\n课题背景：\n游戏正成为多模态智能体的重要验证环境。以SIMA2等工作为代表，业界开始探索智能体在3D虚拟场景中的感知、理解、规划与操作能力。VLA框架为统一建模游戏中的视觉感知、语言理解与动作控制提供了新路径，但在真实游戏场景落地中仍面临实时性不足、长短期任务难统一建模、指令遵循不稳定、跨游戏泛化能力弱等问题。\n\n课题内容及挑战：\n本课题聚焦面向游戏的实时通用智能体，研究适用于复杂交互场景的统一模型与框架，重点提升模型的低时延决策、长程任务执行、自然语言指令遵循和跨游戏迁移能力，探索可在多种游戏中复用的实时决策机制，形成兼顾响应速度、任务完成度、控制稳定性与泛化表现的通用游戏智能体原型。\n\n研究方向\n包括但不限于：\n1、实时通用游戏智能体模型与框架；\n2、面向跨游戏迁移的游戏基础模型；\n3、结合世界模型的实时规划与交互方法；\n4、面向通用游戏智能体的Benchmark构建。\n\n课题要求\n1、人工智能、计算机科学、数学或相关专业，硕士及以上学历，博士优先；有顶会一作论文或知名开源项目优先；\n2、熟练掌握主流深度学习框架，具备扎实的编程能力和工程实现能力，能够独立完成前沿论文复现、优化与落地；\n\n具备以下任一方向经验者优先：\n1、具身智能方向：对VLA、WAM等相关技术有较深入理解，具备感知、决策、动作一体化建模相关研究或实践经验；\n2、模型训练方向：具备大规模预训练、微调或后训练经验，有多模态大模型相关训练、优化或应用经验；\n3、强化学习方向：具备强化学习、模仿学习、基于模型的规划或决策优化相关研究或实践经验；\n4、具备较强的研究能力，有高质量论文发表或开源项目经验者优先；对游戏Agent、具身智能、世界模型、强化学习等方向有浓厚兴趣，具备良好的研究推进能力和沟通协作能力；\n5、加分项：热爱游戏行业，熟悉多类型游戏。\n\nIEG\n互动娱乐事业群\n\n游戏品质管理\n腾讯游戏品质管理，致力于结合未来科技走向，推动互联网产品品质提升和科技应用。 我们深耕品质管理专业能力，建设业内顶级适配/性能/安全/数值等专项测试技术，支持《王者荣耀》、《和平精英》等全球知名游戏，为腾讯游戏保驾护航；搭建行业领先的质量云服务平台「WeTest」及性能分析专家「Perfdog」，服务全球数百万开发者，多次赢得国际国内权威机构认证；建设基于AI技术的「Turing Lab」，积极布局视觉AI、虚实互动等尖端科技，与北大、剑桥等研究机构紧密合作，在CVPR、NeurIPS等顶会发表论文；建设游戏测评平台「游测前线」，携手全球玩家为游戏工作室提供策略支持。 \n加入我们，在品质管理的辽阔天空集结，发现游戏的更多可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1246578010254242819","sourceKey":"tencent","company":"腾讯","title":"腾讯会议端云协同语音大模型研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1246578010254242819","duty":"课题背景：\n随着会议字幕、纪要、问答等能力不断升级，会议语音理解正从单点识别走向端云协同的综合智能。会议场景具有多说话人、远场、长时连续输入等特点，单纯依赖云端或端侧都存在局限，因此需要研究端侧感知、预处理、轻量理解与云端深度推理协同的大模型方案。\n\n课题挑战：\n会议场景中存在连续长音频、多说话人、交叉发言、多语种、多方言及复杂噪声环境，端侧还受到算力、功耗、时延限制。如何合理划分端云职责，在端侧完成低时延感知、信息压缩与关键特征提取，并与云端深层语义理解、多模态融合高效协同，是本课题核心挑战。\n\n具体工作：\n围绕腾讯会议实时字幕、流式纪要、离线总结、录音文件和多语种内容理解等业务，研究端云协同的会议语音理解方案。重点开展端侧低时延前处理、轻量化表征编码、说话人及场景信息建模、关键信息上云策略，以及端云联合优化机制，持续提升整体理解效果与用户体验。","requirements":"1、在语音识别、语音增强、说话人识别、多模态学习、大模型、端侧推理、模型压缩或端云协同等方向有较强研究基础，有相关论文发表者优先；\n2、熟悉 PyTorch 等深度学习框架，具备较强的算法实现与实验能力；有音频、语音、大模型训练优化或端侧部署经验者优先；\n3、对会议语音理解和智能会议场景有浓厚兴趣，具备较强的问题分析能力、创新意识和团队协作能力，能够推动科研成果向实际业务落地转化。","description":"课题描述\n课题背景：\n随着会议字幕、纪要、问答等能力不断升级，会议语音理解正从单点识别走向端云协同的综合智能。会议场景具有多说话人、远场、长时连续输入等特点，单纯依赖云端或端侧都存在局限，因此需要研究端侧感知、预处理、轻量理解与云端深度推理协同的大模型方案。\n\n课题挑战：\n会议场景中存在连续长音频、多说话人、交叉发言、多语种、多方言及复杂噪声环境，端侧还受到算力、功耗、时延限制。如何合理划分端云职责，在端侧完成低时延感知、信息压缩与关键特征提取，并与云端深层语义理解、多模态融合高效协同，是本课题核心挑战。\n\n具体工作：\n围绕腾讯会议实时字幕、流式纪要、离线总结、录音文件和多语种内容理解等业务，研究端云协同的会议语音理解方案。重点开展端侧低时延前处理、轻量化表征编码、说话人及场景信息建模、关键信息上云策略，以及端云联合优化机制，持续提升整体理解效果与用户体验。\n\n课题要求\n1、在语音识别、语音增强、说话人识别、多模态学习、大模型、端侧推理、模型压缩或端云协同等方向有较强研究基础，有相关论文发表者优先；\n2、熟悉 PyTorch 等深度学习框架，具备较强的算法实现与实验能力；有音频、语音、大模型训练优化或端侧部署经验者优先；\n3、对会议语音理解和智能会议场景有浓厚兴趣，具备较强的问题分析能力、创新意识和团队协作能力，能够推动科研成果向实际业务落地转化。\n\nCSIG\n云与智慧产业事业群\n\n腾讯会议\n腾讯会议是腾讯云旗下的一站式音视频协作平台，依托腾讯20余年音视频技术积累，提供高清流畅、安全可靠的会议体验，支持跨企业/跨区域高效协作，服务覆盖全球220+国家地区，累计服务超4亿用户。核心产品包括视频会议、Rooms会议室解决方案等。产品诸多AI能力获得了广大用户的认可，如元宝实时总结纪要、还原真实氛围，AI托管实现分身有术、关键会议永远在场等，近1年AI功能用户量同比增长150%+。现在腾讯会议已成为各行业500强及广大企业的首选协作工具。加入我们，一起打造AI时代极致的会议体验！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1271996654375354368","sourceKey":"tencent","company":"腾讯","title":"医疗大模型的相关研究","city":"上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1271996654375354368","duty":"近年来，大语言模型（LLM）与多模态大模型（MLLM）技术快速发展，在自然语言处理（NLP）领域，LLM 已在文本翻译、阅读理解等任务中确立了新的 SOTA 标准；与此同时， MLLM 通过引入视觉等编码器，实现了跨模态的语义对齐，在图文问答、视觉推理等复合任务中同样取得了突破性进展。\n\n这些技术正在全面赋能医学领域：\n一方面，LLM 广泛应用于以文本为核心的场景，如智能医患对话、病历信息提取、临床指南检索及出院报告生成，已展现出通过医师资格考试的专业知识储备；\n另一方面，MLLM 则深入到了以影像和信号为核心的诊疗环节，能够对 CT/MRI 影像、病理切片以及心电信号进行精准解读，辅助医生完成从视觉特征到临床结论的推理。\n\n当前正在推进这两类技术在医学场景下的落地，无论是基于文本的逻辑推理，还是基于多模态数据的综合研判，都已成为智慧医疗的重要支柱。\n\n基于大语言模型（LLM）和多模态大语言模型（MLLM）的技术特性，在医疗健康领域有三方面的价值：\n\n1、赋能患者端的普惠服务：提升医疗可及性与公平性（社会价值）\n利用 LLM 强大的自然语言理解与共情能力，能够为患者提供全天候的智能预问诊、用药咨询及慢病管理服务。这不仅打破了复杂的医学专业术语壁垒，降低了患者获取高质量医疗信息的门槛，还有效缓解了医疗资源地域分布不均的问题，极大地促进了社会医疗资源的公平普惠；\n\n2、助力医生端的增效提质：确立多模态诊疗的新技术标杆（技术领先）\n通过 MLLM 对医学影像（CT/MRI）、生理信号及临床文本等异构数据的深度融合与跨模态推理，提升模型在辅助诊断、病理分析及自动化报告生成等任务上的能力。这不仅能为医生提供精准的临床决策支持，降低误诊漏诊率，还能大幅减少文书撰写等重复性工作，让医生回归诊疗核心，显著提升临床效率；\n\n3、驱动医疗体系的范式变革：缓解资源矛盾与推动科研创新（综合价值）\n大模型技术的应用推动了医疗服务从“人力密集型”向“人机协同型”的范式转变。它不仅在宏观上有效应对了老龄化社会带来的医疗资源供需矛盾，实现了医疗系统的降本增效；同时，模型在处理海量医学数据中涌现出的新知识发现能力，也为医学科研探索提供了新的工具与方向。","requirements":"1、克服“幻觉”现象与提升事实一致性\n医疗领域具有极低的容错率，模型生成内容中的事实性错误（即“幻觉”）可能导致严重的医疗事故。当前的主要挑战在于如何抑制模型生成看似合理但毫无依据的诊断建议或虚假文献；如何引入知识增强（RAG）与事实核查机制，确保模型的输出严格基于循证医学证据，实现从“概率生成”到“可信推理”的转变。\n\n2、增强复杂临床推理与跨模态语义对齐（能力挑战）\n医疗诊疗不是简单的问答，而是基于多源信息的复杂逻辑推理过程。\n对于LLM： 挑战在于如何提升模型在长文本病历中的因果推理能力，使其能够像医生一样处理时序错综复杂的病情演变。\n对于MLLM： 挑战在于解决跨模态语义鸿沟，即如何实现医学影像（像素特征）与临床文本（语义特征）的精准对齐（Alignment），确保模型能准确识别微小的病灶特征并将其转化为准确的文本描述，而非产生图文不符的描述。\n\n3、解决领域适配、可解释性与数据隐私难题（落地挑战）\n通用大模型缺乏特定专科的深度知识（如罕见病、特定术式），面临着领域微调（Fine-tuning）中灾难性遗忘的风险。此外，医疗决策需要高度的可解释性（即模型不仅要给出结论，还要给出推导过程），“黑盒”模型难以获得医生信任。同时，如何在保护患者隐私数据（HIPAA合规）的前提下，利用高质量、小样本的医疗数据高效训练模型，也是亟待攻克的技术壁垒。","description":"课题描述\n近年来，大语言模型（LLM）与多模态大模型（MLLM）技术快速发展，在自然语言处理（NLP）领域，LLM 已在文本翻译、阅读理解等任务中确立了新的 SOTA 标准；与此同时， MLLM 通过引入视觉等编码器，实现了跨模态的语义对齐，在图文问答、视觉推理等复合任务中同样取得了突破性进展。\n\n这些技术正在全面赋能医学领域：\n一方面，LLM 广泛应用于以文本为核心的场景，如智能医患对话、病历信息提取、临床指南检索及出院报告生成，已展现出通过医师资格考试的专业知识储备；\n另一方面，MLLM 则深入到了以影像和信号为核心的诊疗环节，能够对 CT/MRI 影像、病理切片以及心电信号进行精准解读，辅助医生完成从视觉特征到临床结论的推理。\n\n当前正在推进这两类技术在医学场景下的落地，无论是基于文本的逻辑推理，还是基于多模态数据的综合研判，都已成为智慧医疗的重要支柱。\n\n基于大语言模型（LLM）和多模态大语言模型（MLLM）的技术特性，在医疗健康领域有三方面的价值：\n\n1、赋能患者端的普惠服务：提升医疗可及性与公平性（社会价值）\n利用 LLM 强大的自然语言理解与共情能力，能够为患者提供全天候的智能预问诊、用药咨询及慢病管理服务。这不仅打破了复杂的医学专业术语壁垒，降低了患者获取高质量医疗信息的门槛，还有效缓解了医疗资源地域分布不均的问题，极大地促进了社会医疗资源的公平普惠；\n\n2、助力医生端的增效提质：确立多模态诊疗的新技术标杆（技术领先）\n通过 MLLM 对医学影像（CT/MRI）、生理信号及临床文本等异构数据的深度融合与跨模态推理，提升模型在辅助诊断、病理分析及自动化报告生成等任务上的能力。这不仅能为医生提供精准的临床决策支持，降低误诊漏诊率，还能大幅减少文书撰写等重复性工作，让医生回归诊疗核心，显著提升临床效率；\n\n3、驱动医疗体系的范式变革：缓解资源矛盾与推动科研创新（综合价值）\n大模型技术的应用推动了医疗服务从“人力密集型”向“人机协同型”的范式转变。它不仅在宏观上有效应对了老龄化社会带来的医疗资源供需矛盾，实现了医疗系统的降本增效；同时，模型在处理海量医学数据中涌现出的新知识发现能力，也为医学科研探索提供了新的工具与方向。\n\n课题要求\n1、克服“幻觉”现象与提升事实一致性\n医疗领域具有极低的容错率，模型生成内容中的事实性错误（即“幻觉”）可能导致严重的医疗事故。当前的主要挑战在于如何抑制模型生成看似合理但毫无依据的诊断建议或虚假文献；如何引入知识增强（RAG）与事实核查机制，确保模型的输出严格基于循证医学证据，实现从“概率生成”到“可信推理”的转变。\n\n2、增强复杂临床推理与跨模态语义对齐（能力挑战）\n医疗诊疗不是简单的问答，而是基于多源信息的复杂逻辑推理过程。\n对于LLM： 挑战在于如何提升模型在长文本病历中的因果推理能力，使其能够像医生一样处理时序错综复杂的病情演变。\n对于MLLM： 挑战在于解决跨模态语义鸿沟，即如何实现医学影像（像素特征）与临床文本（语义特征）的精准对齐（Alignment），确保模型能准确识别微小的病灶特征并将其转化为准确的文本描述，而非产生图文不符的描述。\n\n3、解决领域适配、可解释性与数据隐私难题（落地挑战）\n通用大模型缺乏特定专科的深度知识（如罕见病、特定术式），面临着领域微调（Fine-tuning）中灾难性遗忘的风险。此外，医疗决策需要高度的可解释性（即模型不仅要给出结论，还要给出推导过程），“黑盒”模型难以获得医生信任。同时，如何在保护患者隐私数据（HIPAA合规）的前提下，利用高质量、小样本的医疗数据高效训练模型，也是亟待攻克的技术壁垒。\n\nCSIG\n云与智慧产业事业群\n\n腾讯健康\n腾讯健康一直践行\"科技助医，互联为健\"，用科技守护百姓健康，推动社会价值持续创新。一方面，以\"腾讯健康\"小程序为载体，助力个人，打通资讯、挂号、问诊、购药、支付等健康服务环节，实现线上线下一体化的医疗健康服务；腾讯健康药箱化身家庭\"用药助手\"，帮助用户便捷管理家庭成员的用药并建立健康档案，提醒用药不遗漏；微信医保服务依托医保码和微信基础能力，让全国13亿参保人通过微信就能随时进行医保查询、办理、支付报销，就医购药更便捷，更省心；腾讯医典作为权威医学科普平台，携手海量专业医生与机构，为大众提供看得懂、可信赖的健康知识科普。 另一方面，通过数字化解决方案助力政府、医院、医疗机构、医药企业的智慧升级，依托\"数字运河\"打通医疗数据要素的汇聚、治理与流通，为医疗机构和区域医疗建设坚实的技术底座；推出医疗健康行业\"AI Agent全栈解决方案\"，覆盖从底层模型、智能体开发平台到上层应用的全链路能力，助力医院与医药企业加速智能化转型。医行无疆，科技向善，加入我们，一起用科技力量传递腾讯温度！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1274356458519403520","sourceKey":"tencent","company":"腾讯","title":"腾讯营销-广告推荐系统经验驱动的自进化 AutoResearch 研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1274356458519403520","duty":"课题背景：广告推荐系统的持续迭代长期依赖算法工程师手工完成特征挖掘、模型设计与实验验证，周期长、成本高、强依赖个人经验，且工程师的宝贵试错经验难以结构化沉淀与复用。随着大模型与智能体（Agent）能力快速提升，让 AI 自动完成\"提出想法→编码实现→离在线验证→复盘迭代\"的研发闭环成为可能。本课题旨在构建以经验记忆为核心、可自进化的广告推荐 AutoResearch 系统，让每一次实验的成功与失败都沉淀为可复用的经验，把工程师从重复实验中解放出来，持续加速推荐效果与研发效率的提升。\n当前挑战：一是离在线不一致：受限于广告系统的成本与安全约束，自进化闭环只能依赖离线实验做评估与筛选，而离线指标与线上真实收益往往存在 gap（分布偏移、反馈缺失、样本选择偏差等）。一旦离线判断与线上不一致，系统就会在错误信号上持续迭代、越优化越偏。如何构建高保真、可信赖的离线评估与代理指标，让离线增益能稳定映射到线上收益，是本课题最关键的难点。二是记忆设计与经验沉淀：海量成功/失败实验轨迹如何提炼为可检索、可迁移的经验记忆，抑制重复无效探索，并克服记忆漂移、冲突、过期与\"留存即噪声、压缩即丢信息\"的两难。三是闭环 Harness 的自进化：如何让研究流程、工具链与搜索策略自身可被自动改写与迭代，且在自我修改中稳定收敛、不退化。四是长期迭代能否真正持续变强：避免系统只在固定离线评测上\"刷分\"、陷入局部最优或因分布漂移而旧经验失效，让能力真正逐轮累积而非停滞或自欺。\n\n工作内容：\n1. 在既有广告推荐 AutoResearch 闭环基础上做优化：重点研究高保真离线代理指标，融合排序（GAUC）、校准（PCOC）与反事实价值估计（OPE），并用历史线上 A/B 结果校准其权重、最大化与线上收益的排序相关性，缩小离在线 gap。\n2. 改进经验记忆的沉淀、检索与跨任务复用，抑制重复无效探索。\n3. 并优化 Harness 自进化机制的稳定性与迭代效率，在真实广告场景中验证效果增益。\n4. 跟踪国际顶级学术会议与业界生成式推荐最新进展，形成技术路线与专利布局，产出高水平学术论文与技术报告。","requirements":"1、计算机相关专业硕士及以上学历，具有扎实的计算机和机器学习基础，拥有优秀的编程能力和工程能力，学习能力强，具备良好的团队协作意识和主动性；\n2、在搜广推系统、生成式AI、机器学习等一个或多个领域有较深入的研究，包括但不限于判别式推荐、生成式推荐、LLM/MLLM、图像生成/编辑、视频生成/编辑；\n3、具有较强的实践能力，在国际学术会议发表过论文或者有竞赛经验者优先。","description":"课题描述\n课题背景：广告推荐系统的持续迭代长期依赖算法工程师手工完成特征挖掘、模型设计与实验验证，周期长、成本高、强依赖个人经验，且工程师的宝贵试错经验难以结构化沉淀与复用。随着大模型与智能体（Agent）能力快速提升，让 AI 自动完成\"提出想法→编码实现→离在线验证→复盘迭代\"的研发闭环成为可能。本课题旨在构建以经验记忆为核心、可自进化的广告推荐 AutoResearch 系统，让每一次实验的成功与失败都沉淀为可复用的经验，把工程师从重复实验中解放出来，持续加速推荐效果与研发效率的提升。\n当前挑战：一是离在线不一致：受限于广告系统的成本与安全约束，自进化闭环只能依赖离线实验做评估与筛选，而离线指标与线上真实收益往往存在 gap（分布偏移、反馈缺失、样本选择偏差等）。一旦离线判断与线上不一致，系统就会在错误信号上持续迭代、越优化越偏。如何构建高保真、可信赖的离线评估与代理指标，让离线增益能稳定映射到线上收益，是本课题最关键的难点。二是记忆设计与经验沉淀：海量成功/失败实验轨迹如何提炼为可检索、可迁移的经验记忆，抑制重复无效探索，并克服记忆漂移、冲突、过期与\"留存即噪声、压缩即丢信息\"的两难。三是闭环 Harness 的自进化：如何让研究流程、工具链与搜索策略自身可被自动改写与迭代，且在自我修改中稳定收敛、不退化。四是长期迭代能否真正持续变强：避免系统只在固定离线评测上\"刷分\"、陷入局部最优或因分布漂移而旧经验失效，让能力真正逐轮累积而非停滞或自欺。\n\n工作内容：\n1. 在既有广告推荐 AutoResearch 闭环基础上做优化：重点研究高保真离线代理指标，融合排序（GAUC）、校准（PCOC）与反事实价值估计（OPE），并用历史线上 A/B 结果校准其权重、最大化与线上收益的排序相关性，缩小离在线 gap。\n2. 改进经验记忆的沉淀、检索与跨任务复用，抑制重复无效探索。\n3. 并优化 Harness 自进化机制的稳定性与迭代效率，在真实广告场景中验证效果增益。\n4. 跟踪国际顶级学术会议与业界生成式推荐最新进展，形成技术路线与专利布局，产出高水平学术论文与技术报告。\n\n课题要求\n1、计算机相关专业硕士及以上学历，具有扎实的计算机和机器学习基础，拥有优秀的编程能力和工程能力，学习能力强，具备良好的团队协作意识和主动性；\n2、在搜广推系统、生成式AI、机器学习等一个或多个领域有较深入的研究，包括但不限于判别式推荐、生成式推荐、LLM/MLLM、图像生成/编辑、视频生成/编辑；\n3、具有较强的实践能力，在国际学术会议发表过论文或者有竞赛经验者优先。\n\nCDG\n企业发展事业群\n\n腾讯营销\n腾讯营销作为腾讯⾯向企业统⼀的商业服务平台，基于腾讯坚实的技术实力，整合微信、QQ、腾讯新闻、腾讯视频、腾讯音乐等可以触达海量用户的应用场景，将用户与品牌、商品及服务进行高效连接。\n\n同时，我们还致力于为客户提供从营销触达环节，向前后端延伸至整个经营链路的数字化营销解决方案及产品工具，帮助客户实现数字化经营与生意增长。\n\n伴随腾讯业务的稳健成长，腾讯营销持续引领行业创新，实现高质量可持续发展。我们热衷追求满分，所以无比期待与更多能够创造腾讯营销明天的“满分后浪”们，一起上场！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1274356467793009664","sourceKey":"tencent","company":"腾讯","title":"腾讯营销—面向生成式推荐的强化学习优化技术研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1274356467793009664","duty":"课题背景：\n针对工业级商业化推荐系统，结合生成式AI技术构建下一代商业化推荐引擎，并通过强化学习实现持续演进和更新，提升商业化价值天花板\n当前挑战：广告推荐系统是实时在线学习，需要构建有效的实时Reward系统，驱动有效实时 On-Policy 演进机制\n\n\n工作内容：\n1.结合广告推荐优化目标ecpm/gmv，探索并构建生成式推荐下，实时On Policy 强化学习整体算法框架；\n2.探索并设计符合广告优化目标的 Policy机制 与 Reward 系统，驱动推荐 Policy Model 高效探索与更新；\n3. 跟踪国际顶级学术会议与业界生成式推荐最新进展，形成技术路线与专利布局，产出高水平学术论文与技术报告。","requirements":"1、计算机相关专业硕士及以上学历，具有扎实的计算机和机器学习基础，拥有优秀的编程能力和工程能力，学习能力强，具备良好的团队协作意识和主动性；\n2、在搜广推系统、生成式AI、机器学习等一个或多个领域有较深入的研究，包括但不限于判别式推荐、生成式推荐、LLM/MLLM、图像生成/编辑、视频生成/编辑；\n3、具有较强的实践能力，发表过高水平学术会议论文或者有竞赛经验者优先。","description":"课题描述\n课题背景：\n针对工业级商业化推荐系统，结合生成式AI技术构建下一代商业化推荐引擎，并通过强化学习实现持续演进和更新，提升商业化价值天花板\n当前挑战：广告推荐系统是实时在线学习，需要构建有效的实时Reward系统，驱动有效实时 On-Policy 演进机制\n\n\n工作内容：\n1.结合广告推荐优化目标ecpm/gmv，探索并构建生成式推荐下，实时On Policy 强化学习整体算法框架；\n2.探索并设计符合广告优化目标的 Policy机制 与 Reward 系统，驱动推荐 Policy Model 高效探索与更新；\n3. 跟踪国际顶级学术会议与业界生成式推荐最新进展，形成技术路线与专利布局，产出高水平学术论文与技术报告。\n\n课题要求\n1、计算机相关专业硕士及以上学历，具有扎实的计算机和机器学习基础，拥有优秀的编程能力和工程能力，学习能力强，具备良好的团队协作意识和主动性；\n2、在搜广推系统、生成式AI、机器学习等一个或多个领域有较深入的研究，包括但不限于判别式推荐、生成式推荐、LLM/MLLM、图像生成/编辑、视频生成/编辑；\n3、具有较强的实践能力，发表过高水平学术会议论文或者有竞赛经验者优先。\n\nCDG\n企业发展事业群\n\n腾讯营销\n腾讯营销作为腾讯⾯向企业统⼀的商业服务平台，基于腾讯坚实的技术实力，整合微信、QQ、腾讯新闻、腾讯视频、腾讯音乐等可以触达海量用户的应用场景，将用户与品牌、商品及服务进行高效连接。\n\n同时，我们还致力于为客户提供从营销触达环节，向前后端延伸至整个经营链路的数字化营销解决方案及产品工具，帮助客户实现数字化经营与生意增长。\n\n伴随腾讯业务的稳健成长，腾讯营销持续引领行业创新，实现高质量可持续发展。我们热衷追求满分，所以无比期待与更多能够创造腾讯营销明天的“满分后浪”们，一起上场！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1279258990471390208","sourceKey":"tencent","company":"腾讯","title":"腾讯营销—广告推荐模型 Scaling Up（序列和非序列统一建模方向）","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1279258990471390208","duty":"课题背景：当前主流范式将序列建模与非序列特征交互拆分为独立模块，导致信息流动割裂、优化目标分散、工程维护复杂，模型扩展（Scaling）边际收益快速递减。\n而大模型时代的统一骨干架构与缩放定律（Scaling Law） 已在 NLP/CV 领域验证：\n通过统一表示、统一训练、统一推理，可实现模型能力随参数、数据、算力增长而提升。\n本课题面向工业级广告推荐，以序列与非序列统一建模为核心，突破传统分治架构瓶颈，构建具备高效扩展能力的新一代广告推荐模型体系，支撑千亿特征、亿级用户、毫秒级推理的规模化落地，提升广告精准度、平台收益与系统效率。\n\n当前挑战：\n1、工程落地的infra依赖重，广告系统延迟敏感，线上约束严苛；\n2、序列与非序列特征表示异构：行为序列强时序、用户 / 广告 / 上下文高基数稀疏，难以在同一空间对齐与融合。\n\n工作内容：\n1. 负责广告推荐模型的Scaling Up，通过千亿样本、特征，结合模型Dense Scaling Up、超长序列建模和多模态技术，持续推动建模技术的升级突破；\n2. 跟踪国际顶会与业界最新进展，形成技术路线与专利布局，输出高水平学术论文与技术报告；","requirements":"1、硕士研究生及以上学历，计算机科学、人工智能、自然语言处理、多模态等相关领域；\r\n2、对推荐算法和大模型技术有浓厚兴趣，有较好的算法和数据结构基础，有较好的编程能力；\r\n3、拥有扎实的机器学习基础，在深度学习、大语言模型（LLM）、多模态等方向有深入的理解，有推荐研究经历者优先；\r\n4、有国际竞赛经验（包括但不限制于ACM-ICPC、数学建模大赛）或在国际会议发表论文者（包括但不限于KDD、NeurIPS、ICML、ICLR、CVPR等）优先；\r\n5、优秀的分析问题和解决问题的能力，对解决挑战性问题充满激情。","description":"课题描述\n课题背景：当前主流范式将序列建模与非序列特征交互拆分为独立模块，导致信息流动割裂、优化目标分散、工程维护复杂，模型扩展（Scaling）边际收益快速递减。\n而大模型时代的统一骨干架构与缩放定律（Scaling Law） 已在 NLP/CV 领域验证：\n通过统一表示、统一训练、统一推理，可实现模型能力随参数、数据、算力增长而提升。\n本课题面向工业级广告推荐，以序列与非序列统一建模为核心，突破传统分治架构瓶颈，构建具备高效扩展能力的新一代广告推荐模型体系，支撑千亿特征、亿级用户、毫秒级推理的规模化落地，提升广告精准度、平台收益与系统效率。\n\n当前挑战：\n1、工程落地的infra依赖重，广告系统延迟敏感，线上约束严苛；\n2、序列与非序列特征表示异构：行为序列强时序、用户 / 广告 / 上下文高基数稀疏，难以在同一空间对齐与融合。\n\n工作内容：\n1. 负责广告推荐模型的Scaling Up，通过千亿样本、特征，结合模型Dense Scaling Up、超长序列建模和多模态技术，持续推动建模技术的升级突破；\n2. 跟踪国际顶会与业界最新进展，形成技术路线与专利布局，输出高水平学术论文与技术报告；\n\n课题要求\n1、硕士研究生及以上学历，计算机科学、人工智能、自然语言处理、多模态等相关领域；\r\n2、对推荐算法和大模型技术有浓厚兴趣，有较好的算法和数据结构基础，有较好的编程能力；\r\n3、拥有扎实的机器学习基础，在深度学习、大语言模型（LLM）、多模态等方向有深入的理解，有推荐研究经历者优先；\r\n4、有国际竞赛经验（包括但不限制于ACM-ICPC、数学建模大赛）或在国际会议发表论文者（包括但不限于KDD、NeurIPS、ICML、ICLR、CVPR等）优先；\r\n5、优秀的分析问题和解决问题的能力，对解决挑战性问题充满激情。\n\nCDG\n企业发展事业群\n\n腾讯营销\n腾讯营销作为腾讯⾯向企业统⼀的商业服务平台，基于腾讯坚实的技术实力，整合微信、QQ、腾讯新闻、腾讯视频、腾讯音乐等可以触达海量用户的应用场景，将用户与品牌、商品及服务进行高效连接。\n\n同时，我们还致力于为客户提供从营销触达环节，向前后端延伸至整个经营链路的数字化营销解决方案及产品工具，帮助客户实现数字化经营与生意增长。\n\n伴随腾讯业务的稳健成长，腾讯营销持续引领行业创新，实现高质量可持续发展。我们热衷追求满分，所以无比期待与更多能够创造腾讯营销明天的“满分后浪”们，一起上场！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1279258990471390209","sourceKey":"tencent","company":"腾讯","title":"腾讯营销—面向商业化推荐平台的生成式推荐技术研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1279258990471390209","duty":"课题背景：针对工业级商业化推荐系统，结合生成式AI技术构建下一代商业化推荐引擎，并通过强化学习实现持续演进和更新，提升商业化价值天花板\n当前挑战：广告推荐系统是实时在线学习，需要构建有效的实时Reward系统，驱动有效实时 On-Policy 演进机制\n\n工作内容：\n1.针对广告推荐优化目标ecpm/gmv，结合生成式AI技术，探索并构建下一代生成式推荐系统框架；\n2.结合广告推荐系统实时等特点，设计先进的生成式推荐模型架构与训练Recipe，包括 自回归、扩散等生成模型，以及课程学习、预训练、在线训练、强化学习等；\n3. 跟踪国际顶级学术会议与业界生成式推荐最新进展，形成技术路线与专利布局，产出高水平学术论文与技术报告。","requirements":"1.计算机相关专业硕士及以上学历，博士优先，具有扎实的计算机和机器学习基础，拥有优秀的编程能力和工程能力，学习能力强，具备良好的团队协作意识和主动性。\n2.在搜广推系统、生成式AI、机器学习等一个或多个领域有较深入的研究，包括但不限于判别式推荐、生成式推荐、LLM/MLLM、图像生成/编辑、视频生成/编辑； \n3.具有较强的实践能力，发表过高水平学术会议论文或者有竞赛经验者优先；","description":"课题描述\n课题背景：针对工业级商业化推荐系统，结合生成式AI技术构建下一代商业化推荐引擎，并通过强化学习实现持续演进和更新，提升商业化价值天花板\n当前挑战：广告推荐系统是实时在线学习，需要构建有效的实时Reward系统，驱动有效实时 On-Policy 演进机制\n\n工作内容：\n1.针对广告推荐优化目标ecpm/gmv，结合生成式AI技术，探索并构建下一代生成式推荐系统框架；\n2.结合广告推荐系统实时等特点，设计先进的生成式推荐模型架构与训练Recipe，包括 自回归、扩散等生成模型，以及课程学习、预训练、在线训练、强化学习等；\n3. 跟踪国际顶级学术会议与业界生成式推荐最新进展，形成技术路线与专利布局，产出高水平学术论文与技术报告。\n\n课题要求\n1.计算机相关专业硕士及以上学历，博士优先，具有扎实的计算机和机器学习基础，拥有优秀的编程能力和工程能力，学习能力强，具备良好的团队协作意识和主动性。\n2.在搜广推系统、生成式AI、机器学习等一个或多个领域有较深入的研究，包括但不限于判别式推荐、生成式推荐、LLM/MLLM、图像生成/编辑、视频生成/编辑； \n3.具有较强的实践能力，发表过高水平学术会议论文或者有竞赛经验者优先；\n\nCDG\n企业发展事业群\n\n腾讯营销\n腾讯营销作为腾讯⾯向企业统⼀的商业服务平台，基于腾讯坚实的技术实力，整合微信、QQ、腾讯新闻、腾讯视频、腾讯音乐等可以触达海量用户的应用场景，将用户与品牌、商品及服务进行高效连接。\n\n同时，我们还致力于为客户提供从营销触达环节，向前后端延伸至整个经营链路的数字化营销解决方案及产品工具，帮助客户实现数字化经营与生意增长。\n\n伴随腾讯业务的稳健成长，腾讯营销持续引领行业创新，实现高质量可持续发展。我们热衷追求满分，所以无比期待与更多能够创造腾讯营销明天的“满分后浪”们，一起上场！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1279259000613217280","sourceKey":"tencent","company":"腾讯","title":"腾讯营销—广告推荐基础大模型","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1279259000613217280","duty":"课题背景：当前广告系统通常由多个任务特定模型（如 CTR 预估、CVR 预估、召回模型等）独立构成，各模型底层表示重复建设，且难以充分利用全场景数据中的共性知识，导致信息利用不充分、扩展性受限。近年来，基础大模型（如 LLM）的预训练+微调范式已在 NLP/CV 领域证明其强大的泛化能力与扩展性。本课题旨在构建广告领域的基础大模型，通过全场景数据（广告、搜索、推荐等）的联合预训练，打造统一的底座模型，并借助知识蒸馏迁移技术赋能在线模型，突破传统多任务分治架构的瓶颈，提升广告匹配精度与系统效率。\n\n当前挑战：\n1、海量异构数据建模，不同数据源之间差异大，如何进行联合建模，减少负迁移\n2、 预训练-> 蒸馏方式两阶段，如何更好将信息迁移到线上模型，减少迁移损失\n\n工作内容：\n1、负责广告基础大模型的研发与构建，探索预训练+在线微调的新范式，通过全场景数据联合建模，为腾讯广告系统打造统一的底座模型；\n2、利用万亿级异构数据，通过样本、特征、模型的规模化扩展，持续突破基础模型的效果天花板，为在线模型提供更强大的特征表示与先验知识；\n 3、研究 Embedding 迁移、模型蒸馏、知识融合等技术，将基础大模型的能力高效传递给下游线上模型，驱动广告匹配精度持续提升；","requirements":"1、计算机科学、人工智能、自然语言处理、多模态等相关领域；\n2、对推荐算法和大模型技术有浓厚兴趣，有较好的算法和数据结构基础，有较好的编程能力；\n3、拥有扎实的机器学习基础，在深度学习、大语言模型（LLM）、多模态等方向有深入的理解，有推荐研究经历者优先；\n4、有国际竞赛经验（包括ACM、ICPC、数学建模大赛等）或在国际会议发表论文者（包括KDD、NeurIPS、ICML、ICLR、CVPR等）优先；\n5、优秀的分析问题和解决问题的能力，对解决挑战性问题充满激情。","description":"课题描述\n课题背景：当前广告系统通常由多个任务特定模型（如 CTR 预估、CVR 预估、召回模型等）独立构成，各模型底层表示重复建设，且难以充分利用全场景数据中的共性知识，导致信息利用不充分、扩展性受限。近年来，基础大模型（如 LLM）的预训练+微调范式已在 NLP/CV 领域证明其强大的泛化能力与扩展性。本课题旨在构建广告领域的基础大模型，通过全场景数据（广告、搜索、推荐等）的联合预训练，打造统一的底座模型，并借助知识蒸馏迁移技术赋能在线模型，突破传统多任务分治架构的瓶颈，提升广告匹配精度与系统效率。\n\n当前挑战：\n1、海量异构数据建模，不同数据源之间差异大，如何进行联合建模，减少负迁移\n2、 预训练-> 蒸馏方式两阶段，如何更好将信息迁移到线上模型，减少迁移损失\n\n工作内容：\n1、负责广告基础大模型的研发与构建，探索预训练+在线微调的新范式，通过全场景数据联合建模，为腾讯广告系统打造统一的底座模型；\n2、利用万亿级异构数据，通过样本、特征、模型的规模化扩展，持续突破基础模型的效果天花板，为在线模型提供更强大的特征表示与先验知识；\n 3、研究 Embedding 迁移、模型蒸馏、知识融合等技术，将基础大模型的能力高效传递给下游线上模型，驱动广告匹配精度持续提升；\n\n课题要求\n1、计算机科学、人工智能、自然语言处理、多模态等相关领域；\n2、对推荐算法和大模型技术有浓厚兴趣，有较好的算法和数据结构基础，有较好的编程能力；\n3、拥有扎实的机器学习基础，在深度学习、大语言模型（LLM）、多模态等方向有深入的理解，有推荐研究经历者优先；\n4、有国际竞赛经验（包括ACM、ICPC、数学建模大赛等）或在国际会议发表论文者（包括KDD、NeurIPS、ICML、ICLR、CVPR等）优先；\n5、优秀的分析问题和解决问题的能力，对解决挑战性问题充满激情。\n\nCDG\n企业发展事业群\n\n腾讯营销\n腾讯营销作为腾讯⾯向企业统⼀的商业服务平台，基于腾讯坚实的技术实力，整合微信、QQ、腾讯新闻、腾讯视频、腾讯音乐等可以触达海量用户的应用场景，将用户与品牌、商品及服务进行高效连接。\n\n同时，我们还致力于为客户提供从营销触达环节，向前后端延伸至整个经营链路的数字化营销解决方案及产品工具，帮助客户实现数字化经营与生意增长。\n\n伴随腾讯业务的稳健成长，腾讯营销持续引领行业创新，实现高质量可持续发展。我们热衷追求满分，所以无比期待与更多能够创造腾讯营销明天的“满分后浪”们，一起上场！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1279259000613217281","sourceKey":"tencent","company":"腾讯","title":"腾讯营销—端到端广告推荐大模型研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1279259000613217281","duty":"课题背景：\n当前广告推荐系统普遍沿用\"召回—粗排—精排\"的漏斗式级联链路，各阶段目标割裂、算力与样本空间不一致，误差层层传递，且工程约束反向限制了模型能力上限。随着大模型 Scaling Law 在各领域被验证，业界开始探索用统一模型直接建模从候选到最终排序的全过程。本课题旨在打破传统级联范式，通过算法与工程、业务与技术的联合设计（co-design / re-design），构建端到端的广告推荐大模型，释放全链路一致优化的潜力。\n\n课题挑战：\n1、链路重构：如何用统一模型建模数十亿量级候选集，在打破召粗精分治的同时满足在线毫秒级延迟与算力预算，需要算法与工程深度协同的 co-design；\n2、目标一致性：端到端建模需在单一模型内协调召回的多样性、排序的精准性与业务多目标（CTR/CVR/GMV/ROI）之间的冲突，避免局部最优；\n3、样本与训练：全链路联合建模面临严重的样本选择偏差（SSB）与曝光偏差，如何构造无偏训练信号、稳定超大规模稀疏模型的训练是核心难点；\n4、系统协同重设计：模型结构、特征体系、检索索引与在线服务需整体 re-design，任何单点优化都可能被系统瓶颈抵消。\n\n具体工作：\n1、研发端到端广告推荐大模型，探索召粗精一体化的新范式与统一建模结构；\n2、联合工程侧完成检索、索引、在线服务的协同 re-design，打通算法与系统边界；\n3、攻关全链路无偏训练、多目标一致优化与规模化扩展，持续突破链路效果天花板。","requirements":"1、硕士研究生及以上学历，计算机科学、人工智能、机器学习、应用数学等相关领域；\r\n2、对推荐系统与大模型技术有浓厚兴趣，具备扎实的算法与数据结构基础和优秀的编程能力，熟悉主流深度学习框架（PyTorch/TensorFlow）；\r\n3、拥有扎实的机器学习基础，在推荐系统、大语言模型（LLM）、生成式建模等方向有深入理解；对召回/排序链路、序列建模、大规模稀疏模型有实践经验者优先；\r\n4、有大规模分布式训练、算法与工程协同优化（co-design）经验，或在国际竞赛（包括但不限于 ACM-ICPC、数学建模大赛）获奖、在国际顶会（包括但不限于 KDD、NeurIPS、ICML、ICLR、SIGIR、RecSys 等）发表论文者优先；\r\n5、优秀的分析与解决问题能力，敢于挑战传统架构、对突破推荐系统链路瓶颈充满激情。","description":"课题描述\n课题背景：\n当前广告推荐系统普遍沿用\"召回—粗排—精排\"的漏斗式级联链路，各阶段目标割裂、算力与样本空间不一致，误差层层传递，且工程约束反向限制了模型能力上限。随着大模型 Scaling Law 在各领域被验证，业界开始探索用统一模型直接建模从候选到最终排序的全过程。本课题旨在打破传统级联范式，通过算法与工程、业务与技术的联合设计（co-design / re-design），构建端到端的广告推荐大模型，释放全链路一致优化的潜力。\n\n课题挑战：\n1、链路重构：如何用统一模型建模数十亿量级候选集，在打破召粗精分治的同时满足在线毫秒级延迟与算力预算，需要算法与工程深度协同的 co-design；\n2、目标一致性：端到端建模需在单一模型内协调召回的多样性、排序的精准性与业务多目标（CTR/CVR/GMV/ROI）之间的冲突，避免局部最优；\n3、样本与训练：全链路联合建模面临严重的样本选择偏差（SSB）与曝光偏差，如何构造无偏训练信号、稳定超大规模稀疏模型的训练是核心难点；\n4、系统协同重设计：模型结构、特征体系、检索索引与在线服务需整体 re-design，任何单点优化都可能被系统瓶颈抵消。\n\n具体工作：\n1、研发端到端广告推荐大模型，探索召粗精一体化的新范式与统一建模结构；\n2、联合工程侧完成检索、索引、在线服务的协同 re-design，打通算法与系统边界；\n3、攻关全链路无偏训练、多目标一致优化与规模化扩展，持续突破链路效果天花板。\n\n课题要求\n1、硕士研究生及以上学历，计算机科学、人工智能、机器学习、应用数学等相关领域；\r\n2、对推荐系统与大模型技术有浓厚兴趣，具备扎实的算法与数据结构基础和优秀的编程能力，熟悉主流深度学习框架（PyTorch/TensorFlow）；\r\n3、拥有扎实的机器学习基础，在推荐系统、大语言模型（LLM）、生成式建模等方向有深入理解；对召回/排序链路、序列建模、大规模稀疏模型有实践经验者优先；\r\n4、有大规模分布式训练、算法与工程协同优化（co-design）经验，或在国际竞赛（包括但不限于 ACM-ICPC、数学建模大赛）获奖、在国际顶会（包括但不限于 KDD、NeurIPS、ICML、ICLR、SIGIR、RecSys 等）发表论文者优先；\r\n5、优秀的分析与解决问题能力，敢于挑战传统架构、对突破推荐系统链路瓶颈充满激情。\n\nCDG\n企业发展事业群\n\n腾讯营销\n腾讯营销作为腾讯⾯向企业统⼀的商业服务平台，基于腾讯坚实的技术实力，整合微信、QQ、腾讯新闻、腾讯视频、腾讯音乐等可以触达海量用户的应用场景，将用户与品牌、商品及服务进行高效连接。\n\n同时，我们还致力于为客户提供从营销触达环节，向前后端延伸至整个经营链路的数字化营销解决方案及产品工具，帮助客户实现数字化经营与生意增长。\n\n伴随腾讯业务的稳健成长，腾讯营销持续引领行业创新，实现高质量可持续发展。我们热衷追求满分，所以无比期待与更多能够创造腾讯营销明天的“满分后浪”们，一起上场！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1279259000613217282","sourceKey":"tencent","company":"腾讯","title":"腾讯营销—商业化场景中多模态生成算法研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1279259000613217282","duty":"商业化场景中多模态生成算法研究\n岗位描述\n我们聚焦广告创意素材的智能化生产，以多模态生成 Agent 为核心技术路线，为信息流广告、品牌广告、效果广告等场景提供高质量、大规模、低成本的创意内容生成能力。\n我们构建的是能够自主规划创意、编排工具、自我评估与迭代的创意生产 Agent。团队围绕创意规划 Agent、多模态生成、Reward Model 与 Agentic RL 等方向开展研究，以技术驱动广告投放效率与创意质量的双重提升。\n\n工作职责\n创意生产 Agent 架构与规划：设计广告创意生产的 Agent 系统，研究需求理解、创意方案规划、多候选生成与自动优选，实现从投放需求到可投放素材的完整闭环；\n工具编排与自主纠错：构建创意生产工具体系（图像/视频生成、素材检索、布局排版、局部重绘等），研究 Agent 的工具选择与调用决策，实现基于质量反馈的自反思与定向修复；\n多模态生成模型研究：研究广告场景的可控图像与视频生成技术，攻克品牌元素一致性、构图可控性、图文协调等难题，为 Agent 提供可编排的原子生成能力；\nReward Model 与效果对齐：构建覆盖美学、商业表达、图文一致性、合规性的多维奖励模型作为 Agent 决策依据，并研究以 CTR/CVR 为导向的对齐方法（RLHF、DPO、GRPO 等）；\nAgentic RL：研究以强化学习优化 Agent 的规划、选路、工具调用等多步决策，探索多智能体协同、轨迹级优化与稀疏延迟反馈下的信用分配；\n前沿技术跟进与创新：紧跟 AIGC 与 Agent 领域最新进展（Diffusion、DiT、多模态统一模型、Agentic RL、工具学习等），推动业务落地与顶会论文产出。","requirements":"1、计算机科学、人工智能、电子工程、数学等相关专业在读硕士/博士，2026-2027 届毕业生或实习生；\n2、扎实的深度学习基础，熟悉主流生成模型原理（Diffusion Models、GAN、VAE、Flow Matching 等）；\n3、熟练使用 PyTorch 等主流深度学习框架，具备良好的 Python/C++ 编程能力；\n4、了解主流视觉生成模型（如 Stable Diffusion、DALL·E、DiT、Sora、CogVideo 等）及其可控生成方法（ControlNet、IP-Adapter、LoRA 等）；\n5、具备独立复现论文和设计实验的能力，有较强的分析问题和工程落地意识；\n6、良好的沟通协作能力和自驱力，对广告/营销等商业化场景有兴趣；\n7、加分项；\n8、在 CVPR、ICCV、ECCV、NeurIPS、ICML、ICLR、SIGGRAPH、ACM MM 等顶会发表过相关论文；\n9、有图像/视频生成模型的训练、微调或产品化落地经验；\n10、有广告创意、内容营销或推荐系统相关的研究或工程经验；\n11、了解广告投放链路（如 CTR 预估、创意优选）并能将其与生成技术结合思考；\n12、有大规模模型训练或推理优化经验。","description":"课题描述\n商业化场景中多模态生成算法研究\n岗位描述\n我们聚焦广告创意素材的智能化生产，以多模态生成 Agent 为核心技术路线，为信息流广告、品牌广告、效果广告等场景提供高质量、大规模、低成本的创意内容生成能力。\n我们构建的是能够自主规划创意、编排工具、自我评估与迭代的创意生产 Agent。团队围绕创意规划 Agent、多模态生成、Reward Model 与 Agentic RL 等方向开展研究，以技术驱动广告投放效率与创意质量的双重提升。\n\n工作职责\n创意生产 Agent 架构与规划：设计广告创意生产的 Agent 系统，研究需求理解、创意方案规划、多候选生成与自动优选，实现从投放需求到可投放素材的完整闭环；\n工具编排与自主纠错：构建创意生产工具体系（图像/视频生成、素材检索、布局排版、局部重绘等），研究 Agent 的工具选择与调用决策，实现基于质量反馈的自反思与定向修复；\n多模态生成模型研究：研究广告场景的可控图像与视频生成技术，攻克品牌元素一致性、构图可控性、图文协调等难题，为 Agent 提供可编排的原子生成能力；\nReward Model 与效果对齐：构建覆盖美学、商业表达、图文一致性、合规性的多维奖励模型作为 Agent 决策依据，并研究以 CTR/CVR 为导向的对齐方法（RLHF、DPO、GRPO 等）；\nAgentic RL：研究以强化学习优化 Agent 的规划、选路、工具调用等多步决策，探索多智能体协同、轨迹级优化与稀疏延迟反馈下的信用分配；\n前沿技术跟进与创新：紧跟 AIGC 与 Agent 领域最新进展（Diffusion、DiT、多模态统一模型、Agentic RL、工具学习等），推动业务落地与顶会论文产出。\n\n课题要求\n1、计算机科学、人工智能、电子工程、数学等相关专业在读硕士/博士，2026-2027 届毕业生或实习生；\n2、扎实的深度学习基础，熟悉主流生成模型原理（Diffusion Models、GAN、VAE、Flow Matching 等）；\n3、熟练使用 PyTorch 等主流深度学习框架，具备良好的 Python/C++ 编程能力；\n4、了解主流视觉生成模型（如 Stable Diffusion、DALL·E、DiT、Sora、CogVideo 等）及其可控生成方法（ControlNet、IP-Adapter、LoRA 等）；\n5、具备独立复现论文和设计实验的能力，有较强的分析问题和工程落地意识；\n6、良好的沟通协作能力和自驱力，对广告/营销等商业化场景有兴趣；\n7、加分项；\n8、在 CVPR、ICCV、ECCV、NeurIPS、ICML、ICLR、SIGGRAPH、ACM MM 等顶会发表过相关论文；\n9、有图像/视频生成模型的训练、微调或产品化落地经验；\n10、有广告创意、内容营销或推荐系统相关的研究或工程经验；\n11、了解广告投放链路（如 CTR 预估、创意优选）并能将其与生成技术结合思考；\n12、有大规模模型训练或推理优化经验。\n\nCDG\n企业发展事业群\n\n腾讯营销\n腾讯营销作为腾讯⾯向企业统⼀的商业服务平台，基于腾讯坚实的技术实力，整合微信、QQ、腾讯新闻、腾讯视频、腾讯音乐等可以触达海量用户的应用场景，将用户与品牌、商品及服务进行高效连接。\n\n同时，我们还致力于为客户提供从营销触达环节，向前后端延伸至整个经营链路的数字化营销解决方案及产品工具，帮助客户实现数字化经营与生意增长。\n\n伴随腾讯业务的稳健成长，腾讯营销持续引领行业创新，实现高质量可持续发展。我们热衷追求满分，所以无比期待与更多能够创造腾讯营销明天的“满分后浪”们，一起上场！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1280148757136402432","sourceKey":"tencent","company":"腾讯","title":"超大规模多模态训练系统性能优化","city":"杭州","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1280148757136402432","duty":"针对视频模型/世界模型超大规模集群训练场景，聚焦优化超长序列和计算负载不均衡问题：\n1. 针对超长序列场景（1M+）的视频训练，需要解决由于时空复杂度随帧数呈平方级爆炸导致的显存墙突破难、计算密集型算子引发的硬件利用率（MFU）低，以及流水线并行中因帧间依赖造成的负载不均与通信阻塞等问题；\n2. 针对世界模型训练中视觉、音频、文本等模态间的计算特性差异和不同批次数据长短序列问题，研究基于实时数据调度和计算图切分的动态负载均衡方案，以解决因“木桶效应”导致的GPU空置问题，从而显著提升多模态世界模型在超大规模集群训练的吞吐量与资源利用率。","requirements":"1、计算机科学、人工智能、模式识别、计算语言学等相关专业硕士及以上学历；\r\n2、精通一种或多种主流深度学习框架（PyTorch、JAX、TensorFlow），具备大规模分布式训练经验；\r\n3、熟悉LLM/DiT等模型的训练流程，有 Megatron、DeepSpeed、FSDP等大规模训练框架使用经验者优先；\r\n4、具备扎实的工程实现能力与代码规范意识，熟悉CUDA优化、参数并行、流水线并行等技术。","description":"课题描述\n针对视频模型/世界模型超大规模集群训练场景，聚焦优化超长序列和计算负载不均衡问题：\n1. 针对超长序列场景（1M+）的视频训练，需要解决由于时空复杂度随帧数呈平方级爆炸导致的显存墙突破难、计算密集型算子引发的硬件利用率（MFU）低，以及流水线并行中因帧间依赖造成的负载不均与通信阻塞等问题；\n2. 针对世界模型训练中视觉、音频、文本等模态间的计算特性差异和不同批次数据长短序列问题，研究基于实时数据调度和计算图切分的动态负载均衡方案，以解决因“木桶效应”导致的GPU空置问题，从而显著提升多模态世界模型在超大规模集群训练的吞吐量与资源利用率。\n\n课题要求\n1、计算机科学、人工智能、模式识别、计算语言学等相关专业硕士及以上学历；\r\n2、精通一种或多种主流深度学习框架（PyTorch、JAX、TensorFlow），具备大规模分布式训练经验；\r\n3、熟悉LLM/DiT等模型的训练流程，有 Megatron、DeepSpeed、FSDP等大规模训练框架使用经验者优先；\r\n4、具备扎实的工程实现能力与代码规范意识，熟悉CUDA优化、参数并行、流水线并行等技术。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1280285760972760064","sourceKey":"tencent","company":"腾讯","title":"微信安全-内容审核基模","city":"广州","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1280285760972760064","duty":"课题背景\n随着平台内容生态的快速发展，图文、短视频、直播、评论等每日产生海量多模态内容，同时违规形式日益隐蔽和复杂（文字+图像暗示、AI生成对抗、跨模态诱导等）。传统人工审核和单模态模型已难以满足规模化、高实时性的安全治理需求，容易导致漏判风险或高额人力成本。  因此，本课题聚焦研发内容审核多模态基座大模型，旨在构建一个统一、强大、可复用的安全垂类基座，通过深度融合多模态信息，精准理解平台规则与风险模式，为全平台内容审核和账号风控提供高效底层能力，大幅提升自动化审核率、准确率和治理效率，支撑健康的内容生态。\n\n课题挑战  \n1、多模态深度融合与一致性理解：需有效对齐图片、视频、音频、文本、行为序列、关系特征等多模态信息，应对复杂的跨模态对抗和隐性违规，防止模态冲突导致判断失误。  \n2、高动态违规的持续适配：违规手法迭代极快，长尾类别多，模型需实现高效的持续学习，同时避免灾难性遗忘。  \n3、极致规模下的效率与成本：亿级日内容量要求毫秒级低延迟推理，如何在保证极低漏判率的前提下大幅压缩模型、降低算力成本是重大工程挑战。  \n4、数据与对齐难题：高质量违规标注成本高、主观性强，且需严格隐私合规；同时要在高精度打击与低误伤正常内容之间取得平衡。  \n\n具体工作\n加入课题后，同学将主要参与多模态基座模型的预训练/后训练、跨模态融合架构设计、数据 pipeline 构建、模型压缩与推理加速等工作，承担部分实验验证、难例分析及下游任务适配优化，快速积累大模型研发与内容安全领域的实战经验。","requirements":"学历和专业要求\n来自计算机科学、人工智能、机器学习、计算机视觉或相关专业的博士/硕士同学优先。\n技术技能要求\n有大模型或多模态算法研发实习经验，熟练掌握PyTorch（优先）等主流深度学习框架，精通Python编程；扎实的数学基础（概率论、线性代数、微积分等），有大规模模型训练、优化或CUDA并行计算经验者优先。熟悉内容安全、多模态理解（CV+NLP+序列建模）者优先。\n软性素质要求\n对大模型训练、优化及AI安全落地有浓厚兴趣和快速学习能力；具备良好的沟通协作能力、团队合作精神和较强的工程实践与问题解决能力，能够主动推动课题进展。","description":"课题描述\n课题背景\n随着平台内容生态的快速发展，图文、短视频、直播、评论等每日产生海量多模态内容，同时违规形式日益隐蔽和复杂（文字+图像暗示、AI生成对抗、跨模态诱导等）。传统人工审核和单模态模型已难以满足规模化、高实时性的安全治理需求，容易导致漏判风险或高额人力成本。  因此，本课题聚焦研发内容审核多模态基座大模型，旨在构建一个统一、强大、可复用的安全垂类基座，通过深度融合多模态信息，精准理解平台规则与风险模式，为全平台内容审核和账号风控提供高效底层能力，大幅提升自动化审核率、准确率和治理效率，支撑健康的内容生态。\n\n课题挑战  \n1、多模态深度融合与一致性理解：需有效对齐图片、视频、音频、文本、行为序列、关系特征等多模态信息，应对复杂的跨模态对抗和隐性违规，防止模态冲突导致判断失误。  \n2、高动态违规的持续适配：违规手法迭代极快，长尾类别多，模型需实现高效的持续学习，同时避免灾难性遗忘。  \n3、极致规模下的效率与成本：亿级日内容量要求毫秒级低延迟推理，如何在保证极低漏判率的前提下大幅压缩模型、降低算力成本是重大工程挑战。  \n4、数据与对齐难题：高质量违规标注成本高、主观性强，且需严格隐私合规；同时要在高精度打击与低误伤正常内容之间取得平衡。  \n\n具体工作\n加入课题后，同学将主要参与多模态基座模型的预训练/后训练、跨模态融合架构设计、数据 pipeline 构建、模型压缩与推理加速等工作，承担部分实验验证、难例分析及下游任务适配优化，快速积累大模型研发与内容安全领域的实战经验。\n\n课题要求\n学历和专业要求\n来自计算机科学、人工智能、机器学习、计算机视觉或相关专业的博士/硕士同学优先。\n技术技能要求\n有大模型或多模态算法研发实习经验，熟练掌握PyTorch（优先）等主流深度学习框架，精通Python编程；扎实的数学基础（概率论、线性代数、微积分等），有大规模模型训练、优化或CUDA并行计算经验者优先。熟悉内容安全、多模态理解（CV+NLP+序列建模）者优先。\n软性素质要求\n对大模型训练、优化及AI安全落地有浓厚兴趣和快速学习能力；具备良好的沟通协作能力、团队合作精神和较强的工程实践与问题解决能力，能够主动推动课题进展。\n\nWXG\n微信事业群\n\n微信安全团队\n【加入微信安全，成为亿万用户的守护者】 在这里，你将直面黑灰产攻防最前沿，运用AI与大数据构建智能防御体系；你将与顶尖技术团队协同作战，在真实攻防对抗中加速成长；你编写的每行代码，将会守护10亿+用户的账号安全、财产安全与隐私安全。加入我们，让技术的力量照亮数字世界的每个角落。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1281716041881610240","sourceKey":"tencent","company":"腾讯","title":"微信搜索-多模态理解（数据/算法）研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1281716041881610240","duty":"课题背景\n作为连接内生态的桥梁，微信搜索在大模型发展的路径上除了通过语义连接文本内容，还需要让模型理解内生态中的各种多模态内容。在海量图片、视频加持下，为 AI 注入看懂世界的能力，能够提升 AI 搜索内容的准确性和丰富度。在这里，你将会遇到多模态领域的最本质的问题，处理海量且带有噪声的真实多模态数据，充分利用微信内生态各种资源、工具，设计高效原生的数据管线，探索全面且覆盖真实搜索场景的多模态评估基准，跨越数据、评估、训练的全链路。\n课题挑战：\n视觉编码器与 VLM 架构的高效训练是多模态理解的挑战之一。在Vision Encoder 的选型与再训练面临着 CLIP/SigLIP等的适配、Native Resolution/Patch-npack 的取舍。另外在训练阶段还需解决在大 batch、大分辨率下的 loss spike、模态坍塌、语言能力退化等现象的诊断与缓解。\n\n评估是引导模型迭代的重中之重。结合搜索的多模态评测不能局限于公开 benchmark，需要独立地针对任务设计人工评测、自动评测流程。此外，需要构建覆盖幻觉 (Hallucination)、空间推理 (Spatial Reasoning)、细粒度识别 (Fine-grained)、OCR、图表理解 (Chart/Doc)、多图/长视频、意图理解、Agent 交互等维度的分层评测。\n\n引入外部工具 (搜索、code-interpreter等） 是提升多模态能力上限的重要路径，但也会带来副作用。比如能力偏置 (Capability Shift)问题会导致模型过度依赖工具会削弱模型的原生视觉能力 (grounding、counting、reading)。因此需要研究跨模态信号分配、工具加持下多模态模型训练推理一致性和工具调用的鲁棒性。\n\n多模态模型对数据配方 (Data Recipe) 极其敏感。挑战包括：图文数据跨任务的混合策略，在多模态模型训练中对模型能力的影响较大。调配不同任务数据在模型各训练阶段中的配比，才能使模型发挥出需要的关键能力。\n具体工作：\n负责多模态模型的迭代。探索视觉编码器和 VLM 结构的高效训练、评测方式。针对微信搜索场景的多模态理解需求，持续验证和迭代训练算法（包括 SFT/RL/OPD 算法）。\n\n负责多模态模型训练数据的合成预筛选。从头定义图文数据的采集方式、质量标准、筛选逻辑。从丰富的内生态资源中，构建稳定、扎实、高效的自动化合成、清洗的数据管线。在数据侧稳步提升模型的多模态基础能力。\n\n搭建针对微信搜索 Agent 领域的定制化多模态评估基准，定位模型短板，针对性优化模型在多模理解上的不足，并持续回流训练数据建设流程，指引模型迭代。","requirements":"面向计算机科学、人工智能、机器学习、应用数学等相关专业的硕士或博士同学；在顶级学术会议（如ICML, ICLR, NeurIPS, COLM, CVPR等）有相关论文发表经验者优先。\n\n深入理解主流视觉编码器（如 CLIP, SigLIP 等）的模型结构，熟悉其训练与评测方法。\n\n熟悉主流多模态模型的架构，熟悉主流多模态模型架构：LLaVA 系列、Qwen-VL / Qwen2-VL / Qwen2.5-VL、InternVL 系列、Kimi-VL、DeepSeek-VL、Molmo、Pixtral、Gemini、GPT-4o / GPT-4V、Claude 3.5 Sonnet、以及原生多模态 (Emu3 / Show-o / Janus) 的结构差异与工程实现。\n\n大规模多模态预训练或后训练实战经验：至少完整落地过一个阶段 (Pretrain / Mid-Train / SFT / RL / OPD)，理解模态融合、位置编码 (M-RoPE / 2D-RoPE)、AnyRes、Native Resolution、Token Compression 等关键技术。\n\n极强的数据直觉：具备大规模图文/视频数据 清洗、质量标注、去重、合成、混合配比 的实战经验，能从数据分布中一眼识别问题，有大规模图文/视频数据清洗、质量标注及数据合成的实战经验。具备一定的工程代码能力。","description":"课题描述\n课题背景\n作为连接内生态的桥梁，微信搜索在大模型发展的路径上除了通过语义连接文本内容，还需要让模型理解内生态中的各种多模态内容。在海量图片、视频加持下，为 AI 注入看懂世界的能力，能够提升 AI 搜索内容的准确性和丰富度。在这里，你将会遇到多模态领域的最本质的问题，处理海量且带有噪声的真实多模态数据，充分利用微信内生态各种资源、工具，设计高效原生的数据管线，探索全面且覆盖真实搜索场景的多模态评估基准，跨越数据、评估、训练的全链路。\n课题挑战：\n视觉编码器与 VLM 架构的高效训练是多模态理解的挑战之一。在Vision Encoder 的选型与再训练面临着 CLIP/SigLIP等的适配、Native Resolution/Patch-npack 的取舍。另外在训练阶段还需解决在大 batch、大分辨率下的 loss spike、模态坍塌、语言能力退化等现象的诊断与缓解。\n\n评估是引导模型迭代的重中之重。结合搜索的多模态评测不能局限于公开 benchmark，需要独立地针对任务设计人工评测、自动评测流程。此外，需要构建覆盖幻觉 (Hallucination)、空间推理 (Spatial Reasoning)、细粒度识别 (Fine-grained)、OCR、图表理解 (Chart/Doc)、多图/长视频、意图理解、Agent 交互等维度的分层评测。\n\n引入外部工具 (搜索、code-interpreter等） 是提升多模态能力上限的重要路径，但也会带来副作用。比如能力偏置 (Capability Shift)问题会导致模型过度依赖工具会削弱模型的原生视觉能力 (grounding、counting、reading)。因此需要研究跨模态信号分配、工具加持下多模态模型训练推理一致性和工具调用的鲁棒性。\n\n多模态模型对数据配方 (Data Recipe) 极其敏感。挑战包括：图文数据跨任务的混合策略，在多模态模型训练中对模型能力的影响较大。调配不同任务数据在模型各训练阶段中的配比，才能使模型发挥出需要的关键能力。\n具体工作：\n负责多模态模型的迭代。探索视觉编码器和 VLM 结构的高效训练、评测方式。针对微信搜索场景的多模态理解需求，持续验证和迭代训练算法（包括 SFT/RL/OPD 算法）。\n\n负责多模态模型训练数据的合成预筛选。从头定义图文数据的采集方式、质量标准、筛选逻辑。从丰富的内生态资源中，构建稳定、扎实、高效的自动化合成、清洗的数据管线。在数据侧稳步提升模型的多模态基础能力。\n\n搭建针对微信搜索 Agent 领域的定制化多模态评估基准，定位模型短板，针对性优化模型在多模理解上的不足，并持续回流训练数据建设流程，指引模型迭代。\n\n课题要求\n面向计算机科学、人工智能、机器学习、应用数学等相关专业的硕士或博士同学；在顶级学术会议（如ICML, ICLR, NeurIPS, COLM, CVPR等）有相关论文发表经验者优先。\n\n深入理解主流视觉编码器（如 CLIP, SigLIP 等）的模型结构，熟悉其训练与评测方法。\n\n熟悉主流多模态模型的架构，熟悉主流多模态模型架构：LLaVA 系列、Qwen-VL / Qwen2-VL / Qwen2.5-VL、InternVL 系列、Kimi-VL、DeepSeek-VL、Molmo、Pixtral、Gemini、GPT-4o / GPT-4V、Claude 3.5 Sonnet、以及原生多模态 (Emu3 / Show-o / Janus) 的结构差异与工程实现。\n\n大规模多模态预训练或后训练实战经验：至少完整落地过一个阶段 (Pretrain / Mid-Train / SFT / RL / OPD)，理解模态融合、位置编码 (M-RoPE / 2D-RoPE)、AnyRes、Native Resolution、Token Compression 等关键技术。\n\n极强的数据直觉：具备大规模图文/视频数据 清洗、质量标注、去重、合成、混合配比 的实战经验，能从数据分布中一眼识别问题，有大规模图文/视频数据清洗、质量标注及数据合成的实战经验。具备一定的工程代码能力。\n\nWXG\n微信事业群\n\n微信搜索团队\n微信搜索团队依托微信AI助手小微、公众号、视频号、小程序、微信小店构成的独特生态，以大模型技术为驱动，深度耕耘 AI 应用与智能搜索两大方向，覆盖微信各场景。\n在AI应用侧，我们深度参与微信AI助手“小微”的建设，让数亿用户通过自然对话获取信息、完成服务、连接彼此；在搜索侧，我们运用搜索与推荐技术，构建新一代生成式智能搜索，全面覆盖AI搜索、综合搜索、视频号搜索、小店与商品搜索、公众号搜索、小程序搜索等场景。\n独特的生态、海量的用户、领先的大模型落地实践，共同支撑着业务的快速发展。我们拥有优秀的AI算法、工程与产品团队，欢迎你的加入，一起探索大模型在复杂生态下的无限潜力，提升数亿人的AI与搜索体验。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1282757508758628352","sourceKey":"tencent","company":"腾讯","title":"微信 视频号-加热大模型驱动的跨域推荐与商业化全链路优化研究","city":"广州","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1282757508758628352","duty":"课题背景：微信视频号加热服务于创作者/商家，是他们付费进行助推和主动冷启的工具。面临亿级用户、超长序列及多场景跨域推荐的挑战，以及稀疏场景下内容冷启动难等问题，需开展超大推荐模型研究，以提升推荐精准度与商业变现效率。\n\n课题挑战：\n1. 攻克超长序列高效建模；\n2. 探索生成式推荐在视频号加热中的落地；\n3. 探索高效Scaling Up结构，在成本可控的前提下提升模型容量，优化分发效率；\n4. 使用LLM或VLLM增强系统对内容的识别能力，或引入世界知识提升效果。\n\n具体工作：负责视频号加热算法研发，提升全链路用户体验与变现效率。","requirements":"学历和专业要求：计算机科学、人工智能、数据科学等相关专业的博士 / 硕士研究优先，具备扎实的算法理论基础。\n技术技能要求：精通深度学习框架，熟悉超大模型训练；掌握推荐系统、召回 / 排序算法及多目标优化机制；具备LLM开发、调优经验。\n软性素质要求：具备极强的逻辑推理能力与跨团队协作能力，对技术细节有极致追求，能够独立推动算法项目从模型研发到线上落地的全流程。","description":"课题描述\n课题背景：微信视频号加热服务于创作者/商家，是他们付费进行助推和主动冷启的工具。面临亿级用户、超长序列及多场景跨域推荐的挑战，以及稀疏场景下内容冷启动难等问题，需开展超大推荐模型研究，以提升推荐精准度与商业变现效率。\n\n课题挑战：\n1. 攻克超长序列高效建模；\n2. 探索生成式推荐在视频号加热中的落地；\n3. 探索高效Scaling Up结构，在成本可控的前提下提升模型容量，优化分发效率；\n4. 使用LLM或VLLM增强系统对内容的识别能力，或引入世界知识提升效果。\n\n具体工作：负责视频号加热算法研发，提升全链路用户体验与变现效率。\n\n课题要求\n学历和专业要求：计算机科学、人工智能、数据科学等相关专业的博士 / 硕士研究优先，具备扎实的算法理论基础。\n技术技能要求：精通深度学习框架，熟悉超大模型训练；掌握推荐系统、召回 / 排序算法及多目标优化机制；具备LLM开发、调优经验。\n软性素质要求：具备极强的逻辑推理能力与跨团队协作能力，对技术细节有极致追求，能够独立推动算法项目从模型研发到线上落地的全流程。\n\nWXG\n微信事业群\n\n微信视频号团队\n微信视频号团队专注于视频、直播、交易、加热等业务，致力于通过技术连接海量创作者、用户与商家。我们基于实时、超大规模推荐架构与推荐工程平台，持续优化内容分发效率，探索前沿推荐范式，帮助用户快速发现优质内容，同时拥抱AIGC技术，覆盖多模态基础模型研发与后训练，以AI创作模板辅助创作者创作，提升创作效率与表达能力。期待你的加入，在服务创作者、连接用户的过程中，与团队一起实现更有温度的连接，创造可持续的长期价值。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1282757508758628353","sourceKey":"tencent","company":"腾讯","title":"微信 跨平台大模型计算基础设施","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1282757508758628353","duty":"课题背景\n随着语言模型、多模态模型及 AIGC 技术的快速发展，AI 正在深刻重塑微信生态中的内容理解、生成、推荐、问答、交互等核心能力。围绕这些场景，上百种不同规模的模型已经被部署在移动、桌面及服务器等端侧与云侧环境的 CPU/GPU/NPU 等异构硬件之上，并适配多种操作系统与复杂业务环境。\n\n面向大语言模型、多模态模型与 AIGC 应用的极致推理与图形图像处理等并行计算与 Co-design 能力及其配套设施，是微信持续投入、打磨和夯实的重要基础能力模块之一，对于丰富产品能力、提升用户体验、降低功耗和节省成本至关重要。\n\n课题挑战\n1、硬件微架构与体系结构层面：大模型对硬件微架构的效率极为敏感。然而不少关键平台的微架构细节并不完全公开，充分挖掘各平台的真实潜力需要深入剖析硬件行为并设计针对性的软硬件协同优化方案。\n2、大模型结构与并行计算层面：大模型的结构与计算模式复杂且持续演进，需要持续跟进算法进展，快速识别工程落地机会，将学术创新转化为系统优化方向。\n3、软件系统框架与架构层面：不同场景和平台在功耗、吞吐、时延等目标上差异显著。如何围绕微信实际业务目标实现合理折衷，同时保持架构的灵活性与可扩展性。\n4、学科交叉层面：要求研究者具备跨层次、跨方向的综合能力，完成从模型到系统的闭环优化。\n具体工作\n核心目标是面向手机、PC 等终端以及国产 GPU / NPU 加速卡，进行高性能算子开发、推理框架建设与大模型推理优化。\n在算子与推理引擎层面，实现跨平台的通用推理性能提升。在端侧与加速卡 NPU 上进行针对性加速的同时，也探索通用的 CPU / GPU 优化方案，从编译、算子、推理引擎多个维度协同发力。在部署形态上，覆盖端云协同、多机多卡推理等多种方案，追求极致的端到端性能。\n在模型演进层面，传统 LLM 和 DiT 的结构已趋近成熟，自回归视频模型、扩散语言模型、生成理解统一模型等新兴架构将是重点优化方向。同时，已有模型在我们这里并非\"只读\"的——我们也会面向推理场景，通过微调、蒸馏、量化、剪枝等手段优化性能、保证质量、降低成本，推动系统与模型的 Co-design。","requirements":"招聘要求\n学历和专业要求：本科及以上学历，专业不限。\n加分项：\n- 在 ACM / ICPC 等代码竞赛中获得银牌及以上，或在 ASC / CPC / PAC 等超算竞赛中取得前 30% 名次\n- 以第一作者或主要工程贡献者身份，在 SC、PPoPP、ATC、EuroSys、IPDPS、ICCD、MLSys 等系统方向会议，或 CCF-A 类算法方向会议上发表过论文\n技术技能要求\n- 对 CPU/GPU/NPU 等硬件体系结构有实践层面的理解，能分析其对算子性能与模型部署的影响\n- 能够在端侧或服务端独立完成模型的部署、调试与性能分析\n- 在以下一个或多个方向有深入了解：C/C++/CUDA 高性能编程、图编译与算子优化、KV Cache / MoE / DiT 等模型结构的 Training-free 推理优化\n软性素质要求\n- 具备独立思考与自驱能力，能够围绕研究课题进行深入探索\n- 面对新领域能快速上手，具备系统化学习与构建知识体系的能力\n- 拥抱 AI，善于利用 AI 工具辅助工作流，对大模型的落地应用有热情与愿景","description":"课题描述\n课题背景\n随着语言模型、多模态模型及 AIGC 技术的快速发展，AI 正在深刻重塑微信生态中的内容理解、生成、推荐、问答、交互等核心能力。围绕这些场景，上百种不同规模的模型已经被部署在移动、桌面及服务器等端侧与云侧环境的 CPU/GPU/NPU 等异构硬件之上，并适配多种操作系统与复杂业务环境。\n\n面向大语言模型、多模态模型与 AIGC 应用的极致推理与图形图像处理等并行计算与 Co-design 能力及其配套设施，是微信持续投入、打磨和夯实的重要基础能力模块之一，对于丰富产品能力、提升用户体验、降低功耗和节省成本至关重要。\n\n课题挑战\n1、硬件微架构与体系结构层面：大模型对硬件微架构的效率极为敏感。然而不少关键平台的微架构细节并不完全公开，充分挖掘各平台的真实潜力需要深入剖析硬件行为并设计针对性的软硬件协同优化方案。\n2、大模型结构与并行计算层面：大模型的结构与计算模式复杂且持续演进，需要持续跟进算法进展，快速识别工程落地机会，将学术创新转化为系统优化方向。\n3、软件系统框架与架构层面：不同场景和平台在功耗、吞吐、时延等目标上差异显著。如何围绕微信实际业务目标实现合理折衷，同时保持架构的灵活性与可扩展性。\n4、学科交叉层面：要求研究者具备跨层次、跨方向的综合能力，完成从模型到系统的闭环优化。\n具体工作\n核心目标是面向手机、PC 等终端以及国产 GPU / NPU 加速卡，进行高性能算子开发、推理框架建设与大模型推理优化。\n在算子与推理引擎层面，实现跨平台的通用推理性能提升。在端侧与加速卡 NPU 上进行针对性加速的同时，也探索通用的 CPU / GPU 优化方案，从编译、算子、推理引擎多个维度协同发力。在部署形态上，覆盖端云协同、多机多卡推理等多种方案，追求极致的端到端性能。\n在模型演进层面，传统 LLM 和 DiT 的结构已趋近成熟，自回归视频模型、扩散语言模型、生成理解统一模型等新兴架构将是重点优化方向。同时，已有模型在我们这里并非\"只读\"的——我们也会面向推理场景，通过微调、蒸馏、量化、剪枝等手段优化性能、保证质量、降低成本，推动系统与模型的 Co-design。\n\n课题要求\n招聘要求\n学历和专业要求：本科及以上学历，专业不限。\n加分项：\n- 在 ACM / ICPC 等代码竞赛中获得银牌及以上，或在 ASC / CPC / PAC 等超算竞赛中取得前 30% 名次\n- 以第一作者或主要工程贡献者身份，在 SC、PPoPP、ATC、EuroSys、IPDPS、ICCD、MLSys 等系统方向会议，或 CCF-A 类算法方向会议上发表过论文\n技术技能要求\n- 对 CPU/GPU/NPU 等硬件体系结构有实践层面的理解，能分析其对算子性能与模型部署的影响\n- 能够在端侧或服务端独立完成模型的部署、调试与性能分析\n- 在以下一个或多个方向有深入了解：C/C++/CUDA 高性能编程、图编译与算子优化、KV Cache / MoE / DiT 等模型结构的 Training-free 推理优化\n软性素质要求\n- 具备独立思考与自驱能力，能够围绕研究课题进行深入探索\n- 面对新领域能快速上手，具备系统化学习与构建知识体系的能力\n- 拥抱 AI，善于利用 AI 工具辅助工作流，对大模型的落地应用有热情与愿景\n\nWXG\n微信事业群\n\n技术架构团队\n作为微信后台的奠基团队，我们集基础研究与应用开发于一体，深耕底层架构与前沿 AI 引擎，全力支撑全球 14 亿+ 用户的超大规模社交连接。\n\n海量服务基建：打造 WXG 核心 ABC 平台（AI 日均百亿级调用、BigData 日均百万级任务、Cloud 每秒百亿级 TPS），保障微信全线业务的极致稳定。\n\n前沿 AI 探索：主导自研基座大模型 WeLM，在预训练、多模态及 Agent 等方向持续突破，全面赋能微信 AI 助手“小微”、AI 搜索等核心场景，并积极反哺学术界与开源社区。\n\n欢迎加入微信技术架构团队，在 SuperApp 的真实生态中，打造下一代海量服务和 AI 基础能力！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1282757520922109952","sourceKey":"tencent","company":"腾讯","title":"微信视频号-视频号电商新模型推荐范式研究","city":"广州","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1282757520922109952","duty":"课题背景：微信视频号电商致力于优化直播电商、短视频电商等内容分发，提升用户购物和消费体验，以技术升级为微信电商提供增长新动力 。现阶段视频号电商推荐系统已落地LLM推荐和生成式推荐等新推荐范式，下一步将探索两者与传统判别式模型的结合，利用多种建模能力与更合理的算力分配方式，实现在大候选上召回与排序的统一模型，从而提升推荐效果。\n\n课程挑战：\n1. 探索传统判别式与生成式模型的融合方式，提升生成式召回的判别能力，并为判别式任务提供高效的候选压缩与候选表征能力\n2. 探索基于LLM基座的端到端推荐优化，实现微信多领域用户信息的高效压缩输入，并结合电商业务优化SFT与RL方式\n3. 探索LLM表征或推荐结果在判别式与生成式模型的融合方式，提升融合深入程度以提升推荐模型的复杂业务信息感知能力\n\n具体工作（>=T10）：\n1. 具备推荐系统全局视野，理解传统推荐系统召回精排等模型的设计原理与局限，基于现有系统设计全新的模型方案，研究大候选和超长序列下序列和候选的压缩和利用方式，找到最佳的算力分配和组合机制，思考已有建模方式如何改进利用。\n2. 熟悉LLM的工作方式，结合业务的算力和实时性要求，设计LLM与线上系统的融合方式，让LLM能深度赋能推荐系统。\n\n具体工作（\u003cT10）：\n1. 能快速理解各项模型设计思路，承担起单个模型模块的具体工作，能结合实践情况和业界调研解决遇到困难，逐步完善整体设计并工程落地。\n2. 熟悉LLM常见SFT和RL工具和训练方式，能结合业务情况选择合适手段达到预期目标","requirements":"学历和专业要求：计算机科学、人工智能、数据科学等相关专业的博士 / 硕士研究生优先，具备扎实的算法理论基础。\n\n技术技能要求：精通深度学习框架，熟悉超大模型训练；掌握推荐系统、召回 / 排序算法及多目标优化机制；具备LLM开发、调优经验。\n软性素质要求：具备极强的逻辑推理能力与跨团队协作能力，对技术细节有极致追求，能够独立推动算法项目从模型研发到线上落地的全流程。","description":"课题描述\n课题背景：微信视频号电商致力于优化直播电商、短视频电商等内容分发，提升用户购物和消费体验，以技术升级为微信电商提供增长新动力 。现阶段视频号电商推荐系统已落地LLM推荐和生成式推荐等新推荐范式，下一步将探索两者与传统判别式模型的结合，利用多种建模能力与更合理的算力分配方式，实现在大候选上召回与排序的统一模型，从而提升推荐效果。\n\n课程挑战：\n1. 探索传统判别式与生成式模型的融合方式，提升生成式召回的判别能力，并为判别式任务提供高效的候选压缩与候选表征能力\n2. 探索基于LLM基座的端到端推荐优化，实现微信多领域用户信息的高效压缩输入，并结合电商业务优化SFT与RL方式\n3. 探索LLM表征或推荐结果在判别式与生成式模型的融合方式，提升融合深入程度以提升推荐模型的复杂业务信息感知能力\n\n具体工作（>=T10）：\n1. 具备推荐系统全局视野，理解传统推荐系统召回精排等模型的设计原理与局限，基于现有系统设计全新的模型方案，研究大候选和超长序列下序列和候选的压缩和利用方式，找到最佳的算力分配和组合机制，思考已有建模方式如何改进利用。\n2. 熟悉LLM的工作方式，结合业务的算力和实时性要求，设计LLM与线上系统的融合方式，让LLM能深度赋能推荐系统。\n\n具体工作（\u003cT10）：\n1. 能快速理解各项模型设计思路，承担起单个模型模块的具体工作，能结合实践情况和业界调研解决遇到困难，逐步完善整体设计并工程落地。\n2. 熟悉LLM常见SFT和RL工具和训练方式，能结合业务情况选择合适手段达到预期目标\n\n课题要求\n学历和专业要求：计算机科学、人工智能、数据科学等相关专业的博士 / 硕士研究生优先，具备扎实的算法理论基础。\n\n技术技能要求：精通深度学习框架，熟悉超大模型训练；掌握推荐系统、召回 / 排序算法及多目标优化机制；具备LLM开发、调优经验。\n软性素质要求：具备极强的逻辑推理能力与跨团队协作能力，对技术细节有极致追求，能够独立推动算法项目从模型研发到线上落地的全流程。\n\nWXG\n微信事业群\n\n微信视频号团队\n微信视频号团队专注于视频、直播、交易、加热等业务，致力于通过技术连接海量创作者、用户与商家。我们基于实时、超大规模推荐架构与推荐工程平台，持续优化内容分发效率，探索前沿推荐范式，帮助用户快速发现优质内容，同时拥抱AIGC技术，覆盖多模态基础模型研发与后训练，以AI创作模板辅助创作者创作，提升创作效率与表达能力。期待你的加入，在服务创作者、连接用户的过程中，与团队一起实现更有温度的连接，创造可持续的长期价值。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1282757520922109953","sourceKey":"tencent","company":"腾讯","title":"微信视频号-加热Agent智能投放与素材生成算法研究","city":"广州","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1282757520922109953","duty":"课题背景：投放与创意生产正在从\"人工盯盘、经验调优、拍摄剪辑\"升级为\"AI 全流程自动托管\"——未来广告主只需说清目标，一个 24 小时在线的\"AI 数字投手\"即可自主完成从广告诊断、策略制定、素材生成到自动出价的全链路托管。这需要把 LLM 的理解与推理能力、Agent 的感知—决策—执行闭环、生成式模型的多模态创意能力，与真实广告投放系统的反馈信号深度融合，让 AI 具备可持续进化的投放与创意能力，最大化广告主长短期收益。\n\n\n课题挑战：\n1.让 Agent 理解复杂、模糊的投放目标（如\"稳 ROI 拉量、控成本\"），并自主拆解为投放调控与素材生产的动作序列；\n2.让生成的素材不仅\"看起来可投放\"，更能真正带来转化——把点击 / 转化反馈归因回生成模型，形成 ROI 导向的创意闭环，同时满足主体一致性、平台调性与广告合规；\n3.在高动态、强反馈延迟的竞价环境中，实现稳定、可解释、可回滚的策略调整，避免\"幻觉决策\"造成投放事故；\n4.构建面向广告业务的长期记忆与领域知识库，并搭建低成本试错的仿真与评估体系，使 AI 投手持续自我迭代。\n\n\n具体工作：\n1. 智能投放：自动化广告托管、Agent智能决策、Agent全链路闭环优化\n2. AIGC素材生成：面向投放的文生图、图生图、文生视频、图生视频能力优化","requirements":"学历和专业要求：计算机科学、人工智能、数据科学等相关专业的博士 / 硕士研究生，具备扎实的算法理论基础。\n技术技能要求：深入理解 LLM 应用开发，熟练掌握 LangChain 等框架，有 RAG、Function Calling、Memory Mechanism 的实际落地经验；在多模态生成 / 多模态理解领域有深入理解与实际项目经验，掌握扩散模型 / DiT 等生成模型原理；\n\n软性素质要求：问题抽象与拆解能力强，主动推进意识强，注重落地实际效果与业务价值；自驱、务实，能从真实业务 / 用户反馈中发现问题并驱动优化；沟通协作与工程落地能力强，对技术细节有极致追求。","description":"课题描述\n课题背景：投放与创意生产正在从\"人工盯盘、经验调优、拍摄剪辑\"升级为\"AI 全流程自动托管\"——未来广告主只需说清目标，一个 24 小时在线的\"AI 数字投手\"即可自主完成从广告诊断、策略制定、素材生成到自动出价的全链路托管。这需要把 LLM 的理解与推理能力、Agent 的感知—决策—执行闭环、生成式模型的多模态创意能力，与真实广告投放系统的反馈信号深度融合，让 AI 具备可持续进化的投放与创意能力，最大化广告主长短期收益。\n\n\n课题挑战：\n1.让 Agent 理解复杂、模糊的投放目标（如\"稳 ROI 拉量、控成本\"），并自主拆解为投放调控与素材生产的动作序列；\n2.让生成的素材不仅\"看起来可投放\"，更能真正带来转化——把点击 / 转化反馈归因回生成模型，形成 ROI 导向的创意闭环，同时满足主体一致性、平台调性与广告合规；\n3.在高动态、强反馈延迟的竞价环境中，实现稳定、可解释、可回滚的策略调整，避免\"幻觉决策\"造成投放事故；\n4.构建面向广告业务的长期记忆与领域知识库，并搭建低成本试错的仿真与评估体系，使 AI 投手持续自我迭代。\n\n\n具体工作：\n1. 智能投放：自动化广告托管、Agent智能决策、Agent全链路闭环优化\n2. AIGC素材生成：面向投放的文生图、图生图、文生视频、图生视频能力优化\n\n课题要求\n学历和专业要求：计算机科学、人工智能、数据科学等相关专业的博士 / 硕士研究生，具备扎实的算法理论基础。\n技术技能要求：深入理解 LLM 应用开发，熟练掌握 LangChain 等框架，有 RAG、Function Calling、Memory Mechanism 的实际落地经验；在多模态生成 / 多模态理解领域有深入理解与实际项目经验，掌握扩散模型 / DiT 等生成模型原理；\n\n软性素质要求：问题抽象与拆解能力强，主动推进意识强，注重落地实际效果与业务价值；自驱、务实，能从真实业务 / 用户反馈中发现问题并驱动优化；沟通协作与工程落地能力强，对技术细节有极致追求。\n\nWXG\n微信事业群\n\n微信视频号团队\n微信视频号团队专注于视频、直播、交易、加热等业务，致力于通过技术连接海量创作者、用户与商家。我们基于实时、超大规模推荐架构与推荐工程平台，持续优化内容分发效率，探索前沿推荐范式，帮助用户快速发现优质内容，同时拥抱AIGC技术，覆盖多模态基础模型研发与后训练，以AI创作模板辅助创作者创作，提升创作效率与表达能力。期待你的加入，在服务创作者、连接用户的过程中，与团队一起实现更有温度的连接，创造可持续的长期价值。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1282757520922109954","sourceKey":"tencent","company":"腾讯","title":"微信小微主动推荐 - 主动智能与持续学习 Agent 研究","city":"广州","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1282757520922109954","duty":"项目背景：目前 AI 大多等用户提出明确问题，但很多真实需求并不会被直接说出来。小微处在微信场景内，有机会逐渐了解用户正在经历什么，世界在发生什么，在合适的时机提供有用的信息和帮助，并根据用户后续反应不断调整。期望以大量真实交互为基础，探索从“被动回答”走向“持续学习和主动服务”。\n\n课题挑战：Agent 需要从对话、微信全域信息和内容消息中，形成对用户与世界持续更新的理解；面对大量可能的服务，完成需求发现、信息获取、规划和个性化生成；并从真实但稀疏、含噪的用户反馈中学习，期望实现跨用户、跨任务的能力迁移。\n\n具体工作：\n1. 设计大模型持续学习机制，基于用户真实交互反馈，以及微信全域内容数据训练大模型，研究持续学习、知识共享与群体能力涌现。\n2. 设计 Agent 系统，综合多源信息，完成对用户的持续理解，对世界知识的持续补充，提供服务的推荐和表达，并结合用户反馈持续优化。","requirements":"学历和专业要求：计算机、人工智能、数学等相关专业博士或优秀硕士应届生优先，具备扎实的机器学习基础。\n\n技术技能要求：在大模型架构、预训练与后训练、强化学习、持续学习方向有顶尖成果；具备以下任一方向研究或实践经验者优先：Agentic RL、Long horizon Agent、Memory、Self-evolve 等。\n\n软性素质要求：具备优秀的原创思考、问题抽象和实验能力，敢于挑战高风险问题；自驱务实，沟通协作和落地能力强。","description":"课题描述\n项目背景：目前 AI 大多等用户提出明确问题，但很多真实需求并不会被直接说出来。小微处在微信场景内，有机会逐渐了解用户正在经历什么，世界在发生什么，在合适的时机提供有用的信息和帮助，并根据用户后续反应不断调整。期望以大量真实交互为基础，探索从“被动回答”走向“持续学习和主动服务”。\n\n课题挑战：Agent 需要从对话、微信全域信息和内容消息中，形成对用户与世界持续更新的理解；面对大量可能的服务，完成需求发现、信息获取、规划和个性化生成；并从真实但稀疏、含噪的用户反馈中学习，期望实现跨用户、跨任务的能力迁移。\n\n具体工作：\n1. 设计大模型持续学习机制，基于用户真实交互反馈，以及微信全域内容数据训练大模型，研究持续学习、知识共享与群体能力涌现。\n2. 设计 Agent 系统，综合多源信息，完成对用户的持续理解，对世界知识的持续补充，提供服务的推荐和表达，并结合用户反馈持续优化。\n\n课题要求\n学历和专业要求：计算机、人工智能、数学等相关专业博士或优秀硕士应届生优先，具备扎实的机器学习基础。\n\n技术技能要求：在大模型架构、预训练与后训练、强化学习、持续学习方向有顶尖成果；具备以下任一方向研究或实践经验者优先：Agentic RL、Long horizon Agent、Memory、Self-evolve 等。\n\n软性素质要求：具备优秀的原创思考、问题抽象和实验能力，敢于挑战高风险问题；自驱务实，沟通协作和落地能力强。\n\nWXG\n微信事业群\n\n微信视频号团队\n微信视频号团队专注于视频、直播、交易、加热等业务，致力于通过技术连接海量创作者、用户与商家。我们基于实时、超大规模推荐架构与推荐工程平台，持续优化内容分发效率，探索前沿推荐范式，帮助用户快速发现优质内容，同时拥抱AIGC技术，覆盖多模态基础模型研发与后训练，以AI创作模板辅助创作者创作，提升创作效率与表达能力。期待你的加入，在服务创作者、连接用户的过程中，与团队一起实现更有温度的连接，创造可持续的长期价值。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1287215417483756544","sourceKey":"tencent","company":"腾讯","title":"微信-小微主动推荐 - 主动智能与持续学习 Agent 研究","city":"北京/广州","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1287215417483756544","duty":"项目背景：目前 AI 大多等用户提出明确问题，但很多真实需求并不会被直接说出来。小微处在微信场景内，有机会逐渐了解用户正在经历什么，世界在发生什么，在合适的时机提供有用的信息和帮助，并根据用户后续反应不断调整。期望以大量真实交互为基础，探索从“被动回答”走向“持续学习和主动服务”。\n\n课题挑战：Agent 需要从对话、微信全域信息和内容消息中，形成对用户与世界持续更新的理解；面对大量可能的服务，完成需求发现、信息获取、规划和个性化生成；并从真实但稀疏、含噪的用户反馈中学习，期望实现跨用户、跨任务的能力迁移。\n\n具体工作：\n1. 设计大模型持续学习机制，基于用户真实交互反馈，以及微信全域内容数据训练大模型，研究持续学习、知识共享与群体能力涌现。\n2. 设计 Agent 系统，综合多源信息，完成对用户的持续理解，对世界知识的持续补充，提供服务的推荐和表达，并结合用户反馈持续优化。","requirements":"学历和专业要求：计算机、人工智能、数学等相关专业博士或优秀硕士应届生优先，具备扎实的机器学习基础。\n\n技术技能要求：在大模型架构、预训练与后训练、强化学习、持续学习方向有顶尖成果；具备以下任一方向研究或实践经验者优先：Agentic RL、Long horizon Agent、Memory、Self-evolve 等。\n\n软性素质要求：具备优秀的原创思考、问题抽象和实验能力，敢于挑战高风险问题；自驱务实，沟通协作和落地能力强。","description":"课题描述\n项目背景：目前 AI 大多等用户提出明确问题，但很多真实需求并不会被直接说出来。小微处在微信场景内，有机会逐渐了解用户正在经历什么，世界在发生什么，在合适的时机提供有用的信息和帮助，并根据用户后续反应不断调整。期望以大量真实交互为基础，探索从“被动回答”走向“持续学习和主动服务”。\n\n课题挑战：Agent 需要从对话、微信全域信息和内容消息中，形成对用户与世界持续更新的理解；面对大量可能的服务，完成需求发现、信息获取、规划和个性化生成；并从真实但稀疏、含噪的用户反馈中学习，期望实现跨用户、跨任务的能力迁移。\n\n具体工作：\n1. 设计大模型持续学习机制，基于用户真实交互反馈，以及微信全域内容数据训练大模型，研究持续学习、知识共享与群体能力涌现。\n2. 设计 Agent 系统，综合多源信息，完成对用户的持续理解，对世界知识的持续补充，提供服务的推荐和表达，并结合用户反馈持续优化。\n\n课题要求\n学历和专业要求：计算机、人工智能、数学等相关专业博士或优秀硕士应届生优先，具备扎实的机器学习基础。\n\n技术技能要求：在大模型架构、预训练与后训练、强化学习、持续学习方向有顶尖成果；具备以下任一方向研究或实践经验者优先：Agentic RL、Long horizon Agent、Memory、Self-evolve 等。\n\n软性素质要求：具备优秀的原创思考、问题抽象和实验能力，敢于挑战高风险问题；自驱务实，沟通协作和落地能力强。\n\nWXG\n微信事业群\n\n微信视频号团队\n微信视频号团队专注于视频、直播、交易、加热等业务，致力于通过技术连接海量创作者、用户与商家。我们基于实时、超大规模推荐架构与推荐工程平台，持续优化内容分发效率，探索前沿推荐范式，帮助用户快速发现优质内容，同时拥抱AIGC技术，覆盖多模态基础模型研发与后训练，以AI创作模板辅助创作者创作，提升创作效率与表达能力。期待你的加入，在服务创作者、连接用户的过程中，与团队一起实现更有温度的连接，创造可持续的长期价值。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1287771593065775104","sourceKey":"tencent","company":"腾讯","title":"混元基座模型——多模态理解预训练结构与算法研究","city":"深圳总部/北京/上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1287771593065775104","duty":"课题背景：\n1. 多模态模型结构设计：视觉编码器、跨模态融合模块、MoE、Attention上的新架构层出不穷，如何设计更高效、更具扩展性的多模态模型结构仍充满挑战。\n2. 训练效率与成本：超大规模 VLM 训练需要兼顾模型效果、训练效率和推理成本，在算力约束下不断逼近性能上限。\n3. 能力持续演进：如何让模型在 OCR、GUI、视频、Agent、长视觉上下文等复杂场景持续获得泛化能力，是当前多模态领域的重要研究方向。\n\n具体工作：\n你将参与混元多模态基座模型的核心结构与预训练算法研发，探索视觉编码器、跨模态融合、注意力机制、MoE、多模态训练策略等关键技术；设计并验证新型模型结构和预训练算法，在大规模分布式训练平台完成实验验证，不断提升多模态模型的理解、推理和生成能力；你将有机会参与业界领先的多模态基础模型研发，将创新成果沉淀为顶级学术论文、开源项目或核心技术专利，推动下一代多模态大模型的发展。","requirements":"1. 自然语言处理/机器学习/模式识别/人工智能/计算机等相关专业硕士以上学历；\n2. 在NLP、LLM、深度学习、强化学习方面有一定研究基础，熟悉主流模型和算法，并有一定的实践经验；\n3. 较强的工程实现能力，熟练掌握C/C++，Python等至少一种语言，有实际编程项目经验，熟悉DeepSpeed、Megatron等分布式训练框架，熟练使用至少一种深度学习框架(如TensorFlow，PyTorch等)；\n4. 有高质量论文发表者优先（如ACL、EMNLP、NeurIPS、ICML、ICLR等)；\n5. 具备强烈的进取心、自驱力及团队合作精神，热衷于追求技术创新。","description":"课题描述\n课题背景：\n1. 多模态模型结构设计：视觉编码器、跨模态融合模块、MoE、Attention上的新架构层出不穷，如何设计更高效、更具扩展性的多模态模型结构仍充满挑战。\n2. 训练效率与成本：超大规模 VLM 训练需要兼顾模型效果、训练效率和推理成本，在算力约束下不断逼近性能上限。\n3. 能力持续演进：如何让模型在 OCR、GUI、视频、Agent、长视觉上下文等复杂场景持续获得泛化能力，是当前多模态领域的重要研究方向。\n\n具体工作：\n你将参与混元多模态基座模型的核心结构与预训练算法研发，探索视觉编码器、跨模态融合、注意力机制、MoE、多模态训练策略等关键技术；设计并验证新型模型结构和预训练算法，在大规模分布式训练平台完成实验验证，不断提升多模态模型的理解、推理和生成能力；你将有机会参与业界领先的多模态基础模型研发，将创新成果沉淀为顶级学术论文、开源项目或核心技术专利，推动下一代多模态大模型的发展。\n\n课题要求\n1. 自然语言处理/机器学习/模式识别/人工智能/计算机等相关专业硕士以上学历；\n2. 在NLP、LLM、深度学习、强化学习方面有一定研究基础，熟悉主流模型和算法，并有一定的实践经验；\n3. 较强的工程实现能力，熟练掌握C/C++，Python等至少一种语言，有实际编程项目经验，熟悉DeepSpeed、Megatron等分布式训练框架，熟练使用至少一种深度学习框架(如TensorFlow，PyTorch等)；\n4. 有高质量论文发表者优先（如ACL、EMNLP、NeurIPS、ICML、ICLR等)；\n5. 具备强烈的进取心、自驱力及团队合作精神，热衷于追求技术创新。\n\nTEG\n技术工程事业群\n\n腾讯混元基础模型部\n基础模型部负责混元大模型的前沿技术探索与基础模型研发，聚焦模型结构、数据与训练策略、强化学习及Agent能力，协同各模态研发能力，高效开发并迭代基础模型架构，面向AGI愿景探索智能上限、确保技术领先；同时构建基于大模型的AI PaaS中台能力，赋能公司内外部的产品创新与业务应用。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1287771593065775105","sourceKey":"tencent","company":"腾讯","title":"混元基座模型-原生 VLM 预训练与Midtrain","city":"深圳总部/北京/上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1287771593065775105","duty":"课题背景\n原生 VLM 需要从预训练阶段统一学习文本、图像、文档、图表和视频等多模态知识，并在中期训练阶段进一步强化视觉理解、跨模态推理和任务执行能力。\n当前，多模态预训练数据普遍存在质量低、图文错配和长尾知识不足等问题；文档、图表、空间推理、GUI、Agent 等高质量能力数据又较为稀缺。如何打通多模态数据清洗、科学配比、高质量合成和动态调度链路，是提升 VLM 能力上限的关键。\n\n课题挑战\n1、多模态数据质量参差： 在 PB 级数据中高效识别低质、重复和错配样本，同时保留高价值长尾知识。\n2、多领域训练相互干扰： 视觉、语言及不同任务领域学习规律差异较大，混合训练容易出现能力退化和负迁移，如何在保证文本能力的前提下追求视觉能力的极致优化。\n3、高质量能力数据稀缺： 合成数据容易模板化、难度不足和错误累积，缺乏高效可靠的质量评估与调度指标。\n\n具体工作\n1、负责图像、网页、文档、图表和视频等多模态数据的挖掘、清洗、筛选与质量评估；\n2、探索原生 VLM 预训练及中期训练的数据配比、训练目标和阶段衔接策略；\n3、负责 OCR、文档、图表、空间推理、GUI、Agent 等领域数据的挖掘与高质量合成；\n4、设计多领域数据动态调度策略，并在生产级模型上验证训练效果。","requirements":"1、自然语言处理/机器学习/模式识别/人工智能/计算机等相关专业硕士以上学历；\r\n2、相信 Scaling Law，认可数据、算力与模型规模化带来的长期价值，善于通过系统实验验证规律；\r\n3、具备较强的工程能力，能够搭建高效、稳定、可复现的数据与训练链路，并持续优化工具和研发效率；\r\n4、对数据和指标高度敏感，认真严谨，能够从细微异常中发现问题并追溯根因；\r\n5、兼具研究探索能力与落地意识，能够独立推进方案设计、工程实现和生产级模型验证。","description":"课题描述\n课题背景\n原生 VLM 需要从预训练阶段统一学习文本、图像、文档、图表和视频等多模态知识，并在中期训练阶段进一步强化视觉理解、跨模态推理和任务执行能力。\n当前，多模态预训练数据普遍存在质量低、图文错配和长尾知识不足等问题；文档、图表、空间推理、GUI、Agent 等高质量能力数据又较为稀缺。如何打通多模态数据清洗、科学配比、高质量合成和动态调度链路，是提升 VLM 能力上限的关键。\n\n课题挑战\n1、多模态数据质量参差： 在 PB 级数据中高效识别低质、重复和错配样本，同时保留高价值长尾知识。\n2、多领域训练相互干扰： 视觉、语言及不同任务领域学习规律差异较大，混合训练容易出现能力退化和负迁移，如何在保证文本能力的前提下追求视觉能力的极致优化。\n3、高质量能力数据稀缺： 合成数据容易模板化、难度不足和错误累积，缺乏高效可靠的质量评估与调度指标。\n\n具体工作\n1、负责图像、网页、文档、图表和视频等多模态数据的挖掘、清洗、筛选与质量评估；\n2、探索原生 VLM 预训练及中期训练的数据配比、训练目标和阶段衔接策略；\n3、负责 OCR、文档、图表、空间推理、GUI、Agent 等领域数据的挖掘与高质量合成；\n4、设计多领域数据动态调度策略，并在生产级模型上验证训练效果。\n\n课题要求\n1、自然语言处理/机器学习/模式识别/人工智能/计算机等相关专业硕士以上学历；\r\n2、相信 Scaling Law，认可数据、算力与模型规模化带来的长期价值，善于通过系统实验验证规律；\r\n3、具备较强的工程能力，能够搭建高效、稳定、可复现的数据与训练链路，并持续优化工具和研发效率；\r\n4、对数据和指标高度敏感，认真严谨，能够从细微异常中发现问题并追溯根因；\r\n5、兼具研究探索能力与落地意识，能够独立推进方案设计、工程实现和生产级模型验证。\n\nTEG\n技术工程事业群\n\n腾讯混元基础模型部\n基础模型部负责混元大模型的前沿技术探索与基础模型研发，聚焦模型结构、数据与训练策略、强化学习及Agent能力，协同各模态研发能力，高效开发并迭代基础模型架构，面向AGI愿景探索智能上限、确保技术领先；同时构建基于大模型的AI PaaS中台能力，赋能公司内外部的产品创新与业务应用。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1287771601961893888","sourceKey":"tencent","company":"腾讯","title":"混元基座模型——多模态Agent评测研究","city":"深圳总部/北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1287771601961893888","duty":"课题背景：\n随着模型多模态能力的快速进步，多模态Agent评测受到越来越多的挑战。随着AI下半场的到来，前沿的评测也成为迫切的需求，不仅可以客观反映模型的能力，而且能为Agent未来的迭代指出方向。\n\n课题挑战：\n如何高效可靠地建立多模态Agent评测环境是一个开放性问题，特别是随着模型能力的提升，复杂环境的构建越来越重要同时越来越困难。\n\n具体工作：\n本课题关注于前沿多模态Agent评测方向的探索、评测环境的构建与数据的可靠合成。","requirements":"1、自然语言处理/机器学习/模式识别/人工智能/计算机等相关专业；\r\n2、在NLP、LLM领域有深入实践，对生成式AI、复杂推理或特定垂域（如代码生成、数学定理证明等）有丰富的数据构建与模型调优经验；\r\n3、较强的工程实现能力，熟练掌握Python、C/C++等至少一种语言，熟悉指令演化（如Self-Instruct等）及合成数据Pipeline架构；\r\n4、熟悉DeepSpeed、Megatron等分布式训练框架，熟练使用至少一种深度学习框架(如PyTorch等)；\r\n5、有高质量论文发表者优先（如ACL、EMNLP、NeurIPS、ICML、ICLR等），特别是在数据合成、模型微调或特定垂域能力突破方向；\r\n6、具备强烈的进取心、自驱力及跨领域学习能力，团队合作精神极佳，对实现AGI核心能力跃迁充满热情。","description":"课题描述\n课题背景：\n随着模型多模态能力的快速进步，多模态Agent评测受到越来越多的挑战。随着AI下半场的到来，前沿的评测也成为迫切的需求，不仅可以客观反映模型的能力，而且能为Agent未来的迭代指出方向。\n\n课题挑战：\n如何高效可靠地建立多模态Agent评测环境是一个开放性问题，特别是随着模型能力的提升，复杂环境的构建越来越重要同时越来越困难。\n\n具体工作：\n本课题关注于前沿多模态Agent评测方向的探索、评测环境的构建与数据的可靠合成。\n\n课题要求\n1、自然语言处理/机器学习/模式识别/人工智能/计算机等相关专业；\r\n2、在NLP、LLM领域有深入实践，对生成式AI、复杂推理或特定垂域（如代码生成、数学定理证明等）有丰富的数据构建与模型调优经验；\r\n3、较强的工程实现能力，熟练掌握Python、C/C++等至少一种语言，熟悉指令演化（如Self-Instruct等）及合成数据Pipeline架构；\r\n4、熟悉DeepSpeed、Megatron等分布式训练框架，熟练使用至少一种深度学习框架(如PyTorch等)；\r\n5、有高质量论文发表者优先（如ACL、EMNLP、NeurIPS、ICML、ICLR等），特别是在数据合成、模型微调或特定垂域能力突破方向；\r\n6、具备强烈的进取心、自驱力及跨领域学习能力，团队合作精神极佳，对实现AGI核心能力跃迁充满热情。\n\nTEG\n技术工程事业群\n\n腾讯混元基础模型部\n基础模型部负责混元大模型的前沿技术探索与基础模型研发，聚焦模型结构、数据与训练策略、强化学习及Agent能力，协同各模态研发能力，高效开发并迭代基础模型架构，面向AGI愿景探索智能上限、确保技术领先；同时构建基于大模型的AI PaaS中台能力，赋能公司内外部的产品创新与业务应用。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1287771601961893889","sourceKey":"tencent","company":"腾讯","title":"混元基座模型——模型结构设计","city":"深圳总部/北京/上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1287771601961893889","duty":"课题背景\n随着大语言模型规模不断增长，模型结构设计已成为决定模型能力、训练效率和推理成本的核心因素。如何突破传统Transformer架构瓶颈，在Attention、MoE、记忆机制等关键模块上持续创新，构建兼具性能、效率与可扩展性的新一代模型架构，已成为大模型领域的重要研究方向。本课题聚焦前沿模型结构创新，探索更具潜力的大模型架构设计。\n\n课题挑战\n模型结构设计需要同时兼顾模型效果、训练稳定性、推理效率和工程可部署性，多个目标之间存在复杂权衡。Attention、MoE、Engram等模块之间相互耦合，单一模块优化可能带来整体性能退化，需要从系统角度进行协同设计。同时，新架构往往缺乏成熟经验，每次验证均需要大规模预训练实验，实验成本高、迭代周期长；此外，新结构还需具备良好的跨规模扩展能力，在不同模型尺寸和训练阶段保持稳定收益，才能真正应用于新一代基础模型。\n\n具体工作\n参与大模型核心架构设计，研究Attention、MoE、Engram等关键模块，完成算法设计、实现与大规模训练验证，分析实验结果，持续优化模型性能与训练效率，并推动创新成果落地。","requirements":"1、自然语言处理/机器学习/模式识别/人工智能/计算机等相关专业硕士以上学历；\r\n2、在NLP、LLM、深度学习、强化学习方面有一定研究基础，熟悉主流模型和算法，并有一定的实践经验；\r\n3、较强的工程实现能力，熟练掌握C/C++，Python等至少一种语言，有实际编程项目经验，熟悉DeepSpeed、Megatron等分布式训练框架，熟练使用至少一种深度学习框架(如TensorFlow，PyTorch等)；\r\n4、有高质量论文发表者优先（如ACL、EMNLP、NeurIPS、ICML、ICLR等)；\r\n5、具备强烈的进取心、自驱力及团队合作精神，热衷于追求技术创新。","description":"课题描述\n课题背景\n随着大语言模型规模不断增长，模型结构设计已成为决定模型能力、训练效率和推理成本的核心因素。如何突破传统Transformer架构瓶颈，在Attention、MoE、记忆机制等关键模块上持续创新，构建兼具性能、效率与可扩展性的新一代模型架构，已成为大模型领域的重要研究方向。本课题聚焦前沿模型结构创新，探索更具潜力的大模型架构设计。\n\n课题挑战\n模型结构设计需要同时兼顾模型效果、训练稳定性、推理效率和工程可部署性，多个目标之间存在复杂权衡。Attention、MoE、Engram等模块之间相互耦合，单一模块优化可能带来整体性能退化，需要从系统角度进行协同设计。同时，新架构往往缺乏成熟经验，每次验证均需要大规模预训练实验，实验成本高、迭代周期长；此外，新结构还需具备良好的跨规模扩展能力，在不同模型尺寸和训练阶段保持稳定收益，才能真正应用于新一代基础模型。\n\n具体工作\n参与大模型核心架构设计，研究Attention、MoE、Engram等关键模块，完成算法设计、实现与大规模训练验证，分析实验结果，持续优化模型性能与训练效率，并推动创新成果落地。\n\n课题要求\n1、自然语言处理/机器学习/模式识别/人工智能/计算机等相关专业硕士以上学历；\r\n2、在NLP、LLM、深度学习、强化学习方面有一定研究基础，熟悉主流模型和算法，并有一定的实践经验；\r\n3、较强的工程实现能力，熟练掌握C/C++，Python等至少一种语言，有实际编程项目经验，熟悉DeepSpeed、Megatron等分布式训练框架，熟练使用至少一种深度学习框架(如TensorFlow，PyTorch等)；\r\n4、有高质量论文发表者优先（如ACL、EMNLP、NeurIPS、ICML、ICLR等)；\r\n5、具备强烈的进取心、自驱力及团队合作精神，热衷于追求技术创新。\n\nTEG\n技术工程事业群\n\n腾讯混元基础模型部\n基础模型部负责混元大模型的前沿技术探索与基础模型研发，聚焦模型结构、数据与训练策略、强化学习及Agent能力，协同各模态研发能力，高效开发并迭代基础模型架构，面向AGI愿景探索智能上限、确保技术领先；同时构建基于大模型的AI PaaS中台能力，赋能公司内外部的产品创新与业务应用。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1292597525697903616","sourceKey":"tencent","company":"腾讯","title":"腾讯游戏-面向多模态生成的理解算法研究","city":"深圳总部/北京/上海/杭州","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1292597525697903616","duty":"多模态生成大模型的训练和推理离不开多模态理解算法，且生成任务对于理解有其独特的需求。该项目希望能够研究最适合多模态生成大模型的理解能力，重点包括但不限于：\n1. 对多模态音视频进行有重点、准确的文本描述（Caption能力），提升多模态生成的效果。\n2. 精准理解多模态上下文（比如图像、视频、动作、身份ID、镜头等）的关联关系，构建高质量的参考、编辑等指令。\n3. 将用户的Prompt和意图通过理解模型准确转化为多模态生成模型的输入，提高多模态生成系统整体的效果和智能。","requirements":"1. 熟悉多模态理解技术，有VLM模型的核心经验。\n2. 具备大模型训练、调参、实验分析和问题排查能力。\n3. 对数据有感觉、认同数据价值，能够深入分析数据、构建数据方案。\n4. 好奇心强，思路灵活，做事认真负责，愿意挑战开放问题。\n5. 熟练使用 AI 工具提升研发效率。\n\n加分项\n1. 有大规模预训练、VLM模型训练直接经验。\n2. 有顶会论文、开源项目、产品落地经验等。\n3. 在ACM、NOI等竞赛中取得优秀成绩。","description":"课题描述\n多模态生成大模型的训练和推理离不开多模态理解算法，且生成任务对于理解有其独特的需求。该项目希望能够研究最适合多模态生成大模型的理解能力，重点包括但不限于：\n1. 对多模态音视频进行有重点、准确的文本描述（Caption能力），提升多模态生成的效果。\n2. 精准理解多模态上下文（比如图像、视频、动作、身份ID、镜头等）的关联关系，构建高质量的参考、编辑等指令。\n3. 将用户的Prompt和意图通过理解模型准确转化为多模态生成模型的输入，提高多模态生成系统整体的效果和智能。\n\n课题要求\n1. 熟悉多模态理解技术，有VLM模型的核心经验。\n2. 具备大模型训练、调参、实验分析和问题排查能力。\n3. 对数据有感觉、认同数据价值，能够深入分析数据、构建数据方案。\n4. 好奇心强，思路灵活，做事认真负责，愿意挑战开放问题。\n5. 熟练使用 AI 工具提升研发效率。\n\n加分项\n1. 有大规模预训练、VLM模型训练直接经验。\n2. 有顶会论文、开源项目、产品落地经验等。\n3. 在ACM、NOI等竞赛中取得优秀成绩。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1292597534933761024","sourceKey":"tencent","company":"腾讯","title":"腾讯混元基座模型-大模型预训练动力学研究","city":"深圳总部/北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1292597534933761024","duty":"课题背景&挑战\n1. 训练过程的高度不确定性：大模型训练中存在大量随机因素和非线性动力学行为，准确预警和干预极具挑战性\n2. 因果关系的复杂性：需要区分相关性与因果关系，在数十亿参数空间中建立可靠的因果推断链条\n3. 实验成本极其高昂：每次完整训练实验都需要巨大的计算资源和时间成本，对实验设计提出极高要求\n4. 跨规模规律的外推性：从小规模实验推导出的规律是否能够有效迁移到更大规模模型尚待验证\n5. 工程与理论的平衡：需要在系统实现复杂度和理论严谨性之间找到合适的平衡点\n\n具体工作：\n你将参与到前沿的大模型预训练稳定性研究中，深入探索Transformer架构下的优化动力学特性；你将有机会设计并实现创新的监控指标、干预机制与优化算法，积累大规模分布式训练的系统级经验；你将通过严谨的实验设计和因果分析，为行业建立可靠的大模型训练最佳实践；你还可能将研究成果转化为学术论文或技术专利，为未来的模型训练范式提供理论支撑和实践指导。","requirements":"学历和专业要求：\n自然语言处理/机器学习/模式识别/人工智能/计算机等相关专业硕士以上学历；\n\n技术技能要求：\n1.在NLP、LLM、深度学习、强化学习方面有一定研究基础，熟悉主流模型和算法，并有一定的实践经验；\n2.较强的工程实现能力，熟练掌握C/C++，Python等至少一种语言，有实际编程项目经验，熟悉DeepSpeed、Megatron等分布式训练框架，熟练使用至少一种深度学习框架(如TensorFlow，PyTorch等)；\n3.有高质量论文发表者优先（如ACL、EMNLP、NeurIPS、ICML、ICLR等)；\n\n软性素质要求：\n具备强烈的进取心、自驱力及团队合作精神，热衷于追求技术创新。","description":"课题描述\n课题背景&挑战\n1. 训练过程的高度不确定性：大模型训练中存在大量随机因素和非线性动力学行为，准确预警和干预极具挑战性\n2. 因果关系的复杂性：需要区分相关性与因果关系，在数十亿参数空间中建立可靠的因果推断链条\n3. 实验成本极其高昂：每次完整训练实验都需要巨大的计算资源和时间成本，对实验设计提出极高要求\n4. 跨规模规律的外推性：从小规模实验推导出的规律是否能够有效迁移到更大规模模型尚待验证\n5. 工程与理论的平衡：需要在系统实现复杂度和理论严谨性之间找到合适的平衡点\n\n具体工作：\n你将参与到前沿的大模型预训练稳定性研究中，深入探索Transformer架构下的优化动力学特性；你将有机会设计并实现创新的监控指标、干预机制与优化算法，积累大规模分布式训练的系统级经验；你将通过严谨的实验设计和因果分析，为行业建立可靠的大模型训练最佳实践；你还可能将研究成果转化为学术论文或技术专利，为未来的模型训练范式提供理论支撑和实践指导。\n\n课题要求\n学历和专业要求：\n自然语言处理/机器学习/模式识别/人工智能/计算机等相关专业硕士以上学历；\n\n技术技能要求：\n1.在NLP、LLM、深度学习、强化学习方面有一定研究基础，熟悉主流模型和算法，并有一定的实践经验；\n2.较强的工程实现能力，熟练掌握C/C++，Python等至少一种语言，有实际编程项目经验，熟悉DeepSpeed、Megatron等分布式训练框架，熟练使用至少一种深度学习框架(如TensorFlow，PyTorch等)；\n3.有高质量论文发表者优先（如ACL、EMNLP、NeurIPS、ICML、ICLR等)；\n\n软性素质要求：\n具备强烈的进取心、自驱力及团队合作精神，热衷于追求技术创新。\n\nTEG\n技术工程事业群\n\n腾讯混元基础模型部\n基础模型部负责混元大模型的前沿技术探索与基础模型研发，聚焦模型结构、数据与训练策略、强化学习及Agent能力，协同各模态研发能力，高效开发并迭代基础模型架构，面向AGI愿景探索智能上限、确保技术领先；同时构建基于大模型的AI PaaS中台能力，赋能公司内外部的产品创新与业务应用。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1292597534933761025","sourceKey":"tencent","company":"腾讯","title":"腾讯游戏-多模态生成大模型关键算法研究","city":"深圳总部/北京/上海/杭州","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1292597534933761025","duty":"研究多模态生成大模型，推动视频生成从少模态、短上下文，升级为丰富模态、长上下文的生成。使模型能够理解文本、图像、视频、音频、动作、镜头、ID等，能够理解用户的复杂意图。达到世界领先模型效果。重点研究包括但不限于：\n1. 多模态、长上下文的统一建模，研究多模态生成大模型的数据构建、架构与训练方法。\n2. 提升模型的精确控制、编辑能力和组合泛化能力；提升长视频生成中人物、物体、空间关系和视觉风格的一致性。\n3. 研究大规模数据和大规模模型扩展下，进一步提高模型上限。研究利用好用户数据和长程轨迹数据等。","requirements":"1. 熟悉多模态生成技术，有生成模型核心经验。\n2. 具备大模型训练、调参、实验分析和问题排查能力。\n3. 对数据有感觉、认同数据价值，能够深入分析数据、构建数据方案。\n4. 好奇心强，思路灵活，做事认真负责，愿意挑战开放问题。\n5. 熟练使用 AI 工具提升研发效率。\n\n加分项\n1. 有大规模预训练、多模态生成模型训练直接经验。\n2. 有顶会论文、开源项目、产品落地经验等。\n3. 在ACM、NOI等竞赛中取得优秀成绩。","description":"课题描述\n研究多模态生成大模型，推动视频生成从少模态、短上下文，升级为丰富模态、长上下文的生成。使模型能够理解文本、图像、视频、音频、动作、镜头、ID等，能够理解用户的复杂意图。达到世界领先模型效果。重点研究包括但不限于：\n1. 多模态、长上下文的统一建模，研究多模态生成大模型的数据构建、架构与训练方法。\n2. 提升模型的精确控制、编辑能力和组合泛化能力；提升长视频生成中人物、物体、空间关系和视觉风格的一致性。\n3. 研究大规模数据和大规模模型扩展下，进一步提高模型上限。研究利用好用户数据和长程轨迹数据等。\n\n课题要求\n1. 熟悉多模态生成技术，有生成模型核心经验。\n2. 具备大模型训练、调参、实验分析和问题排查能力。\n3. 对数据有感觉、认同数据价值，能够深入分析数据、构建数据方案。\n4. 好奇心强，思路灵活，做事认真负责，愿意挑战开放问题。\n5. 熟练使用 AI 工具提升研发效率。\n\n加分项\n1. 有大规模预训练、多模态生成模型训练直接经验。\n2. 有顶会论文、开源项目、产品落地经验等。\n3. 在ACM、NOI等竞赛中取得优秀成绩。\n\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制作效率和能力；研究「游戏引擎」核心技术并致力于图形学前沿探索，同时开发完全自主知识产权的「自研引擎」；研发业界领先的游戏在线服务及基础服务框架，聚焦提升「游戏GaaS化服务」能力；探索语音前沿领域，引领「游戏语音」行业技术演进；把握行业未来趋势，设计并实现高性能、高效能且安全的「编译编程系统」及工具链……\n加入我们，以领先技术赋能业务，提升用户娱乐品质！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1293194418543067136","sourceKey":"tencent","company":"腾讯","title":"元宝-面向复杂推理的多模态教育智能体研究","city":"深圳总部/北京/上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1293194418543067136","duty":"本课题聚焦面向复杂推理的多模态教育智能体，研究大模型在教育场景中的任务理解、推理规划、多模态交互、工具调用与自我纠错能力，推动教育智能体从“回答问题”升级为能够自主完成长链条复杂任务的智能系统。 面向数学、物理等典型场景，重点开展多模态推理数据构建、图文联合推理、Agent / Tool Use、视觉反馈与强化学习等研究，探索“边作图、边观察、边推理、边修正”的多模态推理范式，使模型能够将图形作为可读写的视觉工作空间，在几何证明、物理受力分析、函数图像等任务中主动构建和更新中间视觉状态，并利用视觉反馈推进后续推理。相关研究可应用于拍照解题、AI Tutor、解题过程演示、个性化辅导等教育产品场景。","requirements":"1、计算机、人工智能、计算机视觉、自然语言处理或相关专业硕士及以上学历，博士优先；具备多模态大模型、数学推理、视觉空间推理或 Agent 等方向研究背景；\r\n2、精通 PyTorch 等深度学习框架，熟悉主流大模型训练、微调与推理方法，具备 SFT、强化学习、Agent / Tool Use 等实操经验；\r\n3、具备较强的科研与实验能力，能够围绕复杂推理中的任务规划、多模态状态建模、工具调用、视觉反馈和自我纠错等问题开展独立研究；有教育场景研究与应用经验者优先。","description":"课题描述\n本课题聚焦面向复杂推理的多模态教育智能体，研究大模型在教育场景中的任务理解、推理规划、多模态交互、工具调用与自我纠错能力，推动教育智能体从“回答问题”升级为能够自主完成长链条复杂任务的智能系统。 面向数学、物理等典型场景，重点开展多模态推理数据构建、图文联合推理、Agent / Tool Use、视觉反馈与强化学习等研究，探索“边作图、边观察、边推理、边修正”的多模态推理范式，使模型能够将图形作为可读写的视觉工作空间，在几何证明、物理受力分析、函数图像等任务中主动构建和更新中间视觉状态，并利用视觉反馈推进后续推理。相关研究可应用于拍照解题、AI Tutor、解题过程演示、个性化辅导等教育产品场景。\n\n课题要求\n1、计算机、人工智能、计算机视觉、自然语言处理或相关专业硕士及以上学历，博士优先；具备多模态大模型、数学推理、视觉空间推理或 Agent 等方向研究背景；\r\n2、精通 PyTorch 等深度学习框架，熟悉主流大模型训练、微调与推理方法，具备 SFT、强化学习、Agent / Tool Use 等实操经验；\r\n3、具备较强的科研与实验能力，能够围绕复杂推理中的任务规划、多模态状态建模、工具调用、视觉反馈和自我纠错等问题开展独立研究；有教育场景研究与应用经验者优先。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1293194428185772032","sourceKey":"tencent","company":"腾讯","title":"混元基座模型-Code&Agent研究","city":"深圳总部/北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1293194428185772032","duty":"课题背景：\nAgent 正在成为下一代生产力系统的核心入口，也是通往 AGI 最重要的技术路径之一。\n\n我们团队致力于通过高质量数据构建与大规模强化学习，从预训练到后训练全链路持续提升混元基础模型的 Agentic 能力；同时探索新的 human-agent-environment 交互方式，推动模型能力与产品体验共同演进。\n我们希望 Agent 能真正成为普通人、开发者与科研工作者的生产力工具，并期待与你一起推动这件事发生。\n\n课题挑战：\n1.高质量 Agentic 数据构建：\n构建覆盖真实任务、工具调用和长程交互的高质量数据体系。解决任务生成、环境搭建、轨迹采集、结果验证以及难度与多样性控制等问题，规模化沉淀高价值数据。\n\n2.大规模 Agentic RL 训练：\n面向长时程、多步骤、稀疏奖励的 Agent 任务，探索稳定高效的强化学习方法。重点解决长轨迹信用分配、有效探索、奖励建模、训练稳定性和环境吞吐等问题，提升模型在复杂环境中的规划、执行与自我纠错能力。\n\n3.Agent Harness 设计：\n设计支撑 Agent 长程运行的系统框架，统一模型、工具与环境的交互边界，处理上下文管理、任务调度、状态持久化、并发执行与故障恢复。构建稳定、可扩展、可插拔的极简 Harness，实现脚手架与模型共同进化。\n\n4.Agent 可观测性设计：\n建立覆盖任务、模型、工具和环境的全链路观测体系，让 Agent 的执行过程能够被理解、评估和复现。围绕行为轨迹追踪、失败归因、能力评测、异常检测和线上反馈闭环，提升 Agent 的可调试性、可靠性与持续迭代效率。\n","requirements":"我们关注三个核心的方向：\n1.Coding Agent：你将深入参与 Coding Agent 的研究与落地，包括复杂代码库理解、工具调用、长链软件任务执行、真实环境交互、agent trajectory 建模、可验证训练数据构造，以及面向真实研发场景和用户体验的能力建设。核心目标是让 Agent 像真正的工程师一样完成端到端的软件工程任务。\n2.Productivity Agent：你将参与构建面向真实工作与生活场景的生产力 Agent，探索 computer use、多工具协同、长期记忆、个性化上下文建模、腾讯生态深度交互等关键能力，核心目标是让 Agent 成为真正能够与用户长期协作、越用越懂你的 coworker。\n3.Research Agent：你将参与 Agent 在 AI 自动化与科学研发自动化中的前沿探索，包括自动化训练流程、实验系统构建、研究任务分解、反馈驱动迭代，以及迈向 AI Scientist 所需的能力基座设计。你将有机会参与定义 Agent 如何加速 AI 自身的发展，并进入更高价值的科学探索场景。\n课题要求\n技术技能要求：1.在 Agent、LLM 或相关方向有深入实践，对复杂任务求解、长链路推理、多工具调用、环境交互或特定应用场景有丰富的研究或落地经验；2.具备扎实的工程实现能力，熟练掌握 Python、C/C++ 等至少一种编程语言，熟悉 Agent 系统搭建中的核心模块，包括任务规划、工具调用、记忆机制、轨迹建模、反馈闭环等，并对相关数据构建与训练流程有实践经验；3.重度使用 Cursor / Claude Code / Codex 等 AI 编程工具，对 agentic coding 的能力边界和失效模式有清晰判断——知道它在什么任务上可靠，在什么场景下会翻车4.有高质量论文发表者优先，特别是在 Agent、复杂推理、环境交互、长上下文建模、数据合成或特定垂域能力突破等方向；5.对代码质量要求严格，代码是给未来的 AI 和人一起维护的，可读性、架构等缺一不可\n软性素质要求：\n具备强烈的进取心、自驱力及跨领域学习能力，良好的团队协作精神，对推动 Agent 成为下一代生产力入口、实现更强通用智能能力充满热情。\n具备极客精神，喜欢折腾新技术，享受新技术带来的生产力突破，拥有一定的全栈工程能力和系统设计功底","description":"课题描述\n课题背景：\nAgent 正在成为下一代生产力系统的核心入口，也是通往 AGI 最重要的技术路径之一。\n\n我们团队致力于通过高质量数据构建与大规模强化学习，从预训练到后训练全链路持续提升混元基础模型的 Agentic 能力；同时探索新的 human-agent-environment 交互方式，推动模型能力与产品体验共同演进。\n我们希望 Agent 能真正成为普通人、开发者与科研工作者的生产力工具，并期待与你一起推动这件事发生。\n\n课题挑战：\n1.高质量 Agentic 数据构建：\n构建覆盖真实任务、工具调用和长程交互的高质量数据体系。解决任务生成、环境搭建、轨迹采集、结果验证以及难度与多样性控制等问题，规模化沉淀高价值数据。\n\n2.大规模 Agentic RL 训练：\n面向长时程、多步骤、稀疏奖励的 Agent 任务，探索稳定高效的强化学习方法。重点解决长轨迹信用分配、有效探索、奖励建模、训练稳定性和环境吞吐等问题，提升模型在复杂环境中的规划、执行与自我纠错能力。\n\n3.Agent Harness 设计：\n设计支撑 Agent 长程运行的系统框架，统一模型、工具与环境的交互边界，处理上下文管理、任务调度、状态持久化、并发执行与故障恢复。构建稳定、可扩展、可插拔的极简 Harness，实现脚手架与模型共同进化。\n\n4.Agent 可观测性设计：\n建立覆盖任务、模型、工具和环境的全链路观测体系，让 Agent 的执行过程能够被理解、评估和复现。围绕行为轨迹追踪、失败归因、能力评测、异常检测和线上反馈闭环，提升 Agent 的可调试性、可靠性与持续迭代效率。\n\n\n课题要求\n我们关注三个核心的方向：\n1.Coding Agent：你将深入参与 Coding Agent 的研究与落地，包括复杂代码库理解、工具调用、长链软件任务执行、真实环境交互、agent trajectory 建模、可验证训练数据构造，以及面向真实研发场景和用户体验的能力建设。核心目标是让 Agent 像真正的工程师一样完成端到端的软件工程任务。\n2.Productivity Agent：你将参与构建面向真实工作与生活场景的生产力 Agent，探索 computer use、多工具协同、长期记忆、个性化上下文建模、腾讯生态深度交互等关键能力，核心目标是让 Agent 成为真正能够与用户长期协作、越用越懂你的 coworker。\n3.Research Agent：你将参与 Agent 在 AI 自动化与科学研发自动化中的前沿探索，包括自动化训练流程、实验系统构建、研究任务分解、反馈驱动迭代，以及迈向 AI Scientist 所需的能力基座设计。你将有机会参与定义 Agent 如何加速 AI 自身的发展，并进入更高价值的科学探索场景。\n课题要求\n技术技能要求：1.在 Agent、LLM 或相关方向有深入实践，对复杂任务求解、长链路推理、多工具调用、环境交互或特定应用场景有丰富的研究或落地经验；2.具备扎实的工程实现能力，熟练掌握 Python、C/C++ 等至少一种编程语言，熟悉 Agent 系统搭建中的核心模块，包括任务规划、工具调用、记忆机制、轨迹建模、反馈闭环等，并对相关数据构建与训练流程有实践经验；3.重度使用 Cursor / Claude Code / Codex 等 AI 编程工具，对 agentic coding 的能力边界和失效模式有清晰判断——知道它在什么任务上可靠，在什么场景下会翻车4.有高质量论文发表者优先，特别是在 Agent、复杂推理、环境交互、长上下文建模、数据合成或特定垂域能力突破等方向；5.对代码质量要求严格，代码是给未来的 AI 和人一起维护的，可读性、架构等缺一不可\n软性素质要求：\n具备强烈的进取心、自驱力及跨领域学习能力，良好的团队协作精神，对推动 Agent 成为下一代生产力入口、实现更强通用智能能力充满热情。\n具备极客精神，喜欢折腾新技术，享受新技术带来的生产力突破，拥有一定的全栈工程能力和系统设计功底\n\nTEG\n技术工程事业群\n\n腾讯混元基础模型部\n基础模型部负责混元大模型的前沿技术探索与基础模型研发，聚焦模型结构、数据与训练策略、强化学习及Agent能力，协同各模态研发能力，高效开发并迭代基础模型架构，面向AGI愿景探索智能上限、确保技术领先；同时构建基于大模型的AI PaaS中台能力，赋能公司内外部的产品创新与业务应用。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1293194428185772033","sourceKey":"tencent","company":"腾讯","title":"元宝-面向复杂搜索的自适应深度决策与推理效率优化","city":"深圳总部/北京/上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1293194428185772033","duty":"真实搜索场景中，模型常面临两难困境：简单问题执行多轮搜索造成计算浪费，长尾高难问题却因搜索深度不足导致答案质量欠佳。随着资源放开，更需让模型内生学会“该停则停、该深则深”。本课题计划从信息论视角出发，将每轮搜索视为一次信息获取行为，研究如何让模型根据任务难度与当前信息状态自主决策搜索深度。\n\n核心探索方向包括：\n\n1. 信息增益感知的搜索价值评估——设计可计算的边际信息增益度量方法（如基于模型置信度变化、知识覆盖增量、不确定性缩减等），量化每轮搜索对最终答案的真实贡献，识别“有效搜索”与“无效搜索”的边界；\n\n2. 难度感知的动态预算分配：构建问题难度预判模块，在搜索启动前输出初始难度评分与搜索预算建议，结合信息增益动态调整预算，既防止简单问题过搜，也保障高难问题有充足探索空间；\n\n3. 自适应早停决策机制——在信息增益显著衰减时由模型自主触发停止，并可结合问题难度预判设定差异化搜索预算，防止简单问题过搜，保障高难问题深度探索；\n\n4. 强化学习驱动的策略学习——采用GRPO/PPO等算法进行端到端训练，设计兼顾答案准确率与搜索效率的奖励函数（如信息增益阈值动态惩罚机制），让模型在探索与利用之间习得最优平衡策略，在保证长尾高难问题解决率的前提下最小化整体推理成本。","requirements":"1. 计算机、人工智能、机器学习、自然语言处理等相关专业，熟悉深度学习及大语言模型基本原理；\n2. 熟练使用Python、PyTorch等常用开发与深度学习框架，具备较强的模型训练、实验分析和工程实践能力，能够熟练使用主流AI编程工具开展研发工作；\n3. 在SFT、RLHF/RL、Agent、Tool Use等方向具有研究或项目经验者优先，熟悉PPO、GRPO等Post-training方法或具有相关实践经验者优先；\n4. 在推理效率优化、自适应计算、Early Exit等方向有相关研究或项目经验者优先，了解信息增益、主动学习等相关方法论；\n5. 具备较强的模型行为分析能力，能够从实际问题出发定义可验证指标、设计优化方案，并通过实验持续迭代；\n6. 具备较强的论文阅读、独立思考和实验分析能力，持续关注大模型推理优化与Agentic RL前沿研究；\n7. 具备良好的沟通协作能力和Owner意识，能够主动推动开放性研究课题取得实质进展，具备高质量论文撰写能力。","description":"课题描述\n真实搜索场景中，模型常面临两难困境：简单问题执行多轮搜索造成计算浪费，长尾高难问题却因搜索深度不足导致答案质量欠佳。随着资源放开，更需让模型内生学会“该停则停、该深则深”。本课题计划从信息论视角出发，将每轮搜索视为一次信息获取行为，研究如何让模型根据任务难度与当前信息状态自主决策搜索深度。\n\n核心探索方向包括：\n\n1. 信息增益感知的搜索价值评估——设计可计算的边际信息增益度量方法（如基于模型置信度变化、知识覆盖增量、不确定性缩减等），量化每轮搜索对最终答案的真实贡献，识别“有效搜索”与“无效搜索”的边界；\n\n2. 难度感知的动态预算分配：构建问题难度预判模块，在搜索启动前输出初始难度评分与搜索预算建议，结合信息增益动态调整预算，既防止简单问题过搜，也保障高难问题有充足探索空间；\n\n3. 自适应早停决策机制——在信息增益显著衰减时由模型自主触发停止，并可结合问题难度预判设定差异化搜索预算，防止简单问题过搜，保障高难问题深度探索；\n\n4. 强化学习驱动的策略学习——采用GRPO/PPO等算法进行端到端训练，设计兼顾答案准确率与搜索效率的奖励函数（如信息增益阈值动态惩罚机制），让模型在探索与利用之间习得最优平衡策略，在保证长尾高难问题解决率的前提下最小化整体推理成本。\n\n课题要求\n1. 计算机、人工智能、机器学习、自然语言处理等相关专业，熟悉深度学习及大语言模型基本原理；\n2. 熟练使用Python、PyTorch等常用开发与深度学习框架，具备较强的模型训练、实验分析和工程实践能力，能够熟练使用主流AI编程工具开展研发工作；\n3. 在SFT、RLHF/RL、Agent、Tool Use等方向具有研究或项目经验者优先，熟悉PPO、GRPO等Post-training方法或具有相关实践经验者优先；\n4. 在推理效率优化、自适应计算、Early Exit等方向有相关研究或项目经验者优先，了解信息增益、主动学习等相关方法论；\n5. 具备较强的模型行为分析能力，能够从实际问题出发定义可验证指标、设计优化方案，并通过实验持续迭代；\n6. 具备较强的论文阅读、独立思考和实验分析能力，持续关注大模型推理优化与Agentic RL前沿研究；\n7. 具备良好的沟通协作能力和Owner意识，能够主动推动开放性研究课题取得实质进展，具备高质量论文撰写能力。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1293212675811278848","sourceKey":"tencent","company":"腾讯","title":"元宝-大模型效果评估的自我迭代与自动进化","city":"深圳总部/北京/上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1293212675811278848","duty":"本课题希望探索面向大模型的Evaluation Evolution 与 Iterative Self-Refinement：一方面研究评测体系如何随着模型能力、用户需求和真实 Badcase 持续自我迭代，自动发现新的能力边界、问题模式和评测维度；另一方面研究如何利用评测反馈，在不依赖额外模型训练或尽量减少训练成本的前提下，通过推理策略、上下文组织、反馈反思、自我修正等方式，实现模型效果的自主迭代与提升。\n\n可能探索的方向包括但不限于：\n1. Evaluation Evolution：基于线上真实问题、模型能力变化及自动化分析，动态发现新的评测维度、生成高质量评测样本，并持续演进 Benchmark；\n2. 自动化评测与归因：研究 LLM-as-a-Judge、自动 Badcase 聚类与归因、评测结果可信度校准等方法，提升评测体系的自动化程度与可靠性；\n3. Iterative Self-Refinement：利用评测反馈驱动模型进行反思、重规划、答案修正和多轮自主优化，探索 Training-Free 的模型效果提升方法；\n4. Evaluation-to-Improvement 闭环：研究如何将“发现问题—评估问题—理解原因—产生改进策略—验证改进效果”连接成自动化闭环，使 Evaluation 从静态测量工具进一步演化为推动模型持续进化的核心机制。\n\n课题将结合真实大模型应用场景与大规模评测数据开展研究，既关注算法和方法创新，也关注其在实际大模型系统中的有效性与可扩展性。","requirements":"希望候选人具备较强的研究兴趣和独立思考能力，对大模型 Evaluation、Agent、Self-Refinement 等方向有兴趣，并愿意探索开放性较强的问题。\n\n具体希望具备：\n1. 计算机、人工智能、机器学习、自然语言处理等相关专业背景；\n熟悉机器学习、深度学习及大语言模型基本原理，具备良好的算法基础；\n2. 熟练使用 Python，熟悉 PyTorch 等常用深度学习框架，具备较好的工程实践能力；\n3. 有 LLM、NLP、Agent、Evaluation、Reasoning、RL、数据挖掘等相关研究或项目经历者优先；\n4. 能够阅读和跟进前沿论文，并具备从问题定义、方法设计、实验验证到结果分析的完整研究能力；\n5. 对真实模型 Case 有敏感度，能够从大量现象中抽象问题、形成假设并通过实验验证，而不仅停留在指标调优层面；\n6. 具备良好的沟通协作能力和 Ownership，能够主动推进开放性课题。\n\n尤其欢迎对“如何让大模型知道自己哪里不好，并进一步自主变好”这一问题感兴趣的同学。","description":"课题描述\n本课题希望探索面向大模型的Evaluation Evolution 与 Iterative Self-Refinement：一方面研究评测体系如何随着模型能力、用户需求和真实 Badcase 持续自我迭代，自动发现新的能力边界、问题模式和评测维度；另一方面研究如何利用评测反馈，在不依赖额外模型训练或尽量减少训练成本的前提下，通过推理策略、上下文组织、反馈反思、自我修正等方式，实现模型效果的自主迭代与提升。\n\n可能探索的方向包括但不限于：\n1. Evaluation Evolution：基于线上真实问题、模型能力变化及自动化分析，动态发现新的评测维度、生成高质量评测样本，并持续演进 Benchmark；\n2. 自动化评测与归因：研究 LLM-as-a-Judge、自动 Badcase 聚类与归因、评测结果可信度校准等方法，提升评测体系的自动化程度与可靠性；\n3. Iterative Self-Refinement：利用评测反馈驱动模型进行反思、重规划、答案修正和多轮自主优化，探索 Training-Free 的模型效果提升方法；\n4. Evaluation-to-Improvement 闭环：研究如何将“发现问题—评估问题—理解原因—产生改进策略—验证改进效果”连接成自动化闭环，使 Evaluation 从静态测量工具进一步演化为推动模型持续进化的核心机制。\n\n课题将结合真实大模型应用场景与大规模评测数据开展研究，既关注算法和方法创新，也关注其在实际大模型系统中的有效性与可扩展性。\n\n课题要求\n希望候选人具备较强的研究兴趣和独立思考能力，对大模型 Evaluation、Agent、Self-Refinement 等方向有兴趣，并愿意探索开放性较强的问题。\n\n具体希望具备：\n1. 计算机、人工智能、机器学习、自然语言处理等相关专业背景；\n熟悉机器学习、深度学习及大语言模型基本原理，具备良好的算法基础；\n2. 熟练使用 Python，熟悉 PyTorch 等常用深度学习框架，具备较好的工程实践能力；\n3. 有 LLM、NLP、Agent、Evaluation、Reasoning、RL、数据挖掘等相关研究或项目经历者优先；\n4. 能够阅读和跟进前沿论文，并具备从问题定义、方法设计、实验验证到结果分析的完整研究能力；\n5. 对真实模型 Case 有敏感度，能够从大量现象中抽象问题、形成假设并通过实验验证，而不仅停留在指标调优层面；\n6. 具备良好的沟通协作能力和 Ownership，能够主动推进开放性课题。\n\n尤其欢迎对“如何让大模型知道自己哪里不好，并进一步自主变好”这一问题感兴趣的同学。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1293212684925501441","sourceKey":"tencent","company":"腾讯","title":"元宝—Agentic Model能力进化","city":"深圳总部/北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1293212684925501441","duty":"随着通用Agent在复杂任务链路中的广泛部署，如何让智能体具备跨场景的技能泛化能力与持续自我进化能力，成为制约Agent从\"单点任务执行\"迈向\"通用智能助理\"的核心瓶颈。传统基于固定Prompt与静态工具集的Agent架构，在面对长尾场景、多步骤工具编排与跨领域知识迁移时，存在技能复用率低、探索效率差、慢思考与快反应难以协同等问题。本课题聚焦以下方向：\n\n1、技能泛化与Agent自进化\n攻克Agent在陌生任务场景中自主发现、组合、迁移已有能力的技能泛化难题，突破技能库随任务反馈自我扩充与淘汰的机制瓶颈，使Agent具备从经验中持续学习、不断拓展能力边界的自进化特性，实现从\"人工预置能力\"到\"自主习得能力\"的跨越。\n\n2、多智能体协同与Agentic RL训练范式\n解决多智能体任务分解与协同决策中的效率瓶颈，突破强化学习在复杂工具调用链路中奖励设计与训练效率的优化难题，结合环境模拟与蒸馏等技术手段，攻克冷启动场景下高质量轨迹数据稀缺的问题，提升Agent在真实业务环境中的探索效率与收敛速度。\n\n3、快慢思考融合与Auto Think机制\n攻克快思考与慢思考融合中的一致性与效率难题，突破Auto Think范式下Agent根据任务复杂度自主判断何时深度推理、何时快速响应的决策瓶颈，在保障效果的同时兼顾推理效率与成本，使Agent具备更接近人类专家的自适应思考能力。","requirements":"1、具备较强的系统架构思维与工程落地能力，能够在Harness底层设计与算法策略之间灵活切换，有独立发表顶会论文（NeurIPS/ICML/ACL等）经验者优先。\n2、计算机、人工智能、自然语言处理或相关专业硕士及以上学历，博士优先。具备扎实的深度学习理论基础，在大模型Agent、强化学习或多智能体系统领域有深入研究背景者优先。\n3、熟悉LLM后训练全流程，以及PyTorch、verl等训练框架。有Tool-calling、Agentic RL、智能体相关Benchmark评测构建经验者优先。\n4、极强的技术自驱力与好奇心，善于在开放性问题中主动定义方向，具备良好的跨团队协作与沟通能力。","description":"课题描述\n随着通用Agent在复杂任务链路中的广泛部署，如何让智能体具备跨场景的技能泛化能力与持续自我进化能力，成为制约Agent从\"单点任务执行\"迈向\"通用智能助理\"的核心瓶颈。传统基于固定Prompt与静态工具集的Agent架构，在面对长尾场景、多步骤工具编排与跨领域知识迁移时，存在技能复用率低、探索效率差、慢思考与快反应难以协同等问题。本课题聚焦以下方向：\n\n1、技能泛化与Agent自进化\n攻克Agent在陌生任务场景中自主发现、组合、迁移已有能力的技能泛化难题，突破技能库随任务反馈自我扩充与淘汰的机制瓶颈，使Agent具备从经验中持续学习、不断拓展能力边界的自进化特性，实现从\"人工预置能力\"到\"自主习得能力\"的跨越。\n\n2、多智能体协同与Agentic RL训练范式\n解决多智能体任务分解与协同决策中的效率瓶颈，突破强化学习在复杂工具调用链路中奖励设计与训练效率的优化难题，结合环境模拟与蒸馏等技术手段，攻克冷启动场景下高质量轨迹数据稀缺的问题，提升Agent在真实业务环境中的探索效率与收敛速度。\n\n3、快慢思考融合与Auto Think机制\n攻克快思考与慢思考融合中的一致性与效率难题，突破Auto Think范式下Agent根据任务复杂度自主判断何时深度推理、何时快速响应的决策瓶颈，在保障效果的同时兼顾推理效率与成本，使Agent具备更接近人类专家的自适应思考能力。\n\n课题要求\n1、具备较强的系统架构思维与工程落地能力，能够在Harness底层设计与算法策略之间灵活切换，有独立发表顶会论文（NeurIPS/ICML/ACL等）经验者优先。\n2、计算机、人工智能、自然语言处理或相关专业硕士及以上学历，博士优先。具备扎实的深度学习理论基础，在大模型Agent、强化学习或多智能体系统领域有深入研究背景者优先。\n3、熟悉LLM后训练全流程，以及PyTorch、verl等训练框架。有Tool-calling、Agentic RL、智能体相关Benchmark评测构建经验者优先。\n4、极强的技术自驱力与好奇心，善于在开放性问题中主动定义方向，具备良好的跨团队协作与沟通能力。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1293212684925501442","sourceKey":"tencent","company":"腾讯","title":"元宝-搜索智能体的动态工具选择与多工具编排学习","city":"深圳总部/北京/上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1293212684925501442","duty":"真实搜索场景中，单一的网页搜索远不足以应对所有需求——复杂任务往往需要通用搜索、内部知识库、数值计算引擎、代码解释器等多类工具的协同配合。然而现有模型大多面向固定工具集训练，既缺乏对工具能力的深层认知，也无法灵活编排多工具协同完成复杂任务。本课题旨在构建一个具备工具意识与编排能力的搜索智能体。\n\n核心探索方向包括：\n1. 工具选择策略学习：构建覆盖多工具的高质量训练数据（含工具选择理由与反例），通过SFT+RL培养模型的工具意识（Tool-Awareness），使其清晰理解各工具的功能边界、适用场景与局限，学会根据任务特征做出精准选择；\n\n2. 工具调用时机优化：研究工具调用不应仅依赖当前轮次，还需结合历史上下文判断调用必要性，探索基于历史轨迹的工具调用决策，避免重复调用与无效调用；\n\n3. 多工具协同编排框架：设计支持串行依赖与并行执行并存的编排框架，能根据任务结构自动拆解为子任务并分配合适工具，灵活应对搜索-计算-验证等复杂多步流程，同时支持工具链的动态重规划（re-planning）；\n\n4. 动态工具集泛化能力：探索模型对动态变化工具集（新工具上线、旧工具下线）的零样本/少样本适应能力，使智能体在工具生态持续演化的真实环境中保持鲁棒性；\n\n5. 工具执行结果验证与纠偏：研究对工具返回结果的可靠性评估机制，当结果异常或与已有证据冲突时触发重试或切换工具策略，确保推理链条的准确性。","requirements":"1. 计算机、人工智能、机器学习、自然语言处理等相关专业，熟悉深度学习及大语言模型基本原理；\n2. 熟练使用Python、PyTorch等常用开发与深度学习框架，具备较强的模型训练、实验分析和工程实践能力，能够熟练使用主流AI编程工具开展研发工作；\n3. 在SFT、RLHF/RL、Agent、Tool Use等方向具有研究或项目经验者优先；熟悉Function Calling、Tool-Augmented LLM等相关技术者优先；\n4. 在工具学习、多智能体系统、任务规划等方向有相关研究或项目经验者优先，了解MCTS、ReAct、Plan-and-Solve等推理范式；\n5. 具备较强的模型行为分析能力，能够从实际问题出发定义可验证指标、设计优化方案，并通过实验持续迭代；\n6. 具备较强的论文阅读、独立思考和实验分析能力，持续关注Agentic AI与Tool Learning前沿研究；\n7. 具备良好的沟通协作能力和Owner意识，能够主动推动开放性研究课题取得实质进展，具备高质量论文撰写能力。","description":"课题描述\n真实搜索场景中，单一的网页搜索远不足以应对所有需求——复杂任务往往需要通用搜索、内部知识库、数值计算引擎、代码解释器等多类工具的协同配合。然而现有模型大多面向固定工具集训练，既缺乏对工具能力的深层认知，也无法灵活编排多工具协同完成复杂任务。本课题旨在构建一个具备工具意识与编排能力的搜索智能体。\n\n核心探索方向包括：\n1. 工具选择策略学习：构建覆盖多工具的高质量训练数据（含工具选择理由与反例），通过SFT+RL培养模型的工具意识（Tool-Awareness），使其清晰理解各工具的功能边界、适用场景与局限，学会根据任务特征做出精准选择；\n\n2. 工具调用时机优化：研究工具调用不应仅依赖当前轮次，还需结合历史上下文判断调用必要性，探索基于历史轨迹的工具调用决策，避免重复调用与无效调用；\n\n3. 多工具协同编排框架：设计支持串行依赖与并行执行并存的编排框架，能根据任务结构自动拆解为子任务并分配合适工具，灵活应对搜索-计算-验证等复杂多步流程，同时支持工具链的动态重规划（re-planning）；\n\n4. 动态工具集泛化能力：探索模型对动态变化工具集（新工具上线、旧工具下线）的零样本/少样本适应能力，使智能体在工具生态持续演化的真实环境中保持鲁棒性；\n\n5. 工具执行结果验证与纠偏：研究对工具返回结果的可靠性评估机制，当结果异常或与已有证据冲突时触发重试或切换工具策略，确保推理链条的准确性。\n\n课题要求\n1. 计算机、人工智能、机器学习、自然语言处理等相关专业，熟悉深度学习及大语言模型基本原理；\n2. 熟练使用Python、PyTorch等常用开发与深度学习框架，具备较强的模型训练、实验分析和工程实践能力，能够熟练使用主流AI编程工具开展研发工作；\n3. 在SFT、RLHF/RL、Agent、Tool Use等方向具有研究或项目经验者优先；熟悉Function Calling、Tool-Augmented LLM等相关技术者优先；\n4. 在工具学习、多智能体系统、任务规划等方向有相关研究或项目经验者优先，了解MCTS、ReAct、Plan-and-Solve等推理范式；\n5. 具备较强的模型行为分析能力，能够从实际问题出发定义可验证指标、设计优化方案，并通过实验持续迭代；\n6. 具备较强的论文阅读、独立思考和实验分析能力，持续关注Agentic AI与Tool Learning前沿研究；\n7. 具备良好的沟通协作能力和Owner意识，能够主动推动开放性研究课题取得实质进展，具备高质量论文撰写能力。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1293212684925501443","sourceKey":"tencent","company":"腾讯","title":"元宝-复杂场景下的知识消歧与推理能力优化","city":"深圳总部/北京/上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1293212684925501443","duty":"真实复杂场景中，搜索模型不仅需要召回相关信息，还需要判断当前证据是否充分、信息之间是否存在歧义或冲突，并据此决定是否继续获取信息以及如何完成后续推理。本课题面向元宝真实搜索场景，研究多层次监督信号与信用分配机制，提升模型在复杂信息环境中的信息获取、知识消歧与推理能力。\n\n可能探索的方向包括但不限于：\n\n复杂搜索中的监督信号与 Credit Assignment：围绕答案正确性、证据充分性、搜索有效性和推理过程设计 Reward Model / Judge，使模型能够识别真正促进问题解决的关键行为，并通过 Agentic RL 优化多步搜索与推理决策。\n\n外部知识增强的自适应推理：研究模型如何根据任务需求和当前信息状态，自主选择并组合不同的信息获取与分析能力，在通用搜索、专业知识调用与数值计算等工具之间动态切换，形成更高效、更可靠的问题求解路径，提升复杂专业场景下的信息获取效率与推理准确性。\n\nPolicy 与 Judge 协同进化：探索搜索场景Agentic RL 训练过程中 Policy 与 Judge 的联合迭代机制，使 Judge 能够持续识别更强 Policy 产生的新型错误与推理模式，同时利用不断演进的评价信号推动 Policy 突破现有能力边界，探索更加稳定、可持续的 Policy-Judge 共进化训练范式。\n\n课题将结合真实互联网环境和元宝线上复杂 Query，探索搜索、知识调用与推理能力的统一优化，提升模型在高难度、专业化和多步问题中的可靠性与效率。","requirements":"希望候选人对大语言模型 Post-training，尤其是 Agentic Reinforcement Learning、Credit Assignment、Reward Model 等方向具有较强兴趣，具备扎实的算法基础和良好的实验能力。\n具体希望具备：\n1. 计算机、人工智能、机器学习、自然语言处理等相关专业背景，熟悉深度学习及大语言模型基本原理；\n2. 熟练使用 Python、PyTorch 等常用开发与深度学习框架，具备较强的模型训练、实验分析和工程实践能力，能够熟练使用主流 AI 编程工具开展研发工作；\n3. 在 SFT、RLHF / RL、Agent、Tool Use 等一个或多个方向具有研究或项目经验者优先；熟悉 PPO、GRPO 等 Post-training 方法或具有相关实践经验者优先；\n4. 具备较强的模型行为分析能力，能够从实际问题出发定义可验证指标、设计优化方案，并通过实验持续迭代模型效果；\n5. 对复杂搜索、Tool-Augmented Reasoning 等方向感兴趣，愿意探索如何通过多种外部工具提升信息可信度、推理一致性与任务完成效率，以及 Policy 与 Judge 协同进化的训练机制；\n6. 具备较强的论文阅读、独立思考和实验分析能力，持续关注大模型 Post-training 与 Agentic RL 的前沿研究；\n7. 具备良好的沟通协作能力和 Ownership，能够主动推动开放性研究课题取得实质进展。","description":"课题描述\n真实复杂场景中，搜索模型不仅需要召回相关信息，还需要判断当前证据是否充分、信息之间是否存在歧义或冲突，并据此决定是否继续获取信息以及如何完成后续推理。本课题面向元宝真实搜索场景，研究多层次监督信号与信用分配机制，提升模型在复杂信息环境中的信息获取、知识消歧与推理能力。\n\n可能探索的方向包括但不限于：\n\n复杂搜索中的监督信号与 Credit Assignment：围绕答案正确性、证据充分性、搜索有效性和推理过程设计 Reward Model / Judge，使模型能够识别真正促进问题解决的关键行为，并通过 Agentic RL 优化多步搜索与推理决策。\n\n外部知识增强的自适应推理：研究模型如何根据任务需求和当前信息状态，自主选择并组合不同的信息获取与分析能力，在通用搜索、专业知识调用与数值计算等工具之间动态切换，形成更高效、更可靠的问题求解路径，提升复杂专业场景下的信息获取效率与推理准确性。\n\nPolicy 与 Judge 协同进化：探索搜索场景Agentic RL 训练过程中 Policy 与 Judge 的联合迭代机制，使 Judge 能够持续识别更强 Policy 产生的新型错误与推理模式，同时利用不断演进的评价信号推动 Policy 突破现有能力边界，探索更加稳定、可持续的 Policy-Judge 共进化训练范式。\n\n课题将结合真实互联网环境和元宝线上复杂 Query，探索搜索、知识调用与推理能力的统一优化，提升模型在高难度、专业化和多步问题中的可靠性与效率。\n\n课题要求\n希望候选人对大语言模型 Post-training，尤其是 Agentic Reinforcement Learning、Credit Assignment、Reward Model 等方向具有较强兴趣，具备扎实的算法基础和良好的实验能力。\n具体希望具备：\n1. 计算机、人工智能、机器学习、自然语言处理等相关专业背景，熟悉深度学习及大语言模型基本原理；\n2. 熟练使用 Python、PyTorch 等常用开发与深度学习框架，具备较强的模型训练、实验分析和工程实践能力，能够熟练使用主流 AI 编程工具开展研发工作；\n3. 在 SFT、RLHF / RL、Agent、Tool Use 等一个或多个方向具有研究或项目经验者优先；熟悉 PPO、GRPO 等 Post-training 方法或具有相关实践经验者优先；\n4. 具备较强的模型行为分析能力，能够从实际问题出发定义可验证指标、设计优化方案，并通过实验持续迭代模型效果；\n5. 对复杂搜索、Tool-Augmented Reasoning 等方向感兴趣，愿意探索如何通过多种外部工具提升信息可信度、推理一致性与任务完成效率，以及 Policy 与 Judge 协同进化的训练机制；\n6. 具备较强的论文阅读、独立思考和实验分析能力，持续关注大模型 Post-training 与 Agentic RL 的前沿研究；\n7. 具备良好的沟通协作能力和 Ownership，能够主动推动开放性研究课题取得实质进展。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1293212684929695744","sourceKey":"tencent","company":"腾讯","title":"元宝-面向低时延场景的小模型 Agentic 能力学习与优化","city":"深圳总部/北京/上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1293212684929695744","duty":"随着大模型逐步应用于搜索、推荐、智能助手、内容理解等创新场景，模型需要从单轮生成进一步具备任务规划、工具调用、多步决策和结果反思等 Agentic 能力。然而，在大量真实产品场景中，端到端耗时、计算成本和服务吞吐具有严格约束，直接使用大尺寸模型往往难以同时满足效果与性能要求。\n\n本课题将面向真实低时延应用场景，探索基于 Agentic-SFT、Agentic-RL 与模型蒸馏的小模型能力优化方法，将大模型的推理、规划、工具使用和决策能力高效迁移到更小、更快的模型中，在效果、延迟和计算成本之间取得更优平衡。\n\n可能探索的方向包括但不限于：\n1. Agentic 数据与轨迹构建：研究如何从真实任务、大模型执行轨迹和交互反馈中自动构造高质量 Agentic 数据，覆盖任务规划、工具选择、参数生成、多步执行、反思与修正等能力；\n2. Agentic-SFT：研究适合小模型的监督微调方法，包括轨迹筛选、难度建模、数据配比、过程监督等，提升有限模型容量下的学习效率；\n3. Agentic-RL：围绕任务最终完成效果、过程质量、工具调用正确性及效率等信号设计强化学习方法，使模型能够通过交互和反馈持续优化 Agentic 决策能力；\n4. 大模型能力蒸馏：探索 On-Policy Distillation、轨迹蒸馏、过程蒸馏等方法，将强模型的推理与决策能力有效迁移到小模型，并研究 Teacher 与 Student 能力差异下更加高效稳定的蒸馏策略；\n5. 效果与效率联合优化：研究模型效果、推理步数、工具调用次数、Token 消耗和端到端时延之间的关系，使模型不仅能够“完成任务”，也能够以更低成本、更短路径完成任务；\n6. 困难样本与自主迭代：利用线上 Badcase、模型探索轨迹以及强模型反馈持续发现小模型的能力边界，并自动生成针对性训练数据，形成数据—训练—评估—再训练的迭代闭环；\n7. 真实应用场景验证：结合对实时性要求较高的 AI 创新应用，对模型在复杂指令理解、工具调用、多步任务执行等场景中的效果、时延与资源成本进行综合验证。\n\n课题将紧密结合真实业务场景与线上模型数据，兼顾算法研究和实际应用价值，鼓励探索能够同时带来模型效果提升与推理效率优化的新方法。","requirements":"希望候选人对大语言模型 Post-training、Agent、Reinforcement Learning、Knowledge Distillation 等方向具有较强兴趣，具备扎实的算法基础和较好的实验能力。\n\n具体希望具备：\n1 计算机、人工智能、机器学习、自然语言处理等相关专业背景；\n熟悉深度学习及大语言模型基本原理，对 Transformer、LLM Post-training 等技术有较好的理解；\n2. 熟练使用 Python、PyTorch 等常用深度学习工具，具备较强的模型训练、实验分析和工程实践能力；\n3. 对 SFT、RLHF / RL、模型蒸馏、Agent、Tool Use 等一个或多个方向有研究或项目经历者优先；\n熟悉 PPO、GRPO、DPO、On-Policy Distillation 等 Post-training / Distillation 方法，或有相关实践经验者优先；\n4. 能够从真实模型 Case 和实验结果中发现问题，设计数据、训练目标和实验方案，并持续迭代模型效果；\n5. 对模型效果与推理效率之间的 Trade-off 有兴趣，愿意探索算法、数据和推理策略的联合优化；\n6. 具备较强的论文阅读、独立思考和实验分析能力，能够跟进大模型 Post-training 与 Agentic Learning 的前沿研究；\n7. 具备良好的沟通协作能力和 Ownership，能够主动推动开放性研究课题取得实质进展。\n\n我们尤其欢迎对“如何让更小、更快的模型拥有真正可用的 Agentic 能力”这一问题感兴趣的同学。","description":"课题描述\n随着大模型逐步应用于搜索、推荐、智能助手、内容理解等创新场景，模型需要从单轮生成进一步具备任务规划、工具调用、多步决策和结果反思等 Agentic 能力。然而，在大量真实产品场景中，端到端耗时、计算成本和服务吞吐具有严格约束，直接使用大尺寸模型往往难以同时满足效果与性能要求。\n\n本课题将面向真实低时延应用场景，探索基于 Agentic-SFT、Agentic-RL 与模型蒸馏的小模型能力优化方法，将大模型的推理、规划、工具使用和决策能力高效迁移到更小、更快的模型中，在效果、延迟和计算成本之间取得更优平衡。\n\n可能探索的方向包括但不限于：\n1. Agentic 数据与轨迹构建：研究如何从真实任务、大模型执行轨迹和交互反馈中自动构造高质量 Agentic 数据，覆盖任务规划、工具选择、参数生成、多步执行、反思与修正等能力；\n2. Agentic-SFT：研究适合小模型的监督微调方法，包括轨迹筛选、难度建模、数据配比、过程监督等，提升有限模型容量下的学习效率；\n3. Agentic-RL：围绕任务最终完成效果、过程质量、工具调用正确性及效率等信号设计强化学习方法，使模型能够通过交互和反馈持续优化 Agentic 决策能力；\n4. 大模型能力蒸馏：探索 On-Policy Distillation、轨迹蒸馏、过程蒸馏等方法，将强模型的推理与决策能力有效迁移到小模型，并研究 Teacher 与 Student 能力差异下更加高效稳定的蒸馏策略；\n5. 效果与效率联合优化：研究模型效果、推理步数、工具调用次数、Token 消耗和端到端时延之间的关系，使模型不仅能够“完成任务”，也能够以更低成本、更短路径完成任务；\n6. 困难样本与自主迭代：利用线上 Badcase、模型探索轨迹以及强模型反馈持续发现小模型的能力边界，并自动生成针对性训练数据，形成数据—训练—评估—再训练的迭代闭环；\n7. 真实应用场景验证：结合对实时性要求较高的 AI 创新应用，对模型在复杂指令理解、工具调用、多步任务执行等场景中的效果、时延与资源成本进行综合验证。\n\n课题将紧密结合真实业务场景与线上模型数据，兼顾算法研究和实际应用价值，鼓励探索能够同时带来模型效果提升与推理效率优化的新方法。\n\n课题要求\n希望候选人对大语言模型 Post-training、Agent、Reinforcement Learning、Knowledge Distillation 等方向具有较强兴趣，具备扎实的算法基础和较好的实验能力。\n\n具体希望具备：\n1 计算机、人工智能、机器学习、自然语言处理等相关专业背景；\n熟悉深度学习及大语言模型基本原理，对 Transformer、LLM Post-training 等技术有较好的理解；\n2. 熟练使用 Python、PyTorch 等常用深度学习工具，具备较强的模型训练、实验分析和工程实践能力；\n3. 对 SFT、RLHF / RL、模型蒸馏、Agent、Tool Use 等一个或多个方向有研究或项目经历者优先；\n熟悉 PPO、GRPO、DPO、On-Policy Distillation 等 Post-training / Distillation 方法，或有相关实践经验者优先；\n4. 能够从真实模型 Case 和实验结果中发现问题，设计数据、训练目标和实验方案，并持续迭代模型效果；\n5. 对模型效果与推理效率之间的 Trade-off 有兴趣，愿意探索算法、数据和推理策略的联合优化；\n6. 具备较强的论文阅读、独立思考和实验分析能力，能够跟进大模型 Post-training 与 Agentic Learning 的前沿研究；\n7. 具备良好的沟通协作能力和 Ownership，能够主动推动开放性研究课题取得实质进展。\n\n我们尤其欢迎对“如何让更小、更快的模型拥有真正可用的 Agentic 能力”这一问题感兴趣的同学。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1293315231581667328","sourceKey":"tencent","company":"腾讯","title":"元宝-大模型后训练算法研究","city":"深圳总部/北京/上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1293315231581667328","duty":"负责元宝通用后训练/搜索问答/教育/微信元宝、生态及创新业务等场景的后训练算法优化，为用户打造准确、高效、智能的信息获取体验，让元宝真正成为用户日常生活与工作中值得依赖的智能助手。\n1、参与元宝核心大模型能力的算法研发：围绕对话质量、指令遵循、事实性、长上下文、多轮一致性等核心指标，负责从问题定义、数据方案设计、训练/评测实验到线上灰度的完整闭环，对指标结果直接负责；\n2、主导或深度参与至少一个元宝后训练优化算法方向；\n3、构建可复用的数据与评测基础设施：设计高质量训练数据，建设可信的自动评测集与人工评测规范；\n4、推动算法成果的线上化落地：与工程、产品、数据团队协同完成模型上线；\n5、参与前沿技术的跟踪、复现与判断：对业界新方法做快速最小成本验证，输出\"是否值得投入\"的技术判断","requirements":"1. 计算机、人工智能、机器学习、自然语言处理等相关专业，熟悉深度学习及大语言模型基本原理；\n2. 熟练使用Python、PyTorch等常用开发与深度学习框架，具备较强的模型训练、实验分析和工程实践能力，能够熟练使用主流AI编程工具开展研发工作；\n3. 在SFT、RLHF/RL、Agent、Tool Use等方向具有研究或项目经验者优先，熟悉PPO、GRPO等Post-training方法或具有相关实践经验者优先；\n4. 具备较强的模型行为分析能力，能够从实际问题出发定义可验证指标、设计优化方案，并通过实验持续迭代；\n5. 具备较强的论文阅读、独立思考和实验分析能力，持续关注大模型推理优化与Agentic RL前沿研究；\n6. 具备良好的沟通协作能力和Owner意识，能够主动推动开放性研究课题取得实质进展，具备高质量论文撰写能力。","description":"课题描述\n负责元宝通用后训练/搜索问答/教育/微信元宝、生态及创新业务等场景的后训练算法优化，为用户打造准确、高效、智能的信息获取体验，让元宝真正成为用户日常生活与工作中值得依赖的智能助手。\n1、参与元宝核心大模型能力的算法研发：围绕对话质量、指令遵循、事实性、长上下文、多轮一致性等核心指标，负责从问题定义、数据方案设计、训练/评测实验到线上灰度的完整闭环，对指标结果直接负责；\n2、主导或深度参与至少一个元宝后训练优化算法方向；\n3、构建可复用的数据与评测基础设施：设计高质量训练数据，建设可信的自动评测集与人工评测规范；\n4、推动算法成果的线上化落地：与工程、产品、数据团队协同完成模型上线；\n5、参与前沿技术的跟踪、复现与判断：对业界新方法做快速最小成本验证，输出\"是否值得投入\"的技术判断\n\n课题要求\n1. 计算机、人工智能、机器学习、自然语言处理等相关专业，熟悉深度学习及大语言模型基本原理；\n2. 熟练使用Python、PyTorch等常用开发与深度学习框架，具备较强的模型训练、实验分析和工程实践能力，能够熟练使用主流AI编程工具开展研发工作；\n3. 在SFT、RLHF/RL、Agent、Tool Use等方向具有研究或项目经验者优先，熟悉PPO、GRPO等Post-training方法或具有相关实践经验者优先；\n4. 具备较强的模型行为分析能力，能够从实际问题出发定义可验证指标、设计优化方案，并通过实验持续迭代；\n5. 具备较强的论文阅读、独立思考和实验分析能力，持续关注大模型推理优化与Agentic RL前沿研究；\n6. 具备良好的沟通协作能力和Owner意识，能够主动推动开放性研究课题取得实质进展，具备高质量论文撰写能力。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null},{"id":"tencent:1295442456116166656","sourceKey":"tencent","company":"腾讯","title":"微信小微-基于CodeLLM的小程序主要功能（MCP Tool）生成式编译技术研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1295442456116166656","duty":"本课题聚焦于自然语言到小程序功能逻辑的自动化转化。研究如何利用CodeLLM 的代码理解与生成能力，将小程序的原子能力编译成标准化的 Skill 组件（JSON/JS 代码块）。重点突破Runtime代码分析、生成小程序代码段、搭建Verify Loop、训练专用CodeLLM等技术，构建一套从任务到功能实现（Text-to-MCP Tool）的高效编译流水线。","requirements":"1、包括但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程等专业的博士和优秀硕士；\n2、具备CodeLLM相关的CPT、SFT、RL经验，参与过CodeLLM的Harness工程建设；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。","description":"课题描述\n本课题聚焦于自然语言到小程序功能逻辑的自动化转化。研究如何利用CodeLLM 的代码理解与生成能力，将小程序的原子能力编译成标准化的 Skill 组件（JSON/JS 代码块）。重点突破Runtime代码分析、生成小程序代码段、搭建Verify Loop、训练专用CodeLLM等技术，构建一套从任务到功能实现（Text-to-MCP Tool）的高效编译流水线。\n\n课题要求\n1、包括但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程等专业的博士和优秀硕士；\n2、具备CodeLLM相关的CPT、SFT、RL经验，参与过CodeLLM的Harness工程建设；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。\n\nWXG\n微信事业群\n\n基础微信团队\n微信基础团队负责微信通讯与社交业务，为亿万用户提供高可用、低延迟的通讯基础设施。\n团队积极探索AI、音乐等创新领域，持续推进原生AI助手\"小微\"的研发，支持通过文字或语音对话操作微信原生功能，致力于打造更智能、更丰富的通讯社交生态。我们始终坚持产品逻辑的科学性与普适性，追求交互体验的简单与细致，以及技术实现的严谨与高效，致力于解决\"看似简单实则复杂\"的核心问题。\n如果你对产品与设计有自己的理解和抱负，对技术创新和实现有自己的理想与追求，欢迎加入微信基础团队，共同塑造下一代通讯社交基础设施。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1296891639222206464","sourceKey":"tencent","company":"腾讯","title":"游戏AI—可控游戏视频生成技术研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1296891639222206464","duty":"【课题背景】\nAIGC正重塑内容生产流程，游戏行业既需要用AI提升生产效率、降低成本，也需要借助生成式技术催生新玩法与新品类。团队探索以可控的实时游戏视频生成替代“人工3D资产生产+引擎渲染”，以更低门槛、更高效率生成多风格、多关卡内容，扩展玩家可体验内容的规模与丰富度。\n【课题挑战】\n在视频生成前沿能力之上，同时满足“实时性、可控性、可交互、可玩性与高画质”的综合要求：\n1.  在低延迟、高帧率、高画质下响应玩家输入并保持物理/逻辑一致，稳定生成长时序一致的画面与世界状态\n2.  支持多风格、多场景泛化与可编辑控制，避免漂移、崩坏与不可预期行为。\n【具体工作】\n你将参与实时可控视频生成模型研发，包括数据构建、模型架构设计、预训练与后训练算法优化、低延迟推理加速、评测体系与Demo实现。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学等专业的博士和优秀硕士\n2、对深度学习、扩散模型、步数蒸馏等算法原理有深入理解\n3、较强的工程实现能力，熟练掌握PyTorch等主流深度学习框架。","description":"课题描述\n【课题背景】\nAIGC正重塑内容生产流程，游戏行业既需要用AI提升生产效率、降低成本，也需要借助生成式技术催生新玩法与新品类。团队探索以可控的实时游戏视频生成替代“人工3D资产生产+引擎渲染”，以更低门槛、更高效率生成多风格、多关卡内容，扩展玩家可体验内容的规模与丰富度。\n【课题挑战】\n在视频生成前沿能力之上，同时满足“实时性、可控性、可交互、可玩性与高画质”的综合要求：\n1.  在低延迟、高帧率、高画质下响应玩家输入并保持物理/逻辑一致，稳定生成长时序一致的画面与世界状态\n2.  支持多风格、多场景泛化与可编辑控制，避免漂移、崩坏与不可预期行为。\n【具体工作】\n你将参与实时可控视频生成模型研发，包括数据构建、模型架构设计、预训练与后训练算法优化、低延迟推理加速、评测体系与Demo实现。\n\n课题要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学等专业的博士和优秀硕士\n2、对深度学习、扩散模型、步数蒸馏等算法原理有深入理解\n3、较强的工程实现能力，熟练掌握PyTorch等主流深度学习框架。\n\nTEG\n技术工程事业群\n\n腾讯AI平台部\n腾讯AI平台部聚焦决策AI和生成式AI两大技术研发方向，致力于探索AI与游戏娱乐行业的深度融合，为游戏研发和运营提供全链路AI解决方案，助力游戏行业发展。在决策AI方面，我们研发出屡获国际大奖的棋牌类 AI“绝艺”，以及攻克了 MOBA、FPS、RTS、3D 开放世界等多类游戏场景的决策智能 AI“绝悟”。在游戏生成式AI方向，我们聚焦于提高工程化效率和拓展游玩内容，自主研发了游戏AI引擎GiiNEX，支持AI NPC的创建、驱动和智能交互等技术，并且能够辅助生成关卡、剧情等游戏体验内容。在学术合作方面，我们与王者荣耀联合打造“开悟”AI开放研究平台，通过赛事、课程、共研项目等推动AI青年人才培养及产业发展。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1296891641365495808","sourceKey":"tencent","company":"腾讯","title":"混元基座模型 - 视觉理解大模型研究","city":"深圳总部/北京/上海","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1296891641365495808","duty":"课题背景：\n视觉理解能力是大模型感知真实世界和走向物理世界的基础，本青云课题主要探索面向未来的视觉理解技术，包括O3类图像推理方法，视觉Agent能力等。\n\n课题挑战：\n目前整个领域的视觉理解能力在全面性和可靠性上还有较大的提升空间，如何进一步提升能力以及展现新的特性仍旧是一个开放性问题。\n\n具体工作：\n帮助持续提升混元在视觉理解模型的能力，包括全面性和可靠性，以及探索面向未来的视觉理解技术，包括类O3的推理能力建设，以及视觉Agent能力等。","requirements":"学历和专业要求：计算机科学、机器学习、人工智能、应用数学等相关专业；\n\n技术技能要求：\n1.在多模态理解相关领域（包括自然语言处理、计算机视觉、语音理解/生成等）有扎实的研究基础\n2.熟悉一个或多个模态领域的主流模型和算法，如CLIP、LLaVA、VALL-E等；\n3.熟悉深度学习框架，如TensorFlow或PyTorch；了解分布式训练框架，如DeepSpeed和Megatron-LM等，并有一定的多机多卡分布式训练经验；\n4.较强的工程实现能力，熟练掌握C/C++, Java,Python等至少一种语言；\n5.有高质量论文发表者优先（如ICLR，NeurIPS，CVPR，ICCV，ECCV，ACL，EMNLP，等）；\n\n软性素质要求：\n具备极强的学习能力和技术追求，良好的团队合作和沟通能力。","description":"课题描述\n课题背景：\n视觉理解能力是大模型感知真实世界和走向物理世界的基础，本青云课题主要探索面向未来的视觉理解技术，包括O3类图像推理方法，视觉Agent能力等。\n\n课题挑战：\n目前整个领域的视觉理解能力在全面性和可靠性上还有较大的提升空间，如何进一步提升能力以及展现新的特性仍旧是一个开放性问题。\n\n具体工作：\n帮助持续提升混元在视觉理解模型的能力，包括全面性和可靠性，以及探索面向未来的视觉理解技术，包括类O3的推理能力建设，以及视觉Agent能力等。\n\n课题要求\n学历和专业要求：计算机科学、机器学习、人工智能、应用数学等相关专业；\n\n技术技能要求：\n1.在多模态理解相关领域（包括自然语言处理、计算机视觉、语音理解/生成等）有扎实的研究基础\n2.熟悉一个或多个模态领域的主流模型和算法，如CLIP、LLaVA、VALL-E等；\n3.熟悉深度学习框架，如TensorFlow或PyTorch；了解分布式训练框架，如DeepSpeed和Megatron-LM等，并有一定的多机多卡分布式训练经验；\n4.较强的工程实现能力，熟练掌握C/C++, Java,Python等至少一种语言；\n5.有高质量论文发表者优先（如ICLR，NeurIPS，CVPR，ICCV，ECCV，ACL，EMNLP，等）；\n\n软性素质要求：\n具备极强的学习能力和技术追求，良好的团队合作和沟通能力。\n\nTEG\n技术工程事业群\n\n腾讯混元基础模型部\n基础模型部负责混元大模型的前沿技术探索与基础模型研发，聚焦模型结构、数据与训练策略、强化学习及Agent能力，协同各模态研发能力，高效开发并迭代基础模型架构，面向AGI愿景探索智能上限、确保技术领先；同时构建基于大模型的AI PaaS中台能力，赋能公司内外部的产品创新与业务应用。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1296893503255019520","sourceKey":"tencent","company":"腾讯","title":"游戏AI—陪伴智能体系统研究","city":"深圳总部","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1296893503255019520","duty":"【课题背景】\nAI 正从被动响应的对话助手，走向能够在真实环境中感知、记忆、推理、规划并行动的智能伙伴。我们致力于打造面向游戏场景的陪伴智能体：以多模态决策大模型为核心，使 AI 不止于会聊天的 NPC，更能理解实时战局与玩家意图，主动协同决策、形成长期记忆，并以具有角色感和情感连接的伙伴身份融入游戏体验。\n相关技术已在《和平精英》等头部游戏正式服规模化上线，代表成果包括游戏行业首个由策略大模型驱动的明星 AI 伙伴。面向下一代智能体技术，我们将持续探索可长期陪伴、可规模部署、可持续进化的游戏AI伙伴系统。\n【课题挑战】\n1. 多模态决策与长期伙伴关系：实时盘面理解、战术推理与长程规划、长期记忆建模、个性化关系与情感交互，使智能体兼具高智商与高情商；\n2. 真实部署约束下的智能体能力保持：轻量化模型的高阶能力涌现、低成本推理与Agentic RL，在严格时延与资源约束下维持决策与交互效果；\n3. 可泛化Agent架构与持续进化：跨游戏场景可复用的Skill/Harness框架，以及从真实用户反馈驱动的评测-训练-上线迭代数据飞轮。\n【具体工作】\n参与多模态感知与世界建模、Lifelong Memory、Agentic RL与长程规划、Skill化执行架构、高情商对话与陪伴、原生Agent系统与评测闭环等方向研究与落地。","requirements":"1、包含但不限于计算机科学、人工智能、强化学习、多模态学习等相关方向的博士/硕士同学；\n2、熟悉LLM/VLM、Agent、RL或推理优化，掌握Python/PyTorch，有顶会论文发表或开源Agent项目经验者优先；\n3、软性素质要求： 自驱力强，具备研究好奇心和工程落地意识，喜欢游戏者更佳。","description":"课题描述\n【课题背景】\nAI 正从被动响应的对话助手，走向能够在真实环境中感知、记忆、推理、规划并行动的智能伙伴。我们致力于打造面向游戏场景的陪伴智能体：以多模态决策大模型为核心，使 AI 不止于会聊天的 NPC，更能理解实时战局与玩家意图，主动协同决策、形成长期记忆，并以具有角色感和情感连接的伙伴身份融入游戏体验。\n相关技术已在《和平精英》等头部游戏正式服规模化上线，代表成果包括游戏行业首个由策略大模型驱动的明星 AI 伙伴。面向下一代智能体技术，我们将持续探索可长期陪伴、可规模部署、可持续进化的游戏AI伙伴系统。\n【课题挑战】\n1. 多模态决策与长期伙伴关系：实时盘面理解、战术推理与长程规划、长期记忆建模、个性化关系与情感交互，使智能体兼具高智商与高情商；\n2. 真实部署约束下的智能体能力保持：轻量化模型的高阶能力涌现、低成本推理与Agentic RL，在严格时延与资源约束下维持决策与交互效果；\n3. 可泛化Agent架构与持续进化：跨游戏场景可复用的Skill/Harness框架，以及从真实用户反馈驱动的评测-训练-上线迭代数据飞轮。\n【具体工作】\n参与多模态感知与世界建模、Lifelong Memory、Agentic RL与长程规划、Skill化执行架构、高情商对话与陪伴、原生Agent系统与评测闭环等方向研究与落地。\n\n课题要求\n1、包含但不限于计算机科学、人工智能、强化学习、多模态学习等相关方向的博士/硕士同学；\n2、熟悉LLM/VLM、Agent、RL或推理优化，掌握Python/PyTorch，有顶会论文发表或开源Agent项目经验者优先；\n3、软性素质要求： 自驱力强，具备研究好奇心和工程落地意识，喜欢游戏者更佳。\n\nTEG\n技术工程事业群\n\n腾讯AI平台部\n腾讯AI平台部聚焦决策AI和生成式AI两大技术研发方向，致力于探索AI与游戏娱乐行业的深度融合，为游戏研发和运营提供全链路AI解决方案，助力游戏行业发展。在决策AI方面，我们研发出屡获国际大奖的棋牌类 AI“绝艺”，以及攻克了 MOBA、FPS、RTS、3D 开放世界等多类游戏场景的决策智能 AI“绝悟”。在游戏生成式AI方向，我们聚焦于提高工程化效率和拓展游玩内容，自主研发了游戏AI引擎GiiNEX，支持AI NPC的创建、驱动和智能交互等技术，并且能够辅助生成关卡、剧情等游戏体验内容。在学术合作方面，我们与王者荣耀联合打造“开悟”AI开放研究平台，通过赛事、课程、共研项目等推动AI青年人才培养及产业发展。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1297696816577839104","sourceKey":"tencent","company":"腾讯","title":"混元基座模型-STEM Agent研究","city":"深圳总部/北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1297696816577839104","duty":"课题背景：\nSTEM是大模型基础能力建设的重要方向。随着Agent能力持续提升，模型优化正从传统的知识问答与推理，进一步走向面向真实科学研究和工程工作的复杂任务执行。\n腾讯混元基础模型强化学习团队聚焦数学、物理、化学、生物、电子工程、机械工程等STEM领域，面向AI4Science与AI4Engineering场景，构建可执行、可复现、可验证的Agent强化学习与评测环境，接入主流科学计算和工业仿真工具，并通过SFT、RL等后训练技术，系统提升模型在科学研究与工程任务中的推理、工具使用和长程任务执行能力。\n\n课题挑战：\n1.真实工作流的可执行与可验证：科研和工程任务通常涉及复杂数据、专业软件及多阶段工作流。如何将真实工作场景转化为可执行、可复现、可自动判定的训练任务，并接入科学计算、工程仿真等专业工具，是该方向的核心挑战。\n\n2.Long-horizon Agent强化学习：科研和工程任务往往需要模型持续进行规划、工具调用、结果分析、错误修正和多轮迭代。如何设计稳定可靠的长程任务环境，解决奖励稀疏、信用分配困难、轨迹成本高和训练不稳定等问题，是重要研究课题。\n\n3.专业领域数据与评测体系：STEM任务具有较高的专业门槛。如何构建专业可靠的训练数据、Reward和评测集，是实现模型能力提升的关键。\n\n具体工作：\n●面向STEM领域构建可执行、可复现的LLM Agent训练与评测任务；\n●接入科学计算、工程仿真等专业工具，建设标准化工具调用和自动验证环境；\n●设计适用于科研和工程任务的Reward、过程反馈及评测指标；\n●参与SFT、RL等后训练实验，分析模型能力边界与典型失败模式；\n●与领域专家和模型算法团队协作，推动模型能力在真实科研及工程场景中落地。\n●作为领域专家，真实体验并使用前沿LLM Agent进行科研探索。","requirements":"1. 具备良好的计算机基础，熟练使用Python和Linux，具备较强的编程、调试及工程落地能力。\n2.经验与能力：满足以下条件其一：\n   ● 计算机相关专业硕士及以上在读，且在基础模型Agent方向有扎实的数据构建、RL训练或模型调优经验。\n   ● STEM领域相关专业（数学、物理、化学、生物、电子工程、机械工程等）博士在读，具备扎实的对应专业领域知识，并在对应领域的LLM Reasoning、Agent、AI4Science、AI4Engineering或模型评测方向有相关项目经验。\n   ●STEM领域相关专业（数学、物理、化学、生物、电子工程、机械工程等）博士在读，在所属细分方向发表过领域公认的高水平期刊或会议论文，具备优秀的科研能力和前沿研究经验；正在探索利用大模型解决本领域的前沿问题，并希望在实习期间依托腾讯混元模型开展科学探索、能力评测与方法研究，产出高质量科研成果。\n3.对大模型、强化学习及AI驱动的科学与工程研究有强烈兴趣，具备良好的自驱力、学习能力和协作能力。","description":"课题描述\n课题背景：\nSTEM是大模型基础能力建设的重要方向。随着Agent能力持续提升，模型优化正从传统的知识问答与推理，进一步走向面向真实科学研究和工程工作的复杂任务执行。\n腾讯混元基础模型强化学习团队聚焦数学、物理、化学、生物、电子工程、机械工程等STEM领域，面向AI4Science与AI4Engineering场景，构建可执行、可复现、可验证的Agent强化学习与评测环境，接入主流科学计算和工业仿真工具，并通过SFT、RL等后训练技术，系统提升模型在科学研究与工程任务中的推理、工具使用和长程任务执行能力。\n\n课题挑战：\n1.真实工作流的可执行与可验证：科研和工程任务通常涉及复杂数据、专业软件及多阶段工作流。如何将真实工作场景转化为可执行、可复现、可自动判定的训练任务，并接入科学计算、工程仿真等专业工具，是该方向的核心挑战。\n\n2.Long-horizon Agent强化学习：科研和工程任务往往需要模型持续进行规划、工具调用、结果分析、错误修正和多轮迭代。如何设计稳定可靠的长程任务环境，解决奖励稀疏、信用分配困难、轨迹成本高和训练不稳定等问题，是重要研究课题。\n\n3.专业领域数据与评测体系：STEM任务具有较高的专业门槛。如何构建专业可靠的训练数据、Reward和评测集，是实现模型能力提升的关键。\n\n具体工作：\n●面向STEM领域构建可执行、可复现的LLM Agent训练与评测任务；\n●接入科学计算、工程仿真等专业工具，建设标准化工具调用和自动验证环境；\n●设计适用于科研和工程任务的Reward、过程反馈及评测指标；\n●参与SFT、RL等后训练实验，分析模型能力边界与典型失败模式；\n●与领域专家和模型算法团队协作，推动模型能力在真实科研及工程场景中落地。\n●作为领域专家，真实体验并使用前沿LLM Agent进行科研探索。\n\n课题要求\n1. 具备良好的计算机基础，熟练使用Python和Linux，具备较强的编程、调试及工程落地能力。\n2.经验与能力：满足以下条件其一：\n   ● 计算机相关专业硕士及以上在读，且在基础模型Agent方向有扎实的数据构建、RL训练或模型调优经验。\n   ● STEM领域相关专业（数学、物理、化学、生物、电子工程、机械工程等）博士在读，具备扎实的对应专业领域知识，并在对应领域的LLM Reasoning、Agent、AI4Science、AI4Engineering或模型评测方向有相关项目经验。\n   ●STEM领域相关专业（数学、物理、化学、生物、电子工程、机械工程等）博士在读，在所属细分方向发表过领域公认的高水平期刊或会议论文，具备优秀的科研能力和前沿研究经验；正在探索利用大模型解决本领域的前沿问题，并希望在实习期间依托腾讯混元模型开展科学探索、能力评测与方法研究，产出高质量科研成果。\n3.对大模型、强化学习及AI驱动的科学与工程研究有强烈兴趣，具备良好的自驱力、学习能力和协作能力。\n\nTEG\n技术工程事业群\n\n腾讯混元基础模型部\n基础模型部负责混元大模型的前沿技术探索与基础模型研发，聚焦模型结构、数据与训练策略、强化学习及Agent能力，协同各模态研发能力，高效开发并迭代基础模型架构，面向AGI愿景探索智能上限、确保技术领先；同时构建基于大模型的AI PaaS中台能力，赋能公司内外部的产品创新与业务应用。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1298382438912983040","sourceKey":"tencent","company":"腾讯","title":"元宝—VLM think with image研究","city":"北京","category":"青云课题","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1298382438912983040","duty":"本课题旨在构建一个具备 “Think with Images” 能力的高阶视觉问答系统，使其能够像人类专家一样通过视觉化的思维路径解决复杂的认知难题。我们不仅挑战基础的视觉识别，更创新性地引入主动视觉推理范式。不同于被动接收视觉信息，本框架允许模型通过生成可执行代码（如 Python 图像处理脚本）主动干预视觉输入，例如进行动态裁剪聚焦、视角矫正、色彩增强或绘制辅助参考线，将隐性的思维过程具象化为中间态的“视觉草稿”。\n\n课题将重点攻克多步视觉逻辑推演中的一致性难题，聚焦于模型在处理几何推理解析、物理规律判断等高难度任务时的思维留痕与自我修正，解决传统 VQA 在复杂场景下因缺乏中间步骤导致的判断失真，通过在教育辅助、精密设计评估等场景中的实战演进，实现从“视觉感知”向“主动视觉思考”的跨越，打造具备深度逻辑解释力的多模态认知中枢。","requirements":"1、计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握大模型、多模态相关的基本算法及应用，熟悉caffe、tensorflow，pytorch等至少一个深度学习框架；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。","description":"课题描述\n本课题旨在构建一个具备 “Think with Images” 能力的高阶视觉问答系统，使其能够像人类专家一样通过视觉化的思维路径解决复杂的认知难题。我们不仅挑战基础的视觉识别，更创新性地引入主动视觉推理范式。不同于被动接收视觉信息，本框架允许模型通过生成可执行代码（如 Python 图像处理脚本）主动干预视觉输入，例如进行动态裁剪聚焦、视角矫正、色彩增强或绘制辅助参考线，将隐性的思维过程具象化为中间态的“视觉草稿”。\n\n课题将重点攻克多步视觉逻辑推演中的一致性难题，聚焦于模型在处理几何推理解析、物理规律判断等高难度任务时的思维留痕与自我修正，解决传统 VQA 在复杂场景下因缺乏中间步骤导致的判断失真，通过在教育辅助、精密设计评估等场景中的实战演进，实现从“视觉感知”向“主动视觉思考”的跨越，打造具备深度逻辑解释力的多模态认知中枢。\n\n课题要求\n1、计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握大模型、多模态相关的基本算法及应用，熟悉caffe、tensorflow，pytorch等至少一个深度学习框架；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。\n\nCSIG\n云与智慧产业事业群\n\n元宝\n元宝是腾讯官方推出的AI助手，以腾讯混元大模型为底座。作为你聪明靠谱、值得信赖的AI伙伴，元宝能一站式解决日常生活与学习需求，帮你打理生活细节、丰富社交娱乐。腾讯生态也全面拥抱元宝，一方面，公众号、视频号的优质内容构成了元宝的底层数据优势；另一方面，元宝的AI能力已全面接入QQ音乐、微信公众号及视频号评论区等数十款腾讯核心应用，覆盖社交、生活服务、内容消费等关键场景，为你提供无处不在的智能陪伴。加入元宝，一起探索AI的无限可能！","jdComplete":false,"sourceStatus":null}];
